insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9b0f257f-da17-52fe-80d7-d7333e40537a', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'csit-601/foundations-of-research/q01', 'mcq', 'understand', 'easy', 'Distinguish research methodology from research methods', 'Which statement best describes research methodology?', null, null, '[{"id":"a","text":"The specific tools, such as questionnaires and interviews, used to collect data"},{"id":"b","text":"The reasoned justification linking philosophy, questions and design choices"},{"id":"c","text":"The statistical software used to analyse survey data"},{"id":"d","text":"The list of references cited in the literature review"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
