insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9b0f257f-da17-52fe-80d7-d7333e40537a', '{"option":"b"}'::jsonb, 'Methodology is the overall strategy and justification explaining why a study is designed as it is. Questionnaires and interviews are methods (techniques), software is a tool used within methods, and a reference list is part of academic presentation, not methodology.', null)
