insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a2e99cb0-1d36-5c1c-b79c-5dea3c470e21', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'csit-601/foundations-of-research/q02', 'true_false', 'recall', 'easy', 'Recognise that research can use secondary data', 'A study can only count as research if it collects new primary data from participants.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
