insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f7217d66-d14b-5def-b336-ac7df8d9f50e', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'csit-601/foundations-of-research/q03', 'scenario', 'apply', 'medium', 'Identify the purpose of a research question', 'Which research purpose best describes this study?', 'A district health directorate in Ghana introduced an electronic patient records system in three
hospitals a year ago. It now asks a researcher to judge whether the system has reduced the time taken
to retrieve patient files and whether it should be extended to other facilities.', null, '[{"id":"a","text":"Exploration"},{"id":"b","text":"Description"},{"id":"c","text":"Evaluation"},{"id":"d","text":"Prediction"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
