insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f7217d66-d14b-5def-b336-ac7df8d9f50e', '{"option":"c"}'::jsonb, 'The directorate wants a judgement about the effectiveness of an existing intervention, which is evaluation. Exploration suits poorly understood phenomena; description would only profile current use; prediction would forecast future outcomes rather than assess the intervention''s effect.', null)
