insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a7369489-9c67-5c70-a4af-2022dfb6e976', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'csit-601/foundations-of-research/q04', 'matching', 'understand', 'medium', 'Match characteristics of good research to their meaning', 'Match each characteristic of good research to its description.', null, null, '{"left":[{"id":"l1","text":"Transparency"},{"id":"l2","text":"Empirical grounding"},{"id":"l3","text":"Contribution"},{"id":"l4","text":"Critical self-awareness"}],"right":[{"id":"r2","text":"Conclusions rest on collected or existing evidence"},{"id":"r3","text":"The study adds to knowledge, theory or practice"},{"id":"r4","text":"Limitations and alternative explanations are acknowledged"},{"id":"r1","text":"Procedures are reported fully enough to be scrutinised or repeated"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a7369489-9c67-5c70-a4af-2022dfb6e976', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'These characteristics jointly distinguish research from opinion. Transparency enables checking, empirical grounding links claims to evidence, contribution justifies the study, and critical self-awareness prevents overclaiming.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4d7af8dc-ff88-5f24-877b-c0e16646af87', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'csit-601/foundations-of-research/q05', 'short_answer', 'recall', 'easy', 'Name the type of research aimed at solving a practical problem', 'What term describes research whose main aim is to solve a practical problem for an organisation or sector?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4d7af8dc-ff88-5f24-877b-c0e16646af87', '{"answers":["applied research","applied"]}'::jsonb, 'Applied research addresses practical problems, while basic research mainly extends theory. Most MSc IT-for-business studies are applied but should still engage with theory so findings can be interpreted beyond one setting.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0386cfcd-e0ee-5f86-974e-caf198c4e732', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'csit-601/foundations-of-research/q06', 'mcq', 'evaluate', 'hard', 'Evaluate whether a proposed study meets the characteristics of research', 'A student plans to survey 600 friends and classmates on social media about cybersecurity habits and generalise the results to all Ghanaian university students. What is the most serious weakness?', null, null, '[{"id":"a","text":"The sample is too large to analyse"},{"id":"b","text":"The sample is not representative, so the generalisation lacks rigour"},{"id":"c","text":"Social media cannot be used for any research purpose"},{"id":"d","text":"Cybersecurity is not a researchable topic"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0386cfcd-e0ee-5f86-974e-caf198c4e732', '{"option":"b"}'::jsonb, 'Size does not compensate for bias. A convenience sample of friends cannot support generalisation to a national population, so the conclusion lacks rigour. A large sample is analysable, social media can be a legitimate recruitment channel with appropriate design, and cybersecurity is clearly researchable.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3b176b08-806b-50a3-af05-19ced78af0a3', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'csit-601/foundations-of-research/q07', 'true_false', 'understand', 'medium', 'Understand the role of replicability', 'The reproducibility project published by the Open Science Collaboration in 2015 showed that publication in a journal guarantees that a finding is robust.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3b176b08-806b-50a3-af05-19ced78af0a3', '{"value":false}'::jsonb, 'The project found that many published psychology findings replicated with weaker effects or not at all, demonstrating that publication does not guarantee robustness and highlighting the importance of transparency and replication.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('572e552f-72b6-5a0b-a346-ecea1233c95f', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'csit-601/foundations-of-research/q08', 'mcq', 'understand', 'easy', 'Identify the core assumption of interpretivism', 'Which assumption is most characteristic of interpretivism?', null, null, '[{"id":"a","text":"Social reality is objective and best studied through large-sample measurement"},{"id":"b","text":"Social reality is constructed through meanings, so research must understand participants'' perspectives"},{"id":"c","text":"Only research that produces immediate practical solutions is valid"},{"id":"d","text":"Reality cannot be studied at all"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('572e552f-72b6-5a0b-a346-ecea1233c95f', '{"option":"b"}'::jsonb, 'Interpretivism holds that people attach meanings to their actions and that these meanings must be understood. The first option describes positivism, the third caricatures pragmatism, and the fourth is an extreme scepticism that no mainstream paradigm adopts.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b3333b91-4b39-5145-989c-3203873acdd3', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'csit-601/foundations-of-research/q09', 'scenario', 'apply', 'medium', 'Select a paradigm that fits a research question', 'Which paradigm best fits this research question?', 'A researcher wants to understand how women traders in a Kumasi market make sense of accepting mobile
money from customers, including concerns about privacy, family obligations and trust in agents.', null, '[{"id":"a","text":"Positivism, because mobile money transactions can be counted"},{"id":"b","text":"Interpretivism, because the question concerns meanings and lived experience"},{"id":"c","text":"Pragmatism, because all studies should use mixed methods"},{"id":"d","text":"Positivism, because women traders form a clear population"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b3333b91-4b39-5145-989c-3203873acdd3', '{"option":"b"}'::jsonb, 'The phrase "make sense of" signals a focus on meanings and experience, which interpretivism addresses. Countable transactions or a definable population do not make a meaning-focused question positivist, and pragmatism does not require mixed methods for every study.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('293713b2-e0e2-56aa-a9c8-e2cddd0251d8', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'csit-601/foundations-of-research/q10', 'matching', 'understand', 'medium', 'Associate paradigms with typical features', 'Match each paradigm to its typical feature.', null, null, '{"left":[{"id":"l1","text":"Positivism"},{"id":"l2","text":"Interpretivism"},{"id":"l3","text":"Pragmatism"},{"id":"l4","text":"Critical realism"}],"right":[{"id":"r1","text":"Deductive testing of hypotheses using structured data"},{"id":"r4","text":"Seeking underlying mechanisms that generate observable events"},{"id":"r3","text":"Choosing methods according to what best answers the research question"},{"id":"r2","text":"Inductive understanding of meanings through rich data"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('293713b2-e0e2-56aa-a9c8-e2cddd0251d8', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each paradigm has a characteristic logic. Remember that these are tendencies, not rigid rules, and the decisive factor is fit with the research question.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2830664e-fcaf-5b52-9206-8e21d40f95b2', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'csit-601/foundations-of-research/q11', 'true_false', 'understand', 'medium', 'Distinguish paradigms from data types', 'Positivism and quantitative research are exactly the same thing.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2830664e-fcaf-5b52-9206-8e21d40f95b2', '{"value":false}'::jsonb, 'Positivism is a set of philosophical assumptions; quantitative research is a type of data and analysis. Positivist studies usually use quantitative data, but the concepts are distinct and qualitative data can be coded and analysed in positivist ways.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('032f0d2c-df2c-503e-99d9-a2ceff499004', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'csit-601/foundations-of-research/q12', 'short_answer', 'recall', 'easy', 'Recall who popularised the term paradigm', 'Which author popularised the term "paradigm" in The Structure of Scientific Revolutions (1962)?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('032f0d2c-df2c-503e-99d9-a2ceff499004', '{"answers":["Kuhn","Thomas Kuhn","Thomas S. Kuhn","T. S. Kuhn"]}'::jsonb, 'Thomas Kuhn described how scientific communities work within shared frameworks that can shift when anomalies accumulate. Social science later adopted the term for competing philosophical traditions.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('124a8982-4c1e-5b00-b872-10f2a8910811', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'csit-601/foundations-of-research/q13', 'mcq', 'evaluate', 'hard', 'Evaluate the justification for pragmatism', 'Which justification for adopting pragmatism would an examiner find strongest?', null, null, '[{"id":"a","text":"I could not decide between positivism and interpretivism, so I chose pragmatism."},{"id":"b","text":"Pragmatism lets me avoid discussing philosophy."},{"id":"c","text":"My question requires interviews to identify merchants'' problems and a survey to estimate how widespread they are, so integrating both answers the question best."},{"id":"d","text":"Pragmatism is the newest paradigm and therefore the most advanced."}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('124a8982-4c1e-5b00-b872-10f2a8910811', '{"option":"c"}'::jsonb, 'A strong justification links the paradigm to the research question and explains how different data will be integrated. Indecision, avoidance of philosophy and novelty are not reasons; they suggest the student has not understood the paradigm.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c0f41347-6316-5829-9aac-9dcef5c486ed', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'csit-601/foundations-of-research/q14', 'mcq', 'analyse', 'medium', 'Analyse lessons from the Hawthorne studies', 'What is the most important methodological lesson from the Hawthorne studies for an IT researcher?', null, null, '[{"id":"a","text":"Lighting levels determine productivity"},{"id":"b","text":"Measuring outcomes may show that something happens, but understanding why may require attention to meanings and social context"},{"id":"c","text":"Interviews are always more accurate than measurements"},{"id":"d","text":"Productivity cannot be researched"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c0f41347-6316-5829-9aac-9dcef5c486ed', '{"option":"b"}'::jsonb, 'The early experiments produced puzzling results that later phases interpreted with attention to social relationships and attitudes. The studies do not show that lighting determines output, that interviews always beat measurement, or that productivity is unresearchable.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('95aea724-d943-5e21-88e8-86fd17eca395', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '3c0e81e1-c292-5cc9-96f8-ff2fe1782c8f', 'csit-601/foundations-of-research/q15', 'mcq', 'recall', 'easy', 'Define epistemology', 'Epistemology is primarily concerned with which question?', null, null, '[{"id":"a","text":"What is the nature of reality?"},{"id":"b","text":"What counts as valid knowledge and how can it be obtained?"},{"id":"c","text":"What role do values play in research?"},{"id":"d","text":"How large should a sample be?"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('95aea724-d943-5e21-88e8-86fd17eca395', '{"option":"b"}'::jsonb, 'Epistemology concerns knowledge and how it is justified. The nature of reality is ontology, the role of values is axiology, and sample size is a technical design decision, not a philosophical branch.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5f5904b8-75a3-566e-a871-7ca8d5b2d238', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '3c0e81e1-c292-5cc9-96f8-ff2fe1782c8f', 'csit-601/foundations-of-research/q16', 'matching', 'understand', 'medium', 'Match philosophical branches to their concerns', 'Match each term to its concern.', null, null, '{"left":[{"id":"l1","text":"Ontology"},{"id":"l2","text":"Epistemology"},{"id":"l3","text":"Axiology"},{"id":"l4","text":"Reflexivity"}],"right":[{"id":"r3","text":"The role of values in research"},{"id":"r4","text":"Critical reflection on the researcher''s own influence"},{"id":"r2","text":"What counts as acceptable knowledge"},{"id":"r1","text":"The nature of reality and what exists"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5f5904b8-75a3-566e-a871-7ca8d5b2d238', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'The three branches answer different questions, and reflexivity is the practical response to axiology in interpretive work. Confusing ontology and epistemology is a common examination error.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2a6b022a-afae-5fcb-a60b-34ae7957f159', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '3c0e81e1-c292-5cc9-96f8-ff2fe1782c8f', 'csit-601/foundations-of-research/q17', 'scenario', 'analyse', 'hard', 'Detect incoherence between philosophy and methods', 'What is the main problem with this proposal?', 'A proposal states: "This study adopts an interpretivist philosophy. A structured questionnaire with
Likert-scale items will be sent to 400 students and hypotheses will be tested using regression."', null, '[{"id":"a","text":"Regression cannot be used with Likert-scale data under any circumstances"},{"id":"b","text":"The stated philosophy contradicts the deductive, structured, statistical design"},{"id":"c","text":"400 students is too few for any study"},{"id":"d","text":"Questionnaires cannot be used in university settings"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2a6b022a-afae-5fcb-a60b-34ae7957f159', '{"option":"b"}'::jsonb, 'Interpretivism seeks in-depth understanding of meanings, while hypothesis testing with structured data is deductive and positivist. The fix is to realign either the philosophy or the methods. The other options are false generalisations about techniques and samples.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('eae82a2c-f9db-5ee4-a33e-bb1b59ef3c41', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '3c0e81e1-c292-5cc9-96f8-ff2fe1782c8f', 'csit-601/foundations-of-research/q18', 'true_false', 'understand', 'medium', 'Understand axiology in quantitative research', 'Axiology is irrelevant to quantitative research because quantitative researchers are value-neutral.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('eae82a2c-f9db-5ee4-a33e-bb1b59ef3c41', '{"value":false}'::jsonb, 'Values influence topic selection, the wording of questionnaire items, the choice of constructs and the interpretation of results. Quantitative researchers aspire to minimise bias but cannot eliminate the influence of values, so axiology remains relevant.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5012cd8c-b9bf-5ced-ade1-9f8361d809c8', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '3c0e81e1-c292-5cc9-96f8-ff2fe1782c8f', 'csit-601/foundations-of-research/q19', 'short_answer', 'recall', 'easy', 'Name the ontological position that social phenomena are created through interaction', 'Which ontological position holds that social phenomena are created and revised through social interaction?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5012cd8c-b9bf-5ced-ade1-9f8361d809c8', '{"answers":["constructionism","constructivism","social constructionism"]}'::jsonb, 'Constructionism contrasts with objectivism, which treats social entities as existing independently of social actors. Some texts use "constructivism" for a closely related position.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('52b8e080-750a-5d10-bb5f-dab3562cd83a', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '3c0e81e1-c292-5cc9-96f8-ff2fe1782c8f', 'csit-601/foundations-of-research/q20', 'mcq', 'apply', 'medium', 'Apply the research onion to choose a coherent approach', 'A researcher adopts an objectivist ontology and positivist epistemology to test whether UTAUT constructs predict nurses'' use of an electronic records system. Which approach to theory development is most coherent?', null, null, '[{"id":"a","text":"Inductive, building theory from interview themes"},{"id":"b","text":"Deductive, testing hypotheses derived from existing theory"},{"id":"c","text":"Abductive, because all health research must be abductive"},{"id":"d","text":"No approach to theory is needed"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('52b8e080-750a-5d10-bb5f-dab3562cd83a', '{"option":"b"}'::jsonb, 'Testing hypotheses derived from an established model such as UTAUT is deductive and coheres with positivism. Induction suits theory-building from data, abduction is not mandatory for health research, and every study involves some relationship to theory.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6b0e38c5-c3dd-59e5-be61-be2de9bb13c4', '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', null, 'csit-601/foundations-of-research/q21', 'essay', 'evaluate', 'hard', 'Justify a coherent philosophical position for a Ghanaian technology adoption study', '"The choice of research paradigm should be determined by the research question rather than by the researcher''s preference for particular methods." Critically discuss this statement with reference to a study of artificial intelligence adoption among Ghanaian SMEs.', null, null, null, 20, array['Introduce paradigms and the claim being evaluated', 'Explain positivism, interpretivism and pragmatism with their ontological and epistemological assumptions', 'Show how different research questions on AI adoption in SMEs imply different paradigms', 'Discuss practical constraints and researcher preferences, and when they legitimately matter', 'Conclude with a reasoned position on the statement']::text[], '[{"criterion":"Understanding of paradigms and philosophical assumptions","marks":6,"descriptor":"Accurate, precise explanation of at least three paradigms with ontology, epistemology and axiology."},{"criterion":"Application to the Ghanaian SME context","marks":6,"descriptor":"Develops contrasting, well-formed research questions and links each to a paradigm and design."},{"criterion":"Critical evaluation","marks":5,"descriptor":"Weighs the claim against counterarguments such as skills, access and supervisor expectations."},{"criterion":"Structure and academic writing","marks":3,"descriptor":"Logical argument, clear conclusion and correct APA 7 citation of credible sources."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6b0e38c5-c3dd-59e5-be61-be2de9bb13c4', '{}'::jsonb, 'Examiners look for accurate philosophical understanding, genuine application to the Ghanaian SME context through contrasting research questions, and a balanced judgement rather than description.', 'A strong answer accepts the statement in principle while recognising its practical limits. It opens by
defining a paradigm as a set of assumptions about reality, knowledge and values (Guba and Lincoln''s
framing via ontology, epistemology and methodology is useful). It then contrasts positivism, which
assumes an objective, measurable reality and suits deductive testing; interpretivism, which assumes
socially constructed meanings and suits inductive understanding; and pragmatism, which judges knowledge
by its usefulness and supports mixed methods.

The core of the answer applies these to AI adoption in Ghanaian SMEs. A question such as "To what extent
do perceived usefulness, cost and skills availability predict AI adoption intention among SMEs in
Accra?" implies measurable constructs and a positivist survey, perhaps using TAM or UTAUT. A question
such as "How do owner-managers of family businesses make sense of AI tools in their decision-making?"
implies interpretivism and interviews. A question asking "What adoption barriers exist and how
widespread are they?" supports pragmatism with sequential qualitative then quantitative phases.

The evaluation should then acknowledge that researcher skills, access to a sampling frame, time and
ethical constraints legitimately influence design, but argue that these should refine, not replace,
question-led reasoning. Choosing a paradigm merely because one prefers statistics risks incoherence and
weak claims. A good conclusion states that the question should lead, with practical constraints
prompting reformulation of the question rather than a mismatch between philosophy and methods.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('7388bf74-4eec-57e7-8aef-45a346f99ecc', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'What three features make an enquiry count as research rather than casual information gathering?', 'It is systematic (planned and logically ordered), grounded in evidence, and transparent enough for others to examine and challenge its procedures and conclusions.', 'supplementary', 'csit-601/foundations-of-research/c2509a82d012', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('87823144-01c2-58ec-aed1-f1b1b86ea041', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'What is the difference between research methods and research methodology?', 'Methods are the techniques for collecting and analysing data; methodology is the justified strategy and philosophy explaining why those techniques suit the question.', 'supplementary', 'csit-601/foundations-of-research/f7c40c596b53', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('cf9ddee2-c0a5-55c1-9529-a8ba652a153d', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'Name the five common purposes of research.', 'Exploration, description, explanation, prediction and evaluation. The wording of the research question usually signals which purpose applies.', 'supplementary', 'csit-601/foundations-of-research/a30ac08e21e9', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e5172099-62d3-534f-8be3-f2e013be444a', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'Why does applied MSc research still need theory?', 'Theory makes findings interpretable and transferable beyond the immediate organisation, and it allows the study to contribute to knowledge rather than only solve a local problem.', 'supplementary', 'csit-601/foundations-of-research/e1071d870986', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ab63d418-fbf1-5778-a42b-de840d1cedeb', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'Why does a large sample not guarantee good research?', 'Rigour depends on the fit between question, design and sampling. A large but biased sample, such as friends on social media, still cannot support generalisation.', 'supplementary', 'csit-601/foundations-of-research/28c706494391', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8d88e6dc-fb80-5a7f-8fef-183b786574b6', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '6ce5e914-8c8d-5c63-975a-6607f50e9890', 'What did the 2015 reproducibility project teach researchers about published findings?', 'Many published results replicated weakly or not at all, showing that publication does not guarantee robustness and that transparency and replication matter.', 'supplementary', 'csit-601/foundations-of-research/a81fea10df8b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ecd7b893-8a64-5782-8e2b-35c52ea6b7f3', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'What is a research paradigm?', 'A shared framework of assumptions about reality, knowledge and appropriate methods that guides how a research community frames and studies problems.', 'supplementary', 'csit-601/foundations-of-research/456b06f29a62', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ac589e60-6f2b-5d72-a80c-aef57c100786', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'How does positivism view the researcher''s role?', 'As detached and value-neutral, measuring an objective reality with structured instruments and testing hypotheses deductively.', 'supplementary', 'csit-601/foundations-of-research/82816fdeaabf', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5d709f04-6f2a-51a8-855a-01c7c1ee7152', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'Why is "make sense of" in a research question a clue to interpretivism?', 'It signals interest in participants'' meanings and lived experience, which interpretivism studies through rich data such as interviews and observation.', 'supplementary', 'csit-601/foundations-of-research/697393e90255', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bfab5b7f-517a-547a-b1ae-bc5056e48c63', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'What is the weakest justification for choosing pragmatism?', 'Indecision or a wish to avoid philosophy. A sound justification shows how combining approaches answers the question and how findings will be integrated.', 'supplementary', 'csit-601/foundations-of-research/c4ab0ef36611', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('42745e79-3086-5d54-91fa-fbabe4450813', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '52005686-2b87-568d-9a4a-0139af122239', 'What does critical realism add to the positivism versus interpretivism debate?', 'It accepts an independent reality but argues our knowledge is fallible and focuses on the underlying mechanisms that produce observable outcomes in context.', 'supplementary', 'csit-601/foundations-of-research/649229fd4cc6', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2883e101-0a8f-512d-9bbc-8e1ba30f2217', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '3c0e81e1-c292-5cc9-96f8-ff2fe1782c8f', 'Distinguish ontology from epistemology in one sentence each.', 'Ontology asks what reality is and what exists; epistemology asks what counts as valid knowledge about it and how that knowledge can be obtained.', 'supplementary', 'csit-601/foundations-of-research/3f862e54efa4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('22ae5357-bfe5-5a82-a308-59566762783d', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '3c0e81e1-c292-5cc9-96f8-ff2fe1782c8f', 'Contrast objectivism and constructionism using "trust in mobile money".', 'Objectivism treats trust as a stable, measurable attribute; constructionism treats it as continually formed through experiences, conversations and relationships.', 'supplementary', 'csit-601/foundations-of-research/e491c13c030f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6b09d568-1da6-52e8-8fc0-3c11f5183053', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '3c0e81e1-c292-5cc9-96f8-ff2fe1782c8f', 'What is axiology and why does it matter in quantitative studies too?', 'Axiology concerns the role of values. Values shape topic choice, item wording and interpretation even in quantitative research.', 'supplementary', 'csit-601/foundations-of-research/ece2b5d20996', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('41d3b967-028d-53b9-8881-1541882ccf1d', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '3c0e81e1-c292-5cc9-96f8-ff2fe1782c8f', 'What does the research onion help a researcher check?', 'That philosophy, approach to theory, methodological choice, strategy, time horizon and techniques follow logically from one another, so the design is coherent.', 'supplementary', 'csit-601/foundations-of-research/c4f57b8ed42a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0e7553be-6110-50d2-8fc1-502cfbf18f7e', null, '2c1df771-f299-58d8-95a4-e55602e24536', '21e524c9-605c-57a0-baf7-a6d11c624409', '3c0e81e1-c292-5cc9-96f8-ff2fe1782c8f', 'Which approach to theory development fits testing hypotheses from UTAUT?', 'Deduction, which derives hypotheses from existing theory and tests them, consistent with a positivist epistemology.', 'supplementary', 'csit-601/foundations-of-research/f22e85046760', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
