insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('02331d2b-8813-5c71-8cae-fc89ade7fe9d', '2c1df771-f299-58d8-95a4-e55602e24536', 'research-problem-development', 'Research Problem Development', 'Turning a topic of interest into a focused, researchable problem with clear aims.', 2, true)
