insert into public.question_keys (question_id, correct, explanation, model_answer) values ('09badc08-1353-550b-9e03-01b511d280d5', '{"option":"c"}'::jsonb, 'A good objective is specific and measurable and uses an action verb such as assess. "Understand" and "know" are vague, and distributing questionnaires is a method rather than an objective.', null)
