insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f98e493c-0fc0-5bbd-ac6b-e8d0ecf3f632', '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', 'b7be0b74-4634-57e6-ad74-3f65cde228bc', 'csit-601/research-problem-development/q19', 'scenario', 'evaluate', 'hard', 'Evaluate the alignment of a research design', 'What is the most serious problem?', 'A proposal''s aim is to examine factors influencing e-commerce adoption among small businesses. Its
