insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('50cd7d84-c2bc-5997-a941-64681de275f4', '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', 'b7be0b74-4634-57e6-ad74-3f65cde228bc', 'csit-601/research-problem-development/q21', 'mcq', 'analyse', 'hard', 'Derive hypotheses from UTAUT', 'According to UTAUT (Venkatesh et al., 2003), which hypothesis is most directly grounded in the model?', null, null, '[{"id":"a","text":"Facilitating conditions positively influence use behaviour"},{"id":"b","text":"Website colour positively influences behavioural intention"},{"id":"c","text":"Perceived enjoyment is the main predictor of use in all contexts"},{"id":"d","text":"Behavioural intention has no role in technology use"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('50cd7d84-c2bc-5997-a941-64681de275f4', '{"option":"a"}'::jsonb, 'UTAUT proposes that facilitating conditions influence use behaviour, alongside performance expectancy, effort expectancy and social influence shaping intention. Website colour and perceived enjoyment are not core UTAUT constructs, and intention is central to the model.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d12f4ca6-2bc7-5eb8-a583-cb46a38c185b', '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', null, 'csit-601/research-problem-development/q22', 'case_analysis', 'evaluate', 'hard', 'Develop an aligned problem statement, objectives and hypotheses for a Ghanaian study', 'Critically evaluate the draft proposal in the case and produce an improved problem statement, aim, objectives, research questions and hypotheses, together with a statement of scope, delimitations and limitations.', null, 'Illustrative scenario. Yaw, an MSc IT for Business student, works for a fintech start-up in Accra. His
draft proposal states: "Digital payments are very important. Many retailers in Ghana do not use them.
This study will prove that retailers are afraid of technology. Objectives: (1) to understand digital
payments; (2) to give questionnaires to retailers; (3) to recommend solutions. Hypothesis: Website
design affects customer loyalty. The study will cover all retailers in Ghana. Limitation: lack of time."
Yaw has permission to recruit retailers who are registered with a traders'' association in two Accra
markets and intends to use UTAUT.', null, 25, array['Diagnose weaknesses in the problem statement, objectives, hypothesis and scope', 'Rewrite the problem statement using ideal state, reality, consequences, gap and purpose', 'Formulate an aim, three SMART objectives and matching research questions', 'Derive two or three hypotheses from UTAUT', 'State scope, justified delimitations and limitations with mitigations', 'Present a brief consistency matrix']::text[], '[{"criterion":"Diagnosis of weaknesses","marks":5,"descriptor":"Identifies vagueness, presumed conclusion, method-as-objective, misaligned hypothesis and infeasible scope."},{"criterion":"Revised problem statement","marks":5,"descriptor":"Specific, neutral, evidence-aware statement containing all five components."},{"criterion":"Aim, objectives and questions","marks":6,"descriptor":"One aim, SMART objectives with measurable verbs and matching questions."},{"criterion":"Hypotheses grounded in theory","marks":4,"descriptor":"Testable hypotheses derived correctly from UTAUT constructs."},{"criterion":"Scope, delimitations and limitations","marks":5,"descriptor":"Clearly separated, justified boundaries and limitations with effects and mitigations."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d12f4ca6-2bc7-5eb8-a583-cb46a38c185b', '{}'::jsonb, 'Examiners reward accurate diagnosis, a neutral and specific problem statement, alignment between all elements, hypotheses genuinely derived from UTAUT, and careful separation of scope, delimitations and limitations, including the insider-researcher issue.', 'A strong answer first diagnoses the draft. The problem statement is vague and unsupported ("very
important", "many retailers"), and it presumes its conclusion ("will prove that retailers are afraid").
Objective 1 uses an unmeasurable verb, objective 2 is a method, and objective 3 is an outcome rather
than a research step. The hypothesis concerns customer loyalty and website design, which are unrelated
to retailer adoption. Covering "all retailers in Ghana" is infeasible, and "lack of time" is not
explained in terms of its effect on findings.

The revised problem statement might read: digital payment platforms are expected to make transactions
faster and safer for merchants; however, available evidence suggests that many market retailers still
rely mainly on cash (to be supported with verified sources); this may limit traders'' access to digital
records and financial services; existing research focuses more on consumers than on merchants in
Ghanaian markets; this study therefore examines factors influencing retailers'' intention to accept
digital payments in two Accra markets.

Aim: to examine factors influencing retailers'' intention to accept digital payments in selected Accra
markets. Objectives: to assess the influence of performance expectancy on intention; to assess the
influence of effort expectancy on intention; to examine the influence of facilitating conditions on
actual acceptance. Each objective has a matching question. Hypotheses: H1 performance expectancy
positively influences intention; H2 effort expectancy positively influences intention; H3 facilitating
conditions positively influence acceptance behaviour.

Scope: UTAUT constructs, registered retailers in two Accra markets, one data collection period.
Delimitations: registered retailers only, because a sampling frame is available through the
association. Limitations: results may not generalise to informal traders; self-reported data may be
affected by social desirability (mitigated by anonymity); Yaw''s employment in fintech creates potential
bias (mitigated by declaring the interest and making participation voluntary). A short consistency
matrix confirms alignment.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e8479cbb-544f-53f1-a6ae-64c3d9ee78d5', null, '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', '83ae55e3-c87c-56e6-9c9e-531456402447', 'How does a research problem differ from a research topic?', 'A topic is a broad area of interest; a problem specifies a gap between an expected and an actual state, with consequences that justify investigation.', 'supplementary', 'csit-601/research-problem-development/696af4510252', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3ab9d8ca-40e5-5f34-a4cc-9b1ff3616d98', null, '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', '83ae55e3-c87c-56e6-9c9e-531456402447', 'What three elements make up a well-formed research problem?', 'The expected or desired state, the actual state supported by evidence, and the consequence of the gap for people, organisations or theory.', 'supplementary', 'csit-601/research-problem-development/30e52808071f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('403c24ee-39d9-5177-b452-f210a9ff227d', null, '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', '83ae55e3-c87c-56e6-9c9e-531456402447', 'Contrast gap-spotting with problematisation.', 'Gap-spotting finds neglected or incomplete areas in the literature; problematisation challenges the assumptions on which existing research rests, often producing more original questions.', 'supplementary', 'csit-601/research-problem-development/c1610d33cef1', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1bd237b6-070c-51fd-acdf-685662b97df5', null, '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', '83ae55e3-c87c-56e6-9c9e-531456402447', 'What are the stages of a funnel-structured background?', 'Broad context, national context, specific setting, evidence of the issue, what is known and unknown, then a transition into the problem.', 'supplementary', 'csit-601/research-problem-development/6a167d901e8b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('755b7951-7097-5dcb-918c-e5ff5eb10b6e', null, '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', '83ae55e3-c87c-56e6-9c9e-531456402447', 'Why is "not yet studied in Ghana" an incomplete justification?', 'The researcher must also explain why the context could produce different results or why the knowledge is needed for theory, practice or policy.', 'supplementary', 'csit-601/research-problem-development/7cc64cf3cb31', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f973560e-be21-5ece-8188-0c9415baf3d7', null, '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', '83ae55e3-c87c-56e6-9c9e-531456402447', 'What does the adapted FINER checklist test?', 'Whether a candidate problem is feasible, interesting, novel, ethical, relevant and researchable within MSc time and resources.', 'supplementary', 'csit-601/research-problem-development/d17a3386622d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c07c9c58-94b5-5345-b97a-b9cfe790f637', null, '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', '62505ff9-1fa4-5d00-9830-b24dbe684c11', 'What five components should a problem statement contain?', 'The ideal or expected state, current reality with evidence, consequences, the knowledge gap, and the purpose of the study.', 'supplementary', 'csit-601/research-problem-development/30fb35d29ce9', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4371d8c6-1e0f-56b5-8fdf-4a25b8ae1c49', null, '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', '62505ff9-1fa4-5d00-9830-b24dbe684c11', 'Why must a problem statement be neutral?', 'Presuming the answer ("this study will prove…") signals bias. A neutral statement specifies what will be examined, not what will be found.', 'supplementary', 'csit-601/research-problem-development/abae83c6d495', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('21755c25-1c4a-5a98-ac4f-963f685556f0', null, '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', '62505ff9-1fa4-5d00-9830-b24dbe684c11', 'What is the difference between a delimitation and a limitation?', 'A delimitation is a boundary the researcher deliberately chooses and justifies; a limitation is a constraint, often outside the researcher''s control, that may affect findings.', 'supplementary', 'csit-601/research-problem-development/5ecc588932eb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('96e2df1d-d423-573f-bd04-08875ba84d8d', null, '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', '62505ff9-1fa4-5d00-9830-b24dbe684c11', 'What four dimensions usually define a study''s scope?', 'Content (variables or themes), geography, population or unit of analysis, and time period.', 'supplementary', 'csit-601/research-problem-development/bffe99b9bf98', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
