  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a98ed594-98ce-5c72-97d6-98dfcc2404d1', null, '2c1df771-f299-58d8-95a4-e55602e24536', '02331d2b-8813-5c71-8cae-fc89ade7fe9d', '62505ff9-1fa4-5d00-9830-b24dbe684c11', 'What should you do if reliable statistics are unavailable for your problem statement?', 'Use a careful qualitative statement supported by credible sources rather than inventing or repeating unverified figures.', 'supplementary', 'csit-601/research-problem-development/b216f82a84c2', true)
