insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('7e0d035c-2942-5869-b7bd-abc9eecba411', '2c1df771-f299-58d8-95a4-e55602e24536', 'literature-review', 'Literature Review', 'Finding, evaluating and synthesising scholarship, and building theoretical and conceptual frameworks.', 3, true)
  on conflict (id) do update set course_id = excluded.course_id, slug = excluded.slug, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.lessons (id, module_id, slug, title, summary, topics, estimated_minutes, difficulty, source, content, word_count, sort_order, is_published) values ('de883484-7983-505a-b991-69220db279f6', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'purpose-and-searching', 'The Purpose of a Literature Review and Searching for Literature', 'Explain what a literature review is for and plan and execute a systematic, documented search of academic databases using keywords, Boolean logic and citation chaining.', array['Purpose of literature reviews', 'Finding scholarly literature', 'Academic databases', 'Search strategies']::text[], 45, 'intermediate', 'supplementary', '{"introduction":"The literature review is often the longest chapter of an MSc proposal and one of the hardest to write well. Many students treat it as a collection of summaries: \"Mensah (2019) found…, Smith (2020) found…, Boateng (2021) found…\". Examiners describe such reviews as \"annotated bibliographies\" and mark them down, because they show reading but not thinking. A good literature review is an argument. It establishes what is known, evaluates the strength of that knowledge, identifies what is missing or contested, and positions your study as a sensible next step.\n\nNone of that is possible without first finding the right literature. This lesson therefore covers two connected skills: understanding the **purposes** of a literature review, and **searching** for scholarly literature systematically using academic databases, search engines and repositories. Later lessons in this module address evaluating sources, synthesising them and building frameworks.","objectives":["Explain the main purposes of a literature review in postgraduate research.","Distinguish narrative, systematic, scoping and integrative reviews.","Identify appropriate academic databases and search tools for IT-for-business research.","Apply keyword development, Boolean operators, truncation and filters to construct effective search strings.","Create a documented, reproducible search log and use citation chaining to extend a search."],"prerequisites":["A defined research problem and draft objectives (Module 2).","Basic familiarity with web search engines."],"keyTerms":[{"term":"Literature review","definition":"A critical, organised account of existing scholarship on a topic that establishes what is known, evaluates it and identifies gaps relevant to a research question."},{"term":"Scholarly literature","definition":"Work written by researchers for researchers, typically peer-reviewed journal articles, academic books, conference papers and theses."},{"term":"Grey literature","definition":"Material produced outside traditional academic publishing, such as government reports, working papers and industry white papers."},{"term":"Boolean operators","definition":"The search terms AND, OR and NOT used to combine or exclude keywords."},{"term":"Truncation","definition":"Using a symbol, commonly an asterisk, to search for variations of a word stem (for example, `adopt*` for adopt, adoption, adopting)."},{"term":"Citation chaining","definition":"Finding further sources by following the references of a key article (backward) and works that later cite it (forward)."},{"term":"Systematic review","definition":"A review that follows an explicit, pre-specified and reproducible protocol for searching, selecting and appraising studies."},{"term":"Search log","definition":"A record of databases searched, search strings, dates, filters and results, allowing the search to be reported and repeated."}],"body":[{"heading":"Detailed Explanation","markdown":"### Why we review literature\n\nA literature review serves several purposes simultaneously.\n\n1. **Establishing the state of knowledge.** It shows what has been discovered about your topic, which concepts and theories are used, and how researchers have studied it.\n2. **Justifying the study.** By identifying gaps, contradictions or untested assumptions, it explains why your research is needed. This links directly to the problem statement.\n3. **Providing a theoretical foundation.** It identifies the theories and models (such as TAM, UTAUT or Diffusion of Innovations) that will frame your study and from which hypotheses or sensitising concepts are drawn.\n4. **Informing methodology.** It reveals which designs, samples, instruments and analysis techniques others have used successfully, and which limitations they reported. Validated questionnaire scales are usually found this way.\n5. **Avoiding duplication and supporting interpretation.** It prevents repeating settled research and later allows you to compare your findings with previous studies in the discussion chapter.\n6. **Demonstrating scholarship.** It shows examiners that you understand the field and can evaluate it critically.\n\nWebster and Watson (2002), writing in *MIS Quarterly*, argued that a strong review in information systems should be **concept-centric** rather than author-centric: organised around ideas and relationships, not around a list of who said what. This principle underlies the synthesis techniques discussed later in the module.\n\n### Types of literature review\n\n- **Narrative or traditional review.** A broad, expert-led overview. Flexible, but potentially selective and difficult to reproduce. Most MSc dissertations use a narrative review made more rigorous by systematic searching.\n- **Systematic review.** Uses an explicit protocol, defined inclusion and exclusion criteria, comprehensive searching and formal quality appraisal. Common in health research and increasingly used in management (Tranfield, Denyer & Smart, 2003).\n- **Scoping review.** Maps the extent and nature of research on a broad topic, often to identify gaps, without necessarily appraising quality in depth.\n- **Integrative review.** Combines different types of studies, including qualitative and quantitative, to generate new frameworks or perspectives (Snyder, 2019, provides an overview of these types for business research).\n\n### Where to search\n\nNo single source covers everything, so researchers combine several.\n\n- **Academic search engines** such as Google Scholar index a very wide range of scholarly material and are useful for initial exploration and forward citation chaining (\"Cited by\"). Their coverage and ranking are not fully transparent, so they should be supplemented.\n- **Bibliographic databases** such as Scopus and Web of Science index journals selectively and provide advanced search and citation tools; access usually depends on institutional subscriptions.\n- **Publisher and subject platforms** such as the AIS eLibrary (Association for Information Systems), IEEE Xplore, the ACM Digital Library, ScienceDirect, Emerald Insight and JSTOR host full texts in IS, computing and management.\n- **Open access sources** such as the Directory of Open Access Journals (DOAJ) and CORE aggregate openly available research papers.\n- **Grey literature** from government ministries, central banks, regulators and international organisations is often essential for context in Ghana, but must be evaluated carefully.\n- **University library portals** provide authenticated access to subscribed databases; check your institution''s library for what is available to you."},{"heading":"Theories, Frameworks and Models","markdown":"### Building a search strategy: the concept table\n\nThe most reliable way to construct searches is to break the research question into **concepts**, then list synonyms for each.\n\n| Concept | Synonyms and variants | Combined with |\n|---|---|---|\n| Technology | \"mobile money\" OR \"digital payment*\" OR \"mobile payment*\" OR \"e-payment*\" | AND |\n| Behaviour | adopt* OR accept* OR \"intention to use\" OR usage | AND |\n| Population | merchant* OR retailer* OR trader* OR \"small business*\" OR SME* | AND |\n| Context | Ghana OR \"West Africa\" OR \"sub-Saharan Africa\" OR \"developing countr*\" | (optional) |\n\nSynonyms within a concept are joined with **OR** (broadening), and concepts are joined with **AND** (narrowing). **NOT** excludes terms but should be used sparingly because it can remove relevant studies. Quotation marks search exact phrases; truncation captures variations. Database syntax varies, so consult each platform''s help pages.\n\n### A reproducible search process\n\nPRISMA 2020 (Page et al., 2021) is a widely used reporting guideline for systematic reviews. Its flow diagram records how many records were identified, screened, excluded and included. Even in a narrative MSc review, borrowing this logic, documenting where you searched, what you found and why you included or excluded studies, greatly increases transparency."},{"heading":"Diagram","markdown":"```mermaid\nflowchart TD\n    A[\"Research question\"] --> B[\"Identify concepts\"]\n    B --> C[\"List synonyms and variants\"]\n    C --> D[\"Build Boolean search strings\"]\n    D --> E[\"Search databases and search engines\"]\n    E --> F[\"Screen titles and abstracts\"]\n    F --> G[\"Read full texts against inclusion criteria\"]\n    G --> H[\"Backward and forward citation chaining\"]\n    H --> I[\"Record everything in a search log\"]\n    I --> J[\"Store references in a reference manager\"]\n    F -.->|\"Too many or too few results\"| D\n```"},{"heading":"Step-by-Step Guide","markdown":"1. **Define the question and scope.** Write the research question and the inclusion criteria: date range, languages, study types, populations.\n2. **Identify concepts.** Typically two to four concepts, for example technology, behaviour and population.\n3. **Generate keywords.** Use the vocabulary of key articles, database subject terms and thesauri; include British and American spellings (behaviour, behavior; organisation, organization).\n4. **Construct and test search strings.** Run a draft search, examine results and refine. If results run into tens of thousands, add a concept or phrase; if very few, add synonyms or remove the context concept.\n5. **Search several sources.** Combine Google Scholar with at least one subscription or subject database and an open access source.\n6. **Screen systematically.** Review titles and abstracts first, then full texts, applying your criteria consistently.\n7. **Chain citations.** Use reference lists of the most relevant papers (backward) and \"cited by\" features (forward) to find further work.\n8. **Record and manage.** Keep a search log and save references in a reference manager such as Zotero, which can generate APA 7 citations."},{"heading":"Worked Example","markdown":"**Illustrative scenario.** Akosua''s research question is: *What factors influence the adoption of AI-based tools by SMEs in Ghana?*\n\n- **Concepts:** artificial intelligence; adoption; SMEs; Ghana or similar contexts.\n- **Draft string:** `(\"artificial intelligence\" OR AI OR \"machine learning\" OR chatbot*) AND (adopt* OR \"intention to use\" OR acceptance) AND (SME* OR \"small and medium\" OR \"small business*\")`\n- **First result:** very large numbers of records, many about AI in large enterprises.\n- **Refinement:** add the context concept `AND (Ghana OR Africa OR \"developing countr*\" OR \"emerging econom*\")`, restrict to the last ten years and to peer-reviewed articles.\n- **Problem:** very few Ghana-specific studies. **Solution:** keep the international SME literature for theory and measurement, use African and developing-economy studies for contextual comparison, and note the scarcity of Ghana-specific work as part of the gap.\n- **Chaining:** a highly relevant review article leads, through its reference list, to studies using the Technology-Organisation-Environment framework, which Akosua had not searched for, so she adds \"TOE\" as a keyword.\n- **Log entry:** database, date, exact string, filters, number of results and number retained.\n\nThe expected learning is that searching is iterative and that the log turns a messy process into a transparent, reportable one."},{"heading":"Ghanaian Business Application","markdown":"Searching for literature on Ghanaian technology and business topics presents specific challenges. Research on Ghana is spread across international journals, African journals, conference proceedings and theses, and some relevant local journals may not be indexed in major subscription databases. Students should therefore combine international databases with open access aggregators and Google Scholar, and search for research from Ghanaian universities and institutions.\n\nGrey literature is particularly important for context. Reports from the Bank of Ghana, the Ghana Statistical Service, the National Communications Authority, the Cyber Security Authority and relevant ministries can supply official context for topics such as mobile money, internet access or cybersecurity, but students must cite the exact report, quote figures accurately and note the date. Industry white papers from technology vendors or telecom operators should be treated with caution because of commercial interests. When researching technology adoption in healthcare, students may also find relevant studies in public health and medical informatics databases, not just business databases, which is a reminder that interdisciplinary topics require interdisciplinary searching."},{"heading":"International Case Study","markdown":"### The Cochrane Collaboration and systematic searching\n\nThe Cochrane Collaboration, now known simply as Cochrane, was founded in 1993 to produce systematic reviews of healthcare interventions. Its reviews are built on transparent, comprehensive searching across multiple databases, explicit inclusion criteria and documented screening by more than one reviewer, so that readers can see how conclusions were reached and other researchers can update them as new evidence appears.\n\nCochrane''s approach, together with reporting guidelines such as PRISMA, influenced how other disciplines think about evidence. Management researchers such as Tranfield, Denyer and Smart (2003) adapted systematic review principles for management research, recognising that business questions are often less clearly defined than clinical ones. For an MSc student in IT for Business, the case shows that a literature search is not merely a preliminary chore; it is a research process in its own right whose quality affects the credibility of everything built on it. Even a narrative review benefits from Cochrane-style transparency: say where you searched, how and why you selected what you did."}],"misconceptions":["**Misconception:** A literature review summarises everything written on a topic. **Correction:** It selectively and critically reviews literature relevant to your research question and builds an argument.","**Misconception:** Google Scholar alone is sufficient. **Correction:** It is useful but its coverage and ranking are not transparent; combine it with subject databases and open access sources.","**Misconception:** More search results mean a better search. **Correction:** Precision matters; thousands of irrelevant hits waste time and hide key studies.","**Misconception:** Only literature from Ghana is relevant to a Ghanaian study. **Correction:** International literature provides theory, methods and comparison; context-specific studies show how findings may differ.","**Misconception:** The search is finished before writing begins. **Correction:** Searching continues iteratively as understanding develops."],"examMistakes":["Describing a literature review as \"a summary of what other authors said\" without mentioning critical evaluation or gaps.","Being unable to explain how literature was searched or selected.","Relying heavily on websites, blogs and news articles instead of scholarly sources.","Confusing systematic reviews with any review that is \"well organised\".","Listing databases without explaining how search strategies were constructed."],"criticalQuestions":["Should MSc students in IT for Business conduct full systematic reviews, or is a systematically searched narrative review more appropriate? Justify your view.","What risks arise when algorithmic ranking in academic search engines shapes which studies researchers read?","How should researchers balance international and local literature when the local evidence base is small?","Is grey literature from technology vendors ever appropriate in an academic literature review? Under what conditions?"],"exercises":["**Concept table.** For the question \"What factors influence cybersecurity behaviour among university students in Ghana?\", build a concept table with at least three concepts and four synonyms each. *Expected output:* a completed table and one Boolean search string combining the concepts.","**Run and refine.** Run your string in Google Scholar and one other source available to you (for example DOAJ or CORE). Refine it at least twice. *Expected output:* a search log with date, source, string, filters, number of results and a note explaining each refinement.","**Citation chaining.** Choose one highly relevant article and perform backward and forward chaining. *Expected output:* a list of at least five additional relevant sources, each labelled as backward or forward, with a one-line relevance note."],"takeaways":["A literature review establishes knowledge, justifies the study, provides theory, informs methods and supports interpretation.","Reviews can be narrative, systematic, scoping or integrative; MSc work usually uses systematic searching within a narrative review.","Break questions into concepts, use synonyms with OR, combine concepts with AND, and use truncation and phrases.","Search several sources, including subject databases, open access aggregators and credible grey literature.","Keep a search log and use citation chaining and a reference manager."],"furtherReading":[{"text":"Webster, J., & Watson, R. T. (2002). Analyzing the past to prepare for the future: Writing a literature review. *MIS Quarterly, 26*(2), xiii-xxiii.","url":null,"verification":"citation"},{"text":"Snyder, H. (2019). Literature review as a research methodology: An overview and guidelines. *Journal of Business Research, 104*, 333-339.","url":"https://doi.org/10.1016/j.jbusres.2019.07.039","verification":"verified"},{"text":"Tranfield, D., Denyer, D., & Smart, P. (2003). Towards a methodology for developing evidence-informed management knowledge by means of systematic review. *British Journal of Management, 14*(3), 207-222.","url":null,"verification":"citation"},{"text":"Page, M. J., McKenzie, J. E., Bossuyt, P. M., Boutron, I., Hoffmann, T. C., Mulrow, C. D., Shamseer, L., Tetzlaff, J. M., Akl, E. A., Brennan, S. E., Chou, R., Glanville, J., Grimshaw, J. M., Hróbjartsson, A., Lalu, M. M., Li, T., Loder, E. W., Mayo-Wilson, E., McDonald, S., … Moher, D. (2021). The PRISMA 2020 statement: An updated guideline for reporting systematic reviews. *BMJ, 372*, n71.","url":"https://doi.org/10.1136/bmj.n71","verification":"unverified"},{"text":"Hart, C. (1998). *Doing a literature review: Releasing the social science research imagination*. SAGE.","url":null,"verification":"citation"}],"videos":[{"title":"Google Scholar Search Help","url":"https://scholar.google.com/intl/en/scholar/help.html","description":"Google. Official help page explaining search operators, \"Cited by\" and library links.","verification":"verified"},{"title":"Purdue Online Writing Lab","url":"https://owl.purdue.edu/","description":"Purdue University. Official writing resource with guidance on conducting research and writing literature reviews.","verification":"verified"}],"revisionSummary":"A literature review is a critical, organised argument about existing knowledge that justifies the study, supplies theory, informs methods and supports interpretation; it should be concept-centric rather than a list of summaries. Effective searching breaks the question into concepts, uses synonyms with OR and concepts with AND, applies truncation and phrases, searches several sources and documents everything in a search log.\n\n- Purposes: state of knowledge, justification, theory, methods, interpretation, scholarship.\n- Types: narrative, systematic, scoping, integrative.\n- Sources: Google Scholar, subject databases, DOAJ and CORE, credible grey literature.\n- Boolean logic, truncation, phrase searching, filters.\n- Citation chaining and a reproducible search log."}'::jsonb, 2556, 1, true)
  on conflict (id) do update set module_id = excluded.module_id, slug = excluded.slug, title = excluded.title, summary = excluded.summary, topics = excluded.topics, estimated_minutes = excluded.estimated_minutes, difficulty = excluded.difficulty, source = excluded.source, content = excluded.content, word_count = excluded.word_count, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.lessons (id, module_id, slug, title, summary, topics, estimated_minutes, difficulty, source, content, word_count, sort_order, is_published) values ('c7696ab0-8d8f-5df7-b77e-a6875fd5f6fd', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'evaluating-sources-and-gaps', 'Evaluating Sources and Identifying Research Gaps', 'Critically appraise academic and grey sources for credibility and quality, and identify and justify theoretical, empirical, methodological, contextual and practical research gaps.', array['Evaluating academic sources', 'Identifying research gaps']::text[], 45, 'intermediate', 'supplementary', '{"introduction":"Finding literature is only the first step. A postgraduate researcher must decide which sources deserve trust, how much weight each should carry, and what the body of evidence collectively does and does not establish. Not every published article is equally credible: journals vary in rigour, some publishers operate without meaningful peer review, findings can be overturned, and even excellent studies have limitations that restrict what they show. A literature review that treats every source as equally authoritative is uncritical, and its conclusions are only as strong as its weakest evidence.\n\nThis lesson develops two linked skills. First, **evaluating sources**: judging the credibility, relevance and methodological quality of what you read. Second, **identifying research gaps**: using that critical evaluation to locate where knowledge is missing, inconsistent or weak, and arguing convincingly that your study addresses one of those gaps.","objectives":["Explain why critical evaluation of sources is essential to a credible literature review.","Apply source-evaluation criteria, including currency, relevance, authority, accuracy and purpose, to academic and grey literature.","Evaluate the methodological quality of empirical studies using structured appraisal questions.","Distinguish theoretical, empirical, methodological, contextual and practical research gaps.","Construct a justified gap statement that links the literature to a proposed study."],"prerequisites":["Purposes of literature reviews and search strategies (previous lesson).","Basic understanding of research designs and sampling."],"keyTerms":[{"term":"Peer review","definition":"Evaluation of a manuscript by independent experts before publication to assess its quality, originality and validity."},{"term":"Predatory publishing","definition":"Publishing practices that charge authors fees while providing little or no genuine peer review or editorial oversight."},{"term":"Retraction","definition":"The formal withdrawal of a published article, typically because of serious error, misconduct or unreliable findings."},{"term":"Critical appraisal","definition":"Systematic assessment of a study''s trustworthiness, relevance and methodological quality."},{"term":"Research gap","definition":"An area where existing knowledge is missing, inconsistent, outdated or methodologically weak, providing a justification for new research."},{"term":"Contextual gap","definition":"A lack of evidence about whether findings hold in a particular population, sector, country or setting."},{"term":"Methodological gap","definition":"A weakness or lack of variety in how a topic has been studied, such as reliance on cross-sectional self-report surveys."},{"term":"Theoretical gap","definition":"An unexplained phenomenon, untested relationship or unchallenged assumption in existing theory."}],"body":[{"heading":"Detailed Explanation","markdown":"### Why evaluation matters\n\nEvidence differs in quality. A well-designed longitudinal study with validated measures and a clearly defined sample offers stronger evidence than a small convenience survey with untested items. A peer-reviewed article in an established journal generally deserves more confidence than an unreviewed blog post, but peer review is not infallible. Evaluating sources lets you weight evidence appropriately, explain inconsistencies between studies, and avoid building your argument on findings that are weak, biased or withdrawn.\n\n### Evaluating the source\n\nSeveral checklists help structure source evaluation. The **CRAAP test**, developed by librarians at California State University, Chico, asks about Currency, Relevance, Authority, Accuracy and Purpose. Adapted for postgraduate research:\n\n- **Currency.** When was it published? In fast-moving areas such as AI or mobile payments, older studies may describe technologies that have changed substantially. Seminal works, however, remain essential regardless of age (Davis, 1989, is still cited for TAM).\n- **Relevance.** Does it address your concepts, population or context? Is it the right level (scholarly rather than popular)?\n- **Authority.** Who wrote it and where was it published? Is the journal established and genuinely peer-reviewed? Is the publisher reputable?\n- **Accuracy.** Is the evidence presented, are claims supported with data and references, and are methods described clearly enough to judge them?\n- **Purpose.** Was it written to inform, to sell or to persuade? Vendor white papers and sponsored reports may present selective evidence.\n\n### Recognising questionable publishing\n\nStudents should be cautious of journals that promise very rapid acceptance, solicit papers through unsolicited emails, display unclear editorial boards or peer review processes, or publish articles with obvious errors. Checking whether a journal is listed in reputable indexes such as DOAJ (for open access journals), Scopus or Web of Science, and whether it is recognised in your field, is a sensible first step. Absence from an index is not automatic proof of poor quality, but it should prompt closer scrutiny.\n\n### Appraising methodological quality\n\nBeyond the source, appraise the study itself. Useful questions include:\n\n1. Is the research question clear, and does the design suit it?\n2. Is the sample appropriate in size and selection for the claims made?\n3. Are the measures or interview guides valid and reliable, and are they reported?\n4. Is the analysis appropriate and clearly reported?\n5. Do the conclusions follow from the findings, or do the authors overclaim (for example, inferring causation from a cross-sectional survey)?\n6. Are limitations acknowledged?\n7. Are there potential conflicts of interest?\n\nRecording these judgements in a structured way, for instance in a synthesis matrix column for \"strengths and weaknesses\", feeds directly into critical writing.\n\n### From evaluation to gaps\n\nGaps emerge from critical evaluation of the literature as a whole. Common types include:\n\n| Gap type | Description | Illustrative example |\n|---|---|---|\n| Theoretical | A relationship is untested, a theory fails to explain observations, or an assumption is unexamined | Adoption models assume individual decision-making, but SME technology decisions may be collective |\n| Empirical or evidence | Little or contradictory evidence exists | Studies disagree on whether perceived risk deters mobile payment use |\n| Methodological | The topic has been studied with limited methods | Most studies of cybersecurity awareness use self-report rather than observed behaviour |\n| Contextual or population | Findings have not been tested in a particular setting | Few studies examine AI adoption among Ghanaian SMEs outside Accra |\n| Practical | Practitioners lack knowledge needed for decisions | Hospital managers lack evidence on which training approaches support EHR use |\n| Temporal | Evidence is outdated owing to technological or social change | Pre-smartphone e-commerce studies may not reflect current behaviour |\n\nA strong **gap statement** names the gap, shows evidence for it from the literature, and explains why addressing it matters. It avoids sweeping claims such as \"no research exists on this topic\", which are rarely true and easily disproved; \"limited research has examined…\" is usually more accurate."},{"heading":"Theories, Frameworks and Models","markdown":"### A hierarchy of evidence, used cautiously\n\nHealth sciences often use a hierarchy that ranks systematic reviews and randomised controlled trials above observational studies and expert opinion. Business and IT research rarely fits neatly into this hierarchy because many questions concern meanings, processes or organisational contexts that experiments cannot address. A more useful principle for MSc students is **fitness for purpose**: the best evidence is the study design most appropriate to the question, executed rigorously. An in-depth interpretive case study may be the strongest available evidence on how a bank''s staff experienced a core system migration."},{"heading":"Diagram","markdown":"```mermaid\nflowchart TD\n    A[\"Retrieved source\"] --> B{\"Credible source?\"}\n    B -->|\"No: predatory, retracted or unsupported\"| X[\"Exclude or treat with caution\"]\n    B -->|\"Yes\"| C{\"Relevant to my question?\"}\n    C -->|\"No\"| X\n    C -->|\"Yes\"| D[\"Appraise methodological quality\"]\n    D --> E[\"Record strengths, weaknesses and findings\"]\n    E --> F[\"Compare across studies\"]\n    F --> G[\"Identify patterns, contradictions and absences\"]\n    G --> H[\"Write a justified gap statement\"]\n```"},{"heading":"Worked Example","markdown":"**Illustrative scenario.** Kwame is reviewing literature on digital payment adoption among retailers in Ghana. He has four sources.\n\n1. **A peer-reviewed article in an established IS journal** testing UTAUT with a large sample of consumers in another African country. *Evaluation:* credible and rigorous, but its population is consumers, not merchants, so relevance is partial. *Use:* theory and measurement scales.\n2. **An article in a journal that accepted it within a week and charged a high fee**, with no named editorial board and several statistical errors. *Evaluation:* questionable authority and accuracy. *Use:* excluded, or at most noted with explicit caution.\n3. **A telecom operator''s white paper** reporting rapid merchant uptake. *Evaluation:* useful context but potentially promotional purpose. *Use:* cited cautiously for context, with its commercial origin acknowledged.\n4. **A qualitative study of market traders in Ghana** with a small sample but rich interview data showing concerns about transaction charges and privacy. *Evaluation:* credible and contextually relevant; not statistically generalisable. *Use:* to identify constructs (cost, privacy) that quantitative merchant studies have rarely measured.\n\n**Gap statement:** \"While consumer adoption of digital payments has been examined extensively using UTAUT, comparatively few studies have examined merchants, and qualitative evidence from Ghanaian markets suggests that transaction costs and privacy concerns may influence merchant acceptance in ways that existing models do not capture. This study therefore tests an extended UTAUT model among registered retailers in Accra.\" The statement identifies population, theoretical and contextual gaps and links them to the study."},{"heading":"Ghanaian Business Application","markdown":"Evaluating sources is particularly important for Ghanaian business and technology topics, where students may encounter a mix of international journals, regional journals of varying quality, conference papers, theses, news reports and corporate announcements. Several practical rules help:\n\n- **Check figures at their origin.** Statistics about mobile money, internet penetration or cybercrime are frequently repeated in news articles and dissertations without sources. Trace each figure back to the original publication, such as an official report, and cite that, or omit it.\n- **Distinguish regulatory facts from commentary.** The existence and provisions of laws such as the Data Protection Act, 2012 (Act 843) or the Cybersecurity Act, 2020 (Act 1038) should be cited from official texts, not from blog summaries.\n- **Be wary of promotional sources.** Fintech and telecom press releases may be useful context but are not neutral evidence of adoption or impact.\n- **Value local qualitative research.** Small Ghanaian qualitative studies may lack statistical generalisability but provide contextual insight that international surveys miss. Evaluate them by qualitative quality criteria rather than dismissing them.\n\nContextual gaps are common justifications in Ghanaian MSc research, but they are strongest when combined with a theoretical or practical argument for why the Ghanaian context matters, for example the role of informal trade, mobile money agents or family ownership structures."},{"heading":"International Case Study","markdown":"### The retracted Wakefield paper\n\nIn 1998, *The Lancet* published a paper led by Andrew Wakefield that suggested a link between the measles, mumps and rubella (MMR) vaccine and developmental disorders in children. The study involved a very small number of children and could not establish causation, yet it received enormous media attention and contributed to declining vaccination rates in some countries. Subsequent investigations revealed serious ethical and scientific problems, and *The Lancet* fully retracted the paper in 2010. Large-scale studies found no evidence of the claimed link.\n\nAlthough this case comes from medicine, its lessons apply to every field. First, publication in a prestigious journal does not guarantee reliability. Second, small samples and designs that cannot support causal claims should be read cautiously, however striking their conclusions. Third, researchers should check whether articles have been retracted or corrected, since retracted papers continue to be cited. For business and IT students, the case is a powerful reminder that critical appraisal of method, not trust in reputation alone, protects the integrity of a literature review."}],"misconceptions":["**Misconception:** Peer-reviewed means correct. **Correction:** Peer review improves quality but does not guarantee it; individual studies still need appraisal.","**Misconception:** Older sources should always be excluded. **Correction:** Seminal works remain essential; currency matters most for fast-changing technologies and statistics.","**Misconception:** Grey literature has no place in academic research. **Correction:** Official reports can provide valuable context if evaluated carefully and cited precisely.","**Misconception:** A gap means no research exists. **Correction:** Gaps are often about limited, inconsistent or methodologically weak evidence, or untested contexts.","**Misconception:** Qualitative studies are weak evidence because they have small samples. **Correction:** Their quality is judged by different criteria, and they provide depth that surveys cannot."],"examMistakes":["Claiming \"there is no research on this topic\" without evidence.","Accepting statistics from news or websites without tracing their origin.","Evaluating sources only by date or journal name, without considering methodology.","Identifying a gap without explaining why it matters.","Confusing a contextual gap with a theoretical contribution."],"criticalQuestions":["How should a researcher handle an important study whose methods are weak but which is the only evidence in a Ghanaian context?","Does the pressure to publish encourage questionable journals, and what are the implications for researchers in developing economies?","Can a contextual gap alone justify a dissertation, or must it be combined with another type of gap?","How might reliance on English-language, indexed journals bias literature reviews about African business?"],"exercises":["**Source evaluation table.** Select five sources on cybersecurity awareness among students (at least one grey source). Evaluate each using currency, relevance, authority, accuracy and purpose. *Expected output:* a five-row table with a rating and comment for each criterion and an overall decision (use, use with caution, exclude).","**Appraise a study.** Apply the seven appraisal questions to one empirical article on technology adoption in Ghanaian healthcare. *Expected output:* a half-page appraisal identifying at least two strengths and two weaknesses with reasons.","**Write a gap statement.** Using your sources, draft a gap statement of 100 to 150 words for a study of e-commerce adoption among small businesses. *Expected output:* a statement naming the gap type(s), citing evidence and linking to a proposed study."],"takeaways":["Evidence varies in quality; evaluate both the source and the study.","Use currency, relevance, authority, accuracy and purpose to judge sources.","Appraise design, sample, measures, analysis, conclusions, limitations and interests.","Gaps may be theoretical, empirical, methodological, contextual, practical or temporal.","A strong gap statement is evidence-based, precise and linked to the study''s significance."],"furtherReading":[{"text":"Saunders, M., Lewis, P., & Thornhill, A. (2019). *Research methods for business students* (8th ed.). Pearson.","url":null,"verification":"citation"},{"text":"Sandberg, J., & Alvesson, M. (2011). Ways of constructing research questions: Gap-spotting or problematization? *Organization, 18*(1), 23-44.","url":null,"verification":"citation"},{"text":"Hart, C. (1998). *Doing a literature review: Releasing the social science research imagination*. SAGE.","url":null,"verification":"citation"},{"text":"Snyder, H. (2019). Literature review as a research methodology: An overview and guidelines. *Journal of Business Research, 104*, 333-339.","url":"https://doi.org/10.1016/j.jbusres.2019.07.039","verification":"verified"}],"videos":[{"title":"Directory of Open Access Journals","url":"https://doaj.org/","description":"DOAJ. Official directory of quality-checked open access journals, useful for checking a journal''s listing.","verification":"unverified"},{"title":"Purdue Online Writing Lab","url":"https://owl.purdue.edu/","description":"Purdue University. Official writing resource with guidance on evaluating sources.","verification":"verified"}],"revisionSummary":"Critical evaluation weighs evidence according to the credibility of the source and the quality of the study. Sources are judged by currency, relevance, authority, accuracy and purpose; studies by design fit, sampling, measures, analysis, justified conclusions, acknowledged limitations and conflicts of interest. Gaps emerge from evaluating the literature as a whole and must be stated precisely and linked to significance.\n\n- Peer review helps but does not guarantee correctness; check for retractions.\n- Trace statistics to their original source.\n- Fitness for purpose matters more than a rigid evidence hierarchy.\n- Gap types: theoretical, empirical, methodological, contextual, practical, temporal.\n- Prefer \"limited research has examined…\" to \"no research exists\"."}'::jsonb, 2373, 2, true)
  on conflict (id) do update set module_id = excluded.module_id, slug = excluded.slug, title = excluded.title, summary = excluded.summary, topics = excluded.topics, estimated_minutes = excluded.estimated_minutes, difficulty = excluded.difficulty, source = excluded.source, content = excluded.content, word_count = excluded.word_count, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.lessons (id, module_id, slug, title, summary, topics, estimated_minutes, difficulty, source, content, word_count, sort_order, is_published) values ('70eb8d1f-66cc-5f35-8a64-5653e434859e', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'synthesising-literature', 'Synthesising Literature', 'Move from summarising individual sources to synthesising them thematically, using synthesis and concept matrices, and write critically about patterns, contradictions and gaps.', array['Synthesising literature', 'Synthesis matrices', 'Critical writing']::text[], 45, 'advanced', 'supplementary', '{"introduction":"Synthesis is the skill that separates a postgraduate literature review from an undergraduate essay. Summarising means reporting what one source says. Synthesising means combining what *many* sources say to reveal patterns, agreements, contradictions and gaps, and to build an argument that no single source makes on its own. Examiners often comment that a review \"describes rather than analyses\" or \"is organised by author rather than theme\"; both comments are requests for synthesis.\n\nThis lesson explains what synthesis involves, introduces practical tools (the synthesis matrix and Webster and Watson''s concept matrix) for organising sources, and shows how to write critically using appropriate academic language. It builds on the previous lessons on searching and evaluating sources and prepares you to construct theoretical and conceptual frameworks in the final lesson of this module.","objectives":["Distinguish summary, paraphrase, analysis and synthesis in literature reviews.","Construct a synthesis matrix that organises sources by concept or theme.","Apply thematic, theoretical, methodological and chronological structures to organise a review.","Write critically synthesised paragraphs that compare, contrast and evaluate multiple sources.","Evaluate a literature review draft for descriptive and author-centred writing."],"prerequisites":["Searching for and evaluating sources and identifying gaps (previous lessons).","Familiarity with APA 7 in-text citation."],"keyTerms":[{"term":"Summary","definition":"A condensed account of the main points of a single source in your own words."},{"term":"Synthesis","definition":"The integration of findings and ideas from multiple sources to identify relationships, patterns and gaps and to construct a new, coherent argument."},{"term":"Synthesis matrix","definition":"A table in which rows represent sources and columns represent concepts, themes or attributes, used to compare sources systematically."},{"term":"Concept matrix","definition":"Webster and Watson''s tool for organising a review by concept, showing which sources address which concepts."},{"term":"Author-centric review","definition":"A review organised source by source, which tends to be descriptive."},{"term":"Concept-centric review","definition":"A review organised around ideas, themes or variables, which supports synthesis."},{"term":"Critical writing","definition":"Writing that evaluates evidence, explains disagreement, weighs strengths and weaknesses and draws reasoned conclusions."},{"term":"Reporting verbs","definition":"Verbs such as argue, demonstrate, suggest, contend and claim that signal how strongly an author asserts a position."}],"body":[{"heading":"Detailed Explanation","markdown":"### From summary to synthesis\n\nConsider four levels of engagement with literature.\n\n1. **Summary**: \"Owusu (2020) found that trust influenced mobile money use.\"\n2. **Juxtaposition**: \"Owusu (2020) found that trust influenced mobile money use. Brown (2019) found that cost was more important.\"\n3. **Comparison and analysis**: \"While Owusu (2020) identified trust as the strongest predictor, Brown (2019) found cost more influential; the difference may reflect their populations, as Owusu surveyed urban consumers and Brown rural traders.\"\n4. **Synthesis**: \"Studies consistently identify trust and cost as determinants of mobile money use, but their relative importance appears to vary by user group: trust dominates among urban consumers, whereas cost appears more salient for traders operating on thin margins. This pattern suggests that merchant adoption may follow a different logic from consumer adoption, a possibility that has rarely been tested directly.\"\n\n*(The names above are illustrative placeholders, not real studies.)*\n\nLevel four makes a claim about the literature as a whole, explains variation, and points to a gap. Most strong review paragraphs work at levels three and four.\n\n### Organising a review\n\nA review can be structured in several ways, and many combine them.\n\n- **Thematic or conceptual**: sections on each theme or construct (for example, perceived usefulness, cost, trust, infrastructure). This is the most common and most effective structure for MSc reviews.\n- **Theoretical**: sections on competing theories (for example, TAM, UTAUT, Diffusion of Innovations) and how each explains the phenomenon.\n- **Methodological**: grouping studies by approach (surveys, case studies, experiments) to show how method influences findings.\n- **Chronological**: tracing how understanding developed over time; useful for showing evolution but risks becoming descriptive.\n\nWhichever structure you choose, each section should open with a claim (a topic sentence), develop the claim with evidence from several sources, evaluate that evidence, and close with what it means for your study.\n\n### The synthesis matrix\n\nA **synthesis matrix** is the practical bridge between reading and writing. Rows are sources; columns are the concepts or attributes you care about. Filling it in as you read forces you to extract comparable information and makes patterns visible when you read across a column.\n\n| Source | Context and sample | Method | Usefulness | Cost | Trust | Key limitation |\n|---|---|---|---|---|---|---|\n| Study A | Consumers, urban | Survey | Significant | Not measured | Strong | Cross-sectional |\n| Study B | Traders, rural | Interviews | Mentioned | Central theme | Moderate | Small sample |\n| Study C | SMEs, national | Survey | Significant | Significant | Not measured | Self-report |\n| Study D | Merchants, peri-urban | Mixed methods | Significant | Significant | Weak | Single region |\n\n*(Illustrative content for demonstration.)*\n\nReading down the \"Cost\" column shows that cost matters wherever merchants or traders are studied but is often unmeasured in consumer studies, which is itself a synthesis insight.\n\n### Webster and Watson''s concept matrix\n\nWebster and Watson (2002) recommended a **concept matrix** in which concepts form the columns and articles the rows, with ticks showing which concepts each article addresses. They suggested that units of analysis (individual, group, organisation) can be added as sub-columns. The matrix encourages a concept-centric review and quickly exposes concepts that few studies have examined together.\n\n### Critical writing\n\nCritical writing does not mean being negative. It means making reasoned judgements. Useful moves include:\n\n- **Comparing and contrasting:** \"In contrast to…\", \"Consistent with…\", \"Similarly…\".\n- **Explaining inconsistency:** \"These divergent findings may be explained by differences in…\".\n- **Evaluating strength of evidence:** \"Although widely cited, this finding rests on a small convenience sample…\".\n- **Choosing reporting verbs carefully:** *demonstrates* implies strong evidence; *suggests* implies tentative evidence; *claims* implies scepticism. Use them accurately.\n- **Establishing your voice:** after presenting evidence, state what you conclude and why it matters for your study.\n\nAvoid long direct quotations; paraphrase and synthesise in your own words with accurate citations. Integrate citations as evidence for your claims, not as the subjects of every sentence."},{"heading":"Theories, Frameworks and Models","markdown":"### A paragraph structure for synthesis\n\nA useful model for each paragraph is **Claim, Evidence, Analysis, Link**:\n\n| Element | Function | Example phrase |\n|---|---|---|\n| Claim | State a point about the literature | \"Research consistently links facilitating conditions to EHR use.\" |\n| Evidence | Cite several sources that support or complicate it | \"Studies in teaching hospitals and district facilities report…\" |\n| Analysis | Compare, explain differences, evaluate quality | \"However, most rely on self-reported use, which may overstate…\" |\n| Link | Connect to your study or the next point | \"This study therefore measures use through system logs where available.\" |"},{"heading":"Diagram","markdown":"```mermaid\nflowchart LR\n    A[\"Read and evaluate sources\"] --> B[\"Extract into synthesis matrix\"]\n    B --> C[\"Read across columns for patterns\"]\n    C --> D[\"Identify agreements, contradictions, gaps\"]\n    D --> E[\"Plan thematic sections\"]\n    E --> F[\"Write Claim-Evidence-Analysis-Link paragraphs\"]\n    F --> G[\"Conclude each section with implications for the study\"]\n```"},{"heading":"Worked Example","markdown":"**Illustrative scenario.** Esi''s draft paragraph on cybersecurity awareness reads:\n\n> \"Adjei (2018) studied students and found low awareness. Mensah (2020) studied staff and found moderate awareness. Lee (2019) did a survey in Asia and found that training helped. Kim (2021) found that students who were victims were more careful.\"\n\n*(Names are placeholders for illustration.)*\n\n**Diagnosis:** author-centric, descriptive, no claim, no evaluation, no link.\n\n**Step 1: Identify the theme.** All four sources concern factors associated with security awareness and behaviour.\n\n**Step 2: Read across the matrix.** Two sources address training, one addresses prior victimisation, and two compare populations. Three rely on self-reported awareness.\n\n**Step 3: Rewrite using Claim, Evidence, Analysis, Link.**\n\n> \"Existing studies suggest that awareness of cybersecurity risks varies by population and is associated with prior training and experience of victimisation. Studies of students tend to report lower awareness than studies of staff, while survey evidence from Asia indicates that structured training is associated with safer practices, and students who have previously been victims appear more cautious. However, most of this evidence relies on self-reported awareness, which may not reflect actual behaviour, and few studies examine training and prior victimisation together. This study therefore examines both factors in relation to observed security behaviour among Ghanaian undergraduates.\"\n\nThe expected outcome is a paragraph that makes a claim about the literature, explains variation, evaluates evidence quality and links to the study."},{"heading":"Ghanaian Business Application","markdown":"Synthesis is particularly valuable when Ghanaian evidence is limited. A student studying AI adoption among SMEs in Ghana may find few Ghana-specific studies but many international ones. Rather than reviewing them separately (\"studies abroad found…; studies in Ghana found…\"), the student can synthesise thematically: for each determinant, such as cost, skills, data availability, perceived usefulness or management support, the review can compare evidence from different contexts and ask whether Ghanaian conditions, such as reliance on mobile connectivity, informal business practices or limited local AI expertise, might strengthen or weaken the relationship.\n\nSimilar reasoning applies to technology adoption in Ghanaian healthcare. A synthesis matrix might reveal that facilitating conditions (power supply, connectivity, technical support) feature far more prominently in studies from resource-constrained settings than in studies from high-income countries. That pattern becomes a synthesised argument for giving facilitating conditions a central role in the conceptual framework, a clear demonstration of how synthesis feeds directly into research design."},{"heading":"International Case Study","markdown":"### Webster and Watson''s guidance in information systems\n\nJane Webster and Richard Watson''s 2002 editorial in *MIS Quarterly*, \"Analyzing the Past to Prepare for the Future: Writing a Literature Review\", was written partly in response to a perceived shortage of high-quality review articles in information systems. They argued that reviews should be concept-centric, proposed the concept matrix as a tool, recommended structured searching including backward and forward citation searches, and encouraged authors to develop theoretical models and propositions from their synthesis rather than simply cataloguing previous work.\n\nThe article has become one of the most widely cited methodological guides in the IS field and is frequently referenced in dissertations worldwide. Its lasting influence shows that synthesis is not just a writing style but a means of creating knowledge: a well-synthesised review can generate new conceptual models that later studies test. For MSc students, following its principles is a practical way to meet examiners'' expectations of critical, concept-centric reviewing."}],"misconceptions":["**Misconception:** Synthesis means summarising many sources in one paragraph. **Correction:** Synthesis integrates sources to make a new claim about patterns, differences and gaps.","**Misconception:** Critical writing means criticising authors. **Correction:** It means evaluating evidence fairly, including strengths as well as weaknesses.","**Misconception:** Chronological organisation is always best. **Correction:** Thematic organisation usually supports synthesis better; chronology suits only arguments about development over time.","**Misconception:** More citations per sentence always show better synthesis. **Correction:** Citations must support an analytical claim; lists of citations without analysis remain descriptive.","**Misconception:** The synthesis matrix is optional busywork. **Correction:** It is the most reliable way to see patterns across sources before writing."],"examMistakes":["Organising the review source by source (\"Author A found…, Author B found…\").","Using reporting verbs inaccurately, for example \"proves\" for tentative findings.","Over-relying on long direct quotations instead of paraphrased synthesis.","Ending sections without stating implications for the study.","Presenting a literature review with no evaluative comments on evidence quality."],"criticalQuestions":["How can a reviewer synthesise studies that used different definitions or measures of the same construct?","When does synthesis risk oversimplifying genuinely contradictory evidence?","How should a reviewer integrate qualitative and quantitative findings on the same theme?","Is it possible for a review to be too concept-centric, losing important information about context and method?"],"exercises":["**Build a synthesis matrix.** For a study of e-commerce adoption among small businesses, create a matrix with at least six real sources you have found and columns for context, method, three key concepts and limitations. *Expected output:* a completed matrix and three sentences describing patterns visible when reading down the columns.","**Rewrite a descriptive paragraph.** Rewrite the following using Claim, Evidence, Analysis, Link: \"Study 1 found trust important. Study 2 found trust not significant. Study 3 found cost important.\" *Expected output:* a synthesised paragraph that explains the contradiction, evaluates the evidence and links to a proposed study.","**Outline a thematic review.** Produce a section outline for a literature review on digital payment adoption among Ghanaian retailers. *Expected output:* four to six thematic headings, each with a topic sentence stating the claim the section will make."],"takeaways":["Summary reports one source; synthesis integrates many to make new claims.","Organise reviews thematically or conceptually wherever possible.","Synthesis and concept matrices make patterns, contradictions and gaps visible.","Write paragraphs using Claim, Evidence, Analysis, Link.","Critical writing evaluates evidence fairly and uses reporting verbs precisely."],"furtherReading":[{"text":"Webster, J., & Watson, R. T. (2002). Analyzing the past to prepare for the future: Writing a literature review. *MIS Quarterly, 26*(2), xiii-xxiii.","url":null,"verification":"citation"},{"text":"Hart, C. (1998). *Doing a literature review: Releasing the social science research imagination*. SAGE.","url":null,"verification":"citation"},{"text":"Snyder, H. (2019). Literature review as a research methodology: An overview and guidelines. *Journal of Business Research, 104*, 333-339.","url":"https://doi.org/10.1016/j.jbusres.2019.07.039","verification":"verified"},{"text":"Saunders, M., Lewis, P., & Thornhill, A. (2019). *Research methods for business students* (8th ed.). Pearson.","url":null,"verification":"citation"}],"videos":[{"title":"Purdue Online Writing Lab","url":"https://owl.purdue.edu/","description":"Purdue University. Official writing resource covering synthesis, paraphrasing and academic writing.","verification":"verified"},{"title":"Zotero Documentation","url":"https://www.zotero.org/support/","description":"Zotero. Official documentation for organising sources, notes and tags that support a synthesis matrix.","verification":"verified"}],"revisionSummary":"Synthesis integrates multiple sources to reveal patterns, explain contradictions and identify gaps, producing an argument no single source makes. Reviews should be concept-centric, typically organised thematically, and built from synthesis or concept matrices that make cross-source patterns visible. Paragraphs follow Claim, Evidence, Analysis, Link, and critical writing evaluates evidence fairly with precise reporting verbs.\n\n- Summary, juxtaposition, comparison, synthesis.\n- Thematic, theoretical, methodological or chronological structures.\n- Synthesis matrix: sources as rows, concepts as columns.\n- Webster and Watson (2002): concept-centric reviews and the concept matrix.\n- End each section with implications for your own study."}'::jsonb, 2233, 3, true)
  on conflict (id) do update set module_id = excluded.module_id, slug = excluded.slug, title = excluded.title, summary = excluded.summary, topics = excluded.topics, estimated_minutes = excluded.estimated_minutes, difficulty = excluded.difficulty, source = excluded.source, content = excluded.content, word_count = excluded.word_count, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.lessons (id, module_id, slug, title, summary, topics, estimated_minutes, difficulty, source, content, word_count, sort_order, is_published) values ('71359625-959c-5565-bb05-27721d982ebc', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'theoretical-and-conceptual-frameworks', 'Theoretical and Conceptual Frameworks', 'Distinguish theoretical from conceptual frameworks, explain TAM, UTAUT and Diffusion of Innovations, and build and justify a conceptual framework for a Ghanaian technology adoption study.', array['Theoretical frameworks', 'Conceptual frameworks', 'TAM', 'UTAUT', 'Diffusion of Innovations']::text[], 55, 'advanced', 'supplementary', '{"introduction":"A literature review ends by telling the reader how the study will think about its problem. That is the role of the **theoretical framework** and the **conceptual framework**. These frameworks determine which variables or themes are examined, which relationships are hypothesised, how questionnaires and interview guides are designed and how findings are interpreted. A dissertation without a clear framework tends to collect data on everything and explain nothing.\n\nIn IT-for-business research, technology adoption theories dominate. This lesson explains the difference between theoretical and conceptual frameworks, examines three of the most influential adoption theories in detail, namely the Technology Acceptance Model (TAM), the Unified Theory of Acceptance and Use of Technology (UTAUT) and Diffusion of Innovations (DOI), and shows step by step how to construct and justify a conceptual framework for a Ghanaian study.","objectives":["Distinguish a theoretical framework from a conceptual framework and explain how each is used.","Explain the constructs and relationships of TAM, UTAUT and Diffusion of Innovations.","Compare the strengths and limitations of these theories for studying technology adoption in Ghanaian organisations.","Construct a conceptual framework diagram with justified constructs and hypothesised relationships.","Evaluate whether a framework fits a given research question and level of analysis."],"prerequisites":["Research objectives, questions and hypotheses (Module 2).","Synthesising literature (previous lesson)."],"keyTerms":[{"term":"Theory","definition":"A set of interrelated concepts and propositions that explains or predicts a phenomenon."},{"term":"Theoretical framework","definition":"The established theory or theories a study draws on to explain the phenomenon and justify its focus."},{"term":"Conceptual framework","definition":"The researcher''s own model, usually presented as a diagram, showing the specific constructs and relationships the study will examine, derived from theory and literature."},{"term":"Construct","definition":"An abstract concept, such as perceived usefulness, that is defined theoretically and measured through indicators."},{"term":"Moderator","definition":"A variable that changes the strength or direction of a relationship between two other variables."},{"term":"Mediator","definition":"A variable that explains how or why an independent variable affects a dependent variable."},{"term":"Level of analysis","definition":"Whether a theory explains behaviour of individuals, groups, organisations or wider systems."},{"term":"Behavioural intention","definition":"A person''s stated likelihood of performing a behaviour, such as using a system, central in many adoption models."}],"body":[{"heading":"Detailed Explanation","markdown":"### Theoretical versus conceptual frameworks\n\nThe two terms are often confused. A **theoretical framework** refers to one or more existing, tested theories that explain the phenomenon, such as UTAUT. It provides the \"lens\" for the study. A **conceptual framework** is the researcher''s own structured representation of the specific constructs and relationships to be investigated in *this* study. It may adapt a theory (by selecting some constructs), combine theories, or add constructs supported by the literature, such as trust or cost. In quantitative studies the conceptual framework usually appears as a diagram of boxes and arrows, with each arrow corresponding to a hypothesis. In qualitative studies it may be a looser set of sensitising concepts that guide data collection without fixing relationships in advance.\n\nA helpful way to remember the distinction: the theoretical framework is borrowed; the conceptual framework is built.\n\n### The Technology Acceptance Model (TAM)\n\nDavis (1989) proposed that two beliefs shape whether people accept an information technology. **Perceived usefulness** is the degree to which a person believes that using a system would enhance their job performance. **Perceived ease of use** is the degree to which a person believes that using the system would be free of effort. In the model, ease of use also influences usefulness, and both influence attitudes and behavioural intention, which in turn predicts actual use. TAM drew on the Theory of Reasoned Action and became one of the most widely applied models in IS research. Venkatesh and Davis (2000) extended it as TAM2 by adding determinants of usefulness, such as subjective norm and job relevance.\n\n**Strengths:** parsimony, validated measurement scales and wide empirical support. **Limitations:** it focuses on individual beliefs, may neglect organisational, social and economic factors, and was originally developed in workplace settings where use was often expected.\n\n### The Unified Theory of Acceptance and Use of Technology (UTAUT)\n\nVenkatesh, Morris, Davis and Davis (2003) reviewed and empirically compared eight models of technology acceptance and integrated them into UTAUT. It proposes four core determinants:\n\n- **Performance expectancy**: the belief that using the system will help attain gains in job performance (related to perceived usefulness).\n- **Effort expectancy**: the ease associated with using the system (related to perceived ease of use).\n- **Social influence**: the degree to which important others believe the individual should use the system.\n- **Facilitating conditions**: the belief that organisational and technical infrastructure exists to support use.\n\nThe first three influence behavioural intention; intention and facilitating conditions influence use behaviour. **Gender, age, experience and voluntariness of use** moderate key relationships. Venkatesh, Thong and Xu (2012) later proposed UTAUT2 for consumer contexts, adding hedonic motivation, price value and habit.\n\n**Strengths:** integrates prior models, explains behaviour well in organisational settings, includes facilitating conditions that matter greatly in resource-constrained contexts. **Limitations:** complexity, frequent partial or inconsistent application (moderators are often dropped without justification) and a focus on individual users rather than organisational adoption decisions.\n\n### Diffusion of Innovations (DOI)\n\nEverett Rogers'' *Diffusion of Innovations* explains how innovations spread through social systems over time. Rogers identified five perceived attributes of innovations that influence their rate of adoption:\n\n- **Relative advantage**: the degree to which an innovation is perceived as better than what it replaces.\n- **Compatibility**: consistency with existing values, experiences and needs.\n- **Complexity**: the perceived difficulty of understanding and using it.\n- **Trialability**: the extent to which it can be experimented with on a limited basis.\n- **Observability**: the visibility of its results to others.\n\nRogers also categorised adopters by the timing of adoption as innovators, early adopters, early majority, late majority and laggards, and described an innovation-decision process moving from knowledge through persuasion, decision and implementation to confirmation. Communication channels and social networks are central to diffusion.\n\n**Strengths:** applicable to individuals and organisations, explains the social spread of innovations and offers a time dimension. **Limitations:** a pro-innovation bias (assuming adoption is desirable), and attributes are sometimes measured inconsistently.\n\n### Other frameworks worth knowing\n\nFor organisation-level adoption, such as AI adoption by SMEs, many researchers use the **Technology-Organisation-Environment (TOE) framework** associated with Tornatzky and Fleischer (1990), which considers technological characteristics, organisational factors (size, resources, management support) and environmental factors (competition, regulation, vendor support). It is frequently combined with DOI. The Theory of Planned Behaviour (Ajzen, 1991) is another foundational model that adds perceived behavioural control to attitudes and subjective norms."},{"heading":"Theories, Frameworks and Models","markdown":"| Feature | TAM | UTAUT | Diffusion of Innovations |\n|---|---|---|---|\n| Originator | Davis (1989) | Venkatesh et al. (2003) | Rogers |\n| Core constructs | Perceived usefulness, perceived ease of use | Performance expectancy, effort expectancy, social influence, facilitating conditions | Relative advantage, compatibility, complexity, trialability, observability |\n| Outcome | Intention and use | Intention and use behaviour | Adoption and rate of diffusion |\n| Typical level | Individual | Individual | Individual or organisation, social system |\n| Moderators | Not central in original | Gender, age, experience, voluntariness | Adopter categories, communication channels |\n| Typical use in Ghana research | Mobile banking, e-learning acceptance | Mobile money, EHR, e-government services | SME technology adoption, often with TOE |\n| Key limitation | Neglects context and cost | Complex, often applied partially | Pro-innovation bias |"},{"heading":"Diagram","markdown":"The following conceptual framework is an **illustrative example** for a study of digital payment acceptance among Ghanaian retailers, adapting UTAUT and adding two constructs justified by literature (perceived transaction cost and trust).\n\n```mermaid\nflowchart LR\n    PE[\"Performance expectancy\"] -->|\"H1\"| BI[\"Behavioural intention to accept digital payments\"]\n    EE[\"Effort expectancy\"] -->|\"H2\"| BI\n    SI[\"Social influence\"] -->|\"H3\"| BI\n    TC[\"Perceived transaction cost\"] -->|\"H4 negative\"| BI\n    TR[\"Trust in payment provider\"] -->|\"H5\"| BI\n    FC[\"Facilitating conditions\"] -->|\"H6\"| UB[\"Actual acceptance behaviour\"]\n    BI -->|\"H7\"| UB\n```"},{"heading":"Step-by-Step Guide","markdown":"1. **Start with the research question and level of analysis.** Individual intention questions suit TAM or UTAUT; organisational adoption questions suit TOE or DOI.\n2. **Review candidate theories.** Use your synthesis to compare how well each theory explains the phenomenon in similar contexts.\n3. **Select a base theory and justify it.** Explain why it fits better than alternatives.\n4. **Adapt with justification.** Remove constructs that do not apply (for instance, voluntariness when use is voluntary for all participants) and add constructs supported by literature. Every addition needs a reason grounded in evidence.\n5. **Define each construct.** Provide clear conceptual definitions and identify validated measurement items.\n6. **Specify relationships and hypotheses.** Each arrow in the diagram should correspond to a hypothesis with a rationale.\n7. **Draw the diagram.** Keep it readable; label hypotheses.\n8. **Check alignment.** Confirm that objectives, questions, hypotheses and the questionnaire all match the framework."},{"heading":"Worked Example","markdown":"**Illustrative scenario.** Nana Ama is studying AI tool adoption among SMEs in Greater Accra.\n\n- **Question:** What factors influence SMEs'' adoption of AI-based tools?\n- **Level of analysis:** organisation, because the owner or management decides on adoption for the firm.\n- **Theory choice:** TOE combined with DOI, rather than UTAUT, because the decision concerns the firm rather than individual employee use.\n- **Constructs:** *Technology*, relative advantage and complexity (from DOI); *Organisation*, top management support and digital skills availability; *Environment*: competitive pressure and vendor support.\n- **Hypotheses:** for example, H1 relative advantage positively influences adoption; H2 complexity negatively influences adoption; H3 top management support positively influences adoption.\n- **Justification:** her synthesis showed that organisational resources and skills feature prominently in SME studies from developing economies, supporting the TOE organisational dimension.\n\nThe expected learning is that framework choice follows from the question and level of analysis, and that adaptations are justified by the literature."},{"heading":"Ghanaian Business Application","markdown":"Adoption theories are widely used in Ghanaian IT research on mobile money, internet banking, e-learning, e-government services and electronic health records. Applying them well in Ghana requires attention to context.\n\n- **Facilitating conditions** such as reliable electricity, network coverage, device costs and technical support may weigh more heavily than in the settings where theories were developed.\n- **Social influence** may operate through family, religious, professional or community networks, and through mobile money agents who often act as trusted intermediaries.\n- **Cost and price value** matter for traders and SMEs, which is why UTAUT2 or added constructs such as perceived transaction cost are often justified for consumer and merchant studies.\n- **Trust and perceived risk** frequently appear in studies of digital finance, given concerns about fraud and failed transactions.\n- **Organisational decisions** in SMEs are often made by owner-managers, so TOE and DOI may be more suitable than individual-level models.\n\nStudents should resist the temptation to add many constructs simply because they appear in the literature. A parsimonious, well-justified framework is stronger than a crowded diagram with weakly justified arrows."},{"heading":"International Case Study","markdown":"### Rogers and the diffusion of hybrid seed corn\n\nOne of the classic studies discussed in Rogers'' *Diffusion of Innovations* is the research by Bryce Ryan and Neal Gross, published in 1943, on how farmers in two Iowa communities adopted hybrid seed corn. Although hybrid corn offered clear advantages, adoption spread gradually over a number of years. Farmers typically first heard about the innovation through commercial sources such as salespeople, but neighbours were especially influential in persuading them to adopt, and many farmers tried the seed on part of their land before committing fully.\n\nThe study illustrates several of Rogers'' concepts: the S-shaped pattern of adoption over time, the role of interpersonal networks, the importance of trialability, and the different timing of adopter categories. It also demonstrates the theoretical value of diffusion research for technology adoption today. When Ghanaian market traders learn about a new payment app from a sales agent but decide to adopt only after seeing neighbouring traders use it successfully, the same mechanisms of observability and interpersonal influence are at work, nearly a century later."}],"misconceptions":["**Misconception:** Theoretical and conceptual frameworks are the same. **Correction:** The theoretical framework is the existing theory; the conceptual framework is the researcher''s adapted model of constructs and relationships for this study.","**Misconception:** A good framework includes as many constructs as possible. **Correction:** Parsimony and justification matter more than size.","**Misconception:** TAM or UTAUT suit every technology study. **Correction:** They explain individual acceptance; organisational adoption questions may need TOE or DOI.","**Misconception:** Qualitative studies cannot use theory. **Correction:** They may use theory as a sensitising lens or generate new theory, without fixed hypotheses.","**Misconception:** UTAUT moderators can be dropped freely. **Correction:** Removing them requires a reason, such as all participants sharing the same level of experience."],"examMistakes":["Describing TAM, UTAUT and DOI without applying them to the question.","Presenting a conceptual framework diagram with arrows that have no corresponding hypotheses.","Adding constructs without literature-based justification.","Mismatching the level of analysis, such as using UTAUT to explain an organisational purchasing decision without justification.","Misattributing constructs, for example listing \"relative advantage\" as a TAM construct."],"criticalQuestions":["Is UTAUT''s integration of eight models a strength or a weakness for researchers seeking explanation rather than prediction?","How might Rogers'' pro-innovation bias affect research on AI adoption among Ghanaian SMEs?","When is it legitimate to combine two theories in one conceptual framework, and what risks does this create?","Should researchers in Ghana develop new, context-specific adoption theories rather than adapting models developed elsewhere?"],"exercises":["**Theory selection.** For each of the following questions, choose TAM, UTAUT, DOI or TOE and justify your choice in two sentences: (a) nurses'' intention to use an EHR system; (b) SMEs'' decisions to adopt cloud accounting; (c) consumers'' continued use of a mobile banking app. *Expected output:* three choices with justifications referring to level of analysis and context.","**Build a framework.** Create a conceptual framework for cybersecurity behaviour among university students, based on an appropriate theory with up to two justified additional constructs. *Expected output:* a labelled diagram, a definition of each construct and a list of hypotheses matching each arrow.","**Critique a framework.** Find a published conceptual framework in a Ghanaian technology adoption study and evaluate it for justification, parsimony and alignment. *Expected output:* a half-page critique identifying at least two strengths and two possible improvements."],"takeaways":["The theoretical framework is borrowed theory; the conceptual framework is the researcher''s adapted model.","TAM centres on perceived usefulness and ease of use; UTAUT on performance expectancy, effort expectancy, social influence and facilitating conditions with moderators; DOI on five innovation attributes and social diffusion.","Choose theory according to question and level of analysis; TOE suits organisational adoption.","Justify every construct and arrow; each arrow is a hypothesis.","Adapt theories carefully to Ghanaian contexts, especially facilitating conditions, cost and trust."],"furtherReading":[{"text":"Davis, F. D. (1989). Perceived usefulness, perceived ease of use, and user acceptance of information technology. *MIS Quarterly, 13*(3), 319-340.","url":"https://doi.org/10.2307/249008","verification":"unverified"},{"text":"Venkatesh, V., Morris, M. G., Davis, G. B., & Davis, F. D. (2003). User acceptance of information technology: Toward a unified view. *MIS Quarterly, 27*(3), 425-478.","url":"https://doi.org/10.2307/30036540","verification":"unverified"},{"text":"Venkatesh, V., Thong, J. Y. L., & Xu, X. (2012). Consumer acceptance and use of information technology: Extending the unified theory of acceptance and use of technology. *MIS Quarterly, 36*(1), 157-178.","url":null,"verification":"citation"},{"text":"Rogers, E. M. (2003). *Diffusion of innovations* (5th ed.). Free Press.","url":null,"verification":"citation"},{"text":"Tornatzky, L. G., & Fleischer, M. (1990). *The processes of technological innovation*. Lexington Books.","url":null,"verification":"citation"},{"text":"Ajzen, I. (1991). The theory of planned behavior. *Organizational Behavior and Human Decision Processes, 50*(2), 179-211.","url":null,"verification":"citation"}],"videos":[{"title":"SAGE Research Methods","url":"https://methods.sagepub.com/","description":"SAGE Publishing. Official platform (institutional access may be required) with material on theoretical and conceptual frameworks.","verification":"verified"},{"title":"Coursera","url":"https://www.coursera.org/","description":"Coursera. Official learning platform; search for university courses on information systems and technology adoption.","verification":"verified"}],"revisionSummary":"A theoretical framework is the existing theory that provides the study''s lens; a conceptual framework is the researcher''s own adapted model of constructs and relationships, often a diagram in which each arrow is a hypothesis. TAM explains acceptance through perceived usefulness and ease of use; UTAUT integrates eight models around performance expectancy, effort expectancy, social influence and facilitating conditions, moderated by gender, age, experience and voluntariness; DOI explains adoption through relative advantage, compatibility, complexity, trialability and observability, and through social diffusion.\n\n- Borrowed theory versus built framework.\n- Match theory to level of analysis: TAM and UTAUT for individuals, TOE and DOI for organisations.\n- UTAUT2 adds hedonic motivation, price value and habit for consumers.\n- Justify every added construct with literature; keep frameworks parsimonious.\n- Context matters in Ghana: facilitating conditions, cost, trust and social networks."}'::jsonb, 2650, 4, true)
  on conflict (id) do update set module_id = excluded.module_id, slug = excluded.slug, title = excluded.title, summary = excluded.summary, topics = excluded.topics, estimated_minutes = excluded.estimated_minutes, difficulty = excluded.difficulty, source = excluded.source, content = excluded.content, word_count = excluded.word_count, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2f801d40-66cd-5775-a6d7-53851c72778b', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'de883484-7983-505a-b991-69220db279f6', 'csit-601/literature-review/q01', 'mcq', 'understand', 'easy', 'Explain the purpose of a literature review', 'Which statement best describes the purpose of a postgraduate literature review?', null, null, '[{"id":"a","text":"To summarise every publication on the topic in chronological order"},{"id":"b","text":"To build a critical argument about existing knowledge that justifies and informs the study"},{"id":"c","text":"To demonstrate that the student has read at least fifty sources"},{"id":"d","text":"To copy definitions from textbooks"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2f801d40-66cd-5775-a6d7-53851c72778b', '{"option":"b"}'::jsonb, 'A literature review evaluates what is known, identifies gaps and positions the study, while also supplying theory and methodological guidance. Exhaustive summary, source counts and copied definitions do not achieve these purposes.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c1f9c6fe-ef54-509b-9df1-18126ca70cd0', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'de883484-7983-505a-b991-69220db279f6', 'csit-601/literature-review/q02', 'scenario', 'apply', 'medium', 'Apply Boolean logic to construct a search string', 'Which search string is constructed most appropriately?', 'A student wants articles on mobile money adoption by retailers or traders. Her concepts are the
technology (mobile money, mobile payments), the behaviour (adoption, acceptance) and the population
(retailers, traders, merchants).', null, '[{"id":"a","text":"mobile money OR adoption OR retailers"},{"id":"b","text":"(\"mobile money\" OR \"mobile payment*\") AND (adopt* OR accept*) AND (retailer* OR trader* OR merchant*)"},{"id":"c","text":"(\"mobile money\" AND \"mobile payment*\") AND (adopt* AND accept*) AND (retailer* AND trader*)"},{"id":"d","text":"mobile money NOT retailers"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c1f9c6fe-ef54-509b-9df1-18126ca70cd0', '{"option":"b"}'::jsonb, 'Synonyms within a concept should be joined with OR and concepts combined with AND. Joining everything with OR retrieves far too much, joining synonyms with AND demands every term in every record and retrieves too little, and NOT retailers excludes the target population.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('685a3dbe-fc08-5a4f-832e-2e15fcbe1cc5', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'de883484-7983-505a-b991-69220db279f6', 'csit-601/literature-review/q03', 'true_false', 'evaluate', 'medium', 'Evaluate reliance on a single search tool', 'Google Scholar alone is sufficient for a rigorous MSc literature search because it indexes all scholarly literature.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
