insert into public.question_keys (question_id, correct, explanation, model_answer) values ('685a3dbe-fc08-5a4f-832e-2e15fcbe1cc5', '{"value":false}'::jsonb, 'Google Scholar has broad coverage but its coverage and ranking are not transparent, and it does not guarantee comprehensiveness. Combining it with subject databases, open access aggregators and credible grey literature produces a more rigorous search.', null)
