insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f9b2f08f-341a-5132-b787-811f814c48ab', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'de883484-7983-505a-b991-69220db279f6', 'csit-601/literature-review/q04', 'matching', 'understand', 'medium', 'Distinguish types of literature review', 'Match each type of review to its description.', null, null, '{"left":[{"id":"l1","text":"Narrative review"},{"id":"l2","text":"Systematic review"},{"id":"l3","text":"Scoping review"},{"id":"l4","text":"Integrative review"}],"right":[{"id":"r1","text":"Broad, flexible overview that may be selective and hard to reproduce"},{"id":"r3","text":"Maps the extent and nature of research on a broad topic"},{"id":"r2","text":"Explicit protocol, defined criteria, comprehensive search and formal appraisal"},{"id":"r4","text":"Combines diverse study types to generate new frameworks or perspectives"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f9b2f08f-341a-5132-b787-811f814c48ab', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Review types differ in protocol, comprehensiveness and purpose. Most MSc dissertations use a narrative review strengthened by systematic searching and transparent selection.', null)
