insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0f18bb53-0861-578b-a31c-f52277eb78a7', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'de883484-7983-505a-b991-69220db279f6', 'csit-601/literature-review/q06', 'mcq', 'analyse', 'hard', 'Analyse how to refine a search returning too many results', 'A search returns tens of thousands of loosely related records. Which refinement is most appropriate first?', null, null, '[{"id":"a","text":"Read every record in order"},{"id":"b","text":"Add a further concept with AND, use phrase searching and apply relevant filters"},{"id":"c","text":"Replace AND with OR throughout"},{"id":"d","text":"Abandon databases and rely on news websites"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
