insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6783f086-580c-5ced-afd8-39f9f5086e5c', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'c7696ab0-8d8f-5df7-b77e-a6875fd5f6fd', 'csit-601/literature-review/q08', 'mcq', 'understand', 'easy', 'Identify source evaluation criteria', 'Which set of criteria forms the CRAAP test for evaluating sources?', null, null, '[{"id":"a","text":"Currency, Relevance, Authority, Accuracy, Purpose"},{"id":"b","text":"Cost, Reliability, Access, Availability, Popularity"},{"id":"c","text":"Citations, Reviews, Abstract, Author, Publisher"},{"id":"d","text":"Content, Readability, Appearance, Age, Price"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6783f086-580c-5ced-afd8-39f9f5086e5c', '{"option":"a"}'::jsonb, 'The CRAAP test asks about currency, relevance, authority, accuracy and purpose. The other lists contain factors such as popularity or appearance that do not indicate credibility.', null)
