insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('eff03206-3676-5ef9-ab7c-3bf29dda8107', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'c7696ab0-8d8f-5df7-b77e-a6875fd5f6fd', 'csit-601/literature-review/q09', 'scenario', 'evaluate', 'hard', 'Evaluate a questionable journal', 'What is the most appropriate way to treat this source?', 'A student finds an article supporting his hypothesis in a journal that accepted it within five days,
charged a high publication fee, lists no editorial board and contains several statistical errors.', null, '[{"id":"a","text":"Cite it as strong evidence because it supports the hypothesis"},{"id":"b","text":"Exclude it or treat it with explicit caution because its authority and accuracy are doubtful"},{"id":"c","text":"Cite it only in the abstract"},{"id":"d","text":"Assume all open access journals are of this quality"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('eff03206-3676-5ef9-ab7c-3bf29dda8107', '{"option":"b"}'::jsonb, 'The signs suggest questionable publishing practices and the errors undermine accuracy. Agreement with a hypothesis is not evidence of quality, and many reputable open access journals exist, so the problem is this journal, not open access in general.', null)
