insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f09ca7e5-bb77-5533-bafe-926e0ec55013', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'c7696ab0-8d8f-5df7-b77e-a6875fd5f6fd', 'csit-601/literature-review/q10', 'matching', 'analyse', 'medium', 'Classify research gaps', 'Match each observation to the type of research gap it represents.', null, null, '{"left":[{"id":"l1","text":"Most cybersecurity awareness studies use self-report rather than observed behaviour"},{"id":"l2","text":"Few studies examine AI adoption among Ghanaian SMEs outside Accra"},{"id":"l3","text":"Adoption models assume individual decisions although SME decisions may be collective"},{"id":"l4","text":"Studies disagree on whether perceived risk deters mobile payment use"}],"right":[{"id":"r1","text":"Methodological gap"},{"id":"r3","text":"Theoretical gap"},{"id":"r4","text":"Empirical or evidence gap"},{"id":"r2","text":"Contextual gap"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
