insert into public.question_keys (question_id, correct, explanation, model_answer) values ('addd0867-b2a8-5083-9112-d62bc67da52f', '{"answers":["retraction","retracted","retracting"]}'::jsonb, 'Retracted articles continue to be cited, so researchers should check the status of key sources on the publisher''s page or in databases before relying on them.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3d26b5c9-ff72-55db-a523-fe9fcc207ef7', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', 'c7696ab0-8d8f-5df7-b77e-a6875fd5f6fd', 'csit-601/literature-review/q14', 'mcq', 'evaluate', 'hard', 'Evaluate qualitative evidence fairly', 'A small qualitative study of Ghanaian market traders provides rich insight into privacy concerns about digital payments. How should it be evaluated?', null, null, '[{"id":"a","text":"Dismissed, because small samples are always weak evidence"},{"id":"b","text":"Evaluated by qualitative quality criteria and valued for contextual insight, while recognising it is not statistically generalisable"},{"id":"c","text":"Treated as proof that all Ghanaian traders share these concerns"},{"id":"d","text":"Used only to calculate prevalence percentages"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3d26b5c9-ff72-55db-a523-fe9fcc207ef7', '{"option":"b"}'::jsonb, 'Qualitative studies are judged by criteria such as credibility and transferability and provide depth that surveys cannot. They cannot support statistical generalisation or prevalence estimates, but they should not be dismissed.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8ee207a2-19ca-5e7b-8a27-b2b1a60a0899', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', '70eb8d1f-66cc-5f35-8a64-5653e434859e', 'csit-601/literature-review/q15', 'mcq', 'understand', 'easy', 'Distinguish synthesis from summary', 'Which best describes synthesis in a literature review?', null, null, '[{"id":"a","text":"Reporting the main points of one article in your own words"},{"id":"b","text":"Listing all sources in alphabetical order"},{"id":"c","text":"Integrating findings from multiple sources to identify patterns, contradictions and gaps and build an argument"},{"id":"d","text":"Quoting long passages from key authors"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8ee207a2-19ca-5e7b-8a27-b2b1a60a0899', '{"option":"c"}'::jsonb, 'Synthesis combines many sources to make claims no single source makes. The first option is summary, the second is a reference list, and long quotations replace analysis with other people''s words.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('15dd589a-6541-558e-b1b7-0467f720c75d', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', '70eb8d1f-66cc-5f35-8a64-5653e434859e', 'csit-601/literature-review/q16', 'scenario', 'analyse', 'medium', 'Diagnose author-centric writing', 'What is the main weakness of this paragraph?', 'A draft review reads: "Author A studied students and found low awareness. Author B studied staff and
found moderate awareness. Author C found training helped. Author D found victims were more careful."', null, '[{"id":"a","text":"It uses too few sources"},{"id":"b","text":"It is author-centric and descriptive, with no claim, comparison, evaluation or link to the study"},{"id":"c","text":"It should use direct quotations instead"},{"id":"d","text":"It should be organised chronologically"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('15dd589a-6541-558e-b1b7-0467f720c75d', '{"option":"b"}'::jsonb, 'The paragraph strings summaries together. A synthesised paragraph would make a claim about factors associated with awareness, compare populations, evaluate reliance on self-report and link to the study. More sources, quotations or chronology would not fix the problem.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e76701cf-1f79-5737-935d-f6b28e29cb30', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', '70eb8d1f-66cc-5f35-8a64-5653e434859e', 'csit-601/literature-review/q17', 'matching', 'understand', 'medium', 'Identify elements of a synthesis paragraph', 'Match each element of the Claim, Evidence, Analysis, Link structure to its function.', null, null, '{"left":[{"id":"l1","text":"Claim"},{"id":"l2","text":"Evidence"},{"id":"l3","text":"Analysis"},{"id":"l4","text":"Link"}],"right":[{"id":"r3","text":"Compares sources, explains differences and evaluates quality"},{"id":"r2","text":"Cites several sources that support or complicate the point"},{"id":"r1","text":"States a point about the body of literature"},{"id":"r4","text":"Connects the point to the current study or the next section"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e76701cf-1f79-5737-935d-f6b28e29cb30', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'The structure ensures each paragraph argues rather than describes, and always shows the relevance of the literature to the study.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4c9ca908-e9ad-57be-bfb8-e6803a05016f', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', '70eb8d1f-66cc-5f35-8a64-5653e434859e', 'csit-601/literature-review/q18', 'true_false', 'understand', 'easy', 'Understand critical writing', 'Critical writing in a literature review means mainly pointing out the faults of other authors.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4c9ca908-e9ad-57be-bfb8-e6803a05016f', '{"value":false}'::jsonb, 'Critical writing means making reasoned, balanced judgements about evidence, recognising strengths as well as weaknesses, explaining disagreement and drawing conclusions.', null)
