insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0450be1e-c68d-59a1-92d7-3a2fbb5de23d', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', '70eb8d1f-66cc-5f35-8a64-5653e434859e', 'csit-601/literature-review/q19', 'short_answer', 'recall', 'easy', 'Recall the tool that organises sources by concept', 'What table, with sources as rows and concepts or themes as columns, helps reveal patterns across studies?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0450be1e-c68d-59a1-92d7-3a2fbb5de23d', '{"answers":["synthesis matrix","concept matrix","literature matrix"]}'::jsonb, 'Reading down a column of a synthesis or concept matrix shows how a concept is treated across studies and which concepts are rarely examined together.', null)
