insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b145c315-f9ca-5ae5-97c3-798f265dcabe', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', '70eb8d1f-66cc-5f35-8a64-5653e434859e', 'csit-601/literature-review/q20', 'mcq', 'apply', 'medium', 'Choose accurate reporting verbs', 'A single small cross-sectional survey found an association between training and safer passwords. Which reporting verb is most accurate?', null, null, '[{"id":"a","text":"The study proves that training causes safer passwords"},{"id":"b","text":"The study suggests that training is associated with safer password practices"},{"id":"c","text":"The study establishes beyond doubt that training works"},{"id":"d","text":"The study confirms a universal law of security behaviour"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b145c315-f9ca-5ae5-97c3-798f265dcabe', '{"option":"b"}'::jsonb, '"Suggests" and "associated with" accurately convey tentative, correlational evidence. "Proves", "establishes beyond doubt" and "universal law" overstate what one cross-sectional study can show.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8c65aa71-25fe-56c8-afe0-a459134b02ad', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', '70eb8d1f-66cc-5f35-8a64-5653e434859e', 'csit-601/literature-review/q21', 'mcq', 'evaluate', 'hard', 'Evaluate review structures', 'For an MSc review of determinants of e-commerce adoption among small businesses, which structure is usually most effective?', null, null, '[{"id":"a","text":"Chronological, describing each study in order of publication"},{"id":"b","text":"Alphabetical by author surname"},{"id":"c","text":"Thematic, organised around determinants such as cost, skills and logistics"},{"id":"d","text":"Random, to avoid bias"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8c65aa71-25fe-56c8-afe0-a459134b02ad', '{"option":"c"}'::jsonb, 'A thematic structure supports concept-centric synthesis and maps directly onto the conceptual framework. Chronological reviews risk description, and alphabetical or random ordering has no analytical logic.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4adbf5c7-5601-5e1a-afc1-811e6b5736b2', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', '71359625-959c-5565-bb05-27721d982ebc', 'csit-601/literature-review/q22', 'mcq', 'understand', 'medium', 'Distinguish theoretical and conceptual frameworks', 'What is the key difference between a theoretical framework and a conceptual framework?', null, null, '[{"id":"a","text":"There is no difference; the terms are interchangeable"},{"id":"b","text":"The theoretical framework is existing theory used as a lens; the conceptual framework is the researcher''s adapted model of constructs and relationships for this study"},{"id":"c","text":"A conceptual framework is used only in qualitative research"},{"id":"d","text":"A theoretical framework must always be drawn as a diagram"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4adbf5c7-5601-5e1a-afc1-811e6b5736b2', '{"option":"b"}'::jsonb, 'Theory is borrowed; the conceptual framework is built for the specific study. Conceptual frameworks appear in both quantitative and qualitative work, and theoretical frameworks need not be diagrams.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('eddc6ac4-eb35-5553-a212-20ee8834cb5f', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', '71359625-959c-5565-bb05-27721d982ebc', 'csit-601/literature-review/q23', 'matching', 'recall', 'medium', 'Associate constructs with their theories', 'Match each construct to the theory in which it is a core construct.', null, null, '{"left":[{"id":"l1","text":"Perceived ease of use"},{"id":"l2","text":"Facilitating conditions"},{"id":"l3","text":"Trialability"},{"id":"l4","text":"Top management support as an organisational factor"}],"right":[{"id":"r2","text":"UTAUT"},{"id":"r3","text":"Diffusion of Innovations"},{"id":"r4","text":"Technology-Organisation-Environment framework"},{"id":"r1","text":"Technology Acceptance Model"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('eddc6ac4-eb35-5553-a212-20ee8834cb5f', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Misattributing constructs is a common examination error. TAM centres on usefulness and ease of use, UTAUT on four determinants including facilitating conditions, DOI on five innovation attributes, and TOE on technology, organisation and environment contexts.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a1c12f69-60ed-5a85-af7a-03af27a95d52', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', '71359625-959c-5565-bb05-27721d982ebc', 'csit-601/literature-review/q24', 'scenario', 'apply', 'medium', 'Select a theory appropriate to the level of analysis', 'Which theoretical approach fits best?', 'A researcher wants to explain why some SMEs in Greater Accra decide to adopt cloud accounting
software for the whole firm while others do not. The decision is usually made by the owner-manager
and depends on resources, competition and vendor support.', null, '[{"id":"a","text":"TAM alone, because it explains individual employee attitudes"},{"id":"b","text":"TOE, possibly combined with DOI, because the question concerns organisational adoption shaped by internal and external factors"},{"id":"c","text":"UTAUT2, because it was designed for consumer hedonic use"},{"id":"d","text":"No theory is needed for applied research"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a1c12f69-60ed-5a85-af7a-03af27a95d52', '{"option":"b"}'::jsonb, 'The unit of analysis is the firm, and the factors span organisation and environment, which TOE addresses; DOI adds innovation attributes. TAM and UTAUT2 explain individual acceptance, and applied research still requires theory.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('82b709fd-47fc-5c34-ae4f-450844f0755e', '2c1df771-f299-58d8-95a4-e55602e24536', '7e0d035c-2942-5869-b7bd-abc9eecba411', '71359625-959c-5565-bb05-27721d982ebc', 'csit-601/literature-review/q25', 'true_false', 'understand', 'easy', 'Recognise UTAUT moderators', 'In UTAUT, gender, age, experience and voluntariness of use are proposed as moderators of key relationships.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
