insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e944e63e-d8b7-5e29-a9ed-1553c6103332', '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'ee15617a-14dc-5130-9b4e-44ae0103b8d1', 'csit-601/sampling-and-data-collection/q22', 'matching', 'apply', 'medium', 'Match research needs to qualitative methods', 'Match each research need to the most suitable method.', null, null, '{"left":[{"id":"l1","text":"Understanding how one SME owner decided to adopt an AI chatbot"},{"id":"l2","text":"Seeing whether cashiers actually offer mobile money at the till"},{"id":"l3","text":"Establishing what a hospital''s e-records policy officially required"},{"id":"l4","text":"Exploring shared student norms about password sharing"}],"right":[{"id":"r2","text":"Non-participant observation"},{"id":"r3","text":"Document analysis"},{"id":"r1","text":"Semi-structured interview"},{"id":"r4","text":"Focus group"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e944e63e-d8b7-5e29-a9ed-1553c6103332', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Interviews suit individual decision processes, observation captures actual behaviour, documents show official positions and focus groups reveal shared norms through interaction. Combining them supports triangulation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e9f58eaa-1384-5004-9876-cb9d0b763697', '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'ee15617a-14dc-5130-9b4e-44ae0103b8d1', 'csit-601/sampling-and-data-collection/q23', 'short_answer', 'recall', 'easy', 'Recall the term for cross-checking with multiple sources', 'What term describes using multiple data sources, methods or investigators to cross-check and deepen understanding of a phenomenon?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e9f58eaa-1384-5004-9876-cb9d0b763697', '{"answers":["triangulation"]}'::jsonb, 'Triangulation, in Denzin''s typology, includes data, investigator, theory and methodological forms. In qualitative research it builds a fuller account rather than proving a single truth.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ac95c4b2-64de-585b-ac12-bcc24df04999', '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'ee15617a-14dc-5130-9b4e-44ae0103b8d1', 'csit-601/sampling-and-data-collection/q24', 'mcq', 'evaluate', 'hard', 'Evaluate conflicting evidence from interviews and observation', 'Nurses say in interviews that they always record observations in the EHR, but field observation shows frequent use of paper notes that are entered later. What is the best interpretation?', null, null, '[{"id":"a","text":"The interviews are worthless and should be discarded"},{"id":"b","text":"The observation was biased and should be ignored"},{"id":"c","text":"The divergence is a finding that suggests workarounds and should be explored further, for example in follow-up interviews"},{"id":"d","text":"Average the two sources to estimate EHR use"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ac95c4b2-64de-585b-ac12-bcc24df04999', '{"option":"c"}'::jsonb, 'Divergence between what people say and do is common in technology-use research and often reveals workarounds driven by workload or system problems. Neither source should be discarded; follow-up enquiry can explain the gap. Averaging qualitative accounts is meaningless.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3201cc47-486a-55b7-a83f-6a2baa359264', '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', null, 'csit-601/sampling-and-data-collection/q25', 'case_analysis', 'evaluate', 'hard', 'Design and justify a sampling and data collection plan', 'Critically evaluate the proposed sampling and data collection plan and propose a revised, justified plan.', null, 'Illustrative scenario. A student plans to study digital payment adoption among retailers in three large
markets in Accra, Kumasi and Tamale. No list of traders exists. Her proposal says: "A random sample of
400 traders will be selected by approaching traders as they arrive at the market. A questionnaire in
English will be used. Twenty interviews will be conducted with traders the researcher knows personally
to explain the results." Her supervisor asks her to revise the plan.', null, 20, array['Identify the actual sampling methods used and why "random" is incorrect', 'Discuss frame, coverage and selection biases', 'Evaluate the language and mode of the questionnaire', 'Evaluate the qualitative sample and its link to the survey', 'Propose a revised sampling design (for example, cluster and systematic sampling of stalls)', 'Justify sample size and response-rate assumptions', 'Address ethics and data protection']::text[], '[{"criterion":"Diagnosis of sampling problems","marks":5,"descriptor":"Correctly identifies convenience sampling, absence of a frame and resulting biases."},{"criterion":"Instrument and mode evaluation","marks":4,"descriptor":"Addresses language, literacy, translation and piloting."},{"criterion":"Revised sampling plan","marks":6,"descriptor":"Proposes a feasible probability-approximating design with clear steps and sample size reasoning."},{"criterion":"Qualitative strand and integration","marks":3,"descriptor":"Proposes purposive selection of interviewees linked to survey results."},{"criterion":"Ethics and presentation","marks":2,"descriptor":"Mentions consent, confidentiality and data protection; clear structure."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3201cc47-486a-55b7-a83f-6a2baa359264', '{}'::jsonb, 'Examiners look for precise naming of methods and biases, a realistic alternative for a setting without a frame, numerical reasoning about sample size, and attention to language and ethics.', 'The proposal mislabels its method. Approaching traders as they arrive is convenience sampling, not random
sampling, because selection probabilities are unknown and early-arriving traders may differ systematically
(for example, wholesalers or full-time traders). Without a frame, coverage cannot be assessed. Interviewing
traders the researcher knows personally adds selection bias and risks socially desirable answers.

The English-only questionnaire may exclude traders more comfortable in Twi, Ga, Dagbani or other languages,
creating non-response and measurement error. Translation with independent back-translation, enumerator
administration and piloting with traders in each market are needed.

A revised plan would construct an area-based frame. In each market, sections or rows would be mapped and a
random sample of sections (clusters) selected; within each selected section, every kth occupied stall would be
chosen after a random start, approximating probability sampling. Allocation across the three markets could be
proportional to estimated stall counts or equal if comparison between cities is the aim. Using Cochran''s
formula with p = 0.5 and ±5% gives about 385 completed responses, which should be inflated for a design effect
because traders in the same section are similar, and further adjusted for the expected response rate from the pilot.

For the qualitative strand, an explanatory sequential design would purposively select interviewees from survey
respondents, for example adopters and non-adopters in each market and unexpected cases, until saturation.
Informed consent, anonymity, secure storage and compliance with the Data Protection Act, 2012 (Act 843) should
be stated, together with market association permission.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('176c0953-7e11-52b5-9ebb-564692ffa048', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', '2caa34eb-8822-5084-b243-05d2aff97977', 'What is coverage error?', 'Error that arises when the sampling frame omits or over-represents parts of the target population, for example a business association list that excludes informal firms.', 'supplementary', 'csit-601/sampling-and-data-collection/c5d5cb587a63', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('75a450dd-3a1c-5d49-8e9d-7fc7f667cfbb', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', '2caa34eb-8822-5084-b243-05d2aff97977', 'How do you compute a systematic sampling interval, and what must accompany it?', 'k = N / n, with a random start between 1 and k; check the list has no periodic pattern matching k.', 'supplementary', 'csit-601/sampling-and-data-collection/785b42dad944', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c54f4435-9c8b-55dd-ad3c-f9981472d120', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', '2caa34eb-8822-5084-b243-05d2aff97977', 'Why does cluster sampling usually need a larger sample than simple random sampling?', 'Cases within a cluster tend to be similar, so each extra case adds less new information; the loss is captured by the design effect.', 'supplementary', 'csit-601/sampling-and-data-collection/ea54eea564f5', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5d7d418d-aefa-5972-ae86-fe305464dc21', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', '2caa34eb-8822-5084-b243-05d2aff97977', 'When is a non-probability sample the right choice rather than a weakness?', 'When the aim is depth, exploration or theory building, or when no frame exists; the error is to report it as if it were representative.', 'supplementary', 'csit-601/sampling-and-data-collection/b674ee32570f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9c0a5f99-e080-5894-9183-df2005452a1b', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', '2caa34eb-8822-5084-b243-05d2aff97977', 'What does the 1936 Literary Digest poll teach about sampling?', 'A huge sample from a biased frame (telephone and car-owner lists) plus non-response produced a wrong prediction; size cannot fix bias.', 'supplementary', 'csit-601/sampling-and-data-collection/c08af981a773', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('84b00b3e-f488-53dd-bc42-5860de3e1c06', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'dd375ecc-26d4-552c-9b11-fc0711c174e8', 'State Cochran''s formula for a proportion and its usual conservative inputs.', 'n0 = z²pq / e²; with z = 1.96, p = 0.5 and e = 0.05, n0 = 384.16, rounded up to 385.', 'supplementary', 'csit-601/sampling-and-data-collection/314f89334163', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('371ec153-1c62-5373-86fa-f4fa8e4a2d4b', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'dd375ecc-26d4-552c-9b11-fc0711c174e8', 'What does the finite population correction do, and when does it matter?', 'n = n0 / (1 + (n0 − 1)/N) reduces the required sample when n0 is a noticeable fraction of a small known population; for very large N it changes little.', 'supplementary', 'csit-601/sampling-and-data-collection/c5c00160df72', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ea6914de-96eb-52ef-a4e2-126f85de48bc', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'dd375ecc-26d4-552c-9b11-fc0711c174e8', 'Is the calculated sample size the number of questionnaires to distribute?', 'No. It is the number of usable responses; divide by the expected response rate (for example 292 / 0.6 = 487) to find how many to approach.', 'supplementary', 'csit-601/sampling-and-data-collection/4d54ce768db5', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('90f34fe4-812d-58a6-89e2-e98a7ba6d92a', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'dd375ecc-26d4-552c-9b11-fc0711c174e8', 'How does the margin of error change if you quadruple the sample size?', 'It halves, because the margin of error is proportional to 1 / √n.', 'supplementary', 'csit-601/sampling-and-data-collection/6cafb44cfa44', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bc6696b9-6743-52ec-a258-b59061842962', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'dd375ecc-26d4-552c-9b11-fc0711c174e8', 'How should a qualitative study justify its sample size?', 'Through saturation (tracking new codes per interview), information power and the analytic approach, with transparent stopping criteria.', 'supplementary', 'csit-601/sampling-and-data-collection/887e62133519', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('877a04ae-89e4-5128-887d-397cf0f4dfed', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'ddc75327-fcb0-53ee-8835-f576de8b6df0', 'What is a double-barrelled question, and how do you fix it?', 'An item that asks about two things at once, such as "fast and secure"; split it into two separate items.', 'supplementary', 'csit-601/sampling-and-data-collection/b276ee96f4bd', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a68320a2-77fb-5840-9eb3-a8a1993872b6', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'ddc75327-fcb0-53ee-8835-f576de8b6df0', 'Why collect variables at the highest sensible level of measurement?', 'Ratio data (exact employee count) can later be grouped into categories, but categorical data cannot be converted back into exact values.', 'supplementary', 'csit-601/sampling-and-data-collection/4063ac7e9587', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('951ac8de-41d1-5948-97e9-dc32b8662d88', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'ddc75327-fcb0-53ee-8835-f576de8b6df0', 'Give Cronbach''s alpha formula and what it does not show.', 'α = (k/(k−1)) × (1 − Σ item variances / total variance). It shows internal consistency, not validity.', 'supplementary', 'csit-601/sampling-and-data-collection/0640b4d7523d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('85aadfbf-50a1-51e1-9c9c-29cbb05a2149', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'ddc75327-fcb0-53ee-8835-f576de8b6df0', 'How do you reverse-code a negatively worded item on a five-point scale?', 'Use 6 − x, so 1 becomes 5, 2 becomes 4, and so on, before computing scale scores.', 'supplementary', 'csit-601/sampling-and-data-collection/6a4ad2d33a60', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('fa17091c-5de5-54aa-8666-51634cc9de18', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'ddc75327-fcb0-53ee-8835-f576de8b6df0', 'What should a good pilot test produce?', 'Evidence on clarity, completion time, routing and reliability from respondents like the target population, plus a documented list of changes.', 'supplementary', 'csit-601/sampling-and-data-collection/ee0286cf7db1', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4e6f8732-1878-5ec5-85db-2dd57f7fa686', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'ee15617a-14dc-5130-9b4e-44ae0103b8d1', 'Why use "Tell me about the last time..." questions in interviews?', 'They elicit concrete episodes rather than generalisations or idealised accounts, giving richer and more credible data.', 'supplementary', 'csit-601/sampling-and-data-collection/36c08a240e62', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f6c2402b-e050-5d51-95dc-73a004cbc87b', null, '2c1df771-f299-58d8-95a4-e55602e24536', '39cf8f58-3e3c-55da-9e73-80a648f8a66b', 'ee15617a-14dc-5130-9b4e-44ae0103b8d1', 'Why separate staff by rank in focus groups?', 'Hierarchy encourages junior participants to defer or give socially desirable answers; homogeneous groups make honest discussion more likely.', 'supplementary', 'csit-601/sampling-and-data-collection/5dfbcd96d1b8', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
