insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('650c0d2d-1cae-5413-9bce-092bc4d145a0', '2c1df771-f299-58d8-95a4-e55602e24536', 'data-analysis', 'Data Analysis', 'Preparing, analysing, visualising and interpreting quantitative and qualitative data.', 6, true)
