insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('35d69013-9754-5847-bfb3-96be0e126657', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', '9c779fba-44a8-5603-aa20-5332ef223c38', 'csit-601/data-analysis/q01', 'short_answer', 'apply', 'easy', 'Calculate a median for an even-sized dataset', 'What is the median of the values 9, 11, 12, 12, 13, 14, 15, 16, 18, 20?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('35d69013-9754-5847-bfb3-96be0e126657', '{"answers":["13.5"]}'::jsonb, 'With ten ordered values, the median is the average of the 5th and 6th values, (13 + 14) / 2 = 13.5. Forgetting to order the data first, or picking only one middle value, are common errors.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ff9bac97-c91c-51ce-a108-9635f4bee61b', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', '9c779fba-44a8-5603-aa20-5332ef223c38', 'csit-601/data-analysis/q02', 'mcq', 'apply', 'medium', 'Calculate a sample standard deviation', 'For a sample of 10 values, the sum of squared deviations from the mean is 100. What is the sample standard deviation?', null, null, '[{"id":"a","text":"10.00"},{"id":"b","text":"3.33"},{"id":"c","text":"3.16"},{"id":"d","text":"11.11"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ff9bac97-c91c-51ce-a108-9635f4bee61b', '{"option":"b"}'::jsonb, 'Sample variance = 100 / (n − 1) = 100 / 9 = 11.11, and SD = √11.11 = 3.33. 11.11 is the variance, not the SD; 3.16 results from dividing by n instead of n − 1; 10.00 is the square root of the sum itself.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9e41bc32-441c-5edb-816b-9e81694fe330', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', '9c779fba-44a8-5603-aa20-5332ef223c38', 'csit-601/data-analysis/q03', 'true_false', 'understand', 'easy', 'Understand the effect of undeclared missing-value codes', 'If the code 99 is used for "no response" on a five-point scale but is not declared as missing in the software, the mean of that item will be inflated.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9e41bc32-441c-5edb-816b-9e81694fe330', '{"value":true}'::jsonb, 'The software treats 99 as a genuine score, so even a few such cases pull the mean far above the possible maximum of 5. Missing-value codes must be declared, and range checks should flag impossible values.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6ee6e7d4-8461-5f28-a7ad-4c7f65f39cc2', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', '9c779fba-44a8-5603-aa20-5332ef223c38', 'csit-601/data-analysis/q04', 'scenario', 'analyse', 'medium', 'Choose an appropriate summary for skewed data', 'Which summary is most appropriate as the main description of a typical retailer?', 'A researcher summarises monthly mobile money transaction values for 200 small retailers. Most retailers
process modest amounts, but a few wholesalers process very large sums. The histogram shows a long
tail to the right, and the mean is much larger than the median.', null, '[{"id":"a","text":"The mean and standard deviation only"},{"id":"b","text":"The median and interquartile range, with the mean also reported"},{"id":"c","text":"The mode only"},{"id":"d","text":"The range only"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6ee6e7d4-8461-5f28-a7ad-4c7f65f39cc2', '{"option":"b"}'::jsonb, 'The distribution is positively skewed, so a few large values pull the mean upwards. The median and IQR describe the typical case and spread robustly; reporting the mean as well keeps the summary transparent. The mode and range alone are too limited for interval data.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4e97e504-e367-5c96-a956-8ef9ba66c35c', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', '9c779fba-44a8-5603-aa20-5332ef223c38', 'csit-601/data-analysis/q05', 'matching', 'understand', 'medium', 'Match data preparation checks to the errors they detect', 'Match each data preparation check to the problem it is designed to detect.', null, null, '{"left":[{"id":"l1","text":"Range check"},{"id":"l2","text":"Consistency check"},{"id":"l3","text":"Duplicate check"},{"id":"l4","text":"Double entry of a subset"}],"right":[{"id":"r3","text":"The same online submission received twice"},{"id":"r1","text":"A value of 7 on a five-point scale"},{"id":"r4","text":"The error rate of manual typing from paper questionnaires"},{"id":"r2","text":"A non-user of mobile money reporting weekly mobile money transactions"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4e97e504-e367-5c96-a956-8ef9ba66c35c', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each check targets a different kind of error. Range checks catch impossible values, consistency checks catch logically incompatible answers, duplicate checks catch repeated submissions, and double entry estimates data entry accuracy.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('225a031b-70fb-5990-95f0-371b3968c866', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', '9c779fba-44a8-5603-aa20-5332ef223c38', 'csit-601/data-analysis/q06', 'mcq', 'evaluate', 'hard', 'Evaluate how to handle a genuine outlier', 'A survey of micro-enterprises includes one verified firm with far higher revenue than all others. What is the most defensible handling?', null, null, '[{"id":"a","text":"Delete it silently because it distorts the mean"},{"id":"b","text":"Change its value to the sample maximum of the other firms"},{"id":"c","text":"Keep it, report robust statistics such as the median, and show results with and without it where it matters"},{"id":"d","text":"Replace the whole revenue variable with the mode"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('225a031b-70fb-5990-95f0-371b3968c866', '{"option":"c"}'::jsonb, 'A verified value is genuine data, so deleting or altering it without disclosure misrepresents the sample. Robust statistics and a sensitivity check (with and without the case) let readers judge its influence. Replacing values with the mode destroys information.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8fcefd88-db4b-554b-b731-5addb481299f', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'ebf3fcf1-e670-587a-94f2-4f790074f018', 'csit-601/data-analysis/q07', 'mcq', 'understand', 'medium', 'Interpret a p-value correctly', 'A study reports p = 0.03 for a difference between two groups. Which interpretation is correct?', null, null, '[{"id":"a","text":"There is a 3% probability that the null hypothesis is true"},{"id":"b","text":"There is a 97% probability that the research hypothesis is true"},{"id":"c","text":"If the null hypothesis and model assumptions were true, results at least this extreme would occur about 3% of the time"},{"id":"d","text":"The effect is large and practically important"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8fcefd88-db4b-554b-b731-5addb481299f', '{"option":"c"}'::jsonb, 'A p-value is computed assuming H0 is true; it is not the probability of H0 or of the research hypothesis. It also says nothing about effect size or importance, as the ASA''s 2016 statement emphasises.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('956f49c4-5115-5397-bfe2-22efcaed71b4', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'ebf3fcf1-e670-587a-94f2-4f790074f018', 'csit-601/data-analysis/q08', 'short_answer', 'apply', 'medium', 'Calculate a standard error of the mean', 'A sample of 64 SMEs has a standard deviation of 1.2 on an AI-readiness scale. What is the standard error of the mean?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('956f49c4-5115-5397-bfe2-22efcaed71b4', '{"answers":["0.15",".15"]}'::jsonb, 'SE = s / √n = 1.2 / √64 = 1.2 / 8 = 0.15. The SE measures how much the sample mean would vary from sample to sample, and it is the basis for confidence intervals and t-tests.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('64b06cd4-bc3b-5492-af99-ac5e030b86da', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'ebf3fcf1-e670-587a-94f2-4f790074f018', 'csit-601/data-analysis/q09', 'scenario', 'apply', 'medium', 'Select an appropriate statistical test', 'Which test is most appropriate?', 'A researcher wants to know whether gender (male or female) is associated with whether university
students reuse passwords across accounts (yes or no). She has responses from 250 students.', null, '[{"id":"a","text":"Independent-samples t-test"},{"id":"b","text":"Pearson correlation"},{"id":"c","text":"Chi-square test of independence"},{"id":"d","text":"Paired-samples t-test"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('64b06cd4-bc3b-5492-af99-ac5e030b86da', '{"option":"c"}'::jsonb, 'Both variables are nominal, so a chi-square test of independence is appropriate (Fisher''s exact test if expected frequencies are small). t-tests need an interval outcome, Pearson correlation needs two interval variables, and a paired test needs repeated measures of the same people.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e08f265b-35b1-5eec-b06c-bacc46d186d5', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'ebf3fcf1-e670-587a-94f2-4f790074f018', 'csit-601/data-analysis/q10', 'true_false', 'understand', 'easy', 'Understand non-significant results', 'A non-significant result (p = 0.20) proves that there is no difference between the groups in the population.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e08f265b-35b1-5eec-b06c-bacc46d186d5', '{"value":false}'::jsonb, 'Failing to reject H0 means the data are not sufficiently incompatible with it. The study may have lacked power to detect a real effect. Confidence intervals show which effect sizes remain plausible.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d6e9f53f-ef80-5f61-ba37-56bd6241e252', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'ebf3fcf1-e670-587a-94f2-4f790074f018', 'csit-601/data-analysis/q11', 'matching', 'understand', 'medium', 'Match inferential concepts to their definitions', 'Match each concept to its definition.', null, null, '{"left":[{"id":"l1","text":"Type I error"},{"id":"l2","text":"Type II error"},{"id":"l3","text":"Power"},{"id":"l4","text":"Effect size"},{"id":"l5","text":"Confidence interval"}],"right":[{"id":"r2","text":"Failing to reject a null hypothesis that is actually false"},{"id":"r3","text":"Probability of detecting an effect that truly exists"},{"id":"r1","text":"Rejecting a null hypothesis that is actually true"},{"id":"r5","text":"Range of plausible values for a population parameter"},{"id":"r4","text":"Magnitude of a difference or relationship"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d6e9f53f-ef80-5f61-ba37-56bd6241e252', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Type I errors are false positives (probability α) and Type II errors are false negatives (probability β). Power is 1 − β. Effect sizes and confidence intervals complement p-values by conveying magnitude and precision.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e5ae6e4e-8b4f-51f4-b8aa-83db66bfb21b', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'ebf3fcf1-e670-587a-94f2-4f790074f018', 'csit-601/data-analysis/q12', 'mcq', 'analyse', 'hard', 'Calculate and interpret a chi-square statistic', 'In a 2 × 2 table, the four (O − E)²/E contributions are 2.70, 0.85, 1.80 and 0.57. With df = 1 and a critical value of 3.84 at α = 0.05, what is the conclusion?', null, null, '[{"id":"a","text":"χ² = 5.92; reject H0, the variables are associated"},{"id":"b","text":"χ² = 5.92; fail to reject H0"},{"id":"c","text":"χ² = 1.48; fail to reject H0"},{"id":"d","text":"χ² = 5.92; the result proves one variable causes the other"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e5ae6e4e-8b4f-51f4-b8aa-83db66bfb21b', '{"option":"a"}'::jsonb, 'χ² is the sum of contributions, 2.70 + 0.85 + 1.80 + 0.57 = 5.92, which exceeds 3.84, so H0 of no association is rejected. 1.48 is the mean contribution, not the statistic. A chi-square test on observational data shows association, not causation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0ad1cf05-2162-5f43-867d-55e9a3309530', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'df7aa797-5ebc-5421-a071-6ad821d46c0c', 'csit-601/data-analysis/q13', 'mcq', 'understand', 'easy', 'Interpret the coefficient of determination', 'Pearson''s correlation between perceived usefulness and intention to use an AI tool is r = 0.60. What proportion of variance do they share?', null, null, '[{"id":"a","text":"60%"},{"id":"b","text":"36%"},{"id":"c","text":"6%"},{"id":"d","text":"77%"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0ad1cf05-2162-5f43-867d-55e9a3309530', '{"option":"b"}'::jsonb, 'Shared variance is r² = 0.60² = 0.36, or 36%. Treating r itself as a percentage is a common error; 77% would be √0.60, which has no meaning here.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0beb6c70-5a6e-5be6-9b3f-88cd21e77e1b', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'df7aa797-5ebc-5421-a071-6ad821d46c0c', 'csit-601/data-analysis/q14', 'short_answer', 'apply', 'medium', 'Calculate a regression slope', 'If Σ(x − x̄)(y − ȳ) = 6 and Σ(x − x̄)² = 10, what is the regression slope b?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0beb6c70-5a6e-5be6-9b3f-88cd21e77e1b', '{"answers":["0.6",".6"]}'::jsonb, 'b = Σ(x − x̄)(y − ȳ) / Σ(x − x̄)² = 6 / 10 = 0.6. Each one-unit increase in x is associated with a 0.6-unit increase in predicted y. The intercept is then a = ȳ − b × x̄.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4e156ae5-e056-542c-9e51-9ef477da51af', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'df7aa797-5ebc-5421-a071-6ad821d46c0c', 'csit-601/data-analysis/q15', 'scenario', 'analyse', 'hard', 'Interpret a multiple regression coefficient', 'Which interpretation of the perceived usefulness coefficient is most accurate?', 'A regression of operational efficiency (1-5) on perceived usefulness (1-5), facilitating conditions
(1-5) and firm age (years) for 180 SMEs gives, for perceived usefulness, B = 0.42, SE = 0.07,
β = 0.39, t = 6.00, p < .001. R² = 0.31.', null, '[{"id":"a","text":"Perceived usefulness causes a 42% increase in efficiency"},{"id":"b","text":"Holding the other predictors constant, a one-point increase in perceived usefulness is associated with a 0.42-point increase in efficiency"},{"id":"c","text":"Perceived usefulness explains 39% of the variance in efficiency"},{"id":"d","text":"The coefficient is not significant because R² is below 0.5"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4e156ae5-e056-542c-9e51-9ef477da51af', '{"option":"b"}'::jsonb, 'B is in the outcome''s units and is interpreted holding other predictors constant. It is not a percentage and does not establish causation from cross-sectional data. β is a standardised coefficient, not variance explained, and R² does not determine the significance of individual predictors.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('72a0377e-1cff-5b85-8691-d01e3abb1ae8', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'df7aa797-5ebc-5421-a071-6ad821d46c0c', 'csit-601/data-analysis/q16', 'true_false', 'understand', 'medium', 'Understand the limits of Pearson''s r', 'A Pearson correlation close to zero shows that two variables have no relationship of any kind.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('72a0377e-1cff-5b85-8691-d01e3abb1ae8', '{"value":false}'::jsonb, 'Pearson''s r measures linear association only. A strong curved relationship can produce r near zero, which is why scatter plots should always be inspected, as Anscombe''s quartet demonstrates.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e9261ae9-eb97-5e1d-848e-d2581d972ac1', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'df7aa797-5ebc-5421-a071-6ad821d46c0c', 'csit-601/data-analysis/q17', 'matching', 'understand', 'medium', 'Match regression output elements to their meaning', 'Match each regression output element to its meaning.', null, null, '{"left":[{"id":"l1","text":"R²"},{"id":"l2","text":"Adjusted R²"},{"id":"l3","text":"F-test"},{"id":"l4","text":"Standardised beta"},{"id":"l5","text":"Variance inflation factor"}],"right":[{"id":"r5","text":"Diagnostic for multicollinearity among predictors"},{"id":"r2","text":"Explained variance penalised for unnecessary predictors"},{"id":"r4","text":"Change in the outcome in standard deviations per standard deviation of a predictor"},{"id":"r3","text":"Whether the model as a whole explains significant variance"},{"id":"r1","text":"Proportion of variance in the outcome explained by the model"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e9261ae9-eb97-5e1d-848e-d2581d972ac1', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Reading a regression output requires distinguishing model-level statistics (R², adjusted R², F) from predictor-level statistics (B, β, t, p) and diagnostics (VIF).', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('df4e5f95-f993-5f26-9aec-adaf18b0a605', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'df7aa797-5ebc-5421-a071-6ad821d46c0c', 'csit-601/data-analysis/q18', 'mcq', 'evaluate', 'hard', 'Evaluate the lesson of Google Flu Trends', 'What is the most important methodological lesson of the Google Flu Trends failure for correlational research?', null, null, '[{"id":"a","text":"Large datasets always produce accurate predictions"},{"id":"b","text":"Predictors chosen only because they correlate historically can capture spurious or unstable patterns, so models need theory and validation on new data"},{"id":"c","text":"Search data should never be used in research"},{"id":"d","text":"Regression cannot be used for prediction"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('df4e5f95-f993-5f26-9aec-adaf18b0a605', '{"option":"b"}'::jsonb, 'The model relied on search terms that correlated with past flu data, some for spurious or seasonal reasons, and the relationships shifted when search behaviour and algorithms changed. Size did not protect against these problems. The lesson is about theory, stability and validation, not a ban on data sources or regression.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8bc84451-7fe0-548f-a6f7-4e32fd73c372', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c48bea74-0c82-5f39-9f75-afa7b35e98d5', 'csit-601/data-analysis/q19', 'mcq', 'recall', 'easy', 'Recall the first phase of Braun and Clarke''s thematic analysis', 'According to Braun and Clarke (2006), what is the first phase of thematic analysis?', null, null, '[{"id":"a","text":"Generating initial codes"},{"id":"b","text":"Familiarising yourself with the data"},{"id":"c","text":"Searching for themes"},{"id":"d","text":"Defining and naming themes"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8bc84451-7fe0-548f-a6f7-4e32fd73c372', '{"option":"b"}'::jsonb, 'Familiarisation (transcribing or checking transcripts, reading and re-reading, noting initial ideas) comes first. Coding, searching for themes, reviewing, defining and naming, and reporting follow, with movement back and forth between phases.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f151f31f-616c-5c98-ac43-92b5e21d8859', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c48bea74-0c82-5f39-9f75-afa7b35e98d5', 'csit-601/data-analysis/q20', 'true_false', 'understand', 'medium', 'Distinguish themes from topic summaries', 'Organising findings into one "theme" per interview question (for example, "Theme 1 - Training") is good practice in thematic analysis.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f151f31f-616c-5c98-ac43-92b5e21d8859', '{"value":false}'::jsonb, 'Grouping answers by question produces topic summaries, not themes. A theme is a pattern of shared meaning with a central organising concept that cuts across questions, such as "Training as a ritual rather than a resource".', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('88856d71-957b-59ba-b107-228c04696cf3', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c48bea74-0c82-5f39-9f75-afa7b35e98d5', 'csit-601/data-analysis/q21', 'short_answer', 'recall', 'easy', 'Recall the term for codes using participants'' own words', 'What type of code uses a participant''s own words, such as "the system sleeps", as its label?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('88856d71-957b-59ba-b107-228c04696cf3', '{"answers":["in vivo","in vivo code","in-vivo"]}'::jsonb, 'In vivo codes preserve participants'' language and meanings, which can make themes more vivid and grounded. They are often combined with descriptive, process and interpretive codes.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4df82c9c-56bc-5673-a3ac-11e7a94d9da8', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c48bea74-0c82-5f39-9f75-afa7b35e98d5', 'csit-601/data-analysis/q22', 'scenario', 'apply', 'medium', 'Apply a hybrid coding approach', 'What should the student do with these data?', 'A student uses UTAUT constructs as initial codes to analyse interviews with nurses about an EHR system.
Several nurses describe relying on a senior colleague''s informal "night-shift tips" rather than
formal training, an issue that does not fit neatly into any UTAUT code.', null, '[{"id":"a","text":"Discard them because they do not fit the theory"},{"id":"b","text":"Force them into the effort expectancy code"},{"id":"c","text":"Create a new inductive code and consider whether it extends or challenges the theoretical framework"},{"id":"d","text":"Count them and report a percentage"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4df82c9c-56bc-5673-a3ac-11e7a94d9da8', '{"option":"c"}'::jsonb, 'A hybrid approach combines deductive codes from theory with inductive codes for unanticipated issues. Data that do not fit the framework may represent a contribution, for example extending facilitating conditions to include informal peer support. Discarding or forcing data undermines credibility.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f66cdcde-62ad-57a6-9c40-b856c308b361', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c48bea74-0c82-5f39-9f75-afa7b35e98d5', 'csit-601/data-analysis/q23', 'matching', 'understand', 'medium', 'Match coding-frame components to their purpose', 'Match each coding-frame component to its purpose.', null, null, '{"left":[{"id":"l1","text":"Code name"},{"id":"l2","text":"Definition"},{"id":"l3","text":"Inclusion criteria"},{"id":"l4","text":"Exclusion criteria"},{"id":"l5","text":"Example extract"}],"right":[{"id":"r2","text":"Statement of what the code means"},{"id":"r1","text":"Short label used to tag segments"},{"id":"r5","text":"Illustration of a segment that fits the code"},{"id":"r3","text":"Conditions under which the code should be applied"},{"id":"r4","text":"Similar material that should not receive the code"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f66cdcde-62ad-57a6-9c40-b856c308b361', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'A complete coding frame supports consistent, transparent coding and forms part of the audit trail. Exclusion criteria are often omitted but are essential for distinguishing similar codes.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5c443ce3-47a2-5054-b5f2-003f026c8162', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c48bea74-0c82-5f39-9f75-afa7b35e98d5', 'csit-601/data-analysis/q24', 'mcq', 'evaluate', 'hard', 'Evaluate the use of inter-coder reliability in reflexive thematic analysis', 'A student using reflexive thematic analysis is asked by a reviewer to report Cohen''s kappa. What is the most defensible response?', null, null, '[{"id":"a","text":"Report kappa because it is required for all qualitative research"},{"id":"b","text":"Explain that reflexive thematic analysis treats coding as interpretive, so quality is shown through reflexivity, transparency and an audit trail rather than agreement statistics"},{"id":"c","text":"Refuse to discuss quality at all"},{"id":"d","text":"Replace the analysis with a word-frequency count"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5c443ce3-47a2-5054-b5f2-003f026c8162', '{"option":"b"}'::jsonb, 'Braun and Clarke argue that agreement measures assume a single correct coding, which conflicts with reflexive TA. Codebook approaches may legitimately report kappa, but a reflexive study should justify quality in terms consistent with its epistemology.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b88b4e08-1793-517a-a1ef-16af0f64118d', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c1fe119e-6383-5bc1-8180-84e88a492662', 'csit-601/data-analysis/q25', 'mcq', 'apply', 'easy', 'Select a chart type for a purpose', 'Which chart is most appropriate for showing the relationship between training hours and the number of security incidents across 150 bank branches?', null, null, '[{"id":"a","text":"Pie chart"},{"id":"b","text":"Scatter plot"},{"id":"c","text":"Stacked bar chart"},{"id":"d","text":"Line chart joining branches alphabetically"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b88b4e08-1793-517a-a1ef-16af0f64118d', '{"option":"b"}'::jsonb, 'A scatter plot displays the relationship between two interval or ratio variables and reveals linearity, outliers and spread. Pie and stacked bar charts show composition, and a line joining unordered branches implies a sequence that does not exist.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7de39cb9-7fbf-5aa1-a37c-a2ce4319ff1f', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c1fe119e-6383-5bc1-8180-84e88a492662', 'csit-601/data-analysis/q26', 'short_answer', 'apply', 'medium', 'Calculate the visual distortion of a truncated axis', 'A bar chart''s axis starts at 60%. Bars show 62% and 68%. By what factor does the taller bar appear larger than the shorter one?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7de39cb9-7fbf-5aa1-a37c-a2ce4319ff1f', '{"answers":["4","four","4 times"]}'::jsonb, 'Visible heights are 68 − 60 = 8 and 62 − 60 = 2, so the taller bar looks 8 / 2 = 4 times larger, although the actual ratio is 68 / 62 ≈ 1.10. Bar charts should start at zero.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4bfc26b5-de50-5293-a6dc-dfe8bba91951', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c1fe119e-6383-5bc1-8180-84e88a492662', 'csit-601/data-analysis/q27', 'true_false', 'understand', 'easy', 'Distinguish results and discussion', 'The main purpose of a discussion chapter is to restate the results in more detail.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4bfc26b5-de50-5293-a6dc-dfe8bba91951', '{"value":false}'::jsonb, 'The discussion interprets results by linking them to research questions, literature and theory, considering alternative explanations, and stating implications and limitations. Restating results adds no interpretation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('23f47672-532f-5374-815f-97b006059c83', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c1fe119e-6383-5bc1-8180-84e88a492662', 'csit-601/data-analysis/q28', 'scenario', 'evaluate', 'hard', 'Evaluate an interpretation for over-claiming', 'What is the main weakness of the interpretation?', 'A dissertation reports that students who attended cybersecurity orientation scored 0.3 points higher
on a five-point awareness scale (d = 0.35, p = .004, n = 300). Attendance was voluntary. The student
recommends that "the university should make orientation compulsory because it causes higher awareness".', null, '[{"id":"a","text":"The p-value is too large to be significant"},{"id":"b","text":"The effect size is too large to be believable"},{"id":"c","text":"Voluntary attendance means self-selection could explain the difference, so the causal claim and recommendation overreach"},{"id":"d","text":"Sample size of 300 is too small for any conclusion"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('23f47672-532f-5374-815f-97b006059c83', '{"option":"c"}'::jsonb, 'More security-conscious students may have chosen to attend, so the association may not be causal. The result is significant, d = 0.35 is a plausible small-to-medium effect, and n = 300 is adequate. A better recommendation would be cautious and could propose a randomised or staggered evaluation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0f71ed33-023e-5243-a9a3-4b5b15be22e4', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c1fe119e-6383-5bc1-8180-84e88a492662', 'csit-601/data-analysis/q29', 'matching', 'apply', 'medium', 'Match results to suitable visualisations', 'Match each result to the most suitable visualisation.', null, null, '{"left":[{"id":"l1","text":"Distribution of monthly online sales for 120 SMEs"},{"id":"l2","text":"Responses to five Likert items on trust in digital payments"},{"id":"l3","text":"Monthly EHR log-ins over two years"},{"id":"l4","text":"Survey percentages beside interview themes"}],"right":[{"id":"r4","text":"Joint display"},{"id":"r1","text":"Histogram or box plot"},{"id":"r3","text":"Line chart"},{"id":"r2","text":"Diverging stacked bar chart"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0f71ed33-023e-5243-a9a3-4b5b15be22e4', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Chart choice follows the data type and message. Distributions need histograms or box plots, Likert items suit diverging bars, time series suit line charts, and mixed-methods integration suits joint displays.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8beecdea-d8a3-5ea3-b266-8cf6b2748c29', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'c1fe119e-6383-5bc1-8180-84e88a492662', 'csit-601/data-analysis/q30', 'mcq', 'analyse', 'medium', 'Analyse the visualisation lesson of the Challenger case', 'According to Tufte''s analysis of the Challenger O-ring charts, what was the key visual weakness?', null, null, '[{"id":"a","text":"The charts used too many colours"},{"id":"b","text":"The charts did not plot damage against temperature for all previous flights, including those without damage, obscuring the relationship"},{"id":"c","text":"The charts started the axis at zero"},{"id":"d","text":"The charts were drawn by hand"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8beecdea-d8a3-5ea3-b266-8cf6b2748c29', '{"option":"b"}'::jsonb, 'Tufte argued that showing only some flights, and not ordering evidence by temperature, hid the link between cold and O-ring damage. The general lesson is that selecting cases and choosing charts shapes what decision-makers see. Others emphasise organisational factors too.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e9b5eba3-78b8-577b-b485-995d444f2acd', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', null, 'csit-601/data-analysis/q31', 'case_analysis', 'evaluate', 'hard', 'Critically evaluate a quantitative results and discussion section', 'Critically evaluate the analysis, presentation and interpretation, and rewrite the conclusion appropriately.', null, 'Illustrative scenario. A dissertation on digital payment adoption among 210 retailers recruited by
convenience sampling in two Accra markets reports: "Trust was strongly correlated with intention to
accept merchant payments (r = 0.25, p < .001). Regression showed that trust (B = 0.30, p < .001) and
transaction cost (B = −0.20, p = .02) significantly impact intention (R² = 0.12). This proves that
improving trust will increase digital payment adoption across Ghana." A 3D pie chart shows
intention categories. Data were collected in English only, and 40 questionnaires with missing items
were deleted without comment.', null, 20, array['Evaluate the description of r = 0.25 as "strong" and interpret r²', 'Interpret the regression coefficients and R² correctly', 'Critique causal language and generalisation from a convenience sample', 'Evaluate data preparation issues (missing data, language)', 'Critique the visualisation and propose alternatives', 'Rewrite the conclusion with calibrated language']::text[], '[{"criterion":"Statistical interpretation","marks":6,"descriptor":"Correctly interprets r, r², B, p and R², noting the small explained variance."},{"criterion":"Causal and generalisation critique","marks":5,"descriptor":"Identifies the unjustified causal claim and the limits of a convenience sample."},{"criterion":"Data preparation critique","marks":3,"descriptor":"Addresses undocumented deletion of missing cases and language-related measurement issues."},{"criterion":"Visualisation critique","marks":3,"descriptor":"Explains problems with 3D pie charts and proposes a suitable chart."},{"criterion":"Revised conclusion","marks":3,"descriptor":"Provides a calibrated, accurate conclusion with limitations."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e9b5eba3-78b8-577b-b485-995d444f2acd', '{}'::jsonb, 'Examiners reward precise statistical interpretation, recognition of over-claiming, attention to data preparation and presentation, and a well-calibrated rewritten conclusion.', 'Describing r = 0.25 as "strong" is inaccurate; by Cohen''s guidelines it is a small-to-medium correlation,
and r² = 0.0625 means trust shares only about 6% of the variance in intention. The significance reflects
the sample size rather than strength. In the regression, B = 0.30 means a one-point increase in trust is
associated with a 0.30-point increase in intention, holding transaction cost constant, and B = −0.20 shows
that higher perceived cost is associated with lower intention. However, R² = 0.12 indicates that 88% of the
variance is unexplained, so other factors matter substantially.

The word "impact" and the claim that improving trust "will increase adoption" are causal claims that a
cross-sectional design cannot support: temporal order is unknown and unmeasured confounders such as
business size or customer base may explain the associations. Generalising "across Ghana" from a
convenience sample in two Accra markets is unjustified; p-values assume random sampling and should be
treated as indicative.

Deleting 40 cases (about 16% of 250) without comment risks bias if missingness relates to the variables,
for example less literate traders struggling with an English-only instrument. The student should report
missingness patterns and consider translated instruments in future.

The 3D pie chart distorts proportions and makes comparison hard; a simple horizontal bar chart with
percentages and n would be clearer.

A revised conclusion: "Among surveyed retailers in two Accra markets, higher trust and lower perceived
transaction costs were modestly associated with stronger intention to accept merchant payments, together
explaining 12% of its variance. Given the cross-sectional convenience sample, these findings are
indicative and should be tested with probability samples and longitudinal or experimental designs."')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('78562240-2733-5806-b563-6c4c079eefac', '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', null, 'csit-601/data-analysis/q32', 'essay', 'evaluate', 'hard', 'Plan an integrated mixed-methods analysis strategy', 'For a mixed-methods study of healthcare technology adoption in Ghanaian hospitals (a nurse survey plus interviews), propose and justify an analysis strategy covering data preparation, descriptive and inferential analysis, thematic analysis and integrated presentation of findings.', null, null, null, 20, array['Data preparation for survey data (codebook, cleaning, missing data, scale construction, reliability)', 'Descriptive statistics appropriate to each variable type', 'Inferential analyses aligned with hypotheses (for example, regression on UTAUT constructs) and assumption checks', 'Thematic analysis approach (reflexive or codebook, deductive or hybrid) and quality measures', 'Integration through a joint display and interpretation', 'Ethical handling of data and limitations']::text[], '[{"criterion":"Quantitative preparation and description","marks":4,"descriptor":"Covers coding, cleaning, missing data, reliability and appropriate descriptives."},{"criterion":"Inferential analysis","marks":5,"descriptor":"Selects tests aligned to hypotheses, checks assumptions and reports effect sizes and CIs."},{"criterion":"Qualitative analysis","marks":5,"descriptor":"Justifies a thematic analysis approach with clear phases and quality criteria."},{"criterion":"Integration and presentation","marks":4,"descriptor":"Explains joint displays and how divergence will be interpreted."},{"criterion":"Ethics, limitations and writing","marks":2,"descriptor":"Addresses data protection and limitations in clear academic prose."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('78562240-2733-5806-b563-6c4c079eefac', '{}'::jsonb, 'Examiners look for a coherent, justified sequence from preparation to integration, with analyses matched to data types and hypotheses, explicit quality criteria for both strands, and a clear integration strategy.', 'A strong answer begins with a codebook defining all survey variables, missing-value codes and UTAUT scale
items. Cleaning involves range, consistency and duplicate checks, logged in a cleaning record, with
missing data quantified and its pattern examined before choosing listwise deletion or imputation. Negatively
worded items are reverse-coded and scale scores computed as item means, with Cronbach''s alpha reported for
each construct.

Descriptive analysis would report frequencies and percentages for nominal variables such as hospital type,
medians for single Likert items, and means and SDs for scale scores, using histograms or box plots to check
distributions. Inferential analysis would test hypotheses with multiple regression of behavioural intention
or reported use on performance expectancy, effort expectancy, social influence and facilitating
conditions, controlling for experience and ward. Assumptions (linearity, homoscedasticity, normality of
residuals, multicollinearity via VIF, independence given clustering by ward) would be checked, and
results reported with B, β, CIs and R², using calibrated language.

For interviews, a hybrid reflexive thematic analysis following Braun and Clarke''s six phases would start
with UTAUT-informed codes but remain open to inductive codes such as informal peer support or paper
workarounds. Quality would be demonstrated through reflexive memos, a coding frame and an audit trail.

Integration would use a joint display aligning each UTAUT construct''s regression result with related
themes, classifying them as confirming, expanding or diverging. Divergence would be interpreted rather than
dismissed. Data would be pseudonymised and stored securely under the Data Protection Act, 2012 (Act 843),
and limitations such as self-report and cross-sectional design acknowledged.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bb501b82-c9a1-5153-b36d-70bc738ca908', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', '9c779fba-44a8-5603-aa20-5332ef223c38', 'Why should a codebook be written alongside the questionnaire rather than after data collection?', 'It fixes variable names, value codes, missing-value codes and measurement levels in advance, preventing inconsistent entry and making cleaning and scale construction systematic.', 'supplementary', 'csit-601/data-analysis/6076cf8df1c4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('7dd084f2-c569-5957-b580-e7bd93c19e11', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', '9c779fba-44a8-5603-aa20-5332ef223c38', 'Why divide by n − 1 when computing a sample variance?', 'It corrects the tendency of a sample to underestimate population variability, giving an unbiased estimate of the population variance.', 'supplementary', 'csit-601/data-analysis/ac09fa76d202', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b7c73293-4f29-5107-abee-adc2dc38335b', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', '9c779fba-44a8-5603-aa20-5332ef223c38', 'What does a single mistyped value (200 instead of 20) do to the mean and median of ten values?', 'In the worked example it raises the mean from 14.0 to 32.0 but leaves the median at 13.5, showing why range checks matter and why the median is robust.', 'supplementary', 'csit-601/data-analysis/145173511499', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('570f6411-c469-548d-9e22-fb8146e43daa', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', '9c779fba-44a8-5603-aa20-5332ef223c38', 'Which measures of centre and spread suit skewed interval data?', 'The median and interquartile range, with the mean reported alongside for transparency.', 'supplementary', 'csit-601/data-analysis/c28edcdae74f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('380d5197-d4df-5742-b505-4956e895cdcb', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', '9c779fba-44a8-5603-aa20-5332ef223c38', 'What is the main lesson of the Reinhart-Rogoff spreadsheet error for MSc students?', 'Coding and data-handling errors can change conclusions; keep raw data untouched, script or log every step, and be ready to share analysis files.', 'supplementary', 'csit-601/data-analysis/2255fee39bce', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8f677d4c-7617-553b-bf67-31c3bddd9bd6', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'ebf3fcf1-e670-587a-94f2-4f790074f018', 'What does a p-value actually measure?', 'The probability of results at least as extreme as those observed if the null hypothesis and model assumptions were true - not the probability that H0 is true.', 'supplementary', 'csit-601/data-analysis/f458c7c69e0e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6d9b3766-4fea-59e0-89db-fbf3714c3703', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'ebf3fcf1-e670-587a-94f2-4f790074f018', 'How do you compute an approximate 95% confidence interval for a mean?', 'x̄ ± 1.96 × SE, where SE = s / √n (use the t multiplier for small samples).', 'supplementary', 'csit-601/data-analysis/201080bfc85b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('82aa4a88-0bed-5c12-8b7c-3f97634f223e', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'ebf3fcf1-e670-587a-94f2-4f790074f018', 'Why should effect sizes be reported alongside p-values?', 'p-values depend heavily on sample size; effect sizes such as Cohen''s d show magnitude, which determines practical importance.', 'supplementary', 'csit-601/data-analysis/98a7111010ce', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f2e6db0a-c458-5b7d-9611-546ffea93660', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'ebf3fcf1-e670-587a-94f2-4f790074f018', 'How are expected frequencies calculated in a chi-square test of independence?', 'E = (row total × column total) / grand total for each cell; then χ² = Σ(O − E)² / E with df = (r − 1)(c − 1).', 'supplementary', 'csit-601/data-analysis/01230d70164e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1e73ab64-756a-5b63-9f9e-ab39caf3e475', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'ebf3fcf1-e670-587a-94f2-4f790074f018', 'Why is "fail to reject H0" preferred to "accept H0"?', 'A non-significant result may reflect low power; it shows the data are not sufficiently incompatible with H0, not that H0 is true.', 'supplementary', 'csit-601/data-analysis/d4bae2414708', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('10bac914-a13c-5e4b-9df7-b185c98c0e22', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'df7aa797-5ebc-5421-a071-6ad821d46c0c', 'What does r² tell you that r does not?', 'The proportion of variance shared by the two variables; r = 0.5 means only 25% shared variance.', 'supplementary', 'csit-601/data-analysis/dc82430f9c52', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('70af09ec-0727-5ad6-8cf2-a414cb279613', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'df7aa797-5ebc-5421-a071-6ad821d46c0c', 'How do you interpret B in a multiple regression?', 'The expected change in the outcome, in its own units, for a one-unit increase in the predictor, holding the other predictors constant.', 'supplementary', 'csit-601/data-analysis/2db66d9776be', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f29f1294-515c-5e06-a874-84be1e842724', null, '2c1df771-f299-58d8-95a4-e55602e24536', '650c0d2d-1cae-5413-9bce-092bc4d145a0', 'df7aa797-5ebc-5421-a071-6ad821d46c0c', 'When should you compare standardised β rather than B?', 'When predictors are measured on different scales, because β expresses effects in standard deviation units.', 'supplementary', 'csit-601/data-analysis/58e8ff3f0991', true)
