insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('aeacda60-a9c1-5c0f-89ce-917969322e94', '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', '10629560-6ec6-5e41-909e-3385ddd6133e', 'csit-601/academic-writing-and-proposals/q33', 'true_false', 'understand', 'easy', 'Recognise when hypotheses are appropriate', 'The exploratory qualitative proposal on e-commerce adoption should include formal hypotheses to be tested.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('aeacda60-a9c1-5c0f-89ce-917969322e94', '{"value":false}'::jsonb, 'Hypotheses belong to deductive, usually quantitative designs. An inductive interview study uses research questions and may use theory as a sensitising framework while allowing new themes to emerge.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f4fa7f54-45fb-558f-910c-df21b38d160b', '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', '10629560-6ec6-5e41-909e-3385ddd6133e', 'csit-601/academic-writing-and-proposals/q34', 'scenario', 'analyse', 'hard', 'Analyse a sampling choice when no frame exists', 'Which sampling approach best fits this situation?', 'Illustrative scenario. A student wants to survey traders in a large market in Kumasi about digital payment acceptance. No list of traders exists, but the market is divided into clearly defined sections.', null, '[{"id":"a","text":"Simple random sampling from a complete list of traders"},{"id":"b","text":"Snowball sampling starting with the student''s relatives"},{"id":"c","text":"Interviewing whichever traders are least busy"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f4fa7f54-45fb-558f-910c-df21b38d160b', '{"option":"b"}'::jsonb, 'Without a frame, simple random sampling is impossible. Randomly selecting sections and then systematically selecting stalls keeps a probability element while being practical; the design effect of clustering should be acknowledged. Snowball and convenience approaches introduce strong selection bias for a question about market-wide acceptance.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('05015cd4-5d6a-5053-8048-36955585a717', '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', '10629560-6ec6-5e41-909e-3385ddd6133e', 'csit-601/academic-writing-and-proposals/q35', 'short_answer', 'recall', 'medium', 'Recall the mixed-methods design in the healthcare proposal', 'What is the name of the mixed-methods design used in the healthcare proposal, in which a survey is followed by interviews that explain its results?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('05015cd4-5d6a-5053-8048-36955585a717', '{"answers":["explanatory sequential","explanatory sequential design","explanatory sequential mixed methods"]}'::jsonb, 'In an explanatory sequential design, the quantitative phase comes first and the qualitative phase explains significant or unexpected results; integration, for example through a joint display, is essential.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('684476a8-b9ea-5bd6-a808-1f9dbe2a8a81', '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', '10629560-6ec6-5e41-909e-3385ddd6133e', 'csit-601/academic-writing-and-proposals/q36', 'mcq', 'evaluate', 'hard', 'Evaluate a causal claim from a cross-sectional design', 'The AI-in-SMEs proposal uses a cross-sectional survey. Which conclusion would its design best support?', null, null, '[{"id":"a","text":"AI adoption causes higher operational efficiency in Ghanaian SMEs"},{"id":"b","text":"AI adoption is positively associated with perceived operational efficiency among the SMEs surveyed"},{"id":"c","text":"All Ghanaian SMEs should adopt AI immediately"},{"id":"d","text":"Operational efficiency causes AI adoption"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('684476a8-b9ea-5bd6-a808-1f9dbe2a8a81', '{"option":"b"}'::jsonb, 'A single-time-point survey can establish association within the sample but not the direction of causation, and perceived efficiency is not an objective measure. Causal claims in either direction and sweeping prescriptions go beyond the evidence.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('278db383-258e-5f2d-9751-72227992ae5e', '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', null, 'csit-601/academic-writing-and-proposals/q37', 'case_analysis', 'evaluate', 'hard', 'Evaluate the alignment and quality of a draft research proposal', 'Critically evaluate Kwame''s draft proposal and recommend specific revisions to its structure, alignment, methodology, referencing and ethics.', null, 'Illustrative scenario. Kwame''s draft proposal is titled "E-commerce in Ghana". His background lists statistics copied from blog posts without original sources. His problem statement says, "E-commerce is important and many businesses are not using it." His objectives are to "look at e-commerce" and "find out what businesses think". His conceptual framework, drawn from UTAUT, includes performance expectancy, effort expectancy, social influence and facilitating conditions. His methodology states that "a questionnaire and interviews will be used and the data will be analysed with SPSS", with no sampling details. He plans to interview friends who run online shops. His reference list mixes Harvard and APA styles, and several in-text citations do not appear in it. Ethics is covered in one sentence: "Ethics will be observed."', null, 20, array['Overview of the proposal''s overall coherence', 'Title, background and problem statement weaknesses', 'Objectives, questions and alignment with the UTAUT framework', 'Methodology, design, sampling and analysis gaps', 'Referencing and integrity issues', 'Ethics gaps', 'Prioritised recommendations']::text[], '[{"criterion":"Introduction and problem analysis","marks":5,"descriptor":"Identifies the vague title, unverified statistics, lack of a knowledge gap and consequences, and proposes a focused title and evidenced problem statement."},{"criterion":"Alignment and framework","marks":5,"descriptor":"Explains that objectives are not measurable and do not map to the UTAUT constructs, and proposes aligned objectives, questions and hypotheses or a justified qualitative alternative."},{"criterion":"Methodology and sampling","marks":5,"descriptor":"Identifies missing paradigm, design, population, frame, sample size and analysis per objective; recognises convenience and researcher bias in interviewing friends; proposes a coherent design such as a survey or a justified mixed-methods approach."},{"criterion":"Referencing and ethics","marks":5,"descriptor":"Identifies mixed styles, missing references and reliance on blogs; recommends consistent APA 7 and primary sources; replaces the generic ethics sentence with specific consent, confidentiality, data protection (Act 843 principles) and institutional approval measures."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('278db383-258e-5f2d-9751-72227992ae5e', '{}'::jsonb, 'Examiners reward answers that diagnose specific weaknesses, explain why they matter, and propose concrete, aligned revisions rather than generic criticism.', 'A strong answer argues that Kwame''s draft lacks the alignment that makes a proposal defensible. The title "E-commerce in Ghana" names no variables, population or setting; a revision might be "Determinants of e-commerce adoption intention among small retail businesses in Accra". The background relies on blog statistics, which should be replaced with verified primary sources such as official reports and peer-reviewed studies. The problem statement asserts importance without evidence, consequences or a knowledge gap; it should state the practical problem, the evidence for it and what research has not established.

The objectives "look at" and "find out" are not measurable and bear no relation to the UTAUT framework. If Kwame keeps UTAUT, his objectives should examine the effects of each construct on adoption intention, with matching questions and hypotheses. Alternatively, if his real interest is how owners experience e-commerce, a qualitative design with research questions and theory used as a sensitising framework would be more coherent; mixing the two without justification creates confusion.

The methodology names tools but not a paradigm, design, population, sampling frame, sample size or analysis technique for each objective; "SPSS" is software, not analysis. Interviewing friends introduces convenience and researcher bias; purposive or probability sampling with a stated frame is needed.

Mixed Harvard and APA styles and citations missing from the reference list raise integrity concerns; Kwame should adopt APA 7 consistently and use Zotero to manage sources. "Ethics will be observed" must be replaced with specific measures: information sheets, informed consent, confidentiality and pseudonyms, secure data handling consistent with Act 843 principles, and institutional ethical approval before data collection. Recommendations should be prioritised: refocus the problem, realign objectives with the framework, specify the design, then fix referencing and ethics.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a3bb9a5a-b595-51b8-9865-b979a4bc6056', '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', null, 'csit-601/academic-writing-and-proposals/q38', 'essay', 'evaluate', 'hard', 'Evaluate the relationship between methodology, findings and recommendations', '"A dissertation is only as credible as the chain linking its research questions to its recommendations." Discuss this statement, explaining how the methodology, results, discussion and conclusion chapters each contribute to that chain, with examples from IT-for-business research in Ghana.', null, null, null, 15, array['Introduction explaining the idea of an alignment chain', 'Methodology as justification and transparency', 'Results as accurate, complete reporting', 'Discussion as interpretation against literature and theory', 'Conclusions and recommendations derived from findings', 'Example of a broken and a strong chain', 'Conclusion evaluating the statement']::text[], '[{"criterion":"Understanding of chapter purposes","marks":4,"descriptor":"Accurately explains the distinct roles of methodology, results, discussion and conclusion chapters."},{"criterion":"Critical argument about alignment","marks":5,"descriptor":"Evaluates how breaks in the chain (such as causal claims from correlational data or ungrounded recommendations) undermine credibility, and considers whether alignment alone is sufficient."},{"criterion":"Application to Ghanaian IT-for-business examples","marks":4,"descriptor":"Uses realistic examples such as digital payments, AI in SMEs or EHR adoption to illustrate strong and weak chains."},{"criterion":"Structure and expression","marks":2,"descriptor":"Logical structure, academic tone and a reasoned conclusion."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a3bb9a5a-b595-51b8-9865-b979a4bc6056', '{}'::jsonb, 'Examiners look for clear understanding of each chapter''s role, critical evaluation of alignment and its limits, and realistic, well-chosen examples.', 'A strong essay explains that credibility depends on a traceable chain from research questions through methodology, results and discussion to conclusions and recommendations. The methodology contributes by justifying each design decision in relation to the questions and reporting enough detail for replication or audit; a survey of retailers, for example, should justify its cluster sampling where no frame exists and map each objective to an analysis technique. The results chapter contributes accurate, complete reporting, including effect sizes and non-significant findings, without interpretation creeping in.

The discussion links findings to literature and theory: a non-significant trust effect among experienced mobile money users might be compared with consumer studies and explained cautiously. Conclusions answer each research question and state the contribution, and recommendations follow directly, such as advising payment providers to review fee structures when perceived cost predicts intention.

The essay should illustrate a broken chain, for instance a cross-sectional study of AI in SMEs that concludes AI "causes" efficiency and recommends national policy changes, and contrast it with a well-aligned study whose claims are proportionate. Critical answers note that alignment is necessary but not sufficient: a perfectly aligned study can still be weak if measures lack validity, samples are biased or ethics are neglected. The conclusion broadly supports the statement while emphasising that the strength of each link, not only its presence, determines credibility.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f238d544-c080-57f2-8da0-149c4baaf183', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', 'c8963a7d-37ea-5c6c-adc5-35f192812339', 'What is the simplest test of whether a paragraph is critical or merely descriptive?', 'Ask "so what?" A critical paragraph evaluates, compares or interprets evidence and explains why it matters for the argument; a descriptive paragraph only reports.', 'supplementary', 'csit-601/academic-writing-and-proposals/767f6c2c6a7d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d2662a1e-e456-5f25-bc47-952e36fef7bc', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', 'c8963a7d-37ea-5c6c-adc5-35f192812339', 'What are the four elements of a PEAL paragraph?', 'Point (topic sentence), Evidence (data or citations), Analysis (what it shows and why it matters), Link (connection to the argument or next paragraph).', 'supplementary', 'csit-601/academic-writing-and-proposals/c129cb5ed80b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1bc08b3d-9e89-575d-b2a0-b535683ec456', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', 'c8963a7d-37ea-5c6c-adc5-35f192812339', 'What five things should an abstract for a completed study cover?', 'Context and problem, purpose, method (design, sample, analysis), main findings, and implications.', 'supplementary', 'csit-601/academic-writing-and-proposals/886ab215c0d7', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('90350af5-65f5-5a20-acb6-139443173828', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', 'c8963a7d-37ea-5c6c-adc5-35f192812339', 'How does a proposal abstract differ from a dissertation abstract?', 'It describes methods in the future tense and states expected contributions instead of findings, because no data have yet been collected.', 'supplementary', 'csit-601/academic-writing-and-proposals/e689b9ff3ebe', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6b45806c-003f-55f3-b22a-61ceed785886', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', 'c8963a7d-37ea-5c6c-adc5-35f192812339', 'Why is hedging a strength rather than a weakness in academic writing?', 'It makes claims proportionate to the evidence, for example "suggests an association" for correlational data rather than "proves causation".', 'supplementary', 'csit-601/academic-writing-and-proposals/19dc3bcb0fde', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9f280af2-0d93-5ca3-9c35-7619a136d121', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', '13c8d0d6-fc6c-5e05-9f5e-e681c4ac42d0', 'What three things should a strong problem statement contain?', 'A practical problem supported by evidence, the consequences of leaving it unaddressed, and a knowledge gap in existing research.', 'supplementary', 'csit-601/academic-writing-and-proposals/b734b2aebaab', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('54b657b7-cce3-5069-af6b-c1b859aa12f0', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', '13c8d0d6-fc6c-5e05-9f5e-e681c4ac42d0', 'What is the funnel structure in a background section?', 'Moving from broad global or regional context to the national setting, then to the specific phenomenon, ending at the research problem.', 'supplementary', 'csit-601/academic-writing-and-proposals/d0b3012d0491', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6708045c-1cdc-50cd-a730-129d30201ef8', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', '13c8d0d6-fc6c-5e05-9f5e-e681c4ac42d0', 'What is wrong with an "author parade" literature review and what should replace it?', 'It summarises studies one by one without synthesis; replace it with a concept-centric review organised by theme or relationship, supported by a concept matrix.', 'supplementary', 'csit-601/academic-writing-and-proposals/71af96a3f592', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('afcf5117-c4e6-5c45-80e3-0ca51c89989b', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', '13c8d0d6-fc6c-5e05-9f5e-e681c4ac42d0', 'How can you test the alignment of a proposal?', 'Trace one objective through its research question, hypothesis, framework construct, instrument items and analysis technique; any missing link is a misalignment.', 'supplementary', 'csit-601/academic-writing-and-proposals/6cd5057d0857', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9222e102-1753-5d58-b679-2b34b5184430', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', '13c8d0d6-fc6c-5e05-9f5e-e681c4ac42d0', 'Why might TOE suit an SME adoption study better than TAM?', 'TOE explains organisational adoption through technological, organisational and environmental contexts, whereas TAM focuses on individual users'' beliefs.', 'supplementary', 'csit-601/academic-writing-and-proposals/0e643c73318e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2a6d41cf-a4b4-5377-87f0-239dcf079b3a', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', 'd6d64a32-d236-53b2-98f1-07744969431a', 'What is the key verb for a methodology chapter and why?', 'Justify: each choice must be linked to the research questions and context, with alternatives considered, not merely described.', 'supplementary', 'csit-601/academic-writing-and-proposals/6c407c13f681', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d788a06c-d6d3-5cc0-baa0-5acbdecc67e5', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', 'd6d64a32-d236-53b2-98f1-07744969431a', 'What distinguishes the results chapter from the discussion chapter?', 'Results report what the data show accurately and completely; the discussion interprets findings and compares them with literature and theory.', 'supplementary', 'csit-601/academic-writing-and-proposals/f867a399ef01', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
