  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f3924d8e-7229-5087-8123-2ae1dcaa895c', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', 'd6d64a32-d236-53b2-98f1-07744969431a', 'What makes a recommendation strong?', 'It names a specific stakeholder and action and is directly derived from a reported finding.', 'supplementary', 'csit-601/academic-writing-and-proposals/ca6ff8b1e545', true)
