insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('923244f8-558b-5788-aea1-a90d60d3f5ae', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', 'd6d64a32-d236-53b2-98f1-07744969431a', 'Why should effect sizes be reported alongside p-values?', 'Statistical significance shows evidence against a null hypothesis, but effect size shows the magnitude and practical importance of a relationship.', 'supplementary', 'csit-601/academic-writing-and-proposals/98a7111010ce', true)
