insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2ed5f6b7-75e3-584c-9ef2-e6166104c3c0', null, '2c1df771-f299-58d8-95a4-e55602e24536', '323e77f6-364c-52b5-b9cc-91ec03945796', 'cb4c9632-8e41-5568-b92d-c221c5ab1778', 'Name two APA 7 changes for books compared with older practice.', 'The publisher''s location is omitted, and DOIs are written as https://doi.org/ URLs without a "DOI:" label.', 'supplementary', 'csit-601/academic-writing-and-proposals/6635549a95bf', true)
