insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c8921b7e-6167-5f87-994f-5be131c96629', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'dbd0785c-d6c4-5aa2-b1a0-5a89e4aceb27', '58faa8b8-b92d-5904-91b1-86462b4ee260', 'What happens in TOGAF ADM phases E and F?', 'Phase E (Opportunities and Solutions) groups gaps into projects and work packages; Phase F (Migration Planning) sequences them into a prioritised roadmap of transition architectures.', 'supplementary', 'csit-603/enterprise-systems-foundations/f5603d6b2409', true)
