insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d253e615-ac61-5475-97a3-a823560693b6', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'dbd0785c-d6c4-5aa2-b1a0-5a89e4aceb27', '58faa8b8-b92d-5904-91b1-86462b4ee260', 'Why does point-to-point integration scale poorly?', 'Interfaces grow as n × (n − 1) / 2, so ten systems can need 45 interfaces, each to be built, monitored and changed; a hub needs only n connections.', 'supplementary', 'csit-603/enterprise-systems-foundations/a9e0073d0e53', true)
