insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('eb9ecffe-2a22-55d1-ba81-661056530964', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'dbd0785c-d6c4-5aa2-b1a0-5a89e4aceb27', '58faa8b8-b92d-5904-91b1-86462b4ee260', 'What is the difference between Zachman and TOGAF?', 'Zachman is a classification matrix for architecture descriptions; TOGAF is a framework with a method (the ADM) for developing and governing architecture.', 'supplementary', 'csit-603/enterprise-systems-foundations/e55e0d26b393', true)
