insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d8b4de86-e959-55f0-983b-e064c3a2207b', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'dbd0785c-d6c4-5aa2-b1a0-5a89e4aceb27', '58faa8b8-b92d-5904-91b1-86462b4ee260', 'When is messaging preferable to a synchronous API call?', 'When systems must be decoupled in time, for example when the receiving system may be offline and no event may be lost, or when volumes are high.', 'supplementary', 'csit-603/enterprise-systems-foundations/82a4c0d1e090', true)
