insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0318a417-a05e-5791-a00b-66d043582cf1', '{"option":"c"}'::jsonb, 'OLAP workloads aggregate large volumes of historical data. The other options are small transactional reads and writes typical of OLTP databases that run day-to-day operations.', null)
