insert into public.question_keys (question_id, correct, explanation, model_answer) values ('333e22dd-7d80-528c-aa44-f85df40c79b9', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Master data describes long-lived business entities referenced by many transactions; transaction data records time-stamped events. Errors in master data propagate into every transaction that refers to it.', null)
