insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('99750347-10a6-53e0-bd2b-3612d0f35cf9', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'bf776172-f644-52ea-b8ff-884b52dde037', 'csit-603/enterprise-applications/q17', 'short_answer', 'recall', 'easy', 'Recall the term for the level of detail of a fact table row', 'In dimensional modelling, what term describes the level of detail represented by one row of a fact table?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
