insert into public.question_keys (question_id, correct, explanation, model_answer) values ('99750347-10a6-53e0-bd2b-3612d0f35cf9', '{"answers":["grain","the grain","granularity"]}'::jsonb, 'Kimball and Ross stress declaring the grain before choosing dimensions and facts, for example "one row per product per sales receipt line". An undeclared grain leads to double counting and confused designs.', null)
