insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('41ca690c-be58-5a25-bfdf-5c571a5d1031', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'bf776172-f644-52ea-b8ff-884b52dde037', 'csit-603/enterprise-applications/q18', 'true_false', 'understand', 'medium', 'Recognise MDM as governance', 'Master data management can be fully achieved by installing an MDM software hub, without assigning data owners or stewards.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
