insert into public.question_keys (question_id, correct, explanation, model_answer) values ('41ca690c-be58-5a25-bfdf-5c571a5d1031', '{"value":false}'::jsonb, 'MDM is primarily an organisational programme: owners, stewards, agreed definitions and creation workflows. A hub supports these but cannot by itself prevent duplicates or settle definitional disputes.', null)
