insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7cc17a72-8632-57d7-86af-5e43b8168ed3', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'bf776172-f644-52ea-b8ff-884b52dde037', 'csit-603/enterprise-applications/q19', 'scenario', 'analyse', 'medium', 'Diagnose a master data quality problem', 'What is the root cause, and what is the best remedy?', 'Illustrative scenario. A supermarket''s dashboard shows that sales of a popular rice brand have fallen by half, but
shelf staff report it is selling as well as ever. Investigation shows a new product code was created for the same
item when a new pack design arrived.', null, '[{"id":"a","text":"A dashboard software bug; replace the dashboard tool"},{"id":"b","text":"Duplicate product master data; merge the codes and introduce controlled product creation with a steward"},{"id":"c","text":"Theft at the branch; install cameras"},{"id":"d","text":"Wrong ETL schedule; refresh the warehouse more often"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7cc17a72-8632-57d7-86af-5e43b8168ed3', '{"option":"b"}'::jsonb, 'Sales are split across two codes for the same item, a classic duplicate master data problem. Merging and controlling creation fixes the cause. The dashboard reports correctly what the data says; refresh frequency and theft do not explain a split between codes.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4951b272-4b99-5d89-81e2-4631ad951fe4', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'bf776172-f644-52ea-b8ff-884b52dde037', 'csit-603/enterprise-applications/q20', 'mcq', 'apply', 'medium', 'Apply analytics types to business questions', 'A hospital asks, "Which wards are likely to exceed bed capacity next week?" Which type of analytics does this require?', null, null, '[{"id":"a","text":"Descriptive"},{"id":"b","text":"Diagnostic"},{"id":"c","text":"Predictive"},{"id":"d","text":"Prescriptive"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4951b272-4b99-5d89-81e2-4631ad951fe4', '{"option":"c"}'::jsonb, 'Forecasting what is likely to happen is predictive analytics. Descriptive reports what happened, diagnostic explains why, and prescriptive recommends an action, such as how to reallocate beds.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3bcca024-30f8-5edb-bbdd-05b2c6126492', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'bf776172-f644-52ea-b8ff-884b52dde037', 'csit-603/enterprise-applications/q21', 'mcq', 'evaluate', 'hard', 'Evaluate data-sharing in the Retail Link example', 'Which condition is most essential for a retailer''s sales data sharing with suppliers, such as Walmart''s Retail Link, to deliver value?', null, null, '[{"id":"a","text":"Suppliers must use the same ERP vendor as the retailer"},{"id":"b","text":"Product, store and date identifiers must be consistent and governed across partners"},{"id":"c","text":"Data must be shared only once a year"},{"id":"d","text":"All analysis must be done by the retailer, not the suppliers"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3bcca024-30f8-5edb-bbdd-05b2c6126492', '{"option":"b"}'::jsonb, 'Shared data is useful only if identifiers mean the same thing to every party; that requires governed master data. Common vendors are unnecessary, annual sharing defeats the purpose of replenishment, and the point of sharing is that suppliers can analyse demand themselves.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d453a1e5-756e-57b4-ba5c-d39855f249a3', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', null, 'csit-603/enterprise-applications/q22', 'case_analysis', 'evaluate', 'hard', 'Evaluate an enterprise application portfolio for a Ghanaian hospital group', 'Analyse the group''s application and data problems, evaluate the suite versus best-of-breed options for patient-facing functions, and recommend an application and data architecture, including master data governance and analytics priorities.', null, 'Illustrative scenario. Nkabom Health is a hypothetical group of three private hospitals in Accra and Kumasi. Each
hospital has its own patient registration and billing system, pharmacy stock is managed in a separate package, HR
and payroll are run on spreadsheets, and there is no group-wide reporting. Insurers, including NHIS-accredited
claims processes, require accurate itemised bills. The board wants an integrated ERP for finance, procurement,
inventory and HR, and asks whether patient-facing functions should come from the same suite or a specialist
hospital management system.', null, 20, array['Diagnosis of application fragmentation and data problems', 'Role of ERP modules (finance, procurement, inventory, HR) and their integration', 'Suite versus specialist hospital system evaluation', 'Master data domains, ownership and governance', 'Analytics priorities and a justified recommendation']::text[], '[{"criterion":"Diagnosis","marks":4,"descriptor":"Identifies duplicate patient and product data, lost charges, manual payroll and lack of group reporting."},{"criterion":"ERP and integration","marks":5,"descriptor":"Explains how procure-to-pay, inventory, payroll and finance would integrate and what controls they provide."},{"criterion":"Suite versus best-of-breed","marks":4,"descriptor":"Balanced evaluation of functional depth, integration effort, skills and vendor management."},{"criterion":"Master data and governance","marks":4,"descriptor":"Identifies master data domains (patient, product, supplier, employee) with owners, stewards and quality measures."},{"criterion":"Analytics and recommendation","marks":3,"descriptor":"Prioritises descriptive reporting before predictive work and gives a clear, justified recommendation."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d453a1e5-756e-57b4-ba5c-d39855f249a3', '{}'::jsonb, 'Examiners look for integration reasoning, a balanced option appraisal and explicit master data governance rather than a list of modules.', 'The diagnosis should note that three separate registration and billing systems give no group view of patients or
revenue; the pharmacy package is unlinked to billing, risking lost charges and weak claims; spreadsheet payroll
lacks controls; and the absence of shared product and patient identifiers prevents group reporting.

An ERP would provide integrated financial accounting, procure-to-pay with three-way matching for medical supplies,
inventory with batch and expiry tracking, and an HR module whose payroll posts to the ledger and cost centres. These
bring control and visibility, but clinical workflows are specialised.

For patient-facing functions, an ERP suite simplifies integration and vendor management but may lack clinical depth
(wards, laboratory orders, clinical records). A specialist hospital management system offers that depth but requires
integration for charges, stock consumption and patient billing. A reasoned answer might recommend a specialist
hospital system for clinical and patient administration integrated with the ERP through APIs or messaging for
charges and stock consumption, provided the vendor offers proven connectors.

Master data governance should cover patient (master patient index owned by medical records), product and medicine
codes (owned by pharmacy and procurement), suppliers (procurement) and employees (HR), each with stewards, creation
rules and quality measures such as duplicate rates. Analytics should start with reliable descriptive reporting on
revenue, claims and stock, then progress to predictive uses such as demand for medicines or bed occupancy.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('dd0afa79-9cba-5d29-a82f-5bf5e496d1e9', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', null, 'csit-603/enterprise-applications/q23', 'essay', 'evaluate', 'hard', 'Critically evaluate best-practice processes in ERP', '"Organisations should always adapt their processes to the ERP package rather than customise the package." Critically evaluate this statement using the concepts of best-practice processes, configuration, customisation and competitive advantage.', null, null, null, 20, array['Define best-practice processes, configuration and customisation', 'Arguments for adapting processes (cost, upgrades, controls, cloud ERP)', 'Arguments for selective customisation or extension (differentiation, local requirements)', 'Use of cases and Davenport''s argument', 'Reasoned conclusion with decision criteria']::text[], '[{"criterion":"Conceptual accuracy","marks":5,"descriptor":"Correct definitions and distinction between configuration, customisation and extension."},{"criterion":"Arguments for the statement","marks":5,"descriptor":"Explains cost, risk, upgrade and control benefits of adopting standard processes."},{"criterion":"Arguments against","marks":5,"descriptor":"Uses Davenport (1998) and examples of differentiating or locally required processes."},{"criterion":"Conclusion and criteria","marks":5,"descriptor":"Offers clear criteria (commodity versus differentiating, extension outside the core) and a justified position."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('dd0afa79-9cba-5d29-a82f-5bf5e496d1e9', '{}'::jsonb, 'Examiners reward precise terminology, balanced argument supported by theory and examples, and practical decision criteria in the conclusion.', 'A strong essay defines best-practice processes as vendor-designed standard processes embedded in the package,
configuration as using built-in settings, and customisation as modifying or adding code. Extensions built outside the
core through APIs or add-ons form a middle path.

In support of the statement, adopting standard processes lowers implementation cost and risk, simplifies upgrades
(especially in cloud ERP with frequent releases), brings proven controls such as three-way matching, and offers an
opportunity to abandon inefficient habits. Fit-to-standard approaches, such as those in SAP Activate, embody this
view.

Against the statement, Davenport (1998) warned that enterprise systems can push firms towards generic processes and
erode differentiation. Where a process is a genuine source of competitive advantage, or where local legal, tax or
industry requirements are not supported, adaptation may be inappropriate. Ghanaian businesses may also need to
support mobile money reconciliation or local statutory reporting.

A balanced conclusion rejects "always": organisations should standardise commodity processes such as payables and
payroll, consider differentiation only where it creates real value, and prefer configuration and extensions over
modifying the core, with every customisation justified by a business case.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bd0f349c-ca57-5e86-b42b-98695bc6bfbc', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', '1f9bde9e-ccda-5c78-8192-b95711189e74', 'csit-603/enterprise-applications/q24', 'mcq', 'understand', 'easy', 'Explain what makes ERP modules an integrated system', 'What chiefly distinguishes an ERP from a bundle of separate business packages?', null, null, '[{"id":"a","text":"It is always hosted in the cloud"},{"id":"b","text":"Its modules share a common database and master data"},{"id":"c","text":"It has a graphical user interface"},{"id":"d","text":"It is sold by a single vendor"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bd0f349c-ca57-5e86-b42b-98695bc6bfbc', '{"option":"b"}'::jsonb, 'Integration comes from shared data, so one transaction updates every relevant module. Cloud hosting, graphical interfaces and single-vendor supply are neither necessary nor sufficient; separate packages can have all three and still hold separate, inconsistent data.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0d4d733b-da5e-5166-811c-96752f28c93d', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', '1f9bde9e-ccda-5c78-8192-b95711189e74', 'csit-603/enterprise-applications/q25', 'mcq', 'understand', 'medium', 'Identify the responsibilities of the ERP tiers', 'In a three-tier ERP architecture, where do pricing rules, credit checks and workflow approvals run?', null, null, '[{"id":"a","text":"Presentation tier"},{"id":"b","text":"Application tier"},{"id":"c","text":"Database tier"},{"id":"d","text":"Network tier"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0d4d733b-da5e-5166-811c-96752f28c93d', '{"option":"b"}'::jsonb, 'The application tier executes business logic. The presentation tier displays information and collects input, and the database tier stores data. There is no separate network tier in this model, although network controls sit between tiers.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('da6fc021-b424-5fc7-aafb-131393ec6daf', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', '1f9bde9e-ccda-5c78-8192-b95711189e74', 'csit-603/enterprise-applications/q26', 'true_false', 'recall', 'easy', 'Recognise that tiers are logical separations', 'True or false: A three-tier ERP architecture requires three physically separate servers.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('da6fc021-b424-5fc7-aafb-131393ec6daf', '{"value":false}'::jsonb, 'Tiers are logical separations of responsibility. They can run on separate machines, on one machine, or on virtual or cloud resources. The benefit lies in independent scaling, security and change, not in the hardware count.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('050bc36f-f785-5423-9345-f86574bbb052', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', '1f9bde9e-ccda-5c78-8192-b95711189e74', 'csit-603/enterprise-applications/q27', 'scenario', 'apply', 'medium', 'Apply the configuration, extension and customisation hierarchy', 'Which approach should the distributor try first, and why?', 'A Ghanaian distributor wants its ERP to apply a seasonal credit policy. The ERP offers a pricing and credit
settings screen, a published API for add-on applications, and the option for developers to edit the delivered
credit-check program. The vendor releases upgrades twice a year.', null, '[{"id":"a","text":"Edit the delivered credit-check program because it gives the exact result"},{"id":"b","text":"Use the built-in settings, because configuration is vendor-supported and survives upgrades"},{"id":"c","text":"Build an add-on through the API before checking the settings"},{"id":"d","text":"Avoid the ERP entirely and use spreadsheets"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('050bc36f-f785-5423-9345-f86574bbb052', '{"option":"b"}'::jsonb, 'The usual order is configuration, then extension, then customisation of the core. Configuration is supported and normally survives upgrades. The API route is the fallback if settings cannot express the policy. Editing the delivered program would have to be retested or rewritten at every upgrade, and abandoning the ERP defeats its purpose.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c79a2aa2-f06b-5cc1-b89a-61887bba21a5', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', '1f9bde9e-ccda-5c78-8192-b95711189e74', 'csit-603/enterprise-applications/q28', 'mcq', 'analyse', 'medium', 'Analyse why middleware reduces integration complexity', 'Why does a hub-based integration platform often become cheaper than point-to-point links as the number of systems grows?', null, null, '[{"id":"a","text":"Each system connects once to the hub instead of to every other system"},{"id":"b","text":"Hubs remove the need for any data transformation"},{"id":"c","text":"Point-to-point links cannot carry data between systems"},{"id":"d","text":"Hubs make all systems use the same database"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c79a2aa2-f06b-5cc1-b89a-61887bba21a5', '{"option":"a"}'::jsonb, 'A mesh can need up to n(n-1)/2 interfaces while a hub needs about n connections. Hubs still perform transformation (they centralise it), point-to-point links do work for small numbers of systems, and a hub does not merge databases.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5e5d3183-4e56-5b01-9c3f-ebc658bfeb8e', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', '1f9bde9e-ccda-5c78-8192-b95711189e74', 'csit-603/enterprise-applications/q29', 'matching', 'understand', 'medium', 'Match deployment models to their defining characteristics', 'Match each deployment model to its description.', null, null, '{"left":[{"id":"l1","text":"On-premise"},{"id":"l2","text":"SaaS"},{"id":"l3","text":"Public cloud (IaaS)"},{"id":"l4","text":"Hybrid"}],"right":[{"id":"r4","text":"Some components in the cloud and some retained locally"},{"id":"r2","text":"Vendor operates a multi-tenant service and applies updates"},{"id":"r3","text":"Organisation installs and administers the ERP on rented infrastructure"},{"id":"r1","text":"Organisation runs the ERP on its own infrastructure"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5e5d3183-4e56-5b01-9c3f-ebc658bfeb8e', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'The models differ in who manages the platform and the application. Hybrid is a mix, which adds integration complexity between its parts.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e2dfa9cb-256d-5555-b37f-9f77ed2fefec', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', '1f9bde9e-ccda-5c78-8192-b95711189e74', 'csit-603/enterprise-applications/q30', 'true_false', 'evaluate', 'hard', 'Evaluate responsibility under SaaS', 'True or false: Moving to SaaS ERP transfers responsibility for data quality and user access control to the vendor.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e2dfa9cb-256d-5555-b37f-9f77ed2fefec', '{"value":false}'::jsonb, 'The vendor runs the platform, but the customer still owns its data quality, user access, process design and compliance duties. SaaS shifts some risks, such as hardware and patching, but does not remove the customer''s responsibilities.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7a7f4d56-313b-5c2c-a514-cd4094a94561', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', '1f9bde9e-ccda-5c78-8192-b95711189e74', 'csit-603/enterprise-applications/q31', 'short_answer', 'recall', 'easy', 'Recall the term for adjusting an ERP using built-in settings', 'What term describes adjusting an ERP through its built-in parameters without changing program code?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7a7f4d56-313b-5c2c-a514-cd4094a94561', '{"answers":["configuration","configuring"]}'::jsonb, 'Configuration uses vendor-supported settings. Customisation, by contrast, changes or adds code in the core and raises upgrade cost.', null)
