insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('48e1df67-5f1c-561b-82e5-e0e27f052dff', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'c30808c1-a5f5-5b36-bd7b-db7c85c31477', 'What is the essence of ERP integration?', 'One transaction updates every affected record across modules (for example, a goods receipt updates stock, the purchase order and the ledger) because modules share one database.', 'supplementary', 'csit-603/enterprise-applications/0c1880235013', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5d806f8b-6ee2-5501-b3a3-7d3d87261176', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'c30808c1-a5f5-5b36-bd7b-db7c85c31477', 'Outline the order-to-cash process in an ERP.', 'Sales order (availability and credit check) → delivery → goods issue (stock and cost of goods sold) → invoice (receivable) → payment receipt (receivable cleared).', 'supplementary', 'csit-603/enterprise-applications/093f7a2e4f0c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ca1028a0-7156-5673-bf9e-5c12a2a5a33f', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'c30808c1-a5f5-5b36-bd7b-db7c85c31477', 'Outline the procure-to-pay process in an ERP.', 'Purchase requisition → approval → purchase order → goods receipt → invoice verification (three-way match) → payment.', 'supplementary', 'csit-603/enterprise-applications/24328bcaeb1b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
