  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5278c1e2-e36b-57c6-b479-8c5ca40d389a', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'c30808c1-a5f5-5b36-bd7b-db7c85c31477', 'When might an organisation justify departing from an ERP''s best-practice process?', 'When the process genuinely differentiates the firm or local legal requirements are unsupported, preferably through configuration or extensions rather than core code changes.', 'supplementary', 'csit-603/enterprise-applications/c47293cb133c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('764e5194-bf9e-5391-ac1b-ec3dca5e6cda', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'c30808c1-a5f5-5b36-bd7b-db7c85c31477', 'What does the Hershey 1999 case teach about ERP risk?', 'Risk lies in implementation decisions; going live near peak season with several interdependent systems switched on at once and compressed testing caused order and shipping problems.', 'supplementary', 'csit-603/enterprise-applications/19705f6037b3', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('183461a6-74c5-5e11-8a3b-b6ed7ac2a5de', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'dd1c244c-77b1-505a-a5e6-2b1ea0bf0c95', 'Distinguish operational, analytical and collaborative CRM.', 'Operational automates customer-facing work; analytical analyses customer data; collaborative coordinates interactions across channels, branches and partners.', 'supplementary', 'csit-603/enterprise-applications/4aa76f265ec3', true)
