insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('30d58576-c556-538d-a921-ffcebb560811', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'dd1c244c-77b1-505a-a5e6-2b1ea0bf0c95', 'What causes the bullwhip effect?', 'Forecasting from orders rather than real demand, order batching, price fluctuations and promotions, and inflated orders during feared shortages.', 'supplementary', 'csit-603/enterprise-applications/fd991efe204a', true)
