insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c2ffc64a-6dc9-50a7-af58-20b64872087d', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', 'dd1c244c-77b1-505a-a5e6-2b1ea0bf0c95', 'What is the trade-off between a suite and best-of-breed?', 'A suite offers simpler integration, consistent data and one vendor; best-of-breed offers deeper specialist function at the cost of integration and vendor management.', 'supplementary', 'csit-603/enterprise-applications/52f1077f094e', true)
