insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('872b2f83-f956-553f-a2b6-f2ce062380cd', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '84796bc1-79bc-5067-9a41-3029c0b58f88', '1f9bde9e-ccda-5c78-8192-b95711189e74', 'Why are ERP modules described as integrated?', 'They read and write a shared database and shared master data, so one transaction (such as a goods receipt) updates stock, the purchase order and the ledger without re-keying or overnight interfaces.', 'supplementary', 'csit-603/enterprise-applications/e6036e7b577f', true)
