insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5e0e17b0-cd74-5867-b933-c301f3826ae6', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '4ff4452b-c5a5-5415-a57c-ccb786502ace', 'csit-603/business-process-management/q01', 'mcq', 'understand', 'easy', 'Distinguish a process from a function, task and project', 'Which of the following is best described as a business process?', null, null, '[{"id":"a","text":"The finance department"},{"id":"b","text":"Approving a single invoice"},{"id":"c","text":"Order-to-cash, from receipt of a customer order to receipt of payment"},{"id":"d","text":"Implementing a new ERP system over eighteen months"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
