insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5e0e17b0-cd74-5867-b933-c301f3826ae6', '{"option":"c"}'::jsonb, 'Order-to-cash is repeatable, has a trigger and outcome, crosses functions and delivers value to a customer. The finance department is a function, approving one invoice is a task and an ERP implementation is a one-off project.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('859ca9ee-bd86-5a78-a99c-68cccf1a5418', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '4ff4452b-c5a5-5415-a57c-ccb786502ace', 'csit-603/business-process-management/q02', 'matching', 'apply', 'medium', 'Classify processes in a hospital', 'Match each hospital process to its category.', null, null, '{"left":[{"id":"l1","text":"Admission-to-discharge"},{"id":"l2","text":"Medical equipment maintenance"},{"id":"l3","text":"Annual budgeting"}],"right":[{"id":"r3","text":"Management process"},{"id":"r2","text":"Support process"},{"id":"r1","text":"Core process"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
