insert into public.question_keys (question_id, correct, explanation, model_answer) values ('859ca9ee-bd86-5a78-a99c-68cccf1a5418', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'Core processes create value directly for patients; support processes enable them; management processes plan, direct and control. Classification depends on the organisation''s value proposition: maintenance would be core for an equipment servicing company.', null)
