insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('38dcc0d6-cdd2-5593-a74e-8716e4924d13', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '4ff4452b-c5a5-5415-a57c-ccb786502ace', 'csit-603/business-process-management/q03', 'short_answer', 'recall', 'easy', 'Recall the first phase of the BPM lifecycle', 'What is the name of the first phase of the BPM lifecycle, in which processes are delineated and prioritised?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
