insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('69aa08ae-b6e0-53c0-9d14-c4d7e0f98f15', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '4ff4452b-c5a5-5415-a57c-ccb786502ace', 'csit-603/business-process-management/q04', 'true_false', 'understand', 'medium', 'Recognise the role of the process owner', 'A process owner is accountable for end-to-end process performance even when several departments perform the activities.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
