insert into public.question_keys (question_id, correct, explanation, model_answer) values ('69aa08ae-b6e0-53c0-9d14-c4d7e0f98f15', '{"value":true}'::jsonb, 'Process owners address the "white space" between departments that Rummler and Brache (1990) identified. Without an end-to-end owner, each department optimises its own part and nobody is accountable for hand-offs.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5e176a3c-a0b8-576e-b019-c179b407da02', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '4ff4452b-c5a5-5415-a57c-ccb786502ace', 'csit-603/business-process-management/q05', 'scenario', 'apply', 'medium', 'Apply weighted prioritisation criteria', 'What are the weighted scores, and which process ranks higher?', 'Illustrative scenario. A logistics firm in Tema scores two processes from 1 to 5 using weights of importance 0.5,
dysfunction 0.3 and feasibility 0.2. Shipment tracking scores importance 4, dysfunction 4, feasibility 3. Staff
expense claims score importance 2, dysfunction 5, feasibility 5.', null, '[{"id":"a","text":"Tracking 3.8, expenses 3.5; tracking ranks higher"},{"id":"b","text":"Tracking 3.5, expenses 3.8; expenses ranks higher"},{"id":"c","text":"Both score 4.0"},{"id":"d","text":"Tracking 4.0, expenses 3.0; tracking ranks higher"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5e176a3c-a0b8-576e-b019-c179b407da02', '{"option":"a"}'::jsonb, 'Tracking = 0.5×4 + 0.3×4 + 0.2×3 = 2.0 + 1.2 + 0.6 = 3.8. Expenses = 0.5×2 + 0.3×5 + 0.2×5 = 1.0 + 1.5 + 1.0 = 3.5. Tracking ranks higher because importance carries the most weight. The scores structure discussion; evidence is still needed to support them.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1b020b56-4b9e-54c6-80e9-3703955c1979', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '4ff4452b-c5a5-5415-a57c-ccb786502ace', 'csit-603/business-process-management/q06', 'mcq', 'analyse', 'hard', 'Analyse trade-offs among performance dimensions', 'A pharmacy adds a second pharmacist check before every dispensing. In terms of the Devil''s Quadrangle, what is the most likely effect?', null, null, '[{"id":"a","text":"Quality improves while time and cost worsen"},{"id":"b","text":"Time, cost, quality and flexibility all improve"},{"id":"c","text":"Cost falls because fewer errors occur, with no other effects"},{"id":"d","text":"Flexibility improves while quality worsens"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1b020b56-4b9e-54c6-80e9-3703955c1979', '{"option":"a"}'::jsonb, 'The Devil''s Quadrangle highlights trade-offs among time, cost, quality and flexibility. An extra check reduces dispensing errors but adds labour and waiting time. Improvement on every dimension at once is rare, and fewer errors do not usually offset the cost of an additional check entirely.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bb4b4700-78d1-52ea-afe5-e2d9cfafeaa4', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '4ff4452b-c5a5-5415-a57c-ccb786502ace', 'csit-603/business-process-management/q07', 'true_false', 'evaluate', 'medium', 'Evaluate prioritisation logic', 'The most dysfunctional process should always be improved first, regardless of its strategic importance or feasibility.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bb4b4700-78d1-52ea-afe5-e2d9cfafeaa4', '{"value":false}'::jsonb, 'Prioritisation balances importance, health and feasibility. A badly performing but strategically minor process may not justify investment, while a highly important process with moderate problems may offer greater value.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6560445e-5b00-5c88-a3a9-adaaf6b0c1c7', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', 'c40f1b2f-0fe0-5604-ae27-959fa5fe8b88', 'csit-603/business-process-management/q08', 'matching', 'recall', 'easy', 'Recall the components of SIPOC', 'Match each SIPOC letter to its meaning in a pharmacy dispensing process.', null, null, '{"left":[{"id":"l1","text":"Supplier"},{"id":"l2","text":"Input"},{"id":"l3","text":"Process"},{"id":"l4","text":"Output"},{"id":"l5","text":"Customer"}],"right":[{"id":"r1","text":"The prescribing clinic"},{"id":"r2","text":"The prescription"},{"id":"r5","text":"The patient"},{"id":"r4","text":"Dispensed medicine and receipt"},{"id":"r3","text":"Verify, price, take payment and dispense"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6560445e-5b00-5c88-a3a9-adaaf6b0c1c7', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'SIPOC scopes a process at a high level before detailed mapping, forcing agreement on boundaries, sources and recipients.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('818e4d7a-1061-5a56-80e7-118e2e57605e', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', 'c40f1b2f-0fe0-5604-ae27-959fa5fe8b88', 'csit-603/business-process-management/q09', 'mcq', 'understand', 'medium', 'Explain the diagnostic value of swimlanes', 'Why are swimlane maps particularly useful for diagnosing process problems?', null, null, '[{"id":"a","text":"They show the organisation''s reporting lines"},{"id":"b","text":"They make hand-offs between roles visible, which are common sources of delay and error"},{"id":"c","text":"They automatically calculate cycle time"},{"id":"d","text":"They are required by law for process documentation"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('818e4d7a-1061-5a56-80e7-118e2e57605e', '{"option":"b"}'::jsonb, 'Each lane crossing is a hand-off where work may wait or information may be lost. Swimlanes do not show reporting lines, do not calculate time on their own and are not legally required.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a158bd25-9be3-547b-ba08-1f6f720ff8d2', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', 'c40f1b2f-0fe0-5604-ae27-959fa5fe8b88', 'csit-603/business-process-management/q10', 'scenario', 'apply', 'medium', 'Select discovery methods', 'What is the best next step in discovery?', 'Illustrative scenario. An analyst mapping a hospital''s laboratory test process has interviewed the laboratory
manager. The resulting map is neat and simple, but nurses complain that results often go missing.', null, '[{"id":"a","text":"Finalise the map, since the manager knows the process best"},{"id":"b","text":"Triangulate by observing cases end to end, interviewing nurses and technicians, and checking system logs"},{"id":"c","text":"Ask the manager to redraw the map in more detail"},{"id":"d","text":"Skip discovery and move straight to redesign"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a158bd25-9be3-547b-ba08-1f6f720ff8d2', '{"option":"b"}'::jsonb, 'A single manager''s view often reflects intended rather than actual practice. Observation, interviews with other roles and log analysis reveal workarounds and missing hand-offs. Redrawing from the same source or skipping discovery would carry the blind spot forward.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('66a5df4a-c528-5d2d-87e4-2461a1e85aca', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', 'c40f1b2f-0fe0-5604-ae27-959fa5fe8b88', 'csit-603/business-process-management/q11', 'true_false', 'understand', 'easy', 'Apply RACI rules', 'In a well-formed RACI matrix, each activity should normally have exactly one Accountable role.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('66a5df4a-c528-5d2d-87e4-2461a1e85aca', '{"value":true}'::jsonb, 'Several people may be Responsible, Consulted or Informed, but a single Accountable role avoids ambiguity about who answers for the outcome and signs off the work.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5ca8ac3b-6092-5340-8ebb-3ae254acbe02', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', 'c40f1b2f-0fe0-5604-ae27-959fa5fe8b88', 'csit-603/business-process-management/q12', 'short_answer', 'recall', 'medium', 'Recall the three minimum attributes of an event log', 'Besides a case identifier and an activity name, which attribute must every event in a process mining log have?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5ca8ac3b-6092-5340-8ebb-3ae254acbe02', '{"answers":["timestamp","a timestamp","time stamp","time"]}'::jsonb, 'Case ID, activity and timestamp allow tools to reconstruct the sequence of activities for each case and measure waiting times. Without timestamps, ordering and timing analysis is impossible.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1e7610dc-f198-5f79-b4d6-24617a64154e', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', 'c40f1b2f-0fe0-5604-ae27-959fa5fe8b88', 'csit-603/business-process-management/q13', 'mcq', 'analyse', 'hard', 'Analyse a process map for problems', 'In an as-is pharmacy map, the pharmacist verifies the prescription only after the patient has paid. What problem does this sequence most likely create?', null, null, '[{"id":"a","text":"It reduces the pharmacist''s workload"},{"id":"b","text":"Queries with the prescriber require refunds and rework, adding delay"},{"id":"c","text":"It speeds up the cashier"},{"id":"d","text":"It improves stock accuracy"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1e7610dc-f198-5f79-b4d6-24617a64154e', '{"option":"b"}'::jsonb, 'Late verification means invalid or queried prescriptions are found after payment, forcing refunds and repeated queuing. Moving verification earlier is a classic redesign of task order. The other options do not follow from the sequence.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('495fb96a-f212-533f-ab6c-de3e1937ab7b', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', 'c40f1b2f-0fe0-5604-ae27-959fa5fe8b88', 'csit-603/business-process-management/q14', 'mcq', 'evaluate', 'medium', 'Evaluate the choice between value stream mapping and swimlanes', 'A courier firm''s main goal is to reduce the total time from parcel collection to delivery. Which mapping technique is most suitable as the main tool?', null, null, '[{"id":"a","text":"An organisation chart"},{"id":"b","text":"A value stream map recording process and waiting times between steps"},{"id":"c","text":"A SIPOC alone"},{"id":"d","text":"A RACI matrix"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('495fb96a-f212-533f-ab6c-de3e1937ab7b', '{"option":"b"}'::jsonb, 'Value stream mapping (Rother & Shook, 1999) emphasises flow and time, including waiting between steps, which is what drives total lead time. SIPOC is only a scoping tool, RACI shows responsibilities and an organisation chart shows reporting lines.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('35564679-1777-5693-a6a8-3c9a8cdf6689', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '182d6e6a-4d8f-54ef-aea9-0046a934197e', 'csit-603/business-process-management/q15', 'matching', 'recall', 'easy', 'Recall BPMN element shapes', 'Match each BPMN element to its shape.', null, null, '{"left":[{"id":"l1","text":"Event"},{"id":"l2","text":"Activity"},{"id":"l3","text":"Gateway"},{"id":"l4","text":"Message flow"},{"id":"l5","text":"Data store"}],"right":[{"id":"r4","text":"Dashed arrow between pools"},{"id":"r2","text":"Rounded rectangle"},{"id":"r5","text":"Cylinder"},{"id":"r1","text":"Circle"},{"id":"r3","text":"Diamond"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('35564679-1777-5693-a6a8-3c9a8cdf6689', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Recognising shapes is the foundation of reading BPMN. Border styles distinguish start, intermediate and end events, and inner markers distinguish gateway and event types.', null)
