insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('af423b78-c5f3-5121-8471-a800a15710b3', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '182d6e6a-4d8f-54ef-aea9-0046a934197e', 'csit-603/business-process-management/q16', 'mcq', 'understand', 'medium', 'Explain parallel gateway behaviour', 'What does a parallel (AND) gateway do when it is used to merge flows?', null, null, '[{"id":"a","text":"Passes the first token that arrives and discards the rest"},{"id":"b","text":"Waits until a token has arrived on every incoming flow, then continues with one token"},{"id":"c","text":"Chooses one incoming flow based on a condition"},{"id":"d","text":"Ends the process instance"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('af423b78-c5f3-5121-8471-a800a15710b3', '{"option":"b"}'::jsonb, 'A parallel join synchronises: it waits for all incoming branches. An exclusive merge passes each token through separately; the first-token behaviour describes neither; ending the instance is the job of end events.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5f6aca26-9c74-5828-a341-6d23554d4d14', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '182d6e6a-4d8f-54ef-aea9-0046a934197e', 'csit-603/business-process-management/q17', 'true_false', 'understand', 'easy', 'Apply the rule for sequence flows and pools', 'In BPMN, a sequence flow may connect an activity in the hospital''s pool directly to an activity in the insurer''s pool.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5f6aca26-9c74-5828-a341-6d23554d4d14', '{"value":false}'::jsonb, 'Sequence flows must stay within one pool. Communication between participants is shown with message flows. Lanes within the same pool can be crossed by sequence flows.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2fc577b2-d568-5db9-8a21-9b650b3c26fc', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '182d6e6a-4d8f-54ef-aea9-0046a934197e', 'csit-603/business-process-management/q18', 'scenario', 'apply', 'medium', 'Choose the correct gateway type', 'Which gateways should model the split and join?', 'Illustrative scenario. A restaurant''s order process must prepare food and drinks for every order at the same time,
and serve the order only when both are ready.', null, '[{"id":"a","text":"Exclusive split and exclusive join"},{"id":"b","text":"Parallel split and parallel join"},{"id":"c","text":"Parallel split and exclusive join"},{"id":"d","text":"Event-based split and parallel join"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
