insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2fc577b2-d568-5db9-8a21-9b650b3c26fc', '{"option":"b"}'::jsonb, 'Both branches always run, so a parallel split is needed, and serving must wait for both, so a parallel join is needed. Merging with an exclusive gateway would let each branch pass separately, causing "Serve order" to run twice.', null)
