insert into public.question_keys (question_id, correct, explanation, model_answer) values ('eef33e96-87e0-542a-9c5f-6a813b4378fb', '{"answers":["timer boundary event","boundary timer event","timer event","boundary event"]}'::jsonb, 'A timer boundary event fires after a defined duration while the activity is active. It may be interrupting (cancelling the activity) or non-interrupting (dashed border, the activity continues).', null)
