insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('253a5df8-3e6f-54dd-ab75-504f70b4b13a', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '182d6e6a-4d8f-54ef-aea9-0046a934197e', 'csit-603/business-process-management/q20', 'mcq', 'analyse', 'hard', 'Analyse a modelling error with token semantics', 'A model splits into two branches with a parallel gateway and merges them with an exclusive gateway before the task "Send invoice". What happens when one instance runs?', null, null, '[{"id":"a","text":"\"Send invoice\" runs once, after both branches complete"},{"id":"b","text":"\"Send invoice\" runs twice, once for each branch''s token"},{"id":"c","text":"The process deadlocks and never reaches \"Send invoice\""},{"id":"d","text":"Only the first branch is executed"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('253a5df8-3e6f-54dd-ab75-504f70b4b13a', '{"option":"b"}'::jsonb, 'The parallel split creates two tokens. An exclusive merge passes each token through as it arrives without synchronising, so "Send invoice" is triggered twice. The fix is to merge with a parallel gateway. A deadlock arises in the opposite error, when a parallel join waits for a branch that was never activated.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2859db8b-15cd-5d19-812d-c77bc34e03b4', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '182d6e6a-4d8f-54ef-aea9-0046a934197e', 'csit-603/business-process-management/q21', 'mcq', 'evaluate', 'medium', 'Evaluate descriptive versus executable modelling', 'A team wants to run a BPMN model in a process engine such as Camunda. Which additional detail is most essential compared with a descriptive model?', null, null, '[{"id":"a","text":"Brighter colours for lanes"},{"id":"b","text":"Task assignments, form data, service connections and data mappings"},{"id":"c","text":"More text annotations explaining the history of the process"},{"id":"d","text":"Removing all gateways"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2859db8b-15cd-5d19-812d-c77bc34e03b4', '{"option":"b"}'::jsonb, 'Executable models need technical detail so that the engine can assign user tasks, collect data, call services and evaluate conditions. Colours and annotations do not affect execution, and gateways are needed to route tokens.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('67949f97-a49a-51cd-afcd-23b71021405c', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', null, 'csit-603/business-process-management/q22', 'case_analysis', 'evaluate', 'hard', 'Discover, document and model a process in BPMN for a Ghanaian business', 'Plan the discovery of this process, produce a SIPOC, describe a BPMN 2.0 collaboration model of the as-is process (participants, lanes, key events, activities, gateways and message flows) and evaluate what the model reveals.', null, 'Illustrative scenario. Coastline Couriers is a hypothetical logistics firm in Tema. Customers book pickups by phone
or messaging app. A dispatcher writes bookings in a notebook, telephones a driver, and the driver collects the parcel
and returns it to the depot. A depot clerk weighs the parcel and calculates the charge; the customer pays by mobile
money, and only then is the parcel scanned and loaded for delivery. Customers complain about missed pickups and
receive no confirmation; management cannot tell how long each stage takes.', null, 20, array['Discovery plan with triangulated methods', 'SIPOC with a clear process boundary', 'BPMN collaboration model with pools, lanes, events, tasks, gateways and message flows', 'Evaluation of hand-offs, missing information and measurement gaps', 'Recommendations for documentation and next BPM lifecycle steps']::text[], '[{"criterion":"Discovery plan","marks":4,"descriptor":"Combines interviews, observation, document review and any available logs, with validation."},{"criterion":"SIPOC","marks":3,"descriptor":"Correct and specific suppliers, inputs, steps, outputs and customers."},{"criterion":"BPMN model","marks":7,"descriptor":"Correct use of pools, lanes, message flows, labelled gateways and start and end events; no sequence flows across pools."},{"criterion":"Evaluation","marks":4,"descriptor":"Identifies hand-offs, missing confirmations, informal capture and lack of timestamps."},{"criterion":"Recommendations","marks":2,"descriptor":"Sensible documentation (RACI, measures) and next steps."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('67949f97-a49a-51cd-afcd-23b71021405c', '{}'::jsonb, 'Examiners look for correct BPMN rules applied to the case, a triangulated discovery approach and insight drawn from the model, not just a description of symbols.', 'Discovery should combine interviews with dispatchers, drivers and clerks; observation of several bookings end to
end; review of the notebook and mobile money records; and a validation workshop. Because bookings are not in a
system, process mining is not yet possible.

SIPOC: suppliers are customers and the mobile money provider; inputs are booking requests, parcels and payments;
steps are take booking, assign driver, collect parcel, weigh and charge, receive payment, scan and load; outputs
are a collected, paid and loaded parcel; customers are the sender and recipient.

The BPMN collaboration has a Customer pool and a Coastline Couriers pool with lanes for dispatcher, driver and depot
clerk, plus a black-box Mobile money provider pool. A message start event "Booking request received" starts the
firm''s process. Tasks include "Record booking", "Assign driver", "Collect parcel", "Weigh parcel and calculate
charge", "Request payment" and "Scan and load parcel". An exclusive gateway "Driver available?" routes to
"Reschedule pickup". Message flows connect the customer (booking, payment request and payment) and the mobile money
provider (payment confirmation). End event: "Parcel loaded for delivery".

The model reveals that no confirmation message is sent to the customer, the booking exists only on paper, there are
several hand-offs between lanes and no timestamps, so delays cannot be measured. Documentation should add a RACI
matrix and measures such as booking-to-pickup time. Next steps are quantitative analysis and redesign, for example
digital booking capture with automatic confirmation.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1de783f7-33fc-5807-86d2-0505ad70b395', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', null, 'csit-603/business-process-management/q23', 'essay', 'evaluate', 'hard', 'Critically evaluate BPMN as a common language for business and IT', '"BPMN 2.0 succeeds as a common language between business and IT only when modellers follow disciplined style rules." Critically evaluate this statement with reference to BPMN''s elements and semantics, the difference between descriptive and executable models, and practical modelling guidelines.', null, null, null, 20, array['Purpose and standardisation of BPMN 2.0', 'Core elements and token semantics', 'Descriptive versus executable models and their audiences', 'Role of style guidelines and common errors', 'Conclusion on the conditions for BPMN to bridge business and IT']::text[], '[{"criterion":"Knowledge of BPMN","marks":6,"descriptor":"Accurate account of events, activities, gateways, pools, lanes and flows with their behaviour."},{"criterion":"Critical analysis","marks":8,"descriptor":"Weighs BPMN''s precision and interoperability against complexity and readability problems, with examples."},{"criterion":"Style and practice","marks":4,"descriptor":"Applies guidelines such as verb-noun labels, matching gateways and layered models."},{"criterion":"Conclusion","marks":2,"descriptor":"A justified position on the statement."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1de783f7-33fc-5807-86d2-0505ad70b395', '{}'::jsonb, 'Examiners reward accurate BPMN knowledge, critical weighing of the notation''s strengths and limitations and concrete style guidance, rather than a list of symbols.', 'BPMN 2.0, standardised by the OMG in 2011, defines a graphical notation with precise semantics and an XML interchange
format, allowing models to move between tools and be executed by engines such as Camunda. Its core elements are
events, activities and gateways connected by sequence flows within pools and by message flows between pools.

The statement is largely supported. BPMN''s vocabulary is large, and models that use obscure event types, implicit
gateways or inconsistent levels of detail confuse business readers. Errors such as merging parallel branches with an
exclusive gateway produce models that mean something different from what the author intended. Style guidelines from
Silver (2011) and Dumas et al. (2018), such as verb-noun labels, explicit start and end events, labelled gateway
conditions and small layered models, make diagrams readable and correct.

However, style is not the only condition. Descriptive and executable models serve different audiences; one diagram
rarely serves both well without layering. Organisations also need shared conventions, training and governance of
model repositories, and business stakeholders must be involved in validation.

A balanced conclusion accepts that disciplined style is necessary but not sufficient: BPMN bridges business and IT
when models are stylistically disciplined, layered for their audience and governed as shared organisational assets.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
