insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('7b2e010a-de77-541d-9172-61782075b8d5', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', 'c40f1b2f-0fe0-5604-ae27-959fa5fe8b88', 'How does value stream mapping differ from a swimlane map?', 'It emphasises material and information flow and time, including waiting between steps, rather than who performs each activity.', 'supplementary', 'csit-603/business-process-management/461441567700', true)
