insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b47d79f8-4fee-5d24-986a-5a366509f9d2', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '21e77958-7f29-5606-b5c1-81b1f9ebd94d', '182d6e6a-4d8f-54ef-aea9-0046a934197e', 'Compare XOR, AND and OR gateways when splitting.', 'Exclusive (XOR) takes exactly one path; parallel (AND) takes all paths; inclusive (OR) takes every path whose condition is true.', 'supplementary', 'csit-603/business-process-management/1ebff215172c', true)
