insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a96d9049-07b2-5e88-8cdd-267377f0a561', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'csit-603/business-process-reengineering/q01', 'mcq', 'understand', 'easy', 'Explain the definition of BPR', 'Which statement best reflects Hammer and Champy''s (1993) definition of business process re-engineering?', null, null, '[{"id":"a","text":"Small, continuous improvements made by front-line staff"},{"id":"b","text":"Fundamental rethinking and radical redesign of business processes to achieve dramatic improvements in performance"},{"id":"c","text":"Replacing old computers with faster ones"},{"id":"d","text":"Reducing headcount in every department by a fixed percentage"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a96d9049-07b2-5e88-8cdd-267377f0a561', '{"option":"b"}'::jsonb, 'The definition stresses fundamental, radical, dramatic and process-focused change. Small continuous gains describe kaizen; faster computers automate old processes; across-the-board headcount cuts are not redesign.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('735660fe-0772-531c-99f7-e76924e02746', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'csit-603/business-process-reengineering/q02', 'matching', 'apply', 'medium', 'Match Hammer''s principles to examples', 'Match each of Hammer''s (1990) principles to the example that best illustrates it.', null, null, '{"left":[{"id":"l1","text":"Capture information once and at the source"},{"id":"l2","text":"Have those who use the output perform the process"},{"id":"l3","text":"Organise around outcomes, not tasks"},{"id":"l4","text":"Put the decision point where the work is performed"}],"right":[{"id":"r3","text":"One case manager handles a loan application from receipt to decision"},{"id":"r1","text":"Patient details recorded once at registration and reused throughout the visit"},{"id":"r2","text":"Departments order low-value stationery directly from an approved online catalogue"},{"id":"r4","text":"A receiving clerk accepts goods matching an order, triggering payment"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('735660fe-0772-531c-99f7-e76924e02746', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Hammer''s principles are design heuristics. Applying them to concrete examples shows understanding beyond listing. The Ford receiving clerk also illustrates subsuming information processing into the real work.', null)
