insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e4225192-43fc-5122-ba9d-5fc18d5c9b2f', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'csit-603/business-process-reengineering/q03', 'true_false', 'understand', 'easy', 'Recognise Hammer''s argument about automation', 'Hammer (1990) argued that the main opportunity from IT is to automate existing processes so that they run faster.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
