insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b614d087-8d9c-5ff8-96a9-7548d3e0d656', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'csit-603/business-process-reengineering/q05', 'scenario', 'evaluate', 'hard', 'Evaluate whether BPR or continuous improvement is appropriate', 'Which approach is most appropriate?', 'Illustrative scenario. A Kumasi supermarket''s checkout process is broadly efficient, but staff have identified many
small issues, such as poorly placed scanners and slow bagging. Customer satisfaction is reasonable and the
management team has limited capacity for major change this year.', null, '[{"id":"a","text":"Radical re-engineering of the checkout process from a clean sheet"},{"id":"b","text":"Continuous improvement led by front-line staff, addressing the identified issues incrementally"},{"id":"c","text":"Outsourcing the checkout to a third party"},{"id":"d","text":"Doing nothing, because satisfaction is reasonable"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
