insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b614d087-8d9c-5ff8-96a9-7548d3e0d656', '{"option":"b"}'::jsonb, 'The process is broadly sound, the gap is small and change capacity is limited, all of which favour continuous improvement. BPR suits large performance gaps or new enabling technology. Outsourcing is unjustified, and ignoring known issues wastes improvement opportunities.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8e10362c-7d8c-5119-a8f9-3f3a5c079833', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'csit-603/business-process-reengineering/q06', 'mcq', 'analyse', 'medium', 'Analyse the Davenport and Short redesign steps', 'How does Davenport and Short''s (1990) approach differ most clearly from extreme clean-sheet re-engineering?', null, null, '[{"id":"a","text":"It ignores information technology"},{"id":"b","text":"It includes understanding and measuring existing processes before designing new ones"},{"id":"c","text":"It focuses only on individual tasks"},{"id":"d","text":"It forbids prototyping"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8e10362c-7d8c-5119-a8f9-3f3a5c079833', '{"option":"b"}'::jsonb, 'Davenport and Short included "understand and measure existing processes" to avoid repeating mistakes and to provide a baseline. Their approach centres on IT levers, works at process level and ends by designing and building a prototype.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0ee378c8-f84c-542a-8c17-161f467dc2e1', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'csit-603/business-process-reengineering/q07', 'true_false', 'evaluate', 'medium', 'Evaluate criticisms of BPR', 'A common criticism of BPR as practised in the 1990s was that it neglected the human side of change and became associated with downsizing.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0ee378c8-f84c-542a-8c17-161f467dc2e1', '{"value":true}'::jsonb, 'Many programmes were linked with large job cuts and underestimated organisational knowledge and resistance. These criticisms led modern BPM to treat re-engineering as one option alongside explicit change management.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('aa036f17-d8a4-57fa-91e9-fa48bffad62a', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'csit-603/business-process-reengineering/q08', 'matching', 'apply', 'medium', 'Classify steps using value-added analysis', 'Match each pharmacy step to its value-added classification.', null, null, '{"left":[{"id":"l1","text":"Pharmacist counsels the patient on dosage"},{"id":"l2","text":"Recording a controlled drug in the statutory register"},{"id":"l3","text":"Patient waits in a second queue to pay"}],"right":[{"id":"r1","text":"Value-adding"},{"id":"r3","text":"Non-value-adding"},{"id":"r2","text":"Business value-adding"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('aa036f17-d8a4-57fa-91e9-fa48bffad62a', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'Customers value counselling; regulation requires controlled-drug records; waiting adds no value for anyone. BVA steps should be kept but streamlined, and their underlying reasons questioned.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e387ee8e-1538-5b61-bd99-90c23b4a4bae', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'csit-603/business-process-reengineering/q09', 'mcq', 'apply', 'medium', 'Calculate cycle time efficiency', 'A claims process takes 4 days (5,760 minutes) end to end, of which 48 minutes are value-adding work. What is the cycle time efficiency?', null, null, '[{"id":"a","text":"About 0.8%"},{"id":"b","text":"About 8%"},{"id":"c","text":"About 48%"},{"id":"d","text":"About 83%"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e387ee8e-1538-5b61-bd99-90c23b4a4bae', '{"option":"a"}'::jsonb, 'Cycle time efficiency = 48 / 5,760 × 100% ≈ 0.83%. Very low values are common in paper-based service processes and show that waiting, not work, dominates; redesign should target queues and hand-offs.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d7c965a6-c00f-5352-8176-df9843f0c936', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'csit-603/business-process-reengineering/q10', 'scenario', 'analyse', 'hard', 'Identify the bottleneck from capacity data', 'Which step is the bottleneck?', 'Illustrative scenario. A restaurant receives 40 orders per hour at lunchtime. Order taking: 2 waiters at 2 minutes
per order. Cooking: 3 cooks at 4 minutes per order. Payment: 1 cashier at 1 minute per order.', null, '[{"id":"a","text":"Order taking (capacity 60 per hour)"},{"id":"b","text":"Cooking (capacity 45 per hour)"},{"id":"c","text":"Payment (capacity 60 per hour)"},{"id":"d","text":"There is no bottleneck because all capacities exceed demand"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d7c965a6-c00f-5352-8176-df9843f0c936', '{"option":"b"}'::jsonb, 'Capacities are order taking 2 × 60/2 = 60, cooking 3 × 60/4 = 45 and payment 60/1 = 60. Utilisations are 67%, 89% and 67%. Cooking has the highest utilisation and limits throughput. Although all capacities exceed demand, the step with the highest utilisation is still the bottleneck and will generate the longest queues when demand varies.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ca8c65aa-d10d-5f4b-890c-4bae76f481b8', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'csit-603/business-process-reengineering/q11', 'short_answer', 'recall', 'easy', 'Recall the acronym for the seven wastes', 'What acronym is commonly used to remember the seven wastes of transport, inventory, motion, waiting, overproduction, over-processing and defects?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ca8c65aa-d10d-5f4b-890c-4bae76f481b8', '{"answers":["TIMWOOD","TIM WOOD"]}'::jsonb, 'TIMWOOD summarises Ohno''s seven wastes. In service processes, waiting and over-processing (such as re-keying data) are usually the most visible.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('aa87451a-7c86-575d-824a-8777ac7befa1', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'csit-603/business-process-reengineering/q12', 'true_false', 'understand', 'medium', 'Understand the effect of improving non-bottleneck steps', 'Halving processing time at a non-bottleneck step will substantially increase the throughput of the whole process.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('aa87451a-7c86-575d-824a-8777ac7befa1', '{"value":false}'::jsonb, 'Throughput is limited by the bottleneck. Improving another step may reduce its own queue but cases will still wait at the constraint. The Theory of Constraints therefore focuses improvement on the constraint first.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c01f43af-366b-5cf7-bfc7-21597b9d1433', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'csit-603/business-process-reengineering/q13', 'mcq', 'apply', 'medium', 'Apply Little''s law', 'A clinic sees 25 patients per hour and each patient spends an average of 2 hours in the clinic. Using Little''s law, how many patients are in the clinic on average?', null, null, '[{"id":"a","text":"12.5"},{"id":"b","text":"25"},{"id":"c","text":"50"},{"id":"d","text":"27"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c01f43af-366b-5cf7-bfc7-21597b9d1433', '{"option":"c"}'::jsonb, 'Work in progress = throughput × cycle time = 25 × 2 = 50 patients. Halving cycle time would halve crowding, which is why reducing waiting improves both experience and space use.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1ebde09d-40de-5e8a-8e85-603385786d8f', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'csit-603/business-process-reengineering/q14', 'scenario', 'evaluate', 'hard', 'Evaluate a root-cause analysis', 'What is the best evaluation of the managers'' conclusion?', 'Illustrative scenario. A distributor''s managers conclude that late deliveries are caused by lazy drivers and plan
disciplinary action. A Pareto count of 200 late deliveries shows 120 caused by orders released to the warehouse
after the daily loading cut-off, 40 by vehicle breakdowns, 25 by wrong addresses and 15 by driver delays.', null, '[{"id":"a","text":"It is correct; driver discipline will solve most late deliveries"},{"id":"b","text":"It is unsupported; most late deliveries stem from late order release, so the order-release process should be investigated first"},{"id":"c","text":"Vehicle breakdowns are the main cause and should be addressed first"},{"id":"d","text":"The data is irrelevant because lateness is a cultural issue"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1ebde09d-40de-5e8a-8e85-603385786d8f', '{"option":"b"}'::jsonb, 'The Pareto data shows 60% of late deliveries come from late order release, a process issue, and only 7.5% from drivers. A 5 Whys analysis of late release should follow. Breakdowns matter but are secondary; dismissing data leads to blaming people for system problems.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d1bf665f-a94f-51f6-aa77-75a3d2ad878e', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'd9b8bb17-3612-50e0-97e7-8c8dcec9328a', 'csit-603/business-process-reengineering/q15', 'matching', 'apply', 'medium', 'Match redesign changes to heuristics', 'Match each redesign change to the heuristic it applies.', null, null, '{"left":[{"id":"l1","text":"Verify the prescription before taking payment"},{"id":"l2","text":"Prepare food and drinks at the same time"},{"id":"l3","text":"Route simple repeat prescriptions to a nurse-led clinic"},{"id":"l4","text":"Remove retrieval of paper folders"},{"id":"l5","text":"One officer handles a customer''s claim end to end"}],"right":[{"id":"r2","text":"Parallelism"},{"id":"r4","text":"Task elimination"},{"id":"r1","text":"Resequencing"},{"id":"r5","text":"Case manager"},{"id":"r3","text":"Triage"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d1bf665f-a94f-51f6-aa77-75a3d2ad878e', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Naming the heuristic shows why a change works and what trade-offs to expect, as described by Reijers and Limam Mansar (2005).', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f839a831-bddb-53b5-a5fe-0d50b98dd879', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'd9b8bb17-3612-50e0-97e7-8c8dcec9328a', 'csit-603/business-process-reengineering/q16', 'mcq', 'recall', 'easy', 'Recall the ADKAR sequence', 'Which sequence correctly lists the ADKAR elements?', null, null, '[{"id":"a","text":"Awareness, Desire, Knowledge, Ability, Reinforcement"},{"id":"b","text":"Ability, Desire, Knowledge, Awareness, Results"},{"id":"c","text":"Analysis, Design, Knowledge, Action, Review"},{"id":"d","text":"Awareness, Delivery, Kick-off, Adoption, Reward"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f839a831-bddb-53b5-a5fe-0d50b98dd879', '{"option":"a"}'::jsonb, 'ADKAR (Hiatt, 2006) describes the individual''s progression: understanding why, wanting to change, knowing how, being able to perform and having the change reinforced.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('cbadbb27-1268-51d4-9698-a96a8788e58d', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'd9b8bb17-3612-50e0-97e7-8c8dcec9328a', 'csit-603/business-process-reengineering/q17', 'scenario', 'analyse', 'medium', 'Diagnose an ADKAR barrier point', 'At which ADKAR element is the main barrier, and what intervention fits best?', 'Illustrative scenario. Nurses at a hospital have attended training on a new electronic triage protocol and pass the
knowledge test, but many still use paper forms. In interviews they say the new screens are fine but they see no
reason to change because "the old way works and doctors still ask for paper".', null, '[{"id":"a","text":"Knowledge; repeat the training"},{"id":"b","text":"Desire; involve nurses and doctors, explain benefits and secure doctors'' visible support for the new protocol"},{"id":"c","text":"Ability; buy faster computers"},{"id":"d","text":"Reinforcement only; introduce penalties immediately"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('cbadbb27-1268-51d4-9698-a96a8788e58d', '{"option":"b"}'::jsonb, 'Nurses know how to use the system but do not want to, partly because doctors'' behaviour undermines it. That is a desire barrier, addressed through involvement, sponsorship and consistent behaviour by clinical leaders. Repeating training ignores the real barrier; hardware is not the issue; penalties without addressing desire breed resistance.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0593797a-9122-5655-b2cd-106cf7c52822', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'd9b8bb17-3612-50e0-97e7-8c8dcec9328a', 'csit-603/business-process-reengineering/q18', 'true_false', 'understand', 'medium', 'Understand Kotter''s warning about early victory', 'According to Kotter, declaring victory too soon after early wins is a common cause of failed transformations.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0593797a-9122-5655-b2cd-106cf7c52822', '{"value":true}'::jsonb, 'Kotter (1995) warned that short-term wins should be used to consolidate gains and drive further change (step 7), and that change must be anchored in culture (step 8) before it is safe to relax.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b9a3fae9-6e0b-5d99-8d62-5326d07e558b', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'd9b8bb17-3612-50e0-97e7-8c8dcec9328a', 'csit-603/business-process-reengineering/q19', 'short_answer', 'recall', 'easy', 'Recall the first of Kotter''s eight steps', 'What is the first of Kotter''s eight steps for leading change?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
