insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b9a3fae9-6e0b-5d99-8d62-5326d07e558b', '{"answers":["establish a sense of urgency","create a sense of urgency","create urgency","establish urgency","sense of urgency"]}'::jsonb, 'Without urgency, people stay with familiar practices. Urgency should be built on evidence, such as waiting-time data and customer complaints, not fear.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('532936e3-443d-5de7-8e2f-24a9cff96c0b', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'd9b8bb17-3612-50e0-97e7-8c8dcec9328a', 'csit-603/business-process-reengineering/q20', 'mcq', 'evaluate', 'hard', 'Evaluate trade-offs in a redesign using the Devil''s Quadrangle', 'A logistics firm proposes fully automating delivery scheduling so that the system assigns all routes. Which evaluation best reflects the Devil''s Quadrangle?', null, null, '[{"id":"a","text":"It will improve time, cost, quality and flexibility simultaneously"},{"id":"b","text":"It may improve time and consistency but can reduce flexibility for unusual deliveries, so exception handling should be designed in"},{"id":"c","text":"It has no effect on performance dimensions"},{"id":"d","text":"It will always increase cost and should be rejected"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('532936e3-443d-5de7-8e2f-24a9cff96c0b', '{"option":"b"}'::jsonb, 'Automation often brings speed and consistency but can make processes rigid for exceptions. A balanced design keeps a route for human override. Claims of improvement on every dimension, or automatic rejection, ignore trade-offs.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('377a51c1-eeef-5a8b-b155-5e537e1cf2f9', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'd9b8bb17-3612-50e0-97e7-8c8dcec9328a', 'csit-603/business-process-reengineering/q21', 'mcq', 'analyse', 'medium', 'Analyse the Mutual Benefit Life redesign', 'Which feature of Mutual Benefit Life''s redesign, as described by Hammer (1990), most clearly made change management essential?', null, null, '[{"id":"a","text":"It changed the colour of application forms"},{"id":"b","text":"It replaced chains of specialists with case managers, fundamentally changing job roles and skills"},{"id":"c","text":"It moved the head office to a new city"},{"id":"d","text":"It reduced the number of insurance products"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('377a51c1-eeef-5a8b-b155-5e537e1cf2f9', '{"option":"b"}'::jsonb, 'The case manager design turned narrow specialist jobs into broad, accountable roles supported by shared data and expert-system tools. Such role changes require new skills, measures and leadership support. The other options were not features of the case.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e4f4d84a-6d18-5bda-a5eb-1e51cf0d0db0', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', null, 'csit-603/business-process-reengineering/q22', 'case_analysis', 'evaluate', 'hard', 'Analyse, redesign and plan change for a Ghanaian process', 'Analyse the as-is process quantitatively and qualitatively, propose a to-be process using redesign heuristics and Hammer''s principles, estimate its effects and trade-offs, and design a change management plan using Kotter''s eight steps and ADKAR.', null, 'Illustrative scenario. Golden Spoon is a hypothetical restaurant chain with four branches in Accra. At lunchtime
each branch receives about 60 orders per hour. Waiters write orders on paper, walk them to the kitchen and later
re-key them into the till for payment. Three cooks handle all dishes at about 3.5 minutes per order; two waiters take
orders at about 1.5 minutes each; one cashier takes payment at about 1 minute per order. Customers wait on average
35 minutes for food and 10 minutes to pay. Kitchen errors (wrong dishes) are frequent, and many are traced to
unreadable handwriting. Staff fear that any new system will be used to cut jobs.', null, 25, array['Quantitative analysis (capacity, utilisation, bottleneck) and qualitative analysis (VA, BVA, NVA and wastes)', 'Root-cause analysis of kitchen errors', 'To-be process with named heuristics and principles', 'Estimated effects and Devil''s Quadrangle trade-offs', 'Change management plan using Kotter and ADKAR, including the job-loss concern']::text[], '[{"criterion":"Quantitative analysis","marks":5,"descriptor":"Correct capacities and utilisations, identification of the bottleneck and interpretation."},{"criterion":"Qualitative analysis and root cause","marks":5,"descriptor":"Classifies steps, names relevant wastes and traces errors to information capture."},{"criterion":"Redesign","marks":6,"descriptor":"Coherent to-be design linking each change to a problem and naming heuristics or principles."},{"criterion":"Evaluation of effects","marks":4,"descriptor":"Reasoned estimates, trade-offs and recognition that a pilot is needed."},{"criterion":"Change management","marks":5,"descriptor":"Applies Kotter''s steps and ADKAR to specific stakeholder groups, addressing job security honestly."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e4f4d84a-6d18-5bda-a5eb-1e51cf0d0db0', '{}'::jsonb, 'Examiners reward correct calculations, explicit links between analysis and redesign, realistic trade-offs and a change plan tailored to stakeholders rather than a generic list of Kotter''s steps.', 'Capacities: waiters 2 × 60/1.5 = 80 orders per hour (75% utilised); cooks 3 × 60/3.5 ≈ 51 per hour (about 117%
utilised); cashier 60 per hour (100% utilised). The kitchen is the bottleneck, which explains the 35-minute wait;
the cashier is at full capacity, explaining the payment queue. Qualitatively, walking orders to the kitchen is
transport and motion waste, re-keying into the till is over-processing, and wrong dishes are defects. A 5 Whys
chain traces errors to handwritten orders, that is, information not captured once and electronically.

A to-be design applies "capture information once at the source": waiters enter orders on handheld devices that send
them directly to a kitchen display and the till (task elimination of re-keying, removing transport). Payment can be
taken at the table by card or mobile money (resequencing and parallelism), removing the cashier queue. To exploit
the kitchen constraint, the menu could be triaged into quick and complex dishes with a dedicated station for quick
items, and simple preparation could be moved before the lunch peak; a fourth cook at peak would raise capacity to
about 69 per hour (about 87% utilised).

Estimated effects include fewer errors, shorter food and payment waits and better data on demand. Trade-offs include
investment in devices, dependence on connectivity and some loss of flexibility for unusual requests. A pilot in one
branch should validate the estimates.

Change management: establish urgency using wait-time and error data; form a coalition of branch managers, a head
cook and respected waiters; communicate a vision of faster, accurate service; address job fears honestly, for
example by committing to redeploy time to customer service; generate a short-term win in the pilot branch;
consolidate and roll out; anchor the change in training and performance measures. ADKAR assessment by group
(waiters, cooks, cashiers) identifies barriers, such as cashiers'' desire, given that their role changes most.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e698d728-46ce-5b1d-bdc9-1c49f721fcdc', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', null, 'csit-603/business-process-reengineering/q23', 'essay', 'evaluate', 'hard', 'Critically evaluate the relevance of BPR today', '"Business process re-engineering was a 1990s fad; today organisations need only continuous improvement and automation." Critically evaluate this statement with reference to Hammer (1990), Hammer and Champy (1993), the criticisms of BPR and contemporary enterprise technologies.', null, null, null, 20, array['Definition and principles of BPR', 'Evidence from classic cases (Ford, Mutual Benefit Life)', 'Criticisms of BPR and lessons learned', 'Role of continuous improvement and automation today', 'Reasoned conclusion on the place of radical redesign']::text[], '[{"criterion":"Understanding of BPR","marks":5,"descriptor":"Accurate definition, key words and principles."},{"criterion":"Use of cases and literature","marks":5,"descriptor":"Appropriate, accurate use of Ford and Mutual Benefit Life and of Hammer, Champy and Davenport."},{"criterion":"Critical evaluation","marks":7,"descriptor":"Weighs criticisms against continued relevance, including the risk of automating broken processes."},{"criterion":"Conclusion","marks":3,"descriptor":"A justified, nuanced position."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e698d728-46ce-5b1d-bdc9-1c49f721fcdc', '{}'::jsonb, 'Examiners look for accurate use of the literature and cases, genuine engagement with criticisms and a nuanced conclusion that relates BPR to contemporary technology.', 'An effective essay defines BPR as the fundamental rethinking and radical redesign of processes for dramatic
improvement (Hammer & Champy, 1993) and summarises Hammer''s (1990) principles, such as organising around outcomes and
capturing information once at the source.

Classic cases show the power of radical redesign: Ford''s invoiceless processing challenged the assumption that
payment requires an invoice, and Mutual Benefit Life replaced specialist chains with case managers supported by
shared data. These changes were not achievable by incremental improvement alone.

The statement draws strength from BPR''s criticisms: many programmes became vehicles for downsizing, ignored people
and failed in implementation, and the term fell out of fashion. Continuous improvement methods such as Lean and Six
Sigma deliver sustained gains with lower risk.

However, the claim that automation and continuous improvement suffice is weak. Hammer''s central warning, that
automating an obsolete process merely makes it obsolete faster, applies directly to modern workflow automation,
robotic process automation and cloud ERP. New technologies such as mobile money, shared cloud databases and process
engines create opportunities for fundamentally different designs, as BPR anticipated.

A balanced conclusion argues that the label "BPR" may be dated but radical, IT-enabled redesign remains relevant
within modern BPM, combined with continuous improvement for refinement and with explicit change management to
avoid the failures of the 1990s.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4b511b26-9cc0-5b32-aa1d-db725d8808ce', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'What are the four key words in Hammer and Champy''s definition of BPR?', 'Fundamental (question why), radical (go to the root), dramatic (step-change improvement) and processes (end-to-end focus).', 'supplementary', 'csit-603/business-process-reengineering/5f8ddbbe7d52', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('fd5429ea-373e-54a1-96bc-a445647d919d', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'What did Hammer mean by "Don''t automate, obliterate"?', 'Automating processes designed for paper only speeds up obsolete work; IT should enable fundamentally new process designs.', 'supplementary', 'csit-603/business-process-reengineering/fe3ed6a4c212', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('40d3c0ba-4b2f-53e5-8284-2d265eed3a80', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'Name four of Hammer''s (1990) re-engineering principles.', 'Organise around outcomes; have users of the output perform the process; subsume information processing into real work; capture information once at the source (also treat dispersed resources as centralised, link parallel activities, decide where work is done).', 'supplementary', 'csit-603/business-process-reengineering/2fd8feff3fc6', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e75e56e9-4ada-5e9b-ad02-2e0af0ac3a57', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'How did Ford re-engineer accounts payable?', 'Purchasing entered orders in a shared database; receiving accepted goods matching an order and the system authorised payment, replacing three-document matching ("invoiceless processing").', 'supplementary', 'csit-603/business-process-reengineering/969db09b9294', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('33b06c25-9483-5411-84bb-0eafe121b694', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'What are Davenport and Short''s (1990) five redesign steps?', 'Develop the business vision and process objectives; identify processes to redesign; understand and measure existing processes; identify IT levers; design and build a prototype.', 'supplementary', 'csit-603/business-process-reengineering/6adbedeec6cb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('507a3ae1-e71e-57ac-920d-34bcd62d3cf1', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', '0096741b-5098-5985-b429-d978b1b0d3c2', 'When is BPR preferable to continuous improvement?', 'When the performance gap is large, new technology enables a different design, the process is strategically important and cross-functional, and leaders can sponsor major change.', 'supplementary', 'csit-603/business-process-reengineering/515a77ef80d3', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('deb67d8e-5e25-55d7-afc5-fb083105b21f', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'Distinguish VA, BVA and NVA steps.', 'Value-adding steps are valued by the customer; business value-adding steps are needed by the business or regulation; non-value-adding steps add value for neither and should be eliminated.', 'supplementary', 'csit-603/business-process-reengineering/6b258d10a845', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a7c239ea-c76b-56ed-aad6-ff04c09be82c', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'What are the seven wastes (TIMWOOD)?', 'Transport, inventory, motion, waiting, overproduction, over-processing and defects.', 'supplementary', 'csit-603/business-process-reengineering/3900ee205a88', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('dad703cc-eabe-571d-8ac3-e4132870aba4', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'How is cycle time efficiency calculated, and what does a low value suggest?', 'Value-adding time ÷ total cycle time × 100%; a low value shows that waiting and hand-offs, not work, dominate elapsed time.', 'supplementary', 'csit-603/business-process-reengineering/3a14b8069357', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bdfc2f29-a928-575f-b5c5-f5ac865f8fcc', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'How do you identify a bottleneck?', 'Calculate capacity (servers × 60 ÷ minutes per case) and utilisation (demand ÷ capacity) for each resource; the highest utilisation is the bottleneck.', 'supplementary', 'csit-603/business-process-reengineering/ebefe1097589', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5433064a-311b-5f15-a851-320e4660d9db', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'What are the Theory of Constraints'' five focusing steps?', 'Identify the constraint, exploit it, subordinate everything else to it, elevate it, then repeat.', 'supplementary', 'csit-603/business-process-reengineering/8fe3a242c150', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f9f6fb87-9cfd-5379-9f84-55aa176a4b56', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'fae248fe-665d-526c-a139-c5e86735de37', 'f6e36b0c-e09e-569b-9fc1-8e9d9bb3063c', 'What does Little''s law state?', 'Work in progress = throughput × cycle time, so reducing cycle time reduces queues and crowding.', 'supplementary', 'csit-603/business-process-reengineering/43d04ed62bcb', true)
