insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'enterprise-implementation', 'Enterprise Implementation', 'Delivering an enterprise system successfully, from requirements to evaluation.', 5, true)
  on conflict (id) do update set course_id = excluded.course_id, slug = excluded.slug, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.lessons (id, module_id, slug, title, summary, topics, estimated_minutes, difficulty, source, content, word_count, sort_order, is_published) values ('307c2a19-dfa2-5544-b34e-7b362d7cb027', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'implementation-strategies-and-requirements', 'ERP Implementation Strategies and Requirements Gathering', 'Compare big bang, phased, parallel and pilot implementation strategies, justify a choice for a given organisation, and plan a requirements-gathering programme that produces prioritised, traceable requirements.', array['ERP implementation strategies', 'Big bang', 'Phased', 'Parallel', 'Requirements gathering']::text[], 50, 'intermediate', 'supplementary', '{"introduction":"Buying an enterprise resource planning (ERP) system is the easy part. Putting it to work across finance, procurement, inventory, sales and human resources, while the business keeps trading, is where most of the risk lies. Two early decisions shape almost everything that follows: *how* the new system will replace the old ways of working (the implementation strategy), and *what* the system must actually do (the requirements). A poor strategy can expose the whole business to a single point of failure on go-live day; poor requirements can produce a technically successful project that nobody can use.\n\nThis lesson treats implementation as a managed organisational change rather than a software installation. You will compare the classic implementation strategies, learn when each is defensible, and then work through the techniques analysts use to elicit, document, prioritise and validate requirements. The lesson closes with a famous international failure and an illustrative Ghanaian scenario so that you can practise justifying a strategy with evidence rather than preference.","objectives":["Explain the phases of the enterprise systems life cycle and the decisions made in each.","Compare big bang, phased (by module and by site), parallel and pilot implementation strategies using explicit criteria such as risk, cost, time and organisational readiness.","Apply requirements-gathering techniques, including interviews, workshops, observation, document analysis and prototyping, to an enterprise system project.","Construct prioritised, testable requirements using MoSCoW and a fit-gap analysis.","Evaluate an implementation plan for risks arising from timing, scope and readiness."],"prerequisites":["Familiarity with ERP modules and best-practice processes (Enterprise Applications module).","Basic understanding of process mapping and BPMN from the Business Process Management module.","Awareness of change-management models such as Kotter''s eight steps."],"keyTerms":[{"term":"Implementation strategy","definition":"The approach used to move an organisation from its legacy systems and processes to the new enterprise system, for example big bang or phased."},{"term":"Big bang","definition":"A strategy in which all modules and all sites switch to the new system at a single cut-over point."},{"term":"Phased roll-out","definition":"A strategy in which the system is introduced incrementally, by module, by business unit or by geography."},{"term":"Parallel running","definition":"Operating the legacy and new systems side by side for a period and comparing outputs before retiring the old system."},{"term":"Pilot implementation","definition":"Deploying the full system at one site or unit first, learning from it, then rolling it out elsewhere."},{"term":"Functional requirement","definition":"A statement of what the system must do, such as \"record a goods receipt against a purchase order\"."},{"term":"Non-functional requirement","definition":"A statement of a quality the system must have, such as availability, response time, security or usability."},{"term":"Fit-gap analysis","definition":"A structured comparison of required processes against the standard capability of a package, classifying each as fit, configurable, gap requiring workaround, or gap requiring development."},{"term":"Requirements traceability matrix (RTM)","definition":"A table linking each requirement to its source, priority, design element and test case."},{"term":"MoSCoW","definition":"A prioritisation scheme classifying requirements as Must have, Should have, Could have or Won''t have this time."}],"body":[{"heading":"The Enterprise Systems Life Cycle","markdown":"Markus and Tanis (2000) describe the enterprise systems experience as a sequence of phases, each with its own typical problems. A useful adaptation for planning purposes is:\n\n1. **Chartering**: the business case, scope, budget, sponsor and high-level strategy are agreed. Problems here (unrealistic expectations, weak sponsorship) are inherited by every later phase.\n2. **Project (configuration and roll-out)**: requirements are gathered, the package is configured, data is migrated, the system is tested and users are trained, ending at go-live.\n3. **Shakedown**: the period from go-live until \"normal operation\" is reached. Performance typically dips as staff learn new procedures and defects surface.\n4. **Onward and upward**: the organisation stabilises, realises benefits, and plans upgrades and extensions.\n\nThe value of this model is that it reminds project teams that success at go-live is not the same as business success. A project can be on time and on budget and still fail in shakedown if process changes were not understood. The implementation strategy is essentially a decision about how much shakedown risk the organisation will accept at once."},{"heading":"Comparing Implementation Strategies","markdown":"### Big bang\n\nAll modules go live together on a single date, usually after a weekend or holiday cut-over. Benefits are realised quickly, there is no need to build temporary interfaces between old and new systems, and the organisation moves to one version of the truth at once. The disadvantage is concentration of risk: if order-to-cash fails on Monday, there is no legacy system to fall back on without a costly rollback.\n\n### Phased roll-out\n\nThe system is introduced in stages. A *module-phased* approach might start with finance and procurement, then add inventory and sales. A *site-phased* approach might start with the head office, then regional branches. Phasing spreads the learning load and allows lessons from early phases to improve later ones. The price is a longer programme, and the need for temporary \"bridge\" interfaces so that, say, a new finance module can receive transactions from a legacy sales system.\n\n### Parallel running\n\nBoth systems process the same transactions for a period, and outputs (trial balances, stock valuations, payroll totals) are reconciled. Parallel running provides the strongest fallback, but it doubles the workload for staff who must key data twice, and differences between the systems are often due to legitimate process redesign rather than errors, which makes reconciliation hard to interpret. It is most defensible for narrow, high-consequence processes such as payroll.\n\n### Pilot\n\nA complete version of the system goes live at one representative site. The pilot tests both the software and the training and support model in real conditions. Pilots work well for multi-branch businesses with similar operations, such as a pharmacy or supermarket chain.\n\n| Criterion | Big bang | Phased (module or site) | Parallel | Pilot then roll-out |\n|---|---|---|---|---|\n| Speed to full benefit | Fastest | Slow | Medium | Medium |\n| Concentration of risk | Very high | Low to medium | Low | Medium (contained to pilot) |\n| Temporary interfaces needed | None | Many | Few | Some, during roll-out |\n| Staff workload | Intense peak | Spread out | Very high (double entry) | High at pilot site |\n| Fallback options | Weak | Good | Strong | Good for later sites |\n| Best suited to | Small, simple, highly integrated firms; strong readiness | Large, diverse organisations | Narrow, high-risk processes such as payroll | Multi-site firms with standardised operations |\n\nIn practice organisations frequently combine strategies: a pilot branch, then site-phased roll-out, with parallel running only for payroll.\n\n### Choosing a strategy: a decision procedure\n\n1. **Assess integration density.** If inventory, sales and finance are tightly coupled, phasing by module needs many bridges; big bang or pilot may be cleaner.\n2. **Assess organisational readiness.** Count trained super-users, the stability of master data and the maturity of IT support. Low readiness argues against big bang.\n3. **Map the business calendar.** Never schedule cut-over near peak trading, financial year-end or statutory reporting deadlines.\n4. **Quantify the cost of failure.** Estimate revenue at risk per day of disruption; high values justify the cost of pilots or parallel running.\n5. **Agree rollback criteria in advance.** Define the conditions under which the team will revert, and test the rollback procedure."},{"heading":"Requirements Gathering","markdown":"Requirements describe the future state the system must support. In package implementations, the aim is not to specify software from scratch but to decide how far the organisation will adopt the package''s built-in processes and where genuine gaps exist.\n\n### Techniques\n\n| Technique | What it produces | Strengths | Limitations |\n|---|---|---|---|\n| Structured interviews | Detailed individual perspectives | Depth, confidentiality | Time-consuming; tells you what people say they do |\n| Facilitated workshops (for example joint application design) | Agreed cross-functional process designs | Builds consensus, resolves hand-off conflicts | Dominant voices; needs skilled facilitation |\n| Observation and job shadowing | Actual work practices, workarounds | Reveals tacit knowledge | Observer effect; limited sample |\n| Document and data analysis | Forms, reports, transaction volumes | Objective evidence, sizing data | Documents may be out of date |\n| Questionnaires | Broad view across many sites | Scale, comparability | Shallow; low response rates |\n| Prototyping and conference-room pilots | Feedback on configured screens and flows | Concrete, exposes misunderstandings early | Users may fixate on cosmetic issues |\n| Process mining of event logs | Evidence-based as-is process variants | Objective, quantifies variation | Needs clean event data |\n\nGood practice triangulates: workshops propose the future design, observation and data analysis check it against reality, and conference-room pilots validate it on the configured system.\n\n### Writing good requirements\n\nEach requirement should be **atomic** (one need per statement), **testable** (a tester can say pass or fail), **traceable** (linked to a source and an owner) and **solution-neutral** where possible. Compare \"the system should be user-friendly\" (untestable) with \"a trained cashier must complete a three-item sale with mobile money payment in under 60 seconds\" (testable)."},{"heading":"Worked Example: Fit-Gap and MoSCoW for a Distributor","markdown":"*Illustrative scenario.* A Kumasi-based distributor of building materials is implementing a mid-market ERP. Workshops have produced the requirements below. The analyst classifies each against the package''s standard capability and assigns a MoSCoW priority.\n\n| ID | Requirement | Source | Fit-gap result | MoSCoW | Treatment |\n|---|---|---|---|---|---|\n| R01 | Record customer orders with credit-limit checking | Sales workshop | Fit (standard) | Must | Configure credit rules |\n| R02 | Accept mobile money payments and match them to invoices | Finance interviews | Gap (needs integration) | Must | Build interface to payment aggregator |\n| R03 | Print invoices with legally required tax details | Document analysis | Configurable | Must | Configure output form |\n| R04 | Track deliveries with digital address of the site | Logistics observation | Gap (minor) | Should | Add custom field |\n| R05 | Commission calculation for sales agents using a bespoke formula | Sales manager interview | Gap (development) | Could | Defer; calculate in spreadsheet initially |\n| R06 | Replicate the legacy system''s green-screen menu layout | User questionnaire | Gap | Won''t | Reject; train users on new layout |\n\nThe analysis gives the steering committee a defensible scope. Three Must requirements are fits or configurations; one Must gap (R02) is a genuine integration need and goes into the integration plan; R05 is deferred to protect the timeline; and R06 is rejected because it would customise the package to preserve a legacy habit rather than a business need. A simple metric is the **fit rate**: here, two of six requirements are standard fits and one more is configurable, so half of the requirements are met without gaps. Each row then enters the requirements traceability matrix, gaining a design reference and a test case."},{"heading":"Ghanaian Business Application","markdown":"*Illustrative scenario.* A pharmacy chain with a head office in Accra and twelve branches across Greater Accra, Ashanti and the Western Region plans to replace branch-level spreadsheets and a standalone accounting package with an integrated ERP covering procurement, inventory with batch and expiry tracking, point of sale and finance.\n\nA big bang across all thirteen locations would be risky: branch staff have varied computer literacy, connectivity outside major towns can be intermittent, and dispensing errors carry patient-safety consequences. A defensible recommendation is a **pilot then site-phased** strategy: go live first at one busy Accra branch close to head office support, stabilise for several weeks, then roll out in waves of three or four branches. Finance and procurement go live at head office with the pilot, so that central purchasing is consistent from the start. Cut-over dates avoid month-end and the December festive trading period.\n\nRequirements gathering combines branch observation (to see how pharmacists actually check expiry dates and handle prescriptions), workshops with procurement and finance, document analysis of supplier invoices and National Health Insurance claim forms, and a conference-room pilot in which pharmacists process realistic transactions on the configured system. Non-functional requirements receive explicit attention: offline capability for point of sale during network outages, role-based access to controlled medicines, and protection of patient data consistent with Ghana''s Data Protection Act, 2012 (Act 843)."},{"heading":"International Case Study: Hershey''s 1999 ERP Go-Live","markdown":"The Hershey Foods Corporation in the United States implemented an integrated set of enterprise applications in the late 1990s, including SAP R/3 for core ERP, together with supply chain planning and customer relationship management software from other vendors. It is widely reported that the project schedule was compressed and that the company chose to switch over many functions together in July 1999. That timing placed the shakedown period directly before Hershey''s busiest trading season, Halloween. The company subsequently experienced serious order-processing and shipment problems, and publicly attributed disappointing results in the second half of 1999 partly to these difficulties.\n\nThe lessons for strategy selection are clear. First, the business calendar should constrain the go-live date, not the other way round. Second, a combined go-live of tightly integrated order, warehouse and planning functions concentrates shakedown risk exactly where errors are most visible to customers. Third, compressing testing to meet a date removes the evidence on which a go or no-go decision should rest. A phased or pilot approach, or simply a go-live after the peak season, would have reduced exposure."},{"heading":"Diagram","markdown":"```mermaid\nflowchart TD\n    A[\"Chartering: business case, scope, sponsor\"] --> B[\"Requirements gathering: interviews, workshops, observation, data analysis\"]\n    B --> C[\"Fit-gap analysis and MoSCoW prioritisation\"]\n    C --> D{\"Choose implementation strategy\"}\n    D -->|\"High readiness, simple firm\"| E[\"Big bang\"]\n    D -->|\"Large, diverse organisation\"| F[\"Phased by module or site\"]\n    D -->|\"Narrow high-risk process\"| G[\"Parallel running\"]\n    D -->|\"Multi-site, standard operations\"| H[\"Pilot then roll-out\"]\n    E --> I[\"Go-live and shakedown\"]\n    F --> I\n    G --> I\n    H --> I\n    I --> J[\"Onward and upward: benefits realisation\"]\n```"}],"misconceptions":["\"Big bang is always reckless.\" Correction: for a small, well-prepared organisation with highly integrated processes, big bang can be the lowest-risk option because it avoids fragile temporary interfaces.","\"Parallel running is the safest strategy, so it should always be used.\" Correction: parallel running doubles workload, is hard to reconcile when processes have been redesigned, and is usually justified only for narrow, high-consequence processes.","\"Requirements gathering means asking users what they want.\" Correction: users describe current practice and preferences; analysts must also observe, analyse data and challenge requirements against business objectives and package best practice.","\"Every gap should be closed by customisation.\" Correction: many gaps are better closed by changing the process, using configuration, or deferring the requirement; custom code raises upgrade and support costs."],"examMistakes":["Describing strategies without comparing them against explicit criteria or recommending one for the case given.","Recommending big bang or phased roll-out without reference to the organisation''s calendar, readiness or integration density.","Writing vague requirements such as \"fast\" or \"easy to use\" instead of measurable statements.","Confusing functional and non-functional requirements.","Ignoring the shakedown phase and treating go-live as the end of the project."],"criticalQuestions":["Under what conditions might a pilot site give misleading evidence about how the rest of the organisation will cope with a new ERP?","Is the high concentration of risk in a big bang implementation offset by the avoidance of temporary interfaces? How would you assess this trade-off for a specific firm?","How should an analyst respond when a senior manager insists that a \"Won''t have\" requirement is essential?","To what extent does adopting a package''s best-practice processes reduce an organisation''s ability to differentiate itself from competitors?"],"exercises":["**Strategy recommendation.** For the illustrative pharmacy chain above, write a one-page memo to the steering committee recommending an implementation strategy. Expected output: a memo that scores at least three strategies against five criteria in a table and justifies the recommendation with reference to readiness, calendar and risk.","**BPMN in Camunda Modeler or Bizagi Modeler.** Model the future-state \"receive supplier delivery\" process for the pharmacy chain, including batch and expiry capture and a gateway for rejecting short-dated stock. Expected output: a BPMN 2.0 diagram with at least two lanes (store clerk, pharmacist), one exclusive gateway and a message flow to the supplier pool, exported as an image.","**Requirements traceability.** Write ten requirements for the pharmacy chain''s point-of-sale process (at least three non-functional), classify each with MoSCoW and fit-gap, and add a test case reference. Expected output: a completed requirements traceability matrix.","**SAP Learning activity.** Create a free account on SAP Learning and complete an introductory learning journey on SAP S/4HANA or SAP Activate. Expected output: a 300-word reflection explaining how the vendor''s recommended phases compare with the Markus and Tanis life cycle."],"takeaways":["Implementation strategy is a decision about how much risk to concentrate at one go-live.","Big bang, phased, parallel and pilot approaches each suit different contexts; hybrid strategies are common.","The business calendar, organisational readiness and integration density should drive the choice.","Requirements must be atomic, testable, traceable and prioritised; fit-gap analysis favours process change and configuration over custom code.","Success at go-live is not success: plan explicitly for shakedown."],"furtherReading":[{"text":"Markus, M. L., & Tanis, C. (2000). The enterprise systems experience: From adoption to success. In R. W. Zmud (Ed.), *Framing the domains of IT management: Projecting the future through the past*. Pinnaflex Educational Resources.","url":null,"verification":"citation"},{"text":"Monk, E., & Wagner, B. (2013). *Concepts in enterprise resource planning* (4th ed.). Cengage Learning.","url":null,"verification":"citation"},{"text":"Davenport, T. H. (1998). Putting the enterprise into the enterprise system. *Harvard Business Review, 76*(4), 121-131.","url":null,"verification":"citation"},{"text":"Nah, F. F.-H., Lau, J. L.-S., & Kuang, J. (2001). Critical factors for successful implementation of enterprise systems. *Business Process Management Journal, 7*(3), 285-296.","url":null,"verification":"citation"},{"text":"Dumas, M., La Rosa, M., Mendling, J., & Reijers, H. A. (2018). *Fundamentals of business process management* (2nd ed.). Springer.","url":null,"verification":"citation"}],"videos":[{"title":"SAP Learning","url":"https://learning.sap.com/","description":"SAP. Free learning journeys, including introductions to SAP S/4HANA and the SAP Activate implementation methodology.","verification":"verified"},{"title":"Microsoft Learn: Dynamics 365 training","url":"https://learn.microsoft.com/training/dynamics365/","description":"Microsoft. Self-paced modules on implementing and using Dynamics 365 business applications.","verification":"verified"},{"title":"Camunda documentation","url":"https://docs.camunda.io/","description":"Camunda. Official guides to the Camunda Modeler for BPMN process modelling.","verification":"verified"}],"revisionSummary":"Implementation strategy and requirements gathering are the two early decisions that most shape ERP outcomes. Strategies range from big bang (fast but risky) through phased and pilot roll-outs (slower, contained risk) to parallel running (strong fallback, heavy workload). Choose using readiness, integration density, the business calendar and the cost of failure. Requirements should be gathered by triangulating interviews, workshops, observation, data analysis and prototyping, then prioritised with MoSCoW and tested against the package with fit-gap analysis.\n\n- Markus and Tanis phases: chartering, project, shakedown, onward and upward.\n- Big bang: no bridges, high risk; phased: many bridges, low risk.\n- Parallel running suits narrow, high-consequence processes such as payroll.\n- Good requirements are atomic, testable, traceable and prioritised.\n- Prefer process change and configuration over customisation.\n- Hershey (1999): go-live timing collided with peak season."}'::jsonb, 2999, 1, true)
  on conflict (id) do update set module_id = excluded.module_id, slug = excluded.slug, title = excluded.title, summary = excluded.summary, topics = excluded.topics, estimated_minutes = excluded.estimated_minutes, difficulty = excluded.difficulty, source = excluded.source, content = excluded.content, word_count = excluded.word_count, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.lessons (id, module_id, slug, title, summary, topics, estimated_minutes, difficulty, source, content, word_count, sort_order, is_published) values ('644ad992-bd04-5030-84e3-9a4125edba24', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'vendor-selection', 'Vendor Selection', 'Run a structured enterprise software selection, build and stress-test a weighted scoring model, and calculate a multi-year total cost of ownership to justify a recommendation.', array['Vendor selection', 'Total cost of ownership', 'Weighted scoring']::text[], 50, 'intermediate', 'supplementary', '{"introduction":"Choosing an enterprise system is one of the largest and least reversible technology decisions an organisation makes. The chosen package will shape processes, skills, data structures and supplier relationships for a decade or more. Yet selections are often driven by an impressive demonstration, a senior manager''s prior experience or the lowest headline licence price. None of these is a sound basis for a commitment of that scale.\n\nThis lesson presents vendor selection as a disciplined, evidence-based procedure. You will learn the stages of a selection, how to design weighted scoring criteria that reflect business priorities, how to test whether the result is robust, and how to calculate total cost of ownership (TCO) so that options with very different cost profiles, such as on-premise licences and cloud subscriptions, can be compared fairly.","objectives":["Explain the stages of a structured enterprise software selection from long list to contract.","Design weighted evaluation criteria that reflect an organisation''s strategic and operational priorities.","Apply a weighted scoring model to compare vendors and perform sensitivity analysis on the weights.","Calculate and interpret a five-year total cost of ownership for alternative deployment options.","Evaluate contractual and relationship factors, including service levels, exit terms and local implementation support."],"prerequisites":["Understanding of ERP modules and of fit-gap analysis from the previous lesson.","Basic spreadsheet skills (multiplication, summation).","Awareness of the differences between on-premise and cloud deployment."],"keyTerms":[{"term":"Request for information (RFI)","definition":"An early, lightweight document asking vendors to describe their products and capabilities so that a long list can be reduced."},{"term":"Request for proposal (RFP)","definition":"A formal document setting out requirements, evaluation criteria and commercial terms, to which shortlisted vendors respond with detailed proposals."},{"term":"Scripted demonstration","definition":"A demonstration in which each vendor must run the buyer''s own scenarios and data, rather than a generic sales presentation."},{"term":"Weighted scoring model","definition":"A decision tool in which each criterion receives a weight reflecting its importance, each option is scored against each criterion, and weighted scores are summed."},{"term":"Sensitivity analysis","definition":"Testing whether the ranking of options changes when weights or scores are varied within plausible ranges."},{"term":"Total cost of ownership (TCO)","definition":"The full cost of acquiring, implementing, operating, supporting and eventually exiting a system over a defined period."},{"term":"Service level agreement (SLA)","definition":"A contractual commitment specifying measurable service standards such as availability and response times, with remedies for failure."},{"term":"Vendor lock-in","definition":"Dependence on a supplier that makes switching costly because of proprietary data formats, customisations or contractual terms."}],"body":[{"heading":"The Selection Process","markdown":"A structured selection reduces the influence of bias and sales pressure by fixing the criteria before vendors are met.\n\n1. **Confirm the business case and scope.** Restate objectives (for example, a single view of stock across branches) and the modules in scope.\n2. **Agree requirements and criteria.** Use the prioritised requirements from requirements gathering. Agree evaluation criteria and their weights with the steering committee *before* contacting vendors.\n3. **Market scan and RFI.** Identify a long list of perhaps eight to twelve candidate products, including vendors'' local partners. Use RFI responses to eliminate products that clearly do not fit size, sector or budget.\n4. **RFP to a short list.** Issue the RFP to three to five vendors. Require responses to each Must requirement in a fixed format (standard, configurable, third-party add-on, custom development).\n5. **Scripted demonstrations.** Give each vendor the same scenarios, for example \"receive a delivery with two batches of different expiry dates, then sell from the earlier batch\". Score live, using the agreed sheet.\n6. **Reference checks and site visits.** Speak to customers of similar size and sector, ideally ones the vendor did not choose for you.\n7. **Proof of concept (optional).** For high-risk gaps such as a mobile money integration, ask the leading vendor to prove feasibility.\n8. **Commercial negotiation and due diligence.** Assess financial stability, product roadmap, partner capacity and contract terms.\n9. **Recommendation and contract.** Present scores, TCO and risks to the decision-makers.\n\nSelecting the **implementation partner** deserves equal attention. Many failures attributed to software are, on investigation, failures of the integrator''s capacity, methodology or knowledge of the client''s industry."},{"heading":"Theories, Frameworks and Models","markdown":"### Multi-criteria decision analysis\n\nWeighted scoring is a simple form of multi-criteria decision analysis. Its strengths are transparency and the ability to combine dissimilar factors. Its weaknesses are well known: weights are subjective; scores on a 1-5 scale imply false precision; and a high score on one criterion can compensate for a fatal weakness on another. Good practice therefore combines weighted scoring with **knock-out criteria** (any vendor failing a Must requirement is excluded regardless of total score) and with sensitivity analysis.\n\n### Cost-benefit and TCO thinking\n\nHeadline licence price is typically a minority of lifetime cost. TCO models classify costs as acquisition (licences, hardware), implementation (consulting, data migration, training, internal backfill), operation (maintenance, subscriptions, hosting, support staff) and change (upgrades, enhancements, exit). Benefits are assessed separately, often in the business case, and the two are combined in measures such as payback period or net present value.\n\n### Fit and misfit\n\nPackage selection is fundamentally about fit between organisational processes and the package''s embedded processes. Davenport (1998) argued that an enterprise system imposes its own logic on a company''s strategy, culture and organisation. A low-fit package forces either extensive customisation or radical process change; both are costly, and organisations should know which they are choosing."},{"heading":"Worked Example: Weighted Scoring with Sensitivity Analysis","markdown":"*Illustrative scenario.* A Tema-based distribution company has short-listed three ERP products, labelled A, B and C. All three pass the knock-out criteria. The steering committee agreed the weights below before the demonstrations; each product is scored from 1 (poor) to 5 (excellent).\n\n| Criterion | Weight | A score | A weighted | B score | B weighted | C score | C weighted |\n|---|---|---|---|---|---|---|---|\n| Functional fit to requirements | 0.30 | 4 | 1.20 | 5 | 1.50 | 3 | 0.90 |\n| Five-year TCO (cheaper scores higher) | 0.20 | 3 | 0.60 | 2 | 0.40 | 5 | 1.00 |\n| Vendor viability and local support | 0.15 | 4 | 0.60 | 3 | 0.45 | 3 | 0.45 |\n| Technical architecture and integration | 0.15 | 4 | 0.60 | 4 | 0.60 | 3 | 0.45 |\n| Usability | 0.10 | 3 | 0.30 | 4 | 0.40 | 4 | 0.40 |\n| Implementation partner capability | 0.10 | 4 | 0.40 | 3 | 0.30 | 3 | 0.30 |\n| **Total** | **1.00** | | **3.70** | | **3.65** | | **3.50** |\n\nEach weighted score is `weight × score`; for example, product A''s functional fit is `0.30 × 4 = 1.20`. Product A ranks first, but the margin over B is only 0.05, which is well within the uncertainty of subjective 1-5 scores.\n\n**Sensitivity test.** Suppose the finance director argues that cost should weigh 0.30 and functional fit 0.20. Recalculating:\n\n- A: `0.20×4 + 0.30×3 + 0.15×4 + 0.15×4 + 0.10×3 + 0.10×4 = 0.80 + 0.90 + 0.60 + 0.60 + 0.30 + 0.40 = 3.60`\n- B: `0.20×5 + 0.30×2 + 0.60 + 0.60 + 0.40 + 0.30` (other criteria unchanged) `= 1.00 + 0.60 + 0.45 + 0.60 + 0.40 + 0.30 = 3.35`\n- C: `0.20×3 + 0.30×5 + 0.45 + 0.45 + 0.40 + 0.30 = 0.60 + 1.50 + 0.45 + 0.45 + 0.40 + 0.30 = 3.70`\n\nThe ranking now changes: C leads. **Interpretation:** the decision hinges on how the organisation trades functional fit against cost. That is a strategic question for the steering committee, not an arithmetic one. The analyst''s job is to make the trade-off explicit and to explore whether C''s lower fit could be compensated by process change, or whether A''s better fit justifies the extra cost."},{"heading":"Worked Example: Five-Year Total Cost of Ownership","markdown":"*Illustrative scenario.* The same company compares an on-premise deployment (perpetual licence) with a cloud subscription. All figures are hypothetical, in Ghana cedis (GHS), undiscounted.\n\n| Cost element | On-premise (5 years) | Cloud subscription (5 years) |\n|---|---|---|\n| Licences (one-off) | 600,000 | n/a |\n| Annual maintenance (20% of licence × 5) | 600,000 | n/a |\n| Subscription (300,000 × 5) | n/a | 1,500,000 |\n| Servers, storage, backup hardware | 250,000 | n/a |\n| Implementation services | 500,000 | 400,000 |\n| Internal IT support staff (150,000 or 80,000 per year × 5) | 750,000 | 400,000 |\n| Training | 80,000 | 80,000 |\n| Major upgrade in year 4 | 150,000 | included |\n| Additional connectivity and redundancy (60,000 × 5) | n/a | 300,000 |\n| **Five-year TCO** | **2,930,000** | **2,680,000** |\n\nYear-one cash outlay differs even more sharply: on-premise requires `600,000 + 120,000 + 250,000 + 500,000 + 150,000 + 80,000 = 1,700,000`, while cloud requires `300,000 + 400,000 + 80,000 + 80,000 + 60,000 = 920,000`.\n\n**Interpretation.** Over five years cloud is cheaper by 250,000, and it shifts spending from capital to operating expenditure. However, the conclusion is sensitive to assumptions: if the subscription price rises each year, if the vendor prices in US dollars and the cedi weakens, or if the system is retained for ten years, the on-premise option may become cheaper. A rigorous analysis would discount cash flows to present value, model currency exposure, and add exit costs such as data extraction at contract end."},{"heading":"Ghanaian Business Application","markdown":"Selection criteria for Ghanaian organisations often need local emphasis:\n\n- **Local partner capacity.** A strong global product with no experienced partner in Ghana may be riskier than a regional product with a capable Accra-based integrator.\n- **Localisation.** Statutory reporting, value added tax and payroll deductions must be supported, and changes in tax rules must be deliverable quickly.\n- **Payment integration.** Native or proven connectors to mobile money and local bank payment platforms are increasingly a Must requirement.\n- **Currency and pricing.** Contracts priced in foreign currency expose the buyer to exchange-rate movements; this belongs in TCO sensitivity analysis.\n- **Infrastructure resilience.** Cloud options must be assessed against connectivity at every site, including backup links and offline modes.\n- **Data protection.** Where personal data is processed, the buyer must be satisfied that the vendor''s arrangements are consistent with the Data Protection Act, 2012 (Act 843)."},{"heading":"International Case Study: Lidl and the Cost of Misfit","markdown":"In 2018 the German discount retailer Lidl announced that it was stopping a multi-year project to replace its in-house merchandise management system with a solution based on SAP software, and would return to developing its own system. The project had been running for several years. Press reports at the time suggested that a significant difficulty was Lidl''s long-established practice of valuing inventory on purchase prices, whereas the standard package logic was oriented to retail prices, so that adapting the software required substantial customisation.\n\nThe case illustrates why functional fit and the cost of closing gaps belong at the centre of a selection. When a package''s core logic conflicts with a deeply embedded business practice, the organisation faces a stark choice: change the practice or customise the package heavily. If neither choice is made consciously during selection, the conflict tends to surface later, when sunk costs are high."},{"heading":"Diagram","markdown":"```mermaid\nflowchart LR\n    A[\"Business case and scope\"] --> B[\"Criteria and weights agreed\"]\n    B --> C[\"Market scan and RFI: long list\"]\n    C --> D[\"RFP: short list of 3 to 5\"]\n    D --> E[\"Scripted demonstrations scored live\"]\n    E --> F[\"Reference checks and proof of concept\"]\n    F --> G[\"Weighted scoring, knock-outs, sensitivity\"]\n    G --> H[\"Five-year TCO and risk assessment\"]\n    H --> I[\"Negotiation: SLA, exit terms, pricing\"]\n    I --> J[\"Recommendation and contract\"]\n```"}],"misconceptions":["\"The vendor with the highest total score must be chosen.\" Correction: small differences in subjective scores are not meaningful; sensitivity analysis, knock-out criteria and risk judgement should inform the final decision.","\"Cloud ERP is always cheaper.\" Correction: cloud usually reduces upfront cost, but over a long horizon recurring subscriptions, price increases and currency exposure can make it more expensive.","\"Licence price is the main cost.\" Correction: implementation, internal staff time, training, support and upgrades usually exceed the licence cost over the life of the system.","\"Weights can be adjusted after demonstrations to reflect what we learned.\" Correction: changing weights after seeing vendors invites bias towards a favoured product; weights should be fixed in advance and sensitivity tested instead."],"examMistakes":["Presenting a weighted scoring table without showing how weighted scores were calculated.","Using weights that do not sum to 1 (or 100%).","Comparing licence prices rather than total cost of ownership over the same time horizon.","Ignoring the implementation partner and local support in the evaluation.","Recommending a vendor without discussing the robustness of the result or its risks."],"criticalQuestions":["How could a buyer reduce the influence of an impressive but unrepresentative sales demonstration?","Should TCO be included as a weighted criterion in the scoring model, or kept separate and compared against the score? Justify your view.","When might a lower-fit but lower-cost package be the better strategic choice?","What contractual terms would most protect a mid-sized Ghanaian firm against vendor lock-in?"],"exercises":["**Weighted scoring model.** Build the weighted scoring table from this lesson in a spreadsheet using formulas, then add a fourth vendor with scores of your choice. Expected output: a spreadsheet in which changing any weight updates totals automatically, plus a note on which weight changes alter the ranking.","**TCO extension.** Extend the TCO example to ten years, assuming the subscription rises by 5% a year from year two and the on-premise system needs a second major upgrade in year eight costing 200,000. Expected output: a ten-year table and a 150-word interpretation stating which option is cheaper and why.","**Scripted demonstration in BPMN.** In Bizagi Modeler or Camunda Modeler, model one demonstration scenario (for example, \"return of damaged goods to a supplier with credit note\") that every vendor must run. Expected output: a BPMN diagram plus a scoring sheet listing what evaluators should observe at each task.","**SAP Learning activity.** On SAP Learning, review the free introductory material on SAP''s cloud ERP offerings. Expected output: a list of five questions you would ask any vendor during scripted demonstrations, based on what you learned."],"takeaways":["Fix criteria and weights before meeting vendors, and use knock-out criteria for Must requirements.","Weighted scoring makes trade-offs transparent but is sensitive to subjective weights; always test sensitivity.","TCO, not licence price, is the correct basis for cost comparison, and it depends heavily on time horizon and assumptions.","Evaluate the implementation partner and local support as seriously as the software.","Misfit between package logic and core business practice is a major hidden cost."],"furtherReading":[{"text":"Monk, E., & Wagner, B. (2013). *Concepts in enterprise resource planning* (4th ed.). Cengage Learning.","url":null,"verification":"citation"},{"text":"Davenport, T. H. (1998). Putting the enterprise into the enterprise system. *Harvard Business Review, 76*(4), 121-131.","url":null,"verification":"citation"},{"text":"Markus, M. L., & Tanis, C. (2000). The enterprise systems experience: From adoption to success. In R. W. Zmud (Ed.), *Framing the domains of IT management: Projecting the future through the past*. Pinnaflex Educational Resources.","url":null,"verification":"citation"},{"text":"Mell, P., & Grance, T. (2011). *The NIST definition of cloud computing* (NIST Special Publication 800-145). National Institute of Standards and Technology.","url":"https://doi.org/10.6028/NIST.SP.800-145","verification":"verified"}],"videos":[{"title":"SAP Learning","url":"https://learning.sap.com/","description":"SAP. Free learning journeys introducing SAP''s ERP products and deployment options.","verification":"verified"},{"title":"Oracle University","url":"https://education.oracle.com/","description":"Oracle. Official training portal with introductory material on Oracle''s cloud ERP applications.","verification":"unreachable"},{"title":"Microsoft Learn: Dynamics 365 training","url":"https://learn.microsoft.com/training/dynamics365/","description":"Microsoft. Self-paced modules describing Dynamics 365 finance and operations capabilities.","verification":"verified"}],"revisionSummary":"Vendor selection should be a structured, evidence-based process: agree requirements, criteria and weights first; move from long list (RFI) to short list (RFP); require scripted demonstrations; check references; and negotiate with due diligence. Weighted scoring combines dissimilar criteria transparently but must be supported by knock-out criteria and sensitivity analysis. TCO captures acquisition, implementation, operation and change costs over a fixed horizon and often reverses conclusions drawn from licence price alone.\n\n- Weighted score = sum of weight × score; weights sum to 1.\n- Small score differences are not decisive; test sensitivity.\n- TCO includes internal staff, training, upgrades and exit costs.\n- Cloud lowers upfront cost; long horizons and currency risk can reverse the advantage.\n- Choose the implementation partner as carefully as the product.\n- Lidl (2018): misfit with a core valuation practice proved decisive."}'::jsonb, 2514, 2, true)
  on conflict (id) do update set module_id = excluded.module_id, slug = excluded.slug, title = excluded.title, summary = excluded.summary, topics = excluded.topics, estimated_minutes = excluded.estimated_minutes, difficulty = excluded.difficulty, source = excluded.source, content = excluded.content, word_count = excluded.word_count, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.lessons (id, module_id, slug, title, summary, topics, estimated_minutes, difficulty, source, content, word_count, sort_order, is_published) values ('c47f138c-f91b-5c80-bedd-fc5d99f947b7', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'data-migration-and-integration', 'Data Migration and System Integration', 'Plan an extract-transform-load data migration with cleansing and reconciliation controls, and select appropriate integration patterns for connecting an ERP with surrounding systems.', array['Data migration', 'System integration']::text[], 50, 'advanced', 'supplementary', '{"introduction":"An enterprise system is only as trustworthy as the data inside it. On go-live day, users will judge the new system by whether customer balances are right, whether stock on the screen matches stock on the shelf, and whether suppliers are paid correctly. All of those depend on data that has been extracted from legacy systems, cleaned, transformed and loaded. Data migration is consistently underestimated because it looks like a technical copying exercise; in reality it forces the organisation to confront years of duplicated, incomplete and inconsistent records.\n\nEqually, no ERP stands alone. It must exchange data with point-of-sale terminals, banking and mobile money platforms, e-commerce sites, tax systems, logistics partners and analytics tools. This lesson covers both halves of the problem: moving data *into* the new system safely, and connecting the new system *to* everything around it.","objectives":["Explain the stages of an extract-transform-load (ETL) data migration and the roles responsible for each.","Apply data cleansing techniques, including profiling, de-duplication, standardisation and enrichment, to legacy master data.","Design reconciliation controls (record counts, control totals and sample checks) and interpret discrepancies.","Compare integration patterns such as point-to-point, hub-and-spoke, enterprise service bus, API-led and event-driven integration.","Evaluate migration and integration risks using a real-world failure."],"prerequisites":["Understanding of master data and transactional data from the Enterprise Databases and Analytics lesson.","Familiarity with APIs and middleware from the Enterprise Architecture and Integration lesson.","Basic knowledge of relational tables and keys."],"keyTerms":[{"term":"Data migration","definition":"The one-time (or few-time) transfer of data from legacy systems into a new system, including its transformation into the new system''s structures."},{"term":"ETL (extract, transform, load)","definition":"The sequence of extracting data from sources, transforming it into the target format and rules, and loading it into the target system."},{"term":"Data profiling","definition":"Statistical examination of source data to discover patterns, null rates, duplicates and invalid values before cleansing."},{"term":"Data cleansing","definition":"Correcting, standardising, de-duplicating and enriching data so it meets the target system''s quality rules."},{"term":"Mapping specification","definition":"A document defining, field by field, how each source attribute becomes a target attribute, including transformation rules and default values."},{"term":"Reconciliation","definition":"Proving that migrated data is complete and accurate by comparing record counts, control totals and samples between source and target."},{"term":"Open items","definition":"Transactions not yet complete at cut-over, such as unpaid invoices or undelivered purchase orders, which must be migrated as live balances."},{"term":"Integration pattern","definition":"A reusable approach to connecting systems, such as point-to-point, hub-and-spoke or publish-subscribe messaging."},{"term":"Idempotency","definition":"The property of an interface whereby processing the same message twice produces the same result as processing it once, preventing duplicate postings."}],"body":[{"heading":"The Data Migration Life Cycle","markdown":"### What to migrate\n\nThe first decision is scope. Most projects migrate:\n\n- **Master data**: customers, suppliers, products, chart of accounts, employees, bills of materials, price lists.\n- **Open items and balances**: open receivables and payables, open orders, stock on hand by location and batch, general ledger opening balances.\n- **Limited history**: sometimes one or two years of summarised history for reporting.\n\nFull transactional history is rarely migrated, because it multiplies effort and risk. Instead the legacy system is archived in read-only form for enquiry and audit. A clear **data retention decision** prevents months of argument later.\n\n### Stages\n\n1. **Profile** the source data to quantify problems: duplicate customers, missing tax identifiers, products with no unit of measure, negative stock.\n2. **Define quality rules and mapping** with business data owners, not only IT staff. Each target field needs a source, a transformation rule and an owner.\n3. **Cleanse at source where possible.** Correcting data in the legacy system means corrected records flow into every trial migration.\n4. **Extract** data into a staging area, frozen at an agreed time.\n5. **Transform** by applying mappings, code conversions (for example, old product categories to new ones), unit-of-measure conversions and default values.\n6. **Validate** against target rules before loading, producing an error report for business correction.\n7. **Load** using the vendor''s supported tools and interfaces so that business logic and validations in the target are respected.\n8. **Reconcile** counts, totals and samples, and obtain formal sign-off from data owners.\n9. **Rehearse.** Run several full trial migrations (\"mock loads\") before cut-over, timing each one, so that the final load fits inside the cut-over window.\n\n### Cleansing techniques\n\n| Problem found in profiling | Technique | Example |\n|---|---|---|\n| Duplicate records | Matching and merging using fuzzy rules on name, phone and address | \"Kofi Mensah Enterprise\" and \"Kofi Mensah Ent.\" with the same phone number merged |\n| Inconsistent formats | Standardisation | Phone numbers converted to one international format |\n| Missing mandatory values | Enrichment from other sources or business follow-up | Missing tax identifiers collected from customers before cut-over |\n| Invalid codes | Code mapping tables | Old unit \"CTN\" mapped to new unit \"Carton\" |\n| Obsolete records | Archival rules | Customers with no activity for several years not migrated |"},{"heading":"Worked Example: Reconciling a Customer Migration","markdown":"*Illustrative scenario.* A wholesale company in Takoradi migrates customer master data and open receivables. The control report after the final mock load is:\n\n| Control | Legacy source | After cleansing | Loaded to ERP | Difference |\n|---|---|---|---|---|\n| Customer records | 12,480 | 11,950 | 11,915 | 35 |\n| Open invoices | 8,204 | 8,204 | 8,151 | 53 |\n| Total open receivables (GHS) | 4,862,350.00 | 4,862,350.00 | 4,858,100.00 | 4,250.00 |\n\n**Step 1: explain the cleansing difference.** 12,480 − 11,950 = 530 records removed. The cleansing log must show that all 530 were duplicates merged into surviving records, and that their open invoices were reassigned to the survivors. Because the receivables total did not change between the source and cleansed columns, the merge preserved value.\n\n**Step 2: explain the load difference.** 11,950 − 11,915 = 35 customers rejected by the ERP''s validation, for example because a mandatory region code was blank. Those 35 customers own 53 open invoices worth 4,250.00. The analyst confirms this by summing the rejected invoices in the error file: if they total exactly 4,250.00, the difference is fully explained.\n\n**Step 3: decide.** The 35 records are corrected and reloaded before cut-over, and the reconciliation is re-run until all differences are zero or explicitly explained and accepted by the finance controller. A **sample check** follows: the controller selects, say, 30 random customers and compares balances, credit limits and contact details on screen against legacy reports.\n\nThe principle is that *every* difference must be either eliminated or explained and signed off. An unexplained difference, however small, suggests a mapping error that may affect other records."},{"heading":"Integration Patterns","markdown":"Integration connects the ERP to surrounding applications. Hohpe and Woolf (2003) catalogued many messaging patterns; at the architectural level the main options are:\n\n| Pattern | How it works | Strengths | Weaknesses | Typical use |\n|---|---|---|---|---|\n| Point-to-point | Each pair of systems has its own custom interface | Quick for one or two links | Number of links grows rapidly; brittle \"spaghetti\" | Small firms with few systems |\n| File-based batch | Systems exchange files on a schedule | Simple, robust, tolerant of downtime | Data is only as fresh as the last batch | Nightly bank statement import |\n| Hub-and-spoke or enterprise service bus (ESB) | A central middleware routes and transforms messages | Central monitoring, reuse of transformations | Hub can become a bottleneck and single point of failure | Large organisations with many systems |\n| API-led | Systems expose documented, versioned APIs (often REST) | Reusable, real-time, suits cloud and mobile | Needs API governance and security | E-commerce site checking ERP stock |\n| Event-driven (publish-subscribe) | Systems publish events; interested systems subscribe | Loose coupling, scalable, near real-time | Harder to trace end-to-end; eventual consistency | \"Goods received\" event updating several systems |\n| Integration platform as a service (iPaaS) | Cloud-hosted middleware with pre-built connectors | Fast for common SaaS connections | Subscription cost, vendor dependence | Linking cloud ERP with cloud CRM |\n\nWith `n` systems, fully connected point-to-point integration can require up to `n × (n − 1) / 2` links: 6 for four systems, but 45 for ten. A hub reduces that to `n` connections, which is the essential argument for middleware.\n\n### Design considerations\n\n- **Synchronous or asynchronous?** A cashier waiting for a payment confirmation needs a synchronous response; posting the day''s sales to the general ledger can be asynchronous.\n- **Error handling.** Every interface needs retry rules, a queue for failed messages and a named person who monitors it.\n- **Idempotency and sequencing.** If a mobile money confirmation is received twice, the invoice must not be paid twice.\n- **Security.** Authenticate every call, encrypt data in transit and log access.\n- **Ownership of master data.** Decide which system is the \"system of record\" for each entity, so that customer data is not edited in three places."},{"heading":"Ghanaian Business Application","markdown":"*Illustrative scenario.* A mid-sized supermarket group in Accra replaces separate branch inventory systems with a cloud ERP. Migration challenges include product codes that differ by branch for the same item, products recorded in mixed units (single, pack, carton), and supplier records lacking tax identification numbers. The team creates a single product master keyed on the GS1 barcode where one exists, with an internal code for loose and locally packaged goods, and runs three mock loads timed against a planned Saturday-night cut-over.\n\nIntegration requirements include branch point-of-sale terminals posting sales to the ERP in near real time (with local storage when connectivity drops, synchronised later), mobile money payment confirmations received through an aggregator''s API and matched to transactions, nightly bank statement files for reconciliation, and supplier price-list uploads. An API-led design with a small integration layer is chosen so that a future e-commerce site can reuse the same stock and price APIs."},{"heading":"International Case Study: TSB''s 2018 Platform Migration","markdown":"In April 2018 the UK bank TSB migrated its customer accounts from systems operated by its former parent, Lloyds Banking Group, to a new platform built for it by its new owner, Banco Sabadell. The migration was carried out over a single weekend. In the days that followed, many customers were unable to access online and mobile banking or saw incorrect information, and the disruption continued for an extended period. TSB''s chief executive later stood down, an independent review was commissioned, and UK regulators subsequently fined the bank in connection with the failings.\n\nFor students of enterprise implementation, the case shows that a single-event migration of a large, complex data estate concentrates risk; that readiness evidence (testing results, performance under real load, the capability of suppliers) must be independently challenged before a go decision; and that a credible fallback plan is essential. It also illustrates that migration success is measured by customers'' experience after cut-over, not by whether the data was technically copied."},{"heading":"Diagram","markdown":"```mermaid\nflowchart LR\n    A[\"Legacy systems\"] --> B[\"Extract to staging (frozen snapshot)\"]\n    B --> C[\"Profile and cleanse: de-duplicate, standardise, enrich\"]\n    C --> D[\"Transform using mapping specification\"]\n    D --> E{\"Validate against target rules\"}\n    E -->|\"Errors\"| F[\"Error report to data owners\"]\n    F --> C\n    E -->|\"Valid\"| G[\"Load to ERP via supported tools\"]\n    G --> H[\"Reconcile: counts, control totals, samples\"]\n    H --> I[\"Sign-off by data owners\"]\n```"}],"misconceptions":["\"Data migration is an IT task.\" Correction: business data owners must define quality rules, correct errors and sign off reconciliations; IT provides tools and execution.","\"We should migrate all historical transactions so nothing is lost.\" Correction: migrating full history multiplies cost and risk; archiving the legacy system for enquiry usually meets audit and reporting needs.","\"If record counts match, the migration is correct.\" Correction: counts can match while values are wrong; control totals and sample checks are also needed.","\"An enterprise service bus is always better than point-to-point.\" Correction: for a firm with two or three systems, middleware may add cost and complexity without benefit."],"examMistakes":["Listing ETL stages without explaining cleansing, validation and reconciliation.","Treating reconciliation as a single count comparison.","Recommending an integration pattern without linking it to the number of systems, latency needs and error handling.","Forgetting open items and balances when scoping migration.","Describing a real case such as TSB with invented figures rather than the well-documented facts."],"criticalQuestions":["Should poor-quality legacy data be cleansed before migration, during transformation, or after go-live? What are the trade-offs?","How would you decide which system is the system of record for customer data when both the ERP and a CRM can edit it?","Is a single-weekend migration ever justified for a large organisation? What evidence would you require before approving it?","How does event-driven integration change the way auditors should trace a transaction?"],"exercises":["**Mapping specification.** For a product master with ten legacy fields, write a mapping specification to a target ERP structure, including at least three transformation rules and one default value. Expected output: a table with source field, target field, rule, owner and validation.","**Reconciliation.** Using the worked example, suppose the error file of rejected invoices totals 3,900.00 rather than 4,250.00. Expected output: a short explanation of what this implies and the investigation steps you would take.","**BPMN cut-over model.** In Camunda Modeler, model the migration rehearsal process from \"freeze legacy data\" to \"sign-off\", including a loop back for errors and a timer event for the cut-over deadline. Expected output: a BPMN diagram with an exclusive gateway, a loop and a boundary timer event.","**SAP Learning activity.** On SAP Learning, search for free material on data migration to SAP S/4HANA. Expected output: a 250-word summary of the vendor-supported migration approach and how it relates to the ETL stages in this lesson."],"takeaways":["Migrate master data, open items and balances; archive most history.","Cleanse at source, rehearse with mock loads and time them against the cut-over window.","Reconcile with counts, control totals and samples; every difference must be eliminated or explained and signed off.","Choose integration patterns by number of systems, latency, error handling and governance needs.","Define a system of record for each master data entity."],"furtherReading":[{"text":"Hohpe, G., & Woolf, B. (2003). *Enterprise integration patterns: Designing, building, and deploying messaging solutions*. Addison-Wesley.","url":null,"verification":"citation"},{"text":"Monk, E., & Wagner, B. (2013). *Concepts in enterprise resource planning* (4th ed.). Cengage Learning.","url":null,"verification":"citation"},{"text":"Kimball, R., & Ross, M. (2013). *The data warehouse toolkit: The definitive guide to dimensional modeling* (3rd ed.). Wiley.","url":null,"verification":"citation"},{"text":"Markus, M. L., & Tanis, C. (2000). The enterprise systems experience: From adoption to success. In R. W. Zmud (Ed.), *Framing the domains of IT management: Projecting the future through the past*. Pinnaflex Educational Resources.","url":null,"verification":"citation"}],"videos":[{"title":"SAP Learning","url":"https://learning.sap.com/","description":"SAP. Free learning journeys including material on data migration and integration for SAP S/4HANA.","verification":"verified"},{"title":"Microsoft Learn: Power Automate documentation","url":"https://learn.microsoft.com/power-automate/","description":"Microsoft. Official guidance on connectors and automated data flows between business applications.","verification":"verified"},{"title":"Camunda documentation","url":"https://docs.camunda.io/","description":"Camunda. Guides to modelling and orchestrating processes that span several systems.","verification":"verified"}],"revisionSummary":"Data migration moves master data, open items and balances into the new system through extract, profile, cleanse, transform, validate, load and reconcile, rehearsed in several mock loads. Reconciliation uses record counts, control totals and samples, and every difference must be explained and signed off by business owners. Integration connects the ERP with surrounding systems through patterns ranging from point-to-point and batch files to hubs, APIs and events; the right choice depends on scale, latency and governance.\n\n- Profile first; cleanse at source where possible.\n- Counts plus control totals plus samples prove completeness and accuracy.\n- Point-to-point links grow as n(n − 1)/2; hubs reduce this to n.\n- Design interfaces for errors, retries and idempotency.\n- Decide the system of record for each master data entity.\n- TSB (2018): single-weekend migration with severe customer impact."}'::jsonb, 2519, 3, true)
  on conflict (id) do update set module_id = excluded.module_id, slug = excluded.slug, title = excluded.title, summary = excluded.summary, topics = excluded.topics, estimated_minutes = excluded.estimated_minutes, difficulty = excluded.difficulty, source = excluded.source, content = excluded.content, word_count = excluded.word_count, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.lessons (id, module_id, slug, title, summary, topics, estimated_minutes, difficulty, source, content, word_count, sort_order, is_published) values ('7777fef8-7874-55dc-9848-2a06747ca876', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'training-testing-deployment-and-evaluation', 'User Training, Testing, Deployment and Post-Implementation Evaluation', 'Design a test strategy and role-based training plan, build a cut-over plan with go/no-go criteria, and evaluate an enterprise system after go-live using measurable post-implementation review metrics.', array['User training', 'Testing', 'Deployment', 'Post-implementation evaluation']::text[], 55, 'intermediate', 'supplementary', '{"introduction":"The final stretch of an enterprise implementation is where plans meet reality. The system must be proven to work (testing), people must be able to use it (training), the organisation must switch over without losing control of its operations (deployment and cut-over), and the investment must be shown to deliver what the business case promised (post-implementation evaluation). Each of these activities is often squeezed when earlier phases overrun, which is exactly why failures cluster around go-live.\n\nThis lesson gives you practical tools for each activity: a map of test types and who owns them, a role-based training design, a cut-over runbook with go/no-go criteria, and a set of post-implementation review metrics with a worked calculation. Throughout, the emphasis is on evidence: a go-live decision should rest on test results and readiness measures, not optimism.","objectives":["Distinguish the main test types used in enterprise implementations and identify who owns each.","Design a role-based training plan using super-users, sandboxes and train-the-trainer approaches.","Construct a cut-over plan with a timeline, go/no-go criteria and a rollback procedure.","Apply post-implementation review metrics to evaluate whether an implementation achieved its objectives.","Evaluate a real deployment failure in terms of testing, training and readiness."],"prerequisites":["Implementation strategies and requirements traceability (earlier lessons in this module).","Data migration and reconciliation concepts.","Change-management models (Kotter, ADKAR) from the Business Process Re-engineering module."],"keyTerms":[{"term":"User acceptance testing (UAT)","definition":"Testing by business users, using realistic scenarios and data, to confirm that the system supports their processes and meets agreed requirements."},{"term":"Regression testing","definition":"Re-running previously passed tests after a change to confirm that nothing that worked before has broken."},{"term":"Performance (load) testing","definition":"Testing that the system meets response-time and throughput requirements under expected and peak volumes."},{"term":"Super-user","definition":"A business staff member given advanced training who supports colleagues, tests the system and acts as a link between users and the project team."},{"term":"Cut-over","definition":"The planned set of activities that moves the organisation from legacy systems to the new system, including final data loads and switching off old processes."},{"term":"Go/no-go criteria","definition":"Pre-agreed, measurable conditions that must be met before the decision to go live is taken."},{"term":"Hypercare","definition":"An intensive support period immediately after go-live, with extra staffing and rapid defect resolution."},{"term":"Post-implementation review (PIR)","definition":"A structured evaluation, typically several months after go-live, comparing actual outcomes with the business case and capturing lessons learned."},{"term":"Defect severity","definition":"A classification of defects by business impact, for example critical (stops a core process), high, medium and low."}],"body":[{"heading":"Testing an Enterprise System","markdown":"Testing proceeds from small components to whole business scenarios, and responsibility shifts from technical teams to business users.\n\n| Test type | Purpose | Typical owner | Example |\n|---|---|---|---|\n| Unit testing | Check individual configurations, reports, interfaces or custom code | Developers, configurators | A custom invoice form prints tax fields correctly |\n| Integration (system integration) testing | Check end-to-end flows across modules and interfaces | Project test team | Sales order to delivery to invoice to mobile money payment to ledger posting |\n| Data migration testing | Check that migrated data loads and reconciles | Data team with data owners | Mock load reconciles customer balances to zero difference |\n| Performance and load testing | Check speed and capacity at peak | Technical team | 40 tills processing simultaneous sales on a festive Saturday |\n| Security and authorisation testing | Check roles, segregation of duties and access controls | Security team, internal audit | A cashier cannot approve their own refund |\n| User acceptance testing | Confirm the system supports business processes | Business users and super-users | Pharmacists process realistic prescriptions end to end |\n| Regression testing | Confirm fixes have not broken earlier work | Test team, often automated | Re-run payment scenarios after an interface fix |\n| Operational acceptance testing | Confirm backups, monitoring, batch jobs and support procedures work | IT operations | Restore from backup within the agreed time |\n\n### Designing UAT\n\nUAT should be driven by the requirements traceability matrix: every Must requirement maps to at least one test scenario. Scenarios should be written as business stories (\"a customer returns a damaged item bought with mobile money and receives a refund\") with expected results, test data and a pass/fail column. Defects are logged with a severity, an owner and a target resolution date.\n\n**UAT exit criteria** are agreed before testing starts, for example: 100% of critical scenarios executed and passed; no open critical defects; no more than an agreed small number of open high-severity defects, each with an approved workaround; and sign-off by each process owner."},{"heading":"Training Users","markdown":"Training is not a single classroom event the week before go-live. Effective programmes are:\n\n- **Role-based.** A cashier, a stores clerk and an accounts payable officer need different content. Map each role to the transactions it performs and train those, using the organisation''s own processes and data.\n- **Timed close to go-live.** Training delivered months early decays before use; training delivered the day before leaves no time to practise.\n- **Hands-on.** Learners need a training environment (sandbox) loaded with realistic data where mistakes are harmless.\n- **Cascaded through super-users.** A train-the-trainer approach develops super-users who then train colleagues and provide floor support during hypercare.\n- **Supported by job aids.** Short step-by-step guides, screen recordings and quick-reference cards for less frequent tasks.\n- **Measured.** Use short practical assessments: can the learner complete their core transactions unaided? Track the proportion of users certified per role as a go/no-go criterion.\n\nTraining also addresses the *why*, not only the *how*. Users who understand that an integrated system makes their data visible to downstream colleagues are more likely to enter it accurately, which is central to the \"Knowledge\" and \"Ability\" elements of the ADKAR model."},{"heading":"Deployment and Cut-Over Planning","markdown":"A cut-over plan (or runbook) lists every activity, its owner, its start time, its duration and its dependencies, from the final weeks before go-live to the first days after. A simplified plan for a weekend cut-over is:\n\n| Time | Activity | Owner |\n|---|---|---|\n| T − 4 weeks | Final mock load and timed dress rehearsal of cut-over | Data lead |\n| T − 2 weeks | UAT sign-off; training certification reviewed | Process owners |\n| T − 1 week | Freeze configuration changes; confirm support rota for hypercare | Project manager |\n| Friday 18:00 | Stop legacy transactions; count stock; print legacy control reports | Operations, finance |\n| Friday 20:00: Saturday 14:00 | Extract, transform, load master data, balances and open items | Data team |\n| Saturday 14:00: 20:00 | Reconcile and obtain data-owner sign-off | Finance controller |\n| Saturday 21:00 | Go/no-go meeting | Steering committee |\n| Sunday | Smoke tests: one transaction per key process; enable user access | Super-users |\n| Monday 07:00 | Go-live; hypercare desk opens | Support lead |\n\n### Go/no-go criteria\n\nExamples include: UAT exit criteria met; reconciliation differences zero or signed off; performance test passed at peak volume; at least an agreed proportion of users certified in each critical role; hypercare staffing confirmed; and rollback procedure tested. The criteria must be decided weeks in advance so that the go/no-go meeting is an evidence review, not a negotiation.\n\n### Rollback\n\nA rollback plan states the latest point at which reverting is possible, the steps to restore legacy systems, and who decides. Once new transactions have been entered, rollback becomes much harder, so the decision point is usually before user access is enabled.\n\n### Hypercare\n\nDuring hypercare, a support desk triages issues by severity, super-users provide floor support, and daily stand-ups review defect counts and backlogs (for example, unprocessed orders or unmatched payments). Hypercare ends when agreed stability criteria are met."},{"heading":"Post-Implementation Evaluation","markdown":"A post-implementation review assesses whether the system is delivering value and what the organisation has learned. It typically considers four perspectives: **project performance** (time, budget, scope); **system quality** (availability, response time, defect trends); **use and user satisfaction** (adoption, workarounds, survey results); and **business benefits** (process KPIs against baseline).\n\n### Worked example: process KPIs against baseline\n\n*Illustrative scenario.* A distribution company measured these KPIs before go-live and six months after:\n\n| KPI | Baseline | Target | Six months after | Change |\n|---|---|---|---|---|\n| Order-to-delivery cycle time (days) | 4.0 | 2.5 | 3.0 | −25% |\n| Order accuracy (orders delivered without error) | 91% | 98% | 97% | +6 points |\n| Days to close monthly accounts | 12 | 5 | 6 | −50% |\n| Inventory record accuracy (cycle counts matching system) | 82% | 97% | 95% | +13 points |\n| Help-desk tickets per 100 users per week | n/a | < 5 | 7 | above target |\n\nThe cycle-time change is `(3.0 − 4.0) / 4.0 = −25%`; the close-time change is `(6 − 12) / 12 = −50%`. Interpreting the table, the system has delivered substantial improvement, but most KPIs remain short of target and the help-desk volume indicates continuing usability or training problems. A sound PIR would investigate root causes (for example, by analysing ticket categories), recommend targeted retraining or configuration changes, and set a date for re-measurement. Without a baseline measured *before* go-live, none of these conclusions would be possible, which is why baselining belongs in the chartering phase."},{"heading":"Ghanaian Business Application","markdown":"*Illustrative scenario.* A private hospital group in Kumasi is deploying a new hospital management system with integrated pharmacy, billing and insurance claims. Testing includes integration scenarios from patient registration through consultation, prescription, dispensing and claim submission for National Health Insurance Scheme patients; performance testing at the morning outpatient peak; and authorisation testing to ensure only clinicians can view clinical notes. Training is role-based (records clerks, nurses, doctors, pharmacists, billing officers), uses a sandbox with fictitious patient records, and is delivered in short sessions fitted around shift patterns. Cut-over is planned for a weekend with reduced outpatient activity, paper fallback forms are prepared for emergencies, and super-users wear identifiable tabards during a two-week hypercare period. The PIR compares outpatient waiting times, claim rejection rates and billing leakage against baselines measured in the three months before go-live."},{"heading":"International Case Study: Heathrow Terminal 5 Opening (2008)","markdown":"When Heathrow''s Terminal 5 opened in March 2008, problems with the new baggage-handling system and its operation led to large numbers of cancelled flights and a backlog of delayed bags in the first days. A subsequent inquiry by the UK House of Commons Transport Committee examined the opening, and commentary identified issues including staff familiarisation with the new building and systems, and the extent of end-to-end testing under realistic operating conditions.\n\nThe case shows that technical testing alone is insufficient: operational readiness depends on people, procedures and the system working together at full load. Rehearsals with real staff, realistic volumes and the actual working environment are part of testing, and go/no-go criteria should include evidence of operational readiness as well as software quality."},{"heading":"Diagram","markdown":"```mermaid\nflowchart TD\n    A[\"Unit and configuration tests\"] --> B[\"System integration testing\"]\n    B --> C[\"Performance, security and migration tests\"]\n    C --> D[\"User acceptance testing against RTM\"]\n    D --> E[\"Role-based training and certification\"]\n    E --> F{\"Go/no-go meeting\"}\n    F -->|\"Criteria not met\"| G[\"Fix, retest or defer go-live\"]\n    G --> D\n    F -->|\"Criteria met\"| H[\"Cut-over and smoke tests\"]\n    H --> I[\"Hypercare\"]\n    I --> J[\"Post-implementation review against baseline\"]\n```"}],"misconceptions":["\"UAT is where testers find bugs.\" Correction: UAT confirms business fitness; most technical defects should already have been found in unit and integration testing.","\"A go-live date, once announced, must be met.\" Correction: a well-governed project lets pre-agreed criteria decide; deferring is often cheaper than a failed go-live.","\"Training is finished once everyone has attended a session.\" Correction: attendance is not competence; certification, floor support and refresher training are needed.","\"The project ends at go-live.\" Correction: hypercare, stabilisation and post-implementation review are where benefits are secured and measured."],"examMistakes":["Listing test types without stating their purpose or owner.","Proposing go/no-go criteria that are not measurable.","Omitting rollback and hypercare from deployment plans.","Evaluating success only in terms of time and budget, ignoring business KPIs and user adoption.","Claiming benefits without reference to a pre-implementation baseline."],"criticalQuestions":["Who should chair the go/no-go meeting, and how can the organisation protect the decision from schedule pressure?","How would you measure whether training has been effective, rather than merely delivered?","If a PIR shows benefits below target, how would you distinguish system problems from process or people problems?","To what extent can automated regression testing reduce the risk of upgrades in a cloud ERP with frequent vendor releases?"],"exercises":["**UAT script.** Write five UAT scenarios for a pharmacy point-of-sale process, each with preconditions, steps, test data, expected result and a requirement reference. Expected output: a UAT script table ready for execution.","**Cut-over runbook in BPMN.** In Bizagi Modeler or Camunda Modeler, model the cut-over weekend from \"stop legacy transactions\" to \"go-live\", including the go/no-go gateway and the rollback path. Expected output: a BPMN diagram with lanes for data team, finance, steering committee and super-users.","**PIR analysis.** Add two further KPIs to the worked example (for example, supplier payment on time and stock-outs per month), with baseline, target and actual values of your choice. Expected output: calculated changes and a 200-word evaluation with recommendations.","**SAP Learning activity.** On SAP Learning, find free material describing SAP Activate''s deploy and run phases. Expected output: a comparison table showing how its deploy activities map to the cut-over plan in this lesson."],"takeaways":["Test from unit to integration to UAT, with performance, security, migration and operational tests alongside.","UAT is driven by the requirements traceability matrix and closed by pre-agreed exit criteria.","Training should be role-based, hands-on, timed close to go-live and verified by certification.","Cut-over needs a timed runbook, measurable go/no-go criteria, a rollback plan and hypercare.","Post-implementation review compares KPIs with a pre-go-live baseline and drives continuous improvement."],"furtherReading":[{"text":"Markus, M. L., & Tanis, C. (2000). The enterprise systems experience: From adoption to success. In R. W. Zmud (Ed.), *Framing the domains of IT management: Projecting the future through the past*. Pinnaflex Educational Resources.","url":null,"verification":"citation"},{"text":"Monk, E., & Wagner, B. (2013). *Concepts in enterprise resource planning* (4th ed.). Cengage Learning.","url":null,"verification":"citation"},{"text":"Kotter, J. P. (1996). *Leading change*. Harvard Business School Press.","url":null,"verification":"citation"},{"text":"Nah, F. F.-H., Lau, J. L.-S., & Kuang, J. (2001). Critical factors for successful implementation of enterprise systems. *Business Process Management Journal, 7*(3), 285-296.","url":null,"verification":"citation"}],"videos":[{"title":"SAP Learning","url":"https://learning.sap.com/","description":"SAP. Free learning journeys including the SAP Activate methodology''s deploy and run phases.","verification":"verified"},{"title":"Microsoft Learn: Dynamics 365 training","url":"https://learn.microsoft.com/training/dynamics365/","description":"Microsoft. Self-paced modules including implementation guidance and testing for business applications.","verification":"verified"},{"title":"Bizagi","url":"https://www.bizagi.com/","description":"Bizagi. Official site for Bizagi Modeler, used for BPMN modelling exercises such as cut-over processes.","verification":"verified"}],"revisionSummary":"Testing, training, deployment and evaluation turn a configured system into working business capability. Testing moves from unit and integration tests to UAT driven by the requirements traceability matrix, supported by performance, security, migration and operational tests. Training is role-based, hands-on and certified, cascaded through super-users. Cut-over follows a timed runbook with measurable go/no-go criteria, a rollback plan and hypercare. Post-implementation review measures KPIs against a baseline and captures lessons.\n\n- UAT exit: critical scenarios passed, no open critical defects, owner sign-off.\n- Regression testing after every fix or upgrade.\n- Attendance is not competence; certify users by role.\n- Go/no-go criteria are agreed weeks in advance.\n- Baselines must be captured before go-live.\n- Heathrow T5 (2008): operational readiness matters as much as software."}'::jsonb, 2495, 4, true)
  on conflict (id) do update set module_id = excluded.module_id, slug = excluded.slug, title = excluded.title, summary = excluded.summary, topics = excluded.topics, estimated_minutes = excluded.estimated_minutes, difficulty = excluded.difficulty, source = excluded.source, content = excluded.content, word_count = excluded.word_count, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('61f53cbb-2fe1-5250-a132-10544fbe4ab0', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'csit-603/enterprise-implementation/q01', 'mcq', 'recall', 'easy', 'Identify the phases of the enterprise systems life cycle', 'In Markus and Tanis''s enterprise systems life cycle, which phase covers the period from go-live until normal operations are reached?', null, null, '[{"id":"a","text":"Chartering"},{"id":"b","text":"Project"},{"id":"c","text":"Shakedown"},{"id":"d","text":"Onward and upward"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('61f53cbb-2fe1-5250-a132-10544fbe4ab0', '{"option":"c"}'::jsonb, 'Shakedown is the period immediately after go-live when performance often dips while users learn new procedures and defects surface. Chartering is the business case and scope phase, the project phase covers configuration and roll-out up to go-live, and onward and upward is the later phase of stabilisation and benefits realisation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7e85cc11-4e71-5661-8fb0-7d061ac55c38', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'csit-603/enterprise-implementation/q02', 'true_false', 'understand', 'medium', 'Explain the trade-offs of a big bang strategy', 'A big bang implementation avoids the need to build temporary interfaces between legacy and new systems.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7e85cc11-4e71-5661-8fb0-7d061ac55c38', '{"value":true}'::jsonb, 'True. Because all modules switch at once, there is no period in which a new module must exchange data with a legacy one, so no bridge interfaces are needed. The trade-off is that risk is concentrated in a single cut-over with limited fallback.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('54843928-6169-5249-92b1-0fc2abbd808e', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'csit-603/enterprise-implementation/q03', 'scenario', 'apply', 'medium', 'Recommend an implementation strategy for a multi-site organisation', 'Which implementation strategy is most defensible?', 'Illustrative scenario. A supermarket group has fifteen branches with almost identical operations. Branch staff
have limited ERP experience, and head office has a small IT team. The group wants to avoid disrupting all
branches at once.', null, '[{"id":"a","text":"Big bang across all fifteen branches on one weekend"},{"id":"b","text":"Pilot at one representative branch, then roll out in waves"},{"id":"c","text":"Parallel running of both systems at every branch for six months"},{"id":"d","text":"Implement only the finance module and never extend the system"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('54843928-6169-5249-92b1-0fc2abbd808e', '{"option":"b"}'::jsonb, 'Standardised branches and limited readiness make a pilot followed by site-phased waves the strongest option: risk is contained, the training and support model is tested in real conditions, and lessons are applied to later waves. Big bang concentrates risk where readiness is weakest; parallel running everywhere would double staff workload; and abandoning the wider scope would fail the business case.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a1282872-6259-53e8-a17c-838ff8908324', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'csit-603/enterprise-implementation/q04', 'short_answer', 'recall', 'easy', 'Name the prioritisation scheme for requirements', 'Name the prioritisation scheme that classifies requirements as Must have, Should have, Could have and Won''t have this time.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a1282872-6259-53e8-a17c-838ff8908324', '{"answers":["MoSCoW","MoSCoW prioritisation","MoSCoW method"]}'::jsonb, 'MoSCoW forces stakeholders to separate essential requirements from desirable ones, which protects scope and timelines. Must requirements typically become knock-out criteria in vendor selection and mandatory UAT scenarios.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('402b544c-2dcb-5597-8e75-1bf64db36dd8', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'csit-603/enterprise-implementation/q05', 'matching', 'understand', 'medium', 'Match requirements-gathering techniques to what they reveal best', 'Match each requirements-gathering technique to the insight it is best at producing.', null, null, '{"left":[{"id":"l1","text":"Observation and job shadowing"},{"id":"l2","text":"Facilitated workshops"},{"id":"l3","text":"Document and data analysis"},{"id":"l4","text":"Conference-room pilot"},{"id":"l5","text":"Process mining"}],"right":[{"id":"r3","text":"Objective evidence such as transaction volumes and forms"},{"id":"r4","text":"Feedback on the configured system using realistic scenarios"},{"id":"r1","text":"Actual work practices and undocumented workarounds"},{"id":"r5","text":"Quantified process variants from event logs"},{"id":"r2","text":"Agreed cross-functional process designs"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('402b544c-2dcb-5597-8e75-1bf64db36dd8', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Each technique has a characteristic strength, which is why good practice triangulates. Observation reveals what people actually do rather than what they say; workshops build consensus across hand-offs; documents and data provide objective sizing; conference-room pilots expose misunderstandings on the real configuration; and process mining quantifies variation from system logs.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e7a90b17-1e69-5bd9-948a-9e934367d31c', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'csit-603/enterprise-implementation/q06', 'mcq', 'analyse', 'medium', 'Distinguish testable from untestable requirements', 'Which of the following is the best-formed non-functional requirement?', null, null, '[{"id":"a","text":"The system should be user-friendly for all staff"},{"id":"b","text":"The system must record goods receipts against purchase orders"},{"id":"c","text":"A trained cashier must complete a three-item mobile money sale in under 60 seconds"},{"id":"d","text":"The system should look like the old system so users are comfortable"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e7a90b17-1e69-5bd9-948a-9e934367d31c', '{"option":"c"}'::jsonb, 'The cashier requirement is measurable and testable, and it describes a quality (speed and usability) rather than a function. "User-friendly" is untestable; recording goods receipts is a functional requirement; and copying the old system''s look is a legacy preference, not a business need.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2e1b2167-09ac-5eb6-a73f-f53599891732', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'csit-603/enterprise-implementation/q07', 'true_false', 'evaluate', 'hard', 'Evaluate the role of the business calendar in go-live planning', 'The Hershey case suggests that the go-live date should be set by the project schedule, with the business calendar adjusted around it.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2e1b2167-09ac-5eb6-a73f-f53599891732', '{"value":false}'::jsonb, 'False. Hershey''s widely reported 1999 problems arose partly because the go-live placed shakedown just before its peak Halloween season. The lesson is the reverse: the business calendar should constrain the go-live date, and peak periods, year-end and statutory deadlines should be avoided.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('03614ea7-0df3-533f-8115-17c0f33c0dd8', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'csit-603/enterprise-implementation/q08', 'mcq', 'recall', 'easy', 'Distinguish RFI from RFP', 'What is the main purpose of a request for information (RFI) in vendor selection?', null, null, '[{"id":"a","text":"To sign the contract with the chosen vendor"},{"id":"b","text":"To gather broad product information so a long list can be reduced"},{"id":"c","text":"To run scripted demonstrations with the buyer''s data"},{"id":"d","text":"To agree service level penalties"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('03614ea7-0df3-533f-8115-17c0f33c0dd8', '{"option":"b"}'::jsonb, 'The RFI is an early, lightweight step used to screen a long list. The RFP follows with detailed requirements and commercial terms for a short list; scripted demonstrations and SLA negotiation come later still.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('899d7138-ca32-5d90-887f-92acf8aaa381', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'csit-603/enterprise-implementation/q09', 'short_answer', 'apply', 'medium', 'Calculate a weighted score', 'A criterion has a weight of 0.25 and a vendor scores 4 out of 5 on it. What is the weighted score? (Give the number only.)', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('899d7138-ca32-5d90-887f-92acf8aaa381', '{"answers":["1","1.0","1.00"]}'::jsonb, 'Weighted score equals weight multiplied by score: 0.25 × 4 = 1.00. Summing such products across all criteria gives the vendor''s total, provided the weights sum to 1.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('39870f9a-01f1-5bfb-8611-91a8a26a1d72', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'csit-603/enterprise-implementation/q10', 'scenario', 'analyse', 'hard', 'Interpret sensitivity analysis in a weighted scoring model', 'What is the most appropriate conclusion for the analyst to present?', 'Illustrative scenario. Vendor A scores 3.70 and vendor B 3.65 under the agreed weights. When the cost weight is
raised from 0.20 to 0.30 and functional fit lowered from 0.30 to 0.20, vendor C moves into first place.', null, '[{"id":"a","text":"Vendor A must be chosen because it won under the agreed weights"},{"id":"b","text":"The weights should be changed until the preferred vendor wins"},{"id":"c","text":"The ranking is sensitive to the fit-versus-cost trade-off, which the steering committee must decide explicitly"},{"id":"d","text":"Weighted scoring is useless and should be abandoned"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('39870f9a-01f1-5bfb-8611-91a8a26a1d72', '{"option":"c"}'::jsonb, 'A 0.05 margin is within the uncertainty of subjective scores, and the ranking flips under a plausible change in weights. The analyst should make the strategic trade-off explicit. Mechanically choosing A ignores fragility; manipulating weights introduces bias; and abandoning the method discards a useful, transparent tool.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('aeac113c-56c6-5238-a609-6ffedeabdf7c', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'csit-603/enterprise-implementation/q11', 'true_false', 'understand', 'medium', 'Explain what total cost of ownership includes', 'Total cost of ownership should include internal staff time, training and future upgrades as well as licence or subscription fees.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('aeac113c-56c6-5238-a609-6ffedeabdf7c', '{"value":true}'::jsonb, 'True. TCO covers acquisition, implementation, operation and change costs over a defined horizon. Internal backfill, support staff, training and upgrades often exceed the licence cost, so ignoring them distorts comparisons.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7c0eb56f-a88d-550d-909c-54712c7da667', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'csit-603/enterprise-implementation/q12', 'mcq', 'apply', 'medium', 'Calculate five-year subscription cost', 'A cloud ERP costs GHS 300,000 per year in subscriptions plus GHS 400,000 one-off implementation. Ignoring all other costs, what is the five-year cost?', null, null, '[{"id":"a","text":"GHS 700,000"},{"id":"b","text":"GHS 1,500,000"},{"id":"c","text":"GHS 1,900,000"},{"id":"d","text":"GHS 2,000,000"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7c0eb56f-a88d-550d-909c-54712c7da667', '{"option":"c"}'::jsonb, 'Five years of subscription is 5 × 300,000 = 1,500,000; adding the one-off implementation gives 1,900,000. 700,000 counts only one year of subscription; 1,500,000 omits implementation; 2,000,000 wrongly adds a further year''s subscription.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e9fdcb98-406a-59f2-8532-630b8d108ea0', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'csit-603/enterprise-implementation/q13', 'matching', 'understand', 'medium', 'Match selection concepts to their definitions', 'Match each vendor selection concept to its description.', null, null, '{"left":[{"id":"l1","text":"Knock-out criterion"},{"id":"l2","text":"Scripted demonstration"},{"id":"l3","text":"Service level agreement"},{"id":"l4","text":"Vendor lock-in"}],"right":[{"id":"r2","text":"Vendors run the buyer''s own scenarios and data"},{"id":"r3","text":"Contractual, measurable service standards with remedies"},{"id":"r1","text":"A requirement that excludes any vendor failing it, regardless of total score"},{"id":"r4","text":"Switching becomes costly because of proprietary formats or terms"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e9fdcb98-406a-59f2-8532-630b8d108ea0', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'These mechanisms protect the buyer: knock-outs stop a high total from hiding a fatal gap, scripted demos prevent polished generic sales presentations, SLAs make service enforceable, and awareness of lock-in shapes exit and data-ownership clauses.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6c07c10d-bbff-520b-9821-8afc1dba8525', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'csit-603/enterprise-implementation/q14', 'true_false', 'evaluate', 'hard', 'Evaluate the integrity of the evaluation process', 'Adjusting criterion weights after seeing the vendor demonstrations is good practice because it reflects what the team has learned.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6c07c10d-bbff-520b-9821-8afc1dba8525', '{"value":false}'::jsonb, 'False. Changing weights after demonstrations invites bias towards a favoured product. Weights should be fixed in advance; new insights are better handled through sensitivity analysis and transparent discussion of trade-offs.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ae1651e1-e25f-5b16-a44e-a9ecf6991269', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'csit-603/enterprise-implementation/q15', 'mcq', 'recall', 'easy', 'Identify the purpose of data profiling', 'What is the main purpose of data profiling at the start of a migration?', null, null, '[{"id":"a","text":"To load data into the target system"},{"id":"b","text":"To quantify data quality problems such as duplicates and missing values"},{"id":"c","text":"To design the user interface of the new system"},{"id":"d","text":"To archive the legacy system"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ae1651e1-e25f-5b16-a44e-a9ecf6991269', '{"option":"b"}'::jsonb, 'Profiling statistically examines source data to reveal null rates, duplicates and invalid values, so cleansing can be planned and sized. Loading, interface design and archiving are separate activities.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('81ad14f7-5d5e-5776-a9aa-e9d556f522ff', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'csit-603/enterprise-implementation/q16', 'short_answer', 'apply', 'medium', 'Calculate the number of point-to-point links', 'Using n × (n − 1) / 2, how many point-to-point links could be needed to fully connect six systems? (Give the number only.)', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('81ad14f7-5d5e-5776-a9aa-e9d556f522ff', '{"answers":["15"]}'::jsonb, '6 × 5 / 2 = 15. The rapid growth in links as systems are added is the main argument for hub-and-spoke or API-led integration, which reduces connections to roughly one per system.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('28b04644-215a-54ec-b0b2-84c34f17bf6a', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'csit-603/enterprise-implementation/q17', 'scenario', 'analyse', 'hard', 'Interpret a reconciliation discrepancy', 'What should the migration team conclude?', 'Illustrative scenario. After a mock load, legacy open receivables total GHS 4,862,350.00 and the ERP shows
GHS 4,858,100.00. The error file lists 35 rejected customers whose open invoices total GHS 3,900.00.', null, '[{"id":"a","text":"The migration is acceptable because the difference is under 0.1%"},{"id":"b","text":"GHS 350.00 remains unexplained, suggesting a further error that must be investigated before sign-off"},{"id":"c","text":"The rejected customers explain the whole difference"},{"id":"d","text":"The legacy system must be wrong and should be ignored"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('28b04644-215a-54ec-b0b2-84c34f17bf6a', '{"option":"b"}'::jsonb, 'The total difference is 4,250.00; rejected records explain only 3,900.00, leaving 350.00 unexplained. Every difference must be eliminated or explained, because an unexplained amount may signal a mapping error affecting other records. Materiality arguments and blaming the source are not acceptable substitutes for investigation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5677f786-6bea-56e5-972b-b6d1d752e3fd', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'csit-603/enterprise-implementation/q18', 'true_false', 'understand', 'medium', 'Explain why record counts alone are insufficient', 'If source and target record counts match exactly, the migration has been proven accurate.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5677f786-6bea-56e5-972b-b6d1d752e3fd', '{"value":false}'::jsonb, 'False. Counts prove completeness of records, not accuracy of values. A balance could be truncated or a code mis-mapped while counts still match. Control totals and sample checks are also required.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3cfa227f-f7b4-5131-8171-13fa59694e9d', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'csit-603/enterprise-implementation/q19', 'matching', 'understand', 'medium', 'Match integration patterns to typical uses', 'Match each integration pattern to its most typical use.', null, null, '{"left":[{"id":"l1","text":"File-based batch"},{"id":"l2","text":"API-led"},{"id":"l3","text":"Publish-subscribe events"},{"id":"l4","text":"Enterprise service bus"}],"right":[{"id":"r3","text":"A goods-received event updating several systems"},{"id":"r2","text":"E-commerce site checking ERP stock in real time"},{"id":"r1","text":"Nightly bank statement import"},{"id":"r4","text":"Central routing and transformation across many systems"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3cfa227f-f7b4-5131-8171-13fa59694e9d', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Pattern choice follows latency and scale. Batch suits non-urgent bulk data; APIs give real-time request-response; events loosely couple many consumers; and an ESB centralises routing and monitoring in large estates.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b6d982fc-0cf6-5ec8-a3e6-d6e08ef24fa2', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'csit-603/enterprise-implementation/q20', 'mcq', 'apply', 'medium', 'Apply idempotency to payment interfaces', 'A mobile money aggregator occasionally resends the same payment confirmation. Which interface property prevents the invoice being paid twice?', null, null, '[{"id":"a","text":"Idempotency"},{"id":"b","text":"Asynchronous batching"},{"id":"c","text":"Point-to-point design"},{"id":"d","text":"Data profiling"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b6d982fc-0cf6-5ec8-a3e6-d6e08ef24fa2', '{"option":"a"}'::jsonb, 'An idempotent interface recognises a repeated message (for example, by a unique transaction reference) and produces the same result as processing it once. Batching, point-to-point design and profiling do not by themselves prevent duplicate postings.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f45d211a-6560-55c6-ae43-3fa3af687e23', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'csit-603/enterprise-implementation/q21', 'true_false', 'evaluate', 'hard', 'Evaluate migration scope decisions', 'Archiving the legacy system in read-only form is usually a better choice than migrating full transactional history into the new ERP.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f45d211a-6560-55c6-ae43-3fa3af687e23', '{"value":true}'::jsonb, 'True. Full history multiplies mapping, cleansing and reconciliation effort and extends the cut-over window. Migrating master data, open items and balances, while keeping the legacy system for enquiry and audit, usually meets business needs at much lower risk.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f0c95fc3-fe69-571a-b802-9cdac24bc55d', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '7777fef8-7874-55dc-9848-2a06747ca876', 'csit-603/enterprise-implementation/q22', 'mcq', 'recall', 'easy', 'Identify the purpose of regression testing', 'What is the purpose of regression testing?', null, null, '[{"id":"a","text":"To confirm that changes have not broken functionality that previously worked"},{"id":"b","text":"To test the system with business users for the first time"},{"id":"c","text":"To measure performance at peak load"},{"id":"d","text":"To train super-users"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f0c95fc3-fe69-571a-b802-9cdac24bc55d', '{"option":"a"}'::jsonb, 'Regression testing re-runs earlier tests after a fix or upgrade. UAT involves business users, performance testing measures speed under load, and super-user training is not testing at all.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('09b85461-eca4-536e-87ca-a30c032652b1', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '7777fef8-7874-55dc-9848-2a06747ca876', 'csit-603/enterprise-implementation/q23', 'matching', 'understand', 'medium', 'Match test types to examples', 'Match each test type to the example that best illustrates it.', null, null, '{"left":[{"id":"l1","text":"System integration testing"},{"id":"l2","text":"Performance testing"},{"id":"l3","text":"Authorisation testing"},{"id":"l4","text":"Operational acceptance testing"},{"id":"l5","text":"User acceptance testing"}],"right":[{"id":"r5","text":"Pharmacists processing realistic prescriptions end to end"},{"id":"r1","text":"Sales order through delivery, invoice, payment and ledger posting"},{"id":"r2","text":"Forty tills processing simultaneous sales on a festive Saturday"},{"id":"r3","text":"A cashier cannot approve their own refund"},{"id":"r4","text":"Restoring from backup within the agreed time"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('09b85461-eca4-536e-87ca-a30c032652b1', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Each test type answers a different question: do flows work across modules, is the system fast enough, are controls enforced, can IT operate it, and does it support real business work? Owners differ accordingly.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f894905a-2c53-5ea4-8099-af9e68635f45', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '7777fef8-7874-55dc-9848-2a06747ca876', 'csit-603/enterprise-implementation/q24', 'scenario', 'evaluate', 'hard', 'Evaluate a go/no-go decision', 'What should the steering committee do?', 'Illustrative scenario. At the go/no-go meeting, UAT shows two open critical defects in the invoicing process,
reconciliation is complete, and 70% of cashiers are certified against a criterion of 90%. The managing director
has already announced the go-live date to customers.', null, '[{"id":"a","text":"Go live because the date has been announced"},{"id":"b","text":"Go live but ask cashiers to work harder"},{"id":"c","text":"Defer go-live until the pre-agreed criteria are met, communicating a revised date"},{"id":"d","text":"Cancel the project entirely"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f894905a-2c53-5ea4-8099-af9e68635f45', '{"option":"c"}'::jsonb, 'Pre-agreed criteria exist precisely to protect the decision from schedule pressure. Open critical defects and insufficient certification are clear no-go signals. Deferral with clear communication is usually far cheaper than a failed go-live; cancellation is a disproportionate response to fixable readiness gaps.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9e728664-4833-52d0-9580-47f38f8d5b0b', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '7777fef8-7874-55dc-9848-2a06747ca876', 'csit-603/enterprise-implementation/q25', 'short_answer', 'recall', 'easy', 'Name the intensive post-go-live support period', 'What term describes the intensive support period immediately after go-live, with extra staffing and rapid defect resolution?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9e728664-4833-52d0-9580-47f38f8d5b0b', '{"answers":["Hypercare","hyper care","hyper-care"]}'::jsonb, 'Hypercare provides a triaged support desk, floor support from super-users and daily reviews of defects and backlogs until agreed stability criteria are met.', null)
