insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('49c760a7-6d7d-5564-ba9b-5291c30ac647', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '7777fef8-7874-55dc-9848-2a06747ca876', 'csit-603/enterprise-implementation/q26', 'mcq', 'apply', 'medium', 'Calculate a KPI change in a post-implementation review', 'Days to close the monthly accounts fell from 12 before go-live to 6 six months later. What is the percentage change?', null, null, '[{"id":"a","text":"-25%"},{"id":"b","text":"-50%"},{"id":"c","text":"-100%"},{"id":"d","text":"+50%"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('49c760a7-6d7d-5564-ba9b-5291c30ac647', '{"option":"b"}'::jsonb, 'Percentage change is (new − old) / old = (6 − 12) / 12 = −0.5, a 50% reduction. The other options apply the formula incorrectly or reverse the direction of change.', null)
