insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1ab89dd3-1217-54cf-9cd2-a62433463b1d', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '7777fef8-7874-55dc-9848-2a06747ca876', 'csit-603/enterprise-implementation/q27', 'true_false', 'analyse', 'medium', 'Analyse the importance of baselines', 'Benefits in a post-implementation review can be demonstrated convincingly even if no KPIs were measured before go-live.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1ab89dd3-1217-54cf-9cd2-a62433463b1d', '{"value":false}'::jsonb, 'False. Without a pre-implementation baseline, there is no reference point against which change can be measured, and claimed improvements cannot be distinguished from opinion. Baselining belongs in the chartering phase.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7ea13d05-29de-5d93-bd37-20617670465c', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '7777fef8-7874-55dc-9848-2a06747ca876', 'csit-603/enterprise-implementation/q28', 'mcq', 'understand', 'medium', 'Explain effective training design', 'Which training design is most likely to produce competent users at go-live?', null, null, '[{"id":"a","text":"A single generic lecture for all staff three months before go-live"},{"id":"b","text":"Role-based, hands-on sandbox sessions close to go-live, with certification and super-user support"},{"id":"c","text":"Emailing the vendor''s user manual to all staff"},{"id":"d","text":"Training only managers and letting them explain the system informally"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7ea13d05-29de-5d93-bd37-20617670465c', '{"option":"b"}'::jsonb, 'Role-based, hands-on training timed close to go-live, verified by certification and backed by super-users, addresses both knowledge and ability. Early generic lectures decay, manuals alone rarely build skill, and informal cascades from managers are inconsistent.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('09c5d83a-cabc-525b-8370-6f8f3e63b9ea', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', null, 'csit-603/enterprise-implementation/q29', 'case_analysis', 'evaluate', 'hard', 'Evaluate an end-to-end ERP implementation plan', 'Critically evaluate Adom''s implementation plan and recommend improvements covering strategy, vendor selection, data migration, testing and training, and evaluation.', null, 'Illustrative scenario. Adom Distribution Ltd, a Ghanaian distributor of consumer goods with a head office in Tema
and six depots, plans to replace spreadsheets and a standalone accounting package with an ERP. The managing
director wants a big bang go-live on 1 December to "start the new year clean". The project manager proposes
migrating ten years of transaction history. Vendor selection was based mainly on the lowest licence price. UAT
is scheduled for the final week of November, and training will consist of one half-day session for all staff.
No KPIs have been measured.', null, 25, array['Brief diagnosis of the overall plan and its key risks', 'Implementation strategy and timing relative to the business calendar', 'Vendor selection weaknesses and the case for weighted scoring and TCO', 'Data migration scope, cleansing and reconciliation', 'Testing, go/no-go criteria, training and hypercare', 'Baselining and post-implementation review']::text[], '[{"criterion":"Strategy and timing","marks":5,"descriptor":"Identifies risk of big bang before the December peak and proposes a justified alternative such as a pilot depot and phased waves."},{"criterion":"Vendor selection","marks":5,"descriptor":"Explains why licence price is inadequate and proposes weighted scoring with knock-outs, sensitivity analysis and five-year TCO."},{"criterion":"Data migration","marks":5,"descriptor":"Challenges ten-year history, recommends master data, open items and balances with archiving, and specifies cleansing and reconciliation controls."},{"criterion":"Testing and training","marks":6,"descriptor":"Proposes staged testing, UAT with exit criteria earlier in the plan, measurable go/no-go criteria, role-based training with certification and hypercare."},{"criterion":"Evaluation and use of evidence","marks":4,"descriptor":"Recommends baseline KPIs and a post-implementation review, using relevant concepts and cases such as Hershey accurately."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('09c5d83a-cabc-525b-8370-6f8f3e63b9ea', '{}'::jsonb, 'Examiners look for a structured critique that links each weakness to a specific remedy, uses module concepts precisely (shakedown, knock-out criteria, TCO, reconciliation, go/no-go criteria, baseline) and refers to documented cases accurately without invented figures.', 'A strong answer opens by noting that the plan concentrates risk at every stage. A big bang on 1 December places
shakedown in the festive peak for a consumer-goods distributor, repeating the timing error widely associated with
Hershey''s 1999 go-live. A pilot at one depot near head office in, say, February, followed by waves of two or
three depots, would contain risk and test training and support in real conditions.

Selecting on licence price ignores fit and lifetime cost. The firm should agree weighted criteria before vendor
contact, use Must requirements as knock-outs, run scripted demonstrations with its own scenarios, test sensitivity
of the ranking, and compare five-year TCO including implementation, internal staff, training and upgrades.

Migrating ten years of history multiplies effort and extends the cut-over window. Master data, open receivables
and payables, open orders and stock by depot should be migrated, with the old system archived read-only. Profiling,
de-duplication of customers, and reconciliation by counts, control totals and samples, signed off by data owners
after several timed mock loads, are essential.

UAT in the final week leaves no time to fix defects. Integration testing should precede UAT by several weeks, UAT
should be driven by a requirements traceability matrix with exit criteria, and the go/no-go decision should rest
on measurable criteria including defect status, reconciliation and user certification. One half-day session is
inadequate: training should be role-based, hands-on in a sandbox, close to go-live and supported by super-users
and hypercare.

Finally, KPIs such as order cycle time, order accuracy, stock accuracy and month-end close days should be
baselined now so that a post-implementation review six months after go-live can demonstrate benefits.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('56cb2abb-1633-58c0-89b7-35a16b2e6657', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', null, 'csit-603/enterprise-implementation/q30', 'essay', 'evaluate', 'hard', 'Evaluate why enterprise implementations fail around go-live', '"Most ERP failures are decided long before go-live." Critically discuss this statement with reference to implementation strategy, data migration and testing, using at least one well-documented international case.', null, null, null, 20, array['Introduction defining failure and the life-cycle view (Markus and Tanis)', 'Early decisions - strategy, scope, timing, vendor and partner selection', 'Data migration and integration readiness', 'Testing, training and go/no-go governance', 'Counter-argument - shakedown management and post-go-live recovery', 'Conclusion with a balanced judgement']::text[], '[{"criterion":"Argument and judgement","marks":6,"descriptor":"Takes a clear, balanced position and sustains it across the essay."},{"criterion":"Use of concepts and frameworks","marks":6,"descriptor":"Applies life-cycle phases, strategy trade-offs, reconciliation and go/no-go criteria accurately."},{"criterion":"Use of cases","marks":5,"descriptor":"Uses documented cases such as Hershey, TSB or Heathrow T5 accurately and analytically."},{"criterion":"Structure and expression","marks":3,"descriptor":"Logical structure, clear academic English and appropriate referencing."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('56cb2abb-1633-58c0-89b7-35a16b2e6657', '{}'::jsonb, 'Examiners reward a nuanced judgement supported by life-cycle reasoning, precise use of implementation concepts and accurate use of well-documented cases rather than descriptive narrative.', 'A good essay accepts much of the statement while qualifying it. Using Markus and Tanis''s life cycle, it argues that
chartering and project-phase decisions largely determine shakedown risk. Strategy and timing are decisive: Hershey''s
widely reported 1999 difficulties followed a go-live close to its peak season, a choice made months earlier. Scope
and readiness evidence matter too: TSB''s 2018 migration was executed as a single weekend event, and subsequent
reviews and regulatory action focused on whether readiness had been adequately evidenced and challenged.

The essay should show how data migration (profiling, cleansing, mock loads, reconciliation) and testing (integration,
performance, UAT with exit criteria) produce the evidence on which a go/no-go decision rests, and that compressing
them to meet a date removes that evidence. Heathrow Terminal 5''s 2008 opening illustrates that operational
readiness of people and procedures must be tested alongside technology.

A balanced answer then argues that not everything is pre-determined. Strong hypercare, rapid defect triage, clear
communication and willingness to apply workarounds can limit damage during shakedown, and post-implementation
reviews can recover benefits over time. The conclusion might be that early decisions set the level of risk, while
post-go-live management determines how much of that risk turns into business harm.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bc9d9c40-edf7-5727-b730-ec6bdc2ae851', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'Why is a big bang implementation both attractive and dangerous?', 'It delivers benefits fastest and needs no temporary interfaces between old and new systems, but it concentrates all shakedown risk in one cut-over with weak fallback options.', 'supplementary', 'csit-603/enterprise-implementation/09b8e4f71b20', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('63d16003-dcfd-5d0c-9474-1471d0dfb9f6', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'When is parallel running most defensible?', 'For narrow, high-consequence processes such as payroll, where outputs can be compared reliably; for whole ERPs it doubles workload and is hard to reconcile when processes have been redesigned.', 'supplementary', 'csit-603/enterprise-implementation/c7462807b4bb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3a7df4cf-3003-5baf-b7b1-ac84865d3e79', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'Name four factors that should drive the choice of implementation strategy.', 'Integration density between modules, organisational readiness, the business calendar (peaks and year-end) and the cost of failure per day of disruption, plus pre-agreed rollback criteria.', 'supplementary', 'csit-603/enterprise-implementation/6a1c4d1be6fc', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('954b9ad5-53bb-5ba9-962e-b615ad3226bc', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'What four qualities make a requirement well formed?', 'It is atomic (one need), testable (pass or fail can be judged), traceable (linked to a source, owner and test) and prioritised, and ideally solution-neutral.', 'supplementary', 'csit-603/enterprise-implementation/598507dc0767', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('cfd0db65-6e52-5d14-b0e4-ac76009f7afd', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'In fit-gap analysis, what should be the default response to a gap?', 'First consider process change, configuration or deferral; customisation is the last resort because it raises upgrade, testing and support costs.', 'supplementary', 'csit-603/enterprise-implementation/aa9a642f3940', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bfa19ae2-f219-55e2-97f6-15b7f1027183', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '307c2a19-dfa2-5544-b34e-7b362d7cb027', 'What is the key lesson of Hershey''s 1999 ERP go-live?', 'The business calendar must constrain the go-live date; going live with tightly integrated order and warehouse functions just before peak season concentrated shakedown risk where customers would see it.', 'supplementary', 'csit-603/enterprise-implementation/834e2cf832c4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('cad96667-eb29-5e93-9342-ee13a001f57d', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'Why must evaluation weights be agreed before meeting vendors?', 'Fixing weights in advance prevents bias towards a favoured product after impressive demonstrations; new insights should be explored through sensitivity analysis instead.', 'supplementary', 'csit-603/enterprise-implementation/2bf947c7621b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('02e631e6-a574-5d18-9a48-cdfd6fcb69ad', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'What is a knock-out criterion and why use it alongside weighted scoring?', 'A requirement that excludes any vendor failing it; it stops a high total score on other criteria from compensating for a fatal gap.', 'supplementary', 'csit-603/enterprise-implementation/4dabc4c087a8', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0da5a986-df77-5955-853c-5ca4b7c0b529', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'What does sensitivity analysis reveal in vendor selection?', 'Whether the ranking changes under plausible changes to weights or scores; if it does, the decision depends on a strategic trade-off the committee must make explicitly.', 'supplementary', 'csit-603/enterprise-implementation/900ed145a056', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f86bf344-a039-5866-9915-5494f254b434', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'List the four main categories of total cost of ownership.', 'Acquisition (licences, hardware), implementation (consulting, migration, training, backfill), operation (maintenance, subscription, hosting, support) and change (upgrades, enhancements, exit).', 'supplementary', 'csit-603/enterprise-implementation/3c83c30b9946', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9fbf3167-4204-5adb-8fd0-08820ac1ab6b', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'Why can a cloud ERP that is cheaper over five years become dearer over ten?', 'Recurring subscriptions accumulate, prices may rise annually, and foreign-currency pricing exposes the buyer to exchange-rate movements, while on-premise licences are largely one-off.', 'supplementary', 'csit-603/enterprise-implementation/177b6abc31a1', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f5ef44f8-2a07-5a14-bc45-02ef45c38c6c', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '644ad992-bd04-5030-84e3-9a4125edba24', 'What does the Lidl case (2018) teach about vendor selection?', 'Misfit between a package''s core logic and a deeply embedded business practice, reportedly inventory valuation, can force heavy customisation; such conflicts must be resolved consciously during selection.', 'supplementary', 'csit-603/enterprise-implementation/52c6afd0efc2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8cb8b701-7c42-513c-9304-ff31080b45d6', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'What data is typically migrated to a new ERP, and what is archived?', 'Master data, open items and balances (and sometimes limited summarised history) are migrated; most transactional history stays in an archived, read-only legacy system.', 'supplementary', 'csit-603/enterprise-implementation/6dca8d9a410e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5a8778d7-d98d-55ee-97c6-e9a68c927d56', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'What three controls together prove a migration is complete and accurate?', 'Record counts (completeness), control totals such as balance sums (value accuracy) and sample checks of individual records by data owners.', 'supplementary', 'csit-603/enterprise-implementation/2f944ef70b56', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('abd300dd-188c-53f2-810f-fc9d0074307f', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'Why run several timed mock loads before cut-over?', 'To find mapping and quality errors early, improve each run, and prove that the final load and reconciliation fit inside the cut-over window.', 'supplementary', 'csit-603/enterprise-implementation/0320c6a4ccc0', true)
