insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3cf4f8d1-518f-53e2-b0ee-7668d60aecd2', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'Why does point-to-point integration become unmanageable?', 'Full connection can need n(n − 1)/2 links (45 for ten systems), each custom and brittle; a hub or API layer reduces this to roughly one connection per system.', 'supplementary', 'csit-603/enterprise-implementation/bf57caeef0f4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('981ff538-70e4-590e-8b0e-f67d8f44c5b3', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', 'c47f138c-f91b-5c80-bedd-fc5d99f947b7', 'What is idempotency and why does it matter for payment interfaces?', 'Processing the same message twice has the same effect as processing it once, so a resent mobile money confirmation does not pay an invoice twice.', 'supplementary', 'csit-603/enterprise-implementation/83b3ac327590', true)
