insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e4490d86-743e-50bf-bd2d-7e51f0d90960', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '343d6fd7-ac41-54ba-a67f-ebf5ff70e26f', '7777fef8-7874-55dc-9848-2a06747ca876', 'Give three examples of measurable go/no-go criteria.', 'No open critical defects with all critical UAT scenarios passed; reconciliation differences zero or signed off; at least the agreed proportion of users certified in each critical role.', 'supplementary', 'csit-603/enterprise-implementation/e63ecbbe056e', true)
