insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6ba6c30c-7cc0-5acc-8602-4cc4cdaa1a54', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'csit-603/enterprise-technology/q01', 'mcq', 'recall', 'easy', 'Define robotic process automation', 'Which description best defines robotic process automation (RPA)?', null, null, '[{"id":"a","text":"Physical robots that move stock in a warehouse"},{"id":"b","text":"Software bots that perform rule-based tasks by operating applications through their user interfaces"},{"id":"c","text":"A database technique for storing historical data"},{"id":"d","text":"A cloud model in which the vendor runs the application"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6ba6c30c-7cc0-5acc-8602-4cc4cdaa1a54', '{"option":"b"}'::jsonb, 'RPA bots mimic a person using screens, keyboards and files. Warehouse robots are physical automation, historical storage describes a data warehouse, and vendor-run applications describe SaaS.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c182a557-004b-5bfa-9733-9ca6a8e7e265', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'csit-603/enterprise-technology/q02', 'matching', 'understand', 'medium', 'Distinguish workflow automation, RPA and API integration', 'Match each automation approach to what it primarily automates.', null, null, '{"left":[{"id":"l1","text":"Workflow automation"},{"id":"l2","text":"RPA"},{"id":"l3","text":"API integration"}],"right":[{"id":"r3","text":"Direct system-to-system data exchange"},{"id":"r2","text":"Repetitive keyboard-and-screen work on existing applications"},{"id":"r1","text":"Coordination of tasks and decisions between people"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c182a557-004b-5bfa-9733-9ca6a8e7e265', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'The three approaches solve different problems. Workflow routes and tracks human work, RPA replaces manual screen operation where no better interface exists, and APIs remove the need for any human or bot to move the data.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a0eb2e7a-7b69-5c6b-bd08-039939883b64', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'csit-603/enterprise-technology/q03', 'scenario', 'apply', 'medium', 'Select the appropriate automation technology', 'What is the most robust long-term solution?', 'Illustrative scenario. A distributor''s staff copy order details from emailed spreadsheets into the ERP. The
customer, a large retailer, has just launched a documented, versioned ordering API for its suppliers.', null, '[{"id":"a","text":"Deploy an RPA bot to copy the spreadsheets into the ERP"},{"id":"b","text":"Integrate the ERP with the retailer''s ordering API"},{"id":"c","text":"Hire more data-entry clerks"},{"id":"d","text":"Build an approval workflow for each spreadsheet"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a0eb2e7a-7b69-5c6b-bd08-039939883b64', '{"option":"b"}'::jsonb, 'Where a stable, versioned API exists, direct integration is more robust than screen-level automation, which breaks when layouts change. RPA might be a tactical stopgap; more clerks scale cost with volume; and an approval workflow does not address the re-keying problem.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bccdb4b8-8cac-59bf-b961-9a16c7b2780c', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'csit-603/enterprise-technology/q04', 'short_answer', 'apply', 'medium', 'Calculate hours of manual effort', 'A task is performed 1,800 times a month and takes 4 minutes each time. How many hours of effort is this per month? (Number only.)', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bccdb4b8-8cac-59bf-b961-9a16c7b2780c', '{"answers":["120"]}'::jsonb, '1,800 × 4 = 7,200 minutes, and 7,200 ÷ 60 = 120 hours. Baseline effort is the starting point for any automation business case, before deducting exception handling.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('dc7cfc18-814b-53df-ab3d-9b634dc9d883', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'csit-603/enterprise-technology/q05', 'true_false', 'understand', 'medium', 'Explain shared responsibility in cloud ERP', 'In a multi-tenant cloud ERP, the vendor is fully responsible for which users can access which data.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('dc7cfc18-814b-53df-ab3d-9b634dc9d883', '{"value":false}'::jsonb, 'False. Security is shared: the vendor secures the platform and infrastructure, but the customer remains responsible for user provisioning, roles, segregation of duties and data governance.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('85536519-7185-5f14-99f4-ebaaded5a954', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'csit-603/enterprise-technology/q06', 'mcq', 'analyse', 'hard', 'Analyse the sensitivity of an RPA business case', 'In an RPA business case, which change would most directly delay payback?', null, null, '[{"id":"a","text":"A higher straight-through processing rate"},{"id":"b","text":"Staff time saved being redeployed to arrears collection"},{"id":"c","text":"Frequent changes to the screens the bot uses, requiring rework"},{"id":"d","text":"A lower hourly staff cost being replaced by a higher one"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('85536519-7185-5f14-99f4-ebaaded5a954', '{"option":"c"}'::jsonb, 'Screen changes break bots and add maintenance cost, reducing net benefit and pushing payback later. Higher straight-through processing and redeployment increase realised benefit, and a higher staff cost increases the value of time saved.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e7ee3930-336b-55e0-9018-03341b77f262', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'csit-603/enterprise-technology/q07', 'mcq', 'evaluate', 'hard', 'Evaluate cloud ERP deployment models', 'A group with a large ERP at head office wants simple, fast-to-deploy systems for small subsidiaries, consolidated monthly. Which approach is most appropriate?', null, null, '[{"id":"a","text":"Two-tier ERP with multi-tenant cloud ERP at subsidiaries integrated with the corporate system"},{"id":"b","text":"Copy the full head office ERP to every subsidiary on local servers"},{"id":"c","text":"Let each subsidiary choose any spreadsheet system it likes"},{"id":"d","text":"Abandon consolidation and report each subsidiary separately"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e7ee3930-336b-55e0-9018-03341b77f262', '{"option":"a"}'::jsonb, 'Two-tier ERP balances standardisation and speed: lightweight cloud ERP meets subsidiary needs while integration supports consolidation. Replicating the full ERP is costly and heavy for small units; uncontrolled spreadsheets undermine data quality; and abandoning consolidation fails group reporting needs.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('689ff88f-86dd-5ed4-ad54-4f1b9adfb04b', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'f140168b-4ec9-582f-8869-fdda4d9f958c', 'csit-603/enterprise-technology/q08', 'short_answer', 'recall', 'easy', 'Name the access principle of minimum necessary rights', 'Name the principle that each user should receive only the access needed to perform their job.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('689ff88f-86dd-5ed4-ad54-4f1b9adfb04b', '{"answers":["Least privilege","principle of least privilege","minimum privilege"]}'::jsonb, 'Least privilege limits the damage any compromised or careless account can cause and makes segregation of duties easier to maintain.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f10189fd-3781-56ce-8ab7-12155f0f3db2', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'f140168b-4ec9-582f-8869-fdda4d9f958c', 'csit-603/enterprise-technology/q09', 'mcq', 'understand', 'medium', 'Explain the purpose of segregation of duties', 'What is the main purpose of segregation of duties?', null, null, '[{"id":"a","text":"To make each employee''s job more varied"},{"id":"b","text":"To prevent any one person from both committing and concealing an error or fraud"},{"id":"c","text":"To reduce the number of system licences required"},{"id":"d","text":"To speed up approval of transactions"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f10189fd-3781-56ce-8ab7-12155f0f3db2', '{"option":"b"}'::jsonb, 'SoD divides authorisation, custody, recording and reconciliation so that one person cannot complete and hide an irregular transaction. It is not intended to vary jobs, save licences or speed approvals; it may in fact add steps.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7fc3c6c7-b955-5583-96ba-f4adb0e332b7', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'f140168b-4ec9-582f-8869-fdda4d9f958c', 'csit-603/enterprise-technology/q10', 'scenario', 'analyse', 'medium', 'Detect a segregation of duties conflict', 'What does this assignment show?', 'Illustrative scenario. In a pharmacy chain''s ERP, Efua holds the accounts payable role (post supplier invoices)
and the treasury role (release payments). Each role on its own is conflict-free.', null, '[{"id":"a","text":"There is no risk because each role is clean"},{"id":"b","text":"A user-level conflict that lets Efua post and pay a fictitious invoice"},{"id":"c","text":"A network security weakness"},{"id":"d","text":"A data migration error"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7fc3c6c7-b955-5583-96ba-f4adb0e332b7', '{"option":"b"}'::jsonb, 'Clean roles can combine into a conflict at user level. Posting invoices and releasing payment together allows a fictitious invoice to be created and paid. This is an authorisation and process-control issue, not a network or migration problem.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c1a11677-b26b-5dec-8d28-5e59223cdcda', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'f140168b-4ec9-582f-8869-fdda4d9f958c', 'csit-603/enterprise-technology/q11', 'true_false', 'understand', 'medium', 'Explain compensating controls', 'Where an SoD conflict cannot practically be removed, an independent review of a payment report by a manager can serve as a compensating control.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c1a11677-b26b-5dec-8d28-5e59223cdcda', '{"value":true}'::jsonb, 'True. Compensating controls such as independent review, approval thresholds and exception reports reduce residual risk where staffing prevents full separation. They should be documented, owned and periodically tested.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('28c34f76-dd65-5e4c-8924-f272537a70fc', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'f140168b-4ec9-582f-8869-fdda4d9f958c', 'csit-603/enterprise-technology/q12', 'matching', 'understand', 'medium', 'Match security layers to typical controls', 'Match each enterprise security layer to a typical control.', null, null, '{"left":[{"id":"l1","text":"Identity and authentication"},{"id":"l2","text":"Application authorisation"},{"id":"l3","text":"Business process controls"},{"id":"l4","text":"Monitoring and audit"},{"id":"l5","text":"Data protection"}],"right":[{"id":"r2","text":"Roles restricting transactions by branch"},{"id":"r5","text":"Encryption at rest and masking of sensitive fields"},{"id":"r4","text":"Alerts on changes to supplier bank details"},{"id":"r3","text":"Three-way match of order, receipt and invoice"},{"id":"r1","text":"Multi-factor authentication and prompt removal of leavers"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('28c34f76-dd65-5e4c-8924-f272537a70fc', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Defence in depth layers different controls so that a failure in one is caught by another. Recognising which layer a control belongs to helps identify gaps in a security design.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0738d3a7-907d-592b-aaa8-2b6f186df4c7', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'f140168b-4ec9-582f-8869-fdda4d9f958c', 'csit-603/enterprise-technology/q13', 'mcq', 'apply', 'medium', 'Apply the conflict matrix to procure-to-pay', 'Which pair of functions represents the most direct risk of paying a fictitious supplier?', null, null, '[{"id":"a","text":"Approve purchase order and record goods receipt"},{"id":"b","text":"Maintain supplier master data and release payment"},{"id":"c","text":"Create purchase order and view stock levels"},{"id":"d","text":"Record goods receipt and print a delivery note"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0738d3a7-907d-592b-aaa8-2b6f186df4c7', '{"option":"b"}'::jsonb, 'A user who can create or alter a supplier, including bank details, and also release payments can pay a fictitious or redirected supplier directly. The other pairs either involve lower-risk functions or do not touch payment.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('22704f2a-9711-5bfb-b085-41eb3c672258', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'f140168b-4ec9-582f-8869-fdda4d9f958c', 'csit-603/enterprise-technology/q14', 'true_false', 'evaluate', 'hard', 'Evaluate the Barings case in control terms', 'The Barings collapse is best explained as a failure of network security controls.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('22704f2a-9711-5bfb-b085-41eb3c672258', '{"value":false}'::jsonb, 'False. The central failure was organisational: Nick Leeson controlled both trading and the settlement operations that recorded and reconciled trades, allowing losses to be concealed, combined with weak management oversight. It is a segregation of duties and monitoring failure, not a network breach.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d7865406-97bc-5423-8e03-2b9b64d6e54b', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'd5dc0291-fd02-50fd-9331-d209e2e3268b', 'csit-603/enterprise-technology/q15', 'mcq', 'recall', 'easy', 'Identify the components of a star schema', 'In a star schema, what does the central fact table contain?', null, null, '[{"id":"a","text":"Descriptions of products and customers"},{"id":"b","text":"Numeric measurements of business events, such as quantity and revenue"},{"id":"c","text":"User passwords and roles"},{"id":"d","text":"The ETL program code"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d7865406-97bc-5423-8e03-2b9b64d6e54b', '{"option":"b"}'::jsonb, 'Fact tables hold measurements at a defined grain, linked to dimension tables (product, customer, date, branch) that describe the context. Security data and code are not part of the dimensional model.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c195d340-61d9-5c0c-83c1-c9bc885f5ff1', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'd5dc0291-fd02-50fd-9331-d209e2e3268b', 'csit-603/enterprise-technology/q16', 'short_answer', 'apply', 'medium', 'Calculate gross margin percentage', 'Revenue is GHS 500,000 and cost of goods sold is GHS 400,000. What is the gross margin percentage? (Number only, without the % sign.)', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c195d340-61d9-5c0c-83c1-c9bc885f5ff1', '{"answers":["20","20%"]}'::jsonb, 'Gross margin % = (500,000 − 400,000) / 500,000 = 100,000 / 500,000 = 20%. Note that margin is calculated on revenue, not on cost; on cost the mark-up would be 25%.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0010c3c0-e563-5c82-9931-72604102cdea', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'd5dc0291-fd02-50fd-9331-d209e2e3268b', 'csit-603/enterprise-technology/q17', 'scenario', 'analyse', 'hard', 'Interpret interacting KPIs', 'What is the most appropriate conclusion?', 'Illustrative scenario. Branch X has a gross margin of 30% and stock turnover of 4 times a year. Branch Y has a
gross margin of 25% and stock turnover of 6 times a year. Their average inventories differ.', null, '[{"id":"a","text":"Branch X is clearly better because its margin is higher"},{"id":"b","text":"Branch Y is clearly better because its turnover is higher"},{"id":"c","text":"The KPIs must be considered together, for example via gross margin return on inventory, before judging"},{"id":"d","text":"The data is meaningless because the branches differ"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0010c3c0-e563-5c82-9931-72604102cdea', '{"option":"c"}'::jsonb, 'Margin and turnover pull in different directions, so neither alone ranks the branches. A combined measure such as gross profit per cedi of average inventory, plus drill-down by product category, gives a sounder judgement. Dismissing the data ignores what comparative analysis can reveal.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('fae6e5d2-54e9-5301-88bd-97d218d72411', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'd5dc0291-fd02-50fd-9331-d209e2e3268b', 'csit-603/enterprise-technology/q18', 'matching', 'understand', 'medium', 'Distinguish analytics types', 'Match each type of analytics to the question it answers.', null, null, '{"left":[{"id":"l1","text":"Descriptive"},{"id":"l2","text":"Diagnostic"},{"id":"l3","text":"Predictive"},{"id":"l4","text":"Prescriptive"}],"right":[{"id":"r2","text":"Why did it happen?"},{"id":"r1","text":"What happened?"},{"id":"r3","text":"What is likely to happen?"},{"id":"r4","text":"What should we do?"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
