insert into public.question_keys (question_id, correct, explanation, model_answer) values ('fae6e5d2-54e9-5301-88bd-97d218d72411', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'The sequence reflects increasing analytical maturity. Most early BI value comes from reliable descriptive and diagnostic analysis, which must be trusted before predictive and prescriptive models can be.', null)
