insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6ea204ea-f079-5b82-be7d-5733cb9ad7b1', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'd5dc0291-fd02-50fd-9331-d209e2e3268b', 'csit-603/enterprise-technology/q19', 'mcq', 'apply', 'medium', 'Classify initiatives by depth of digital change', 'A pharmacy moves paper prescriptions into an electronic workflow that routes them to the dispensary. How is this best classified?', null, null, '[{"id":"a","text":"Digitisation"},{"id":"b","text":"Digitalisation"},{"id":"c","text":"Digital transformation of the business model"},{"id":"d","text":"Business intelligence"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6ea204ea-f079-5b82-be7d-5733cb9ad7b1', '{"option":"b"}'::jsonb, 'Changing an existing process with digital tools is digitalisation. Scanning prescriptions alone would be digitisation; launching online consultations with subscription refills would change the business model; BI is about analysis rather than process execution.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6a91a9ff-e669-5c6b-aa9c-74680af1e41d', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'd5dc0291-fd02-50fd-9331-d209e2e3268b', 'csit-603/enterprise-technology/q20', 'true_false', 'evaluate', 'medium', 'Evaluate the role of leadership in digital transformation', 'According to Westerman, Bonnet and McAfee, digital capabilities alone are sufficient for successful digital transformation.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6a91a9ff-e669-5c6b-aa9c-74680af1e41d', '{"value":false}'::jsonb, 'False. Their framework pairs digital capabilities with leadership capabilities such as vision, engagement and governance. Technology without leadership rarely changes how an organisation works.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('98dd151f-0430-520a-a278-29644e85971a', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'd5dc0291-fd02-50fd-9331-d209e2e3268b', 'csit-603/enterprise-technology/q21', 'short_answer', 'apply', 'medium', 'Calculate days of inventory', 'Stock turnover is 5 times per year. Using 365 days, how many days of inventory does this represent? (Number only.)', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('98dd151f-0430-520a-a278-29644e85971a', '{"answers":["73"]}'::jsonb, 'Days of inventory = 365 / turnover = 365 / 5 = 73 days. Higher turnover means fewer days of stock held, which frees cash but may risk stock-outs.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9cacdaf0-d702-50cd-8e18-f10e28d622a3', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', null, 'csit-603/enterprise-technology/q22', 'case_analysis', 'evaluate', 'hard', 'Evaluate an enterprise technology roadmap', 'Evaluate Nkabom''s situation and recommend a prioritised enterprise technology roadmap covering automation, security and BI, and the proposed digital transformation.', null, 'Illustrative scenario. Nkabom Retail, a Ghanaian chain of twenty convenience stores, runs a cloud ERP. The finance
director wants RPA bots to compile the weekly sales spreadsheet from each store''s ERP screens. Store managers
currently create, approve and receive their own purchase orders, and two head office staff can both edit supplier
bank details and release payments. Board reports are assembled manually and figures often differ between
departments. The chief executive wants to "transform the business digitally" with a delivery app within a year.', null, 25, array['Diagnosis of the core problems and their business risk', 'Automation - RPA versus reporting from governed data', 'Security - SoD conflicts, remediation and compensating controls', 'BI - architecture, semantic layer, KPI definitions', 'Digital transformation - readiness and sequencing of the delivery app', 'Prioritised roadmap with justification']::text[], '[{"criterion":"Automation judgement","marks":5,"descriptor":"Recognises that bots scraping ERP screens is inferior to governed BI reporting from ERP data and justifies the alternative."},{"criterion":"Security analysis","marks":6,"descriptor":"Identifies both SoD conflicts, explains the fraud risks and proposes role redesign and compensating controls."},{"criterion":"BI design","marks":5,"descriptor":"Proposes a warehouse or governed data model, semantic layer and KPI definition cards with owners."},{"criterion":"Digital transformation evaluation","marks":5,"descriptor":"Distinguishes digitalisation from transformation and argues for sequencing based on data and process readiness."},{"criterion":"Roadmap and coherence","marks":4,"descriptor":"Presents a prioritised, coherent roadmap with clear rationale."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9cacdaf0-d702-50cd-8e18-f10e28d622a3', '{}'::jsonb, 'Examiners look for prioritisation driven by risk, accurate application of SoD and BI concepts, a reasoned rejection of inappropriate RPA, and a realistic sequencing of transformation on top of trustworthy data.', 'The strongest answers first identify the most urgent risk: the SoD conflicts. Store managers who create, approve
and receive their own purchase orders can order goods for private use or collude with suppliers, and confirm
receipt without independent evidence. Two staff who can both edit supplier bank details and release payment can
redirect funds. Supplier master maintenance should move to a separate officer with second-person approval of bank
detail changes; purchase approval should go to an area manager through workflow, with thresholds; and where small
stores cannot separate receipt from ordering, weekly exception reports and stock counts act as compensating
controls.

Second, RPA scraping ERP screens is a poor fit: the data already sits in a cloud ERP with reporting interfaces, so
a governed BI layer is more robust. A small warehouse or cloud analytics model fed from the ERP, a semantic layer
defining sales, margin and stock measures once, and KPI definition cards with owners would end conflicting figures
in board reports.

Third, the delivery app is a genuine transformation of customer experience, but it depends on accurate real-time
stock and pricing data and on store fulfilment processes. Launching it before data and controls are trusted risks
customer disappointment. A sensible roadmap is: quarter one, fix SoD and access; quarters one and two, build
governed BI and KPIs; quarters two and three, redesign store fulfilment and pilot the app in a few stores; then
scale, measuring order accuracy, delivery time and margin.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('00baf686-4e53-5231-9afc-42f0cdfaeb5d', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', null, 'csit-603/enterprise-technology/q23', 'essay', 'evaluate', 'hard', 'Evaluate the strategic role of cloud ERP', 'Critically evaluate the claim that cloud ERP is now the best choice for most Ghanaian medium-sized enterprises.', null, null, null, 20, array['Introduction defining cloud ERP models', 'Arguments for - cost profile, speed, upgrades, scalability', 'Arguments against - connectivity, currency exposure, customisation limits, lock-in', 'Security and data protection as a shared responsibility', 'Conditions under which the claim holds', 'Conclusion']::text[], '[{"criterion":"Argument and balance","marks":6,"descriptor":"Presents a clear, balanced judgement with conditions."},{"criterion":"Conceptual accuracy","marks":6,"descriptor":"Distinguishes SaaS, private cloud, hosted and on-premise models and uses TCO reasoning correctly."},{"criterion":"Contextual application","marks":5,"descriptor":"Applies the arguments to Ghanaian conditions without invented statistics."},{"criterion":"Structure and expression","marks":3,"descriptor":"Logical structure, clear academic English and correct referencing."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('00baf686-4e53-5231-9afc-42f0cdfaeb5d', '{}'::jsonb, 'Examiners reward conditional, evidence-based judgements that use deployment-model distinctions and TCO reasoning accurately and apply them to local conditions qualitatively.', 'A strong essay defines cloud ERP using the NIST service models and distinguishes multi-tenant SaaS from private
cloud and hosted deployments. Arguments in favour include low upfront cost, rapid deployment, vendor-managed
infrastructure and continuous upgrades, which suit medium-sized firms with small IT teams. Arguments against
include dependence on reliable connectivity at every site, subscription pricing in foreign currency that exposes
firms to exchange-rate movements, restricted customisation under a clean-core model, mandatory release cycles that
require regression testing, and the risk of lock-in without strong data-export clauses.

The essay should stress that security and data protection are shared responsibilities: the customer still owns
user access, roles and SoD, and must satisfy itself that arrangements are consistent with the Data Protection Act,
2012 (Act 843). A TCO comparison over five and ten years, with currency sensitivity, is the right analytical tool.

A balanced conclusion might accept the claim for firms with standard processes, reliable connectivity and limited
IT capacity, while noting that firms with unusual core processes, weak connectivity or long planning horizons
should evaluate private cloud, hosted or on-premise options carefully.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9ce6cfbd-3848-5625-ad7e-793aee374e89', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'What does a workflow engine do when it executes a process model?', 'It creates and routes tasks to the right roles, applies business rules, enforces deadlines with reminders and escalations, handles delegation and records a full audit trail.', 'supplementary', 'csit-603/enterprise-technology/430fd9266c0f', true)
