insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c687a5ea-e0d9-55b0-81fa-e768e6a66818', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'List the five suitability criteria for an RPA candidate.', 'Rule-based, high volume or frequent, stable screens and rules, structured digital inputs, and a mature documented process with known exceptions.', 'supplementary', 'csit-603/enterprise-technology/63aaed607112', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bab91146-b1e4-5918-b1e7-a7fb84b3ba77', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'Why is RPA often described as a tactical bridge?', 'It automates quickly without changing systems, but bots break when screens change; where stable APIs exist or can be built, direct integration is more robust long term.', 'supplementary', 'csit-603/enterprise-technology/b2e531d6dd73', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5068e0da-c51a-5c9d-85ab-573aeb58c65f', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'What drives the benefit in an RPA business case, and what erodes it?', 'Volume, time per case, straight-through processing rate and redeployment of saved time drive it; exceptions, licences, maintenance and screen changes erode it.', 'supplementary', 'csit-603/enterprise-technology/522b16196289', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8771601a-b90e-55c5-96d5-37fe8c60e566', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'What is the "clean core" approach in cloud ERP?', 'Keeping the vendor''s standard code unmodified and extending it only through configuration and published APIs, so that frequent upgrades remain possible.', 'supplementary', 'csit-603/enterprise-technology/3a80186770bb', true)
