insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5c91353f-582e-5949-b335-59d1dbf97a26', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'c407f587-994e-5de9-ac0b-af118ac35d85', 'What is two-tier ERP?', 'A large ERP at corporate level combined with simpler, often cloud, ERP at subsidiaries or branches, integrated for consolidation and intercompany trading.', 'supplementary', 'csit-603/enterprise-technology/5e3f698dabce', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f4a8537a-6d49-50be-af09-6fa7cb215531', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'f140168b-4ec9-582f-8869-fdda4d9f958c', 'What four activities does segregation of duties separate?', 'Authorising a transaction, having custody of the asset, recording the transaction and reconciling or reviewing it.', 'supplementary', 'csit-603/enterprise-technology/d4c2b42da4e9', true)
