insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('460bf944-c047-5be5-a8a2-b0966476b29b', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'f140168b-4ec9-582f-8869-fdda4d9f958c', 'Why is role-based access control easier to govern than user-by-user permissions?', 'Permissions are grouped into job-based roles that can be checked for SoD at design time, provisioned consistently and reviewed by managers in business terms.', 'supplementary', 'csit-603/enterprise-technology/3cf1a3231ec7', true)
