insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a3e00d8b-579e-5ece-bc8c-adacc4e65896', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'f140168b-4ec9-582f-8869-fdda4d9f958c', 'Why must SoD be checked at user level as well as role level?', 'Two individually conflict-free roles assigned to the same user can combine into a conflict, such as posting invoices plus releasing payments.', 'supplementary', 'csit-603/enterprise-technology/44ee31088778', true)
