insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c4680161-5c35-5244-a0d8-944ce72d2eb5', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2e6aa391-1d37-50fe-a5f3-4abebedcc998', 'f140168b-4ec9-582f-8869-fdda4d9f958c', 'Give three examples of compensating controls for an unavoidable SoD conflict.', 'Independent manager review of payment runs or reports, system-enforced approval thresholds, and exception reports or alerts on sensitive changes such as supplier bank details.', 'supplementary', 'csit-603/enterprise-technology/2db2a8b73381', true)
