insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('2f69fb46-06b4-5abd-bb43-5149b3fa2871', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', 'enterprise-case-studies', 'Practical Enterprise Case Studies', 'Applying process analysis and enterprise systems thinking to realistic sector scenarios.', 7, true)
