insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b699722b-341a-5444-a218-c736a2227055', '{"answers":["FEFO","first expired first out","first expired","first out"]}'::jsonb, 'FEFO (first expired, first out) reduces expiry write-offs and patient-safety risk. It differs from FIFO, which issues the oldest received stock first regardless of expiry date.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2115f6bd-3642-52ad-b397-3e2d99aecc99', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '224bfd99-e26b-5e33-927e-114fd1b7b649', 'csit-603/enterprise-case-studies/q02', 'mcq', 'understand', 'medium', 'Explain the order of the six-step case method', 'In the six-step case method, at which point should the enterprise technology be specified?', null, null, '[{"id":"a","text":"First, so that the process can be designed around the product"},{"id":"b","text":"After the as-is process has been diagnosed and the redesign justified"},{"id":"c","text":"Only after go-live, during the post-implementation review"},{"id":"d","text":"It is not needed if the process is redesigned"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2115f6bd-3642-52ad-b397-3e2d99aecc99', '{"option":"b"}'::jsonb, 'Technology is step four: describe, diagnose and redesign first, then choose technology to enable the redesign. Starting with a product risks automating existing weaknesses; leaving it until after go-live is illogical; and most redesigns depend on enabling technology.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('37e04205-f4e6-5ab0-a790-77de7a025cb5', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '224bfd99-e26b-5e33-927e-114fd1b7b649', 'csit-603/enterprise-case-studies/q03', 'scenario', 'apply', 'medium', 'Apply redesign principles to pharmacy replenishment', 'Which redesign best addresses the problem?', 'Illustrative scenario. A pharmacy chain''s branches each phone wholesalers when they notice low stock. Head office
cannot see branch stock, and one branch often runs out of a medicine that another branch holds in surplus.', null, '[{"id":"a","text":"Ask branch pharmacists to phone each other before ordering"},{"id":"b","text":"Generate replenishment proposals from POS-driven reorder points, consolidated at head office, with inter-branch transfers considered first"},{"id":"c","text":"Double the safety stock at every branch"},{"id":"d","text":"Allow each branch to choose its own wholesaler without approval"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('37e04205-f4e6-5ab0-a790-77de7a025cb5', '{"option":"b"}'::jsonb, 'System-driven proposals based on real-time sales and stock, consolidated centrally, give visibility, leverage volume and allow surplus to be transferred. Phoning is unreliable; doubling stock raises cost and expiry risk; and unapproved independent buying worsens fragmentation and control.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e36d9d27-7749-5cb0-994f-99b492cd41ee', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '224bfd99-e26b-5e33-927e-114fd1b7b649', 'csit-603/enterprise-case-studies/q04', 'true_false', 'understand', 'medium', 'Explain batch traceability', 'Batch traceability allows a pharmacy chain to identify which branches received and sold a recalled batch.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
