insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e36d9d27-7749-5cb0-994f-99b492cd41ee', '{"value":true}'::jsonb, 'True. Capturing batch numbers at receipt and deducting by batch at sale links each batch to its supplier, location and sales, so recalls can be targeted quickly.', null)
