insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4bee0fc6-d68b-554c-afcb-4b0a433be1e9', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '224bfd99-e26b-5e33-927e-114fd1b7b649', 'csit-603/enterprise-case-studies/q05', 'matching', 'analyse', 'medium', 'Link hospital weaknesses to redesign steps', 'Match each as-is hospital weakness to the redesign step that addresses it.', null, null, '{"left":[{"id":"l1","text":"Handwritten prescriptions misread at the pharmacy"},{"id":"l2","text":"Services provided but never billed"},{"id":"l3","text":"Patients queuing repeatedly at each department"},{"id":"l4","text":"Doctors unable to see previous results"}],"right":[{"id":"r1","text":"Electronic prescribing with allergy checks"},{"id":"r4","text":"Results flowing into a shared electronic medical record"},{"id":"r2","text":"Automatic charge posting at the point of care"},{"id":"r3","text":"Electronic orders and a single payment point"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
