insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4bee0fc6-d68b-554c-afcb-4b0a433be1e9', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'A good redesign links each diagnosed weakness to a specific change. This traceability from weakness to redesign to KPI is what examiners look for in case analyses.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ed1966fc-4625-5028-8929-68296a567c88', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '224bfd99-e26b-5e33-927e-114fd1b7b649', 'csit-603/enterprise-case-studies/q06', 'mcq', 'analyse', 'hard', 'Identify a control weakness in an as-is process', 'In the illustrative pharmacy''s as-is process, which weakness creates the greatest fraud risk?', null, null, '[{"id":"a","text":"Expiry dates checked monthly by visual inspection"},{"id":"b","text":"The same person ordering, receiving and paying small suppliers"},{"id":"c","text":"Sales recorded by value rather than batch"},{"id":"d","text":"Claims compiled at month-end"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ed1966fc-4625-5028-8929-68296a567c88', '{"option":"b"}'::jsonb, 'Combining ordering, receipt and payment in one person is a segregation of duties conflict allowing fictitious or inflated purchases to be paid. The other weaknesses cause waste, poor traceability or claim errors, but are not primarily fraud enablers.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d44d41dc-a29b-5903-b67c-30ef3ec35428', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '224bfd99-e26b-5e33-927e-114fd1b7b649', 'csit-603/enterprise-case-studies/q07', 'true_false', 'evaluate', 'hard', 'Evaluate lessons from NPfIT', 'A key lesson commonly drawn from England''s National Programme for IT is that central technology procurement should precede engagement with clinicians and local organisations.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d44d41dc-a29b-5903-b67c-30ef3ec35428', '{"value":false}'::jsonb, 'False. Criticism of the programme highlighted weak engagement with clinicians and local organisations. The lesson is that understanding local processes and involving the people who deliver care must come first.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d19efdc9-748f-5e2c-b4fe-2b0cab35b718', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '10a0f9b5-cb19-570e-a09f-e1c564604ea8', 'csit-603/enterprise-case-studies/q08', 'short_answer', 'apply', 'medium', 'Calculate actual food cost', 'Opening ingredient stock is GHS 10,000, purchases GHS 15,000 and closing stock GHS 9,000. What is the actual food cost in GHS? (Number only.)', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d19efdc9-748f-5e2c-b4fe-2b0cab35b718', '{"answers":["16000","16,000"]}'::jsonb, 'Actual food cost = opening + purchases − closing = 10,000 + 15,000 − 9,000 = 16,000. Dividing by food sales gives the food cost percentage, which is compared with theoretical cost from recipes.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4e785390-fa4e-5517-8dbd-2242bbd54040', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '10a0f9b5-cb19-570e-a09f-e1c564604ea8', 'csit-603/enterprise-case-studies/q09', 'mcq', 'apply', 'medium', 'Calculate a shrinkage rate', 'A category''s system stock value is GHS 40,000 and the physical count is GHS 38,800. What is the shrinkage rate?', null, null, '[{"id":"a","text":"1.2%"},{"id":"b","text":"3.0%"},{"id":"c","text":"3.1%"},{"id":"d","text":"97.0%"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4e785390-fa4e-5517-8dbd-2242bbd54040', '{"option":"b"}'::jsonb, 'Shrinkage = 40,000 − 38,800 = 1,200; rate = 1,200 / 40,000 = 3.0%. Dividing by the physical value gives about 3.1%, which uses the wrong base; 97% is the accuracy ratio, not the loss.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b226e59a-4742-5188-90d4-21f491c583ea', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '10a0f9b5-cb19-570e-a09f-e1c564604ea8', 'csit-603/enterprise-case-studies/q10', 'scenario', 'analyse', 'medium', 'Interpret theoretical versus actual food cost', 'What is the most appropriate first response?', 'Illustrative scenario. A restaurant''s recipe-based theoretical food cost is 30% of sales, but its actual food cost
over four weeks is consistently 36%.', null, '[{"id":"a","text":"Raise menu prices by 6% immediately"},{"id":"b","text":"Investigate waste, portion sizes, unrecorded staff meals, theft and recipe accuracy"},{"id":"c","text":"Ignore the variance because recipes are never accurate"},{"id":"d","text":"Stop recording ingredient purchases"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b226e59a-4742-5188-90d4-21f491c583ea', '{"option":"b"}'::jsonb, 'A persistent variance signals operational losses or inaccurate recipes, which must be diagnosed before acting. Raising prices treats the symptom, ignoring the variance wastes the control, and stopping recording removes the data needed to manage cost.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('806ad552-b272-51b9-ab03-81c46bff2036', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '10a0f9b5-cb19-570e-a09f-e1c564604ea8', 'csit-603/enterprise-case-studies/q11', 'true_false', 'understand', 'medium', 'Explain the role of a kitchen display system', 'The main value of a kitchen display system is that it routes orders to stations, tracks preparation times and helps synchronise dishes for a table.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('806ad552-b272-51b9-ab03-81c46bff2036', '{"value":true}'::jsonb, 'True. A KDS does more than replace paper: it routes items, shows order age, coordinates timing and records performance data, enabling KPIs such as ticket time per station.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('60b3ceb6-ed10-525e-b2de-ac29bee37108', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '10a0f9b5-cb19-570e-a09f-e1c564604ea8', 'csit-603/enterprise-case-studies/q12', 'matching', 'understand', 'medium', 'Match retail controls to the risks they address', 'Match each supermarket control to the risk it mainly addresses.', null, null, '{"left":[{"id":"l1","text":"Supervisor authorisation for price overrides"},{"id":"l2","text":"Weekly cycle counts of high-risk categories"},{"id":"l3","text":"Three-way match by accounts payable"},{"id":"l4","text":"Daily automatic payment matching"}],"right":[{"id":"r4","text":"Electronic payment errors going undetected"},{"id":"r1","text":"Cashiers under-charging friends or keying wrong prices"},{"id":"r3","text":"Paying for goods not received"},{"id":"r2","text":"Shrinkage discovered months too late"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('60b3ceb6-ed10-525e-b2de-ac29bee37108', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each control is designed into the to-be process to address a diagnosed risk, with the system enforcing and logging it. Controls without a linked risk add friction without value.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('54b54b66-5144-571a-853b-b16bceb03ede', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '10a0f9b5-cb19-570e-a09f-e1c564604ea8', 'csit-603/enterprise-case-studies/q13', 'mcq', 'evaluate', 'hard', 'Evaluate the lesson of Target Canada', 'Which conclusion is best supported by widely reported accounts of Target''s Canadian expansion?', null, null, '[{"id":"a","text":"POS hardware choice was the decisive factor"},{"id":"b","text":"Product master data quality and rapid scaling on new systems undermined replenishment"},{"id":"c","text":"Canadian customers did not want to shop at Target"},{"id":"d","text":"The failure had nothing to do with enterprise systems"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('54b54b66-5144-571a-853b-b16bceb03ede', '{"option":"b"}'::jsonb, 'Press accounts described problems with supply chain processes and inaccurate product data in new systems, which disrupted replenishment while many stores opened rapidly. The other options are unsupported by the documented accounts.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ce479243-c5ab-5209-bf31-d67258e57d29', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '28e34241-338e-5ab7-884a-029b631bb023', 'csit-603/enterprise-case-studies/q14', 'mcq', 'apply', 'medium', 'Calculate OTIF correctly', 'Of 2,000 orders, 1,860 were on time, 1,900 were in full and 1,780 were both on time and in full. What is OTIF?', null, null, '[{"id":"a","text":"88.4%"},{"id":"b","text":"89.0%"},{"id":"c","text":"93.0%"},{"id":"d","text":"95.0%"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ce479243-c5ab-5209-bf31-d67258e57d29', '{"option":"b"}'::jsonb, 'OTIF counts orders meeting both conditions: 1,780 / 2,000 = 89.0%. Multiplying 93% by 95% gives about 88.4%, which wrongly assumes independent failures; 93% and 95% are the separate on-time and in-full rates.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('dc4d21f0-afc1-5e7d-a2ed-bc6c1f4b3888', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '28e34241-338e-5ab7-884a-029b631bb023', 'csit-603/enterprise-case-studies/q15', 'matching', 'understand', 'medium', 'Match WMS functions to descriptions', 'Match each warehouse management function to its description.', null, null, '{"left":[{"id":"l1","text":"Putaway"},{"id":"l2","text":"Slotting"},{"id":"l3","text":"Wave picking"},{"id":"l4","text":"Cycle counting"}],"right":[{"id":"r3","text":"Picking batches of orders aligned with vehicle departures"},{"id":"r2","text":"Assigning products to locations to minimise travel"},{"id":"r1","text":"Moving received goods to a system-directed storage location"},{"id":"r4","text":"Regularly counting a subset of locations to keep stock accurate"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('dc4d21f0-afc1-5e7d-a2ed-bc6c1f4b3888', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'These functions together turn a warehouse from memory-based searching into directed, measurable work, each targeting a specific as-is weakness.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('20f1366c-8b11-59cf-85ed-da8c6a636555', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '28e34241-338e-5ab7-884a-029b631bb023', 'csit-603/enterprise-case-studies/q16', 'scenario', 'apply', 'medium', 'Apply technology to shorten the cash cycle', 'Which redesign best addresses both problems?', 'Illustrative scenario. A distributor raises invoices only when drivers return paper delivery notes, often several
days after delivery. Customers then dispute deliveries for which no clear evidence exists.', null, '[{"id":"a","text":"Ask drivers to return paper notes more quickly"},{"id":"b","text":"Electronic proof of delivery on a driver app that triggers the invoice automatically"},{"id":"c","text":"Invoice customers before goods are picked"},{"id":"d","text":"Hire an extra clerk to file delivery notes"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('20f1366c-8b11-59cf-85ed-da8c6a636555', '{"option":"b"}'::jsonb, 'Electronic POD with signature, photo, timestamp and location provides dispute evidence and triggers invoicing at delivery, shortening the cash cycle. Faster paper handling helps marginally; pre-invoicing causes credit notes when deliveries change; and extra filing staff do not address delay or evidence.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('55fca900-e023-5da6-b94f-7dad3b8e05a3', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '28e34241-338e-5ab7-884a-029b631bb023', 'csit-603/enterprise-case-studies/q17', 'true_false', 'understand', 'medium', 'Explain the limits of route optimisation', 'Route planning software produces good routes regardless of the accuracy of customer addresses and time-per-drop estimates.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('55fca900-e023-5da6-b94f-7dad3b8e05a3', '{"value":false}'::jsonb, 'False. Route plans depend on the constraints and data supplied. Poor addresses or unrealistic drop times lead to plans that drivers cannot execute; digital addresses and historic delivery data improve them.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9b958f47-5482-5611-a7cb-62deefcb3dab', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '28e34241-338e-5ab7-884a-029b631bb023', 'csit-603/enterprise-case-studies/q18', 'short_answer', 'apply', 'easy', 'Calculate pick accuracy', 'Out of 20,000 order lines, 19,800 were picked correctly. What is the pick accuracy percentage? (Number only.)', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9b958f47-5482-5611-a7cb-62deefcb3dab', '{"answers":["99","99%","99.0"]}'::jsonb, '19,800 / 20,000 = 99%. Even at 99%, 200 lines were wrong, each a potential complaint or credit note, which is why scanned picking and good slotting matter.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('44298e8e-6ea0-56e5-b5bf-6ad6851ce11b', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '28e34241-338e-5ab7-884a-029b631bb023', 'csit-603/enterprise-case-studies/q19', 'mcq', 'evaluate', 'hard', 'Evaluate the lessons of FoxMeyer', 'What is the most defensible lesson from FoxMeyer''s mid-1990s experience?', null, null, '[{"id":"a","text":"Warehouse automation should never be used by distributors"},{"id":"b","text":"Combining a new ERP with warehouse automation at once multiplies risk and must be proven at realistic volumes"},{"id":"c","text":"SAP software is unsuitable for distribution firms"},{"id":"d","text":"Projects should be justified by the most optimistic savings possible"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('44298e8e-6ea0-56e5-b5bf-6ad6851ce11b', '{"option":"b"}'::jsonb, 'FoxMeyer combined an ERP implementation with highly automated warehouses and encountered serious integration and volume problems before its 1996 bankruptcy. The defensible lesson concerns risk concentration and testing at scale, not a blanket rejection of automation or a particular vendor; optimistic savings assumptions were part of the problem.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4ec961cd-d327-5815-bb3f-81866c00fd78', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', null, 'csit-603/enterprise-case-studies/q20', 'case_analysis', 'evaluate', 'hard', 'Conduct a full process redesign case analysis', 'Using the six-step case method, analyse FreshWay''s as-is process, propose a redesigned process and supporting enterprise technology, define KPIs, and evaluate the main risks and change-management needs.', null, 'Illustrative scenario. FreshWay is a Ghanaian business with a central kitchen in Accra that supplies ten small
restaurant outlets and a growing delivery service. Outlets order ingredients and prepared items from the central
kitchen by WhatsApp each evening. The central kitchen plans production on paper, and its two vans follow routes
chosen by the drivers. Outlets frequently receive the wrong quantities, food is wasted when outlets over-order,
and delivery customers complain about late orders. Each outlet uses a different till, so head office cannot see
sales or food cost by outlet. The owner has asked you to recommend an enterprise systems solution.', null, 30, array['As-is process description and diagnosis of weaknesses', 'Redesigned process across outlets, central kitchen and transport', 'Enabling technology - POS and KDS, central ERP with recipes and production planning, routing and POD, BI', 'KPIs with baselines and targets', 'Risks, mitigation and implementation strategy', 'Change management using a recognised model']::text[], '[{"criterion":"As-is diagnosis","marks":6,"descriptor":"Accurately identifies information, waste, control and service weaknesses and links them to business impact."},{"criterion":"Redesigned process","marks":7,"descriptor":"Proposes a coherent to-be process with demand-driven ordering, production planning, routing and electronic POD."},{"criterion":"Technology specification","marks":6,"descriptor":"Specifies integrated POS, KDS, ERP recipes and inventory, routing tools and BI, justified by the redesign."},{"criterion":"KPIs","marks":5,"descriptor":"Defines relevant KPIs such as food cost variance, waste, OTIF to outlets and delivery time, with baselines."},{"criterion":"Risks and change management","marks":6,"descriptor":"Evaluates data, integration and adoption risks, proposes a pilot strategy and applies Kotter or ADKAR meaningfully."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4ec961cd-d327-5815-bb3f-81866c00fd78', '{}'::jsonb, 'Examiners look for systematic use of the six-step method, explicit links between weaknesses, redesign steps, technology and KPIs, realistic risk mitigation and meaningful rather than generic use of change models.', 'A strong answer begins by describing the as-is flow: outlets send WhatsApp orders, the central kitchen plans on
paper, drivers choose routes, and outlets use unconnected tills. Weaknesses include ordering based on guesswork
rather than sales, re-keying and misread messages, over-production and waste, no visibility of outlet sales or food
cost, unplanned routes causing late deliveries, and no evidence when quantities are disputed.

The redesign standardises all outlets on one integrated POS with KDS, so that sales are captured by menu item.
Recipes deduct ingredients and prepared items at each outlet, and the system proposes next-day orders from par
levels and sales forecasts, which outlet managers review rather than create from scratch. The central kitchen''s
ERP consolidates orders into a production plan using recipes for prepared items, and generates picking lists by
route. A routing tool plans van routes with outlet time windows, and drivers capture electronic POD with quantities
received, so discrepancies are recorded immediately. Delivery-platform orders flow into the outlet POS and KDS.

KPIs include food cost variance (actual against theoretical) by outlet, waste value, in-full rate of outlet
deliveries, on-time arrival at outlets, delivery customer order-to-door time and stock-outs, each baselined for at
least a month before go-live.

Risks are inaccurate recipes, poor connectivity at outlets, staff resistance, and over-reliance on forecasts for a
growing business. A pilot with the central kitchen and two outlets, offline-capable POS, and a recipe costing
exercise led by the head chef reduce risk. Using Kotter, the owner creates urgency with waste data, builds a
coalition of the head chef and outlet managers, and publicises early wins such as reduced waste at pilot outlets.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('547aea19-7e48-5c41-adb5-4e574351c8ba', 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', null, 'csit-603/enterprise-case-studies/q21', 'essay', 'evaluate', 'hard', 'Evaluate the role of master data across sector cases', '"In every sector case, the enterprise system succeeds or fails on the quality of its master data." Critically evaluate this statement with reference to pharmacy, retail and distribution scenarios and at least one documented international case.', null, null, null, 20, array['Introduction defining master data and its role in integrated processes', 'Pharmacy - product, batch and supplier data', 'Retail and restaurants - product master and recipes', 'Distribution - customer addresses, locations and product dimensions', 'Counter-argument - process design, controls and people', 'Conclusion']::text[], '[{"criterion":"Argument and judgement","marks":6,"descriptor":"Develops a clear, balanced position on the centrality of master data."},{"criterion":"Application to sector scenarios","marks":6,"descriptor":"Shows concretely how master data supports each redesigned process."},{"criterion":"Use of documented cases","marks":5,"descriptor":"Uses Target Canada or similar cases accurately without invented details."},{"criterion":"Structure and expression","marks":3,"descriptor":"Clear structure, academic tone and correct referencing."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('547aea19-7e48-5c41-adb5-4e574351c8ba', '{}'::jsonb, 'Examiners reward precise examples of how master data enables specific process steps across sectors, accurate use of documented cases and a balanced conclusion that recognises process and people factors.', 'A strong essay defines master data as the shared reference records (products, customers, suppliers, locations,
recipes) on which every transaction depends. In the pharmacy case, accurate product codes, units, batch rules and
shelf-life thresholds are preconditions for FEFO, replenishment and claims. In retail, barcodes, prices and units
drive scanning, perpetual inventory and pricing controls; in restaurants, recipes are the master data that make
theoretical food cost meaningful. In distribution, customer addresses, time windows, product dimensions and
warehouse locations feed routing, slotting and load planning.

The essay uses widely reported accounts of Target''s Canadian expansion, where inaccurate product data disrupted
replenishment, as evidence that poor master data can undermine an entire operation.

A balanced answer then argues that master data is necessary but not sufficient. Process redesign, segregation of
duties, testing at realistic volumes (as FoxMeyer illustrates), training and change management also determine
outcomes; perfect data cannot rescue a poorly designed process or a workforce that bypasses the system. The
conclusion might state that master data quality is the most common single point of failure, but success requires
data, process and people together.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('19981dee-2518-5312-87f8-d84fb6f4514a', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '224bfd99-e26b-5e33-927e-114fd1b7b649', 'What are the six steps of the case analysis method used in this module?', 'Describe the as-is process, diagnose weaknesses, redesign the process, specify enabling technology, define KPIs, and plan for risks and change management.', 'supplementary', 'csit-603/enterprise-case-studies/4e489331850c', true)
