insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('aa516046-d0bf-5c05-998e-095d3b4804b6', null, 'adfca7e6-41fb-5885-8e5b-aa5b3ca0bcdf', '2f69fb46-06b4-5abd-bb43-5149b3fa2871', '10a0f9b5-cb19-570e-a09f-e1c564604ea8', 'Why is the product master the foundation of a supermarket redesign?', 'Scanning, pricing, perpetual inventory, replenishment, receiving and analytics all depend on accurate barcodes, units, costs and prices for every product.', 'supplementary', 'csit-603/enterprise-case-studies/3c62760ca4fc', true)
