insert into public.courses (id, code, slug, title, description, status, status_note, classification, credit_slots, accent, outcomes, sort_order, source, is_published) values ('c70e42f8-2885-5638-8b66-6e3de39938a7', 'CSIT 605', 'csit-605', 'Computer & Cybersecurity', 'The principles, technologies and management practices used to protect information systems. The course covers threats and attacks, network and system defences, cryptography, application and cloud security, governance and risk (including the NIST Cybersecurity Framework 2.0), and hands-on defensive practice. All practical exercises must be performed only on systems you own or are explicitly authorised to test.', 'listed', 'Core course in the MSc IT for Business Semester 1 programme (3 credit slots).', 'core', 3, 'rose', array['Explain core security principles including the CIA triad and the relationship between threats, vulnerabilities and risk.', 'Analyse common attack techniques and recommend proportionate defences.', 'Apply network, system, application and database security controls.', 'Explain and correctly apply cryptographic primitives, certificates and key management.', 'Evaluate cloud and infrastructure security, backup and disaster recovery arrangements.', 'Apply governance, risk assessment and incident response frameworks, including NIST CSF 2.0.']::text[], 3, 'supplementary', true)
  on conflict (id) do update set code = excluded.code, slug = excluded.slug, title = excluded.title, description = excluded.description, status = excluded.status, status_note = excluded.status_note, classification = excluded.classification, credit_slots = excluded.credit_slots, accent = excluded.accent, outcomes = excluded.outcomes, sort_order = excluded.sort_order, source = excluded.source, is_published = excluded.is_published;
insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('9f3aabee-771a-542a-9472-1819111d3d59', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'security-fundamentals', 'Security Fundamentals', 'The vocabulary and principles on which all security decisions rest.', 1, true)
