insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('90762921-08a6-5e20-875e-13608b1b4891', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'threats-and-attacks', 'Threats and Attacks', 'How attackers operate and why their techniques succeed.', 2, true)
