insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e6eb9474-9cfe-53df-8325-c7ac9c1e6dde', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'b34476ae-8459-57d7-bbae-6c1be6f713f2', 'csit-605/threats-and-attacks/ta01', 'matching', 'recall', 'easy', 'Classify malware types by propagation and payload', 'Match each malware type to its defining characteristic.', null, null, '{"left":[{"id":"l1","text":"Worm"},{"id":"l2","text":"Trojan"},{"id":"l3","text":"Virus"},{"id":"l4","text":"Rootkit"},{"id":"l5","text":"Ransomware"}],"right":[{"id":"r4","text":"Hides its presence by subverting the operating system"},{"id":"r1","text":"Spreads across networks by itself by exploiting vulnerabilities"},{"id":"r2","text":"Disguised as legitimate software that the user installs"},{"id":"r3","text":"Attaches to a host file and spreads when that file is run or shared"},{"id":"r5","text":"Encrypts or locks data and demands payment"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e6eb9474-9cfe-53df-8325-c7ac9c1e6dde', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Worms self-propagate without user action, Trojans rely on deception, viruses need a host file, rootkits provide concealment and ransomware''s payload is extortion. Real campaigns frequently combine several of these.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4ad4b717-b8df-5480-ac90-f54694f332d7', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'b34476ae-8459-57d7-bbae-6c1be6f713f2', 'csit-605/threats-and-attacks/ta02', 'mcq', 'understand', 'medium', 'Explain the significance of the Cyber Kill Chain for defenders', 'What is the main defensive insight of the Lockheed Martin Cyber Kill Chain?', null, null, '[{"id":"a","text":"Attackers only need to succeed at the final stage to cause harm"},{"id":"b","text":"The attacker must succeed at every stage, so the defender can stop the intrusion by breaking any one link"},{"id":"c","text":"Defences should focus exclusively on the reconnaissance stage"},{"id":"d","text":"Insider threats are the most common cause of intrusions"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4ad4b717-b8df-5480-ac90-f54694f332d7', '{"option":"b"}'::jsonb, 'The model presents an intrusion as a sequence; disrupting any stage, such as blocking delivery or command and control, breaks the chain. It does not focus solely on reconnaissance, and it says little about insiders, which is one of its acknowledged limitations.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5183257f-f7d4-52c7-9b9c-3c95571a9695', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'b34476ae-8459-57d7-bbae-6c1be6f713f2', 'csit-605/threats-and-attacks/ta03', 'true_false', 'understand', 'medium', 'Recall the patch status relevant to WannaCry', 'WannaCry exploited a vulnerability for which Microsoft had already released a security update before the May 2017 outbreak.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5183257f-f7d4-52c7-9b9c-3c95571a9695', '{"value":true}'::jsonb, 'Microsoft released MS17-010 in March 2017, about two months before WannaCry spread. Unpatched systems with SMBv1 exposed were vulnerable, which is why WannaCry is a patch management lesson rather than a zero-day case.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b57022ce-f5f3-5681-b0ae-fcf46f6506ee', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'b34476ae-8459-57d7-bbae-6c1be6f713f2', 'csit-605/threats-and-attacks/ta04', 'scenario', 'apply', 'medium', 'Apply backup principles to ransomware resilience', 'What is the most important weakness in this arrangement?', 'Illustrative scenario. A fictional Takoradi accounting firm backs up its file server every night to a network-attached storage device that is permanently mapped as a drive on all staff PCs. The firm believes it is protected against ransomware.', null, '[{"id":"a","text":"Nightly backups are too frequent"},{"id":"b","text":"The backup is reachable from compromised PCs, so attackers or ransomware can encrypt or delete it"},{"id":"c","text":"Network-attached storage cannot store accounting files"},{"id":"d","text":"Backups should only be taken monthly to save storage"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b57022ce-f5f3-5681-b0ae-fcf46f6506ee', '{"option":"b"}'::jsonb, 'Human-operated ransomware deliberately seeks reachable backups. At least one copy must be offline or immutable and restore tests must be performed. Frequency is not the problem, and reducing frequency would increase data loss.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b6756a0e-0493-5cff-a405-9bc7c6314154', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'b34476ae-8459-57d7-bbae-6c1be6f713f2', 'csit-605/threats-and-attacks/ta05', 'short_answer', 'recall', 'easy', 'Recall the term for stealing data before encryption', 'What term describes the ransomware tactic of stealing data before encrypting it and threatening to publish it?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b6756a0e-0493-5cff-a405-9bc7c6314154', '{"answers":["double extortion"]}'::jsonb, 'Double extortion means that restoring from backup does not end the incident, because the confidentiality breach and legal duties remain.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a0f0a658-25b4-57cd-8150-166d0a87e660', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'b34476ae-8459-57d7-bbae-6c1be6f713f2', 'csit-605/threats-and-attacks/ta06', 'mcq', 'analyse', 'hard', 'Analyse NotPetya''s propagation and intent', 'Which statement best characterises NotPetya in June 2017?', null, null, '[{"id":"a","text":"A ransomware campaign spread only by phishing emails, whose victims could reliably recover by paying"},{"id":"b","text":"A supply chain attack via a compromised accounting software update that spread laterally and behaved as a destructive wiper disguised as ransomware"},{"id":"c","text":"A denial-of-service attack against DNS providers"},{"id":"d","text":"A credential stuffing campaign against online banking"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a0f0a658-25b4-57cd-8150-166d0a87e660', '{"option":"b"}'::jsonb, 'NotPetya entered via a compromised M.E.Doc update, spread with EternalBlue and stolen credentials, and was designed so that payment would not realistically restore data. It was not phishing-led, nor a DDoS or credential stuffing campaign.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2f155a4d-9697-5398-b651-337017217f9c', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'b34476ae-8459-57d7-bbae-6c1be6f713f2', 'csit-605/threats-and-attacks/ta07', 'mcq', 'evaluate', 'hard', 'Evaluate priorities for ransomware prevention in a small organisation', 'A small clinic exposes remote desktop to the internet with password-only login and keeps backups on a connected drive. With a limited budget, which pair of actions gives the greatest risk reduction?', null, null, '[{"id":"a","text":"Buy a next-generation antivirus licence and redesign the website"},{"id":"b","text":"Put remote access behind a VPN with MFA and create an offline, tested backup"},{"id":"c","text":"Increase password complexity rules and enforce monthly password changes"},{"id":"d","text":"Purchase cyber insurance and accept the remaining risk"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2f155a4d-9697-5398-b651-337017217f9c', '{"option":"b"}'::jsonb, 'Exposed password-only remote access is a leading initial access route, and offline backups determine recovery. Antivirus alone does not stop credential-based intrusion; frequent password changes add little; insurance does not prevent or recover the outage.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('09cb466e-d3c4-5560-8d63-7688a14225ba', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', '977b552f-439d-519e-9709-89af082c71ab', 'csit-605/threats-and-attacks/ta08', 'mcq', 'understand', 'easy', 'Distinguish phishing variants', 'A caller claiming to be from the IT help desk phones an employee and asks her to read out the code just sent to her phone. Which attack type is this?', null, null, '[{"id":"a","text":"Smishing"},{"id":"b","text":"Vishing"},{"id":"c","text":"Whaling"},{"id":"d","text":"Credential stuffing"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('09cb466e-d3c4-5560-8d63-7688a14225ba', '{"option":"b"}'::jsonb, 'Vishing is voice phishing. Smishing uses SMS, whaling targets senior executives and credential stuffing reuses leaked password pairs. Combined vishing and code theft is a common account takeover technique.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('78c6d7f4-f4e6-5182-84f4-038d556de544', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', '977b552f-439d-519e-9709-89af082c71ab', 'csit-605/threats-and-attacks/ta09', 'scenario', 'apply', 'medium', 'Apply process controls against business email compromise', 'Which control most reliably prevents this payment being misdirected?', 'Illustrative scenario. The accounts officer of a fictional Accra construction firm receives an email in an existing thread with a long-standing supplier. It says the supplier''s bank has changed and attaches a letter with new account details. The email address appears identical to the supplier''s usual address.', null, '[{"id":"a","text":"Replying to the email to ask the supplier to confirm the change"},{"id":"b","text":"Calling the supplier on a phone number already held on file, not one in the email, before changing details"},{"id":"c","text":"Checking that the attached letter has a company logo"},{"id":"d","text":"Processing the payment quickly to maintain the supplier relationship"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('78c6d7f4-f4e6-5182-84f4-038d556de544', '{"option":"b"}'::jsonb, 'The mailbox itself may be compromised, so replying reaches the attacker, and logos are easily copied. Out-of-band verification using independently held contact details breaks the fraud. Urgency is exactly what the attacker exploits.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0946dc06-8618-53ce-bfd0-b0c6607fbd84', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', '977b552f-439d-519e-9709-89af082c71ab', 'csit-605/threats-and-attacks/ta10', 'matching', 'understand', 'medium', 'Link persuasion principles to social engineering lures', 'Match each lure to the persuasion principle it primarily exploits.', null, null, '{"left":[{"id":"l1","text":"This is the MD - process this transfer before the board meeting"},{"id":"l2","text":"Your wallet will be blocked in 30 minutes unless you verify now"},{"id":"l3","text":"All staff in your department have already updated their details here"},{"id":"l4","text":"I have fixed your account problem; now just read me the code"}],"right":[{"id":"r3","text":"Social proof"},{"id":"r2","text":"Scarcity and urgency"},{"id":"r4","text":"Reciprocity"},{"id":"r1","text":"Authority"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0946dc06-8618-53ce-bfd0-b0c6607fbd84', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Recognising the principle helps staff pause. Authority invokes seniority, scarcity and urgency forces fast decisions, social proof suggests others complied and reciprocity creates a sense of obligation after a favour.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('59ac843c-7ca7-5ecd-9e87-7d342219ed92', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', '977b552f-439d-519e-9709-89af082c71ab', 'csit-605/threats-and-attacks/ta11', 'true_false', 'understand', 'medium', 'Explain the limits of SMS-based MFA', 'SMS one-time passwords fully protect against phishing because the attacker would also need the victim''s phone.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('59ac843c-7ca7-5ecd-9e87-7d342219ed92', '{"value":false}'::jsonb, 'Attackers can relay codes in real time through adversary-in-the-middle phishing pages, trick victims into reading codes aloud or obtain them via SIM swap. Phishing-resistant MFA bound to the genuine domain, such as FIDO2 keys or passkeys, is much stronger.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5b2c00f7-1b67-590e-aed8-8117a4dc8cff', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', '977b552f-439d-519e-9709-89af082c71ab', 'csit-605/threats-and-attacks/ta12', 'short_answer', 'recall', 'easy', 'Recall the term for fraudulent transfer of a mobile number', 'What is the term for fraudulently transferring a victim''s mobile number to a SIM card controlled by an attacker?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5b2c00f7-1b67-590e-aed8-8117a4dc8cff', '{"answers":["SIM swap","SIM swapping","SIM-swap","SIM swap fraud"]}'::jsonb, 'SIM swap lets an attacker receive the victim''s SMS codes and calls, enabling mobile money and bank account takeover. Strong identity checks and insider controls on SIM replacement are key defences.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4a44ff39-00b9-5993-a8d6-f19a3e5509b7', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', '977b552f-439d-519e-9709-89af082c71ab', 'csit-605/threats-and-attacks/ta13', 'mcq', 'analyse', 'hard', 'Classify insider types in the Twitter 2020 case', 'In the July 2020 Twitter compromise, the employees whose credentials were captured by phone-based phishing are best classified as which type of insider?', null, null, '[{"id":"a","text":"Malicious insiders"},{"id":"b","text":"Compromised insiders"},{"id":"c","text":"Third-party contractors acting with intent"},{"id":"d","text":"Negligent insiders who leaked data by email"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4a44ff39-00b9-5993-a8d6-f19a3e5509b7', '{"option":"b"}'::jsonb, 'The employees did not intend harm; their legitimate access was taken over by external attackers after vishing. That makes them compromised insiders. The case also shows how over-broad access to administrative tools magnifies impact.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2b450891-730b-540e-b811-e7de8e579145', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', '977b552f-439d-519e-9709-89af082c71ab', 'csit-605/threats-and-attacks/ta14', 'mcq', 'evaluate', 'hard', 'Evaluate awareness programme metrics', 'Which metric best indicates that a phishing awareness programme is building a healthy security culture?', null, null, '[{"id":"a","text":"The percentage of staff who attended the annual lecture"},{"id":"b","text":"A rising proportion of staff who quickly report suspicious messages"},{"id":"c","text":"The number of staff disciplined for clicking simulated phishing links"},{"id":"d","text":"The total number of phishing emails blocked by the filter"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2b450891-730b-540e-b811-e7de8e579145', '{"option":"b"}'::jsonb, 'Reporting rate and speed show that staff recognise and escalate threats, enabling fast response. Attendance does not show behaviour change, discipline discourages reporting and filter statistics measure technology rather than people.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a7413e4b-cc1b-550f-bcd7-053abf58def8', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'bf2bf203-69a7-5838-b29a-bc097f9c9b04', 'csit-605/threats-and-attacks/ta15', 'mcq', 'understand', 'medium', 'Distinguish password spraying from credential stuffing', 'Logs show the same single password tried once against each of 2,000 different accounts from a few IP addresses. Which attack is most likely?', null, null, '[{"id":"a","text":"Credential stuffing"},{"id":"b","text":"Password spraying"},{"id":"c","text":"Offline brute force"},{"id":"d","text":"Volumetric DDoS"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a7413e4b-cc1b-550f-bcd7-053abf58def8', '{"option":"b"}'::jsonb, 'Spraying tries a few common passwords across many accounts to avoid lockout. Credential stuffing uses many different leaked username-password pairs; offline brute force happens on stolen hashes, not live logins; DDoS targets availability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('021c4840-b379-596d-8a78-a6407c9f19fa', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'bf2bf203-69a7-5838-b29a-bc097f9c9b04', 'csit-605/threats-and-attacks/ta16', 'short_answer', 'apply', 'medium', 'Apply the search-space formula', 'How many possible combinations does a 4-digit numeric PIN have?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('021c4840-b379-596d-8a78-a6407c9f19fa', '{"answers":["10000","10,000","ten thousand"]}'::jsonb, 'Search space is N^L = 10^4 = 10,000. Such a small space is only safe with strict attempt limits and binding to a device or SIM, which is why SIM replacement security matters for mobile money.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3f6661ba-bbc4-5ad7-92e2-7d7e4f9e494e', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'bf2bf203-69a7-5838-b29a-bc097f9c9b04', 'csit-605/threats-and-attacks/ta17', 'matching', 'understand', 'medium', 'Match DoS categories to resources and defences', 'Match each denial-of-service category to the resource it primarily exhausts.', null, null, '{"left":[{"id":"l1","text":"Volumetric attack"},{"id":"l2","text":"SYN flood"},{"id":"l3","text":"Repeated expensive search requests"}],"right":[{"id":"r2","text":"Connection state tables"},{"id":"r1","text":"Network bandwidth"},{"id":"r3","text":"Application server and database capacity"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3f6661ba-bbc4-5ad7-92e2-7d7e4f9e494e', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'Volumetric floods saturate links and need upstream scrubbing; protocol attacks such as SYN floods exhaust connection tables and are countered with SYN cookies and limits; application-layer attacks consume server and database resources and are countered by rate limiting and caching.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f84a65d3-4331-53a2-8673-e88e5392cf6b', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'bf2bf203-69a7-5838-b29a-bc097f9c9b04', 'csit-605/threats-and-attacks/ta18', 'true_false', 'understand', 'medium', 'Explain NIST guidance on password changes', 'NIST SP 800-63B recommends forcing all users to change their passwords every 30 days regardless of any evidence of compromise.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f84a65d3-4331-53a2-8673-e88e5392cf6b', '{"value":false}'::jsonb, 'NIST SP 800-63B advises against arbitrary periodic changes, which encourage predictable patterns, and recommends changes when there is evidence of compromise, along with screening against breached and common passwords.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('29753c2e-8b17-5f2b-be76-61699f2800a3', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'bf2bf203-69a7-5838-b29a-bc097f9c9b04', 'csit-605/threats-and-attacks/ta19', 'scenario', 'analyse', 'hard', 'Analyse lockout trade-offs', 'What is the most serious weakness of the bank''s policy in this situation?', 'Illustrative scenario. A fictional Ghanaian online bank locks any account permanently after three failed login attempts until the customer visits a branch. A competitor''s customers report that a criminal group has been deliberately entering wrong passwords for thousands of usernames harvested from social media.', null, '[{"id":"a","text":"It allows unlimited guessing against each account"},{"id":"b","text":"It enables attackers to cause a denial of service by locking out large numbers of legitimate customers, while doing little against spraying"},{"id":"c","text":"It makes MFA unnecessary"},{"id":"d","text":"It prevents the bank from logging failed logins"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('29753c2e-8b17-5f2b-be76-61699f2800a3', '{"option":"b"}'::jsonb, 'Aggressive permanent lockout turns authentication into an availability weapon and gives little protection against spraying, which uses very few attempts per account. Throttling, bot detection and MFA are better. The policy does not allow unlimited guessing or prevent logging.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1a88903b-323f-5795-9a3f-f79c35eea173', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'bf2bf203-69a7-5838-b29a-bc097f9c9b04', 'csit-605/threats-and-attacks/ta20', 'mcq', 'evaluate', 'hard', 'Evaluate lessons from the Colonial Pipeline intrusion', 'According to the company''s congressional testimony, which control would most directly have blocked the reported initial access in the 2021 Colonial Pipeline attack?', null, null, '[{"id":"a","text":"A larger DDoS mitigation contract"},{"id":"b","text":"Removing the dormant VPN account and requiring MFA on all remote access"},{"id":"c","text":"Encrypting the pipeline''s operational data at rest"},{"id":"d","text":"Annual security awareness lectures"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1a88903b-323f-5795-9a3f-f79c35eea173', '{"option":"b"}'::jsonb, 'The testimony described entry via a legacy VPN account protected only by a password. Account removal and MFA address exactly that weakness. DDoS protection, encryption at rest and lectures do not stop login with a valid password.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('644d4dd7-ed37-5211-b8c0-6a919dbc10c4', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', null, 'csit-605/threats-and-attacks/ta21', 'essay', 'evaluate', 'hard', 'Evaluate a layered defence against human-operated ransomware', '"Human-operated ransomware cannot be stopped by technology alone." Critically evaluate this statement with reference to the Cyber Kill Chain, at least one 2017 case study, and the situation of Ghanaian small and medium enterprises.', null, null, null, 25, array['Introduction defining human-operated ransomware and double extortion', 'Kill Chain analysis showing technical and non-technical control points', 'Case evidence from WannaCry or NotPetya', 'People and process controls, including social engineering and governance of ransom decisions', 'Ghanaian SME context and proportionate recommendations', 'Reasoned conclusion']::text[], '[{"criterion":"Conceptual understanding","marks":5,"descriptor":"Accurately explains human-operated ransomware, RaaS and double extortion"},{"criterion":"Use of frameworks","marks":6,"descriptor":"Applies the Cyber Kill Chain or ATT&CK tactics to identify control points at several stages"},{"criterion":"Case evidence","marks":5,"descriptor":"Uses accurate public facts from WannaCry or NotPetya to support arguments"},{"criterion":"Contextual application","marks":5,"descriptor":"Applies the argument realistically to Ghanaian SMEs, including resource constraints and regulation"},{"criterion":"Critical evaluation and conclusion","marks":4,"descriptor":"Weighs technical against human and governance factors and reaches a justified conclusion"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('644d4dd7-ed37-5211-b8c0-6a919dbc10c4', '{}'::jsonb, 'Examiners reward balanced evaluation that links technical controls to human and governance factors, accurate case facts and realistic recommendations for the Ghanaian context.', 'A strong answer accepts the statement with qualification. Human-operated ransomware involves attackers who adapt in real time, use stolen credentials and legitimate administrative tools, and choose when to deploy encryption. Technology such as patching, endpoint detection, MFA and segmentation is essential, but each control can be bypassed if people and processes fail.
Using the Kill Chain, delivery is often social (phishing, vishing) and exploitation may consist of a user entering credentials, so awareness and process controls matter. Installation and command and control can be detected technically, but only if someone monitors alerts and has authority to act. Actions on objectives are limited by segmentation and offline backups, which are technical but require disciplined operation and restore testing.
WannaCry shows that a technical fix (MS17-010) existed but organisational patch management failed; the problem was governance and prioritisation as much as technology. NotPetya shows that trusted supplier channels and credential theft can defeat patched systems, requiring supplier risk management and privileged access discipline.
For Ghanaian SMEs, limited budgets mean low-cost controls with high impact: licensed and updated software, MFA on email and remote access, no daily admin accounts, offline backups and a simple incident plan with contacts for the Cyber Security Authority. Decisions about ransom payment are governance matters requiring legal advice and should be prepared in advance.
The conclusion should be that technology is necessary but insufficient; resilience depends on combining technical controls with people, process and governance.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('26ffd546-dc84-5a7c-a2ee-7feefc4d0a35', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'b34476ae-8459-57d7-bbae-6c1be6f713f2', 'What is the key difference between a virus and a worm?', 'A virus needs a host file and usually user action to spread; a worm propagates by itself across networks by exploiting vulnerabilities.', 'supplementary', 'csit-605/threats-and-attacks/d44e4c1fb90f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
