insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('51eb43f7-594c-5fc2-9137-11d712cd4951', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'b34476ae-8459-57d7-bbae-6c1be6f713f2', 'What made NotPetya a supply chain attack?', 'Its initial spread came through a compromised update of M.E.Doc, a trusted Ukrainian accounting software package.', 'supplementary', 'csit-605/threats-and-attacks/d77563f63b8b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
