insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1bee1db3-83d8-56c7-9d4d-90e15c0f58d1', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', '977b552f-439d-519e-9709-89af082c71ab', 'How does the mobile money "wrong transfer" scam work?', 'A fake SMS credit alert is followed by a call asking the victim to return money "sent by mistake"; the victim sends real money although no funds were received. Always check the balance through the official menu or app.', 'supplementary', 'csit-605/threats-and-attacks/ae5aa29f605c', true)
