insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bf816d76-c308-5030-ab22-b2858ef810cc', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', '977b552f-439d-519e-9709-89af082c71ab', 'Distinguish malicious, negligent and compromised insiders.', 'Malicious insiders intend harm; negligent insiders cause harm through carelessness; compromised insiders are legitimate users whose accounts or devices have been taken over by outsiders.', 'supplementary', 'csit-605/threats-and-attacks/62a626bfabb9', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a1937af4-4834-5cd8-bf0a-cdd3e03001f0', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', '977b552f-439d-519e-9709-89af082c71ab', 'Why does phishing-resistant MFA defeat adversary-in-the-middle phishing?', 'Methods such as FIDO2 keys and passkeys are cryptographically bound to the genuine website''s domain, so a fake site cannot obtain a usable authentication response to relay.', 'supplementary', 'csit-605/threats-and-attacks/a20d6a40e89c', true)
