insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('566a4521-f104-5cfe-aac0-086243f32d3e', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'bf2bf203-69a7-5838-b29a-bc097f9c9b04', 'Password spraying versus credential stuffing - what is the difference?', 'Spraying tries a few common passwords against many accounts; stuffing tests many username-password pairs leaked from other services, exploiting reuse.', 'supplementary', 'csit-605/threats-and-attacks/4383ca8827fe', true)
