insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c514f725-8fc0-5026-bea8-229c31e5d555', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'bf2bf203-69a7-5838-b29a-bc097f9c9b04', 'Why does length matter more than complexity for random passwords?', 'Search space is N^L, so adding characters multiplies the space exponentially, whereas enlarging the alphabet raises it more slowly; but this holds only for random passwords.', 'supplementary', 'csit-605/threats-and-attacks/b47137d13209', true)
