  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c7f54049-e565-5cc9-b9b1-7e1e7c696043', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '90762921-08a6-5e20-875e-13608b1b4891', 'bf2bf203-69a7-5838-b29a-bc097f9c9b04', 'What did the 2016 Mirai attack on Dyn demonstrate?', 'Default IoT credentials can build huge botnets, and attacking a shared dependency such as a DNS provider can disrupt many websites at once.', 'supplementary', 'csit-605/threats-and-attacks/6cb62085fe00', true)
