insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'network-and-system-security', 'Network and System Security', 'Defending networks, operating systems and endpoints.', 3, true)
