insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ce5251f9-fe0e-57f2-b00b-cb796ce56fbc', '{"answers":["DMZ","demilitarised zone","demilitarized zone"]}'::jsonb, 'A DMZ contains public services such as web servers, so a compromise there does not give direct access to internal systems.', null)
