insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ea8821da-1084-5819-9a9b-a93d0d2326c4', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'd69c1d48-1278-59c8-b957-3c702a744b3c', 'csit-605/network-and-system-security/ns05', 'matching', 'understand', 'medium', 'Match firewall types to their capabilities', 'Match each firewall type to its best description.', null, null, '{"left":[{"id":"l1","text":"Stateless packet filter"},{"id":"l2","text":"Web application firewall"},{"id":"l3","text":"Next-generation firewall"},{"id":"l4","text":"Host-based firewall"}],"right":[{"id":"r4","text":"Runs on an individual endpoint and protects it wherever it is connected"},{"id":"r2","text":"Filters HTTP requests to a specific web application for attack patterns"},{"id":"r1","text":"Decides on header fields only, packet by packet"},{"id":"r3","text":"Combines stateful inspection with application and user awareness and intrusion prevention"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
