insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ea8821da-1084-5819-9a9b-a93d0d2326c4', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each type operates at a different layer or location; real designs combine them in defence in depth.', null)
