insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('667b8295-24bd-52fe-a921-6a318ada8412', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'd69c1d48-1278-59c8-b957-3c702a744b3c', 'csit-605/network-and-system-security/ns06', 'mcq', 'analyse', 'hard', 'Analyse the Target breach from a segmentation perspective', 'Which network design change would most directly have broken the path used in the 2013 Target breach?', null, null, '[{"id":"a","text":"Faster internet connectivity at stores"},{"id":"b","text":"Strong segmentation preventing vendor-access systems from reaching the point-of-sale environment"},{"id":"c","text":"Replacing POS terminals with newer models"},{"id":"d","text":"Blocking all inbound HTTPS traffic to the corporate website"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('667b8295-24bd-52fe-a921-6a318ada8412', '{"option":"b"}'::jsonb, 'Attackers used an HVAC contractor''s credentials and moved from vendor-facing systems towards POS terminals. Segmenting vendor access from the cardholder data environment breaks that path. The other options do not address lateral movement.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4bb9f8e9-79c3-5f6b-9ab2-26b1508bc80a', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'd69c1d48-1278-59c8-b957-3c702a744b3c', 'csit-605/network-and-system-security/ns07', 'mcq', 'evaluate', 'hard', 'Evaluate zero trust relative to perimeter security', 'Which statement best evaluates zero trust architecture as described in NIST SP 800-207?', null, null, '[{"id":"a","text":"It removes the need for any network controls"},{"id":"b","text":"It grants no implicit trust based on network location and verifies each access request using identity, device and context, complementing network controls"},{"id":"c","text":"It trusts all devices on the corporate VPN"},{"id":"d","text":"It is only applicable to military networks"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4bb9f8e9-79c3-5f6b-9ab2-26b1508bc80a', '{"option":"b"}'::jsonb, 'Zero trust shifts the main control point to per-request identity and policy decisions while keeping network controls as a layer. Trusting VPN devices is the opposite of zero trust, and the model applies broadly.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1d72c607-da79-5146-9554-8b29117817a3', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'csit-605/network-and-system-security/ns08', 'mcq', 'understand', 'medium', 'Explain the role of CertificateVerify in TLS 1.3', 'In the TLS 1.3 handshake, what does the server''s CertificateVerify message achieve?', null, null, '[{"id":"a","text":"It encrypts the session key with the server''s public key"},{"id":"b","text":"It proves the server holds the private key matching its certificate by signing the handshake transcript"},{"id":"c","text":"It lists the cipher suites the server supports"},{"id":"d","text":"It ends the TLS session"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1d72c607-da79-5146-9554-8b29117817a3', '{"option":"b"}'::jsonb, 'CertificateVerify is a signature over the handshake so far, binding the ephemeral key exchange to the certified identity. TLS 1.3 does not use RSA key transport, cipher suites are chosen in ServerHello and Finished messages authenticate the transcript rather than ending the session.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2a917b20-028b-59fc-bce0-f26e99289e65', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'csit-605/network-and-system-security/ns09', 'true_false', 'understand', 'medium', 'Explain what DNSSEC protects', 'DNSSEC encrypts DNS queries so that eavesdroppers cannot see which websites a user looks up.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
