insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('91e4ce92-b2fe-55fe-9e1b-6df86cab46bf', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'csit-605/network-and-system-security/ns11', 'matching', 'apply', 'medium', 'Select appropriate secure protocols for business needs', 'Match each business need to the most appropriate protocol.', null, null, '{"left":[{"id":"l1","text":"Administering a Linux server remotely"},{"id":"l2","text":"Linking a branch office network to head office over the internet"},{"id":"l3","text":"Protecting customer logins to a web portal"},{"id":"l4","text":"Allowing resolvers to verify DNS answers have not been forged"}],"right":[{"id":"r4","text":"DNSSEC"},{"id":"r3","text":"HTTPS using TLS 1.2 or 1.3"},{"id":"r1","text":"SSH with key-based authentication"},{"id":"r2","text":"IPsec site-to-site VPN"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
