insert into public.question_keys (question_id, correct, explanation, model_answer) values ('91e4ce92-b2fe-55fe-9e1b-6df86cab46bf', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each protocol fits a layer and purpose; choosing the wrong one, such as relying on a VPN for public website security, leaves gaps.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('546aacf6-6ac0-56d4-9f7d-34d2f40a08d2', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'csit-605/network-and-system-security/ns12', 'scenario', 'apply', 'medium', 'Apply protocol configuration recommendations', 'Which recommendation is most appropriate?', 'Illustrative scenario. A fictional Kumasi e-commerce company''s web server accepts SSL 3.0, TLS 1.0, TLS 1.1, TLS 1.2 and TLS 1.3. Its routers are managed using Telnet from the office network.', null, '[{"id":"a","text":"Keep all TLS versions for compatibility and continue using Telnet inside the office"},{"id":"b","text":"Allow only TLS 1.2 and 1.3 with modern cipher suites and replace Telnet with SSH using key-based authentication"},{"id":"c","text":"Disable TLS 1.3 because it is too new"},{"id":"d","text":"Replace HTTPS with a VPN for all customers"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('546aacf6-6ac0-56d4-9f7d-34d2f40a08d2', '{"option":"b"}'::jsonb, 'SSL 3.0 and TLS 1.0/1.1 are deprecated and Telnet sends credentials in clear text. TLS 1.3 is the current standard, and customers cannot reasonably be required to use a VPN to shop.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5fd03a15-e5fd-573e-b0e6-4078d2bcc589', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'csit-605/network-and-system-security/ns13', 'mcq', 'analyse', 'hard', 'Analyse the lessons of Heartbleed', 'Which conclusion is best supported by the 2014 Heartbleed vulnerability?', null, null, '[{"id":"a","text":"The TLS protocol design was fundamentally broken"},{"id":"b","text":"A coding error in a widely used implementation can undermine a sound protocol, and recovery required key replacement and certificate revocation as well as patching"},{"id":"c","text":"Only websites using TLS 1.3 were affected"},{"id":"d","text":"Heartbleed was a denial-of-service attack against DNS"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5fd03a15-e5fd-573e-b0e6-4078d2bcc589', '{"option":"b"}'::jsonb, 'Heartbleed was a missing bounds check in OpenSSL''s heartbeat code that leaked memory, possibly including private keys. TLS 1.3 did not exist yet, and it was not a DNS attack.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2623eeda-5c57-5a39-8305-000002d06a04', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'csit-605/network-and-system-security/ns14', 'mcq', 'evaluate', 'hard', 'Evaluate VPN security for remote access', 'A company argues that its TLS VPN makes remote access fully secure. Which response is most defensible?', null, null, '[{"id":"a","text":"Agree, because VPN traffic is encrypted"},{"id":"b","text":"Disagree; the VPN protects traffic in transit, but weak credentials without MFA and unpatched gateways create direct attack paths, so MFA, patching and least-privilege access are also needed"},{"id":"c","text":"Agree, as long as the VPN uses TLS 1.0"},{"id":"d","text":"Disagree, because VPNs never encrypt traffic"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2623eeda-5c57-5a39-8305-000002d06a04', '{"option":"b"}'::jsonb, 'Encryption in transit does not prevent an attacker with valid credentials logging in, as the Colonial Pipeline case showed. TLS 1.0 is deprecated, and VPNs do encrypt traffic.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('00e6aec6-20cc-5ecd-a3d4-c7f894ddb527', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', '11edcec6-e6ea-5e20-a4a2-6169e030075a', 'csit-605/network-and-system-security/ns15', 'matching', 'understand', 'medium', 'Compare access control models', 'Match each access control model to its description.', null, null, '{"left":[{"id":"l1","text":"Discretionary access control"},{"id":"l2","text":"Mandatory access control"},{"id":"l3","text":"Role-based access control"},{"id":"l4","text":"Attribute-based access control"}],"right":[{"id":"r2","text":"A central policy based on security labels that users cannot override"},{"id":"r3","text":"Permissions assigned to job roles and users assigned to roles"},{"id":"r1","text":"Resource owners decide who may access their resources"},{"id":"r4","text":"Decisions evaluate attributes of user, resource, action and environment"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
