insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bb61ad16-bd2c-503b-9e89-4ca6d3751f28', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', '11edcec6-e6ea-5e20-a4a2-6169e030075a', 'csit-605/network-and-system-security/ns16', 'scenario', 'apply', 'medium', 'Apply segregation of duties to role design', 'Why does this role design violate good access control practice?', 'Illustrative scenario. In a fictional savings and loans company, the proposed Teller role can post deposits and withdrawals and also reverse transactions without approval.', null, '[{"id":"a","text":"Tellers should not be able to view customer records"},{"id":"b","text":"One person could post and then reverse transactions to conceal theft, violating segregation of duties"},{"id":"c","text":"Reversals should be done only by the system administrator"},{"id":"d","text":"Tellers should have local administrator rights instead"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
