insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bb61ad16-bd2c-503b-9e89-4ca6d3751f28', '{"option":"b"}'::jsonb, 'Combining the ability to initiate and to reverse transactions lets a single person conceal fraud. Reversals should need a manager, preferably with a recorded reason. Administrators should not hold business permissions.', null)
