insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('545610b8-9b93-5362-8439-cba15ca9b974', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', '11edcec6-e6ea-5e20-a4a2-6169e030075a', 'csit-605/network-and-system-security/ns18', 'true_false', 'understand', 'medium', 'Explain the limits of full-disk encryption', 'Full-disk encryption prevents malware running on an unlocked laptop from reading the user''s files.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
