insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('fcad0099-a14e-50e5-a281-86bf37c6b3ce', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', '11edcec6-e6ea-5e20-a4a2-6169e030075a', 'csit-605/network-and-system-security/ns19', 'mcq', 'recall', 'easy', 'Recall the purpose of the Biba model', 'Which security property is the Biba model primarily designed to protect?', null, null, '[{"id":"a","text":"Confidentiality"},{"id":"b","text":"Integrity"},{"id":"c","text":"Availability"},{"id":"d","text":"Non-repudiation"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
