insert into public.question_keys (question_id, correct, explanation, model_answer) values ('fcad0099-a14e-50e5-a281-86bf37c6b3ce', '{"option":"b"}'::jsonb, 'Biba enforces "no read down, no write up" to protect integrity. Bell-LaPadula enforces "no read up, no write down" for confidentiality.', null)
