insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e658c4ca-04e2-5793-8b74-f088d64d0643', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', '11edcec6-e6ea-5e20-a4a2-6169e030075a', 'csit-605/network-and-system-security/ns20', 'mcq', 'evaluate', 'hard', 'Evaluate privileged access controls after an insider case', 'Following the 2013 Snowden disclosures, which control would best reduce the risk of a single systems administrator gathering large volumes of sensitive data unnoticed?', null, null, '[{"id":"a","text":"Giving all administrators identical, broad access for efficiency"},{"id":"b","text":"Partitioned privileged access with two-person control for sensitive operations and monitoring of privileged activity"},{"id":"c","text":"Relying on annual background checks alone"},{"id":"d","text":"Allowing administrators to disable logging during maintenance"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e658c4ca-04e2-5793-8b74-f088d64d0643', '{"option":"b"}'::jsonb, 'Partitioning, two-person control and monitoring limit and expose misuse of privilege; NSA publicly announced a two-person rule for administrators afterwards. Background checks alone do not detect behaviour, and disabling logs removes accountability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('73932dc7-b340-5f2e-afaa-336693745ea4', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', '11edcec6-e6ea-5e20-a4a2-6169e030075a', 'csit-605/network-and-system-security/ns21', 'mcq', 'understand', 'medium', 'Explain why removing local administrator rights is effective', 'Why is removing local administrator rights from everyday user accounts considered a highly cost-effective endpoint control?', null, null, '[{"id":"a","text":"It makes computers run faster"},{"id":"b","text":"Much malware needs administrative privileges to install persistently, disable defences or spread, so standard accounts limit its impact"},{"id":"c","text":"It removes the need for patching"},{"id":"d","text":"It encrypts the hard disk automatically"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('73932dc7-b340-5f2e-afaa-336693745ea4', '{"option":"b"}'::jsonb, 'Running as a standard user applies least privilege at the operating system level. It does not replace patching or encryption, and its benefit is security, not speed.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('12ea89fc-d73b-5ae6-b104-d35ec05118d6', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', null, 'csit-605/network-and-system-security/ns22', 'case_analysis', 'evaluate', 'hard', 'Evaluate the network and system security of a Ghanaian organisation', 'Evaluate the main network and system security weaknesses at Ridge Medical Diagnostics and recommend a prioritised improvement plan, justifying each recommendation with reference to concepts and cases from this module.', null, 'Illustrative scenario. Ridge Medical Diagnostics is a fictional laboratory chain with a head office in Accra and four collection centres. All sites connect to head office over the public internet without tunnels. Every PC is on one flat network with the laboratory information system and its database. The edge firewall''s first rule allows all traffic from the internet to TCP 3389 (remote desktop) so the IT contractor can work remotely. Staff log in to PCs using a shared account with local administrator rights. The patient results portal accepts TLS 1.0 and above. Logs are kept only on each PC and are never reviewed.', null, 25, array['Identification of the critical assets and CIA priorities', 'Analysis of network weaknesses (perimeter rule, flat network, untunnelled sites)', 'Analysis of protocol weaknesses (TLS versions, remote access)', 'Analysis of endpoint and access control weaknesses (shared admin account, logging)', 'Prioritised plan with justification and links to cases']::text[], '[{"criterion":"Identification of weaknesses","marks":6,"descriptor":"Identifies at least five distinct weaknesses across network, protocol, endpoint and access control areas"},{"criterion":"Technical accuracy","marks":6,"descriptor":"Correctly explains why each weakness creates risk using module concepts such as first-match rules, segmentation, forward secrecy, least privilege and accountability"},{"criterion":"Recommendations","marks":6,"descriptor":"Proposes specific, feasible controls such as VPN with MFA, segmentation, TLS 1.2/1.3 only, individual standard accounts and central logging"},{"criterion":"Prioritisation and justification","marks":4,"descriptor":"Orders actions by risk reduction and cost and justifies the order"},{"criterion":"Use of cases and context","marks":3,"descriptor":"Links appropriately to cases such as Target, Colonial Pipeline or WannaCry and to Ghanaian data protection obligations"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('12ea89fc-d73b-5ae6-b104-d35ec05118d6', '{}'::jsonb, 'Examiners look for accurate diagnosis across layers, specific controls, sensible prioritisation and well-chosen links to cases and Ghanaian obligations.', 'The critical assets are patient results and personal data (confidentiality, under the Data Protection Act, 2012), result accuracy (integrity, since wrong results harm patients) and laboratory system availability.
The most urgent weakness is internet-exposed remote desktop. Password attacks against exposed RDP are a common ransomware entry route, and credential-based remote access caused the Colonial Pipeline incident. Remove the rule, provide access through a VPN with MFA, and restrict the contractor to named systems with time-limited, logged accounts.
Second, the shared local administrator account destroys accountability and lets malware run with full privileges. Introduce individual standard accounts, unique local administrator passwords held by IT and MFA for privileged actions.
Third, the flat network means one compromised collection-centre PC can reach the database, like the lateral movement seen in the Target breach and the spread of WannaCry. Segment users, the laboratory system, the database and management interfaces, and allow only required flows with a logged default deny.
Fourth, untunnelled site links expose results in transit. Deploy IPsec site-to-site VPNs.
Fifth, the portal should accept only TLS 1.2 and 1.3 with modern cipher suites providing forward secrecy.
Sixth, centralise logs and review alerts, so attacks are detected during the window before impact.
Priority follows risk and cost: close RDP and enforce MFA immediately, then fix accounts and TLS, then segmentation and VPN links, then central logging. Residual risks should be documented and accepted by management.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3410590e-2514-5d62-9a56-37b2c93a0107', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'd69c1d48-1278-59c8-b957-3c702a744b3c', 'What does "first match wins" mean for firewall rule sets?', 'Rules are evaluated top-down and the first matching rule decides the action, so a broad rule placed early can shadow later, more specific rules.', 'supplementary', 'csit-605/network-and-system-security/cf10a5d7100b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('cd1b4843-0de0-5a53-a63c-da1991486760', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'd69c1d48-1278-59c8-b957-3c702a744b3c', 'Why should every firewall rule set end with a logged default deny?', 'It applies fail-safe defaults, blocking anything not explicitly permitted, and the logs reveal attempted traffic for investigation.', 'supplementary', 'csit-605/network-and-system-security/2694bbc42102', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('57f8a502-8774-5b95-a0b5-2b8f61eb2159', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'd69c1d48-1278-59c8-b957-3c702a744b3c', 'What is the purpose of a DMZ?', 'To host internet-facing services in a separate segment so that compromising them does not give direct access to the internal network.', 'supplementary', 'csit-605/network-and-system-security/d51bfda50367', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bd2d1f12-d634-582b-9a45-998a8643ee64', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'd69c1d48-1278-59c8-b957-3c702a744b3c', 'How does segmentation limit the damage of a phishing compromise?', 'A compromised PC in the user segment cannot directly reach servers, payment systems or management interfaces, so lateral movement is blocked or slowed and more detectable.', 'supplementary', 'csit-605/network-and-system-security/6491daa9e406', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('20278703-1a30-599e-b27d-1057c9f120fd', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'd69c1d48-1278-59c8-b957-3c702a744b3c', 'What network lesson does the 2013 Target breach teach?', 'Third-party (HVAC vendor) access must be tightly scoped and segmented from sensitive systems such as point-of-sale, and security alerts must be acted upon.', 'supplementary', 'csit-605/network-and-system-security/4492c8131808', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c9ffec2c-ea5d-58f6-aecf-d51c1ddeaaa8', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'd69c1d48-1278-59c8-b957-3c702a744b3c', 'What is the core idea of zero trust architecture?', 'No implicit trust based on network location; every access request is authenticated and authorised using identity, device health and context, with least privilege per session.', 'supplementary', 'csit-605/network-and-system-security/127719fcdb1a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6cc9e415-9e94-533b-b21b-af4c7b102879', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'What four properties should a secure channel provide?', 'Confidentiality, integrity, authentication (at least of the server) and forward secrecy.', 'supplementary', 'csit-605/network-and-system-security/67155054a648', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('830a147b-2b84-5ae3-a67d-1f701c9df319', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'In TLS 1.3, how are session keys established?', 'Through an ephemeral (EC)DHE key exchange - client and server exchange key shares in ClientHello and ServerHello and derive keys with HKDF; the certificate key only signs the handshake.', 'supplementary', 'csit-605/network-and-system-security/62ab396bd496', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('dd299ac2-6f84-5f50-b36e-6a8e06c3b902', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'What does the client check before trusting a TLS server?', 'That the certificate chain leads to a trusted root, the certificate is valid and matches the server name, the CertificateVerify signature is valid and the Finished message verifies.', 'supplementary', 'csit-605/network-and-system-security/0e70122d9824', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a70b84b1-da35-5cee-a010-93fc61d3f8ac', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'What does DNSSEC protect and what does it not protect?', 'It protects the authenticity and integrity of DNS answers through signatures; it does not provide confidentiality or stop lookalike domains.', 'supplementary', 'csit-605/network-and-system-security/ee599f695bfc', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('53289cd0-fb2e-57e5-a226-b956fe36674c', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'Why is password-based SSH exposed to the internet a risk?', 'It invites credential attacks; key-based authentication, disabling password login and restricting source networks are safer.', 'supplementary', 'csit-605/network-and-system-security/d6228539d6d5', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('961c1b3a-e16f-5d87-8f3f-e0813d5a5df4', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', 'e1747710-6b9b-5246-8fd3-f6e152dbb862', 'Why did Heartbleed require more than a software patch?', 'Leaked memory might have exposed private keys, sessions and passwords, so organisations had to replace keys, reissue and revoke certificates and reset sessions or passwords.', 'supplementary', 'csit-605/network-and-system-security/bdf01fbe1091', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('828a1072-0d60-53b7-8fd8-80f48a8a3e30', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', '11edcec6-e6ea-5e20-a4a2-6169e030075a', 'Name four operating system hardening practices.', 'Prompt patching, secure configuration baselines (such as CIS Benchmarks), removal of unnecessary services and default accounts, and enabling host firewalls, encryption and logging.', 'supplementary', 'csit-605/network-and-system-security/d4fbe14168d8', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
