  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3365f781-a0e8-542b-af58-022fe0810670', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', '11edcec6-e6ea-5e20-a4a2-6169e030075a', 'List four components of privileged access management.', 'Separate admin accounts, credential vaulting, MFA with just-in-time elevation, and session recording or two-person control for sensitive operations.', 'supplementary', 'csit-605/network-and-system-security/d4c7c5735232', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('eb36db33-846f-51e7-8986-4c766dac0e30', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'f842462c-a3fd-5c0b-86d2-f59e47ebbfab', '11edcec6-e6ea-5e20-a4a2-6169e030075a', 'Why are shared accounts a problem even in small businesses?', 'They remove accountability, so fraud or mistakes cannot be traced to individuals, and they usually carry more privilege than any one person needs.', 'supplementary', 'csit-605/network-and-system-security/496939c29958', true)
