insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0c1ceadd-d677-5e49-864a-773e016740fa', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', '25dcc639-e065-549b-92fd-cf86748dc7c0', 'csit-605/cryptography/cr18', 'scenario', 'apply', 'medium', 'Apply key management principles to a leaked key', 'What is the most appropriate response?', 'Illustrative scenario. During a review, a fictional Accra fintech finds that its mobile money API signing key has been committed to a shared source code repository for six months, accessible to all developers and two former contractors.', null, '[{"id":"a","text":"Delete the file in the next commit and continue using the key"},{"id":"b","text":"Treat the key as compromised - revoke and replace it, remove it from repository history, review logs for misuse, and add secret scanning and a key management service"},{"id":"c","text":"Change the repository to private and keep the key"},{"id":"d","text":"Ask the former contractors to confirm they did not copy it"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0c1ceadd-d677-5e49-864a-773e016740fa', '{"option":"b"}'::jsonb, 'Once exposed, a key must be presumed compromised; deleting it from the latest commit leaves it in history and anyone may already have copied it. Assurances from former contractors are not a control.', null)
