insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('271be6d0-e08a-5d2f-bf24-74a6246f1a66', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', '25dcc639-e065-549b-92fd-cf86748dc7c0', 'csit-605/cryptography/cr20', 'mcq', 'analyse', 'hard', 'Analyse the systemic lesson of DigiNotar', 'What is the most important systemic lesson of the 2011 DigiNotar compromise?', null, null, '[{"id":"a","text":"Wildcard certificates should never be issued"},{"id":"b","text":"Because any trusted CA can issue certificates for any domain, the whole web''s security depends on the weakest trusted CA, motivating Certificate Transparency and stricter CA oversight"},{"id":"c","text":"Users in Iran should not use Google services"},{"id":"d","text":"Certificates should be valid for longer to reduce issuance"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('271be6d0-e08a-5d2f-bf24-74a6246f1a66', '{"option":"b"}'::jsonb, 'The fraudulent google.com certificate was trusted because DigiNotar was trusted. Wildcards were incidental, the geographical point misses the lesson, and longer validity would make compromise worse.', null)
