insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c086fe6b-2703-5fb7-8cd3-c8934d300486', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', '25dcc639-e065-549b-92fd-cf86748dc7c0', 'csit-605/cryptography/cr21', 'mcq', 'evaluate', 'hard', 'Evaluate certificate lifecycle controls', 'A bank suffered an outage when an API certificate expired. Which control combination best prevents recurrence?', null, null, '[{"id":"a","text":"Buy certificates with the longest possible validity period"},{"id":"b","text":"A central certificate inventory with named owners, automated renewal and expiry alerting"},{"id":"c","text":"Disable certificate validation in the mobile app"},{"id":"d","text":"Switch the API to plain HTTP"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c086fe6b-2703-5fb7-8cd3-c8934d300486', '{"option":"b"}'::jsonb, 'Inventory, ownership, automation and alerting address the root cause. Longer validity only postpones the problem and conflicts with industry trends, and disabling validation or TLS destroys security.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1e4ae154-8213-50c5-b702-795b9d57898f', 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', null, 'csit-605/cryptography/cr22', 'case_analysis', 'evaluate', 'hard', 'Evaluate the cryptographic design of a Ghanaian digital service', 'Critically evaluate AgroLink''s cryptographic design and recommend a corrected design, justifying each change with reference to cryptographic principles and relevant case studies.', null, 'Illustrative scenario. AgroLink Ghana is a fictional platform connecting farmers with buyers and paying farmers through mobile money. Its current design: the Android app talks to the server over HTTPS, but developers disabled certificate validation in the app to fix a test error. User passwords are stored as unsalted MD5 hashes. Buyers'' payment instructions are protected with an HMAC using one key shared by all buyers and the platform. The database is encrypted with AES in ECB mode, using a key stored in the application''s configuration file. The website''s TLS certificate is renewed manually by one engineer, who is leaving the company next month.', null, 25, array['Overview of assets and security goals (confidentiality, integrity, authenticity, non-repudiation, availability)', 'Evaluation of each weakness and its consequences', 'Corrected design for transport, passwords, payment instructions, data at rest and certificates', 'Key management and governance recommendations', 'Conclusion with priorities']::text[], '[{"criterion":"Identification and explanation of weaknesses","marks":7,"descriptor":"Correctly explains the risks of disabled validation, unsalted MD5, a shared HMAC key, ECB mode, co-located keys and manual single-person renewal"},{"criterion":"Corrected design","marks":7,"descriptor":"Proposes appropriate replacements such as enforced validation, Argon2id or bcrypt with salts, per-buyer digital signatures, AES-GCM with envelope encryption in a KMS or HSM, and automated renewal"},{"criterion":"Use of principles","marks":5,"descriptor":"Applies principles such as Kerckhoffs, non-repudiation, forward secrecy, key separation and the certificate chain of trust"},{"criterion":"Use of cases and context","marks":3,"descriptor":"Uses relevant cases such as LinkedIn 2012, Flame or DigiNotar and Ghanaian legal context such as the Data Protection Act, 2012"},{"criterion":"Prioritisation and clarity","marks":3,"descriptor":"Orders recommendations by risk and presents them clearly"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1e4ae154-8213-50c5-b702-795b9d57898f', '{}'::jsonb, 'Examiners look for accurate diagnosis of each flaw, correct replacement primitives, sound key management and well-chosen links to cases and Ghanaian context.', 'AgroLink''s assets are farmer and buyer credentials, payment instructions (integrity, authenticity and non-repudiation) and personal data (confidentiality, a Data Protection Act, 2012 obligation). Platform availability matters because farmers depend on timely payment.
Disabled certificate validation is the most urgent flaw: any attacker on the network, for example on public Wi-Fi, can impersonate the server, so HTTPS gives no authentication. Validation must be restored, with pinning considered for the platform''s own API. Unsalted MD5 password hashes are fast and identical for identical passwords; as LinkedIn''s 2012 unsalted SHA-1 leak showed, such hashes are cracked at scale. Migrate to Argon2id or bcrypt with unique salts, wrapping existing hashes immediately.
A single HMAC key shared by all buyers means any buyer, or the platform, could forge any instruction, so there is neither per-buyer authenticity nor non-repudiation. Each buyer should sign instructions with their own private key, held on their device, with certificates from a platform-run PKI.
ECB leaks patterns, and a key in the configuration file is exposed by any server compromise. Use AES-GCM with envelope encryption: data keys wrapped by key encryption keys in a cloud KMS or HSM, separated by purpose and rotated.
Manual single-person certificate renewal threatens availability and violates separation of duties. Automate renewal, keep an inventory with owners and alerts, and monitor Certificate Transparency logs for lookalike domains, mindful that DigiNotar showed how mis-issuance can undermine trust.
Priorities are restoring validation and fixing password storage first, then payment signatures, then encryption at rest and key management, then certificate automation before the engineer leaves.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2d61025c-bb48-522a-896d-126782604b3c', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', 'e68ea9c7-5b4b-58fd-a867-90238ad3effe', 'What is Kerckhoffs''s principle and why does it matter in business?', 'A cryptosystem should stay secure even if everything except the key is public; organisations should use published, vetted algorithms such as AES rather than proprietary secret schemes.', 'supplementary', 'csit-605/cryptography/3f2d7d2dc564', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('efeacfc4-666b-5a5b-8ef4-50bf5ee346d3', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', 'e68ea9c7-5b4b-58fd-a867-90238ad3effe', 'What is the main weakness of symmetric encryption and how is it solved?', 'Key distribution - parties must share a secret key securely. Asymmetric key exchange such as (EC)DH solves this in hybrid systems.', 'supplementary', 'csit-605/cryptography/a15491ce1496', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f66109f9-7d5f-5da3-971b-17736bc196ca', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', 'e68ea9c7-5b4b-58fd-a867-90238ad3effe', 'Work through toy RSA with p = 5, q = 11, e = 3.', 'n = 55, φ(n) = 40, d = 27 (3 × 27 = 81 ≡ 1 mod 40). Encrypt 7 - 7^3 mod 55 = 13. Decrypt - 13^27 mod 55 = 7.', 'supplementary', 'csit-605/cryptography/56ff83cbefb0', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c2c465f8-8158-510b-81b0-7844e1240d67', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', 'e68ea9c7-5b4b-58fd-a867-90238ad3effe', 'In toy Diffie-Hellman with p = 23, g = 5, a = 6, b = 15, what is exchanged and what is shared?', 'Public values A = 5^6 mod 23 = 8 and B = 5^15 mod 23 = 19 are exchanged; both compute the shared secret 2 without sending it.', 'supplementary', 'csit-605/cryptography/34c0e606242a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0677ca2d-5a35-523c-b159-5e059763eec5', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', 'e68ea9c7-5b4b-58fd-a867-90238ad3effe', 'Why should ECB mode not be used to encrypt data?', 'Identical plaintext blocks produce identical ciphertext blocks, revealing patterns; authenticated modes such as AES-GCM should be used instead.', 'supplementary', 'csit-605/cryptography/d675378b314c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b4dec7ef-4a93-5549-b55f-36fd61f63d9c', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', 'e68ea9c7-5b4b-58fd-a867-90238ad3effe', 'Why does post-quantum cryptography matter today?', 'Large quantum computers would break RSA, DH and ECC, and data recorded now could be decrypted later; NIST published ML-KEM (FIPS 203) in 2024 to support migration.', 'supplementary', 'csit-605/cryptography/049579828488', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a37129a0-1495-5188-97e2-7c364d9af8ef', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', '21312b82-0a4e-5788-bd56-36cb403743c0', 'Why does collision resistance require only about 2^(n/2) work to break by brute force?', 'Because of the birthday paradox, among many random inputs a matching pair appears much sooner than a match to one specific digest.', 'supplementary', 'csit-605/cryptography/22ea180d0edf', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2d5f1764-71fa-5be7-865a-2a928f460f33', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', '21312b82-0a4e-5788-bd56-36cb403743c0', 'Hash, MAC or signature - which provides non-repudiation, and why?', 'Only a digital signature, because only the signer holds the private key; anyone can compute a hash, and both parties share a MAC key.', 'supplementary', 'csit-605/cryptography/444529be0465', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6f919400-7a6d-5840-90f8-438ba56338f7', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', '21312b82-0a4e-5788-bd56-36cb403743c0', 'Why is SHA-256 unsuitable for storing passwords?', 'It is designed to be fast, so attackers can test billions of guesses per second; password storage needs slow, salted, ideally memory-hard functions such as Argon2id or bcrypt.', 'supplementary', 'csit-605/cryptography/f202cf9b2477', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('25d5f754-4b64-5029-98a2-0bc796a957a8', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', '21312b82-0a4e-5788-bd56-36cb403743c0', 'What does a salt achieve in password storage?', 'It makes each stored hash unique, so identical passwords differ, precomputed tables fail and each hash must be cracked separately.', 'supplementary', 'csit-605/cryptography/003bb10a9d38', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ed31c747-9d69-522c-9b2c-4435e5e3d0be', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', '21312b82-0a4e-5788-bd56-36cb403743c0', 'Outline the steps to verify a digital signature.', 'Validate the signer''s certificate, recompute the document hash, and verify the signature against that hash with the signer''s public key; a match proves integrity and authenticity.', 'supplementary', 'csit-605/cryptography/52fcfbea92db', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9e94804e-5c9d-5a53-a466-4571333fd1a8', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', '21312b82-0a4e-5788-bd56-36cb403743c0', 'What did the 2012 LinkedIn leak teach about password hashing?', 'Unsalted SHA-1 hashes were cracked in bulk, and password reuse turned the leak into years of credential stuffing elsewhere.', 'supplementary', 'csit-605/cryptography/c489e778e60b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c7fb13bf-766e-58f4-a1cd-6dc3baa62da7', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', '00f5f0a3-7849-538e-9c2c-655e966f737f', '25dcc639-e065-549b-92fd-cf86748dc7c0', 'Describe the PKI chain of trust.', 'An offline root CA in the trust store signs intermediate CA certificates, which sign leaf certificates; clients verify each signature up to the trusted root.', 'supplementary', 'csit-605/cryptography/97b08b98aa71', true)
