insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9b153b94-28ea-5bfe-a33b-ed30748246d4', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'csit-605/application-and-database-security/q01', 'mcq', 'recall', 'easy', 'Identify the first-ranked category in the OWASP Top 10:2021', 'Which category is ranked A01 in the OWASP Top 10:2021?', null, null, '[{"id":"a","text":"Injection"},{"id":"b","text":"Broken Access Control"},{"id":"c","text":"Cryptographic Failures"},{"id":"d","text":"Security Misconfiguration"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
