insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9b153b94-28ea-5bfe-a33b-ed30748246d4', '{"option":"b"}'::jsonb, 'Broken Access Control moved to first place in the 2021 edition, reflecting how often applications fail to check whether a user may act on a specific object. Injection fell to A03 (and now includes XSS), Cryptographic Failures is A02 and Security Misconfiguration is A05.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('aba145e3-562a-57ed-b775-270e4e0ee38a', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'csit-605/application-and-database-security/q02', 'true_false', 'understand', 'easy', 'Recognise the primary defence against SQL injection', 'Rigorous input validation is a sufficient replacement for parameterised queries as a defence against SQL injection.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('aba145e3-562a-57ed-b775-270e4e0ee38a', '{"value":false}'::jsonb, 'Validation reduces attack surface but cannot safely handle every legitimate value (for example names containing apostrophes) and is easy to get wrong. Parameterised queries fix the root cause by keeping SQL structure and data separate, so validation is a supporting layer only.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('774c5cfd-aead-5ad1-90b8-b9d4810266f9', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'csit-605/application-and-database-security/q03', 'scenario', 'analyse', 'medium', 'Classify an XSS vulnerability by its data flow', 'Which type of cross-site scripting is this?', 'A single-page web application reads the value after the # in the URL and writes it into a welcome banner using element.innerHTML. The server never receives the fragment. An authorised tester shows that a crafted link causes script to run in the victim''s browser.', null, '[{"id":"a","text":"Stored XSS"},{"id":"b","text":"Reflected XSS"},{"id":"c","text":"DOM-based XSS"},{"id":"d","text":"SQL injection"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('774c5cfd-aead-5ad1-90b8-b9d4810266f9', '{"option":"c"}'::jsonb, 'The vulnerable code runs entirely in client-side JavaScript, reading attacker-influenced data (the URL fragment) and writing it to a dangerous sink (innerHTML), so it is DOM-based. It is not stored because nothing is saved on the server, and not reflected because the server does not echo the payload. Server-side filters cannot see it, so the fix is to use a safe sink such as textContent.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b138ac3c-5fd0-5bdd-a9dc-2bc102d4b96d', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'csit-605/application-and-database-security/q04', 'short_answer', 'recall', 'easy', 'Name the HTTP header that restricts permitted script sources', 'Name the HTTP response header that tells the browser which sources of script and other content are permitted on a page.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b138ac3c-5fd0-5bdd-a9dc-2bc102d4b96d', '{"answers":["Content Security Policy","Content-Security-Policy","CSP"]}'::jsonb, 'Content Security Policy (CSP) limits where scripts may load from and can block inline script, reducing the impact of any XSS that slips through. It complements, but does not replace, output encoding.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8d7683ba-51bb-5988-ae22-ee235eb51322', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'csit-605/application-and-database-security/q05', 'matching', 'understand', 'medium', 'Match web vulnerabilities to their primary defences', 'Match each vulnerability or risk to its primary defence.', null, null, '{"left":[{"id":"l1","text":"SQL injection"},{"id":"l2","text":"Stored or reflected XSS"},{"id":"l3","text":"DOM-based XSS via innerHTML"},{"id":"l4","text":"Injected script that bypasses encoding"}],"right":[{"id":"r2","text":"Context-aware output encoding"},{"id":"r4","text":"A strict Content Security Policy"},{"id":"r3","text":"Use safe sinks such as textContent"},{"id":"r1","text":"Parameterised queries"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8d7683ba-51bb-5988-ae22-ee235eb51322', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each defence addresses the interpreter boundary involved. Parameterised queries keep SQL data separate from code; encoding makes data inert in HTML; safe DOM sinks avoid parsing markup; CSP is a browser-enforced backstop limiting what injected script can do.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('47aceb9c-2cb4-538b-92db-8abb15c7c90c', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'csit-605/application-and-database-security/q06', 'scenario', 'evaluate', 'hard', 'Evaluate compensating controls for a legacy injection flaw', 'Which immediate action most reduces risk while the rewrite is planned?', 'Illustrative scenario. A Ghanaian insurer''s legacy claims portal contains concatenated SQL throughout. A full rewrite will take nine months. The portal connects to the database as the database owner.', null, '[{"id":"a","text":"Rely on the existing perimeter firewall because the portal is behind it"},{"id":"b","text":"Deploy a web application firewall and reduce the portal''s database account to only the permissions it needs, while prioritising fixes to the most exposed queries"},{"id":"c","text":"Add a CAPTCHA to every form"},{"id":"d","text":"Encrypt the database files with transparent data encryption"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('47aceb9c-2cb4-538b-92db-8abb15c7c90c', '{"option":"b"}'::jsonb, 'A WAF buys time against common injection patterns and least privilege limits what a successful injection can do; prioritised code fixes then address the root cause. A network firewall allows web traffic by design, CAPTCHA does not stop injection, and TDE protects files at rest but not data queried through the application.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e2201fce-b2aa-5446-9ae1-d40d93af2cc5', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'csit-605/application-and-database-security/q07', 'true_false', 'understand', 'medium', 'Explain why stored XSS is often high impact', 'Stored XSS can be more damaging than reflected XSS because the payload is delivered to every user who views the affected content, including administrators, without needing a crafted link.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e2201fce-b2aa-5446-9ae1-d40d93af2cc5', '{"value":true}'::jsonb, 'Stored XSS persists on the server and executes whenever the content is viewed, so it can reach many users and privileged staff. Reflected XSS requires each victim to be lured into following a crafted request.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('458aec87-a94e-5cfe-891a-7dd3d8812634', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'csit-605/application-and-database-security/q08', 'mcq', 'understand', 'easy', 'Distinguish authentication from authorisation', 'Which statement correctly distinguishes authentication from authorisation?', null, null, '[{"id":"a","text":"Authentication decides what a user may do; authorisation verifies who they are"},{"id":"b","text":"Authentication verifies a claimed identity; authorisation decides whether that identity may perform a specific action on a resource"},{"id":"c","text":"They are synonyms used in different countries"},{"id":"d","text":"Authorisation happens only once at login, authentication on every request"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('458aec87-a94e-5cfe-891a-7dd3d8812634', '{"option":"b"}'::jsonb, 'Authentication answers "who is this?" and authorisation answers "may they do this to this object?". Authorisation must be checked on every request; logging in once does not grant blanket permission.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('98bb1717-da0a-5b3d-9570-771b6054804a', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'csit-605/application-and-database-security/q09', 'mcq', 'apply', 'medium', 'Apply NIST SP 800-63B to password policy', 'Which policy change best aligns with NIST SP 800-63B guidance?', null, null, '[{"id":"a","text":"Require one uppercase letter, one digit and one symbol"},{"id":"b","text":"Force all users to change passwords every 60 days"},{"id":"c","text":"Screen new passwords against lists of common and breached passwords and require changes only on evidence of compromise"},{"id":"d","text":"Ask users a security question such as their mother''s maiden name"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('98bb1717-da0a-5b3d-9570-771b6054804a', '{"option":"c"}'::jsonb, 'SP 800-63B recommends screening against common or compromised passwords and changing on evidence of compromise. It advises against arbitrary composition rules and periodic forced changes, which produce predictable patterns, and against knowledge-based security questions.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7f79135d-10bc-50d3-9095-6a6dc155ca3f', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'csit-605/application-and-database-security/q10', 'scenario', 'analyse', 'medium', 'Analyse MFA phishing resistance', 'Which control would most effectively defeat this attack?', 'Staff at a logistics firm use passwords plus six-digit codes from an authenticator app. An attacker sends a phishing email linking to a proxy site that looks identical to the staff portal and relays everything the victim types to the real site in real time.', null, '[{"id":"a","text":"Increasing the code length to eight digits"},{"id":"b","text":"FIDO2/WebAuthn security keys or passkeys bound to the genuine site''s origin"},{"id":"c","text":"Requiring passwords to be changed monthly"},{"id":"d","text":"Sending codes by SMS instead"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7f79135d-10bc-50d3-9095-6a6dc155ca3f', '{"option":"b"}'::jsonb, 'A real-time relay captures any typed code, whatever its length or delivery channel. FIDO2/WebAuthn authenticators sign a challenge that includes the origin, so a signature obtained on a look-alike domain is useless to the attacker. Password expiry does not address relay attacks.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0544d893-0617-591e-aa06-ebdd8d8fdb86', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'csit-605/application-and-database-security/q11', 'true_false', 'understand', 'medium', 'Explain the relationship between OAuth 2.0 and OpenID Connect', 'OAuth 2.0 on its own provides a standard, verifiable statement of the user''s identity to the client application.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0544d893-0617-591e-aa06-ebdd8d8fdb86', '{"value":false}'::jsonb, 'OAuth 2.0 is a delegated authorisation framework; its access token tells a resource server that access was granted. OpenID Connect adds an ID token, a signed JWT with claims about the authenticated user, which the client validates.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('77a7a34a-23be-5a55-963f-808d79f55a61', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'csit-605/application-and-database-security/q12', 'short_answer', 'recall', 'medium', 'Identify the attack defeated by regenerating session identifiers at login', 'Which session attack is prevented by issuing a new session identifier when the user logs in?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('77a7a34a-23be-5a55-963f-808d79f55a61', '{"answers":["session fixation","fixation"]}'::jsonb, 'In session fixation the attacker plants a known session ID before login; if the ID is not regenerated, it becomes authenticated. Regenerating the identifier at login makes the attacker''s planted value worthless.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9daf2ffb-448d-5124-85e5-73d9aefe3073', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'csit-605/application-and-database-security/q13', 'matching', 'understand', 'medium', 'Match identity concepts to examples', 'Match each concept to the best example.', null, null, '{"left":[{"id":"l1","text":"Possession factor"},{"id":"l2","text":"Inherence factor"},{"id":"l3","text":"RBAC rule"},{"id":"l4","text":"ABAC rule"},{"id":"l5","text":"Accountability"}],"right":[{"id":"r4","text":"Loan officers can view loan files for their own branch from managed devices"},{"id":"r5","text":"An audit log attributing each refund to a named staff account"},{"id":"r1","text":"A code generated by an authenticator app on the user''s phone"},{"id":"r2","text":"A fingerprint used to unlock a passkey"},{"id":"r3","text":"Loan officers can view loan files"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9daf2ffb-448d-5124-85e5-73d9aefe3073', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Possession and inherence are factor categories; RBAC grants permissions via roles while ABAC evaluates attributes such as branch and device; accountability depends on individual accounts and logging so actions can be attributed.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e5a84cbf-3c58-5b72-a375-8590c68d2aec', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'csit-605/application-and-database-security/q14', 'scenario', 'evaluate', 'hard', 'Evaluate identity governance failures', 'Which pair of controls would most directly have prevented this intrusion?', 'A post-incident review finds that attackers logged into a company''s VPN using the password of an employee who left two years earlier. The VPN required only a password.', null, '[{"id":"a","text":"Longer password expiry and a stronger firewall"},{"id":"b","text":"Timely deprovisioning of leavers'' accounts and MFA on remote access"},{"id":"c","text":"Data loss prevention and full-disk encryption"},{"id":"d","text":"Security awareness posters and CAPTCHA"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e5a84cbf-3c58-5b72-a375-8590c68d2aec', '{"option":"b"}'::jsonb, 'The intrusion relied on an account that should not have existed and on single-factor remote access, the same pattern reported in the Colonial Pipeline case. Joiner-mover-leaver processes and MFA address both. The other options do not stop a valid but stale credential being used.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('17b0a949-ca04-5352-a8f8-e0cefa4b7588', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'csit-605/application-and-database-security/q15', 'mcq', 'understand', 'easy', 'Distinguish SAST from DAST', 'Which statement best describes static application security testing (SAST)?', null, null, '[{"id":"a","text":"It sends crafted requests to a running application and observes the responses"},{"id":"b","text":"It analyses source code or binaries without executing them to find insecure patterns"},{"id":"c","text":"It lists open-source components and their licences"},{"id":"d","text":"It is a manual test performed by an authorised human tester"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('17b0a949-ca04-5352-a8f8-e0cefa4b7588', '{"option":"b"}'::jsonb, 'SAST inspects code without running it, so it can point to the exact line but cannot see runtime configuration. Sending requests to a running app is DAST, listing components is SCA, and manual chained testing is penetration testing.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('458cd00a-d1fd-5b89-9202-1d8f0cd3dce4', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'csit-605/application-and-database-security/q16', 'true_false', 'understand', 'medium', 'Explain the limits of transparent data encryption', 'Transparent data encryption prevents attackers from stealing data through a SQL injection flaw in the application.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('458cd00a-d1fd-5b89-9202-1d8f0cd3dce4', '{"value":false}'::jsonb, 'TDE protects data files and backups at rest. Data returned through queries is decrypted automatically by the database engine, so a successful injection still exposes it. Parameterised queries and least privilege address injection.', null)
