insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7237b73d-b865-51ef-af44-496f8ff9ab01', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'csit-605/application-and-database-security/q17', 'short_answer', 'recall', 'medium', 'Name the inventory that lists software components', 'What is the name of the formal inventory of components and dependencies that make up a piece of software (abbreviation accepted)?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
