insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7237b73d-b865-51ef-af44-496f8ff9ab01', '{"answers":["software bill of materials","SBOM"]}'::jsonb, 'An SBOM lets an organisation answer quickly whether it uses a component named in a new advisory, which was a weakness highlighted by the Equifax breach.', null)
