insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f40987e4-6b65-5081-87af-089a621fcb4a', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'csit-605/application-and-database-security/q18', 'matching', 'apply', 'medium', 'Map security activities to SDLC phases', 'Match each secure SDLC phase to an appropriate security activity.', null, null, '{"left":[{"id":"l1","text":"Requirements"},{"id":"l2","text":"Design"},{"id":"l3","text":"Build"},{"id":"l4","text":"Test"},{"id":"l5","text":"Operate"}],"right":[{"id":"r5","text":"Monitoring, patching and incident response"},{"id":"r2","text":"STRIDE threat modelling"},{"id":"r3","text":"Software composition analysis and artefact signing"},{"id":"r4","text":"DAST and threat-informed test cases"},{"id":"r1","text":"Classify data and define abuse cases"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
