insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f40987e4-6b65-5081-87af-089a621fcb4a', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Shifting left places each activity where it is cheapest and most effective, while operations activities continue after release because new vulnerabilities are disclosed in components already in production.', null)
