insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('12a18c11-6931-5502-9f5d-27ef05c8e1ab', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'csit-605/application-and-database-security/q19', 'scenario', 'apply', 'medium', 'Apply row-level security to a multi-branch data store', 'Which database control would most robustly prevent this class of error recurring?', 'Illustrative scenario. A savings company with twenty branches discovers that a developer forgot a branch filter in one report query, so branch staff could see other branches'' customers.', null, '[{"id":"a","text":"A row-level security policy that filters rows by the session''s branch attribute"},{"id":"b","text":"Transparent data encryption"},{"id":"c","text":"Nightly full backups"},{"id":"d","text":"Renaming the table"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('12a18c11-6931-5502-9f5d-27ef05c8e1ab', '{"option":"a"}'::jsonb, 'RLS enforces the branch restriction inside the database for every query, so a missing WHERE clause in application code no longer exposes other rows. TDE and backups address different risks, and renaming a table is not a control.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1849c3e4-08c7-5d4b-a247-fec8db93d7bd', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'csit-605/application-and-database-security/q20', 'mcq', 'analyse', 'hard', 'Analyse the Equifax breach as a lifecycle failure', 'Which lifecycle weakness was most central to the Equifax 2017 breach?', null, null, '[{"id":"a","text":"Use of a weak encryption algorithm in the website''s TLS configuration"},{"id":"b","text":"Failure to identify and patch a known vulnerable Apache Struts component after a fix was available"},{"id":"c","text":"A malicious insider deleting audit logs"},{"id":"d","text":"A distributed denial-of-service attack"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
