insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1849c3e4-08c7-5d4b-a247-fec8db93d7bd', '{"option":"b"}'::jsonb, 'A patch for CVE-2017-5638 was published in March 2017 but the dispute portal was not updated, and attackers exploited it from May. This is an operate-phase failure of component inventory and patch management, compounded by monitoring gaps; the other options were not the reported cause.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e5e56539-6720-5341-85c3-18df884509b7', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'csit-605/application-and-database-security/q21', 'true_false', 'evaluate', 'medium', 'Evaluate the claim that penetration testing replaces secure development', 'An annual penetration test is an adequate substitute for security activities during design and coding.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e5e56539-6720-5341-85c3-18df884509b7', '{"value":false}'::jsonb, 'Penetration testing is periodic and samples the system; it cannot find everything, and defects found late are expensive to fix. It is one assurance activity within a secure SDLC that also includes threat modelling, code review, SAST, SCA and patch management.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2a190b9e-bb80-5bba-8fa8-656a7382d0df', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', null, 'csit-605/application-and-database-security/q22', 'case_analysis', 'evaluate', 'hard', 'Evaluate and prioritise application and database security controls for a Ghanaian fintech', 'Analyse the findings, map them to relevant OWASP Top 10:2021 categories, and recommend a prioritised remediation plan that also strengthens PayNkoso''s development lifecycle. Justify your priorities with reference to likelihood, impact and regulatory context in Ghana.', null, 'Illustrative scenario. PayNkoso is a fictional Accra fintech offering a merchant dashboard and an API that lets small shops accept mobile money payments. It has eight developers and releases twice a week. An authorised assessment finds: (1) two report pages building SQL by string concatenation; (2) merchant support messages rendered unencoded in the staff console; (3) staff log in with passwords only, and a single shared "admin" account exists; (4) the API returns another merchant''s transactions if the merchant ID in the URL is changed; (5) the database account used by the API has owner rights and no audit logging is enabled; (6) no dependency scanning is performed.', null, 20, array['Brief context and the assets at risk', 'Mapping of each finding to OWASP categories and root causes', 'Prioritisation using likelihood and impact', 'Technical remediation for each finding', 'Lifecycle and governance improvements (SAST, SCA, threat modelling, access reviews)', 'Regulatory considerations (Act 843, Act 1038, sector regulator) and conclusion']::text[], '[{"criterion":"Accurate mapping and root-cause analysis","marks":5,"descriptor":"Correctly links findings to Injection, Broken Access Control, Identification and Authentication Failures, Vulnerable and Outdated Components and Logging failures, explaining root causes."},{"criterion":"Justified prioritisation","marks":5,"descriptor":"Uses likelihood and impact explicitly; places the broken object-level authorisation and injection at the top with reasons."},{"criterion":"Quality of technical recommendations","marks":5,"descriptor":"Recommends parameterised queries, output encoding and CSP, server-side authorisation checks, MFA and named accounts, least-privilege database roles and auditing."},{"criterion":"Lifecycle, governance and regulatory insight","marks":5,"descriptor":"Proposes sustainable SDLC changes and correctly references Ghanaian data protection and cybersecurity obligations without overstating them."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2a190b9e-bb80-5bba-8fa8-656a7382d0df', '{}'::jsonb, 'Examiners look for correct OWASP mapping, explicit risk-based prioritisation, specific controls rather than generic advice, and accurate but measured regulatory references.', 'A strong answer starts by identifying the assets: merchant and customer transaction data, payout details and the integrity of the payment flow. Finding 4 is Broken Access Control (A01) and should be the top priority: it is trivially exploitable by any authenticated merchant and exposes other merchants'' data at scale. Findings 1 and 2 are Injection (A03), covering SQLi and stored XSS; the XSS is especially serious because it executes in staff browsers with elevated privileges. Finding 3 is an Identification and Authentication Failure (A07) and also undermines accountability. Finding 5 magnifies every other flaw by giving attackers full database rights and leaves the firm blind, aligning with A09 Logging and Monitoring Failures. Finding 6 relates to A06 Vulnerable and Outdated Components.

The plan should therefore be: immediately add server-side object-level authorisation checks on every API endpoint; replace concatenated SQL with parameterised queries; encode output and introduce a CSP in the staff console; remove the shared admin account, issue named accounts and enforce phishing-resistant MFA for staff; create a least-privilege database role and enable auditing with logs sent to a separate platform. In the medium term, add SAST and SCA to the CI pipeline, run short STRIDE sessions for new features, write threat-informed test cases for authorisation, and schedule periodic access reviews.

Regulatory context: as a data controller PayNkoso must protect personal data under the Data Protection Act, 2012 (Act 843); as a payment business it is subject to Bank of Ghana requirements; and if designated as Critical Information Infrastructure it would have obligations under the Cybersecurity Act, 2020 (Act 1038), including incident reporting to the Cyber Security Authority. The conclusion should stress that fixing individual bugs without lifecycle changes will lead to recurrence.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c86236b3-7b75-5dc7-896f-bcc927f79749', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', null, 'csit-605/application-and-database-security/q23', 'essay', 'evaluate', 'hard', 'Critically evaluate modern authentication approaches', '"Passwords should be abolished." Critically evaluate this claim with reference to NIST SP 800-63B, MFA methods and phishing-resistant authentication, considering the practical constraints faced by Ghanaian organisations serving both urban and rural customers.', null, null, null, 15, array['Define the problem with passwords (reuse, phishing, guessing)', 'Summarise NIST SP 800-63B improvements to password practice', 'Compare MFA methods and introduce passkeys and FIDO2', 'Discuss account recovery, device access, cost and inclusion', 'Reach a reasoned, nuanced conclusion']::text[], '[{"criterion":"Understanding of password weaknesses and NIST guidance","marks":5,"descriptor":"Accurately explains length, breached-password screening, no forced expiry or composition rules."},{"criterion":"Comparative evaluation of MFA and passwordless options","marks":5,"descriptor":"Compares SMS, TOTP, push and FIDO2 on phishing resistance and usability, including SIM-swap risk."},{"criterion":"Contextual judgement and conclusion","marks":5,"descriptor":"Weighs inclusion, cost and recovery risks in the Ghanaian context and reaches a justified position."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c86236b3-7b75-5dc7-896f-bcc927f79749', '{}'::jsonb, 'Examiners reward accurate reference to NIST guidance, a comparative rather than descriptive treatment of MFA, and a conclusion that balances security, usability and inclusion.', 'A good essay accepts that passwords are a weak sole factor: they are reused, guessed, sprayed and phished. NIST SP 800-63B has improved practice by recommending longer passphrases, screening against breached and common lists, rate limiting and change-on-compromise rather than arbitrary complexity and expiry, but even well-chosen passwords can be phished. MFA reduces risk, yet methods differ: SMS codes are vulnerable to SIM swap and real-time relay, TOTP codes to relay, and push approvals to fatigue unless number matching is used. FIDO2/WebAuthn keys and passkeys are phishing resistant because they bind authentication to the site''s origin.

Abolition, however, raises practical problems. Passkeys require compatible devices; many customers use basic or shared phones; recovery of a lost authenticator often falls back to weaker channels such as SMS or customer-care calls, which social engineers target. For a Ghanaian bank serving rural customers, a realistic position is tiered: passkeys or hardware keys for staff and high-value business users; SMS or app-based MFA plus transaction limits, SIM-change checks and fraud analytics for mass-market customers; and well-designed, verified recovery processes. The conclusion should argue that passwords should cease to be the sole factor wherever possible and be phased out for privileged access, but that complete abolition depends on device access and robust recovery.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0c8423e8-0484-591c-bfac-a82bf0006dc9', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'What single root cause do SQL injection and cross-site scripting share?', 'Untrusted data is mixed with code and parsed by an interpreter (the database or the browser), so attacker input changes what the interpreter executes.', 'supplementary', 'csit-605/application-and-database-security/8ef0d87bc34f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8dae4aef-90b8-566f-8b26-eb2cffcecda6', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'Why does a parameterised query defeat SQL injection?', 'The SQL structure is parsed first with placeholders, and user values are bound afterwards purely as data, so no input can alter the query''s grammar.', 'supplementary', 'csit-605/application-and-database-security/c2bb161170ab', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bd7ecb68-8b73-54aa-885e-0c106f7ad624', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'How do stored, reflected and DOM-based XSS differ?', 'Stored is saved on the server and served to viewers; reflected is echoed back from the request; DOM-based occurs entirely in client-side JavaScript writing untrusted data to a dangerous sink such as innerHTML.', 'supplementary', 'csit-605/application-and-database-security/4fe58f5f1a6e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0633b498-24ce-56f6-abcb-baa513e6b69f', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'Why is Content Security Policy described as a backstop rather than a fix for XSS?', 'CSP limits what injected script can run or load, but the encoding flaw that allowed injection still exists and must be fixed; weak policies such as allowing unsafe-inline give little protection.', 'supplementary', 'csit-605/application-and-database-security/dfb6cca2b9c3', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('eda6abb2-0f5d-5834-ae23-64638db67d28', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'What changed about XSS and access control in the OWASP Top 10:2021?', 'Broken Access Control rose to A01, and cross-site scripting was merged into the A03 Injection category.', 'supplementary', 'csit-605/application-and-database-security/c48ca7fc1394', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9d903d5e-f60f-524a-8281-4d9925b96d3d', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '5d3b9fcc-0fce-5f6a-b739-dbfd4782ccd7', 'What role should a web application firewall play in remediating injection flaws?', 'A compensating control that buys time and blocks common patterns while code is fixed; it can be bypassed and is not a substitute for parameterisation and encoding.', 'supplementary', 'csit-605/application-and-database-security/09bdb0d200fd', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d276ddc9-d257-5a69-8abb-bfac794497a3', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'Why are two passwords not multi-factor authentication?', 'MFA requires factors from different categories (knowledge, possession, inherence); two passwords are both knowledge factors and fail the same way.', 'supplementary', 'csit-605/application-and-database-security/91e08755523d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('26849003-5f73-5f6a-b625-2693ed561ed3', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'What makes FIDO2/WebAuthn phishing resistant when SMS and TOTP codes are not?', 'The authenticator signs a challenge bound to the genuine site''s origin, so a look-alike site cannot obtain a usable signature, whereas typed codes can be relayed in real time.', 'supplementary', 'csit-605/application-and-database-security/9855ac1e2742', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d2aa0634-18ba-5b90-8552-3733247cbe5f', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'Summarise the core NIST SP 800-63B password recommendations.', 'Allow long passphrases, screen against common and breached passwords, no arbitrary composition rules, no forced periodic changes (change on compromise), no security questions, allow paste, rate-limit attempts, store with salted slow hashing.', 'supplementary', 'csit-605/application-and-database-security/5c32dd1cf198', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d45e8dbb-fc55-5c78-8d8e-e807b60af35b', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'OAuth 2.0 versus OpenID Connect?', 'OAuth 2.0 delegates authorisation via access tokens; OpenID Connect adds authentication through a signed ID token describing the user, enabling single sign-on.', 'supplementary', 'csit-605/application-and-database-security/bf5e028b6ab5', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('886b3ade-de40-5f64-aa5f-d8a826e69028', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'When would you choose ABAC over RBAC?', 'When access depends on context such as branch, data sensitivity, time or device, and pure roles would cause role explosion; RBAC remains simpler to audit for coarse entitlements.', 'supplementary', 'csit-605/application-and-database-security/5368e95a468a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e650c7e2-bc31-5082-9405-ef0044307ca7', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', 'dec6a055-f7dd-5546-b9c1-727f8a95f0e6', 'List four session management controls.', 'Cryptographically random session IDs, regeneration at login (prevents fixation), Secure/HttpOnly/SameSite cookie flags, idle and absolute timeouts with invalidation at logout and re-authentication for risky actions.', 'supplementary', 'csit-605/application-and-database-security/ca4d3d243a29', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f7a75a3a-fa49-5d5e-9938-f5334c6d1a3c', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'What does "shift left" mean in a secure SDLC?', 'Moving security activities earlier (requirements, design, coding) where defects are cheaper to fix, while still testing and monitoring later phases.', 'supplementary', 'csit-605/application-and-database-security/5e5336a623d2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ac710c56-b553-5ef2-ad4d-d004100c6943', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'Compare SAST, DAST and SCA in one line each.', 'SAST analyses code without running it; DAST tests the running application from outside; SCA identifies third-party components with known vulnerabilities.', 'supplementary', 'csit-605/application-and-database-security/1496124a0a14', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ae58f518-c9db-5147-9cd4-ba9cdb58461f', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'What is threat-informed testing?', 'Deriving test cases from the system''s threat model and documented attacker techniques, so each test links to a realistic threat and coverage can be justified.', 'supplementary', 'csit-605/application-and-database-security/909c8d8846d9', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('45ab7127-b453-5eaf-95e2-f61aa9d30172', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'What does row-level security add beyond application-layer filtering?', 'The database itself enforces which rows a session may access, so an application query missing a filter cannot expose rows outside the user''s scope.', 'supplementary', 'csit-605/application-and-database-security/044ce3c31277', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2790c58a-033a-5901-88a4-52f5557dfe1f', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'What does transparent data encryption protect against, and what not?', 'It protects data files and backups if stolen; it does not protect data returned through legitimate or injected queries, which the engine decrypts automatically.', 'supplementary', 'csit-605/application-and-database-security/8ba9f55954ed', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a8a4bec3-c10b-50c4-9408-fb4406f686de', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'd4cc9a37-040d-5e5e-98a5-bd91c12b72d0', '239219a4-3d48-5413-8d0c-6867d086b9f4', 'What was the central lifecycle failure in the Equifax 2017 breach?', 'A known Apache Struts vulnerability (CVE-2017-5638) with an available patch was not identified and fixed on an internet-facing portal, compounded by monitoring gaps.', 'supplementary', 'csit-605/application-and-database-security/4ff8e97e70e1', true)
