insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('a010847e-43ed-5870-9355-17e182d92deb', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'cloud-and-infrastructure-security', 'Cloud and Infrastructure Security', 'Protecting cloud services, identities, configurations and data, and recovering from failure.', 6, true)
