insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a747b5e3-db2b-5497-be4f-daca59b3cbc3', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'csit-605/cloud-and-infrastructure-security/q01', 'mcq', 'understand', 'easy', 'Apply the shared responsibility model across service models', 'Under the shared responsibility model, which responsibility remains with the customer in IaaS, PaaS and SaaS alike?', null, null, '[{"id":"a","text":"Patching the hypervisor"},{"id":"b","text":"Physical security of the data centre"},{"id":"c","text":"Protecting their data and managing identities and access"},{"id":"d","text":"Maintaining the provider''s global network"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
