insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a747b5e3-db2b-5497-be4f-daca59b3cbc3', '{"option":"c"}'::jsonb, 'Data, its classification and the identities that can access it are always the customer''s responsibility. Hypervisors, physical facilities and the provider''s network are part of security of the cloud, handled by the provider in all three models.', null)
