insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('33a56dd4-ca9d-543c-8ec7-83a7b25ce05b', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'csit-605/cloud-and-infrastructure-security/q02', 'matching', 'understand', 'medium', 'Distinguish cloud service models by customer duties', 'Match each service to the model it best represents.', null, null, '{"left":[{"id":"l1","text":"Renting virtual machines and patching their operating systems yourself"},{"id":"l2","text":"A managed database where the provider patches the engine"},{"id":"l3","text":"A hosted email and office productivity suite"},{"id":"l4","text":"A cloud shared by several government agencies with common requirements"}],"right":[{"id":"r1","text":"IaaS"},{"id":"r4","text":"Community cloud"},{"id":"r3","text":"SaaS"},{"id":"r2","text":"PaaS"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
