insert into public.question_keys (question_id, correct, explanation, model_answer) values ('33a56dd4-ca9d-543c-8ec7-83a7b25ce05b', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'IaaS, PaaS and SaaS are service models with progressively more provider-managed layers; community cloud is a deployment model defined in NIST SP 800-145, shared by organisations with common concerns.', null)
