insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c85b8216-02a8-5be1-9c2d-c54a3e2243ca', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'csit-605/cloud-and-infrastructure-security/q03', 'true_false', 'understand', 'easy', 'Recognise the risk of long-lived access keys', 'Attaching a role with temporary credentials to a cloud workload is generally safer than storing a long-lived access key in the application''s configuration file.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c85b8216-02a8-5be1-9c2d-c54a3e2243ca', '{"value":true}'::jsonb, 'Temporary credentials expire automatically and are not stored where they can leak through repositories, images or logs. Static keys remain valid until someone notices and revokes them.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3eb14c53-607e-5b5f-98bb-06c174b8b4a1', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'csit-605/cloud-and-infrastructure-security/q04', 'scenario', 'analyse', 'hard', 'Analyse the attack chain in an SSRF-based cloud breach', 'Which single change would most directly have limited the damage once the credentials were obtained?', 'A web application firewall running on a cloud virtual machine can be induced to fetch arbitrary URLs. An attacker uses it to request the instance metadata service, obtains temporary credentials for the machine''s role, and then lists and downloads many storage buckets.', null, '[{"id":"a","text":"Enabling full-disk encryption on the virtual machine"},{"id":"b","text":"Restricting the role''s permissions to only the specific resources the firewall needed"},{"id":"c","text":"Changing the root account password"},{"id":"d","text":"Moving the virtual machine to a different region"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3eb14c53-607e-5b5f-98bb-06c174b8b4a1', '{"option":"b"}'::jsonb, 'This is the Capital One 2019 pattern. The SSRF gave access to the role''s credentials, and the role''s broad storage permissions turned that into mass data access. Least privilege on the role limits blast radius. Disk encryption, root password changes and region moves do not affect what the stolen role could do.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7e53e241-5f6c-5aed-bdd6-6fb0658bef59', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'csit-605/cloud-and-infrastructure-security/q05', 'short_answer', 'recall', 'medium', 'Name the practice of using an organisation''s identity provider for cloud sign-in', 'What term describes letting staff sign in to cloud services with their organisation''s own identity provider, via SAML or OpenID Connect, instead of separate cloud passwords?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7e53e241-5f6c-5aed-bdd6-6fb0658bef59', '{"answers":["federation","identity federation","federated identity"]}'::jsonb, 'Federation centralises authentication and MFA and means that disabling a leaver''s corporate account removes their cloud access, reducing orphaned accounts.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9104ccf0-96c2-527a-bf61-b230dcea42da', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'csit-605/cloud-and-infrastructure-security/q06', 'mcq', 'apply', 'medium', 'Prioritise cloud account hardening', 'A small company has just opened a public cloud account. Which action should be taken first?', null, null, '[{"id":"a","text":"Enable strong MFA on the root or global administrator account and remove any root access keys"},{"id":"b","text":"Purchase a dedicated hot DR site"},{"id":"c","text":"Disable audit logging to reduce cost"},{"id":"d","text":"Grant all developers administrator rights to speed up work"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9104ccf0-96c2-527a-bf61-b230dcea42da', '{"option":"a"}'::jsonb, 'The root account can do anything, including deleting all resources and logs, so protecting it is the highest-value first step. Audit logging should be enabled, not disabled, and broad administrator rights violate least privilege. A hot DR site is a later, risk-based decision.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7efb02a3-86fa-5fb1-ae96-3a36e9585263', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'csit-605/cloud-and-infrastructure-security/q07', 'true_false', 'evaluate', 'medium', 'Evaluate the claim that SaaS removes customer security duties', 'Because the provider runs the application, a SaaS customer has no meaningful security configuration responsibilities.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7efb02a3-86fa-5fb1-ae96-3a36e9585263', '{"value":false}'::jsonb, 'SaaS customers still manage user identities, MFA, administrator roles, sharing settings, retention and audit logging. Many SaaS data exposures result from customer-side settings such as public sharing links.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3f82d3e4-9e47-52ce-87e6-006d383294ce', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'csit-605/cloud-and-infrastructure-security/q08', 'mcq', 'understand', 'easy', 'Define configuration drift', 'What is configuration drift?', null, null, '[{"id":"a","text":"The movement of data between cloud regions"},{"id":"b","text":"The gradual divergence of a system''s actual settings from its approved baseline"},{"id":"c","text":"A type of denial-of-service attack"},{"id":"d","text":"The rotation of encryption keys"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3f82d3e4-9e47-52ce-87e6-006d383294ce', '{"option":"b"}'::jsonb, 'Drift occurs through manual changes, emergency fixes and updates. Continuous monitoring (for example CSPM) detects it so that it can be remediated or formally accepted.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c9620961-72f9-5bc8-a083-eda7a153ff8a', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'csit-605/cloud-and-infrastructure-security/q09', 'scenario', 'apply', 'medium', 'Apply data classification to prioritise findings', 'How should the security team prioritise these findings?', 'Illustrative scenario. A posture management tool reports two publicly readable storage buckets. One holds published product brochures; the other holds scanned Ghana Card images submitted by customers for identity verification.', null, '[{"id":"a","text":"Treat both equally because both are public"},{"id":"b","text":"Treat the Ghana Card bucket as critical because it contains restricted personal data, and review the brochure bucket as low priority"},{"id":"c","text":"Treat the brochure bucket as critical because it is customer-facing"},{"id":"d","text":"Ignore both because storage is the provider''s responsibility"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c9620961-72f9-5bc8-a083-eda7a153ff8a', '{"option":"b"}'::jsonb, 'Classification turns identical misconfigurations into different risk levels. National ID images are restricted personal data protected under Act 843, so exposure is serious and may require investigation of access logs and breach assessment. Brochures are public by design. Storage configuration is the customer''s responsibility.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('578d1f79-d877-5606-8092-1ed75c1aebc3', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'csit-605/cloud-and-infrastructure-security/q10', 'true_false', 'understand', 'easy', 'Recognise correct secrets management', 'Storing cloud access keys in a private code repository is acceptable because only employees can see the repository.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('578d1f79-d877-5606-8092-1ed75c1aebc3', '{"value":false}'::jsonb, 'Repository access can be compromised, as in the Uber 2016 breach. Secrets belong in a dedicated secrets manager with rotation, access control and logging, and workloads should use temporary credentials where possible.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c7097054-ab1f-52a0-bca6-4c63ce2b8c1e', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'csit-605/cloud-and-infrastructure-security/q11', 'matching', 'understand', 'medium', 'Match data protection controls to their purpose', 'Match each control to its purpose.', null, null, '{"left":[{"id":"l1","text":"Tokenisation"},{"id":"l2","text":"Masking"},{"id":"l3","text":"Data loss prevention"},{"id":"l4","text":"Customer-managed keys"},{"id":"l5","text":"Data minimisation"}],"right":[{"id":"r5","text":"Collects and keeps only the data needed for the stated purpose"},{"id":"r4","text":"Gives the organisation control over rotation and revocation of encryption keys"},{"id":"r3","text":"Detects and blocks unauthorised movement of sensitive data"},{"id":"r1","text":"Replaces a sensitive value with a surrogate, keeping the real value in a secured vault"},{"id":"r2","text":"Shows only part of a value, such as the last four digits, to users who do not need it all"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c7097054-ab1f-52a0-bca6-4c63ce2b8c1e', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'These controls complement encryption. They reduce how much sensitive data exists, who can see it and where it can go, and keep control of keys with the data owner.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d2964afb-7d75-5afb-9325-1f6d539d1293', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'csit-605/cloud-and-infrastructure-security/q12', 'short_answer', 'recall', 'medium', 'Name the category of tools that continuously assess cloud settings', 'What category of tool continuously checks cloud configurations against policies and benchmarks and alerts on risky settings (abbreviation accepted)?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d2964afb-7d75-5afb-9325-1f6d539d1293', '{"answers":["cloud security posture management","CSPM"]}'::jsonb, 'CSPM tools detect public storage, unencrypted resources, permissive security groups and similar issues across accounts, supporting continuous verification of baselines.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('80a34456-bc99-5458-926f-bcd410cc5231', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'csit-605/cloud-and-infrastructure-security/q13', 'mcq', 'evaluate', 'hard', 'Evaluate the design of a classification scheme', 'A company''s draft policy classifies all information as "Strictly Confidential" and requires encryption and director approval for any sharing. What is the main weakness?', null, null, '[{"id":"a","text":"It is too permissive"},{"id":"b","text":"Over-classification makes rules impractical, so staff bypass them and truly sensitive data is not distinguished"},{"id":"c","text":"It does not mention firewalls"},{"id":"d","text":"Classification should be set by the cloud provider"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('80a34456-bc99-5458-926f-bcd410cc5231', '{"option":"b"}'::jsonb, 'Effective schemes are simple, proportionate and actionable. Labelling everything at the highest level imposes unworkable controls, encourages workarounds and obscures which data truly needs the strongest protection. Data owners, not providers, set classification.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('19f10f82-f4d8-511c-b737-26f54ce2c50d', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'csit-605/cloud-and-infrastructure-security/q14', 'true_false', 'analyse', 'medium', 'Analyse the role of infrastructure as code in preventing misconfiguration', 'Defining cloud infrastructure in version-controlled templates allows insecure settings to be caught by peer review and automated scanning before deployment.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('19f10f82-f4d8-511c-b737-26f54ce2c50d', '{"value":true}'::jsonb, 'Infrastructure as code makes configuration visible, reviewable and repeatable, and scanners can block risky settings such as public access or wildcard permissions in the pipeline, shifting configuration security left.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3d28a2be-bd4a-56cb-b7e1-576f44601533', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'csit-605/cloud-and-infrastructure-security/q15', 'mcq', 'recall', 'easy', 'State the 3-2-1 backup rule', 'Which statement correctly describes the 3-2-1 backup rule?', null, null, '[{"id":"a","text":"Three backups per day, two administrators, one restore test per year"},{"id":"b","text":"Three copies of data, on two different types of media or storage, with one copy off-site"},{"id":"c","text":"Three servers, two data centres, one cloud provider"},{"id":"d","text":"Three-hour RPO, two-hour RTO, one-day MTD"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3d28a2be-bd4a-56cb-b7e1-576f44601533', '{"option":"b"}'::jsonb, '3-2-1 protects against corrupt copies, media-specific failure and site loss. Modern practice extends it with an immutable or offline copy and verified restores (3-2-1-1-0).', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2d6cc5c7-6acd-5c54-92d6-0ad1c9cb7cf4', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'csit-605/cloud-and-infrastructure-security/q16', 'scenario', 'apply', 'medium', 'Calculate whether a backup schedule meets RPO', 'How much data is lost, and is the RPO met?', 'Illustrative scenario. A company takes a full backup every night at 00:00 and no other backups. Its RPO for the finance system is 6 hours. The system fails at 15:00.', null, '[{"id":"a","text":"6 hours lost; RPO met"},{"id":"b","text":"9 hours lost; RPO not met"},{"id":"c","text":"15 hours lost; RPO not met"},{"id":"d","text":"0 hours lost; RPO met"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2d6cc5c7-6acd-5c54-92d6-0ad1c9cb7cf4', '{"option":"c"}'::jsonb, 'Data loss equals the failure time minus the last recoverable copy, 15:00 minus 00:00, which is 15 hours, exceeding the 6-hour RPO. Backups at least every 6 hours (or replication plus point-in-time copies) would be needed.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('665d14c5-2752-5230-8c22-2f271463fefa', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'csit-605/cloud-and-infrastructure-security/q17', 'short_answer', 'apply', 'medium', 'Calculate restore time from size and throughput', 'A 1,200 GB database restores at 150 GB per hour, with 1 additional hour for verification and reconnection. What is the total recovery time in hours (number only)?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('665d14c5-2752-5230-8c22-2f271463fefa', '{"answers":["9","9 hours","nine"]}'::jsonb, 'Restore time is 1,200 ÷ 150 = 8 hours, plus 1 hour of overhead, giving 9 hours. This must be compared with the RTO to judge whether the design is adequate.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b604c3c3-63d8-5df2-9288-6e681cb18fbc', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'csit-605/cloud-and-infrastructure-security/q18', 'true_false', 'understand', 'easy', 'Distinguish replication from backup', 'Continuous replication to a second site removes the need for point-in-time backups.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b604c3c3-63d8-5df2-9288-6e681cb18fbc', '{"value":false}'::jsonb, 'Replication copies changes faithfully, including deletions, corruption and ransomware encryption. Isolated point-in-time backups are needed to roll back to a clean state; the Maersk NotPetya case showed synchronised domain controllers being destroyed together.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('53805992-4330-540b-8569-32f6f7b6d4ec', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'csit-605/cloud-and-infrastructure-security/q19', 'matching', 'understand', 'medium', 'Match recovery concepts to definitions', 'Match each term to its definition.', null, null, '{"left":[{"id":"l1","text":"RPO"},{"id":"l2","text":"RTO"},{"id":"l3","text":"MTD"},{"id":"l4","text":"Warm site"},{"id":"l5","text":"Immutable backup"}],"right":[{"id":"r5","text":"Copy that cannot be altered or deleted during its retention period"},{"id":"r1","text":"Maximum acceptable data loss measured in time"},{"id":"r4","text":"Recovery location with some equipment ready, restored from recent backups"},{"id":"r2","text":"Maximum acceptable time to restore a system to agreed service"},{"id":"r3","text":"Total time a business process can be down before unacceptable harm"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('53805992-4330-540b-8569-32f6f7b6d4ec', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'RPO drives backup frequency, RTO drives restore capability, and both must sit within MTD from the business impact analysis. Warm sites trade cost against recovery speed; immutability resists ransomware.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ab7627ae-e7b7-5bac-bcad-d2dea25fa25e', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'csit-605/cloud-and-infrastructure-security/q20', 'scenario', 'evaluate', 'hard', 'Evaluate backup resilience against ransomware', 'What is the most significant weakness against a ransomware attacker who gains domain administrator rights?', 'Illustrative scenario. A logistics firm backs up nightly to a network-attached storage device joined to the corporate domain. Domain administrators can manage the backup software. The firm says it complies with 3-2-1 because it also copies backups weekly to a second NAS in the same building.', null, '[{"id":"a","text":"Nightly backups are too frequent"},{"id":"b","text":"All copies are online, reachable with domain credentials and on-site, so the attacker can delete or encrypt them before encrypting production"},{"id":"c","text":"NAS devices cannot store database backups"},{"id":"d","text":"Weekly copies violate data protection law"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ab7627ae-e7b7-5bac-bcad-d2dea25fa25e', '{"option":"b"}'::jsonb, 'Attackers target backups to force payment. Copies reachable with the same administrative credentials, all in one building, offer no immutable, offline or off-site protection. Separate credentials, MFA, an off-site immutable copy and restore testing are needed. The design is not genuinely 3-2-1 compliant because no copy is off-site.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7eb42be1-00e2-596a-bbde-8f560c9395da', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'csit-605/cloud-and-infrastructure-security/q21', 'mcq', 'analyse', 'medium', 'Analyse which testing method gives the strongest evidence', 'Which test provides the strongest evidence that an RTO can be met, while avoiding disruption to production?', null, null, '[{"id":"a","text":"Checking that last night''s backup job reported success"},{"id":"b","text":"A tabletop walk-through of the DR plan"},{"id":"c","text":"A full restoration of the system into an isolated environment, timed from start to service verification"},{"id":"d","text":"Reading the vendor''s documentation on restore speeds"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7eb42be1-00e2-596a-bbde-8f560c9395da', '{"option":"c"}'::jsonb, 'A timed, full restore to an isolated environment measures real-world recovery time and data integrity without affecting production. Job success messages, tabletop reviews and vendor claims do not prove the organisation can actually restore within the target.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9688727b-f6a0-597c-a15d-8d36740acd6a', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', null, 'csit-605/cloud-and-infrastructure-security/q22', 'case_analysis', 'evaluate', 'hard', 'Evaluate a cloud migration''s security, data protection and recovery design', 'Critically evaluate the plan and recommend a revised design covering shared responsibility, identity and access management, configuration security, data classification and protection, and backup and disaster recovery. Show how your design meets the RPO and RTO.', null, 'Illustrative scenario. Ahenfie Microinsurance, a fictional Kumasi company, is moving its policy administration system to a public cloud IaaS platform and its staff email to a SaaS suite. The current plan is: one shared administrator login for the cloud account used by the three-person IT team; the application will use an access key stored in a configuration file; customer documents (including Ghana Card scans and medical declarations) will go into a storage bucket; database snapshots will be kept in the same cloud account; and email will use passwords only. Management''s target is an RPO of 2 hours and an RTO of 6 hours for policy administration.', null, 20, array['Clarify shared responsibility for IaaS and SaaS components', 'Identity weaknesses and IAM redesign', 'Data classification and protection for restricted documents', 'Configuration guardrails and monitoring', 'Backup and DR design with RPO/RTO reasoning', 'Regulatory considerations and conclusion']::text[], '[{"criterion":"Shared responsibility and IAM","marks":5,"descriptor":"Correctly allocates duties; replaces shared admin with named federated accounts and MFA; uses roles not static keys; protects root."},{"criterion":"Classification and data protection","marks":5,"descriptor":"Classifies Ghana Card and medical data as restricted and specifies encryption, key management, access restriction, logging and minimisation."},{"criterion":"Configuration security","marks":4,"descriptor":"Proposes guardrails such as blocking public storage, infrastructure as code with review, CSPM and secrets management."},{"criterion":"Backup, DR and RPO/RTO reasoning","marks":6,"descriptor":"Identifies that same-account snapshots are vulnerable; proposes cross-account or cross-region immutable copies, frequent backups, a warm standby or tested restore approach and shows calculations against targets."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9688727b-f6a0-597c-a15d-8d36740acd6a', '{}'::jsonb, 'Examiners look for correct allocation of responsibilities, concrete IAM and data controls, recognition that same-account snapshots are not isolated, and explicit RPO/RTO arithmetic.', 'Under IaaS, Ahenfie is responsible for the operating system, application, configuration, identities and data; under SaaS, for user identities, MFA, sharing and retention. The shared administrator login destroys accountability and is a single point of compromise; it should be replaced by named accounts federated from the email suite''s identity provider with phishing-resistant MFA, a protected root account without access keys, and least-privilege roles. The application should use an attached role with temporary credentials rather than a static key in a configuration file, and secrets scanning should be enabled.

Ghana Card scans and medical declarations are restricted personal data under Act 843. They should be stored in a bucket with account-level public access blocked, encryption using customer-managed keys, access limited to the application role and a small claims team, access logging, and retention limits. Guardrails, infrastructure as code with peer review and a CSPM tool should prevent and detect misconfiguration.

Keeping snapshots in the same account means an attacker with administrative access could delete production and backups together. A better design takes database backups every hour (worst-case loss about one hour, inside the 2-hour RPO) and copies them to a separate backup account or region with object lock. For RTO, if a restore of the database takes, say, three hours at measured throughput plus one hour to redeploy the application from templates and verify, total recovery of four hours meets the 6-hour RTO; if measured times are longer, a warm standby should be added. Quarterly timed restore tests provide evidence. The answer should conclude that the plan''s main risks are identity and backup isolation, and note relevant duties under Act 843 and, where applicable, sector or Act 1038 obligations.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('067557de-7a16-5094-984d-f7b1334cac27', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'What is the core message of the shared responsibility model?', 'The provider secures the cloud (facilities, hardware, hypervisor, network); the customer secures what it puts in the cloud, and data and identities are always the customer''s duty whatever the service model.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/9589ad3d2a52', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('30959201-7074-5d30-a7c3-82acdc08f76b', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'Why is identity described as the new perimeter in cloud computing?', 'Management consoles and APIs are reachable over the internet, so anyone with valid credentials can control resources; strong identity controls replace the physical and network boundary.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/b0da0e439193', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b7094f7b-db2c-5882-82eb-74dedb04235a', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'Name the five essential characteristics of cloud computing in NIST SP 800-145.', 'On-demand self-service, broad network access, resource pooling, rapid elasticity and measured service.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/d68779d4dbd7', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0fb92ce2-c594-5943-9516-a0c379ba2048', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'Why should workloads use roles rather than static access keys?', 'Roles issue short-lived credentials automatically, so nothing long-lived is stored in code or configuration to leak; exposure windows shrink and rotation is built in.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/d8491f11d8c8', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bb5d904b-8153-5498-9336-23215835d671', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'How did the Capital One 2019 breach illustrate shared responsibility?', 'A customer-side WAF misconfiguration enabled SSRF to the metadata service, yielding role credentials whose broad storage permissions allowed bulk data access; the provider''s infrastructure was not breached.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/069f468a7285', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a15a7746-2aaf-50b9-a408-92d0bc45e70b', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', 'cd99bebe-fcca-5cc7-9b52-85c4186f405f', 'What does federation give an organisation for cloud access?', 'Central sign-in with corporate MFA and single sign-on, and automatic removal of cloud access when a leaver''s corporate account is disabled.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/a8db5bb20acf', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4f320f82-3f6f-5e20-8960-ade669ba6874', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'Why is misconfiguration so common in cloud environments?', 'Self-service speed, enormous configuration complexity and the invisibility of exposure, combined with attackers'' automated internet-wide scanning.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/7af3f6c41b0e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b856f6bf-268e-53a7-b330-5e7e70eb268f', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'What makes a data classification scheme effective?', 'Few simple levels, clear owners for each dataset, and concrete handling rules and technical controls mapped to each label.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/649172fb39a7', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('7b2eef63-fb44-5e39-8a59-b7b8dfe10894', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'Tokenisation versus masking?', 'Tokenisation replaces the real value with a surrogate and stores the original in a secured vault; masking displays only part of the value to users while the full value still exists in the system.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/a9b0eb9b499e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('cab14207-9bbc-5497-b9e8-ae66b8393e59', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'Why is encryption "only as strong as its key management"?', 'If keys are stored with the data, widely accessible or never rotated, an attacker who reaches the data can usually reach the keys; separation, restricted access, rotation and logging are essential.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/0333de414d60', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e4bfc7ee-9442-5d5a-8021-3960840e2ab3', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'What were the configuration and governance lessons of the Uber 2016 breach?', 'Cloud credentials stored in a code repository enabled mass data access; concealing the breach by paying attackers turned it into a legal and reputational crisis.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/52168bca6682', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f5aa2a47-4ea8-567a-b2da-6ca07f2565df', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '59531fd7-ed50-560d-a876-4dcf4bbc9a2b', 'How does infrastructure as code improve configuration security?', 'Settings become version-controlled, peer-reviewed, automatically scanned before deployment and reproducible, and drift can be detected against the template.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/215d02381c6d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('dd5e68c6-d654-5f67-b1a0-fb7f4cb3f142', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'What do the extra "1" and "0" add in 3-2-1-1-0?', 'One immutable or offline copy that survives an attacker with admin rights, and zero errors on verified restore tests.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/f8382b31f6f5', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4791e36e-5407-5ccf-a711-d77b5340f15a', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'RPO versus RTO: what does each drive?', 'RPO (maximum data loss) drives backup or replication frequency; RTO (maximum downtime) drives restore capability such as throughput, standby systems and procedures.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/e7a6157137cb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a53c0df4-0040-501b-bea1-34a0bb751260', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'How do you check a design against RPO and RTO?', 'Worst-case data loss = time since last recoverable copy; recovery time = data size ÷ restore throughput + provisioning and verification overheads; compare each with the targets.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/54584c17fe50', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('870ad024-c049-5fb9-98da-531d23b1e0e2', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'Compare hot, warm and cold DR sites.', 'Hot is fully equipped with replicated data (minutes to hours, high cost); warm has some equipment and restores from backups (hours to days); cold provides space and power only (days to weeks, low cost).', 'supplementary', 'csit-605/cloud-and-infrastructure-security/40ea4202b0a1', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4fcb55af-c4a7-52f4-933a-3bf19bf1c647', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'Why is replication not a backup?', 'It copies every change, including deletion, corruption and ransomware encryption, to the replica; isolated point-in-time copies are needed to restore a clean state.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/7b6e9b6f550a', true)
