insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2e456b2d-f63b-5ecc-bad7-0a0267ede34e', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a010847e-43ed-5870-9355-17e182d92deb', '9a1f3735-d02a-576c-aa3e-db2d6e379c34', 'What is the Ghana connection in Maersk''s NotPetya recovery?', 'A domain controller in Maersk''s Ghana office survived because a power outage had taken it offline, and it was used to rebuild the company''s Active Directory.', 'supplementary', 'csit-605/cloud-and-infrastructure-security/5f3f0f415ab7', true)
