insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('a411da28-b172-571f-b29f-838f9b32d7b3', 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'practical-security', 'Practical Security', 'Applying defensive techniques to realistic, authorised scenarios.', 8, true)
