insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a7360743-5cd7-5b5a-9615-00f236bb4ffd', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a411da28-b172-571f-b29f-838f9b32d7b3', '31538f45-52e0-5781-bf80-216a56dea0b6', 'Why focus threat analysis on trust boundaries?', 'Where data crosses from less trusted to more trusted zones, identities and inputs must be verified; failures at these crossings cause many serious flaws, such as forged partner callbacks.', 'supplementary', 'csit-605/practical-security/e11e3ae07b80', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('05ada67b-dc63-5ccf-9ab9-4f2ede64b1ce', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a411da28-b172-571f-b29f-838f9b32d7b3', '31538f45-52e0-5781-bf80-216a56dea0b6', 'Repudiation versus spoofing?', 'Spoofing is pretending to be someone else; repudiation is denying an action you performed because there is insufficient evidence, countered by individual accounts and tamper-evident logs.', 'supplementary', 'csit-605/practical-security/877a2d8a41a0', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
