insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d58d9ea1-a4cd-57e8-a134-6d060081cc42', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a411da28-b172-571f-b29f-838f9b32d7b3', 'b29b2e9e-4891-5bbc-9c17-4d97c6297e49', 'Why is CVSS severity not the same as risk?', 'The base score ignores your exposure, asset criticality, active exploitation and compensating controls; risk-based prioritisation adds these, using sources such as CISA KEV and EPSS.', 'supplementary', 'csit-605/practical-security/af10093fc7e1', true)
