insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('86e6cc6f-c26f-5f79-b411-f500faff7f8c', null, 'c70e42f8-2885-5638-8b66-6e3de39938a7', 'a411da28-b172-571f-b29f-838f9b32d7b3', 'c6b19197-9d71-5b55-98e4-63d238c9b884', 'Defence in depth versus zero trust?', 'Defence in depth layers independent controls so one failure is not fatal; zero trust removes implicit trust based on network location and evaluates every access request; they are complementary.', 'supplementary', 'csit-605/practical-security/879999931c11', true)
