insert into public.quizzes (id, external_ref, kind, title, description, instructions, course_id, module_id, lesson_id, scope_course_ids, question_count, open_ended_count, time_limit_minutes, randomize, reveal_answers, is_published, sort_order) values ('e7735315-6507-5dc8-808c-f3dfc144eaf4', 'csit-607/ai-foundations/assessment', 'module_assessment', 'Module assessment: AI Foundations', 'A timed assessment covering every lesson in "AI Foundations".', '14 objective questions and one extended-response question. You have 35 minutes. The objective section is scored automatically; the extended response is self-assessed against a rubric. All questions are supplementary practice questions generated for GradPath. They are not official University of Ghana examination questions, and results are not official grades.', '8462b4f9-230e-5350-ad0a-300b08f70203', '816c50d6-74af-5d5e-bb4d-9542c80120f0', null, '{}'::uuid[], 14, 1, 35, true, 'after_submit', true, 1)
