insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('151ddbe2-6290-585a-93b0-29812978675a', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '689be811-2f84-5173-9ed9-48d5203e32ee', 'csit-607/machine-learning/q05', 'short_answer', 'recall', 'easy', 'Identify the known outcome in supervised learning', 'In supervised learning, what is the term for the known outcome a model learns to predict?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
