insert into public.question_keys (question_id, correct, explanation, model_answer) values ('151ddbe2-6290-585a-93b0-29812978675a', '{"answers":["label","target","the label","target variable"]}'::jsonb, 'The label (or target) is the outcome recorded for each training example, such as defaulted or repaid. Features are the inputs used to predict it.', null)
