insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6b4231d0-1507-5ee6-8d69-0dd87f00f3e6', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '689be811-2f84-5173-9ed9-48d5203e32ee', 'csit-607/machine-learning/q06', 'mcq', 'analyse', 'hard', 'Analyse selection bias in supervised labels', 'A digital lender trains a default model using only loans it previously approved. What is the main analytical problem?', null, null, '[{"id":"a","text":"The model will be unable to compute probabilities"},{"id":"b","text":"The labels exist only for previously approved applicants, so the model learns nothing about the rejected population"},{"id":"c","text":"Default is a regression target, not a classification target"},{"id":"d","text":"Approved loans contain no features"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6b4231d0-1507-5ee6-8d69-0dd87f00f3e6', '{"option":"b"}'::jsonb, 'This is selection bias. Outcomes are only observed for applicants the old process accepted, so the model may perform poorly on people unlike past approvals. Logistic models can still output probabilities, default is a classification target, and approved loans do have features.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bf1d767e-3fc7-5650-b4e0-39bf59d7dd8f', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '8f7c9c59-0707-548f-821f-e62b29f08d43', 'csit-607/machine-learning/q07', 'mcq', 'apply', 'medium', 'Compute a linear regression prediction', 'A model is predicted sales = 1.7 + 1.5 × promo spend (both in hundreds). What is predicted sales when promo spend is 4?', null, null, '[{"id":"a","text":"6.2"},{"id":"b","text":"7.7"},{"id":"c","text":"5.7"},{"id":"d","text":"8.0"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bf1d767e-3fc7-5650-b4e0-39bf59d7dd8f', '{"option":"b"}'::jsonb, '1.7 + 1.5 × 4 = 1.7 + 6.0 = 7.7 hundred units. A value of 6.2 is the mean of y, 5.7 omits part of the slope term, and 8.0 is the actual week-4 value in the lesson''s data, not the prediction.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('09a86646-95bb-5a42-84be-bfdc32358459', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '8f7c9c59-0707-548f-821f-e62b29f08d43', 'csit-607/machine-learning/q08', 'mcq', 'apply', 'hard', 'Apply the sigmoid function in logistic regression', 'A logistic regression model produces a linear score z = 0 for an applicant. What is the predicted probability of the positive class?', null, null, '[{"id":"a","text":"0"},{"id":"b","text":"0.5"},{"id":"c","text":"1"},{"id":"d","text":"It cannot be determined without the threshold"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('09a86646-95bb-5a42-84be-bfdc32358459', '{"option":"b"}'::jsonb, 'The sigmoid is 1 / (1 + e^(−z)). With z = 0, e^0 = 1, so p = 1 / 2 = 0.5. The threshold is used to turn the probability into a decision, not to compute the probability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('aa5e1d68-7f86-5d6c-a20e-8f671697f5f9', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '8f7c9c59-0707-548f-821f-e62b29f08d43', 'csit-607/machine-learning/q09', 'short_answer', 'apply', 'hard', 'Compute Gini impurity of a node', 'A decision tree node contains 4 churners and 4 non-churners. What is its Gini impurity? Give a decimal.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('aa5e1d68-7f86-5d6c-a20e-8f671697f5f9', '{"answers":["0.5","0.50",".5"]}'::jsonb, 'Gini = 1 − (0.5² + 0.5²) = 1 − 0.5 = 0.5, the maximum for two classes. A pure node would have Gini 0.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('deef154d-cfad-54e0-9644-c72e29db2753', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '8f7c9c59-0707-548f-821f-e62b29f08d43', 'csit-607/machine-learning/q10', 'true_false', 'understand', 'medium', 'Interpret regression coefficients correctly', 'A positive regression coefficient on promotional spend proves that promotions cause higher sales.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('deef154d-cfad-54e0-9644-c72e29db2753', '{"value":false}'::jsonb, 'Coefficients describe associations in the observed data. Other factors, such as promotions being run in festive weeks, may explain the relationship. Causal claims require experiments or careful causal analysis.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('75c45e1e-4ee4-5cc6-a465-c4a102b4e495', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '8f7c9c59-0707-548f-821f-e62b29f08d43', 'csit-607/machine-learning/q11', 'scenario', 'evaluate', 'hard', 'Evaluate model choice in a regulated context', 'Which decision is best justified?', 'Illustrative scenario. A rural bank compares a logistic regression model and a gradient-boosted tree for loan screening. The boosted model is slightly more accurate on held-out data. The bank must explain decisions to applicants and its board.', null, '[{"id":"a","text":"Deploy the boosted model because accuracy is the only relevant criterion"},{"id":"b","text":"Deploy the logistic model with a reviewed threshold and monitor the boosted model as a challenger"},{"id":"c","text":"Deploy neither, because machine learning cannot be used in lending"},{"id":"d","text":"Average the two models'' coefficients"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('75c45e1e-4ee4-5cc6-a465-c4a102b4e495', '{"option":"b"}'::jsonb, 'In a regulated, high-impact setting, a small accuracy gain may not outweigh the explainability and predictability of logistic regression. Keeping the boosted model as a challenger preserves learning. Accuracy is not the only criterion, ML is used in lending with safeguards, and tree ensembles do not have coefficients to average.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1c7a357a-8be8-51e3-8ce2-1a4c1eb5661e', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '8f7c9c59-0707-548f-821f-e62b29f08d43', 'csit-607/machine-learning/q12', 'matching', 'recall', 'easy', 'Match model types to business tasks', 'Match each business task to the most natural model framing.', null, null, '{"left":[{"id":"l1","text":"Predicting next week''s units sold of rice per branch"},{"id":"l2","text":"Estimating the probability that an applicant defaults"},{"id":"l3","text":"Producing transparent if-then rules for triaging support tickets"},{"id":"l4","text":"Combining many trees trained on random samples for higher accuracy"}],"right":[{"id":"r1","text":"Regression"},{"id":"r4","text":"Random forest"},{"id":"r2","text":"Logistic regression"},{"id":"r3","text":"Shallow decision tree"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1c7a357a-8be8-51e3-8ce2-1a4c1eb5661e', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Quantities call for regression, probabilities of a category for logistic regression, readable rules for a shallow tree, and higher accuracy at some loss of transparency for ensembles such as random forests.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f2c00d93-2b31-5eb0-8602-8eacc43eb77d', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'd82c4e94-b6bc-588d-9d3f-b6e911bb7bd1', 'csit-607/machine-learning/q13', 'mcq', 'understand', 'easy', 'Describe the k-means update step', 'In k-means, how is each centroid updated after points are assigned?', null, null, '[{"id":"a","text":"It moves to the point furthest from it"},{"id":"b","text":"It becomes the mean of the points assigned to it"},{"id":"c","text":"It is chosen at random again"},{"id":"d","text":"It becomes the median of all points in the dataset"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f2c00d93-2b31-5eb0-8602-8eacc43eb77d', '{"option":"b"}'::jsonb, 'The update step sets each centroid to the mean of its assigned points, which reduces the within-cluster sum of squares. Random reselection happens only at initialisation, and the dataset-wide median ignores cluster membership.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('85c2284c-fbd5-5a96-b42f-d82677f816a3', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'd82c4e94-b6bc-588d-9d3f-b6e911bb7bd1', 'csit-607/machine-learning/q14', 'scenario', 'apply', 'medium', 'Apply a k-means assignment', 'To which centroid is the customer assigned, using Euclidean distance?', 'Illustrative scenario. Two centroids are at c1 = (1, 1.5) and c2 = (5.25, 4.5). A customer is at (2, 1) using features visits per month and basket value in hundreds of cedis.', null, '[{"id":"a","text":"c1, because its squared distance is 1.25 compared with about 22.8 for c2"},{"id":"b","text":"c2, because it has more members"},{"id":"c","text":"c2, because its squared distance is smaller"},{"id":"d","text":"Neither, because the point lies between them"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('85c2284c-fbd5-5a96-b42f-d82677f816a3', '{"option":"a"}'::jsonb, 'Distance squared to c1 is (2 − 1)² + (1 − 1.5)² = 1.25, and to c2 is (2 − 5.25)² + (1 − 4.5)² ≈ 22.81. The nearer centroid is c1. Cluster size plays no role in assignment, and every point is always assigned to some centroid.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('83103eaa-9f8b-51a9-9702-b0b984de6b90', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'd82c4e94-b6bc-588d-9d3f-b6e911bb7bd1', 'csit-607/machine-learning/q15', 'true_false', 'understand', 'medium', 'Explain the effect of feature scaling', 'If annual spend in cedis and visits per month are used without scaling in k-means, annual spend will tend to dominate the clustering.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('83103eaa-9f8b-51a9-9702-b0b984de6b90', '{"value":true}'::jsonb, 'k-means relies on distances, and spend values in hundreds or thousands vary far more than visit counts, so distance is driven by spend. Standardising each feature to mean 0 and standard deviation 1 gives them comparable influence.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4e6c1a77-ab1d-50a2-a56d-34066d1672d1', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'd82c4e94-b6bc-588d-9d3f-b6e911bb7bd1', 'csit-607/machine-learning/q16', 'short_answer', 'recall', 'medium', 'Name a method for choosing the number of clusters', 'Name the heuristic that plots within-cluster sum of squares against k and looks for a bend where improvements slow sharply.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4e6c1a77-ab1d-50a2-a56d-34066d1672d1', '{"answers":["elbow method","elbow","the elbow method"]}'::jsonb, 'The elbow method is widely used but often ambiguous, so it should be combined with silhouette analysis and business actionability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('60a595e3-f029-5ed2-a036-d751f220b637', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'd82c4e94-b6bc-588d-9d3f-b6e911bb7bd1', 'csit-607/machine-learning/q17', 'mcq', 'analyse', 'hard', 'Analyse algorithm suitability for anomaly screening', 'Why might DBSCAN suit screening mobile money wallet behaviour better than k-means?', null, null, '[{"id":"a","text":"DBSCAN requires k in advance, which simplifies tuning"},{"id":"b","text":"DBSCAN finds irregularly shaped dense clusters and labels isolated points as noise, which highlights unusual wallets"},{"id":"c","text":"DBSCAN only works on categorical variables"},{"id":"d","text":"DBSCAN guarantees the global optimum of WCSS"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('60a595e3-f029-5ed2-a036-d751f220b637', '{"option":"b"}'::jsonb, 'DBSCAN groups dense regions and marks sparse points as noise, a natural fit for spotting unusual behaviour. It does not require k, it works on numeric distances, and it does not optimise WCSS.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0c0c5627-36f1-5111-809e-b3305b6d13a6', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'd82c4e94-b6bc-588d-9d3f-b6e911bb7bd1', 'csit-607/machine-learning/q18', 'true_false', 'evaluate', 'hard', 'Evaluate the choice of k against business constraints', 'The clustering solution with the lowest within-cluster sum of squares should always be chosen for a marketing segmentation.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0c0c5627-36f1-5111-809e-b3305b6d13a6', '{"value":false}'::jsonb, 'WCSS always falls as k increases, reaching zero when every customer is its own cluster. A useful segmentation balances fit with stability, interpretability and the number of distinct actions the organisation can actually take.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6aca80fa-2ef5-5b4d-bc7c-1ba40326eb05', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'a952d1b5-3271-5892-8989-6a2c6a28443b', 'csit-607/machine-learning/q19', 'mcq', 'apply', 'medium', 'Compute precision from a confusion matrix', 'A fraud model has TP = 40, FP = 60, FN = 10 and TN = 890. What is its precision?', null, null, '[{"id":"a","text":"0.80"},{"id":"b","text":"0.40"},{"id":"c","text":"0.93"},{"id":"d","text":"0.53"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6aca80fa-2ef5-5b4d-bc7c-1ba40326eb05', '{"option":"b"}'::jsonb, 'Precision = TP / (TP + FP) = 40 / 100 = 0.40. The value 0.80 is recall (40 / 50), 0.93 is accuracy and 0.53 is F1.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6931c2af-1578-5ca6-a854-f5403a18356e', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'a952d1b5-3271-5892-8989-6a2c6a28443b', 'csit-607/machine-learning/q20', 'short_answer', 'apply', 'hard', 'Compute F1 from precision and recall', 'A model has precision 0.5 and recall 0.5. What is its F1 score? Give a decimal.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6931c2af-1578-5ca6-a854-f5403a18356e', '{"answers":["0.5","0.50",".5"]}'::jsonb, 'F1 = 2 × 0.5 × 0.5 / (0.5 + 0.5) = 0.5 / 1 = 0.5. When precision equals recall, F1 equals both; when they differ, the harmonic mean is pulled towards the lower value.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2abf1e13-bbb9-5bc6-a1a2-6e99ca5f6f9f', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'a952d1b5-3271-5892-8989-6a2c6a28443b', 'csit-607/machine-learning/q21', 'scenario', 'analyse', 'medium', 'Diagnose overfitting from training and validation results', 'What is the most likely diagnosis and remedy?', 'Illustrative scenario. A churn model reaches 99 per cent accuracy on training data but only 72 per cent on validation data drawn from a later month.', null, '[{"id":"a","text":"Underfitting; add more layers or depth"},{"id":"b","text":"Overfitting; simplify or regularise the model and check for leakage"},{"id":"c","text":"A perfect model; deploy immediately"},{"id":"d","text":"The validation data are wrong; discard them"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2abf1e13-bbb9-5bc6-a1a2-6e99ca5f6f9f', '{"option":"b"}'::jsonb, 'A large gap between training and validation performance indicates overfitting. Remedies include reducing complexity, regularisation, more data and checking that no leaking features inflate training results. Adding complexity would worsen the problem, and discarding inconvenient validation data defeats evaluation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('92ca38ce-0ab7-573f-b43e-4cbb5f787549', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'a952d1b5-3271-5892-8989-6a2c6a28443b', 'csit-607/machine-learning/q22', 'true_false', 'understand', 'medium', 'Explain the accuracy paradox', 'When only 5 per cent of transactions are fraudulent, a model that labels every transaction legitimate achieves 95 per cent accuracy while catching no fraud.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('92ca38ce-0ab7-573f-b43e-4cbb5f787549', '{"value":true}'::jsonb, 'This is the accuracy paradox. Under class imbalance, accuracy rewards predicting the majority class. Recall would be 0, revealing the model''s uselessness.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('27a022df-fea5-55e8-9471-cc043735620e', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'a952d1b5-3271-5892-8989-6a2c6a28443b', 'csit-607/machine-learning/q23', 'matching', 'understand', 'medium', 'Match evaluation concepts to definitions', 'Match each concept to its definition.', null, null, '{"left":[{"id":"l1","text":"Validation set"},{"id":"l2","text":"Test set"},{"id":"l3","text":"Data leakage"},{"id":"l4","text":"Recall"},{"id":"l5","text":"Hyperparameter"}],"right":[{"id":"r3","text":"Information unavailable at prediction time entering training"},{"id":"r5","text":"A setting chosen before training, such as tree depth"},{"id":"r4","text":"Proportion of actual positives correctly identified"},{"id":"r2","text":"Data used once at the end for an unbiased performance estimate"},{"id":"r1","text":"Held-out data used to compare models and tune hyperparameters"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('27a022df-fea5-55e8-9471-cc043735620e', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Keeping these roles separate is the foundation of honest evaluation. Using the test set for tuning or allowing leakage both produce over-optimistic estimates.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('50da301c-f0e1-5886-b7c2-e5591969bed3', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'a952d1b5-3271-5892-8989-6a2c6a28443b', 'csit-607/machine-learning/q24', 'scenario', 'evaluate', 'hard', 'Evaluate data splitting for forecasting', 'What is the strongest criticism of this evaluation?', 'Illustrative scenario. An analyst forecasting weekly supermarket demand randomly shuffles two years of weekly records into training and test sets and reports very low error.', null, '[{"id":"a","text":"Random splitting lets the model learn from weeks after the test weeks, so the error estimate is optimistic"},{"id":"b","text":"Two years is too much data for forecasting"},{"id":"c","text":"Demand forecasting should be evaluated with precision and recall"},{"id":"d","text":"The test set should always be larger than the training set"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('50da301c-f0e1-5886-b7c2-e5591969bed3', '{"option":"a"}'::jsonb, 'Forecasts must be evaluated on genuinely future periods. A time-based split, training on earlier weeks and testing on later weeks, mimics deployment. More data is generally helpful, regression metrics suit quantities, and test sets are normally smaller than training sets.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3d5ea978-9c4e-5b75-8cd8-084e1a5ccc3b', '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', null, 'csit-607/machine-learning/q25', 'essay', 'evaluate', 'hard', 'Design and justify an end-to-end supervised learning evaluation for a business problem', 'A Ghanaian telecommunications operator wants to predict which prepaid subscribers will churn within the next 60 days so that it can target retention offers. Critically discuss how you would frame the problem, prepare and split the data, select and train models, and evaluate them, justifying your choice of metrics and threshold in business terms.', null, null, null, 25, array['Frame as supervised classification; define the label and prediction horizon', 'Identify features available at prediction time and discuss leakage', 'Propose a time-based split with validation and test sets, and baselines', 'Compare candidate models such as logistic regression and decision trees, addressing overfitting', 'Justify metrics (precision, recall, F1, precision at top k) and a cost-based threshold', 'Address monitoring, fairness and data protection']::text[], '[{"criterion":"Problem framing","marks":4,"descriptor":"Clear label definition, horizon and link to the retention decision"},{"criterion":"Data preparation and leakage","marks":5,"descriptor":"Realistic features, explicit leakage checks, handling of class imbalance"},{"criterion":"Splitting and model selection","marks":6,"descriptor":"Time-based split, validation versus test roles, baselines, overfitting control"},{"criterion":"Metrics and threshold","marks":6,"descriptor":"Correct metric definitions and a cost-based, capacity-aware threshold with worked reasoning"},{"criterion":"Critical evaluation","marks":4,"descriptor":"Discusses limitations, monitoring, fairness and Act 843 obligations"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3d5ea978-9c4e-5b75-8cd8-084e1a5ccc3b', '{}'::jsonb, 'Examiners reward coherent links between the business decision, the data split and the metric. Generic lists of algorithms without evaluation reasoning score poorly.', 'A strong answer frames the task as binary classification, with the label "no top-up or activity in the 60 days after the scoring date". The decision is which subscribers receive a retention offer, so the model output should rank subscribers by churn probability.

Features must be available on the scoring date, for example recent top-up frequency and value, change in data usage, complaint counts, network-quality indicators and tenure. Any field recorded after the scoring date, such as a deactivation flag, would leak. Churners may be a minority, so stratification and imbalance-aware metrics are needed.

Data should be split by time, training on earlier scoring months, validating on a later month to tune hyperparameters and choose between models, and testing once on the most recent month. Baselines include "predict no churn" and a simple rule such as "no top-up in 14 days". Logistic regression provides an interpretable benchmark; a depth-limited decision tree or ensemble may capture interactions. Overfitting is diagnosed by comparing training and validation performance.

Accuracy is inappropriate under imbalance. Recall indicates how many churners are reached, precision how many offers are wasted, and precision at top k matches a fixed campaign budget. The threshold should minimise expected cost, for example comparing offer cost with expected lost margin, and respect contact capacity.

Finally, the answer should discuss monitoring for drift, checking whether offers systematically exclude some regions or groups, and processing subscriber data lawfully under Ghana''s Data Protection Act, 2012 (Act 843).')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d51a6fba-fc3d-51c2-8075-3512548f0a5d', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '689be811-2f84-5173-9ed9-48d5203e32ee', 'How do supervised, unsupervised and reinforcement learning differ?', 'By feedback. Supervised learning uses known labels, unsupervised learning has no labels and finds structure, and reinforcement learning learns a policy from rewards received while acting over time.', 'supplementary', 'csit-607/machine-learning/3644b55d9dde', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('81b1d489-050d-50c9-9d4f-48dd817b9698', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '689be811-2f84-5173-9ed9-48d5203e32ee', 'What is selection bias in supervised labels? Give a lending example.', 'Labels exist only for cases the past process allowed, so the model cannot learn about others. A lender that only observes repayment for approved applicants learns nothing about those it rejected.', 'supplementary', 'csit-607/machine-learning/41747a1b4f42', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('881f928e-df1b-5d5a-be95-21fa26063d43', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '689be811-2f84-5173-9ed9-48d5203e32ee', 'Why is exploration risky in business reinforcement learning?', 'Trying uncertain actions on real customers, such as extreme prices, can damage revenue and reputation, so business RL is often trained in simulators or on logs and deployed with constraints.', 'supplementary', 'csit-607/machine-learning/f0841599c14b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c5a2f3a3-be11-5f7d-bcb2-948492289d2c', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '689be811-2f84-5173-9ed9-48d5203e32ee', 'What is reward hacking?', 'An agent maximising a mis-specified reward in unintended ways, such as a recommender rewarded only for clicks promoting sensational content.', 'supplementary', 'csit-607/machine-learning/8978166f8aa4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('260b55b4-bcf8-5570-a6de-dca2683a5ace', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '689be811-2f84-5173-9ed9-48d5203e32ee', 'How did AlphaGo combine learning paradigms?', 'It used supervised learning to predict strong human players'' moves, then improved through reinforcement learning by playing against itself, combined with tree search.', 'supplementary', 'csit-607/machine-learning/0e86e4722076', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c67a52d0-70b8-5463-9bce-37f29e88d920', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '8f7c9c59-0707-548f-821f-e62b29f08d43', 'What decides whether a problem is classification or regression?', 'The type of label. Categories mean classification; continuous numbers mean regression. The framing should follow the business decision.', 'supplementary', 'csit-607/machine-learning/b3a45fe638e7', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d98ad20f-d505-511a-9d7b-ca0b4d17fa44', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '8f7c9c59-0707-548f-821f-e62b29f08d43', 'How does logistic regression turn a score into a probability?', 'It computes a linear score z and applies the sigmoid p = 1 / (1 + e^(−z)). z = 0 gives 0.5; large positive z approaches 1.', 'supplementary', 'csit-607/machine-learning/e77d3462831a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('60e0ba3b-3eef-5cee-819e-150944c32cd7', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '8f7c9c59-0707-548f-821f-e62b29f08d43', 'Why is a 0.5 threshold rarely optimal in business?', 'The costs of false positives and false negatives usually differ. If missing fraud is costly, a lower threshold catches more fraud at the price of more false alarms.', 'supplementary', 'csit-607/machine-learning/b272a1d21df8', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c056be73-da29-5447-9261-57c2b56c9103', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '8f7c9c59-0707-548f-821f-e62b29f08d43', 'How does a decision tree choose a split?', 'It evaluates candidate splits and picks the one with the largest reduction in impurity, such as size-weighted Gini of the child nodes compared with the parent.', 'supplementary', 'csit-607/machine-learning/3f82f0a338bf', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b9626ee8-06a9-5928-807c-dd628a56c70c', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', '8f7c9c59-0707-548f-821f-e62b29f08d43', 'What is the main lesson of the Zillow Offers case for regression?', 'Small systematic prediction errors become large losses when predictions drive many purchases, especially when market conditions shift and counterparties accept only overpriced offers.', 'supplementary', 'csit-607/machine-learning/f0579637e372', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ae3736a0-177c-5e5e-89a6-fb48656c6191', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'd82c4e94-b6bc-588d-9d3f-b6e911bb7bd1', 'What are the four steps of k-means?', 'Initialise k centroids, assign each point to the nearest centroid, recompute each centroid as the mean of its points, and repeat until assignments stop changing.', 'supplementary', 'csit-607/machine-learning/39e21428965a', true)
