insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ddeaaa1c-080e-5fc2-a434-3e093482496a', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '866ffb0f-cbfa-51e8-a1f4-b132b3aaf504', 'd82c4e94-b6bc-588d-9d3f-b6e911bb7bd1', 'Why standardise features before k-means?', 'Distances are dominated by features with large units. Standardising each feature to mean 0 and standard deviation 1 gives every feature comparable influence.', 'supplementary', 'csit-607/machine-learning/95a1b74465e2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
