insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7ff70b70-628a-5ef0-aebc-158821083e95', '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '538ff955-68b0-5300-be72-3daec28058fd', 'csit-607/advanced-ai/q14', 'true_false', 'evaluate', 'medium', 'Evaluate transfer of vision models across contexts', 'An object-detection model that performs well on international retail images can be deployed in Ghanaian supermarkets without local testing.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
