insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7ff70b70-628a-5ef0-aebc-158821083e95', '{"value":false}'::jsonb, 'Differences in packaging, lighting, shelf layout and products can reduce accuracy. Local evaluation and, often, fine-tuning on local images are needed before deployment.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('045f4447-85f0-55e3-ac22-3531a62d74dd', '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'csit-607/advanced-ai/q15', 'mcq', 'understand', 'medium', 'Explain how LLMs generate text', 'How does a decoder-style large language model produce a response?', null, null, '[{"id":"a","text":"It retrieves a stored answer from a database of facts"},{"id":"b","text":"It repeatedly predicts a probability distribution over the next token and selects one, appending it to the context"},{"id":"c","text":"It translates the question into logic and proves the answer"},{"id":"d","text":"It copies the most similar web page"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('045f4447-85f0-55e3-ac22-3531a62d74dd', '{"option":"b"}'::jsonb, 'LLMs are autoregressive; they generate one token at a time from learned probabilities. They do not have a built-in fact database or theorem prover, and while they can reproduce training text, generation is not page copying.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5321fcd1-8eab-5714-b46b-368f673fd31d', '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'csit-607/advanced-ai/q16', 'mcq', 'apply', 'hard', 'Compute softmax probabilities', 'Scores for three tokens are 2.0, 1.0 and 0.1. Using softmax at temperature 1, what is the probability of the first token, approximately?', null, null, '[{"id":"a","text":"0.66"},{"id":"b","text":"0.50"},{"id":"c","text":"0.86"},{"id":"d","text":"0.67 exactly, because 2 is two-thirds of the total score"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5321fcd1-8eab-5714-b46b-368f673fd31d', '{"option":"a"}'::jsonb, 'e^2.0 ≈ 7.389 and the sum of exponentials ≈ 11.212, so p ≈ 0.66. Dividing raw scores by their sum is not softmax; 0.86 is the result at temperature 0.5; and 0.50 is roughly the result at temperature 2.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('dd1bf626-f0f2-53fb-97cd-0f5de82a6143', '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'csit-607/advanced-ai/q17', 'true_false', 'understand', 'medium', 'Explain the effect of temperature', 'Lowering the temperature makes an LLM''s output more consistent because the most likely token receives a larger share of probability.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('dd1bf626-f0f2-53fb-97cd-0f5de82a6143', '{"value":true}'::jsonb, 'Dividing scores by a temperature below 1 widens the gaps between them before softmax, concentrating probability on the top token. Higher temperatures flatten the distribution and increase variety.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('abe26628-18de-5774-b0e0-638017ac15d6', '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'csit-607/advanced-ai/q18', 'short_answer', 'recall', 'easy', 'Name the grounding technique that supplies retrieved documents to an LLM', 'What is the name, or its abbreviation, of the technique that retrieves relevant passages from trusted documents and supplies them to an LLM as context?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('abe26628-18de-5774-b0e0-638017ac15d6', '{"answers":["retrieval-augmented generation","RAG","retrieval augmented generation"]}'::jsonb, 'Retrieval-augmented generation grounds answers in specific sources, ideally with citations, reducing but not eliminating hallucination.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f345e72e-e2c3-5bc9-abd5-0f8f69d75287', '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'csit-607/advanced-ai/q19', 'scenario', 'evaluate', 'hard', 'Evaluate controls for hallucination in professional use', 'Which response best addresses the risk?', 'Illustrative scenario. A law firm in Accra lets junior staff use a general-purpose chatbot to draft submissions. One draft contains case citations that partners cannot find in any law report.', null, '[{"id":"a","text":"Ban all AI tools permanently without further analysis"},{"id":"b","text":"Require verification of every citation against authoritative sources, use tools grounded in legal databases where possible, and keep professional accountability with the lawyer"},{"id":"c","text":"Increase the chatbot''s temperature to improve creativity"},{"id":"d","text":"Trust the citations because the chatbot sounded confident"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f345e72e-e2c3-5bc9-abd5-0f8f69d75287', '{"option":"b"}'::jsonb, 'As Mata v. Avianca showed, LLMs can fabricate realistic citations. Verification, grounding and clear accountability address the root causes. A blanket ban forgoes benefits without analysis, higher temperature increases randomness, and confident tone is not evidence of truth.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('05d64309-2f7f-5b92-a9af-b55d65d9c945', '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'csit-607/advanced-ai/q20', 'matching', 'understand', 'medium', 'Match generative AI concepts to descriptions', 'Match each concept to its description.', null, null, '{"left":[{"id":"l1","text":"Pre-training"},{"id":"l2","text":"Instruction tuning"},{"id":"l3","text":"RLHF"},{"id":"l4","text":"Context window"},{"id":"l5","text":"Diffusion model"}],"right":[{"id":"r2","text":"Fine-tuning on examples of instructions and good responses"},{"id":"r3","text":"Refining a model using human preference rankings as a reward signal"},{"id":"r4","text":"The maximum number of tokens a model can consider at once"},{"id":"r1","text":"Self-supervised next-token prediction over a very large text corpus"},{"id":"r5","text":"Generates images by learning to reverse a gradual noising process"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('05d64309-2f7f-5b92-a9af-b55d65d9c945', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'These stages and concepts explain both what LLMs can do and their limits, such as knowledge cut-offs and the amount of material that can be supplied in one request.', null)
