insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f87165f6-2c55-54f5-a9b1-815bc991d2d4', '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'csit-607/advanced-ai/q21', 'mcq', 'analyse', 'hard', 'Analyse the root cause of hallucination', 'Which statement best explains why LLMs hallucinate?', null, null, '[{"id":"a","text":"They are trained to produce plausible continuations of text rather than verified facts, and have no built-in mechanism for checking truth"},{"id":"b","text":"Their programmers insert false information deliberately"},{"id":"c","text":"Hallucination only happens when the internet connection fails"},{"id":"d","text":"They always copy incorrect web pages"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f87165f6-2c55-54f5-a9b1-815bc991d2d4', '{"option":"a"}'::jsonb, 'The training objective rewards plausibility. When knowledge is missing or the prompt pushes for an answer, a fluent fabrication may be the most probable continuation. Deliberate insertion, connectivity and simple copying do not explain the phenomenon.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('68850e33-7396-5315-aa53-d8394d2b748f', '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', null, 'csit-607/advanced-ai/q22', 'case_analysis', 'evaluate', 'hard', 'Evaluate a proposed generative AI deployment and design safeguards', 'Critically evaluate the proposal and recommend a design and deployment approach that balances value and risk.', null, 'Illustrative scenario. A large hospital in Accra plans a patient-facing chatbot built on a general-purpose LLM. It will answer questions about clinic opening hours, preparation for procedures, medication instructions and billing, in English and Twi, through WhatsApp. The project sponsor wants it live within six weeks and proposes using the model "as is", without connecting it to hospital documents, to save time.', null, 20, array['Explain how the LLM generates answers and why hallucination is likely without grounding', 'Distinguish lower-risk (opening hours, billing process) from higher-risk (medication) questions', 'Propose a RAG design over approved hospital documents with citations and refusal behaviour', 'Address Twi and code-switched language performance and evaluation', 'Address data protection, escalation to humans, monitoring and accountability']::text[], '[{"criterion":"Technical understanding","marks":5,"descriptor":"Accurately explains next-token generation, hallucination causes and the role of grounding"},{"criterion":"Risk analysis","marks":5,"descriptor":"Differentiates question types by risk and identifies patient-safety, language and privacy risks"},{"criterion":"Design recommendation","marks":6,"descriptor":"Coherent RAG design, scope limits, low temperature, refusal and human escalation, evaluation plan"},{"criterion":"Governance and realism","marks":4,"descriptor":"Addresses Act 843, accountability, monitoring and a realistic phased timeline"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('68850e33-7396-5315-aa53-d8394d2b748f', '{}'::jsonb, 'Examiners look for a technically correct explanation of hallucination, explicit risk tiering, a concrete grounded design and governance that reflects healthcare''s high stakes.', 'A strong answer begins by explaining that an ungrounded LLM generates the most plausible next tokens from training data. It does not know this hospital''s opening hours, prices or procedures, so it will produce confident but possibly fabricated answers. For medication instructions, a hallucination could directly harm patients.

The candidate should segment the scope. Opening hours, directions and billing processes are lower risk and well suited to a grounded assistant. Procedure preparation is moderate risk and should only be answered from approved clinical documents. Personalised medication advice is high risk and should be excluded, with the bot directing patients to a pharmacist or clinician.

The recommended design is retrieval-augmented generation over an approved, owned and regularly updated document set, with instructions to answer only from retrieved passages, cite them, decline when no source exists and use a low temperature. Twi and code-switched performance must be tested separately with native speakers, because LLM quality is often weaker for low-resource languages; human-reviewed Twi templates may be needed for critical content.

Patient messages are personal and often health-related, so processing must comply with the Data Protection Act, 2012 (Act 843), including clear notices, minimal data collection, secure handling and review of where the provider processes data. The bot should hand over to staff for complaints, emergencies and anything outside scope. A phased plan would launch a pilot on low-risk topics after evaluation on a test set of real questions, with monitoring of unanswered and escalated queries, rather than a six-week "as is" launch.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3cf72cb0-1a5b-51be-ab49-26260996f242', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '89c71563-3824-5343-8029-e45df7c8ece1', 'What does an artificial neuron compute?', 'An activation function applied to the weighted sum of its inputs plus a bias, output = f(Σ wi xi + b). With a sigmoid activation, a single neuron is equivalent to logistic regression.', 'supplementary', 'csit-607/advanced-ai/c800e15d3c6e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e24a27be-15b0-5bad-8296-9698c4a5490b', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '89c71563-3824-5343-8029-e45df7c8ece1', 'Why are non-linear activation functions essential?', 'Without them, stacked layers collapse into one linear model. Non-linearity lets networks learn complex functions and hierarchical representations.', 'supplementary', 'csit-607/advanced-ai/0a7c50506f34', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('991e3bc4-b7b3-57df-bea5-13cd6703d37a', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '89c71563-3824-5343-8029-e45df7c8ece1', 'What is the gradient-descent update rule?', 'New weight = old weight − learning rate × gradient. For a sigmoid neuron with log loss, the gradient for each weight is (output − true label) × input.', 'supplementary', 'csit-607/advanced-ai/b6d1a4953c7e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('aab98c90-6d60-53fb-af18-8e5074b1ffed', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '89c71563-3824-5343-8029-e45df7c8ece1', 'What does backpropagation contribute to training?', 'It applies the chain rule backwards through the layers to compute the gradient of the loss for every weight efficiently, so all layers can learn.', 'supplementary', 'csit-607/advanced-ai/cf5798d5e93c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d363605a-8907-54ab-974d-88cfd5561648', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '89c71563-3824-5343-8029-e45df7c8ece1', 'What three factors drove the deep learning resurgence around 2012?', 'Large labelled datasets such as ImageNet, GPU computing, and algorithmic advances such as ReLU, dropout and better initialisation.', 'supplementary', 'csit-607/advanced-ai/ca6546e78b24', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e2a0d303-971c-5baf-b9b4-bc4f5c5d8c9e', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '89c71563-3824-5343-8029-e45df7c8ece1', 'When is deep learning not the best choice for a business?', 'For structured tabular data, small datasets or decisions needing clear explanations, where gradient-boosted trees or logistic regression often perform as well at lower cost.', 'supplementary', 'csit-607/advanced-ai/9a5ddffba699', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f9d7aac5-279e-5d0b-b495-54eea43cdea7', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '538ff955-68b0-5300-be72-3daec28058fd', 'How does a convolution filter detect a pattern?', 'It slides across the image, multiplying its values with each window of pixels and summing them; high outputs mark where the pattern, such as a vertical edge, occurs.', 'supplementary', 'csit-607/advanced-ai/11d970849a94', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('acaf6eb3-fbeb-5df1-9d93-72cedac5be4e', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '538ff955-68b0-5300-be72-3daec28058fd', 'Distinguish image classification, object detection and segmentation.', 'Classification gives one label per image, detection locates and labels multiple objects with boxes, and segmentation labels every pixel to outline exact shapes.', 'supplementary', 'csit-607/advanced-ai/d571ebe42506', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('07cbb30d-2cc7-51b5-9fa6-ed7f2b93e4dc', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '538ff955-68b0-5300-be72-3daec28058fd', 'Why do modern NLP models use subword tokenisation?', 'It represents any word, including rare names, slang and misspellings, with a fixed vocabulary by splitting unfamiliar words into smaller known pieces.', 'supplementary', 'csit-607/advanced-ai/db600a12ed97', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f285b89e-6bc9-5706-988d-2f5ef6b65d83', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '538ff955-68b0-5300-be72-3daec28058fd', 'What is cosine similarity and why does it matter for business search?', '(a · b) / (|a| × |b|), measuring how closely two embeddings point in the same direction. It lets semantic search match "borrow money" with a loan FAQ without shared words.', 'supplementary', 'csit-607/advanced-ai/48fb311fcc20', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('11b1a19f-e6ce-561c-b43c-ab09bc5d25c3', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '538ff955-68b0-5300-be72-3daec28058fd', 'Why is NLP harder for Ghanaian customer messages?', 'Languages such as Twi, Ewe, Ga and Dagbani are low-resource and messages often mix them with English, so English-trained models misread them; local data and per-language evaluation are needed.', 'supplementary', 'csit-607/advanced-ai/572ff2a2c6bb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('85de864a-4421-5c19-9b81-5084e22e0bb8', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'What are the main steps of a transformer LLM generating text?', 'Tokenise, embed with positional information, pass through transformer blocks with self-attention and feed-forward layers, compute next-token probabilities by softmax, select a token, append and repeat.', 'supplementary', 'csit-607/advanced-ai/53ad2c45a2ce', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('55480274-ea01-5186-97f4-79c30f16b798', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'What do queries, keys and values do in self-attention?', 'Each token''s query is compared with other tokens'' keys to produce scores; softmax turns scores into weights; the token''s new representation is the weighted sum of values.', 'supplementary', 'csit-607/advanced-ai/99077f38ee06', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('80a22243-4b1d-5756-a2d7-c11fa3c17778', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'How does temperature change LLM output?', 'Scores are divided by the temperature before softmax. Low temperature concentrates probability on the top token, giving consistent output; high temperature flattens it, giving varied, less reliable output.', 'supplementary', 'csit-607/advanced-ai/01d928595583', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('90f7ef5b-6c79-5899-853b-e48e90ae909d', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'Why do LLMs hallucinate?', 'They are trained to produce plausible continuations, not verified facts, and lack a built-in truth check, so data gaps, cut-off dates and pressure to answer yield confident fabrications.', 'supplementary', 'csit-607/advanced-ai/b2fda171eac0', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('381dbbea-0901-5bb6-92b3-3ebd1e0f69bd', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'How does retrieval-augmented generation reduce hallucination, and what are its limits?', 'It retrieves trusted passages and instructs the model to answer from them with citations. Retrieval can still fetch the wrong passage and models can misread sources, so evaluation remains essential.', 'supplementary', 'csit-607/advanced-ai/d8e8f8a7342c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('29fa7a2b-5431-5965-a078-a8d334b446dd', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'fbfeb0c6-6f91-5f4b-af18-6431cd375dfc', '7c57d37e-cb02-5d6a-b2b7-49465f7fc2f0', 'What is the business lesson of Mata v. Avianca (2023)?', 'Lawyers were sanctioned after filing ChatGPT-generated citations to non-existent cases. Outputs relied upon must be verified against authoritative sources, and accountability stays with the professional.', 'supplementary', 'csit-607/advanced-ai/96f833aea31e', true)
