insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c8477ce2-207f-5fee-bff7-6e314c5e78de', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Traditional BI mainly covers descriptive and diagnostic analytics; predictive and prescriptive analytics use models to estimate outcomes and recommend actions. Each stage depends on trustworthy data from the earlier ones.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f63ab44d-eee9-5ee1-8a68-d65c86c6efba', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', 'b4e2f7a0-6b1c-5c65-b8c6-da5903e95b15', 'csit-607/ai-in-business/q02', 'mcq', 'apply', 'medium', 'Compute a moving-average forecast', 'Weekly sales are 140, 135 and 150 for the three most recent weeks. What is the three-week moving-average forecast for next week?', null, null, '[{"id":"a","text":"150.00"},{"id":"b","text":"141.67"},{"id":"c","text":"135.00"},{"id":"d","text":"425.00"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f63ab44d-eee9-5ee1-8a68-d65c86c6efba', '{"option":"b"}'::jsonb, '(140 + 135 + 150) / 3 = 425 / 3 ≈ 141.67. Using only the last value (150) is a naive forecast, 135 is one observation, and 425 is the unaveraged sum.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('78c78a61-1694-5bf2-b993-d68d6f80963b', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', 'b4e2f7a0-6b1c-5c65-b8c6-da5903e95b15', 'csit-607/ai-in-business/q03', 'short_answer', 'apply', 'hard', 'Apply simple exponential smoothing', 'With α = 0.3, last week''s forecast was 123.6 and last week''s actual sales were 140. What is the forecast for this week? Give two decimal places.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('78c78a61-1694-5bf2-b993-d68d6f80963b', '{"answers":["128.52"]}'::jsonb, 'F = 0.3 × 140 + 0.7 × 123.6 = 42 + 86.52 = 128.52. The latest actual is weighted by α and the previous forecast by 1 − α.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('64af9c34-6ab2-5c58-ad0f-57c953612f6a', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', 'b4e2f7a0-6b1c-5c65-b8c6-da5903e95b15', 'csit-607/ai-in-business/q04', 'true_false', 'understand', 'medium', 'Explain the limitation of simple smoothing methods with trends', 'Moving averages and simple exponential smoothing tend to under-forecast when demand is rising steadily.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
