insert into public.question_keys (question_id, correct, explanation, model_answer) values ('64af9c34-6ab2-5c58-ad0f-57c953612f6a', '{"value":true}'::jsonb, 'Both methods average past values, so their forecasts lag behind an upward trend. Methods with an explicit trend component, such as Holt''s method, address this.', null)
