insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6dbfbf35-97c2-5537-9d74-5a88b358cc7a', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', 'b4e2f7a0-6b1c-5c65-b8c6-da5903e95b15', 'csit-607/ai-in-business/q05', 'scenario', 'evaluate', 'hard', 'Evaluate the adoption of machine learning forecasting', 'What should the distributor do first?', 'Illustrative scenario. A Ghanaian pharmaceutical distributor''s sales data are spread across spreadsheets with inconsistent product codes. A vendor proposes a deep learning forecasting platform that will "eliminate stock-outs".', null, '[{"id":"a","text":"Buy the platform immediately because AI forecasts are always better"},{"id":"b","text":"Integrate and clean the data into a BI layer, establish baseline forecasts and error measures, then pilot advanced models against those benchmarks"},{"id":"c","text":"Stop forecasting and rely on intuition"},{"id":"d","text":"Use MAPE only for products that sell zero units"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6dbfbf35-97c2-5537-9d74-5a88b358cc7a', '{"option":"b"}'::jsonb, 'Reliable integrated data and simple benchmarks must come first; any advanced model should prove it beats them out of sample. Vendor claims to eliminate stock-outs are unrealistic, abandoning forecasting loses value, and MAPE is undefined for zero sales.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5167a69d-af9d-5bd0-ac64-9d56b6ffa594', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', 'b4e2f7a0-6b1c-5c65-b8c6-da5903e95b15', 'csit-607/ai-in-business/q06', 'mcq', 'analyse', 'medium', 'Analyse the role of event-specific drivers in forecasting', 'What is the main forecasting lesson from Walmart''s analysis of pre-hurricane purchases?', null, null, '[{"id":"a","text":"Weather never affects retail demand"},{"id":"b","text":"Event-specific drivers can cause demand changes, including unexpected products, that ordinary weekly forecasts miss"},{"id":"c","text":"Forecasting should only use the previous week''s sales"},{"id":"d","text":"Only perishable goods respond to events"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5167a69d-af9d-5bd0-ac64-9d56b6ffa594', '{"option":"b"}'::jsonb, 'Historical analysis showed demand rising for items such as strawberry Pop-Tarts as well as emergency supplies. Including event drivers, such as festive seasons or school terms in Ghana, improves forecasts. The other options contradict the case.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('540b3832-00fd-5d37-8dc2-1b545c462dd1', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'csit-607/ai-in-business/q07', 'mcq', 'apply', 'medium', 'Apply RFM scoring', 'Among five customers, C4 bought 90 days ago, made 1 purchase and spent the least. What RFM code should C4 receive on a 1-5 scale where 5 is best?', null, null, '[{"id":"a","text":"555"},{"id":"b","text":"111"},{"id":"c","text":"511"},{"id":"d","text":"151"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('540b3832-00fd-5d37-8dc2-1b545c462dd1', '{"option":"b"}'::jsonb, 'C4 is the least recent, least frequent and lowest-spending customer, so it scores 1 on each dimension. A score of 5 for recency would wrongly reward a long gap since the last purchase.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e12be0c0-2e94-5c0e-85bf-bac44331042d', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'csit-607/ai-in-business/q08', 'short_answer', 'apply', 'medium', 'Compute a z-score anomaly measure', 'A customer''s transfers have mean GHS 150 and standard deviation GHS 50. What is the z-score of a new GHS 900 transfer?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e12be0c0-2e94-5c0e-85bf-bac44331042d', '{"answers":["15","15.0"]}'::jsonb, 'z = (900 − 150) / 50 = 15, far outside normal variation for this customer. It is a signal for verification, not proof of fraud.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4e11b65c-0137-54d3-b1ec-f7926aab2289', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'csit-607/ai-in-business/q09', 'true_false', 'understand', 'medium', 'Explain correct use of resampling', 'Oversampling the fraud class should be applied to the whole dataset before splitting into training and test sets.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4e11b65c-0137-54d3-b1ec-f7926aab2289', '{"value":false}'::jsonb, 'Resampling before splitting lets copies or synthetic versions of test cases appear in training, leaking information and inflating results. Resampling must be applied to the training data only.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ed24cf54-9980-578c-81c9-7ec069106d6c', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'csit-607/ai-in-business/q10', 'scenario', 'analyse', 'hard', 'Analyse retention targeting using propensity and uplift', 'What would most improve the programme?', 'Illustrative scenario. A bank sends fee waivers to all customers its model predicts are likely to churn. Churn among them falls slightly, but costs rise sharply. A test later shows many recipients would have stayed anyway.', null, '[{"id":"a","text":"Send waivers to every customer"},{"id":"b","text":"Target customers who are both likely to churn and likely to respond to the offer, identified through controlled testing"},{"id":"c","text":"Stop measuring churn"},{"id":"d","text":"Use accuracy as the only evaluation metric"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ed24cf54-9980-578c-81c9-7ec069106d6c', '{"option":"b"}'::jsonb, 'Predicting churn is not the same as preventing it. Uplift-oriented targeting, learned from control groups, focuses spending where the intervention changes behaviour. Blanket offers waste money, and abandoning measurement or relying on accuracy hides the problem.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1d6b9a2d-ef1d-58e3-b93b-0d6c274be2aa', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'csit-607/ai-in-business/q11', 'matching', 'understand', 'medium', 'Match fraud detection approaches to characteristics', 'Match each fraud detection approach to its characteristic.', null, null, '{"left":[{"id":"l1","text":"Expert rules"},{"id":"l2","text":"Supervised classifier"},{"id":"l3","text":"Anomaly detection"},{"id":"l4","text":"Graph analysis"}],"right":[{"id":"r4","text":"Links accounts, devices and numbers to uncover mule networks"},{"id":"r1","text":"Transparent and quick to deploy, but fraudsters learn to evade them"},{"id":"r2","text":"Learns complex patterns from labelled history, but labels are delayed and incomplete"},{"id":"r3","text":"Flags unusual behaviour without labels, helping to catch new schemes"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1d6b9a2d-ef1d-58e3-b93b-0d6c274be2aa', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Mature systems layer these approaches because each covers weaknesses of the others in an adversarial, imbalanced environment.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e483dc32-0ed7-5ac4-b422-fe149f35ab72', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'csit-607/ai-in-business/q12', 'mcq', 'evaluate', 'hard', 'Evaluate the ethical lesson of the Target case', 'What is the main lesson of the Target pregnancy-prediction case for customer analytics?', null, null, '[{"id":"a","text":"Retail purchase data contain no useful information"},{"id":"b","text":"Accurate inference of sensitive characteristics can itself be intrusive and harmful, so organisations must set limits on acceptable inferences"},{"id":"c","text":"Models should always be made less accurate"},{"id":"d","text":"Personalised marketing is illegal in all countries"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e483dc32-0ed7-5ac4-b422-fe149f35ab72', '{"option":"b"}'::jsonb, 'The case shows that a correct prediction about something sensitive can breach customer expectations of privacy. The response is governance over which inferences are made and how they are used, not deliberately poor models or blanket claims about legality.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('57c25676-88d5-5a5f-813e-7c261a79c48c', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '2d74d50e-3acd-5983-927c-a942b46e4dd7', 'csit-607/ai-in-business/q13', 'mcq', 'apply', 'medium', 'Compute containment and resolution', 'A chatbot handled 10,000 conversations, 6,000 without transfer, and 900 of those customers re-contacted within 48 hours about the same issue. What is the verified resolution rate by the bot?', null, null, '[{"id":"a","text":"60%"},{"id":"b","text":"51%"},{"id":"c","text":"69%"},{"id":"d","text":"9%"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('57c25676-88d5-5a5f-813e-7c261a79c48c', '{"option":"b"}'::jsonb, 'Resolution = (6,000 − 900) / 10,000 = 51%. 60% is containment, which ignores repeat contacts; 69% wrongly adds the repeats; 9% is the repeat-contact proportion.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2c8e11a5-5e43-5f3a-8143-deaefbcfb88a', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '2d74d50e-3acd-5983-927c-a942b46e4dd7', 'csit-607/ai-in-business/q14', 'scenario', 'apply', 'medium', 'Apply escalation rules', 'What should the system do?', 'Illustrative scenario. A customer writes to a mobile money chatbot that someone phoned pretending to be staff and the customer shared their PIN. The intent classifier returns "fraud report" with confidence 0.88.', null, '[{"id":"a","text":"Answer automatically with a generic FAQ because confidence exceeds 0.80"},{"id":"b","text":"Escalate immediately to the fraud team with conversation context and guide the customer through urgent security steps"},{"id":"c","text":"Ask the customer to try again tomorrow"},{"id":"d","text":"Close the conversation because the customer made the mistake"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2c8e11a5-5e43-5f3a-8143-deaefbcfb88a', '{"option":"b"}'::jsonb, 'Fraud and PIN compromise are sensitive topics that should always trigger human escalation regardless of confidence, with context passed on and immediate protective guidance. The other options increase harm and liability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('729ff698-01ee-5c3b-aa3c-b729dba42236', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '2d74d50e-3acd-5983-927c-a942b46e4dd7', 'csit-607/ai-in-business/q15', 'true_false', 'understand', 'easy', 'Explain organisational accountability for chatbots', 'In Moffatt v. Air Canada (2024), the tribunal accepted the airline''s argument that it was not responsible for information given by its chatbot.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('729ff698-01ee-5c3b-aa3c-b729dba42236', '{"value":false}'::jsonb, 'The tribunal rejected that argument, holding the airline responsible for all information on its website, including the chatbot''s, and ordered compensation. Organisations should treat bot answers as their own statements.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ab8347ed-7c18-5b50-8313-8d63f1c303c5', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '2d74d50e-3acd-5983-927c-a942b46e4dd7', 'csit-607/ai-in-business/q16', 'short_answer', 'recall', 'medium', 'Recall Simon''s decision-making phases', 'Simon''s model describes decision-making as intelligence, design and which third phase?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ab8347ed-7c18-5b50-8313-8d63f1c303c5', '{"answers":["choice","the choice phase"]}'::jsonb, 'Intelligence identifies the problem, design develops alternatives and choice selects among them. AI can support each phase, from anomaly alerts to optimisation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9a9a2118-8843-5c05-a8d6-e999ab949c49', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '2d74d50e-3acd-5983-927c-a942b46e4dd7', 'csit-607/ai-in-business/q17', 'mcq', 'apply', 'hard', 'Compute expected value in a payoff table', 'An order option yields GHS 2,750 with probability 0.3, GHS 6,000 with probability 0.5 and GHS 6,000 with probability 0.2. What is its expected value?', null, null, '[{"id":"a","text":"GHS 4,916"},{"id":"b","text":"GHS 5,025"},{"id":"c","text":"GHS 6,000"},{"id":"d","text":"GHS 14,750"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9a9a2118-8843-5c05-a8d6-e999ab949c49', '{"option":"b"}'::jsonb, '0.3 × 2,750 + 0.5 × 6,000 + 0.2 × 6,000 = 825 + 3,000 + 1,200 = 5,025. A simple unweighted mean gives about 4,917, the best-case payoff is 6,000, and 14,750 is the unweighted sum.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1a07c5e6-0baf-5707-9e1b-3c8b50d92071', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '2d74d50e-3acd-5983-927c-a942b46e4dd7', 'csit-607/ai-in-business/q18', 'scenario', 'evaluate', 'hard', 'Evaluate DSS design against automation bias', 'Which design change best addresses this?', 'Illustrative scenario. Loan officers at a savings and loans company approve almost every application the DSS marks "recommended", including some with obvious documentation problems.', null, '[{"id":"a","text":"Hide the recommendation entirely and remove the DSS"},{"id":"b","text":"Show the key factors and uncertainty behind each recommendation, require officers to record reasons for decisions, and audit agreement patterns"},{"id":"c","text":"Make the recommendation appear in larger font"},{"id":"d","text":"Automate approvals fully so officers are not involved"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1a07c5e6-0baf-5707-9e1b-3c8b50d92071', '{"option":"b"}'::jsonb, 'This is automation bias. Explanations, uncertainty display, recorded reasoning and audits encourage critical engagement while retaining the DSS''s value. Removing the DSS loses benefits, emphasis worsens over-reliance, and full automation removes the human safeguard.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('985986c5-9941-5d8c-b8d6-f4763230a28d', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', null, 'csit-607/ai-in-business/q19', 'case_analysis', 'evaluate', 'hard', 'Design an integrated AI-enabled customer and operations strategy', 'Critically evaluate and prioritise AI applications for this chain across forecasting, customer analytics, fraud detection and customer support, recommending a phased roadmap with appropriate methods, metrics and safeguards.', null, 'Illustrative scenario. A supermarket chain with twelve branches in Accra, Kumasi and Takoradi has a loyalty programme, point-of-sale data for four years and a growing mobile money payment channel. Managers report frequent stock-outs of staples before festive periods, high waste of fresh produce, rising complaints about long call-centre waits, and a small number of suspicious refunds processed at tills. The board asks for an AI roadmap for the next eighteen months.', null, 25, array['Diagnose the data foundation and BI needs before advanced AI', 'Propose demand forecasting with benchmarks, festive drivers and an expected-value ordering DSS', 'Propose RFM segmentation and retention targeting with privacy limits', 'Propose refund-fraud analytics handling imbalance and investigator feedback', 'Propose support automation with escalation and balanced metrics', 'Prioritise into phases with KPIs, risks and governance including Act 843']::text[], '[{"criterion":"Data and BI foundation","marks":4,"descriptor":"Recognises integration, data quality and dashboards as prerequisites"},{"criterion":"Forecasting and decision support","marks":6,"descriptor":"Appropriate methods, benchmarks, event drivers, error metrics and link to ordering decisions"},{"criterion":"Customer analytics and fraud","marks":6,"descriptor":"Correct use of RFM/CLV and anomaly or supervised fraud methods with imbalance handling and ethics"},{"criterion":"Support automation","marks":4,"descriptor":"Suitable chatbot architecture, escalation and resolution-based metrics"},{"criterion":"Prioritisation and governance","marks":5,"descriptor":"Justified phasing, measurable KPIs, risks, accountability and data protection"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('985986c5-9941-5d8c-b8d6-f4763230a28d', '{}'::jsonb, 'Examiners reward prioritisation grounded in business value and data readiness, correct method choices with matching metrics, and explicit safeguards rather than a list of fashionable tools.', 'A strong answer begins with the data foundation. Four years of POS and loyalty data are valuable only if product codes, branches and customer identifiers are integrated in a warehouse with reliable dashboards for stock-outs, waste and refunds. This should be phase one, because it also yields quick descriptive wins.

Forecasting is the highest-value application, as stock-outs and waste are direct costs. The chain should forecast at product-branch-week level, start with seasonal exponential smoothing benchmarks, then pilot gradient-boosted models including festive periods, paydays, school terms and promotions. Evaluation should use MAE or RMSE on held-out festive seasons. Forecasts should feed an ordering DSS using expected-value or newsvendor-style logic, especially for perishables where unsold stock is costly, with buyers able to adjust for local knowledge.

Customer analytics via RFM gives transparent segments for promotions; CLV helps decide retention spending; controlled tests should show which offers change behaviour. Limits on sensitive inferences, consent and purpose specification are required under the Data Protection Act, 2012 (Act 843).

Refund fraud is rare and adversarial. Rules (for example, refunds without matching sales), anomaly scores by cashier and till, and later a supervised model trained on investigated cases are appropriate, with precision and recall rather than accuracy and with investigator outcomes fed back as labels. Staff fairness and due process matter.

For support, a WhatsApp bot handling store hours, stock queries and loyalty balances via APIs, with a grounded knowledge base, clear human escalation and resolution-based metrics, would reduce waits.

A phased roadmap might be: months 0-6 data and BI plus a forecasting pilot; months 6-12 ordering DSS, RFM and refund rules; months 12-18 support automation and supervised fraud models, each with KPIs, owners and review.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('72ffc09b-9f4e-5f62-a8d8-4e62681de462', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'csit-607/ai-in-business/q20', 'mcq', 'understand', 'easy', 'Distinguish content-based from collaborative filtering', 'What is the key difference between content-based and collaborative filtering?', null, null, '[{"id":"a","text":"Content-based filtering uses item attributes, whereas collaborative filtering uses patterns in other users'' behaviour"},{"id":"b","text":"Content-based filtering needs ratings, whereas collaborative filtering needs only item prices"},{"id":"c","text":"Content-based filtering works only offline, whereas collaborative filtering works only online"},{"id":"d","text":"Content-based filtering recommends random items, whereas collaborative filtering ranks them"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('72ffc09b-9f4e-5f62-a8d8-4e62681de462', '{"option":"a"}'::jsonb, 'Content-based methods match item attributes to a user''s profile, so they can recommend new items immediately. Collaborative methods need no attributes but rely on interaction data from many users. The other options invent differences that do not exist.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8592bfe1-f94e-5fa5-88fc-c1eee94ccfe6', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'csit-607/ai-in-business/q21', 'scenario', 'apply', 'medium', 'Compute precision@k and recall@k', 'What are precision@10 and recall@10 for this customer?', 'A shop''s recommender shows a customer 10 products. The customer later buys 3 of them. Across the whole catalogue, the customer is known to have 6 products that would count as relevant.', null, '[{"id":"a","text":"Precision 0.30 and recall 0.50"},{"id":"b","text":"Precision 0.50 and recall 0.30"},{"id":"c","text":"Precision 0.30 and recall 0.30"},{"id":"d","text":"Precision 0.60 and recall 0.10"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8592bfe1-f94e-5fa5-88fc-c1eee94ccfe6', '{"option":"a"}'::jsonb, 'Precision@k divides the relevant items in the list by k, giving 3 / 10 = 0.30. Recall@k divides them by all relevant items, giving 3 / 6 = 0.50. Swapping the denominators produces the second option, a common examination error.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f9d269b8-1b93-5d6f-bf01-6c05a296e6f8', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'csit-607/ai-in-business/q22', 'true_false', 'understand', 'medium', 'Recognise the limits of offline evaluation', 'A recommender that scores best on offline accuracy will always produce the highest conversion in a live A/B test.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f9d269b8-1b93-5d6f-bf01-6c05a296e6f8', '{"value":false}'::jsonb, 'Offline metrics judge a model against past behaviour that was shaped by the earlier system and cannot show how recommendations change behaviour. Only a randomised online test measures business impact, and Netflix did not deploy its Prize-winning ensemble in full for related reasons.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2334d53f-d57d-5403-a8c7-bbc36d7fa4d8', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'csit-607/ai-in-business/q23', 'short_answer', 'recall', 'easy', 'Name the new-user and new-item data problem', 'What term describes the difficulty of recommending for a brand-new user or item with no interaction history?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2334d53f-d57d-5403-a8c7-bbc36d7fa4d8', '{"answers":["cold start","the cold start problem","cold-start"]}'::jsonb, 'Cold start arises because collaborative methods depend on past interactions. Mitigations include onboarding questions, content-based rules and popularity fallbacks.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3cc39fac-9f5a-5b80-aa2b-4f1413a324eb', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'csit-607/ai-in-business/q24', 'mcq', 'apply', 'hard', 'Predict a rating from neighbour similarities', 'Two neighbours have cosine similarities of 0.9 and 0.3 with a target user. They rated an unseen item 5 and 1 respectively. What is the similarity-weighted predicted rating?', null, null, '[{"id":"a","text":"3.00"},{"id":"b","text":"4.00"},{"id":"c","text":"4.50"},{"id":"d","text":"6.00"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3cc39fac-9f5a-5b80-aa2b-4f1413a324eb', '{"option":"b"}'::jsonb, 'The weighted average is (0.9 x 5 + 0.3 x 1) / (0.9 + 0.3) = 4.8 / 1.2 = 4.00. A simple average gives 3.00, which ignores that the first neighbour is far more similar. 4.50 and 6.00 come from no correct calculation, and a predicted rating cannot exceed the 5-point scale.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('07fd7e1a-d433-5e7f-8534-1822bf4a35bf', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'csit-607/ai-in-business/q25', 'matching', 'understand', 'medium', 'Match recommendation problems to mitigations', 'Match each problem to the most suitable mitigation.', null, null, '{"left":[{"id":"l1","text":"New user with no history"},{"id":"l2","text":"Popularity bias starving niche items"},{"id":"l3","text":"Offline accuracy that may not reflect business value"},{"id":"l4","text":"Sparse user-item matrix"}],"right":[{"id":"r2","text":"Managed exposure and diversity objectives"},{"id":"r1","text":"Onboarding questions and popularity fallback"},{"id":"r3","text":"Randomised A/B test with guardrail metrics"},{"id":"r4","text":"Matrix factorisation with implicit feedback"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('07fd7e1a-d433-5e7f-8534-1822bf4a35bf', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each mitigation targets the specific cause. Onboarding gives early data, diversity objectives counter rich-get-richer exposure, A/B tests measure real behaviour change, and factorisation pools information to handle sparsity.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bb62d762-33f3-5243-81b8-5203f435b31a', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'csit-607/ai-in-business/q26', 'scenario', 'evaluate', 'hard', 'Evaluate a recommender design for a small retailer', 'Which first step is most sensible?', 'A small Kumasi retailer has two thousand products, few registered customers and many guest checkouts. It wants its first recommender within a month.', null, '[{"id":"a","text":"Train a deep personalised collaborative model on the few registered users"},{"id":"b","text":"Build a \"frequently bought together\" item-based rule from past baskets and add attribute-based similar items for new stock"},{"id":"c","text":"Wait until every customer has registered before recommending anything"},{"id":"d","text":"Copy a global competitor''s recommendations without testing"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bb62d762-33f3-5243-81b8-5203f435b31a', '{"option":"b"}'::jsonb, 'Item-based co-purchase rules work from basket data without registration, and attribute-based similarity handles new items. A personalised collaborative model would be starved of data, waiting delays value, and untested copying ignores local customers. Each stage should be A/B tested.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8c4db428-1220-51f4-839d-9f635b30aa63', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'csit-607/ai-in-business/q27', 'mcq', 'understand', 'easy', 'Identify a common cause of AI project failure', 'Which statement best explains why many AI pilots never reach production?', null, null, '[{"id":"a","text":"Pilots usually use too much real data"},{"id":"b","text":"Pilots are often built to impress with curated data and no integration, so operational conditions are never tested"},{"id":"c","text":"Production systems never need monitoring"},{"id":"d","text":"Models cannot be deployed outside a laboratory"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8c4db428-1220-51f4-839d-9f635b30aa63', '{"option":"b"}'::jsonb, 'Pilot purgatory arises when pilots avoid the integration, ownership and monitoring challenges of real operation. The other options are false, because using real data helps, production needs monitoring, and models are routinely deployed.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('dad4290c-90b4-5f97-b834-2500099b626c', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'csit-607/ai-in-business/q28', 'scenario', 'apply', 'medium', 'Apply weighted value-feasibility scoring', 'Which project ranks higher, and with what scores?', 'A company weights value at 0.6 and feasibility at 0.4. Project X scores value 5 and feasibility 2. Project Y scores value 4 and feasibility 4.', null, '[{"id":"a","text":"X with 3.8 against Y with 4.0, so Y ranks higher"},{"id":"b","text":"X with 4.4 against Y with 4.0, so X ranks higher"},{"id":"c","text":"X with 3.8 against Y with 3.6, so X ranks higher"},{"id":"d","text":"Both score 4.0, so they tie"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('dad4290c-90b4-5f97-b834-2500099b626c', '{"option":"a"}'::jsonb, 'X = (0.6 x 5) + (0.4 x 2) = 3.0 + 0.8 = 3.8. Y = (0.6 x 4) + (0.4 x 4) = 2.4 + 1.6 = 4.0. The balanced project wins even though X has higher value, because X''s low feasibility drags its score down. The weights are a leadership choice and should be stated explicitly.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9a683a4c-c542-5cbd-bd52-8e4f80bfccb9', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'csit-607/ai-in-business/q29', 'true_false', 'understand', 'medium', 'Recognise the role of change management', 'Once a model has been deployed and tested for accuracy, user adoption can be assumed.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9a683a4c-c542-5cbd-bd52-8e4f80bfccb9', '{"value":false}'::jsonb, 'Technical accuracy does not guarantee use. Staff may distrust, ignore or work around the tool, so involvement in design, training, incentives and feedback channels are needed. Value is realised only when decisions and behaviour change.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6a71302a-d0e7-525e-8202-b604fd3d7079', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'csit-607/ai-in-business/q30', 'short_answer', 'recall', 'easy', 'Name practices for production machine learning', 'What abbreviation names the practices for deploying, monitoring and retraining machine learning models in production?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6a71302a-d0e7-525e-8202-b604fd3d7079', '{"answers":["MLOps","ML Ops","machine learning operations"]}'::jsonb, 'MLOps applies software operations discipline to models, including versioning, automated deployment, monitoring of drift and fairness, retraining triggers and rollback.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6cee67dd-f387-5ac3-b478-21fbca0f0fcd', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'csit-607/ai-in-business/q31', 'mcq', 'apply', 'hard', 'Calculate ROI over a fixed period', 'A project costs GH₵200,000 to build and GH₵50,000 a year to run, and yields GH₵150,000 of benefit a year. Over three years, what is the ROI?', null, null, '[{"id":"a","text":"10.0 percent"},{"id":"b","text":"28.6 percent"},{"id":"c","text":"42.9 percent"},{"id":"d","text":"75.0 percent"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6cee67dd-f387-5ac3-b478-21fbca0f0fcd', '{"option":"b"}'::jsonb, 'Total cost = 200,000 + 3 x 50,000 = 350,000. Total benefit = 3 x 150,000 = 450,000. Net benefit = 100,000, so ROI = 100,000 / 350,000 = 28.6 percent. The 42.9 percent figure would come from dividing the annual benefit by total cost, ignoring the three-year horizon.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('cae7028f-19ab-523a-8281-74b07aa9b0f9', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'csit-607/ai-in-business/q32', 'matching', 'understand', 'medium', 'Match sourcing options to their typical fit', 'Match each sourcing option to the situation in which it is most suitable.', null, null, '{"left":[{"id":"l1","text":"Build in-house"},{"id":"l2","text":"Buy a product or API"},{"id":"l3","text":"Partner or co-develop"}],"right":[{"id":"r2","text":"Generic need such as speech or translation, needed quickly"},{"id":"r3","text":"Domain data exist but internal skills are limited"},{"id":"r1","text":"Capability is a source of competitive advantage using proprietary data"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('cae7028f-19ab-523a-8281-74b07aa9b0f9', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'Build gives control at higher cost and skill demand, buy gives speed with lock-in risk, and partnering transfers know-how while sharing risk.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4a68d676-3785-557a-a992-3c85eace8f10', '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'csit-607/ai-in-business/q33', 'scenario', 'analyse', 'medium', 'Diagnose readiness gaps before choosing a project', 'What is the most appropriate advice?', 'A rural bank keeps loan histories on paper in half its branches. Its board wants an AI credit-scoring model within six months.', null, '[{"id":"a","text":"Build the scoring model now and fix the data later"},{"id":"b","text":"Digitise and govern the loan data first, buy a commodity intake tool, and pilot a simple pre-screening model with officers retaining authority"},{"id":"c","text":"Cancel all AI work permanently"},{"id":"d","text":"Outsource the lending decision entirely to a vendor"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4a68d676-3785-557a-a992-3c85eace8f10', '{"option":"b"}'::jsonb, 'Data readiness is the binding constraint, so enabling investment and a low-risk pilot with human oversight come first. Building on missing data would give an unreliable model, cancelling ignores achievable value, and outsourcing the decision removes accountability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('49e25bd7-97ee-59e5-abc3-ce03e4411d04', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', 'b4e2f7a0-6b1c-5c65-b8c6-da5903e95b15', 'How does business intelligence differ from predictive analytics?', 'BI integrates and presents historical and current data to show what happened and why; predictive analytics uses models to estimate what is likely to happen, with uncertainty.', 'supplementary', 'csit-607/ai-in-business/f7817395e4b2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('974a42b7-3ee5-5393-aac6-38b3670064ef', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', 'b4e2f7a0-6b1c-5c65-b8c6-da5903e95b15', 'What are the main layers of a BI architecture?', 'Source systems, ETL or ELT pipelines, a data warehouse or lakehouse, and a presentation layer of dashboards and reports, all governed by data definitions, ownership and quality controls.', 'supplementary', 'csit-607/ai-in-business/4f1bab68c64c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0507c388-c2c0-5845-86ae-30b7d48db962', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', 'b4e2f7a0-6b1c-5c65-b8c6-da5903e95b15', 'State the simple exponential smoothing formula and the effect of alpha.', 'F(t+1) = α × A(t) + (1 − α) × F(t). High α reacts quickly but follows noise; low α is smoother but slower to respond.', 'supplementary', 'csit-607/ai-in-business/f21bd1d482e7', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('7393d16e-04a0-5cff-a6e4-141a41d53839', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', 'b4e2f7a0-6b1c-5c65-b8c6-da5903e95b15', 'Why should advanced forecasting models be compared with simple benchmarks?', 'Simple methods are often competitive, especially with short or noisy data; a complex model is only justified if it beats them on the same held-out periods.', 'supplementary', 'csit-607/ai-in-business/e23cc7d707e2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b421565d-550b-5ea7-9f50-bc806b8108ce', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', 'b4e2f7a0-6b1c-5c65-b8c6-da5903e95b15', 'Why is MAPE problematic for slow-moving products?', 'It divides by actual values, so it is undefined when sales are zero and is inflated by small denominators; MAE or scaled measures are often better.', 'supplementary', 'csit-607/ai-in-business/c98f8d3eff21', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('7f8c1452-c1cc-5ecf-8f25-be98a4f125a8', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'What do the letters in RFM stand for and how is recency scored?', 'Recency, frequency and monetary value. Recency scores highest for customers who purchased most recently, that is, the fewest days ago.', 'supplementary', 'csit-607/ai-in-business/b5b19a68c0dc', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d15b81bf-fed6-56ac-ab0e-5909e1d18144', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'Why is predicting churn not enough to reduce it?', 'Some predicted churners will not respond to an offer and some would stay anyway; uplift-oriented targeting tested with control groups directs spending where it changes behaviour.', 'supplementary', 'csit-607/ai-in-business/ee8c87b6174c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('7d932812-7a07-58e5-b2a3-6b6b6e81fb04', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'Why do fraud systems combine rules, supervised models and anomaly detection?', 'Rules are transparent but evadable, supervised models need delayed and incomplete labels, and anomaly detection catches new schemes; layering covers each method''s weaknesses.', 'supplementary', 'csit-607/ai-in-business/d0dcd946bf36', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d591efac-4e30-5ded-871c-a130ca14abc8', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'How should class imbalance be handled in fraud modelling?', 'Resample or weight the training data only, choose a cost-sensitive threshold on validation data, and evaluate with precision, recall and PR-AUC rather than accuracy.', 'supplementary', 'csit-607/ai-in-business/9c2a16aa047d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('87421dd6-bda4-5134-b2f1-da9dea7e15d6', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'Why does fraud detection suffer from concept drift?', 'Fraudsters adapt to controls, changing the relationship between features and fraud, so models must be monitored, retrained and fed investigator outcomes.', 'supplementary', 'csit-607/ai-in-business/bd55a9eb7450', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d9670332-cf9d-5cb8-8892-b7f0c0329808', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '07309d87-febc-51f0-a31d-700d24724ca4', 'What ethical lesson does the Target pregnancy-prediction case teach?', 'Accurately inferring sensitive traits from ordinary data can feel intrusive and cause harm, so organisations must decide in advance which inferences are acceptable.', 'supplementary', 'csit-607/ai-in-business/f56a10571a7e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6d0349d7-b63c-588d-8cc1-26c4f304f528', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '2d74d50e-3acd-5983-927c-a942b46e4dd7', 'Why can containment rate be misleading?', 'A bot can keep customers from reaching humans without solving their problems. Resolution, verified by absence of repeat contact, and satisfaction must also be measured.', 'supplementary', 'csit-607/ai-in-business/b91dddc10f63', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e57f594e-b560-5293-9fc9-2f765163f03c', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '2d74d50e-3acd-5983-927c-a942b46e4dd7', 'When should a support chatbot escalate to a human?', 'When intent confidence is low, the customer repeats themselves or shows frustration, or the topic is sensitive such as fraud, PIN compromise, bereavement or health, always passing conversation context.', 'supplementary', 'csit-607/ai-in-business/fd020e3341c3', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3c0e082d-bf31-59ea-bd53-7d85bbfdeac4', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '2d74d50e-3acd-5983-927c-a942b46e4dd7', 'What did Moffatt v. Air Canada (2024) establish for chatbot deployers?', 'The tribunal held the airline responsible for incorrect bereavement-fare information from its website chatbot, rejecting the argument that the bot was separately responsible.', 'supplementary', 'csit-607/ai-in-business/a3e10927d8ab', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bd38aeb5-3317-5399-a6c3-b8515ccc773c', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '2d74d50e-3acd-5983-927c-a942b46e4dd7', 'What are the three components of a decision support system?', 'Data management, model management (forecasts, optimisation, simulation, ML predictions) and a user interface, supporting semi-structured decisions.', 'supplementary', 'csit-607/ai-in-business/9982383b28a9', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('46031c83-1c8a-5092-86af-cb3ed8086ed7', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '2d74d50e-3acd-5983-927c-a942b46e4dd7', 'What is automation bias and how can a DSS reduce it?', 'Over-reliance on system recommendations even when wrong. Showing key factors and uncertainty, requiring recorded reasons and auditing agreement rates encourage critical use.', 'supplementary', 'csit-607/ai-in-business/fa56b5a7ee39', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b403f21b-1f93-5252-9e67-b52928d8cd92', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'How does item-based collaborative filtering differ from user-based, and why is it often easier to scale?', 'It recommends items similar to those the user liked, where similarity comes from shared audiences, instead of finding similar users. Item similarities change slowly and can be precomputed offline, so serving is fast.', 'supplementary', 'csit-607/ai-in-business/03ba6d77ebbb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5660caf5-78a3-552f-b7b1-ad8b88ad0a34', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'Explain the intuition of matrix factorisation in one sentence.', 'Each user and item is described by a short vector of learned latent factors, and the predicted rating is their dot product, which compresses a sparse matrix into patterns that generalise.', 'supplementary', 'csit-607/ai-in-business/d2a28a88936a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('903f7bef-b633-5ef9-9443-b4cb09f9100f', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'What are the three forms of the cold-start problem and one mitigation for each?', 'New user (onboarding questions), new item (content-based similarity or managed exposure) and new system (popularity rules and data collection until interactions accumulate).', 'supplementary', 'csit-607/ai-in-business/a3e51db1aea4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('558367e0-9edd-5ae5-af3d-3c0248f4e61b', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'Define precision@k and recall@k, and say how each changes as k increases.', 'Precision@k is relevant items in the top k divided by k; recall@k is relevant items in the top k divided by all relevant items. Raising k usually lowers precision and raises recall.', 'supplementary', 'csit-607/ai-in-business/f7254ac3a25e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('439b9b48-a29c-5e96-ba48-3fbca1a03625', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'Why must a recommender be validated with an A/B test and not offline metrics alone?', 'Offline data reflect past behaviour shaped by the old system and cannot show whether recommendations change behaviour. A randomised test measures real business impact with guardrail metrics.', 'supplementary', 'csit-607/ai-in-business/867b0e0a9044', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1fe6b229-354c-51e3-950d-946e0eb12422', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '58ecb665-82fb-5575-9f7a-ce5701bec224', 'Name three risks of personalisation and one mitigation for each.', 'Filter bubbles (diversity objectives and user controls), unfair exposure for providers (exposure budgets and fairness audits) and privacy harm (minimisation, transparency and compliance with Act 843).', 'supplementary', 'csit-607/ai-in-business/f6455caaa164', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d27e22f8-124c-5abf-9792-65d568d8742f', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'List the main barriers to AI adoption in organisations.', 'Data quality and access, skills, total cost, culture and leadership, legacy system integration, trust and explainability, and regulation such as Ghana''s Data Protection Act, 2012 (Act 843).', 'supplementary', 'csit-607/ai-in-business/e2731e01f3df', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5acf73cd-d114-5182-bcc0-a27c125adf82', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'How do you prioritise AI use cases using value and feasibility?', 'Score each use case on value and on feasibility, weight and combine the scores, and plot them. High value and high feasibility are quick wins; high value and low feasibility are strategic bets needing enabling investment.', 'supplementary', 'csit-607/ai-in-business/da9be17ce65e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8d9352f6-6e36-5692-a450-11ca7816b4d7', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'When is build, buy or partner the best sourcing choice?', 'Build when the capability is a differentiator using proprietary data; buy for generic, commodity needs where speed matters; partner when domain data exist but skills are limited. Consider total cost, lock-in and exit plans.', 'supplementary', 'csit-607/ai-in-business/50bb43172fa6', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c18f6e55-4121-53f3-8bf5-b5093353cd48', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'What is pilot purgatory and how can it be avoided?', 'Many pilots launched but few scaled. Avoid it by testing real data feeds, users and integration, setting a baseline, control and pre-agreed stop-or-go rule, and naming operational owners.', 'supplementary', 'csit-607/ai-in-business/3664ed73bf4b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('28c184e0-65b7-555d-871b-08a7ffdcfa1b', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'Why does an AI model need MLOps and named hand-off owners after deployment?', 'Data and behaviour drift, so performance decays. MLOps provides versioning, monitoring, retraining and rollback, and named owners ensure someone answers for incidents, changes and regulator or customer queries.', 'supplementary', 'csit-607/ai-in-business/ee0c0b9687f2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e6ce08f5-c852-52e2-bd17-b1a498bbd841', null, '8462b4f9-230e-5350-ad0a-300b08f70203', 'a9903d1b-4e98-522b-8688-e8039fa69399', '7106fd30-95c2-59ab-a3b2-01b82b570202', 'How do you calculate risk-adjusted ROI and payback for an AI project?', 'ROI = (total benefit minus total cost) divided by total cost, with benefits multiplied by a realisation factor. Payback = one-off cost divided by annual net benefit after running costs.', 'supplementary', 'csit-607/ai-in-business/aa0a139a92e3', true)
