insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('8be5ae44-1661-50ca-958a-f6f880e55cd7', '8462b4f9-230e-5350-ad0a-300b08f70203', 'ai-engineering', 'AI Engineering Concepts', 'The engineering discipline required to move AI from experiment to dependable service.', 6, true)
