insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f0afaac8-8c37-5430-aa15-daf76829b34d', '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'f6fe6575-9ac5-5870-8ee9-3cbf7e5cc891', 'csit-607/responsible-ai/q11', 'true_false', 'understand', 'medium', 'Understand the status of pseudonymised data', 'Pseudonymised data, where names are replaced by codes but a key exists to re-identify people, is still personal data.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f0afaac8-8c37-5430-aa15-daf76829b34d', '{"value":true}'::jsonb, 'Because individuals can be re-identified using additional information, pseudonymised data remains personal data and data protection obligations continue to apply. Only effectively anonymised data falls outside, and anonymisation is hard to achieve.', null)
