insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b1b95b4b-b1f7-57c1-b727-fd626631efd9', '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'f6fe6575-9ac5-5870-8ee9-3cbf7e5cc891', 'csit-607/responsible-ai/q12', 'short_answer', 'recall', 'easy', 'Recall the regulator established by Act 843', 'Which body was established by Ghana''s Data Protection Act, 2012 (Act 843) to regulate the processing of personal information?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b1b95b4b-b1f7-57c1-b727-fd626631efd9', '{"answers":["Data Protection Commission","the Data Protection Commission","DPC"]}'::jsonb, 'Act 843 established the Data Protection Commission, with which data controllers must register, and which oversees compliance with the Act''s principles.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1d7b10c4-a02b-5166-a968-2af3bb187d31', '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'f6fe6575-9ac5-5870-8ee9-3cbf7e5cc891', 'csit-607/responsible-ai/q13', 'scenario', 'apply', 'medium', 'Classify AI uses under EU AI Act risk tiers', 'Under the EU AI Act''s risk-based approach, this use is most likely classified as', 'A Ghanaian fintech (illustrative scenario) plans to offer, in an EU country, an AI system that assesses the creditworthiness of individual loan applicants.', null, '[{"id":"a","text":"unacceptable risk and prohibited"},{"id":"b","text":"high risk, subject to requirements such as risk management, data governance, documentation and human oversight"},{"id":"c","text":"limited risk, requiring only a chatbot disclosure"},{"id":"d","text":"minimal risk with no specific obligations"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1d7b10c4-a02b-5166-a968-2af3bb187d31', '{"option":"b"}'::jsonb, 'Creditworthiness assessment of natural persons is listed among high-risk uses, which are permitted but subject to strict obligations. It is not a prohibited practice like social scoring by public authorities, and it carries more than transparency or minimal obligations.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3e41dc6e-493d-58f1-8b72-22355845685e', '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'f6fe6575-9ac5-5870-8ee9-3cbf7e5cc891', 'csit-607/responsible-ai/q14', 'mcq', 'analyse', 'hard', 'Analyse controls for model extraction', 'A competitor is suspected of systematically querying a lender''s public credit-scoring API to replicate the model. Which set of controls is most appropriate?', null, null, '[{"id":"a","text":"Retrain the model weekly"},{"id":"b","text":"Authentication, rate limiting, monitoring of unusual query patterns and returning less granular outputs"},{"id":"c","text":"Adding more features to the model"},{"id":"d","text":"Publishing the model weights to remove the incentive"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3e41dc6e-493d-58f1-8b72-22355845685e', '{"option":"b"}'::jsonb, 'Model extraction relies on many queries and detailed outputs, so limiting and monitoring access and reducing output granularity raise the cost of copying. Retraining or adding features do not prevent extraction, and publishing weights gives away the asset.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('76f84a98-a6fe-5b8c-ba87-c32a05f05ffe', '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'f6fe6575-9ac5-5870-8ee9-3cbf7e5cc891', 'csit-607/responsible-ai/q15', 'true_false', 'understand', 'easy', 'Recognise the nature of the UNESCO Recommendation', 'The UNESCO Recommendation on the Ethics of Artificial Intelligence (2021) is a global normative instrument adopted by member states rather than a binding national statute.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('76f84a98-a6fe-5b8c-ba87-c32a05f05ffe', '{"value":true}'::jsonb, 'The Recommendation sets out values, principles and policy action areas agreed by UNESCO member states; it guides national policy but is not itself a national law such as Act 843.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('db94e817-e506-5041-8e69-99916eedf6ec', '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'f6fe6575-9ac5-5870-8ee9-3cbf7e5cc891', 'csit-607/responsible-ai/q16', 'scenario', 'evaluate', 'hard', 'Evaluate a data minimisation decision', 'Which evaluation best reflects data protection principles?', 'A telecoms provider (illustrative scenario) wants to add customers'' full contact lists and the content of SMS messages to its churn model "in case they improve accuracy".', null, '[{"id":"a","text":"Acceptable, because more data generally improves models"},{"id":"b","text":"Acceptable if the data is pseudonymised"},{"id":"c","text":"Not justified; it conflicts with data minimisation and purpose limitation, is highly intrusive and should be rejected unless a clear necessity and lawful basis can be shown"},{"id":"d","text":"Acceptable as long as the model is accurate"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('db94e817-e506-5041-8e69-99916eedf6ec', '{"option":"c"}'::jsonb, 'Collecting highly intrusive data speculatively conflicts with minimisation and purpose specification. Pseudonymisation does not remove these obligations, and accuracy gains do not justify disproportionate processing.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('41cf9be2-87c8-59c7-ac41-3ae87565443a', '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', null, 'csit-607/responsible-ai/q17', 'case_analysis', 'evaluate', 'hard', 'Apply fairness, privacy, security and governance frameworks to an AI deployment', 'Evaluate the responsible AI risks in this case and recommend a governance and deployment plan.', null, 'Illustrative scenario. A fictional Ghanaian microfinance institution has built a model that approves small business loans automatically within minutes using mobile money histories, phone metadata and location. Testing shows a selection rate of 0.55 for urban applicants and 0.33 for rural applicants, and a true positive rate of 0.88 for urban and 0.68 for rural applicants who repaid in a pilot. The institution also plans an LLM chatbot that explains decisions and can "update customer details" on request. There is no AI policy, no register of models and no named owner for the system, and the privacy notice does not mention automated decisions.', null, 25, array['Brief summary of the system and stakeholders', 'Fairness analysis using the metrics provided', 'Explainability and contestability', 'Privacy analysis under Act 843', 'Security analysis of the chatbot', 'Governance using the NIST AI RMF', 'Prioritised recommendations and deployment conditions']::text[], '[{"criterion":"Fairness analysis","marks":6,"descriptor":"Correctly computes the parity ratio (about 0.60) and TPR gap (0.20), interprets them and identifies plausible proxy causes and mitigations"},{"criterion":"Privacy and Act 843","marks":5,"descriptor":"Applies minimisation, purpose, openness and data subject rights, including automated decision transparency"},{"criterion":"Security","marks":4,"descriptor":"Identifies prompt injection and excessive agency risks of the update tool and proposes least privilege and verification"},{"criterion":"Governance and deployment","marks":6,"descriptor":"Uses Govern, Map, Measure, Manage to propose ownership, register, testing, staged rollout, human review and appeals"},{"criterion":"Critical judgement and communication","marks":4,"descriptor":"Prioritises actions, justifies trade-offs and writes clearly"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('41cf9be2-87c8-59c7-ac41-3ae87565443a', '{}'::jsonb, 'Examiners reward accurate calculation and interpretation, specific application of Act 843 principles, recognition of the chatbot''s excessive agency, and a structured, prioritised governance plan rather than generic statements.', 'A strong answer first quantifies the disparities. The demographic parity ratio is 0.33 / 0.55 = 0.60, well below the four-fifths benchmark, and the equal opportunity gap is 0.88 - 0.68 = 0.20, meaning creditworthy rural applicants are refused far more often. Because the gap persists among people who repaid, it cannot be explained only by different base rates. Likely causes include proxies such as transaction frequency, phone type or location that measure connectivity rather than creditworthiness, and under-representation of rural repayers. Remedies include collecting rural outcome data, reviewing proxy features, considering threshold adjustment where lawful, and adding human review for borderline rural cases, with re-measurement.

On privacy, Act 843 principles of specification of purpose, compatibility, minimisation and openness are engaged: phone metadata and precise location may be excessive; the privacy notice must disclose automated decision-making; and customers need routes to access and correct data and to contest decisions, including the Act''s provisions on automated decisions. Registration with the Data Protection Commission should be confirmed.

The chatbot''s ability to update customer details is a serious security risk: prompt injection or social engineering could change phone numbers and enable account takeover. It should not hold that tool; changes require authenticated, verified workflows with human or strong-authentication checks. Explanations must be grounded in actual decision reasons.

Governance should follow the NIST AI RMF: Govern (board-approved AI policy, named owner, register); Map (intended use, affected groups, legal duties); Measure (fairness, accuracy, robustness and red-team tests); Manage (conditional go-live, appeals, monitoring by region, incident response). Deployment should be paused for rural applicants or moved to human-in-the-loop approval until the disparity is addressed.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('125c71f5-6f9c-57a9-ad3d-2edb778fb2e0', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'acce5ae1-87e7-5542-97cf-0d459359e5b5', 'Why does "fairness through unawareness" usually fail?', 'Proxy features such as location, language or school can encode the removed protected attribute, so disparities persist; fairness must be measured on outcomes.', 'supplementary', 'csit-607/responsible-ai/f18519c2394a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('24c480ae-7815-5cb9-bac7-6c86dffe9d47', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'acce5ae1-87e7-5542-97cf-0d459359e5b5', 'How do demographic parity and equal opportunity differ?', 'Demographic parity compares overall selection rates across groups; equal opportunity compares true positive rates among qualified individuals.', 'supplementary', 'csit-607/responsible-ai/5200832684d2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b2e25e55-d682-5a54-b4e2-02587b240faa', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'acce5ae1-87e7-5542-97cf-0d459359e5b5', 'What does the four-fifths rule indicate?', 'A selection-rate ratio below 0.8 between a group and the most favoured group is treated, in US employment practice, as an indicator of possible adverse impact needing investigation.', 'supplementary', 'csit-607/responsible-ai/28661c44cd2d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3a16eff2-422c-51f1-860e-92d9d48467c7', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'acce5ae1-87e7-5542-97cf-0d459359e5b5', 'What do the fairness impossibility results imply for practice?', 'When base rates differ, calibration and equal error rates cannot all hold, so selecting a fairness criterion is a justified, documented normative choice.', 'supplementary', 'csit-607/responsible-ai/ee3f1e519e17', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('53a8d7f3-8a1f-54ab-a155-309fc6f6c5d1', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'acce5ae1-87e7-5542-97cf-0d459359e5b5', 'Explain LIME in one sentence.', 'LIME perturbs inputs around one instance, observes the black-box predictions and fits a simple interpretable surrogate model that approximates the model locally.', 'supplementary', 'csit-607/responsible-ai/0f25593281d4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('57d43db9-cd88-5713-a282-c5ae1ff68c07', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'acce5ae1-87e7-5542-97cf-0d459359e5b5', 'Global versus local explanation?', 'Global explanations describe overall model behaviour (for example permutation importance); local explanations account for one specific prediction (for example SHAP values for one applicant).', 'supplementary', 'csit-607/responsible-ai/9841d8a704eb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9f09d57b-8c63-5497-a46c-e141a278c7e8', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '56205ae5-5401-5e20-9896-3089c5481b02', 'acce5ae1-87e7-5542-97cf-0d459359e5b5', 'What is the key lesson of Obermeyer et al. (2019)?', 'Predicting a biased proxy (cost) for the real target (health need) produced racial disparity even without race as an input; label choice is a fairness decision.', 'supplementary', 'csit-607/responsible-ai/329d5f5cc3d5', true)
