insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('51d2e86d-2aad-59d9-90d0-56cf59a794c0', '8462b4f9-230e-5350-ad0a-300b08f70203', 'business-ai-projects', 'Practical Business AI Projects', 'End-to-end project designs that connect AI techniques to measurable business outcomes.', 8, true)
