insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('02f4c0b9-a0d9-55db-a392-3f2496d60951', '8462b4f9-230e-5350-ad0a-300b08f70203', '51d2e86d-2aad-59d9-90d0-56cf59a794c0', '98b3ca76-0c1f-5e09-bdca-d2529de082ce', 'csit-607/business-ai-projects/q18', 'mcq', 'analyse', 'medium', 'Analyse the ethical consequences of fraud false positives', 'Why is a challenge tier (extra verification) valuable between approve and block decisions?', null, null, '[{"id":"a","text":"It removes the need for fraud models"},{"id":"b","text":"It reduces harm to genuine customers flagged by the model while still stopping many fraudsters, lowering friction compared with outright blocking"},{"id":"c","text":"It increases the number of blocked transactions"},{"id":"d","text":"It avoids the need to monitor drift"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('02f4c0b9-a0d9-55db-a392-3f2496d60951', '{"option":"b"}'::jsonb, 'Genuine customers who are blocked may lose access to money they urgently need. A challenge step lets them proceed after verification while still deterring fraud. It complements, rather than replaces, models and monitoring.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('28148495-7b45-52d0-ad8e-0b9b73f0ff4f', '8462b4f9-230e-5350-ad0a-300b08f70203', '51d2e86d-2aad-59d9-90d0-56cf59a794c0', '98b3ca76-0c1f-5e09-bdca-d2529de082ce', 'csit-607/business-ai-projects/q19', 'scenario', 'evaluate', 'hard', 'Evaluate controls for natural-language querying of company data', 'Which design change is most important?', 'A distributor (illustrative scenario) wants managers to ask questions such as "What were Kumasi depot sales last month?" through a text-to-SQL feature connected directly to the production ERP database with full write permissions.', null, '[{"id":"a","text":"Use a larger language model"},{"id":"b","text":"Restrict queries to read-only, pre-approved views with access controls, test the feature on a question set, and show the generated SQL and source for verification"},{"id":"c","text":"Allow only the managing director to use it"},{"id":"d","text":"Remove the dashboard so managers rely on the chat feature"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('28148495-7b45-52d0-ad8e-0b9b73f0ff4f', '{"option":"b"}'::jsonb, 'Full write access to production risks data corruption and leakage; read-only curated views, access controls, testing and transparency reduce these risks. A larger model does not remove them, restricting users does not fix the design flaw, and removing the dashboard reduces verifiability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1a810e66-13e7-5668-9f87-583377cbd0c1', '8462b4f9-230e-5350-ad0a-300b08f70203', '51d2e86d-2aad-59d9-90d0-56cf59a794c0', '98b3ca76-0c1f-5e09-bdca-d2529de082ce', 'csit-607/business-ai-projects/q20', 'true_false', 'analyse', 'medium', 'Recognise limitations of the anonymised fraud benchmark', 'Because the public anonymised credit-card fraud dataset covers only a short period with PCA-transformed features, it is poorly suited to practising behavioural feature design and drift monitoring.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1a810e66-13e7-5668-9f87-583377cbd0c1', '{"value":true}'::jsonb, 'Anonymised components prevent meaningful feature engineering, and a two-day window hides concept drift. The dataset is useful for practising imbalance-aware metrics and thresholds, but local projects need time-based splits and behavioural features.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2c20822d-eac6-5d38-ba40-53927f2c77dd', '8462b4f9-230e-5350-ad0a-300b08f70203', '51d2e86d-2aad-59d9-90d0-56cf59a794c0', null, 'csit-607/business-ai-projects/q21', 'essay', 'evaluate', 'hard', 'Design a complete business AI project proposal', 'Choose ONE of the six projects in this module and write a project proposal for an illustrative Ghanaian organisation. Your proposal must cover the business problem, data needed, approach (including a baseline), evaluation metrics, deployment, risks, ethics and a phased plan using free tools. Critically justify your key design decisions.', null, null, null, 30, array['Organisation context labelled as an illustrative scenario and the business objective', 'Data sources, quality issues, labels and legal basis under Act 843', 'Approach with baseline and justified model choices', 'Model, business and guardrail metrics with an evaluation design', 'Deployment pattern, human oversight and fallback', 'Risks, ethics and mitigations', 'Phased plan with tools, timeline and success criteria', 'Critical reflection on limitations']::text[], '[{"criterion":"Problem framing and business objective","marks":4,"descriptor":"Clear decision, owner and measurable objective in a labelled illustrative scenario"},{"criterion":"Data and approach","marks":7,"descriptor":"Realistic data and labels, quality issues, a baseline and justified model choices"},{"criterion":"Evaluation design","marks":6,"descriptor":"Appropriate model metrics, business metrics, guardrails, time-aware testing and a controlled pilot"},{"criterion":"Deployment, risk and ethics","marks":7,"descriptor":"Suitable deployment pattern, fallback, human oversight, specific risks and Act 843 compliance"},{"criterion":"Plan and critical justification","marks":6,"descriptor":"Feasible phased plan with free tools and reasoned trade-offs and limitations"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2c20822d-eac6-5d38-ba40-53927f2c77dd', '{}'::jsonb, 'Examiners reward coherence across all template elements, realistic data and evaluation design, justified rather than fashionable model choices, concrete risk and ethics controls, and a feasible plan that uses free tools.', 'A strong proposal might choose fraud detection for an illustrative scenario Ghanaian fintech offering wallet transfers. It frames the decision (approve, challenge or block each transaction), the owner (head of risk) and the objective (reduce total fraud-related cost without increasing complaints).

Data includes twelve months of transactions, device and SIM-swap events, account age and confirmed fraud labels, with recognition that labels are delayed and incomplete. Quality checks cover duplicates, timestamps and inconsistent labels. Processing is justified under Act 843, with minimised features and documented purpose.

The approach starts with the existing rules as a baseline, then a gradient-boosted classifier with class weights and an isolation forest for novel patterns. Choices are justified by tabular data, interpretability through SHAP reason codes and the need to catch unseen tactics.

Evaluation uses a time-based split, PR-AUC, precision and recall at capacity-feasible thresholds, value detection rate, and a total-cost comparison of thresholds; guardrails include segment false positive rates and latency. Deployment is a real-time API with a rules fallback, preceded by shadow deployment and canary release, with analysts reviewing alerts and customers able to verify or appeal.

Risks include adversarial drift, label delay, model extraction and unfair friction; mitigations include monitoring with PSI and flag rates, monthly retraining, rate limiting and fairness review. The phased plan runs over about sixteen weeks using Python, scikit-learn and Google Colab. A reflective conclusion acknowledges limits such as unreported fraud and the difficulty of estimating friction costs.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ce1ff87d-a57d-56e2-adf1-dd28c49d8e16', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '51d2e86d-2aad-59d9-90d0-56cf59a794c0', 'b21457b2-e0f1-5cea-8773-dd4141e49707', 'What are the eight elements of the business AI project template?', 'Business problem, data needed, approach, evaluation metrics, deployment, risks, ethics and a phased plan.', 'supplementary', 'csit-607/business-ai-projects/48b37d928a82', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('70174078-cd65-5e33-8f5e-3becf0c84712', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '51d2e86d-2aad-59d9-90d0-56cf59a794c0', 'b21457b2-e0f1-5cea-8773-dd4141e49707', 'Why use rolling-origin backtesting for demand forecasts?', 'It repeatedly trains on data up to a cut-off and tests on the following period, mimicking real forecasting and avoiding learning from the future.', 'supplementary', 'csit-607/business-ai-projects/627cdd82d779', true)
