insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('36bd8d94-774b-50cf-8bb1-4344cb863ee5', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '51d2e86d-2aad-59d9-90d0-56cf59a794c0', 'b21457b2-e0f1-5cea-8773-dd4141e49707', 'Why must churn be explicitly defined in prepaid businesses?', 'Prepaid customers seldom cancel formally, so churn must be defined behaviourally (for example, no purchase for 45 days), and the definition shapes labels and value.', 'supplementary', 'csit-607/business-ai-projects/4341f159a2a2', true)
