insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('27bc73de-1622-51b9-ad3b-7b59608982fc', null, '8462b4f9-230e-5350-ad0a-300b08f70203', '51d2e86d-2aad-59d9-90d0-56cf59a794c0', 'b21457b2-e0f1-5cea-8773-dd4141e49707', 'State the net value formula for a retention campaign.', 'Net value = (precision at k × k × retention success rate × CLV) − (k × offer cost).', 'supplementary', 'csit-607/business-ai-projects/ec0fed96132e', true)
