-- CSIT 610 Seminar
insert into public.courses (id, code, slug, title, description, status, status_note, classification, credit_slots, accent, outcomes, sort_order, source, is_published) values ('7b687631-8925-5aa4-a415-6ed134a64891', 'CSIT 610', 'csit-610', 'Seminar', 'A practical learning area for the academic seminar: what seminars are for and what examiners and peers expect, how to choose and refine a topic, explore and critically analyse the literature, build an evidence-based argument, structure and design an academic presentation, reference sources correctly, deliver with confidence, handle questions, and learn from feedback. GradPath provides preparation guidance and a personal seminar tracker; it does not set official seminar topics, deadlines or assessment criteria.', 'listed', 'Required course (1 credit slot), listed in the Semester 1 selection as "Required / Seminar". Confirm the official course title, seminar format, topic allocation and presentation dates with the department; GradPath does not set any of these.', 'required', 1, 'orange', array['Explain the purpose, common formats and expectations of a postgraduate academic seminar.', 'Select, scope and justify a seminar topic and frame it as a focused question or argument.', 'Locate, evaluate and critically synthesise literature to support a seminar argument.', 'Structure and design a clear academic presentation that uses evidence and visuals responsibly.', 'Reference sources accurately in slides and speech and uphold academic integrity.', 'Deliver a seminar presentation, handle questions professionally and participate constructively in discussion.', 'Use feedback and reflection to improve and develop seminar work into written research.']::text[], 5, 'supplementary', true)
  on conflict (id) do update set code = excluded.code, slug = excluded.slug, title = excluded.title, description = excluded.description, status = excluded.status, status_note = excluded.status_note, classification = excluded.classification, credit_slots = excluded.credit_slots, accent = excluded.accent, outcomes = excluded.outcomes, sort_order = excluded.sort_order, source = excluded.source, is_published = excluded.is_published;
insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('464a2054-a68c-59e7-a7d3-99aeda8b504a', '7b687631-8925-5aa4-a415-6ed134a64891', 'seminar-foundations', 'Seminar Foundations', 'What an academic seminar is for, what is expected of presenters and participants, and how to conduct yourself professionally.', 1, true)
  on conflict (id) do update set course_id = excluded.course_id, slug = excluded.slug, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.lessons (id, module_id, slug, title, summary, topics, estimated_minutes, difficulty, source, content, word_count, sort_order, is_published) values ('d6e64b86-788a-5250-ba80-ff096b4bbadc', '464a2054-a68c-59e7-a7d3-99aeda8b504a', 'seminar-purpose-and-expectations', 'The Academic Seminar: Purpose, Formats and Expectations', 'Explain what a postgraduate seminar is for, recognise its common formats, and prepare against the expectations that presenters, peers and assessors typically hold.', array['Academic seminar', 'Seminar formats', 'Assessment expectations']::text[], 40, 'introductory', 'supplementary', '{"introduction":"A postgraduate seminar is different from a lecture and different from a conference talk. In a lecture, an expert transmits established knowledge to a largely silent audience. In a seminar, a student presents a piece of reasoned work, usually a topic investigated through the literature, and the audience is expected to question it, test it and help improve it. The seminar is therefore a rehearsal for the professional life of a researcher or a senior practitioner: you defend a position in front of informed people who are entitled to disagree with you.\n\nThis lesson explains why academic seminars exist, the formats they commonly take, and the expectations that usually surround them. It also shows you how to turn vague expectations into a personal preparation plan. A word of caution runs through the whole course: GradPath is supplementary study material. The official seminar format, topic allocation, presentation dates and assessment criteria for CSIT 610 are set by your department, and you must confirm them with your course coordinator or supervisor. Nothing here replaces those instructions.","objectives":["Explain the educational purposes of a postgraduate academic seminar.","Compare common seminar formats, including individual presentations, panel sessions, journal-club style discussions and work-in-progress seminars.","Distinguish a seminar presentation from a lecture, a business pitch and a written report.","Identify the questions to ask your department so that you prepare against official rather than assumed requirements.","Construct a personal seminar preparation timeline that works backwards from a confirmed presentation date."],"prerequisites":["None beyond general familiarity with postgraduate study and academic reading.","Helpful: some experience of reading journal articles, as covered in earlier research methods material."],"keyTerms":[{"term":"Academic seminar","definition":"A structured session in which a presenter shares reasoned, evidence-based work and the audience engages in questioning and discussion."},{"term":"Work-in-progress seminar","definition":"A seminar where unfinished research is presented specifically to receive critical feedback before completion."},{"term":"Journal club","definition":"A format in which participants read and critically discuss a published paper together."},{"term":"Discussant","definition":"A person assigned to respond critically and constructively to a presentation."},{"term":"Assessment criteria","definition":"The published standards against which a presentation is judged, set by the institution rather than by the student."},{"term":"Learning outcome","definition":"A statement of what a student should be able to do after completing a learning activity."},{"term":"Audience analysis","definition":"Deciding what the listeners already know, what they need and what they are likely to ask."}],"body":[{"heading":"Detailed Explanation","markdown":"### Why seminars exist\n\nUniversities use seminars because several important academic abilities cannot be developed by reading and writing alone. A seminar develops at least five.\n\n1. **Synthesis under pressure.** You must reduce a body of reading to a message that can be understood in a fixed time. This forces you to decide what matters.\n2. **Oral argument.** Many professional settings, such as board meetings, client reviews and project steering groups, reward the ability to defend a claim aloud. A seminar is a safe place to practise.\n3. **Critical listening.** Seminar audiences are not passive. Listening for weak evidence, hidden assumptions and unsupported leaps is itself a research skill.\n4. **Scholarly community.** Research is a collective activity. Seminars expose you to the questions peers ask, which often reveal gaps you have not noticed.\n5. **Preparation for the dissertation.** A seminar is often an early opportunity to test an idea that later becomes a proposal or dissertation chapter.\n\n### Seminar versus lecture, pitch and report\n\nStudents often misjudge the genre. A **lecture** presents settled knowledge; a seminar presents an argument that remains open to challenge. A **business pitch** aims to persuade an audience to buy or fund something and may legitimately minimise doubt; an academic seminar is rewarded for acknowledging limitations. A **written report** can be read at the reader''s pace and can contain detail; a seminar must be understood in real time, so it needs fewer points, clearer signposting and deliberate repetition of the key message.\n\n### Common formats\n\nDepartments vary, so treat the following as a map of possibilities rather than a description of what you will be asked to do.\n\n| Format | Typical features | What it tests |\n|---|---|---|\n| Individual presentation | One presenter, fixed time, questions afterwards | Structure, evidence, clarity, composure |\n| Group or panel session | Several presenters on a shared theme | Coordination, distinct contributions, consistency |\n| Journal-club style | Everyone reads a paper; one person leads discussion | Critical reading, evaluation of methods and claims |\n| Work-in-progress seminar | Presenter shares unfinished research | Openness to feedback, clear statement of problems |\n| Poster or lightning talk | Very short or visual summary | Prioritisation and concision |\n\nWhatever the format, an examiner or lecturer is usually looking for a recognisable set of qualities: a clear question or argument, evidence from credible sources, logical structure, accurate referencing, professional delivery and the ability to respond to questions. You should confirm the exact weighting and any marking guide with your department.\n\n### What audiences expect\n\nPeers expect to learn something and to be treated respectfully. Lecturers expect evidence that you have read widely, understood what you read and can evaluate it rather than only summarise it. Everyone expects you to keep to time. Overrunning is usually interpreted as poor planning, and it consumes the discussion time that makes a seminar worthwhile."},{"heading":"Theories, Frameworks and Models","markdown":"### Bloom''s taxonomy as a guide to ambition\n\nBloom''s revised taxonomy, which orders cognitive tasks from remembering and understanding through applying, analysing, evaluating and creating, is a useful way to judge the level of a seminar. A presentation that only describes sources sits at the lower levels. A presentation that compares sources, judges their quality and constructs a reasoned position operates at the higher levels. Postgraduate seminars are expected to reach analysis and evaluation.\n\n### The audience-purpose-message triangle\n\nA simple planning model asks three linked questions: who is the audience, what is the purpose of the session, and what single message should they leave with? If you cannot state the message in one sentence, the presentation is probably a tour of the literature rather than an argument. Each choice you make later, such as which studies to include or which figure to show, can then be tested against that sentence.\n\n### Backward planning\n\nBackward planning starts from the confirmed presentation date and allocates time to reading, drafting, slide preparation, rehearsal and revision. It is an application of ordinary project management, which MSc IT for Business students already understand, to an academic deliverable."},{"heading":"Step-by-Step Guide: Building your seminar preparation plan","markdown":"1. **Confirm the official requirements.** Ask your coordinator or department for the seminar format, duration, topic allocation process, date, assessment criteria and any submission requirements such as slides or a written summary. Record the answers and the date you received them.\n2. **Clarify what is fixed and what is your choice.** Find out whether you choose your own topic, are assigned one or select from a list.\n3. **Write your one-sentence message.** Even a provisional one anchors your reading.\n4. **Work backwards from the date.** Allocate time to topic selection, literature search, analysis, drafting, slides, at least two rehearsals and a buffer.\n5. **Identify your audience.** Note what they probably know about your topic and which terms need defining.\n6. **Prepare for questions early.** List five questions a sceptical peer might ask and note where your evidence is thin.\n7. **Review against the criteria.** Before the seminar, check your draft against whatever criteria your department supplied."},{"heading":"Worked Example","markdown":"Illustrative scenario. A student is told that her seminar will take place in eight weeks, with a fifteen-minute presentation followed by questions. She works backwards.\n\n| Week | Task | Output |\n|---|---|---|\n| 1 | Confirm format and criteria; shortlist topics | Written requirements note; three candidate topics |\n| 2 | Select and scope topic; draft question | One-sentence message |\n| 3-4 | Search and read; annotate sources | Source table with 10-15 evaluated sources |\n| 5 | Build argument; draft structure | Outline with evidence per point |\n| 6 | Prepare slides; draft speaking notes | First complete draft |\n| 7 | Rehearse twice with a peer; time it | Revised slides; list of likely questions |\n| 8 | Final rehearsal and logistics check | Ready, with buffer |\n\nThe plan shows a principle worth remembering: reading and thinking occupy most of the time, and slides occupy less than students expect."},{"heading":"Ghanaian Business Application","markdown":"Seminars are not confined to universities. In Ghanaian professional life, IT and business graduates routinely present to audiences who can challenge them: an internal technology steering committee deciding whether to adopt a new system, a professional association meeting, an industry forum or a project review with a client. The habits built in an academic seminar transfer directly. A manager who has learned to state a clear message, support it with credible evidence, acknowledge limitations and answer questions calmly is more persuasive in a boardroom than one who simply asserts conclusions.\n\nFor an MSc IT for Business student in Ghana, the same discipline applies to local topics. If you present on digital payments, for example, the audience will expect you to separate well-documented developments from impressions, to say where your sources come from, and to acknowledge that evidence about Ghana may be thinner than evidence from larger markets. Remember also that your own department sets the rules for your seminar. Treat the guidance in this lesson as preparation, and the department''s instructions as the authority."},{"heading":"International Case Study","markdown":"Illustrative scenario. Two students at an overseas university are given the same topic, the adoption of cloud computing by small firms, and the same ten minutes. The first student presents twenty slides summarising the findings of nine studies in the order she read them. When a peer asks, \"So what should a small firm owner conclude?\", she cannot answer, because no argument was ever stated. The second student opens with a single claim: \"Cost savings are the most cited benefit, but the evidence suggests that skills shortages, not cost, decide whether adoption succeeds.\" He uses five slides, each tied to that claim, states that two of his sources rely on self-reported data, and answers the peer''s question directly.\n\nThe comparison is instructive. Both students read widely. The difference lies in genre awareness. The first treated the seminar as a report delivered aloud; the second treated it as an argument offered for testing. Examiners and peers in almost any university system are likely to credit the second approach, because it demonstrates analysis, evaluation and honesty about limitations rather than only coverage."},{"heading":"Diagram","markdown":"```mermaid\nflowchart TD\n    A[\"Confirm official requirements\"] --> B[\"Choose and scope topic\"]\n    B --> C[\"State one-sentence message\"]\n    C --> D[\"Search and evaluate literature\"]\n    D --> E[\"Build argument and structure\"]\n    E --> F[\"Prepare slides and notes\"]\n    F --> G[\"Rehearse and anticipate questions\"]\n    G --> H[\"Present and discuss\"]\n    H --> I[\"Reflect on feedback\"]\n```"}],"misconceptions":["**\"A seminar is a short lecture.\"** A lecture transmits settled knowledge; a seminar offers an argument for discussion and challenge.","**\"Covering more sources is always better.\"** Coverage without an argument is description. Fewer, well-evaluated sources organised around a claim are stronger.","**\"Questions from the audience mean I did badly.\"** Questions are the purpose of the format. They usually signal engagement.","**\"I can find the requirements out later.\"** Format, timing and criteria shape every decision, so they should be confirmed first.","**\"Slides are the main work.\"** Reading, thinking and structuring the argument are the main work; slides support them."],"examMistakes":["Assuming the format, duration or criteria instead of confirming them with the department.","Presenting a list of summaries with no central question or argument.","Overrunning the allocated time and leaving no room for discussion.","Treating limitations as embarrassing and omitting them.","Confusing the genre with a sales pitch and overstating certainty.","Neglecting to prepare for obvious questions about method, evidence and relevance."],"criticalQuestions":["Why might a seminar be a better assessment of some academic abilities than an examination or an essay, and what might it measure less well?","How would you adapt the same topic for a seminar of peers, for a panel of lecturers and for an industry forum?","In what situations might a presenter legitimately be less certain in a seminar than in a business pitch, and why is that acceptable?","If you could state only one sentence of your seminar, what would it be, and what does your answer reveal about how clear your argument is?"],"exercises":["**Requirements checklist.** Draft a list of at least eight questions to ask your department about the CSIT 610 seminar (format, duration, topic allocation, date, criteria, submission, language of delivery, support available). Expected output: a one-page checklist you can send or take to a meeting.","**Genre comparison.** Take one journal article and write three opening sentences for it: one as a lecture, one as a business pitch and one as a seminar argument. Expected output: three sentences and a short note on how they differ.","**Backward plan.** Using a real or hypothetical date eight weeks away, build a weekly preparation plan. Expected output: a table similar to the worked example, with a buffer week identified.","**Question forecast.** For a topic that interests you, write five hard questions a peer might ask and one sentence on how you would prepare to answer each. Expected output: a list of five questions with preparation notes."],"takeaways":["A seminar presents a reasoned argument for discussion, not settled knowledge for transmission.","Seminars build synthesis, oral argument, critical listening and readiness for the dissertation.","Formats vary; always confirm the official format, timing and criteria with your department.","Audience, purpose and a one-sentence message should guide every content decision.","Backward planning turns a fixed date into a realistic preparation timeline.","Acknowledging limitations signals academic maturity."],"furtherReading":[{"text":"American Psychological Association. (2020). *Publication manual of the American Psychological Association* (7th ed.). American Psychological Association.","url":null,"verification":"citation"},{"text":"Booth, W. C., Colomb, G. G., & Williams, J. M. (2008). *The craft of research* (3rd ed.). University of Chicago Press.","url":null,"verification":"citation"},{"text":"Cottrell, S. (2017). *Critical thinking skills: Effective analysis, argument and reflection* (3rd ed.). Palgrave Macmillan.","url":null,"verification":"citation"}],"videos":[{"title":"Purdue Online Writing Lab","url":"https://owl.purdue.edu/","description":"Purdue University. Official writing resource portal with guidance on research writing, presentations and academic communication.","verification":"verified"},{"title":"APA Style","url":"https://apastyle.apa.org/","description":"American Psychological Association. Official APA Style site with guidance on writing and referencing.","verification":"verified"}],"revisionSummary":"An academic seminar is a structured occasion for presenting reasoned work and having it questioned, which develops synthesis, oral argument, critical listening and readiness for dissertation work. It differs from a lecture, a business pitch and a written report. Formats vary, so the official requirements for CSIT 610 must be confirmed with the department rather than assumed. Good preparation starts from a one-sentence message, considers the audience and works backwards from the confirmed date.\n\n- A seminar offers an argument for testing, not settled facts.\n- Confirm format, timing and criteria first.\n- State your message in one sentence.\n- Plan backwards from the date.\n- Prepare for questions early.\n- Admit limitations honestly."}'::jsonb, 2411, 1, true)
  on conflict (id) do update set module_id = excluded.module_id, slug = excluded.slug, title = excluded.title, summary = excluded.summary, topics = excluded.topics, estimated_minutes = excluded.estimated_minutes, difficulty = excluded.difficulty, source = excluded.source, content = excluded.content, word_count = excluded.word_count, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.lessons (id, module_id, slug, title, summary, topics, estimated_minutes, difficulty, source, content, word_count, sort_order, is_published) values ('48d323c6-e68e-54b7-b4aa-104503a1db52', '464a2054-a68c-59e7-a7d3-99aeda8b504a', 'participation-and-academic-conduct', 'Seminar Participation and Professional Academic Conduct', 'Participate constructively as audience member, discussant and presenter, disagree respectfully, and uphold the professional and integrity standards expected in academic settings.', array['Seminar participation', 'Academic conduct', 'Respectful debate']::text[], 40, 'introductory', 'supplementary', '{"introduction":"Most students think of a seminar as the presenter''s performance. In reality, a seminar succeeds or fails on the quality of everyone''s participation. A presenter with a strong argument will still leave the room having learned little if the audience is silent or hostile, and a modest presentation can become a valuable session when peers ask precise, generous questions. Participation is therefore a skill to be practised, and in many programmes it is also observed and judged.\n\nThis lesson covers three connected topics: how to take part productively when you are not presenting, how to disagree and challenge ideas without damaging relationships, and how to maintain professional and ethical standards before, during and after a seminar. These standards include honest use of sources, fair credit for group work, respect for confidentiality and appropriate behaviour online and in person. As elsewhere in this course, the official rules on attendance, participation marks and academic misconduct belong to your department and the university; you should read them directly rather than rely on this supplementary material.","objectives":["Describe the roles of audience member, discussant and presenter and the responsibilities attached to each.","Formulate questions and comments that are specific, evidence-focused and respectful.","Apply a structure for disagreeing constructively with a claim without attacking the person.","Identify behaviours that breach professional academic conduct, including plagiarism, misrepresentation of data and unfair credit in group work.","Evaluate a seminar contribution against criteria of relevance, clarity, evidence and courtesy."],"prerequisites":["Completion of the lesson on the purpose, formats and expectations of the academic seminar, or equivalent understanding.","Basic awareness of plagiarism and the need to cite sources."],"keyTerms":[{"term":"Participation","definition":"Active, informed contribution to a seminar through listening, questioning, commenting and responding."},{"term":"Academic conduct","definition":"The standards of honesty, fairness and respect expected of students and researchers."},{"term":"Academic integrity","definition":"The commitment to honesty in learning, research and communication, including accurate acknowledgement of sources."},{"term":"Respectful debate","definition":"Disagreement that targets arguments and evidence rather than the character of the speaker."},{"term":"Clarifying question","definition":"A question asking the speaker to explain or define something that was unclear."},{"term":"Probing question","definition":"A question that tests the strength of evidence, reasoning or assumptions."},{"term":"Ad hominem","definition":"An attack on the person making a claim rather than on the claim itself."},{"term":"Collusion","definition":"Unauthorised cooperation that results in work being presented as independent when it is not."}],"body":[{"heading":"Detailed Explanation","markdown":"### Three roles, three responsibilities\n\n**The audience member** has a duty to prepare. If the topic or reading is circulated in advance, read it. Arrive on time, switch off distractions and listen for the main argument. A good audience member makes brief notes of the claim, the evidence offered and any point where the reasoning seems weak. Behaviour that signals disrespect, such as private conversations, repeated phone use or leaving noisily, damages the atmosphere for everyone.\n\n**The discussant**, where the format includes one, is not an opponent but a critical friend. A discussant summarises the argument fairly, identifies its strengths, raises two or three substantive issues and suggests how the work might be improved. The order matters: a fair summary shows that you understood before you criticised.\n\n**The presenter** has a duty to be honest about the strength of the evidence, to credit every source, to keep to time and to treat questions as contributions. A presenter who becomes defensive teaches the audience not to ask.\n\n### The anatomy of a good question\n\nPoor questions are long statements disguised as questions, requests for the presenter to repeat what they said, or attempts to show off the questioner''s knowledge. Good questions are short, specific and tied to the content. They usually fall into recognisable types.\n\n| Question type | Purpose | Example stem |\n|---|---|---|\n| Clarifying | Remove ambiguity | \"When you say adoption, do you mean intention or actual use?\" |\n| Probing evidence | Test support for a claim | \"What evidence suggests the effect applies beyond the studies you reviewed?\" |\n| Probing assumption | Expose hidden premises | \"Does your argument assume that firms have reliable internet access?\" |\n| Extending | Move the idea forward | \"How might the argument change for very small firms?\" |\n| Connecting | Link to other work | \"How does this relate to the literature on trust that we discussed earlier?\" |\n\nBefore asking, decide whether the question is something the whole room benefits from. If it concerns a personal interest or requires a long answer, it may be better asked after the session.\n\n### Disagreeing without damage\n\nAcademic life depends on disagreement, because claims improve when they are challenged. The skill is to challenge the claim and not the person. A useful four-step structure is:\n\n1. **Acknowledge** the point accurately: \"You argue that cost is the main barrier.\"\n2. **State the disagreement or concern precisely:** \"I am not yet convinced, because two of the studies you cited surveyed only large firms.\"\n3. **Give the reason or evidence** for your concern.\n4. **Invite a response:** \"How would you respond to that limitation?\"\n\nContrast this with remarks such as \"That is obviously wrong\" or \"Anyone who has worked in industry knows that is nonsense\". These offer no reasoning and signal contempt. An *ad hominem* remark about the presenter''s competence, background or accent has no place in a seminar.\n\n### Professional academic conduct\n\nConduct expectations apply well beyond the seminar room.\n\n- **Honesty with sources.** Every idea, figure and quotation that is not yours must be acknowledged. Presenting another person''s slides, paraphrase or diagram as your own is plagiarism even if it is spoken rather than written.\n- **Honesty with data.** Do not fabricate, selectively report or alter figures to make an argument look stronger. If you adapt a chart from a source, say so.\n- **Fair credit in group work.** If a seminar is delivered by a team, each member''s contribution must be genuine and the division of work should be agreed openly. Allowing a colleague to carry the work, or taking credit for it, is unfair and may breach university rules.\n- **Collusion.** Sharing slides or answers where independent work is required is misconduct. Collaboration is acceptable only when the assignment permits it.\n- **Confidentiality.** If a peer shares an unpublished idea or a company shares sensitive information with you, do not disclose it beyond the permitted setting. Do not name individuals or organisations in ways that could harm them.\n- **Respect and inclusion.** Listen to colleagues with different accents, languages, experience and confidence levels. Avoid interrupting, and give quieter participants space.\n- **Digital conduct.** Do not record a seminar without permission. Keep online chat on topic and courteous.\n- **Use of AI tools.** Whether and how tools that generate text may be used in preparation is a matter of institutional policy. Ask your department, and where use is permitted, disclose it in the way it requires. You remain fully responsible for the accuracy of anything you present."},{"heading":"Theories, Frameworks and Models","markdown":"### The ladder of inference\n\nThe ladder of inference, associated with Chris Argyris and popularised in organisational learning writing, describes how people move from observable data to selected data, meanings, assumptions, conclusions and actions, often so quickly that they confuse their conclusion with fact. In a seminar, it explains why disagreements stall: each side is climbing a different ladder. A productive response is to climb down and ask, \"What data are you using, and how did you interpret them?\"\n\n### Charitable interpretation (the principle of charity)\n\nThe principle of charity asks you to interpret an argument in its strongest reasonable form before criticising it. It protects you from attacking a weak version that the speaker did not mean, and it makes your criticism more credible. If you can restate the presenter''s position so that they say \"Yes, that is what I mean\", your challenge will be taken seriously.\n\n### Psychological safety\n\nResearch on teams commonly describes psychological safety as a shared belief that people can speak up without being humiliated. Seminars work best in such an environment. Tone, body language and the way errors are treated either build or erode it, and every participant contributes."},{"heading":"Step-by-Step Guide: Contributing to a seminar you are attending","markdown":"1. **Prepare.** Read any circulated material and write down two questions beforehand.\n2. **Listen for structure.** Note the claim, the evidence and the conclusion.\n3. **Mark uncertainty.** Place a question mark beside any claim that seems unsupported.\n4. **Choose your question.** Select the single most useful clarifying or probing question.\n5. **Frame it briefly.** Use one sentence of context and one question.\n6. **Listen to the answer.** Do not prepare your next point while the speaker is replying.\n7. **Follow up only if needed.** Avoid turning the exchange into a debate that excludes others.\n8. **Thank and reflect.** Afterwards, note what you learned and what you would ask differently."},{"heading":"Worked Example","markdown":"Illustrative scenario. A presenter argues that mobile banking adoption among small traders is mainly limited by distrust of providers. A peer feels the evidence is thin.\n\nAn unhelpful contribution: \"I do not agree. Everyone knows trust is not the problem. You clearly have not spoken to real traders.\"\n\nA constructive contribution using the four steps: \"You argue that distrust is the main barrier, and you cite three studies for this (acknowledge). I am not yet convinced, because two of those studies appear to measure intention rather than actual use (concern). Intention often differs from behaviour, so the studies may not show that distrust prevents adoption in practice (reason). Do you have evidence that links distrust to actual non-use?\" (invite response).\n\nThe second version is longer, but it is specific, fair and answerable, and it improves the argument. The presenter can respond with additional evidence or concede a limitation, and both responses advance the discussion."},{"heading":"Ghanaian Business Application","markdown":"Ghanaian professional culture often places high value on courtesy, seniority and community, and these are real strengths in a discussion setting. They also create a particular challenge: junior colleagues may hesitate to question a senior person, and polite silence can be mistaken for agreement. The skills in this lesson help to reconcile respect with rigour. Framing a challenge as a question (\"May I ask what evidence supports this?\"), acknowledging the speaker''s point first and keeping a courteous tone are all consistent with respectful norms while still allowing a claim to be tested.\n\nThese skills matter in practical business settings. In a project meeting where a vendor proposes a costly system, a manager who can ask a clear, respectful probing question about assumptions may prevent an expensive mistake. In a professional forum, accurate crediting of other people''s work protects reputations and builds trust. Observe the specific conduct rules of your university, which govern plagiarism and group assessment in your own programme; this lesson can help you understand the reasons behind them but does not state them."},{"heading":"International Case Study","markdown":"Illustrative scenario. A research team at an overseas university presents preliminary findings at an internal seminar. A senior professor challenges one analysis forcefully, and a doctoral student on the team becomes defensive. A visiting colleague intervenes: \"Could you tell us what result would change your mind?\" The question moves the exchange from personalities to evidence. The team agrees to run an additional check, and the finding is later revised in their draft.\n\nThe scenario illustrates two points that apply in any setting. First, a well-chosen question can convert conflict into collaboration by making the criteria for being convinced explicit. Second, a seminar is a place where being wrong early is cheaper than being wrong in publication. Departments with strong seminar cultures tend to treat challenge as a service to the presenter. Students who take the same stance learn faster, because they treat each question as free expert feedback."},{"heading":"Diagram","markdown":"```mermaid\nflowchart LR\n    A[\"Listen and note claim and evidence\"] --> B[\"Acknowledge the point accurately\"]\n    B --> C[\"State concern precisely\"]\n    C --> D[\"Give reason or evidence\"]\n    D --> E[\"Invite response\"]\n    E --> F{\"Is the concern resolved?\"}\n    F -- Yes --> G[\"Move discussion forward\"]\n    F -- No --> H[\"Offer to continue after the session\"]\n```"}],"misconceptions":["**\"Respect means never disagreeing.\"** Respect is shown by engaging seriously with an argument, which includes testing it. Silence is not always respect.","**\"A tough question is an attack.\"** A precise challenge is usually a sign that the questioner took the work seriously.","**\"Plagiarism only happens in written work.\"** Presenting another person''s ideas, slides or analysis as your own in speech is also plagiarism.","**\"Group work means I can rely on others.\"** Each member remains responsible for the integrity of the whole submission and for a genuine contribution.","**\"If I paraphrase, I do not need to cite.\"** Paraphrased ideas must still be attributed to their source."],"examMistakes":["Asking a long statement instead of a focused question.","Criticising the presenter personally rather than the argument or evidence.","Failing to prepare, then asking a question already answered in the presentation.","Using a source''s slides or diagram without acknowledgement.","Ignoring the department''s stated rules on group contribution and collusion.","Becoming defensive when challenged instead of treating the question as information."],"criticalQuestions":["When does challenging a senior colleague''s claim become professionally necessary, and how can you do so while preserving respect?","Is a question that you already know the answer to ever legitimate in a seminar? Justify your view.","How can a seminar group distinguish between a vigorous but fair debate and an exchange that has become personal?","What responsibilities do you have if you notice that a peer has presented a source''s work as their own?"],"exercises":["**Question rewrite.** Take five poor questions (for example, \"Why did you not cover blockchain?\") and rewrite each as a specific, answerable clarifying or probing question. Expected output: five original and five improved questions.","**Four-step disagreement.** Choose a claim from a journal article abstract and write a four-step respectful disagreement with it. Expected output: a short paragraph that acknowledges, states a concern, gives a reason and invites a response.","**Conduct audit.** Read your university''s published academic integrity guidance and list five behaviours it prohibits that could arise in a seminar. Expected output: a list with the source of each rule, noting only what the policy actually says.","**Peer observation.** Observe a recorded public talk or an authorised live session and note the types of question asked and how the speaker responded. Expected output: a table of questions by type with a short evaluation of each."],"takeaways":["Participation is an academic skill involving preparation, careful listening and well-formed questions.","Challenge the argument, not the person; acknowledge before you criticise.","Good questions are short, specific and answerable.","Professional conduct includes honest use of sources and data, fair credit in group work, confidentiality and inclusive behaviour.","Follow your institution''s actual rules on integrity, group work and the use of AI tools.","Treating questions as feedback accelerates learning."],"furtherReading":[{"text":"American Psychological Association. (2020). *Publication manual of the American Psychological Association* (7th ed.). American Psychological Association.","url":null,"verification":"citation"},{"text":"Cottrell, S. (2017). *Critical thinking skills: Effective analysis, argument and reflection* (3rd ed.). Palgrave Macmillan.","url":null,"verification":"citation"},{"text":"Booth, W. C., Colomb, G. G., & Williams, J. M. (2008). *The craft of research* (3rd ed.). University of Chicago Press.","url":null,"verification":"citation"}],"videos":[{"title":"Purdue Online Writing Lab","url":"https://owl.purdue.edu/","description":"Purdue University. Official writing resource portal including guidance on avoiding plagiarism and acknowledging sources.","verification":"verified"},{"title":"APA Style","url":"https://apastyle.apa.org/","description":"American Psychological Association. Official APA Style site with guidance on citing sources and ethical writing.","verification":"verified"}],"revisionSummary":"Seminar participation involves preparation, careful listening and short, specific questions of the clarifying, probing, extending or connecting kind. Disagreement is healthy when it targets claims and evidence, follows a structure of acknowledging, stating a concern, giving a reason and inviting a response, and avoids personal attacks. Professional conduct covers honest use of sources and data, fair credit in group work, confidentiality, inclusion and responsible digital behaviour. Official rules are set by your institution.\n\n- Prepare, listen and ask one good question.\n- Acknowledge before you challenge.\n- Attack arguments, never people.\n- Cite spoken as well as written borrowing.\n- Share credit fairly in group work.\n- Follow your university''s integrity rules."}'::jsonb, 2596, 2, true)
  on conflict (id) do update set module_id = excluded.module_id, slug = excluded.slug, title = excluded.title, summary = excluded.summary, topics = excluded.topics, estimated_minutes = excluded.estimated_minutes, difficulty = excluded.difficulty, source = excluded.source, content = excluded.content, word_count = excluded.word_count, sort_order = excluded.sort_order, is_published = excluded.is_published;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f35f1587-f07b-5399-8448-5ef1a7998a74', '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', 'd6e64b86-788a-5250-ba80-ff096b4bbadc', 'csit-610/seminar-foundations/q01', 'mcq', 'understand', 'easy', 'Distinguish a seminar from a lecture', 'Which statement best distinguishes an academic seminar from a lecture?', null, null, '[{"id":"a","text":"A seminar presents settled knowledge while a lecture presents open arguments"},{"id":"b","text":"A seminar offers reasoned work for questioning and discussion, while a lecture mainly transmits established knowledge"},{"id":"c","text":"A seminar is always shorter than a lecture"},{"id":"d","text":"A seminar does not require sources"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f35f1587-f07b-5399-8448-5ef1a7998a74', '{"option":"b"}'::jsonb, 'In a seminar the presenter offers an argument that the audience is expected to test, whereas a lecture usually transmits established knowledge. Length varies in both, and seminars certainly require credible sources.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
