insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('95fbd88b-d6d6-5fef-be1b-70ae96ebd262', '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', 'd6e64b86-788a-5250-ba80-ff096b4bbadc', 'csit-610/seminar-foundations/q06', 'mcq', 'analyse', 'hard', 'Analyse why seminar and pitch genres differ', 'Why is acknowledging limitations rewarded in an academic seminar but sometimes minimised in a business pitch?', null, null, '[{"id":"a","text":"Academic audiences are not interested in outcomes"},{"id":"b","text":"A pitch aims to persuade to buy or fund, while a seminar is judged on honest, evidence-based argument that can withstand challenge"},{"id":"c","text":"Limitations are never relevant in business"},{"id":"d","text":"Seminars are informal so honesty is optional"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('95fbd88b-d6d6-5fef-be1b-70ae96ebd262', '{"option":"b"}'::jsonb, 'The genres have different purposes. A seminar is assessed on the quality and honesty of reasoning, so limitations show maturity. A pitch seeks commitment and may downplay doubt, although misleading an investor is still unethical. The other options misstate what each audience values.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
