insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5b31f210-6e9b-564b-a3c1-c3246abff6cb', '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', 'd6e64b86-788a-5250-ba80-ff096b4bbadc', 'csit-610/seminar-foundations/q08', 'scenario', 'evaluate', 'hard', 'Evaluate a preparation plan', 'Which judgement of this plan is most defensible?', 'Illustrative scenario. A student has eight weeks. His plan allocates seven weeks to building slides and one week to reading, with no rehearsal time.', null, '[{"id":"a","text":"It is sound because slides are the main deliverable"},{"id":"b","text":"It is weak because reading, argument-building and rehearsal need more time than slide design"},{"id":"c","text":"It is sound because rehearsal wastes time"},{"id":"d","text":"It is weak only because eight weeks is too long"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5b31f210-6e9b-564b-a3c1-c3246abff6cb', '{"option":"b"}'::jsonb, 'Most of the effort should go into reading, thinking and structuring the argument, with at least two rehearsals. Slides support the argument and take less time than students expect. Eight weeks is a reasonable period.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f777a679-e5ae-5f4f-8d25-89745d8d8acf', '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', '48d323c6-e68e-54b7-b4aa-104503a1db52', 'csit-610/seminar-foundations/q09', 'mcq', 'understand', 'easy', 'Describe the role of a discussant', 'What is the main role of a discussant?', null, null, '[{"id":"a","text":"To oppose the presenter regardless of the content"},{"id":"b","text":"To act as a critical friend who summarises fairly, identifies strengths and raises substantive issues"},{"id":"c","text":"To repeat the presentation for latecomers"},{"id":"d","text":"To mark the presenter privately"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f777a679-e5ae-5f4f-8d25-89745d8d8acf', '{"option":"b"}'::jsonb, 'A discussant is a critical friend, not an opponent. A fair summary shows understanding before criticism. The other options misdescribe the role.', null)
