insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d56f99af-c67c-56d2-9727-b1e6d6cd3eda', '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', '48d323c6-e68e-54b7-b4aa-104503a1db52', 'csit-610/seminar-foundations/q10', 'matching', 'recall', 'medium', 'Match question types to purposes', 'Match each type of seminar question with its purpose.', null, null, '{"left":[{"id":"l1","text":"Clarifying question"},{"id":"l2","text":"Probing evidence question"},{"id":"l3","text":"Probing assumption question"},{"id":"l4","text":"Extending question"}],"right":[{"id":"r4","text":"Moves the idea into a new situation"},{"id":"r1","text":"Removes ambiguity about a term or claim"},{"id":"r2","text":"Tests support for a claim"},{"id":"r3","text":"Exposes hidden premises"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
