insert into public.question_keys (question_id, correct, explanation, model_answer) values ('04151ef9-b0d4-5451-916f-3dd1e13ba3c7', '{"value":true}'::jsonb, 'Plagiarism concerns presenting someone else''s ideas, words or work as your own, whatever the medium. Spoken and slide-based borrowing must be acknowledged in the same way as written text.', null)
