insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c849d4a2-f906-5cea-b48d-1d0f12fe17ce', '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', '48d323c6-e68e-54b7-b4aa-104503a1db52', 'csit-610/seminar-foundations/q12', 'scenario', 'apply', 'medium', 'Apply the four-step structure for disagreement', 'Which contribution best follows the acknowledge, concern, reason, invite structure?', 'Illustrative scenario. A presenter claims that distrust is the main barrier to mobile banking adoption. A peer notes that two of the cited studies measured intention, not actual use.', null, '[{"id":"a","text":"That is obviously wrong and you have not met real customers."},{"id":"b","text":"You argue distrust is the main barrier. I am not yet convinced, because two studies measured intention rather than use, which may differ. What evidence links distrust to actual non-use?"},{"id":"c","text":"Many people disagree with you."},{"id":"d","text":"I have a different topic I would like to talk about."}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c849d4a2-f906-5cea-b48d-1d0f12fe17ce', '{"option":"b"}'::jsonb, 'The correct option accurately restates the claim, states a specific concern, gives a reason and invites a response. The others are personal, vague or off-topic and give the presenter nothing to answer.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
