insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1806307c-6137-5d85-a7dc-18d30afb36d6', '{"answers":["ad hominem","ad hominem attack","argumentum ad hominem"]}'::jsonb, 'An ad hominem remark targets the speaker''s character, competence or background and offers no reasoning about the claim. It has no place in respectful academic debate.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('759452cb-df45-5364-9612-0fa65a290908', '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', '48d323c6-e68e-54b7-b4aa-104503a1db52', 'csit-610/seminar-foundations/q14', 'mcq', 'analyse', 'hard', 'Analyse group work integrity', 'In a team seminar, one member did most of the work and another presented it as an equal contribution. Which analysis is most accurate?', null, null, '[{"id":"a","text":"There is no issue because the team received one mark"},{"id":"b","text":"It raises fairness and integrity concerns because the division of work should be agreed openly and credit reflect genuine contribution"},{"id":"c","text":"It is acceptable if the team is friendly"},{"id":"d","text":"It is only a problem if the audience notices"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('759452cb-df45-5364-9612-0fa65a290908', '{"option":"b"}'::jsonb, 'Fair credit and genuine contribution are core conduct expectations in group work. Whether anyone notices, or whether the team is friendly, does not change the integrity issue. The department''s rules govern how it would be handled.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f2b62167-74ef-549e-98ee-e7db96a0d6d0', '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', '48d323c6-e68e-54b7-b4aa-104503a1db52', 'csit-610/seminar-foundations/q15', 'scenario', 'evaluate', 'hard', 'Evaluate a response to a culturally sensitive challenge', 'Which approach best combines respect and rigour?', 'Illustrative scenario. A junior colleague doubts a senior manager''s claim in a project meeting but fears appearing disrespectful.', null, '[{"id":"a","text":"Stay silent to avoid conflict"},{"id":"b","text":"Ask a courteous, specific question about the evidence after acknowledging the manager''s point"},{"id":"c","text":"Contradict the claim loudly"},{"id":"d","text":"Raise the concern only in private messages to others"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f2b62167-74ef-549e-98ee-e7db96a0d6d0', '{"option":"b"}'::jsonb, 'A respectful, specific question allows the claim to be tested without personal attack and is consistent with courteous norms. Silence leaves a possible error unchallenged, while loud contradiction or back-channel complaints damage trust.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f57b41ed-506e-5129-9d41-02189a68aa8c', '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', '48d323c6-e68e-54b7-b4aa-104503a1db52', 'csit-610/seminar-foundations/q16', 'true_false', 'apply', 'medium', 'Apply guidance on AI tools', 'Whether text-generation tools may be used when preparing a seminar is a matter of institutional policy, so a student should ask the department and follow its disclosure rules.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f57b41ed-506e-5129-9d41-02189a68aa8c', '{"value":true}'::jsonb, 'Policy on such tools varies and is set by the institution. Regardless of permission, the student remains responsible for the accuracy of everything presented.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('40d2f529-dbb3-5ae6-bcd5-6f88bfc6924e', '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', null, 'csit-610/seminar-foundations/q17', 'essay', 'evaluate', 'hard', 'Evaluate the value of seminar participation', 'Discuss the claim that the quality of a postgraduate seminar depends as much on the audience as on the presenter. Refer to the purposes of seminars, the skills of constructive participation and professional academic conduct.', null, null, null, 20, array['Introduction defining the seminar as an argument offered for testing', 'Purposes of seminars and why they need an active audience', 'Constructive questioning and respectful disagreement', 'Conduct and integrity responsibilities of all participants', 'Counter-view that presenter preparation matters most', 'Conclusion with a reasoned judgement']::text[], '[{"criterion":"Understanding of seminar purposes","marks":5,"descriptor":"Explains synthesis, oral argument, critical listening, community and dissertation preparation and links them to audience roles."},{"criterion":"Analysis of participation skills","marks":6,"descriptor":"Uses question types and the acknowledge-concern-reason-invite structure to show how participation raises quality."},{"criterion":"Treatment of conduct and integrity","marks":4,"descriptor":"Covers honest sourcing, fair credit, confidentiality and respect, and notes institutional policy as authoritative."},{"criterion":"Critical evaluation and structure","marks":5,"descriptor":"Considers the opposing view, reaches a balanced judgement and writes in a clear academic structure."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('40d2f529-dbb3-5ae6-bcd5-6f88bfc6924e', '{}'::jsonb, 'Examiners look for a reasoned position rather than a list of tips, specific reference to question types and conduct standards, and recognition that the department''s rules are the authority.', 'A strong essay argues that seminars are designed as collective inquiry, so quality is shared between presenter and audience. It begins by defining a seminar as a reasoned argument offered for testing, unlike a lecture that transmits settled knowledge. The educational purposes, which include synthesis, oral argument, critical listening and preparation for the dissertation, depend on responses: a presenter cannot practise defending a claim if nobody tests it.

The essay should explain how audience members raise quality through preparation and well-formed clarifying and probing questions, and how discussants act as critical friends. Disagreement should be structured, for instance by acknowledging the claim, stating a precise concern, giving a reason and inviting a response, which keeps debate on arguments rather than persons. Conduct matters to everyone: honest acknowledgement of sources and data, fair credit in group work, confidentiality, inclusive behaviour and compliance with institutional policy, including policy on AI tools.

A balanced answer considers the counter-view that the presenter''s preparation sets the ceiling, since a poorly argued presentation limits what an audience can do. It concludes that preparation is necessary but not sufficient: the best learning arises when a well-prepared presenter meets a prepared, respectful and critical audience, and that responsibility is shared.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('845e99f8-75aa-5ebd-a861-91d1630ebc16', null, '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', 'd6e64b86-788a-5250-ba80-ff096b4bbadc', 'How does a seminar differ from a lecture?', 'A lecture mainly transmits settled knowledge; a seminar offers reasoned work as an argument that the audience questions and tests.', 'supplementary', 'csit-610/seminar-foundations/f61bb4fbe727', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1719303d-bfdc-595d-918a-de5cbce01420', null, '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', 'd6e64b86-788a-5250-ba80-ff096b4bbadc', 'Why should a presenter be able to state a one-sentence message?', 'Without a clear message the presentation becomes a tour of the literature. The sentence anchors every decision about which evidence and slides to include.', 'supplementary', 'csit-610/seminar-foundations/0ed30f27f0f7', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d74c8fcb-95cb-53b9-b4b2-af6efa31f554', null, '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', 'd6e64b86-788a-5250-ba80-ff096b4bbadc', 'Who sets the official seminar format, topic allocation, dates and assessment criteria?', 'The department. GradPath is supplementary, so confirm these with the course coordinator or supervisor rather than assuming them.', 'supplementary', 'csit-610/seminar-foundations/7b03fe82babc', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c484478c-e0d5-5fc2-9b19-fe87638f4c37', null, '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', 'd6e64b86-788a-5250-ba80-ff096b4bbadc', 'Why is acknowledging limitations rewarded in a seminar?', 'Seminars are judged on honest, evidence-based argument that can withstand challenge, so naming limits shows analysis and maturity rather than weakness.', 'supplementary', 'csit-610/seminar-foundations/15c3e3f4b801', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2b5ac3a2-a4b8-5047-9fac-99a497cf625e', null, '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', 'd6e64b86-788a-5250-ba80-ff096b4bbadc', 'What is backward planning and why use it?', 'Starting from the confirmed presentation date and allocating time backwards for reading, drafting, slides, rehearsals and a buffer, so the fixed deadline is met realistically.', 'supplementary', 'csit-610/seminar-foundations/92560b632e45', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('178ef791-f429-5374-8592-cd1e20ffb3ec', null, '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', 'd6e64b86-788a-5250-ba80-ff096b4bbadc', 'Name three abilities a seminar develops that reading and writing alone do not.', 'Synthesis under time pressure, oral argument, and critical listening (also scholarly community and dissertation preparation).', 'supplementary', 'csit-610/seminar-foundations/a07942c2c9e2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9b4b0566-96d9-5070-a669-483e017207c9', null, '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', '48d323c6-e68e-54b7-b4aa-104503a1db52', 'What is the role of a discussant?', 'A critical friend who summarises the work fairly, identifies strengths, raises a few substantive issues and suggests improvements.', 'supplementary', 'csit-610/seminar-foundations/765509233a80', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('cea19615-4fe3-52bf-9065-00646ad3c7ef', null, '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', '48d323c6-e68e-54b7-b4aa-104503a1db52', 'What are the four steps of a respectful disagreement?', 'Acknowledge the point accurately, state the concern precisely, give the reason or evidence, and invite a response.', 'supplementary', 'csit-610/seminar-foundations/61c7b7fef844', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('14682e20-dbf3-59ee-8e17-34e5db3987c7', null, '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', '48d323c6-e68e-54b7-b4aa-104503a1db52', 'How does a probing question differ from a clarifying question?', 'A clarifying question removes ambiguity about what was said; a probing question tests the evidence, reasoning or assumptions behind it.', 'supplementary', 'csit-610/seminar-foundations/4e480d588591', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('678d3fa5-31dd-5eeb-ab76-6fa5589888ee', null, '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', '48d323c6-e68e-54b7-b4aa-104503a1db52', 'Is it plagiarism to present someone else''s slides or analysis as your own in a spoken seminar?', 'Yes. Plagiarism concerns presenting another person''s work as your own in any medium, so spoken and slide-based borrowing must be acknowledged.', 'supplementary', 'csit-610/seminar-foundations/361ecf22e9b2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8b6d9058-e7a4-5087-a8d1-168f299ed223', null, '7b687631-8925-5aa4-a415-6ed134a64891', '464a2054-a68c-59e7-a7d3-99aeda8b504a', '48d323c6-e68e-54b7-b4aa-104503a1db52', 'What does the principle of charity ask you to do before criticising an argument?', 'Interpret it in its strongest reasonable form, so that you challenge what the speaker actually means, not a weak version of it.', 'supplementary', 'csit-610/seminar-foundations/e4778e2b9a37', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
