insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('c06717ce-0e2d-5378-955b-1742b47f7495', '7b687631-8925-5aa4-a415-6ed134a64891', 'topic-and-literature', 'Topic, Literature and Critical Analysis', 'Choosing a workable topic, finding and evaluating literature, and building a critical argument from it.', 2, true)
