insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2dc361ed-d7fa-59c1-b266-8dd0bd6a1c5b', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'csit-610/topic-and-literature/q01', 'mcq', 'understand', 'easy', 'Distinguish a topic from a research question', 'Which of the following is a focused analytical question rather than a topic?', null, null, '[{"id":"a","text":"Cybersecurity in banks"},{"id":"b","text":"Banks and technology"},{"id":"c","text":"To what extent does staff awareness training reduce phishing incidents in financial institutions, according to the available evidence?"},{"id":"d","text":"Digital transformation"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
