insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2dc361ed-d7fa-59c1-b266-8dd0bd6a1c5b', '{"option":"c"}'::jsonb, 'A topic names an area, whereas a question demands a specific, answerable response and invites argument. The third option specifies an intervention, outcome and evidence base. The others are broad areas.', null)
