insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('187a15f1-aba1-5504-8779-ae621f5deb5d', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'csit-610/topic-and-literature/q02', 'true_false', 'understand', 'easy', 'Understand the value of a working thesis', 'A working thesis should be abandoned if later reading suggests it is incorrect.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
