insert into public.question_keys (question_id, correct, explanation, model_answer) values ('187a15f1-aba1-5504-8779-ae621f5deb5d', '{"value":false}'::jsonb, 'A working thesis is a provisional answer that may be confirmed, qualified or revised in light of evidence. Revising it is a sign of good scholarship, not failure. Abandoning the question altogether is not required.', null)
