insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('170531d9-6e0b-5221-8c63-f8b97fba3003', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'csit-610/topic-and-literature/q03', 'matching', 'recall', 'medium', 'Match narrowing dimensions with examples', 'Match each narrowing dimension with an example.', null, null, '{"left":[{"id":"l1","text":"Who"},{"id":"l2","text":"Where"},{"id":"l3","text":"Which technology"},{"id":"l4","text":"Which perspective"}],"right":[{"id":"r1","text":"Small retailers"},{"id":"r4","text":"Regulator"},{"id":"r2","text":"Urban Ghana"},{"id":"r3","text":"Mobile money"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
