insert into public.question_keys (question_id, correct, explanation, model_answer) values ('170531d9-6e0b-5221-8c63-f8b97fba3003', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Narrowing a topic along these dimensions turns a broad field such as digital payments into a focused, researchable question. Too many constraints can leave too little literature, so balance is needed.', null)
