insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('95b2edaa-539e-55b4-bf67-0fc6e8c9cdc7', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'csit-610/topic-and-literature/q04', 'scenario', 'apply', 'medium', 'Apply the topic tests', 'Which test does the candidate topic most clearly fail?', 'Illustrative scenario. A student wants to present on "e-commerce". A quick scholarly search returns many thousands of results across dozens of subtopics.', null, '[{"id":"a","text":"Interest"},{"id":"b","text":"Scope"},{"id":"c","text":"Spelling"},{"id":"d","text":"Referencing"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('95b2edaa-539e-55b4-bf67-0fc6e8c9cdc7', '{"option":"b"}'::jsonb, 'A whole field cannot be treated well in a short seminar, so the topic fails on scope. It should be narrowed by population, setting, aspect or perspective. Interest might be high, and spelling and referencing are not topic tests.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3e0b7c9f-28d3-5407-b5a9-b2c28bf778c3', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'csit-610/topic-and-literature/q05', 'short_answer', 'recall', 'easy', 'Recall the term for deliberate exclusions', 'What term describes a deliberate choice to exclude certain areas to keep a study manageable?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3e0b7c9f-28d3-5407-b5a9-b2c28bf778c3', '{"answers":["delimitation","delimitations","scope delimitation"]}'::jsonb, 'Delimitations state what the work will not cover, which manages audience expectations. They differ from limitations, which are weaknesses arising from the design or evidence.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('35dcd79a-df28-5bbf-b013-efa181f598e2', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'csit-610/topic-and-literature/q06', 'mcq', 'analyse', 'hard', 'Analyse the trade-off in narrowing', 'Why can adding too many constraints to a topic become a problem?', null, null, '[{"id":"a","text":"It makes the topic more interesting"},{"id":"b","text":"It may leave too little literature to support an argument"},{"id":"c","text":"It removes the need for a question"},{"id":"d","text":"It guarantees a new gap"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('35dcd79a-df28-5bbf-b013-efa181f598e2', '{"option":"b"}'::jsonb, 'Each constraint reduces the number of directly relevant sources. A topic narrowed too far may have insufficient evidence, so the student must balance focus against availability, perhaps drawing on adjacent contexts with clear caveats.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9619ec18-0a1e-58e4-9637-180f7fbbc79f', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'csit-610/topic-and-literature/q07', 'scenario', 'evaluate', 'hard', 'Evaluate handling of thin local evidence', 'Which approach is most academically sound?', 'Illustrative scenario. A student wants to examine algorithmic credit scoring in Ghana. She finds substantial international evidence but very little Ghana-specific research.', null, '[{"id":"a","text":"Present international findings as if they describe Ghana"},{"id":"b","text":"Frame the question internationally, use Ghana as an illustration and state clearly where local evidence is thin"},{"id":"c","text":"Abandon the topic entirely"},{"id":"d","text":"Invent plausible Ghana statistics to fill the gap"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9619ec18-0a1e-58e4-9637-180f7fbbc79f', '{"option":"b"}'::jsonb, 'Being transparent about what is known locally and what is extrapolated protects credibility. Presenting foreign findings as local ones is overclaiming, and fabricating statistics is a serious integrity breach. Abandoning the topic is unnecessary.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7335215b-0712-5249-9229-d2f306b77f0f', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'csit-610/topic-and-literature/q08', 'true_false', 'apply', 'medium', 'Apply feasibility judgement', 'A topic requiring confidential company data that the student cannot lawfully obtain should be revised or reframed.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7335215b-0712-5249-9229-d2f306b77f0f', '{"value":true}'::jsonb, 'Feasibility includes access to data and permission to use it. A topic that depends on unobtainable or confidential information is risky, so it should be reframed around accessible evidence.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ee497eb9-a8e9-579c-94a5-9a6b9d849169', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '438c1efd-01db-55f2-8995-e88b165e3319', 'csit-610/topic-and-literature/q09', 'mcq', 'understand', 'easy', 'Understand Boolean operators', 'In a search string, what is the main purpose of OR?', null, null, '[{"id":"a","text":"To narrow results to documents containing all terms"},{"id":"b","text":"To join synonyms so that documents matching any of them are retrieved"},{"id":"c","text":"To exclude a term"},{"id":"d","text":"To sort results by date"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ee497eb9-a8e9-579c-94a5-9a6b9d849169', '{"option":"b"}'::jsonb, 'OR widens a search by joining alternative terms for the same concept, whereas AND combines different concepts and narrows results. NOT excludes terms.', null)
