insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3bbc3e20-576c-5e47-9593-bcca9fa2c73d', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '438c1efd-01db-55f2-8995-e88b165e3319', 'csit-610/topic-and-literature/q10', 'matching', 'recall', 'medium', 'Match source types with descriptions', 'Match each source type with its description.', null, null, '{"left":[{"id":"l1","text":"Primary source"},{"id":"l2","text":"Secondary source"},{"id":"l3","text":"Grey literature"},{"id":"l4","text":"Citation chaining"}],"right":[{"id":"r1","text":"Reports original research or first-hand data"},{"id":"r4","text":"Finding sources through reference lists and later citing works"},{"id":"r2","text":"Analyses or summarises primary sources"},{"id":"r3","text":"Material from organisations and regulators outside commercial academic publishing"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
