insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e6bc83b5-60aa-5398-9bc5-be36894ac56c', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '438c1efd-01db-55f2-8995-e88b165e3319', 'csit-610/topic-and-literature/q11', 'true_false', 'understand', 'medium', 'Understand limits of peer review', 'If an article is peer reviewed, its findings can be assumed to be correct.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
