insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('142d0835-3a18-56a0-9cc0-6132d9b6bae9', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '438c1efd-01db-55f2-8995-e88b165e3319', 'csit-610/topic-and-literature/q12', 'scenario', 'apply', 'medium', 'Apply source evaluation to vendor material', 'How should the student use this source?', 'Illustrative scenario. A consultancy white paper, published by a company that sells analytics software, claims large performance gains for firms that adopt analytics but does not explain its method.', null, '[{"id":"a","text":"As neutral proof of the gains"},{"id":"b","text":"As evidence of what vendors claim, noting its commercial purpose and unclear method"},{"id":"c","text":"Not at all, under any circumstances"},{"id":"d","text":"As the main basis for the whole argument"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('142d0835-3a18-56a0-9cc0-6132d9b6bae9', '{"option":"b"}'::jsonb, 'Such a source can illustrate industry claims but should be flagged for its purpose and weak method. It should not be treated as neutral evidence or as the main basis of an argument. Whether to cite it at all depends on the argument, but it need not be banned.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('027616ef-70f5-51e9-848c-c8fb31179fc2', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '438c1efd-01db-55f2-8995-e88b165e3319', 'csit-610/topic-and-literature/q13', 'short_answer', 'recall', 'easy', 'Recall the term for tracing references forwards', 'What is the technique called of following a paper''s reference list backwards and its citing papers forwards?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
