insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('545cd9b2-9cd3-5f81-9374-1a0f30aa3c39', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '438c1efd-01db-55f2-8995-e88b165e3319', 'csit-610/topic-and-literature/q14', 'mcq', 'analyse', 'hard', 'Analyse poor search results', 'A student''s search returns very few relevant results. Which diagnosis is most likely and useful?', null, null, '[{"id":"a","text":"The topic cannot be researched"},{"id":"b","text":"The search terms may be too narrow or may not match the vocabulary authors use, so synonyms should be added"},{"id":"c","text":"The database is always faulty"},{"id":"d","text":"Boolean operators should never be used"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('545cd9b2-9cd3-5f81-9374-1a0f30aa3c39', '{"option":"b"}'::jsonb, 'Few relevant results often reflect narrow terms or different vocabulary, so adding synonyms with OR and checking the terms used in known papers helps. It does not necessarily mean the topic is unresearchable.', null)
