insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a82ed104-205c-5ee6-8fb3-2f3945e12c5f', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '438c1efd-01db-55f2-8995-e88b165e3319', 'csit-610/topic-and-literature/q15', 'scenario', 'evaluate', 'hard', 'Evaluate a statistic encountered in a news article', 'What is the best course of action?', 'Illustrative scenario. A student finds an impressive percentage about digital payment use in a social media post that cites no source.', null, '[{"id":"a","text":"Use it because it is widely shared"},{"id":"b","text":"Trace it to the original organisation and release, and omit it if it cannot be verified"},{"id":"c","text":"Round it to a safer figure and use it"},{"id":"d","text":"Cite the social media post as the authority"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
