insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b7b96ad0-b0dd-5abb-8f2c-c3b1c2109a75', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '4cabb8f6-f69c-5ad4-9346-68ea870cfa00', 'csit-610/topic-and-literature/q17', 'mcq', 'understand', 'easy', 'Understand critical analysis', 'In an academic sense, what does "critical" mean?', null, null, '[{"id":"a","text":"Finding as many faults as possible"},{"id":"b","text":"Judging the strength and limits of claims, evidence and reasoning in a balanced way"},{"id":"c","text":"Rejecting all sources"},{"id":"d","text":"Summarising each source in turn"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b7b96ad0-b0dd-5abb-8f2c-c3b1c2109a75', '{"option":"b"}'::jsonb, 'Critical analysis is balanced judgement, including recognising strengths. It is not fault-finding, wholesale rejection or description.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2c7af5ee-2d36-51cc-a633-8701403d9755', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '4cabb8f6-f69c-5ad4-9346-68ea870cfa00', 'csit-610/topic-and-literature/q18', 'matching', 'recall', 'medium', 'Match Toulmin components', 'Match each Toulmin component with its meaning.', null, null, '{"left":[{"id":"l1","text":"Claim"},{"id":"l2","text":"Grounds"},{"id":"l3","text":"Warrant"},{"id":"l4","text":"Rebuttal"}],"right":[{"id":"r2","text":"The facts or data offered in support"},{"id":"r1","text":"What you want the audience to accept"},{"id":"r3","text":"The principle linking the grounds to the claim"},{"id":"r4","text":"The conditions under which the claim would not hold"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
