insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0cf3af03-d66c-5d01-8224-7bbc697bbbbf', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '4cabb8f6-f69c-5ad4-9346-68ea870cfa00', 'csit-610/topic-and-literature/q19', 'scenario', 'analyse', 'medium', 'Identify a fallacy', 'Which weakness is most evident?', 'Illustrative scenario. A cross-sectional survey finds that firms with higher analytics use report higher sales. The author concludes that analytics "causes" higher sales.', null, '[{"id":"a","text":"Hasty generalisation from one anecdote"},{"id":"b","text":"Correlation presented as causation"},{"id":"c","text":"Straw man"},{"id":"d","text":"False dichotomy"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0cf3af03-d66c-5d01-8224-7bbc697bbbbf', '{"option":"b"}'::jsonb, 'A cross-sectional association does not show direction or cause. Successful firms may simply be more able to afford analytics. A causal claim would need stronger design or additional reasoning.', null)
