insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1e0e3e3a-0874-526f-aff4-60ef585edd98', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '4cabb8f6-f69c-5ad4-9346-68ea870cfa00', 'csit-610/topic-and-literature/q21', 'short_answer', 'recall', 'easy', 'Recall the tool used to compare sources by theme', 'What is the table called that lists sources against themes to reveal patterns and gaps?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
