insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('099fe9c2-aba3-5960-a4bc-c4b88bc6bd3b', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '4cabb8f6-f69c-5ad4-9346-68ea870cfa00', 'csit-610/topic-and-literature/q22', 'mcq', 'evaluate', 'hard', 'Evaluate proportionate conclusions', 'Evidence consists of three cross-sectional surveys with self-reported measures. Which conclusion is best calibrated?', null, null, '[{"id":"a","text":"The evidence proves that the practice causes better performance"},{"id":"b","text":"The evidence suggests an association, but the case for a causal effect remains weak because of the designs and self-reporting"},{"id":"c","text":"The evidence shows the practice is useless"},{"id":"d","text":"Nothing can be said"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('099fe9c2-aba3-5960-a4bc-c4b88bc6bd3b', '{"option":"b"}'::jsonb, 'The wording should match the strength of the evidence. Surveys can indicate association, and self-reports may be biased, so the second option is proportionate. The others overclaim, dismiss the evidence or say nothing.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f7559630-acf0-58f1-89f5-2e8f1685cc98', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '4cabb8f6-f69c-5ad4-9346-68ea870cfa00', 'csit-610/topic-and-literature/q23', 'scenario', 'evaluate', 'hard', 'Evaluate the response to conflicting evidence', 'What is the most defensible course?', 'Illustrative scenario. Four studies support a student''s working thesis, but one well-designed study contradicts it. She plans to leave the contradicting study out.', null, '[{"id":"a","text":"Leave it out because most studies agree"},{"id":"b","text":"Include it, explain possible reasons for the difference and qualify the thesis accordingly"},{"id":"c","text":"Replace the thesis with its opposite"},{"id":"d","text":"Mention it without comment"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f7559630-acf0-58f1-89f5-2e8f1685cc98', '{"option":"b"}'::jsonb, 'Omitting conflicting evidence is cherry-picking. Addressing it, and testing explanations such as different populations or measures, strengthens credibility and may refine the thesis. Reversing the thesis is not justified by one study, and mentioning it without comment adds nothing.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('95e3bd2f-f00c-54d6-8746-a8b399498627', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '4cabb8f6-f69c-5ad4-9346-68ea870cfa00', 'csit-610/topic-and-literature/q24', 'true_false', 'apply', 'medium', 'Apply the lesson from the Reinhart-Rogoff episode', 'The public discussion of the Reinhart and Rogoff growth-and-debt paper shows that a widely cited source can contain errors and that transparency of data and method allows others to test claims.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('95e3bd2f-f00c-54d6-8746-a8b399498627', '{"value":true}'::jsonb, 'In 2013 Herndon, Ash and Pollin reported errors and questionable choices after attempting to replicate the analysis, and the authors acknowledged a coding error. The episode shows why authority alone is not enough and why proportionate judgement is needed about how much an error changes a conclusion.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('41106927-9ac0-5c12-8b7c-1ccfb005c286', '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', null, 'csit-610/topic-and-literature/q25', 'case_analysis', 'evaluate', 'hard', 'Evaluate a seminar plan from topic to argument', 'Critically evaluate Efua''s seminar plan and recommend specific improvements to her topic, literature search and argument.', null, 'Illustrative scenario. Efua, an MSc IT for Business student, has chosen the topic "Technology in Ghanaian business". She searched Google Scholar once, using the phrase "technology Ghana business", and chose the first ten results, including a software vendor''s white paper and a blog post. Her slides summarise each source in turn. Her conclusion states that "technology clearly improves business performance in Ghana", and she quotes a percentage from a social media post without a source. She has not considered any evidence that contradicts her conclusion.', null, 20, array['Overall assessment of the plan', 'Topic scope and question', 'Search strategy and source quality', 'Synthesis and critical analysis', 'Argument, qualification and use of statistics', 'Prioritised recommendations']::text[], '[{"criterion":"Topic and question","marks":4,"descriptor":"Identifies that the topic is a whole field and proposes narrowing by population, aspect and perspective into an analytical question with a working thesis."},{"criterion":"Literature search and source evaluation","marks":5,"descriptor":"Criticises the single-phrase search, reliance on first results and unevaluated vendor and blog sources; recommends concepts, synonyms, Boolean strings, citation chaining and appraisal."},{"criterion":"Critical analysis and synthesis","marks":5,"descriptor":"Explains that source-by-source summary is not synthesis and recommends a synthesis matrix, thematic organisation and treatment of conflicting evidence."},{"criterion":"Argument and integrity","marks":6,"descriptor":"Identifies overclaiming, correlation as causation and the untraceable statistic; recommends Toulmin-style argument with qualifier and rebuttal and verification or omission of the figure."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('41106927-9ac0-5c12-8b7c-1ccfb005c286', '{}'::jsonb, 'Examiners reward answers that link each weakness to a specific consequence for credibility and propose concrete, ordered remedies rather than generic advice.', 'A strong answer observes that Efua''s plan has the surface features of research but lacks the discipline that makes an argument credible. Her topic is a whole field. She should narrow it, for example to the effect of a specific technology on a defined group of firms, and pose an analytical question such as how strong the available evidence is for that effect, with a provisional thesis to test.

Her search is thin: a single phrase and the first ten results. She should list concepts and synonyms, build Boolean strings, use more than one source, chain citations forwards and backwards and screen against written criteria. Her sources are unevenly credible. The vendor white paper has a commercial purpose and should be cited, if at all, as evidence of vendor claims; the blog post is not suitable for factual claims. Each retained source needs appraisal of method, sample, context and limitations.

Source-by-source summary is description, not synthesis. A synthesis matrix would let her compare findings by theme and explain disagreement. Her conclusion overclaims: "clearly improves" is not warranted by uncontrolled evidence, and she should qualify it and state a rebuttal. The percentage from a social media post must be traced to its original source or omitted, since unverified statistics damage credibility. She should also seek and discuss contradictory evidence and be honest about the lack of Ghana-specific data if that is the case.

The recommendations, in priority order, are to narrow the question, redo the search, appraise and synthesise, then restate the argument with proportionate qualification.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c0b65414-b5f9-596a-99ca-75b8db8cc8c3', null, '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'What is the difference between a topic and a research question?', 'A topic names an area of interest; a question is focused and answerable, demanding a specific response that can be argued.', 'supplementary', 'csit-610/topic-and-literature/a3c52e7f7cde', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b009b7c6-26f6-5509-8d52-3f80221a112f', null, '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'What five tests help judge a candidate topic?', 'Scope, significance, evidence availability, feasibility and interest.', 'supplementary', 'csit-610/topic-and-literature/3f1ccf0a3af9', true)
