insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('570b9744-fc2a-55a0-b37e-0b5631100be9', null, '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'Why prefer analytical or evaluative questions to descriptive ones at postgraduate level?', 'They invite argument and judgement about evidence, whereas descriptive questions only invite a report of what exists.', 'supplementary', 'csit-610/topic-and-literature/7879b6cf7f3e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('94d4d778-1e8f-53c5-93e0-b7096c535d97', null, '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'What is a working thesis?', 'A provisional answer to your question that directs reading and may be confirmed, qualified or rejected as evidence is found.', 'supplementary', 'csit-610/topic-and-literature/06a873d0411b', true)
