insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('49ccc01a-c769-552a-987c-03c682798eae', null, '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'What is the risk of narrowing a topic too far?', 'Too few directly relevant sources may exist to support an argument, so focus must be balanced against evidence availability.', 'supplementary', 'csit-610/topic-and-literature/25f723c9ec78', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('33c3987a-69f1-5d01-8dc8-c02c19774ffb', null, '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '69d06160-5476-5278-8d59-2b1212572290', 'How should you handle a Ghana-focused topic when local evidence is thin?', 'Say so openly, separate Ghana-specific evidence from international evidence used by extension, and never fill gaps with unverified figures.', 'supplementary', 'csit-610/topic-and-literature/d041e3f9b11a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('183345bd-48e8-593d-9a5c-7d281cea460c', null, '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '438c1efd-01db-55f2-8995-e88b165e3319', 'How do AND and OR work in a literature search?', 'OR joins synonyms for one concept and widens results; AND combines different concepts and narrows results.', 'supplementary', 'csit-610/topic-and-literature/2598e031a899', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
