insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b7f424b5-c355-5162-928a-138bea34796d', null, '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '438c1efd-01db-55f2-8995-e88b165e3319', 'What should you do with a statistic you cannot trace to its original source?', 'Do not use it. Repetition is not verification, so trace it to the originating organisation and release or omit it.', 'supplementary', 'csit-610/topic-and-literature/e3a2110d57f8', true)
