insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c2117217-4e2f-5287-9d1b-825d62a4bc8f', null, '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '438c1efd-01db-55f2-8995-e88b165e3319', 'What signals that a seminar literature search is sufficient?', 'Saturation: new searches mostly return the same studies and arguments, and you can say what is known, disputed and missing.', 'supplementary', 'csit-610/topic-and-literature/d0c3fa52d3b9', true)
