insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e75876b9-c63d-59c8-9cfc-491e1c5b483a', null, '7b687631-8925-5aa4-a415-6ed134a64891', 'c06717ce-0e2d-5378-955b-1742b47f7495', '438c1efd-01db-55f2-8995-e88b165e3319', 'What should notes on each source include?', 'Full APA 7 reference, purpose, method and sample, findings in your own words, strengths and limitations, relevance to your argument, and page numbers for any quotations.', 'supplementary', 'csit-610/topic-and-literature/86c10f7c920f', true)
