insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f7d30837-f4ac-53db-9da6-fff9a41ca3cc', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'csit-610/preparing-the-presentation/q01', 'mcq', 'understand', 'easy', 'Explain why spoken presentations need a different structure from written papers', 'Why does a seminar presentation usually need more explicit signposting than a written paper?', null, null, '[{"id":"a","text":"Listeners hear each sentence once at the speaker''s pace and cannot re-read or skim ahead"},{"id":"b","text":"Examiners award marks for the number of transitions used"},{"id":"c","text":"Written papers never use headings or summaries"},{"id":"d","text":"Slides replace the need for any spoken structure"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f7d30837-f4ac-53db-9da6-fff9a41ca3cc', '{"option":"a"}'::jsonb, 'A reader can pause, re-read and see the headings, but a listener relies on the speaker to make the structure audible. The other options are false or unsupported; signposting is valued for its function, not counted, and slides do not remove the need for spoken previews and links.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('dbc8cbff-c79d-5511-8f63-e877a360ae20', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'csit-610/preparing-the-presentation/q02', 'true_false', 'understand', 'easy', 'Recognise the value of repetition in a spoken argument', 'Restating the central claim in the opening, the body and the closing of a talk is usually a weakness because it wastes time.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('dbc8cbff-c79d-5511-8f63-e877a360ae20', '{"value":false}'::jsonb, 'In a written essay repetition is often padding, but in a talk it gives listeners who lost attention a chance to rejoin the argument. The claim should be restated in different words and linked to the new evidence, not copied mechanically.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ff0cb528-3b1a-533d-9d50-181871ba945e', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'csit-610/preparing-the-presentation/q03', 'scenario', 'apply', 'medium', 'Apply a timing plan with a buffer', 'What is the most appropriate response?', 'Illustrative scenario. A student has a 12-minute slot. A first rehearsal of the talk takes 11 minutes 50 seconds with no pauses for questions or technical delays.', null, '[{"id":"a","text":"Leave the talk as it is, because it fits inside the limit"},{"id":"b","text":"Speak faster on the day to create more time"},{"id":"c","text":"Cut content so that a rehearsed run takes roughly 10 to 11 minutes, leaving a buffer"},{"id":"d","text":"Add more slides so that the limit is used completely"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ff0cb528-3b1a-533d-9d50-181871ba945e', '{"option":"c"}'::jsonb, 'Nerves, a brief clarifying question or a technical hiccup can easily add a minute or more, so a rehearsal that fills the whole slot leaves no margin. Speaking faster reduces comprehension, and adding slides worsens the problem. Cutting content protects the conclusion.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4f7d2c43-6bc9-59b9-a8e4-cae4179164b4', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'csit-610/preparing-the-presentation/q04', 'short_answer', 'recall', 'easy', 'Recall the term for cues that tell the audience where the talk is going', 'What term describes spoken or visual cues that tell the audience where a talk has been and where it is going?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4f7d2c43-6bc9-59b9-a8e4-cae4179164b4', '{"answers":["signposting","signpost","sign posting"]}'::jsonb, 'Signposting includes previews, markers, summaries and links. It makes the structure of the talk audible and visible so that listeners do not have to guess where they are.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e05375dc-1d39-51f2-84bc-f1f3caa65ae4', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'csit-610/preparing-the-presentation/q05', 'matching', 'understand', 'medium', 'Distinguish the main forms of signposting', 'Match each signposting move with the example that illustrates it.', null, null, '{"left":[{"id":"l1","text":"Preview"},{"id":"l2","text":"Marker"},{"id":"l3","text":"Summary"},{"id":"l4","text":"Link"}],"right":[{"id":"r3","text":"So far I have shown that adoption is driven mostly by perceived usefulness."},{"id":"r2","text":"That was the first position. The second takes the opposite view."},{"id":"r4","text":"Given that gap, the next question is how researchers have measured trust."},{"id":"r1","text":"I will make three points: what the literature agrees on, where it disagrees, and what that means for small firms."}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e05375dc-1d39-51f2-84bc-f1f3caa65ae4', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each move does a different job: a preview announces the route, a marker flags a boundary, a summary consolidates what has been shown, and a link explains why the next section follows. Good transitions combine marker and link so that they carry logic.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('29d94e24-5a8a-5a0f-915e-7ea2abd405e1', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'csit-610/preparing-the-presentation/q06', 'mcq', 'evaluate', 'hard', 'Evaluate a draft outline for focus and coherence', 'A draft outline lists nine headings, including a long history of the technology, five theories and a catalogue of country studies, but no stated claim. What is the best first improvement?', null, null, '[{"id":"a","text":"Add a ninth slide listing all the references"},{"id":"b","text":"Write a one-sentence central claim and test every section against it, moving what does not support it to backup slides"},{"id":"c","text":"Reorder the headings alphabetically"},{"id":"d","text":"Reduce the font size so that all nine headings fit on fewer slides"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('29d94e24-5a8a-5a0f-915e-7ea2abd405e1', '{"option":"b"}'::jsonb, 'A talk with no claim is a list of topics. Writing the claim first gives a test for inclusion. Reordering, shrinking text and adding references do not address the lack of focus, and shrinking text harms legibility.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('98c3a114-31e4-5a9d-81de-2c870cba0220', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'csit-610/preparing-the-presentation/q07', 'true_false', 'apply', 'medium', 'Apply good practice for the closing of a talk', 'A good closing introduces one or two new pieces of evidence to leave a strong final impression.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('98c3a114-31e4-5a9d-81de-2c870cba0220', '{"value":false}'::jsonb, 'The closing should restate the claim in light of the evidence, state limitations, draw out implications and deliver the take-home message. New evidence at the end is unsupported and cannot be questioned fairly, and it tends to dilute the main message.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6d3974b8-4742-58be-b50c-c6561e160cd6', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'csit-610/preparing-the-presentation/q08', 'mcq', 'understand', 'easy', 'Explain the role of slides as support for a spoken argument', 'Which statement best describes the purpose of slides in a seminar?', null, null, '[{"id":"a","text":"To contain the full text of the speech so the audience can read it"},{"id":"b","text":"To show what is hard to say and easy to show, while the speaker provides reasoning and interpretation"},{"id":"c","text":"To prove that the presenter has read many sources"},{"id":"d","text":"To replace the reference list"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6d3974b8-4742-58be-b50c-c6561e160cd6', '{"option":"b"}'::jsonb, 'Slides carry figures, diagrams, structure and key terms; speech carries reasoning and qualification. Putting the full speech on slides creates redundancy, with the audience reading while the speaker reads aloud, which competes for attention.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4e0dc2f6-769f-52fd-8c30-17f246b43d66', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'csit-610/preparing-the-presentation/q09', 'scenario', 'analyse', 'medium', 'Identify misleading design choices in a chart', 'Which problem is the most serious for the honest communication of the evidence?', 'Illustrative scenario. A bar chart compares the average satisfaction scores of two systems, 7.1 and 7.3 on a 10-point scale. The value axis runs from 7.0 to 7.4, so the second bar appears three times as tall as the first. The axis has no label and the chart has no source line.', null, '[{"id":"a","text":"The chart uses bars instead of a table"},{"id":"b","text":"The truncated axis exaggerates a very small difference"},{"id":"c","text":"The scores are shown to one decimal place"},{"id":"d","text":"The chart compares only two systems"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4e0dc2f6-769f-52fd-8c30-17f246b43d66', '{"option":"b"}'::jsonb, 'Bar length should be proportional to value, so a baseline that does not start at zero makes a 0.2 difference look dramatic. The missing axis label and source are also faults, but the truncation most directly distorts the viewer''s conclusion. Bars, one decimal place and two categories are acceptable.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8cf0f48c-0f83-5ae3-947a-689e3f065347', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'csit-610/preparing-the-presentation/q10', 'mcq', 'apply', 'medium', 'Select an appropriate visual for a type of evidence', 'A presenter wants to show how adoption intention changed across five consecutive years for three firm sizes. Which visual is most suitable?', null, null, '[{"id":"a","text":"A three-dimensional pie chart for each year"},{"id":"b","text":"A line chart with one line per firm size and labelled axes"},{"id":"c","text":"A paragraph of text on the slide"},{"id":"d","text":"A scatter plot with years on both axes"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8cf0f48c-0f83-5ae3-947a-689e3f065347', '{"option":"b"}'::jsonb, 'Change over time is shown most clearly by a line chart, and three lines remain readable. Pie charts show parts of a whole and their 3D effects distort size, text hides the pattern, and a scatter plot with years on both axes shows no relationship between variables.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('34a1b9d1-7b7c-57e9-bd43-c80834b4a934', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'csit-610/preparing-the-presentation/q11', 'true_false', 'recall', 'easy', 'Recall accessibility practice for colour use', 'Using colour alone to distinguish categories in a chart is good accessibility practice as long as the colours are bright.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('34a1b9d1-7b7c-57e9-bd43-c80834b4a934', '{"value":false}'::jsonb, 'Some viewers have colour vision deficiency, and slides are sometimes printed in greyscale or projected poorly. Categories should also be distinguished by labels, patterns or shapes. Brightness does not solve the problem.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9a2aa677-10f5-5979-a5ac-d421756f3f1c', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'csit-610/preparing-the-presentation/q12', 'short_answer', 'recall', 'medium', 'Recall the term for text that describes a visual to people who cannot see it', 'What short text description of an image or chart is supplied for screen reader users?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9a2aa677-10f5-5979-a5ac-d421756f3f1c', '{"answers":["alternative text","alt text","alt-text"]}'::jsonb, 'Alternative text states the content and finding of a visual in words. It is a basic requirement of accessible documents, and writing it also forces you to decide what your visual is meant to show.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('fba5f0a5-5636-59a6-ac20-6a869baaa453', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'csit-610/preparing-the-presentation/q13', 'matching', 'understand', 'medium', 'Match types of evidence with suitable visuals', 'Match each type of evidence with the visual that usually suits it best.', null, null, '{"left":[{"id":"l1","text":"Comparison of a few categories"},{"id":"l2","text":"Change over time"},{"id":"l3","text":"Relationship between two numeric variables"},{"id":"l4","text":"Exact values that readers must look up"},{"id":"l5","text":"Steps in a process"}],"right":[{"id":"r2","text":"Line chart"},{"id":"r1","text":"Bar chart with a zero baseline"},{"id":"r4","text":"Table"},{"id":"r3","text":"Scatter plot"},{"id":"r5","text":"Flowchart"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('fba5f0a5-5636-59a6-ac20-6a869baaa453', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'The choice follows from the question the audience needs answered. Tables serve exact lookup while graphs serve pattern recognition, a distinction made by Few (2012). A scatter plot shows association but cannot establish causation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('044c9ce1-a151-501b-ae1f-a75468e210b8', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'csit-610/preparing-the-presentation/q14', 'scenario', 'apply', 'medium', 'Apply the orient, direct, interpret sequence', 'Which improvement best applies the orient, direct, interpret sequence?', 'Illustrative scenario. A presenter shows a bar chart of the barriers to digital payment adoption cited by retailers. She says, "Here is the chart," and then waits for the audience to find the pattern.', null, '[{"id":"a","text":"Say what the chart shows, point to the key bar, and explain what it means for the argument"},{"id":"b","text":"Show the chart for as short a time as possible"},{"id":"c","text":"Read out every value on the chart"},{"id":"d","text":"Add more bars so the audience has more to explore"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('044c9ce1-a151-501b-ae1f-a75468e210b8', '{"option":"a"}'::jsonb, 'A visual does not explain itself. Orienting tells the audience what the axes and groups are, directing points them to the feature that matters, and interpreting links it to the claim. Reading every value or hiding the chart fails to help the audience see the point.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('34b057a6-1289-5913-8bca-cc32c4994f8a', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'csit-610/preparing-the-presentation/q15', 'mcq', 'understand', 'easy', 'Distinguish what requires attribution in a presentation', 'Which of the following requires a citation on a slide?', null, null, '[{"id":"a","text":"A paraphrased idea taken from a journal article"},{"id":"b","text":"Your own opinion about the topic"},{"id":"c","text":"A definition so widely known that it is common knowledge"},{"id":"d","text":"Your own survey data presented as your own analysis"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('34b057a6-1289-5913-8bca-cc32c4994f8a', '{"option":"a"}'::jsonb, 'Paraphrased ideas, data, figures and structures from other authors need attribution even when no words are copied. Your own opinion and your own data need no citation, although the data source should be described, and genuinely common knowledge usually needs none.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('fe76fb0c-e702-528e-985c-5a0c62d97ae5', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'csit-610/preparing-the-presentation/q16', 'mcq', 'apply', 'medium', 'Apply APA 7 in-text citation conventions', 'A study by three or more authors, Venkatesh, Morris, Davis and Davis, was published in 2003. Which APA 7 in-text citation is correct?', null, null, '[{"id":"a","text":"(Venkatesh, Morris, Davis, & Davis, 2003)"},{"id":"b","text":"(Venkatesh et al., 2003)"},{"id":"c","text":"(Venkatesh 2003)"},{"id":"d","text":"(Venkatesh & others, 2003)"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('fe76fb0c-e702-528e-985c-5a0c62d97ae5', '{"option":"b"}'::jsonb, 'APA 7 uses the first author''s surname followed by "et al." from the first citation for works with three or more authors. Listing all authors, omitting the comma before the year, or writing "others" does not follow the style.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e735f468-0e58-5375-bfb2-c32bc65fe99f', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'csit-610/preparing-the-presentation/q17', 'scenario', 'evaluate', 'hard', 'Evaluate an integrity risk in a draft presentation', 'What should she do?', 'Illustrative scenario. A student''s draft slide reports that "about 80 per cent of small firms in the region have experienced a data breach". She remembers reading this on social media but cannot find the original source. She plans to keep the figure because it makes the point strongly.', null, '[{"id":"a","text":"Keep the figure and add \"(Anon., n.d.)\" so that it looks cited"},{"id":"b","text":"Keep the figure, since the exact origin does not matter if the point is true"},{"id":"c","text":"Remove the figure, or replace it with a statistic she can trace to a verified source, or a qualitative statement she can support"},{"id":"d","text":"Round the figure to 100 per cent to make it memorable"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e735f468-0e58-5375-bfb2-c32bc65fe99f', '{"option":"c"}'::jsonb, 'An untraceable statistic cannot be checked by the audience and risks fabrication or misrepresentation, and a placeholder citation is misleading. The honest options are to find and verify the original source or to make a claim the evidence supports. Altering the number makes the problem worse.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('97af4fc8-0b23-5151-9f57-1d661859c3a2', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'csit-610/preparing-the-presentation/q18', 'true_false', 'apply', 'medium', 'Apply image-licence checking', 'An image returned by a search engine can be used freely in a seminar presentation because it is publicly visible online.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('97af4fc8-0b23-5151-9f57-1d661859c3a2', '{"value":false}'::jsonb, 'Public availability is not permission. The image may be protected by copyright or carry licence conditions, such as a requirement to credit the creator. You should check the licence, record the creator and source, and credit the image appropriately.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b04da7bf-54d6-5086-8255-ba71e6b1b8c6', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'csit-610/preparing-the-presentation/q19', 'short_answer', 'recall', 'medium', 'Recall the term for restating an idea in your own words with a citation', 'What is the term for restating an author''s idea in your own words and sentence structure while still citing the source?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b04da7bf-54d6-5086-8255-ba71e6b1b8c6', '{"answers":["paraphrase","paraphrasing","a paraphrase"]}'::jsonb, 'A genuine paraphrase changes both wording and structure and still needs a citation, because the idea belongs to the source. Changing a few words while keeping the original structure is too close and should instead be quoted or properly rewritten.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('95ac3f38-3a29-5bc6-90ab-9fe942205587', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'csit-610/preparing-the-presentation/q20', 'matching', 'understand', 'medium', 'Match source-line wording to the status of a visual', 'Match each situation with the most appropriate source line.', null, null, '{"left":[{"id":"l1","text":"A figure reproduced unchanged from a published report"},{"id":"l2","text":"A figure you modified from a published diagram"},{"id":"l3","text":"A chart you drew from an organisation''s published data"},{"id":"l4","text":"A chart from your own survey"}],"right":[{"id":"r1","text":"Source: Author (Year), Figure 2."},{"id":"r4","text":"Source: author''s survey data (n = 120)."},{"id":"r2","text":"Adapted from Author (Year)."},{"id":"r3","text":"Data from Organisation (Year); author''s analysis."}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('95ac3f38-3a29-5bc6-90ab-9fe942205587', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'A source line tells the audience how your visual relates to the original. Claiming an adapted or reproduced figure as your own, or omitting the data origin, misleads the audience and can breach copyright or integrity rules.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0d3d92a3-4cdf-571f-9e48-fa21356486df', '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', null, 'csit-610/preparing-the-presentation/q21', 'case_analysis', 'evaluate', 'hard', 'Evaluate a draft presentation for structure, visual evidence and referencing', 'Critically evaluate Efosa''s draft seminar presentation and recommend specific changes to its structure, slides, visual evidence and referencing.', null, 'Illustrative scenario. Efosa has 15 minutes to present a literature-based seminar on cloud adoption by small firms in Ghana. His draft has 28 slides. The first six cover the history of cloud computing. Slide titles are topic labels such as "Theories" and "Results". Many slides contain full paragraphs in 14-point type. One slide shows a three-dimensional pie chart with eight slices in similar shades of blue, with no source. Another shows a screenshot from a client''s system including customer names. A statistic about "usage in Ghana" has no source. There is no stated claim, no conclusion slide and no reference slide. A trial run took 27 minutes.', null, 20, array['Overall assessment against the central claim and time limit', 'Structure, timing and signposting', 'Slide design, text and accessibility', 'Visual evidence and honest charting', 'Referencing and integrity, including personal data', 'Prioritised recommendations']::text[], '[{"criterion":"Structure and timing","marks":5,"descriptor":"Identifies the missing central claim, the disproportionate background, the overrun and the absent conclusion, and proposes a claim-first structure with a timing plan, buffer and backup slides."},{"criterion":"Slide design and accessibility","marks":5,"descriptor":"Identifies topic-label titles, dense text, small type and similar-shade colours; recommends action titles, minimal text, larger type, high contrast and colour-independent coding."},{"criterion":"Visual evidence","marks":5,"descriptor":"Explains the distortion and poor comparability of a 3D, many-slice pie chart, proposes a better chart, and recommends orient, direct, interpret delivery for each visual."},{"criterion":"Referencing and integrity","marks":5,"descriptor":"Identifies the unsourced statistic, the missing reference slide and the exposure of customer personal data; recommends verification, APA 7 citation, a source line and anonymisation or authority to use the data."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0d3d92a3-4cdf-571f-9e48-fa21356486df', '{}'::jsonb, 'Examiners look for diagnosis of specific faults, explanation of why each matters to the audience or to integrity, and concrete, prioritised remedies rather than generic advice to make the slides better.', 'A strong answer begins by noting that the draft lacks a central claim, which explains most of its other problems. With no claim to test content against, Efosa has included everything, producing 28 slides and a 27-minute run for a 15-minute slot. He should write a one-sentence claim, move the history of cloud computing to a backup slide, keep two or three body blocks with signposted transitions, plan roughly 12 to 13 minutes of content, and add a conclusion that restates the claim and states limitations.

On slide design, topic-label titles should become action titles that state the point, for example "Owner capability explains adoption better than cost". Paragraphs in small type should be reduced to short prompts, with reasoning moved to speech and notes, and type should be large enough to read from the back of the room.

The three-dimensional pie with eight similar blue slices distorts size, is hard to compare and cannot be read in greyscale. A sorted bar chart with a zero baseline, direct labels, one highlight colour and a source line would be better. Each visual should be introduced by saying what it shows, pointing to the key feature and interpreting it.

On integrity, the "usage in Ghana" statistic must be traced to a verified source or removed. A reference slide in consistent APA 7 style is required, with every in-text citation matched. The screenshot shows customer names, so it should be cropped or anonymised, and the presenter should consider the obligations on personal data, including the Data Protection Act, 2012 (Act 843), and obtain authority to use client material. The answer should end with prioritised actions: claim and cuts first, then slides, then charts, then referencing.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('7b7f4f27-93f9-528a-a435-edfb63c53c3d', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'Why must a presentation be built around a single central claim?', 'The claim gives a test for what to include. Every section should help the audience believe, understand or evaluate it; anything else goes to a backup slide.', 'supplementary', 'csit-610/preparing-the-presentation/a4912a793f8d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('71651f39-fa37-5784-bd25-6484b054d96b', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'What are the three parts of the basic presentation shape and roughly how is time split?', 'Opening (about 10 to 15 per cent), body (about 65 to 75 per cent) and closing (about 10 to 15 per cent). These proportions are a guide, not an official rule.', 'supplementary', 'csit-610/preparing-the-presentation/25c66d5365a6', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('421730ea-632c-55a2-96ab-b7a5602adc50', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'Name four signposting moves and give the job of each.', 'Preview (announce the route), marker (flag a boundary), summary (consolidate what has been shown) and link (explain why the next section follows).', 'supplementary', 'csit-610/preparing-the-presentation/6aa320abe4ff', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('14266314-2513-5824-942c-8f3275f1c862', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'Why is repetition of the main point a strength in a talk but a flaw in an essay?', 'Listeners cannot re-read, so restating the claim in the opening, body and closing lets anyone who lost attention rejoin the argument.', 'supplementary', 'csit-610/preparing-the-presentation/61b2a151c556', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2947733c-a562-556f-86be-fd02f6c24e8a', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'How should you build a timing plan, and what should you do if you rehearse over time?', 'Allocate minutes per section and keep a buffer of at least 10 per cent. If you overrun, cut content and protect the conclusion; do not speak faster.', 'supplementary', 'csit-610/preparing-the-presentation/2a1baae12dbc', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ecf13a06-020c-5e00-8596-9e0a388ec635', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'a7148d70-7495-5110-9c18-131afe2ccde9', 'What belongs in the closing of a presentation, and what does not?', 'Restate the claim in light of the evidence, state limitations, draw out implications and give the take-home message. Do not add new evidence or end on an apology.', 'supplementary', 'csit-610/preparing-the-presentation/41ca5a2487c8', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e7122789-cf8c-5f1a-859c-1e1a9cca0ecc', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'What should slides do that speech cannot easily do, and vice versa?', 'Slides show figures, diagrams, structure and key terms. Speech carries reasoning, qualification and interpretation.', 'supplementary', 'csit-610/preparing-the-presentation/a5026bb55d24', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f5b13424-337c-59d1-a293-6fe8f5debe87', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'What is an action title and why use one?', 'A slide title written as a short sentence stating the point, such as "Cost is the most cited barrier". It tells the audience what to take from the slide, unlike a topic label such as "Results".', 'supplementary', 'csit-610/preparing-the-presentation/61f74f4a9542', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ccc04df7-857f-5fd1-9fe5-f3338eb02058', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'Why is a truncated bar-chart axis misleading?', 'Bar length should be proportional to the value. A baseline that does not start at zero exaggerates small differences.', 'supplementary', 'csit-610/preparing-the-presentation/5a9e3e89f71e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('cab45541-4cb5-5d15-b2c9-2e5c9c2c3d4c', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'When is a table better than a graph, and when is a graph better?', 'Tables suit situations where readers need exact values; graphs suit situations where they need to see patterns or trends (Few, 2012).', 'supplementary', 'csit-610/preparing-the-presentation/34d054d7a6f5', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('dc791498-4a9c-5edd-b762-d13c90e9dcc4', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'List three accessibility practices for slides.', 'Strong text contrast and large plain type; not relying on colour alone to distinguish categories; alternative text for images and charts in shared files.', 'supplementary', 'csit-610/preparing-the-presentation/93147728cad0', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4312c0f0-210c-5fcb-a934-b04244ca0a68', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', '485e4f59-c6e0-5d54-b9b7-4e6d291945e7', 'What is the orient, direct, interpret sequence for presenting a visual?', 'Orient (say what it shows), direct (point to the feature that matters) and interpret (say why it matters for your argument).', 'supplementary', 'csit-610/preparing-the-presentation/845c4cef0c80', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('202b97bd-bf8b-57af-9c30-ec7a90647109', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'Besides direct quotations, what else needs attribution in a presentation?', 'Paraphrased ideas, data, figures, images, diagrams and the structure of another author''s argument.', 'supplementary', 'csit-610/preparing-the-presentation/b300e769e5e9', true)
