insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('25214843-504b-5783-b59b-1ced4c874f65', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'What does a source line beneath a figure communicate?', 'How the visual relates to the original: reproduced, adapted, drawn from published data, or from your own data, with the author, year and figure or sample details.', 'supplementary', 'csit-610/preparing-the-presentation/fc2f1d17ac7b', true)
