insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6c065aec-7d45-5d33-b9e4-2d3e1f51b3fe', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'Why is "found online" not the same as "free to use"?', 'Images and data may be protected by copyright or licence conditions. Check the licence, record the creator and source, and credit them as the licence requires.', 'supplementary', 'csit-610/preparing-the-presentation/f45ac5261633', true)
