insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8130fd9b-798a-5bd2-a8c4-8ae0fd33e9f7', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'What is the difference between a genuine paraphrase and patchwriting?', 'A genuine paraphrase changes wording and structure after understanding the source and still cites it. Patchwriting swaps a few words in the original sentence and stays too close.', 'supplementary', 'csit-610/preparing-the-presentation/a2af707b0cf6', true)
