insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('57438b8c-2458-5527-8cc5-01bc5d8f4b11', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'What checks should you make on a reference list before presenting?', 'Every in-text citation appears in the list and vice versa, the style is APA 7 and consistent, and each source, DOI or URL has been verified as real.', 'supplementary', 'csit-610/preparing-the-presentation/607280c07289', true)
