insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('343680f3-64e1-54e7-acd9-1ef09461ab85', null, '7b687631-8925-5aa4-a415-6ed134a64891', '17a3e5d3-7a63-5180-ac43-78d6ecd7ce53', 'b0c75462-0f9e-582b-88ed-40c9dd50cbdd', 'What are the main integrity risks when using generative AI tools to prepare a seminar?', 'Submitting generated work as your own where rules forbid it, failing to disclose use where required, citing sources that do not exist, and presenting unverified claims. Follow your institution''s rules and verify everything.', 'supplementary', 'csit-610/preparing-the-presentation/f1f7324f2537', true)
