insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4caf20a1-af6c-5bb9-9747-b32cea97d10e', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'csit-610/delivery-and-discussion/q01', 'mcq', 'understand', 'easy', 'Explain why delivery skills matter in research communication', 'Why does delivery matter even when the research content is strong?', null, null, '[{"id":"a","text":"Because content is irrelevant if the speaker is energetic"},{"id":"b","text":"Because the audience partly judges command of the work by how clearly it is explained, and unclear delivery can hide good content"},{"id":"c","text":"Because examiners only assess voice and posture"},{"id":"d","text":"Because delivery can replace evidence"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4caf20a1-af6c-5bb9-9747-b32cea97d10e', '{"option":"b"}'::jsonb, 'Good content can be lost through poor delivery, and explaining a method without reading it from the slide shows understanding. Delivery does not replace evidence, and it is not the sole focus of assessment.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('33dc4f6d-be6c-58db-a89f-d2d8a6c98553', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'csit-610/delivery-and-discussion/q02', 'scenario', 'apply', 'medium', 'Apply techniques for managing pace and filler words', 'Which strategy is most likely to help?', 'Illustrative scenario. A student''s recorded rehearsal shows that she speaks quickly, fills pauses with "you know", and speeds up further whenever she feels unsure.', null, '[{"id":"a","text":"Speak even faster so that there is less time to make mistakes"},{"id":"b","text":"Plan deliberate pauses at transitions and before key points, and practise replacing filler words with silence"},{"id":"c","text":"Memorise the whole script word for word"},{"id":"d","text":"Avoid rehearsing so that the delivery feels spontaneous"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('33dc4f6d-be6c-58db-a89f-d2d8a6c98553', '{"option":"b"}'::jsonb, 'Silence feels long to the speaker but natural to the audience. Deliberate pauses slow the pace, give weight to key points and replace filler words. Speaking faster lowers comprehension, and skipping rehearsal removes the practice that improves delivery.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7258f780-772d-5a35-a876-2f6f90884a29', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'csit-610/delivery-and-discussion/q03', 'matching', 'understand', 'medium', 'Compare approaches to notes', 'Match each approach to notes with its main risk.', null, null, '{"left":[{"id":"l1","text":"Reading a full script aloud"},{"id":"l2","text":"Key-word prompts"},{"id":"l3","text":"Memorising without notes"},{"id":"l4","text":"Learning only the opening and closing exactly"}],"right":[{"id":"r4","text":"Little risk, though the middle still needs prompts"},{"id":"r2","text":"Rambling if the talk is poorly prepared"},{"id":"r1","text":"Flat delivery and little eye contact"},{"id":"r3","text":"Collapse if memory fails, and rigid delivery"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7258f780-772d-5a35-a876-2f6f90884a29', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each approach trades fluency against safety. For most seminars, prompts with a learned opening and closing offer the best balance, because the most pressured moments are secure while the middle sounds natural.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7da3f3e7-1efd-5cac-87b7-97502c2cc867', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'csit-610/delivery-and-discussion/q04', 'true_false', 'evaluate', 'medium', 'Evaluate a popular claim about body language', 'The claim that 55 per cent of every message is conveyed by body language is a reliable description of communication in general.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7da3f3e7-1efd-5cac-87b7-97502c2cc867', '{"value":false}'::jsonb, 'The figures come from narrow experiments on the communication of feelings and attitudes, and the researcher himself has said they do not apply to communication in general. A sound conclusion is more modest: content matters, and voice and presence affect how credible and clear it seems.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4f287106-10bf-545f-8c34-8c2c807be770', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'csit-610/delivery-and-discussion/q05', 'mcq', 'apply', 'medium', 'Prepare a contingency plan for equipment problems', 'Which preparation best protects a presentation against equipment failure?', null, null, '[{"id":"a","text":"Relying on a live internet link to a cloud copy of the slides"},{"id":"b","text":"Carrying slides on a USB drive, in cloud storage and as a PDF, and being able to give the talk without slides"},{"id":"c","text":"Arriving a minute before the start"},{"id":"d","text":"Embedding a live web demonstration with no fallback"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4f287106-10bf-545f-8c34-8c2c807be770', '{"option":"b"}'::jsonb, 'Multiple copies and a no-slides version mean that a single failure does not end the talk. Depending on live connectivity, arriving late or having no fallback for a demonstration all increase risk.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('cb9f01ac-ce1c-5907-ba2b-e07cddef60a1', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'csit-610/delivery-and-discussion/q06', 'short_answer', 'recall', 'medium', 'Recall the term for planned responses to foreseeable problems', 'What two-word term describes a prepared response to foreseeable problems such as equipment failure or reduced time?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('cb9f01ac-ce1c-5907-ba2b-e07cddef60a1', '{"answers":["contingency plan","contingency planning"]}'::jsonb, 'A contingency plan reduces anxiety because the worst cases already have an answer. It should cover technology, time cuts and interruptions, and identify which slide is the safe place to stop.', null)
