insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d0bc4978-e6f7-5945-bd3a-9155fc695e31', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'csit-610/delivery-and-discussion/q07', 'mcq', 'analyse', 'hard', 'Analyse presentation anxiety strategies', 'Which approach to presentation nerves best reflects the idea that moderate arousal can help performance?', null, null, '[{"id":"a","text":"Trying to eliminate all nervousness before speaking"},{"id":"b","text":"Reframing nerves as energy and using preparation, breathing and a learned opening to keep arousal at a useful level"},{"id":"c","text":"Avoiding rehearsal to prevent worry"},{"id":"d","text":"Interpreting any nervousness as proof of incompetence"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d0bc4978-e6f7-5945-bd3a-9155fc695e31', '{"option":"b"}'::jsonb, 'Some tension sharpens attention, so the aim is to keep it useful, not to remove it. Preparation, slow breathing and a learned opening reduce excessive arousal. Persistent severe anxiety is a matter for institutional support, not a personal failing.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('63a4e489-c02d-5a48-b438-e2230bc2cf4f', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'csit-610/delivery-and-discussion/q08', 'mcq', 'understand', 'easy', 'Explain the purpose of seminar questions', 'Which view of audience questions is most accurate?', null, null, '[{"id":"a","text":"They are mainly attempts to humiliate the presenter"},{"id":"b","text":"They usually aim to understand, test, extend or contribute to the argument, and are an opportunity to show understanding"},{"id":"c","text":"They indicate that the presentation failed"},{"id":"d","text":"They should be avoided by speaking until time runs out"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('63a4e489-c02d-5a48-b438-e2230bc2cf4f', '{"option":"b"}'::jsonb, 'Most questions come from interest in the work. Assuming good faith helps a presenter stay calm and respond to the substance. A question does not mean the talk failed, and avoiding questions harms credibility.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d7a83fc9-4b2e-52c5-831b-34148abe7b3e', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'csit-610/delivery-and-discussion/q09', 'scenario', 'apply', 'medium', 'Apply an honest response to a question you cannot answer', 'What is the best response?', 'Illustrative scenario. During questions, an examiner asks which study first measured trust using the instrument the presenter described. The presenter cannot remember.', null, '[{"id":"a","text":"Name a plausible-sounding author and year to appear knowledgeable"},{"id":"b","text":"Say that it does not matter"},{"id":"c","text":"Say they do not recall the original source, state what they do know about how the instrument is used, and offer to check and follow up"},{"id":"d","text":"Change the subject to a different question"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d7a83fc9-4b2e-52c5-831b-34148abe7b3e', '{"option":"c"}'::jsonb, 'Bluffing risks fabrication and damages credibility if detected. Saying what you do not know, giving relevant knowledge and offering to follow up is honest and professional. Dismissing the question or changing the subject avoids the issue.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c6c37bc9-49e3-543c-b4b9-34feb0d8f20e', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'csit-610/delivery-and-discussion/q10', 'matching', 'understand', 'medium', 'Match question types to response approaches', 'Match each type of question with the most suitable response approach.', null, null, '{"left":[{"id":"l1","text":"Clarification"},{"id":"l2","text":"Methodological"},{"id":"l3","text":"Scope"},{"id":"l4","text":"Valid challenge"}],"right":[{"id":"r3","text":"State what the evidence covers and mark inference as inference"},{"id":"r2","text":"State the reasoning and acknowledge trade-offs"},{"id":"r4","text":"Concede the valid point and explain its effect on the conclusion"},{"id":"r1","text":"Define briefly, then link to the evidence"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c6c37bc9-49e3-543c-b4b9-34feb0d8f20e', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Recognising the type of question allows a focused answer. A challenge that is partly or fully valid is best met by conceding what holds, which preserves credibility, rather than defending a position the evidence does not support.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('706747bd-a05c-5184-93e9-4f1352a45748', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'csit-610/delivery-and-discussion/q11', 'true_false', 'understand', 'easy', 'Recall the value of pausing and paraphrasing', 'Pausing briefly and paraphrasing a question before answering helps the presenter avoid answering the wrong question and lets the whole audience hear it.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('706747bd-a05c-5184-93e9-4f1352a45748', '{"value":true}'::jsonb, 'A short pause shows thought, and paraphrasing ("If I understand correctly, you are asking...") confirms the question, helps listeners who did not hear it and gives you time. It also lets the questioner correct you before you invest in a long answer.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5e6497da-8e10-57c6-bdf0-0468ab0db4cc', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'csit-610/delivery-and-discussion/q12', 'mcq', 'analyse', 'hard', 'Analyse the part of an argument being challenged', 'A questioner says, "Your evidence is from a convenience sample, so it cannot support a claim about all small firms." In Toulmin''s terms, which element of the argument is being challenged?', null, null, '[{"id":"a","text":"The grounds (the evidence) and their relationship to the claim''s scope"},{"id":"b","text":"The title of the presentation"},{"id":"c","text":"The presenter''s accent"},{"id":"d","text":"The format of the reference list"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5e6497da-8e10-57c6-bdf0-0468ab0db4cc', '{"option":"a"}'::jsonb, 'The questioner disputes whether the evidence is adequate to support a broad claim. An effective reply acknowledges the sample limitation and narrows the claim to what the grounds support. Identifying which element is under attack helps you answer precisely.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7cc46923-153c-5c37-ab75-9f7d2c81881a', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'csit-610/delivery-and-discussion/q13', 'scenario', 'evaluate', 'hard', 'Evaluate a response to a hostile question', 'Which assessment of the reply is most accurate?', 'Illustrative scenario. A participant says, "This is just a summary of other people''s work." The presenter replies sharply, "If you had read the literature properly you would see it is not."', null, '[{"id":"a","text":"It is effective because it shows confidence"},{"id":"b","text":"It is weak because it responds to the tone with a personal remark; a better reply states what the synthesis adds, using evidence, and offers to continue the discussion afterwards"},{"id":"c","text":"It is ideal because it ends the discussion quickly"},{"id":"d","text":"It is acceptable because the participant was rude first"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7cc46923-153c-5c37-ab75-9f7d2c81881a', '{"option":"b"}'::jsonb, 'Responding to the substance rather than the tone preserves credibility. A calm statement of the contribution, such as comparing how studies measured a concept, answers the criticism without a personal attack, while an offer to continue later respects the time of others.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('329af634-b361-596d-919c-af686bd16be8', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'csit-610/delivery-and-discussion/q14', 'short_answer', 'recall', 'medium', 'Recall the term for a slide prepared for expected questions', 'What type of slide, kept after the final slide, is prepared in advance to answer an expected question?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('329af634-b361-596d-919c-af686bd16be8', '{"answers":["backup slide","backup slides","back-up slide","appendix slide"]}'::jsonb, 'Backup slides hold detailed data, methods or alternative interpretations that would overload the main talk. Having them ready shows preparation and lets you answer with evidence.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('cf465479-a516-58a2-9ecb-6a54e3d0347a', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'csit-610/delivery-and-discussion/q15', 'mcq', 'understand', 'easy', 'Explain the three questions of effective feedback', 'According to Hattie and Timperley (2007), effective feedback helps learners answer which three questions?', null, null, '[{"id":"a","text":"Who marked it, when, and how many marks?"},{"id":"b","text":"Where am I going, how am I going, and where to next?"},{"id":"c","text":"What did I like, what did I dislike, and who agrees?"},{"id":"d","text":"How long, how many, and how often?"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('cf465479-a516-58a2-9ecb-6a54e3d0347a', '{"option":"b"}'::jsonb, 'The three questions concern the goal, current progress and next steps. Feedback that only judges performance addresses the second question but not the third, which is why vague praise or criticism is frustrating.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6a92ff49-f5f7-59d1-8955-3d7c3f6c33f7', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'csit-610/delivery-and-discussion/q16', 'matching', 'recall', 'medium', 'Recall the stages of Gibbs'' reflective cycle', 'Match each stage of Gibbs'' reflective cycle with its guiding question.', null, null, '{"left":[{"id":"l1","text":"Description"},{"id":"l2","text":"Evaluation"},{"id":"l3","text":"Analysis"},{"id":"l4","text":"Action plan"}],"right":[{"id":"r2","text":"What was good and bad about the experience?"},{"id":"r1","text":"What happened?"},{"id":"r3","text":"Why did things go as they did?"},{"id":"r4","text":"What will I do next time, and how?"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6a92ff49-f5f7-59d1-8955-3d7c3f6c33f7', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'The cycle moves from narrating to analysing and planning. Weak reflection stops at description; strong reflection explains why events occurred and ends with specific actions.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e92266d0-6cdd-535c-8ca4-3e4e6acb00ad', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'csit-610/delivery-and-discussion/q17', 'scenario', 'apply', 'medium', 'Apply goal setting to feedback', 'Which revised goal is most useful?', 'Illustrative scenario. A student receives the feedback "needs better delivery" and writes the goal "improve my delivery".', null, '[{"id":"a","text":"Be a better speaker."},{"id":"b","text":"Record two rehearsals, count filler words in each, and halve the count before the next presentation."},{"id":"c","text":"Try harder next time."},{"id":"d","text":"Avoid presenting if possible."}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e92266d0-6cdd-535c-8ca4-3e4e6acb00ad', '{"option":"b"}'::jsonb, 'A useful goal is specific, measurable and time-bound, so progress can be checked. The other options are vague, give no way to measure success or avoid the skill rather than develop it.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1894b458-e6f3-5957-aba3-c67fe7400724', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'csit-610/delivery-and-discussion/q18', 'true_false', 'analyse', 'medium', 'Analyse the use of conflicting feedback', 'When two sources of feedback conflict, you should always follow the more senior source without further thought.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1894b458-e6f3-5957-aba3-c67fe7400724', '{"value":false}'::jsonb, 'Conflicting comments should be evaluated against your purpose, the audience and the assessment requirements. Seniority may carry relevant knowledge, but if the conflict concerns assessment criteria you should check with your lecturer, and patterns across several sources deserve more weight than a single comment.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('63feeb1a-9b38-55da-8128-b4413c1d3996', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'csit-610/delivery-and-discussion/q19', 'mcq', 'evaluate', 'hard', 'Evaluate the use of seminar material in later written work', 'A student wants to reuse large parts of her graded seminar paper in her dissertation. Which course of action is most appropriate?', null, null, '[{"id":"a","text":"Reuse it without comment, since it is her own work"},{"id":"b","text":"Check her programme''s rules, discuss the plan with her supervisor, acknowledge the earlier work where required, and rewrite it for a reader with full citations"},{"id":"c","text":"Replace all the references with new ones to avoid detection"},{"id":"d","text":"Copy only the slides into the dissertation"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('63feeb1a-9b38-55da-8128-b4413c1d3996', '{"option":"b"}'::jsonb, 'Reusing submitted work without acknowledgement can be treated as self-plagiarism, and rules vary between programmes. Talking to a supervisor and rewriting for readers, who need fuller definitions and methods than listeners, is both honest and better for the work.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f5c542fc-bc0e-59f7-a653-febbf607e629', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'csit-610/delivery-and-discussion/q20', 'short_answer', 'recall', 'medium', 'Recall the term for feedback focused on what to do next', 'What term describes feedback focused on what to do next rather than only judging what was done?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f5c542fc-bc0e-59f7-a653-febbf607e629', '{"answers":["feedforward","feed-forward","feed forward"]}'::jsonb, 'Feedforward answers the "where to next?" question and is the part of feedback most likely to change later performance. A good comment on a seminar names a specific change to try.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('aad7da50-be9a-5f52-9689-383d6382e8ec', '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', null, 'csit-610/delivery-and-discussion/q21', 'essay', 'evaluate', 'hard', 'Evaluate the contribution of delivery, discussion and reflection to seminar performance and learning', '"A seminar is only partly won in the presentation itself." Discuss this statement, explaining how delivery skills, the handling of questions and the use of feedback and reflection each contribute to a postgraduate seminar, and justify the practices you would prioritise.', null, null, null, 20, array['Introduction interpreting the statement', 'Delivery skills and rehearsal as the visible performance', 'Questions and discussion as evidence of understanding', 'Feedback and reflection as the route to improvement and further development', 'Critical evaluation, including limits and fairness', 'Prioritised practices and conclusion']::text[], '[{"criterion":"Understanding of delivery, discussion and reflection","marks":6,"descriptor":"Accurately explains the contribution of voice, notes and rehearsal, of structured question handling, and of feedback and reflection, with accurate use of terminology."},{"criterion":"Critical evaluation","marks":6,"descriptor":"Weighs the relative importance of the three areas, considers limits such as anxiety, fairness for different speakers and conflicting feedback, and avoids one-sided assertion."},{"criterion":"Application and examples","marks":4,"descriptor":"Uses realistic examples from seminar or professional settings to illustrate points and links them to practices such as staged rehearsal, paraphrasing questions and Gibbs-style reflection."},{"criterion":"Structure and expression","marks":4,"descriptor":"Clear introduction, logical argument, reasoned prioritisation and a conclusion in academic English."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('aad7da50-be9a-5f52-9689-383d6382e8ec', '{}'::jsonb, 'Examiners look for a balanced argument that connects the three areas, evaluates their relative contribution with reasons, and supports claims with practical, realistic examples.', 'A strong answer interprets the statement as claiming that the quality of a seminar depends on preparation before it and learning after it as well as on the talk itself. Delivery matters because listeners cannot re-read: voice, pace, pauses, eye contact and sensible use of notes make content intelligible and signal command of the material. Staged, timed and recorded rehearsal, a learned opening and closing, and a contingency plan are the practical foundations, and nerves can be managed by preparation, breathing and reframing.

The question session is where understanding becomes visible. Examiners and peers probe reasoning, so a presenter who listens fully, paraphrases, answers directly with evidence, concedes valid criticism and admits what is not known demonstrates intellectual honesty. Preparation, including anticipated questions and backup slides, is again the main protection. Toulmin''s model can help identify which part of an argument is being challenged.

Feedback and reflection turn a single event into learning. Hattie and Timperley''s (2007) three questions, a method of receiving, understanding, evaluating, prioritising and acting, and a structured reflection such as Gibbs'' cycle, lead to specific goals. The seminar material can also be developed into a literature review, paper or proposal, with attention to acknowledgement of earlier work.

A critical answer notes limits: delivery can be over-weighted at the expense of content, anxiety and language background affect performance, feedback may conflict and reflection can become formulaic. A reasoned conclusion would prioritise rehearsal with feedback, honest question handling and a concrete action plan, since these are controllable and compound over time.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c8304de5-5d53-540f-a136-4624783b18a8', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'Why are pauses valuable in delivery?', 'They give weight to key points, let the audience absorb ideas and replace filler words. Silence feels longer to the speaker than to the listener.', 'supplementary', 'csit-610/delivery-and-discussion/8576c11d8926', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('14add587-dfc2-5f08-91fe-d8e117509a72', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'What is the recommended note strategy for most seminars?', 'Key-word prompts for each slide, with the opening and closing sentences learned exactly. This balances natural speech with security at the most pressured moments.', 'supplementary', 'csit-610/delivery-and-discussion/41bac6880389', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d03da93f-b76e-54f1-89f8-50918998aa7e', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'Describe the stages of effective rehearsal.', 'Silent run-through, aloud with a timer, standing with slides, recorded, in front of peers, and a final dress rehearsal in the venue if possible, with one improvement goal per run.', 'supplementary', 'csit-610/delivery-and-discussion/d366e96943c6', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0c8ba8c3-79cd-5f44-8967-9efbe4f96a64', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'What should be in a contingency plan for a presentation?', 'Slides in several formats (USB, cloud, PDF), a no-slides version of the talk, fallback screenshots instead of live demonstrations, and a plan for reduced time.', 'supplementary', 'csit-610/delivery-and-discussion/0d456225616e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('aaca7381-20b8-5a5d-99e5-40c0afce3172', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'Name three techniques for managing presentation anxiety.', 'Thorough preparation and realistic rehearsal, slow breathing with longer exhalations, and starting from a learned opening. Reframing nerves as energy also helps.', 'supplementary', 'csit-610/delivery-and-discussion/09d556e50827', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('78fb345f-1676-5e2a-9a16-29fa1bf6d91d', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '4760665a-b00e-5dee-ad81-34828597d4d3', 'Why is the "55 per cent body language" claim misleading?', 'It comes from narrow experiments on feelings and attitudes and does not describe communication in general. Content matters, and voice and presence affect its credibility.', 'supplementary', 'csit-610/delivery-and-discussion/1a3dd1636f60', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('fbe4e7bf-f6bd-590d-9d7a-c159a2d80387', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'What are the steps of the method for answering a question?', 'Listen fully, pause, paraphrase or clarify, answer directly, give evidence, be honest about limits, check the answer was sufficient, and keep it concise.', 'supplementary', 'csit-610/delivery-and-discussion/bb6a12d3b205', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('fdb1d834-529d-58fe-9452-f90800f2d132', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'How should you respond if you do not know the answer?', 'Say so, explain what you do know that is relevant and how you could find out, and offer to follow up. Do not bluff.', 'supplementary', 'csit-610/delivery-and-discussion/b2d622f0efd5', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9088d48b-6c5f-5af6-a2cb-df524df6e472', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'How should you respond to a valid criticism?', 'Concede the point, explain its effect on your conclusion and say what you would do differently. Conceding a valid point enhances credibility.', 'supplementary', 'csit-610/delivery-and-discussion/d41fb8acaf5d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('10e8de11-7e0f-526e-b64e-f7ee5a4cf5b9', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'What is the value of a backup slide?', 'It holds detailed data, methods or alternative interpretations ready for expected questions without overloading the main talk.', 'supplementary', 'csit-610/delivery-and-discussion/35806fe13d42', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('dafe9f42-b001-5441-88fa-d1b1bc1e29c7', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'What makes a good audience question?', 'It is specific, linked to the speaker''s content, asked one at a time, aimed at the argument rather than the person, and seeks understanding or advances discussion.', 'supplementary', 'csit-610/delivery-and-discussion/5279dcb3cb2a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('919700a6-2d42-5f2d-a03e-331e889e60a5', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '609d16a5-6554-558a-adc3-e5ac8a48ac4f', 'What does the principle of charity ask of a questioner or respondent?', 'Interpret the other person''s argument in its strongest reasonable form before responding, which models honesty and often reduces tension.', 'supplementary', 'csit-610/delivery-and-discussion/3aba3ebcffdc', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ebc48d8c-b362-5b1c-bf89-c82ae75edd78', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'What three questions does effective feedback answer?', 'Where am I going? How am I going? Where to next? (Hattie & Timperley, 2007).', 'supplementary', 'csit-610/delivery-and-discussion/fdc474420f3f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d854f202-81e2-5c22-8267-1fb4246ef159', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'What is the difference between feedback and feedforward?', 'Feedback describes the gap between performance and goal; feedforward focuses on what to do next to close it.', 'supplementary', 'csit-610/delivery-and-discussion/5a5154a45e0f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c4362fe5-90c9-5915-841c-6a413bbf2b66', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'List the six stages of Gibbs'' reflective cycle.', 'Description, feelings, evaluation, analysis, conclusion and action plan.', 'supplementary', 'csit-610/delivery-and-discussion/bf7b23ac1442', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3860178a-07a5-5760-a153-8e3b0b4feac6', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'How do you process feedback instead of reacting to it defensively?', 'Receive it, understand it by asking for examples, evaluate its accuracy and patterns, prioritise a few changes and act on them.', 'supplementary', 'csit-610/delivery-and-discussion/b31330a86882', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('55fe0c25-78a2-59e0-935b-57bc90e876df', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'What makes an improvement goal useful?', 'It is specific, measurable and time-bound, for example recording two rehearsals and halving filler words before the next presentation.', 'supplementary', 'csit-610/delivery-and-discussion/76372502ab81', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('593cb0dd-311d-55cc-ac26-a813e1ff44b9', null, '7b687631-8925-5aa4-a415-6ed134a64891', '5f1c3380-9d9a-565e-863a-09eda263ca73', '673ac622-0486-5fd2-8aab-cac6372fffe6', 'What changes when seminar material is turned into written research?', 'Readers need fuller definitions, detailed methods, explicit reasoning and complete citations, but not the repeated signposts of a talk. Check rules on acknowledging reused work.', 'supplementary', 'csit-610/delivery-and-discussion/1b6477f49d11', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
