insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('911e3658-49ea-530d-8a6d-a477a44c6978', '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '327d5a63-e013-5c31-b652-fddd4df8cbda', 'csit-613/e-business-foundations/q09', 'matching', 'understand', 'medium', 'Match revenue models to examples', 'Match each revenue model to the example that best illustrates it.', null, null, '{"left":[{"id":"l1","text":"Subscription"},{"id":"l2","text":"Transaction fee"},{"id":"l3","text":"Advertising"},{"id":"l4","text":"Freemium"},{"id":"l5","text":"Affiliate"}],"right":[{"id":"r1","text":"Monthly fee for unlimited access to a streaming library"},{"id":"r5","text":"Review website earning commission when readers buy through its links"},{"id":"r2","text":"Payment gateway charging a percentage of each successful payment"},{"id":"r4","text":"Free basic cloud storage with paid extra capacity"},{"id":"r3","text":"Free social media service paid for by brands seeking user attention"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
