insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e51cd05f-bcf8-5265-b5be-34af638cbc3b', '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '327d5a63-e013-5c31-b652-fddd4df8cbda', 'csit-613/e-business-foundations/q10', 'short_answer', 'recall', 'easy', 'Recall the number of building blocks in the Business Model Canvas', 'How many building blocks make up Osterwalder and Pigneur''s Business Model Canvas?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
