insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e51cd05f-bcf8-5265-b5be-34af638cbc3b', '{"answers":["9","nine"]}'::jsonb, 'The nine blocks are customer segments, value propositions, channels, customer relationships, revenue streams, key resources, key activities, key partnerships and cost structure.', null)
