insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8f348c1b-6c5a-5977-a85e-cb188419d3b9', '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '327d5a63-e013-5c31-b652-fddd4df8cbda', 'csit-613/e-business-foundations/q11', 'scenario', 'apply', 'medium', 'Calculate contribution per order to test unit economics', 'What is the contribution per order?', 'Illustrative scenario. An online grocery start-up has an average order value of GHS 200 and a gross margin of 30 per cent. Delivery costs GHS 35 per order and payment fees plus packaging cost GHS 8 per order.', null, '[{"id":"a","text":"GHS 60"},{"id":"b","text":"GHS 17"},{"id":"c","text":"GHS 25"},{"id":"d","text":"GHS 157"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8f348c1b-6c5a-5977-a85e-cb188419d3b9', '{"option":"b"}'::jsonb, 'Gross margin = 200 × 0.30 = GHS 60. Contribution = 60 − 35 − 8 = GHS 17. GHS 60 ignores variable costs; GHS 25 subtracts only delivery; GHS 157 wrongly subtracts costs from revenue rather than from margin.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a23fc8e2-f74c-527c-adcf-a63686bbbbff', '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '327d5a63-e013-5c31-b652-fddd4df8cbda', 'csit-613/e-business-foundations/q12', 'true_false', 'understand', 'medium', 'Understand cost structures of digital goods', 'Because digital goods have near-zero marginal cost, digital businesses are guaranteed to be profitable once they have customers.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a23fc8e2-f74c-527c-adcf-a63686bbbbff', '{"value":false}'::jsonb, 'Near-zero marginal cost is usually accompanied by high fixed costs for development, content and marketing. Profit depends on recovering those fixed costs, managing churn and pricing by customer value.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('673b3689-19e5-556e-a093-2bdf3cc348fd', '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '327d5a63-e013-5c31-b652-fddd4df8cbda', 'csit-613/e-business-foundations/q13', 'mcq', 'analyse', 'hard', 'Analyse sources of digital value creation', 'A ride-hailing app integrates maps, in-app payment and two-way rating so that passengers and drivers obtain more value than from each feature separately. Which source of value creation identified by Amit and Zott does this primarily illustrate?', null, null, '[{"id":"a","text":"Efficiency"},{"id":"b","text":"Complementarities"},{"id":"c","text":"Lock-in"},{"id":"d","text":"Novelty"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('673b3689-19e5-556e-a093-2bdf3cc348fd', '{"option":"b"}'::jsonb, 'Complementarities arise when bundled elements are worth more together than apart. The app may also create efficiency and lock-in, but the defining feature here is the combination of components.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('94bd317a-07b5-5177-af32-d76b50cd52bf', '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '327d5a63-e013-5c31-b652-fddd4df8cbda', 'csit-613/e-business-foundations/q14', 'scenario', 'evaluate', 'hard', 'Evaluate the coherence of a business model', 'Which is the most important weakness in this business model?', 'Illustrative scenario. A start-up offers free same-day delivery on all orders of any size across Greater Accra, earns a 10 per cent margin on low-priced household goods, and plans to grow rapidly through social media advertising.', null, '[{"id":"a","text":"It uses social media advertising"},{"id":"b","text":"Its cost structure is inconsistent with its revenue stream, since free delivery on small low-margin orders produces negative unit economics"},{"id":"c","text":"It operates in Greater Accra rather than nationally"},{"id":"d","text":"It sells household goods rather than electronics"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('94bd317a-07b5-5177-af32-d76b50cd52bf', '{"option":"b"}'::jsonb, 'Coherence requires revenue and cost blocks to fit. Free delivery on small baskets with a 10 per cent margin almost certainly loses money per order, and rapid growth would magnify losses. The other options are strategic choices, not structural incoherence.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('683e4a2d-d256-5316-b34a-fde885cc63be', '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '327d5a63-e013-5c31-b652-fddd4df8cbda', 'csit-613/e-business-foundations/q15', 'true_false', 'recall', 'easy', 'Recall the purpose of the canvas''s left side', 'In the Business Model Canvas, key partnerships, key activities and key resources primarily drive the cost structure.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('683e4a2d-d256-5316-b34a-fde885cc63be', '{"value":true}'::jsonb, 'The left-hand side of the canvas describes the operational infrastructure that delivers the value proposition and therefore generates most costs; the right-hand side concerns customers and revenue.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('29c43edc-ec2d-576d-8fc9-2f9bc5cd23f3', '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', null, 'csit-613/e-business-foundations/q16', 'case_analysis', 'evaluate', 'hard', 'Apply the Business Model Canvas and transformation concepts to a Ghanaian SME', 'Using the Business Model Canvas and the distinction between digitalisation and digital transformation, analyse KenteCraft''s current position and recommend a business model for its next stage of growth.', null, 'Illustrative scenario. KenteCraft is a hypothetical family business in the Volta Region that weaves and sells kente cloth. It sells mainly to walk-in customers and resellers, but over the past year it has started posting products on Instagram, receiving orders from the Ghanaian diaspora in the United Kingdom and the United States, and accepting mobile money from local buyers. International customers currently pay by bank transfer, which is slow, and deliveries are arranged ad hoc through courier companies. Orders are tracked in a notebook. The owner is considering three options: (a) a website with card payments and international shipping; (b) listing on an established international marketplace for handmade goods; (c) offering custom-woven pieces for weddings and graduations booked online with a deposit.', null, 20, array['Brief diagnosis of current level (digitisation, digitalisation, e-commerce, e-business)', 'Business Model Canvas of the current model, highlighting weak blocks', 'Comparison of options (a), (b) and (c) against customer segments, channels, revenue streams and costs', 'Recommendation with justification and risks', 'Implementation priorities, including back-office e-business improvements']::text[], '[{"criterion":"Diagnosis using lesson concepts","marks":4,"descriptor":"Correctly identifies sell-side e-commerce with weak e-business integration and explains why the firm has not yet transformed."},{"criterion":"Application of the canvas","marks":6,"descriptor":"Completes relevant blocks with case evidence and identifies weaknesses in channels, payments, logistics and order management."},{"criterion":"Evaluation of options","marks":6,"descriptor":"Compares the three options on value proposition, revenue, cost and risk, showing trade-offs such as marketplace fees versus control."},{"criterion":"Recommendation and implementation","marks":4,"descriptor":"Makes a justified, realistic recommendation with priorities and acknowledges risks."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('29c43edc-ec2d-576d-8fc9-2f9bc5cd23f3', '{}'::jsonb, 'Examiners look for correct use of e-business and transformation concepts, a canvas grounded in case evidence, a balanced comparison of options and a justified, realistic recommendation.', 'A strong answer begins by diagnosing KenteCraft as a business practising early sell-side e-commerce (Instagram, mobile money) with almost no e-business integration: orders sit in a notebook, international payments are slow and logistics are improvised. Its activity is digitalisation of marketing and some payments, not transformation, because the value proposition and revenue model are unchanged.

The canvas should show two clear segments (local walk-in and reseller buyers; diaspora buyers with high willingness to pay for authenticity), a value proposition built on authentic handmade cloth, channels that are fragmented, and revenue from one-off sales. Weak blocks are channels (no structured storefront), key activities (order management, international fulfilment) and partnerships (no reliable payment or shipping partner).

Option (a) gives control and margin but requires investment in a storefront, payment integration and marketing to attract traffic. Option (b) offers immediate reach and trust but involves commission fees, less control over customer data and competition on the same platform. Option (c) creates a novel, higher-value proposition with deposits that improve cash flow, and suits both diaspora and local ceremonies, but requires capacity planning.

A reasonable recommendation is to combine (b) as a low-cost test of diaspora demand with (c) as a differentiated premium service, while fixing the back office: a simple order and inventory system, a payment service provider that accepts cards and mobile money, and a negotiated courier arrangement. Risks include fees, delivery damage, currency issues and capacity constraints. Examiners reward linking each recommendation to specific canvas blocks.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('551efe1e-1198-5abd-96bc-1f20668a876d', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '4e3b3afd-4be1-5513-ad5b-8d8e973b0b80', 'How does e-business differ from e-commerce?', 'E-commerce is the digitally enabled exchange of value between parties; e-business is the digital enablement of all organisational processes (buy-side, internal and sell-side), with e-commerce as one part.', 'supplementary', 'csit-613/e-business-foundations/d4bad0e25668', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a7c37537-8b7a-57df-b897-b42c1a3b4e8e', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '4e3b3afd-4be1-5513-ad5b-8d8e973b0b80', 'Distinguish digitisation, digitalisation and digital transformation.', 'Digitisation changes the format of information; digitalisation changes a process using digital technology; digital transformation changes the value proposition, business model, structure and culture.', 'supplementary', 'csit-613/e-business-foundations/1b9ca935f93e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8152d46f-1931-565a-b8a5-d63e5cb6480f', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '4e3b3afd-4be1-5513-ad5b-8d8e973b0b80', 'Why has reintermediation been more common than disintermediation online?', 'New digital intermediaries (marketplaces, payment providers, review and delivery platforms) add value by reducing search costs, aggregating demand and building trust, so intermediaries change form rather than disappear.', 'supplementary', 'csit-613/e-business-foundations/e95b8d4fe45b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d1a54711-0f7b-5d1f-b106-92452dd744e3', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '4e3b3afd-4be1-5513-ad5b-8d8e973b0b80', 'Why does information density cut both ways in digital markets?', 'It makes prices and product information more transparent for buyers, but it also gives sellers rich customer data that supports personalisation and price discrimination.', 'supplementary', 'csit-613/e-business-foundations/a4fdf5015a40', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0746c599-5f3d-55e3-aefc-c8c92cb1c94d', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '4e3b3afd-4be1-5513-ad5b-8d8e973b0b80', 'What two capabilities do Westerman, Bonnet and McAfee say digital masters combine?', 'Digital capability (what the firm does with technology across customer experience, operations and business models) and leadership capability (vision, governance, engagement and IT-business relationships).', 'supplementary', 'csit-613/e-business-foundations/eccad7f1e83e', true)
