insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ca2e16c2-efa2-5da1-888b-c7a3558469e7', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '4e3b3afd-4be1-5513-ad5b-8d8e973b0b80', 'Why has mobile money mattered for e-commerce in Ghana?', 'It provides a widely used digital payment method that does not depend on card ownership, lowering a traditional barrier to online selling, although logistics and trust remain constraints.', 'supplementary', 'csit-613/e-business-foundations/64772fe98fdb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('94ce3239-8abc-516d-b387-11e7ac7a7c85', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '327d5a63-e013-5c31-b652-fddd4df8cbda', 'What four questions does a business model answer?', 'Who the customer is, what they value, how that value is delivered, and how the firm captures value (earns money) at an appropriate cost.', 'supplementary', 'csit-613/e-business-foundations/7a95df096060', true)
