insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bc701048-47f7-52ae-b52c-b59cd3acbcbf', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '0642fd4b-df9f-5fe6-827a-1295a2954e41', '327d5a63-e013-5c31-b652-fddd4df8cbda', 'What is the main limitation of the Business Model Canvas as an analytical tool?', 'It is a static description that does not model competition or dynamics; it must be followed by an evaluation of coherence, assumptions, unit economics and risks.', 'supplementary', 'csit-613/e-business-foundations/1f8ba8239907', true)
