insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('dda3c643-6999-5f37-9e2d-9741da5ee243', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e-commerce-models', 'E-Commerce Models', 'Who sells to whom, and how platforms orchestrate markets.', 2, true)
