insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('45e5d2ac-cf9d-54e0-8edc-e6c4112f0e66', '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', 'dd193a1b-6e35-575c-a758-94825be0030a', 'csit-613/e-commerce-models/q03', 'mcq', 'understand', 'medium', 'Explain distinctive features of B2B buying', 'Which feature most clearly distinguishes B2B from B2C buying processes?', null, null, '[{"id":"a","text":"B2B buyers never use mobile devices"},{"id":"b","text":"B2B purchases typically involve several people, negotiated prices, approval workflows and credit terms"},{"id":"c","text":"B2B transactions are always conducted through public marketplaces"},{"id":"d","text":"B2B buyers decide more quickly and emotionally than consumers"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
