insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9faf6a05-bb5c-5784-9158-775b57b60b38', '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', 'dd193a1b-6e35-575c-a758-94825be0030a', 'csit-613/e-commerce-models/q07', 'mcq', 'analyse', 'hard', 'Analyse why trust mechanisms matter most in C2C', 'Why is the trust problem typically more severe in C2C than in established B2C e-commerce?', null, null, '[{"id":"a","text":"C2C transactions are always larger in value"},{"id":"b","text":"C2C buyers and sellers are usually strangers without brands, contracts or reputations to lose, so the platform must supply trust through ratings, verification and payment holding"},{"id":"c","text":"C2C platforms are not allowed to process payments"},{"id":"d","text":"Consumers in C2C markets do not care about product quality"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
