insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9faf6a05-bb5c-5784-9158-775b57b60b38', '{"option":"b"}'::jsonb, 'Established B2C sellers have brands and legal accountability; individuals in C2C lack these signals, so platform-provided reputation and payment protection become decisive. C2C values are typically small, and platforms often do process payments.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8b6724d6-aba0-53f6-9136-92c6cdcf147d', '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'csit-613/e-commerce-models/q08', 'mcq', 'understand', 'easy', 'Distinguish a marketplace from a reseller', 'Which statement correctly distinguishes a marketplace from a reseller?', null, null, '[{"id":"a","text":"A marketplace owns inventory and sets prices; a reseller earns commission"},{"id":"b","text":"A marketplace hosts third-party sellers who keep ownership and pricing, typically earning commission; a reseller buys stock and earns a margin"},{"id":"c","text":"They differ only in the design of their websites"},{"id":"d","text":"A reseller never sells online"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8b6724d6-aba0-53f6-9136-92c6cdcf147d', '{"option":"b"}'::jsonb, 'The reseller (merchant) model takes ownership and inventory risk; the marketplace facilitates third-party transactions. Many firms are hybrids, operating both.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('66e0516d-27e0-53b4-a51a-6b657f9a7cc7', '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'csit-613/e-commerce-models/q09', 'matching', 'understand', 'medium', 'Match network effect types to examples', 'Match each network effect type to the example that illustrates it.', null, null, '{"left":[{"id":"l1","text":"Positive cross-side"},{"id":"l2","text":"Negative same-side"},{"id":"l3","text":"Positive same-side"},{"id":"l4","text":"Negative cross-side"}],"right":[{"id":"r1","text":"More sellers on a marketplace give buyers more choice"},{"id":"r2","text":"More drivers on a ride-hailing app compete for the same fares"},{"id":"r4","text":"A flood of low-quality listings reduces buyers'' trust in the marketplace"},{"id":"r3","text":"More friends on a messaging app make it more useful to each user"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('66e0516d-27e0-53b4-a51a-6b657f9a7cc7', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Distinguishing the side and the sign of each effect is essential for platform analysis. Negative effects are managed through governance.', null)
