insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a6b6a137-86ba-54a4-8464-431720b9f058', '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'csit-613/e-commerce-models/q10', 'short_answer', 'recall', 'medium', 'Recall the term for users participating in several platforms', 'What term describes users who participate in several competing platforms at the same time?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a6b6a137-86ba-54a4-8464-431720b9f058', '{"answers":["multi-homing","multihoming","multi homing"]}'::jsonb, 'Multi-homing weakens the protection network effects give a platform, because users can easily shift activity between platforms.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ef4939b7-2d43-5e68-a1fc-b3be21d07986', '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'csit-613/e-commerce-models/q11', 'scenario', 'apply', 'medium', 'Apply Rochet and Tirole''s pricing logic', 'Which pricing structure is most consistent with two-sided market theory?', 'Illustrative scenario. A new platform connects event venues in Kumasi with people planning weddings and funerals. Planners are highly price-sensitive and compare options informally, while venues value a steady flow of bookings and are willing to pay for them.', null, '[{"id":"a","text":"Charge planners a high booking fee and let venues list free"},{"id":"b","text":"Let planners search and book free and charge venues a commission on confirmed bookings"},{"id":"c","text":"Charge both sides the same fee for fairness"},{"id":"d","text":"Charge neither side and rely on future growth"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ef4939b7-2d43-5e68-a1fc-b3be21d07986', '{"option":"b"}'::jsonb, 'Rochet and Tirole show that price structure matters. Subsidising the price-sensitive side whose participation creates value for the other (planners) and charging the side that values access more (venues) is consistent with the theory. Equal fees ignore asymmetric sensitivities, and charging nothing provides no revenue model.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6fd05447-27c8-5a03-9685-8af349519e8c', '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'csit-613/e-commerce-models/q12', 'true_false', 'understand', 'medium', 'Understand the limits of network effects', 'Strong network effects guarantee that a leading platform will remain dominant permanently.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6fd05447-27c8-5a03-9685-8af349519e8c', '{"value":false}'::jsonb, 'Multi-homing, low switching costs, negative network effects from poor governance, disintermediation and regulation can all erode a leader''s position.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('cba83742-f9a3-514c-8518-0d63fee1781a', '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'csit-613/e-commerce-models/q13', 'scenario', 'evaluate', 'hard', 'Evaluate responses to disintermediation risk', 'Which response is most likely to reduce disintermediation sustainably?', 'Illustrative scenario. A platform connecting home cleaners with households in Accra finds that after the first booking many households contact cleaners directly by phone, so the platform loses its commission on repeat work.', null, '[{"id":"a","text":"Hide cleaners'' names so that households cannot recognise them"},{"id":"b","text":"Provide ongoing value to both sides inside the platform, such as payment protection, insurance, scheduling, ratings that build cleaners'' reputations, and lower commission on repeat bookings"},{"id":"c","text":"Double the commission to recover lost revenue"},{"id":"d","text":"Ban households that are suspected of contacting cleaners directly"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('cba83742-f9a3-514c-8518-0d63fee1781a', '{"option":"b"}'::jsonb, 'Users bypass platforms that add little value after matching. Ongoing benefits and fair value sharing give both sides reasons to stay. Hiding identities undermines trust, higher commission strengthens the incentive to bypass, and bans are hard to enforce and alienate users.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1548229b-4449-5cf1-8ec7-ce66a7e9390e', '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'csit-613/e-commerce-models/q14', 'mcq', 'analyse', 'hard', 'Analyse chicken-and-egg launch strategies', 'A new B2C marketplace in Ghana starts by selling its own stock of phone accessories before opening to third-party sellers. Which launch strategy does this illustrate?', null, null, '[{"id":"a","text":"Piggybacking on an existing user base"},{"id":"b","text":"Seeding the platform with its own supply to attract buyers before sellers join"},{"id":"c","text":"Multi-homing"},{"id":"d","text":"Same-side subsidy for buyers"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1548229b-4449-5cf1-8ec7-ce66a7e9390e', '{"option":"b"}'::jsonb, 'Acting as a reseller first provides supply so that buyers arrive, which then attracts third-party sellers. Piggybacking uses another network''s users; multi-homing is user behaviour, not a launch strategy.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('19396e11-fdcc-5537-bcce-05b9766d1f65', '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'csit-613/e-commerce-models/q15', 'short_answer', 'recall', 'easy', 'Recall the authors of the seminal two-sided market paper', 'Which two economists wrote the 2003 paper "Platform competition in two-sided markets"? (Give surnames.)', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('19396e11-fdcc-5537-bcce-05b9766d1f65', '{"answers":["Rochet and Tirole","Rochet & Tirole","Rochet Tirole"]}'::jsonb, 'Jean-Charles Rochet and Jean Tirole''s paper in the Journal of the European Economic Association established the importance of price structure in two-sided markets.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e273d0c7-29f1-5b9c-986d-46277fffac73', '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', null, 'csit-613/e-commerce-models/q16', 'essay', 'evaluate', 'hard', 'Evaluate platform strategy in a Ghanaian context', '"Network effects mean that in every digital market in Ghana, a single platform will eventually dominate." Critically evaluate this statement with reference to platform theory and at least two Ghanaian or African examples.', null, null, null, 20, array['Define platforms, two-sided markets and network effects (cross-side, same-side, positive, negative)', 'Explain the mechanism by which network effects can lead to concentration', 'Present counter-forces such as multi-homing, low switching costs, negative network effects, local niches, disintermediation and regulation', 'Apply to Ghanaian or African examples such as ride-hailing, marketplaces and mobile money interoperability', 'Reach a reasoned conclusion on when concentration is and is not likely']::text[], '[{"criterion":"Conceptual accuracy","marks":5,"descriptor":"Defines platforms and network effects precisely, including the distinction between cross-side and same-side and between positive and negative effects."},{"criterion":"Argument for concentration","marks":4,"descriptor":"Explains the virtuous circle and why winner-take-most outcomes can arise, citing Rochet and Tirole or Parker et al. appropriately."},{"criterion":"Counter-arguments","marks":5,"descriptor":"Analyses multi-homing, switching costs, governance failures, disintermediation and regulation as limits on dominance."},{"criterion":"Application to examples","marks":4,"descriptor":"Uses accurate, well-known facts about Ghanaian or African platforms without invented statistics."},{"criterion":"Conclusion","marks":2,"descriptor":"Reaches a balanced, conditional conclusion supported by the argument."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e273d0c7-29f1-5b9c-986d-46277fffac73', '{}'::jsonb, 'Examiners look for precise use of platform concepts, a balanced argument that recognises counter-forces, accurate examples and a conditional conclusion.', 'A strong answer opens by defining a platform as a business that facilitates interactions between interdependent groups and explains that cross-side network effects create a virtuous circle: more sellers attract more buyers and vice versa, while data improves matching. Where these effects are strong and users single-home, markets tend towards concentration, which supports the statement.

The answer should then challenge the word "every". Multi-homing is common in Ghanaian ride-hailing, where many drivers and riders use more than one app, so network effects provide weaker protection and several platforms coexist. Switching costs are low when the service is standardised. Negative network effects from fraud or poor quality can push users away if governance is weak. Disintermediation is a strong force in Ghana''s relationship-based markets: once a buyer has a seller''s WhatsApp contact, the platform may be bypassed. Regulation can also reduce the advantages of size, as with mobile money interoperability, which allowed customers on different networks and banks to transact with one another and so reduced the value of being on the largest network alone.

Examples might include ride-hailing competition, marketplaces that combine first- and third-party sales, and M-Pesa in Kenya as a contrasting case of a dominant mobile money platform. The conclusion should be conditional: concentration is likely where cross-side effects are strong, multi-homing is costly and governance is good; it is unlikely where services are standardised, users multi-home and regulators promote interoperability.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8a7d2137-3c1f-5ee2-ae7f-df0565b97146', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', 'dd193a1b-6e35-575c-a758-94825be0030a', 'On which dimensions should B2B, B2C, C2C and C2B be compared?', 'Seller and buyer, transaction value, buying process, pricing mechanism, payment method, main trust problem and key technologies.', 'supplementary', 'csit-613/e-commerce-models/135411b39279', true)
