insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c36b4d83-6b6d-59c4-8fc1-9c04ed482ae2', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', 'dd193a1b-6e35-575c-a758-94825be0030a', 'Name four forms of B2B e-commerce.', 'Direct selling through customer portals, e-procurement systems, EDI or API integration between buyer and supplier, B2B marketplaces, and private industrial networks.', 'supplementary', 'csit-613/e-commerce-models/55a8a3159791', true)
