insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3617c88e-04fa-5c6b-b254-728032cad025', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', 'dd193a1b-6e35-575c-a758-94825be0030a', 'What is the central problem of C2C e-commerce and how do platforms address it?', 'Trust between strangers; platforms use ratings, identity verification, escrow-style payment holding and dispute resolution.', 'supplementary', 'csit-613/e-commerce-models/347c3db7a2be', true)
