insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ea4d8817-ded7-5a5e-8bc0-8da08f2bd438', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', 'dd193a1b-6e35-575c-a758-94825be0030a', 'Give three examples of C2B e-commerce.', 'Freelancers selling services to firms via work platforms, photographers licensing images to stock sites used by businesses, and creators paid by brands for promotion.', 'supplementary', 'csit-613/e-commerce-models/680b45fbb106', true)
