insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ede64d5c-1c78-57b7-aa92-d9af8e92575a', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', 'dd193a1b-6e35-575c-a758-94825be0030a', 'How does transaction cost economics explain the value of e-commerce models?', 'Digital tools reduce the costs of searching, negotiating, contracting and monitoring, for example integration cuts B2B order processing costs and reputation systems cut the cost of assessing unknown C2C sellers.', 'supplementary', 'csit-613/e-commerce-models/ab1fe3961bc7', true)
