insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9f20a8cd-4a2c-52ae-94e2-01b107f3267c', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', 'dd193a1b-6e35-575c-a758-94825be0030a', 'What did Alipay originally do for Taobao''s C2C marketplace?', 'It acted as an escrow-style service, holding the buyer''s payment until the buyer confirmed receipt, which addressed trust between strangers.', 'supplementary', 'csit-613/e-commerce-models/c5533598b451', true)
