insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('688bb0ad-fb10-583c-a269-d00f36db0a54', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'How does a pipeline business differ from a platform business?', 'A pipeline controls a linear chain (buy inputs, transform, sell); a platform creates value by facilitating interactions between external producers and consumers.', 'supplementary', 'csit-613/e-commerce-models/c2e02ef278f1', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8732d2ea-3b7b-59b2-bf4b-761d842180ba', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'What are the three components of a platform''s core interaction (Parker et al.)?', 'Participants (producer and consumer), the value unit (for example a listing) and the filter that matches value units to consumers.', 'supplementary', 'csit-613/e-commerce-models/67d275a985eb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('91b790a4-c389-57f2-9b00-7e1665ffbbc4', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'What is the key insight of Rochet and Tirole (2003) about platform pricing?', 'The structure of prices across sides matters, not just the level; it is often optimal to subsidise the price-sensitive side whose presence creates value for the other and charge the side that values access more.', 'supplementary', 'csit-613/e-commerce-models/4cce7ea70654', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8b78ca49-5ac9-5ba6-9f4d-a3a87708de03', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'List four strategies for solving the chicken-and-egg problem.', 'Subsidise one side, seed the platform with its own supply, start in a dense niche, piggyback on an existing user base, or provide stand-alone value to one side.', 'supplementary', 'csit-613/e-commerce-models/9aa54286fa05', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e4cc4b4f-3454-50d6-8088-5fa7fecb952c', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'Why does multi-homing weaken network-effect advantages?', 'If users can easily use several platforms at once, no single platform captures all the network benefits, so competitors can survive and switching is easy.', 'supplementary', 'csit-613/e-commerce-models/749d40e023d5', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9d4b30e5-da95-52ed-b55d-af22dcf7b1a4', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'dda3c643-6999-5f37-9e2d-9741da5ee243', '9959f400-42b1-536c-9e02-3c84c4ff109d', 'What is disintermediation risk for a platform, and how is it reduced?', 'Users bypass the platform after being matched; it is reduced by providing ongoing value inside the platform (payment protection, scheduling, reputation, insurance) and fair value sharing.', 'supplementary', 'csit-613/e-commerce-models/920e80ef9bbe', true)
