insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('e09cc604-b642-50f6-acc7-46a7c60f4aac', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e-commerce-technology', 'E-Commerce Technology', 'The systems that make an online business work.', 3, true)
