insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('185bed1e-5ac5-5d42-ac33-4d66e783a18a', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e09cc604-b642-50f6-acc7-46a7c60f4aac', '3a174381-48c3-5f73-b258-6befad24c449', 'csit-613/e-commerce-technology/q02', 'mcq', 'understand', 'medium', 'Explain products, variants and SKUs', 'A shop sells one T-shirt design in three sizes and four colours. How should this be modelled in the catalogue?', null, null, '[{"id":"a","text":"Twelve separate products with no link between them"},{"id":"b","text":"One product with twelve variants, each with its own SKU, price and stock level"},{"id":"c","text":"One SKU with a note describing sizes and colours"},{"id":"d","text":"Three products, one per size, each with four colour images"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
