insert into public.question_keys (question_id, correct, explanation, model_answer) values ('185bed1e-5ac5-5d42-ac33-4d66e783a18a', '{"option":"b"}'::jsonb, 'Variants under one product keep listings clean and allow per-variant stock and price. Separate products clutter search; a single SKU cannot track stock by size and colour; splitting only by size is inconsistent.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('65b3bbf0-85c4-5132-870b-0d7d8fccbbd3', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e09cc604-b642-50f6-acc7-46a7c60f4aac', '3a174381-48c3-5f73-b258-6befad24c449', 'csit-613/e-commerce-technology/q03', 'true_false', 'understand', 'easy', 'Understand the effect of forced account creation', 'Requiring every shopper to create an account before checkout is a recommended way to reduce cart abandonment.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
