insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('44b821b6-9ae7-5717-b8a8-726b47d516a7', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e09cc604-b642-50f6-acc7-46a7c60f4aac', '3a174381-48c3-5f73-b258-6befad24c449', 'csit-613/e-commerce-technology/q04', 'short_answer', 'recall', 'easy', 'Recall the term for decoupled front-end commerce architecture', 'What term describes an architecture in which the front-end presentation layer is separated from the commerce back end and connected through APIs?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
