insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f5722874-6f9c-529b-94e0-b3a4468c5645', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e09cc604-b642-50f6-acc7-46a7c60f4aac', '3a174381-48c3-5f73-b258-6befad24c449', 'csit-613/e-commerce-technology/q05', 'scenario', 'apply', 'medium', 'Apply the friction audit to a Ghanaian checkout', 'Which set of changes best addresses the evidence?', 'Illustrative scenario. A Kumasi electronics shop''s website shows the delivery fee only on the final payment page, accepts only card payments and requires a full street address. Analytics show most abandonment happens at the payment step.', null, '[{"id":"a","text":"Add more product photos and a blog"},{"id":"b","text":"Show the delivery fee in the cart, add mobile money through a payment service provider, and accept a digital address or landmark"},{"id":"c","text":"Require customers to create an account so that they feel committed"},{"id":"d","text":"Increase prices to cover lost sales"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
