insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f5722874-6f9c-529b-94e0-b3a4468c5645', '{"option":"b"}'::jsonb, 'The evidence points to late cost disclosure, missing preferred payment methods and unsuitable address fields. Product photos affect earlier funnel stages, forced accounts add friction, and price rises do not fix abandonment.', null)
