insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b24204d8-673d-533f-bbdc-c5d9ffd606b9', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e09cc604-b642-50f6-acc7-46a7c60f4aac', '3a174381-48c3-5f73-b258-6befad24c449', 'csit-613/e-commerce-technology/q06', 'mcq', 'evaluate', 'hard', 'Evaluate storefront options for an SME', 'A small Ghanaian bakery with no in-house developer wants online pre-orders with mobile money payment, launched within a month and at low cost. Which option is most appropriate?', null, null, '[{"id":"a","text":"A custom headless build with a bespoke mobile app"},{"id":"b","text":"A SaaS or simple hosted store integrated with a local payment service provider, possibly alongside WhatsApp ordering"},{"id":"c","text":"Self-hosted open-source software maintained by the owner"},{"id":"d","text":"Waiting until it can afford an enterprise platform"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b24204d8-673d-533f-bbdc-c5d9ffd606b9', '{"option":"b"}'::jsonb, 'SaaS options give a fast, low-maintenance launch, and local PSP plugins provide mobile money. Custom builds are costly and slow; self-hosting shifts security and updates to someone without skills; waiting forgoes demand.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5c8b54f7-acb2-581c-81fa-fc62791ba24c', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e09cc604-b642-50f6-acc7-46a7c60f4aac', '5b64b618-a84f-5ef0-ba91-00711a1d957d', 'csit-613/e-commerce-technology/q07', 'mcq', 'understand', 'medium', 'Explain how an order moves from pending payment to confirmed', 'In a typical integration, what usually moves a mobile money order from "pending payment" to "confirmed" in the merchant''s system?', null, null, '[{"id":"a","text":"The customer refreshing the order page"},{"id":"b","text":"A callback or webhook from the payment provider confirming a successful payment, ideally verified by the merchant"},{"id":"c","text":"The courier collecting the parcel"},{"id":"d","text":"The merchant assuming success after five minutes"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
