insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5c8b54f7-acb2-581c-81fa-fc62791ba24c', '{"option":"b"}'::jsonb, 'Payment providers notify merchants asynchronously, and merchants should verify the status before fulfilling. Page refreshes and assumptions are unreliable, and dispatch happens only after confirmation.', null)
