insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('586cde49-9657-5736-a1ad-f36c0698e977', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e09cc604-b642-50f6-acc7-46a7c60f4aac', 'e6d3ebef-21b1-526b-93ca-c198e8ee3ae8', 'csit-613/e-commerce-technology/q18', 'mcq', 'evaluate', 'hard', 'Evaluate measurement approaches for social and WhatsApp sales', 'A Ghanaian SME closes most sales in WhatsApp chats paid by mobile money, so web analytics show few conversions. What is the best way to evaluate which campaigns work?', null, null, '[{"id":"a","text":"Conclude that digital marketing does not work and stop it"},{"id":"b","text":"Use campaign-specific discount codes or WhatsApp links and record the order source in the order system"},{"id":"c","text":"Rely only on social media follower counts"},{"id":"d","text":"Assume all sales came from the most recent campaign"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
