insert into public.question_keys (question_id, correct, explanation, model_answer) values ('586cde49-9657-5736-a1ad-f36c0698e977', '{"option":"b"}'::jsonb, 'Codes, unique links and order-source fields connect off-site sales to campaigns. Follower counts are vanity metrics, and assumptions do not measure anything.', null)
