insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4209183d-5d97-5038-aba3-3a6d56f878b9', '{"option":"a"}'::jsonb, 'Expected loss = PD × LGD × EAD = 0.05 × 0.75 × 800 = GHS 30. GHS 40 ignores LGD; GHS 600 ignores PD; GHS 3.75 omits the exposure.', null)
