insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6ff1a041-38b6-59d1-8a6b-483da89a93be', '289f40af-c81b-540f-85f0-62d76d5630d3', '998d23b2-73cf-5989-a5c8-16d3349e3a25', 'bc4d46ef-74d1-5bba-bcbe-fe7370a6dee8', 'csit-613/digital-finance/q05', 'mcq', 'analyse', 'medium', 'Analyse the main purpose of UK open banking', 'What was the principal policy objective behind the introduction of open banking in the United Kingdom?', null, null, '[{"id":"a","text":"To replace banks with technology companies"},{"id":"b","text":"To increase competition by letting customers share their data with authorised third parties"},{"id":"c","text":"To abolish card payments"},{"id":"d","text":"To allow banks to sell customer data for profit"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
