insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6ff1a041-38b6-59d1-8a6b-483da89a93be', '{"option":"b"}'::jsonb, 'Open banking followed a Competition and Markets Authority investigation and aimed to reduce incumbents'' informational advantage. It did not aim to replace banks, abolish cards or monetise data without consent.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('97a7877f-ed85-5854-840d-9aa91279696e', '289f40af-c81b-540f-85f0-62d76d5630d3', '998d23b2-73cf-5989-a5c8-16d3349e3a25', 'bc4d46ef-74d1-5bba-bcbe-fe7370a6dee8', 'csit-613/digital-finance/q06', 'mcq', 'evaluate', 'hard', 'Evaluate responses to a loss-making digital loan product', 'A digital lender''s expected loss exceeds its expected fee income. Which response best balances viability and consumer protection?', null, null, '[{"id":"a","text":"Sharply raise fees for all borrowers"},{"id":"b","text":"Improve credit scoring with consented transaction data and start new borrowers on small limits that grow with repayment"},{"id":"c","text":"Lend larger amounts to spread fixed costs"},{"id":"d","text":"Remove affordability checks to speed up approvals"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('97a7877f-ed85-5854-840d-9aa91279696e', '{"option":"b"}'::jsonb, 'Better data and graduated limits reduce default risk and exposure while new information accumulates. Raising fees invites adverse selection and over-indebtedness, larger loans raise exposure, and removing checks increases harm.', null)
