insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e7b5a46b-a5bb-57b0-a098-5f18ecb4176c', '{"option":"a"}'::jsonb, 'Cash-in raises cash and lowers e-float; cash-out does the reverse. Cash = 4,000 + 2,500 − 1,000 = 5,500; e-float = 3,000 − 2,500 + 1,000 = 1,500. Total liquidity stays at GHS 7,000.', null)
