insert into public.question_keys (question_id, correct, explanation, model_answer) values ('22178fcd-91b0-58d2-82ff-47747fde292a', '{"option":"b"}'::jsonb, 'When anyone can pay anyone, the benefit of being on the biggest network shrinks, but every user gains. Competition moves to reliability, agent quality, fees and services. Agents remain needed for cash.', null)
