insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('97b148fa-6832-5b8c-88aa-b14400dd8326', '289f40af-c81b-540f-85f0-62d76d5630d3', '998d23b2-73cf-5989-a5c8-16d3349e3a25', '3748932f-a591-55eb-814e-f59d069ecef7', 'csit-613/digital-finance/q18', 'scenario', 'analyse', 'hard', 'Diagnose an integration flaw causing unpaid orders to ship', 'What is the most appropriate correction?', 'Illustrative scenario. An online shop in Accra marks orders as paid as soon as the customer''s browser returns to the "success" page after a mobile money checkout. Several orders were shipped although the PSP later reported the payments as failed after the customer did not approve the prompt.', null, '[{"id":"a","text":"Ask customers to send screenshots of their payment confirmation"},{"id":"b","text":"Mark orders as paid only after a verified webhook or server-side status check confirms success, keeping others in a pending state with a timeout"},{"id":"c","text":"Stop accepting mobile money"},{"id":"d","text":"Ship orders only on weekdays"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
