insert into public.question_keys (question_id, correct, explanation, model_answer) values ('97b148fa-6832-5b8c-88aa-b14400dd8326', '{"option":"b"}'::jsonb, 'Redirects do not prove payment. Server-side verification of the PSP status, with explicit pending handling, prevents shipping unpaid orders. Screenshots can be faked, abandoning mobile money loses customers, and timing is irrelevant.', null)
