insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4344897c-be61-54f6-83ac-8e94d235340f', '289f40af-c81b-540f-85f0-62d76d5630d3', '998d23b2-73cf-5989-a5c8-16d3349e3a25', '3748932f-a591-55eb-814e-f59d069ecef7', 'csit-613/digital-finance/q20', 'true_false', 'understand', 'medium', 'Distinguish refunds from chargebacks', 'A chargeback is a refund that the merchant initiates voluntarily after a customer complains.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
