insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4344897c-be61-54f6-83ac-8e94d235340f', '{"value":false}'::jsonb, 'A refund is merchant-initiated. A chargeback is initiated by the cardholder through the issuer under card scheme rules, and the merchant may contest it with evidence.', null)
