insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('57549742-3979-51ff-a126-4a9cc4e524fa', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '998d23b2-73cf-5989-a5c8-16d3349e3a25', '2972e880-4bff-5a77-a19f-61c6a3f95e98', 'Why does issuing e-money not create new money like bank lending?', 'E-money is issued in exchange for funds held in trust or custodial accounts, so it converts cash into a backed electronic claim rather than extending credit.', 'supplementary', 'csit-613/digital-finance/afd27ed5bc2f', true)
