insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3a844014-b764-5502-a9e2-e3def14ea784', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '998d23b2-73cf-5989-a5c8-16d3349e3a25', '2972e880-4bff-5a77-a19f-61c6a3f95e98', 'How do cash-in and cash-out affect an agent''s cash and e-float?', 'Cash-in raises cash and lowers e-float; cash-out lowers cash and raises e-float. Total liquidity is unchanged apart from commissions.', 'supplementary', 'csit-613/digital-finance/fcde3d11cfda', true)
