insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ba0fd9b5-a89b-52ee-a0ae-9286ee7cd630', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'b594a2ff-948e-5c3f-83bf-b4fddc8c31ed', 'ed51e0f2-329f-5c98-89d4-0c1d46f1bd0b', 'What is the main weakness of a purely rule-based fraud system?', 'Rigidity, fraudsters learn and stay beneath thresholds, and large overlapping rule sets generate many false positives.', 'supplementary', 'csit-613/payment-security/9d25a79401e2', true)
