insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1c2369fc-16a3-5841-ada7-bd8e925dde47', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'csit-613/blockchain-and-digital-finance/bc01', 'mcq', 'understand', 'easy', 'Explain how linked blocks make a ledger tamper-evident', 'Why does altering a transaction in an old block become detectable?', null, null, '[{"id":"a","text":"Because transactions are encrypted and cannot be read"},{"id":"b","text":"Because the change alters the block''s Merkle root and header hash, breaking the previous-hash link stored in the next block"},{"id":"c","text":"Because each block is stored on a central server that logs changes"},{"id":"d","text":"Because miners delete blocks older than one day"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1c2369fc-16a3-5841-ada7-bd8e925dde47', '{"option":"b"}'::jsonb, 'Each block header commits to its transactions through the Merkle root and to its predecessor through the previous-hash field, so any change cascades into mismatched hashes. Transactions on public chains are usually not encrypted, there is no central server, and old blocks are not deleted.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('75de9ead-fa5d-5858-aa6a-cb8c76fa0c3f', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'csit-613/blockchain-and-digital-finance/bc02', 'true_false', 'understand', 'easy', 'Distinguish hashing from encryption', 'A cryptographic hash such as SHA-256 is designed to be decrypted by someone who holds the correct key.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('75de9ead-fa5d-5858-aa6a-cb8c76fa0c3f', '{"value":false}'::jsonb, 'Hash functions are one-way and keyless; pre-image resistance means the input cannot feasibly be recovered from the digest. Encryption, by contrast, is designed to be reversible with a key.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('86bbbaa7-a060-56a3-a629-e41d077b36ed', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'csit-613/blockchain-and-digital-finance/bc03', 'short_answer', 'apply', 'medium', 'Apply Merkle proof sizing', 'Approximately how many sibling hashes are needed in a Merkle proof for a block containing 16 transactions?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('86bbbaa7-a060-56a3-a629-e41d077b36ed', '{"answers":["4","four"]}'::jsonb, 'A Merkle proof needs roughly log2(n) sibling hashes; log2(16) = 4. This logarithmic growth is what lets lightweight wallets verify inclusion without downloading entire blocks.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('fc471984-b78c-520e-a2fd-f5cb3a13a0cd', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'csit-613/blockchain-and-digital-finance/bc04', 'matching', 'recall', 'medium', 'Match consensus mechanisms to their characteristics', 'Match each consensus mechanism to its defining characteristic.', null, null, '{"left":[{"id":"l1","text":"Proof of work"},{"id":"l2","text":"Proof of stake"},{"id":"l3","text":"Practical Byzantine Fault Tolerance"},{"id":"l4","text":"Centralised database"}],"right":[{"id":"r3","text":"Voting among known validators giving deterministic finality"},{"id":"r4","text":"Single operator decides the authoritative record"},{"id":"r1","text":"Computational puzzle with probabilistic finality"},{"id":"r2","text":"Validators lock capital that can be slashed for misbehaviour"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('fc471984-b78c-520e-a2fd-f5cb3a13a0cd', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Proof of work secures the chain by expended computation, proof of stake by capital at risk, and BFT protocols by rounds of voting among a known set that tolerates fewer than one-third faulty members. A centralised database has no consensus problem because one party is trusted.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('62bae4f6-3334-56f0-a70a-7b3f74bdf26b', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'csit-613/blockchain-and-digital-finance/bc05', 'scenario', 'evaluate', 'hard', 'Evaluate whether a blockchain is needed', 'Using a decision framework such as Wüst and Gervais (2018), what is the best recommendation?', 'A single supermarket chain in Ghana wants to run a loyalty points scheme. Only the chain issues and redeems points, and customers trust it to keep the records. A consultant proposes building the scheme on a permissioned blockchain.', null, '[{"id":"a","text":"Use a public permissionless blockchain to maximise transparency"},{"id":"b","text":"Use a permissioned blockchain with BFT consensus among the chain''s branches"},{"id":"c","text":"Use a conventional database, because there is a single trusted writer"},{"id":"d","text":"Use proof of work so that customers can mine points"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('62bae4f6-3334-56f0-a70a-7b3f74bdf26b', '{"option":"c"}'::jsonb, 'With one writer that participants already trust, the framework points to a conventional database, which is simpler and cheaper. Public or permissioned blockchains add cost without solving a trust problem, and mining points would be absurdly inefficient.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8102ea52-1e8b-5e80-978a-d71ca3715566', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'csit-613/blockchain-and-digital-finance/bc06', 'true_false', 'analyse', 'medium', 'Analyse the limits of blockchain for supply-chain data quality', 'Recording cocoa lots on a blockchain guarantees that the origin information entered by a warehouse clerk is accurate.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8102ea52-1e8b-5e80-978a-d71ca3715566', '{"value":false}'::jsonb, 'A blockchain prevents undetected alteration after recording but cannot verify the truth of inputs. Physical controls, audits and digital identity for participants are needed to address the "garbage in, garbage out" problem.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('973d9d66-0bae-5187-9383-faeb49a7553c', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'csit-613/blockchain-and-digital-finance/bc07', 'mcq', 'analyse', 'hard', 'Analyse the risk of probabilistic finality', 'Why might a merchant accepting a proof-of-work cryptocurrency payment wait for several further blocks before releasing high-value goods?', null, null, '[{"id":"a","text":"Because the transaction is encrypted until several blocks pass"},{"id":"b","text":"Because a chain reorganisation could remove the block containing the payment, and each extra block makes this less likely"},{"id":"c","text":"Because miners charge the merchant per block waited"},{"id":"d","text":"Because the customer''s private key is only valid after several blocks"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('973d9d66-0bae-5187-9383-faeb49a7553c', '{"option":"b"}'::jsonb, 'Proof of work offers probabilistic finality; a competing longer chain could displace recent blocks, enabling double spending. Waiting for confirmations reduces this risk. Transactions are not encrypted, merchants are not charged per block, and private keys do not have block-based validity.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('cc1ecf6f-01e8-530e-aad1-0ed7db56a673', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '68173535-1095-58eb-a773-cb619df37835', 'csit-613/blockchain-and-digital-finance/bc08', 'mcq', 'understand', 'easy', 'Explain custodial wallet risk', 'What is the main additional risk of holding cryptocurrency in a custodial wallet at an exchange?', null, null, '[{"id":"a","text":"The user may forget the recovery phrase"},{"id":"b","text":"Counterparty risk if the exchange fails, is hacked or misuses customer assets"},{"id":"c","text":"The blockchain will reject transactions from exchanges"},{"id":"d","text":"Transactions become reversible by the central bank"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('cc1ecf6f-01e8-530e-aad1-0ed7db56a673', '{"option":"b"}'::jsonb, 'In a custodial wallet the exchange controls the keys, so customers depend on its solvency and security, as the FTX collapse illustrated. Forgetting a recovery phrase is a non-custodial risk; blockchains accept exchange transactions; and central banks cannot reverse crypto transactions.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d19b48eb-2602-5d1e-94a6-44ac9a5e8641', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '68173535-1095-58eb-a773-cb619df37835', 'csit-613/blockchain-and-digital-finance/bc09', 'matching', 'understand', 'medium', 'Match stablecoin designs to their principal risks', 'Match each stablecoin type to its main risk.', null, null, '{"left":[{"id":"l1","text":"Fiat-collateralised"},{"id":"l2","text":"Crypto-collateralised"},{"id":"l3","text":"Algorithmic"}],"right":[{"id":"r2","text":"Sharp falls in collateral value triggering liquidations"},{"id":"r3","text":"Loss of confidence causing a collapse of the peg"},{"id":"r1","text":"Quality and transparency of the issuer''s reserves"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d19b48eb-2602-5d1e-94a6-44ac9a5e8641', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'Each design''s stability rests on a different foundation, so each fails differently. Fiat-backed coins depend on reserves; crypto-backed coins on volatile collateral; algorithmic coins on market confidence, as the TerraUSD collapse demonstrated.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8034b3a1-e615-5357-94be-ab7465efb8cb', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '68173535-1095-58eb-a773-cb619df37835', 'csit-613/blockchain-and-digital-finance/bc10', 'short_answer', 'recall', 'easy', 'Recall the term for external data providers to smart contracts', 'What is the term for a service that supplies off-chain data, such as delivery confirmation, to a smart contract?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8034b3a1-e615-5357-94be-ab7465efb8cb', '{"answers":["oracle","an oracle","blockchain oracle"]}'::jsonb, 'Oracles bridge the blockchain and the real world. The oracle problem is that a contract is only as trustworthy as the oracle feeding it.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('88b5dea4-4039-517e-8b08-67eef50b7c5e', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '68173535-1095-58eb-a773-cb619df37835', 'csit-613/blockchain-and-digital-finance/bc11', 'scenario', 'analyse', 'hard', 'Analyse where trust lies in a smart contract escrow', 'Which statement best describes the trust structure of this arrangement?', 'A Tema importer and an overseas supplier use a smart contract escrow. Funds are released to the supplier when the shipping agent''s system calls confirmDelivery(). The importer can claim a refund only if no confirmation arrives before the deadline.', null, '[{"id":"a","text":"The arrangement is completely trustless because it runs on a blockchain"},{"id":"b","text":"Trust has been relocated to the shipping agent acting as oracle, and disputes about damaged goods fall outside the contract"},{"id":"c","text":"The supplier must trust the importer to release the funds manually"},{"id":"d","text":"The central bank guarantees the outcome of the contract"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('88b5dea4-4039-517e-8b08-67eef50b7c5e', '{"option":"b"}'::jsonb, 'The contract removes the need to trust the counterparty with funds but depends on the oracle''s honesty and security, and it has no logic for partial or damaged delivery, which would require off-chain dispute resolution. Funds are not released manually, and no central bank guarantees smart contracts.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('299d8088-730f-5e5b-ba45-ecc35fb718e3', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '68173535-1095-58eb-a773-cb619df37835', 'csit-613/blockchain-and-digital-finance/bc12', 'true_false', 'understand', 'medium', 'Distinguish CBDC from mobile money', 'Mobile money balances in Ghana are a direct liability of the Bank of Ghana, which makes them a form of CBDC.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('299d8088-730f-5e5b-ba45-ecc35fb718e3', '{"value":false}'::jsonb, 'Mobile money is electronic money issued by licensed issuers and backed by funds held in trust at banks; it is a liability of the issuer, not the central bank. A CBDC would be a direct central bank liability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8878af32-ae18-57d9-a08a-08b92a3e0a7d', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '68173535-1095-58eb-a773-cb619df37835', 'csit-613/blockchain-and-digital-finance/bc13', 'matching', 'apply', 'medium', 'Apply digital identity models to examples', 'Match each example to the identity model it best represents.', null, null, '{"left":[{"id":"l1","text":"A national register issuing a biometric ID card"},{"id":"l2","text":"Many websites accepting a single \"sign in with\" provider"},{"id":"l3","text":"A graduate holding a signed degree credential in a personal wallet"}],"right":[{"id":"r1","text":"Centralised identity"},{"id":"r3","text":"Self-sovereign identity"},{"id":"r2","text":"Federated identity"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8878af32-ae18-57d9-a08a-08b92a3e0a7d', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'Centralised identity relies on a single authority; federated identity on a trusted provider authenticating users for many services; self-sovereign identity on individuals holding verifiable credentials and disclosing them selectively.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('51ffbe7b-405f-5ad1-8661-d4ce376d0a56', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '68173535-1095-58eb-a773-cb619df37835', 'csit-613/blockchain-and-digital-finance/bc14', 'mcq', 'evaluate', 'hard', 'Evaluate CBDC design choices for inclusion', 'A central bank wants a retail CBDC that supports financial inclusion in areas with weak connectivity while protecting bank deposit stability. Which combination of design features is most consistent with these goals?', null, null, '[{"id":"a","text":"Direct issuance to citizens, online-only, unlimited holdings"},{"id":"b","text":"Intermediated distribution, offline capability, holding limits"},{"id":"c","text":"Wholesale-only access for banks, no retail use"},{"id":"d","text":"Anonymous bearer tokens with no limits and no intermediaries"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('51ffbe7b-405f-5ad1-8661-d4ce376d0a56', '{"option":"b"}'::jsonb, 'Intermediated models leverage existing banks and payment providers; offline capability serves low-connectivity areas; holding limits reduce the risk of rapid deposit outflows. Online-only and unlimited designs work against both goals, wholesale-only excludes the public, and unlimited anonymous tokens raise integrity and stability concerns.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a24128ed-c951-5b5f-81f2-1df2b500abb9', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', null, 'csit-613/blockchain-and-digital-finance/bc15', 'case_analysis', 'evaluate', 'hard', 'Evaluate a blockchain proposal for a Ghanaian business consortium', 'Critically evaluate the consortium''s proposal and recommend whether, and how, it should proceed.', null, 'Illustrative scenario: a hypothetical consortium of five Ghanaian agricultural exporters, two warehouse operators and a certification body proposes a "blockchain traceability and payment platform". Lots would be recorded on a permissioned ledger, and a smart contract would automatically pay farmers'' cooperatives in a stablecoin when a certifier confirms quality. Farmer identities would be stored on-chain using their Ghana Card numbers so buyers abroad can verify origin. The consortium argues that the platform will "guarantee honest data" and remove the need for banks.', null, 25, array['Apply a blockchain decision framework to the trust problem', 'Evaluate consensus and governance among consortium members', 'Analyse the smart contract, oracle and stablecoin payment design', 'Evaluate the identity and data protection approach', 'Recommend a revised design and implementation safeguards']::text[], '[{"criterion":"Application of decision framework","marks":5,"descriptor":"Correctly determines whether multiple mutually distrusting writers and the absence of an accepted intermediary justify a permissioned ledger."},{"criterion":"Technical and governance analysis","marks":6,"descriptor":"Discusses consensus among a small known group, governance, onboarding and data-quality limits."},{"criterion":"Payment and smart contract evaluation","marks":6,"descriptor":"Identifies oracle trust in the certifier, stablecoin and regulatory risks, and farmers'' practical need for cedi or mobile money payouts."},{"criterion":"Identity and privacy evaluation","marks":5,"descriptor":"Explains why storing national ID numbers on an immutable ledger conflicts with data protection and proposes alternatives such as off-chain storage or verifiable credentials."},{"criterion":"Recommendation quality","marks":3,"descriptor":"Gives a reasoned, balanced recommendation and notes that the analysis is educational, not regulatory advice."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a24128ed-c951-5b5f-81f2-1df2b500abb9', '{}'::jsonb, 'Examiners look for disciplined use of a decision framework, recognition of the oracle and data-quality problems, regulatory awareness about stablecoins, sound privacy reasoning and a balanced recommendation.', 'A strong answer starts with the trust problem. Several independent organisations write records and may not fully trust one another, and buyers abroad want verifiable claims, so a permissioned ledger is defensible under the Wüst and Gervais framework, provided no existing intermediary is acceptable to all. A BFT-style consensus among the eight members would give fast finality, but governance must define who may join, how disputes are resolved and what happens if members collude.

The claim that the platform "guarantees honest data" should be rejected: the ledger only prevents later alteration. Sealed bags, audits and identity checks at points of entry remain essential.

The payment design needs scrutiny. The certifier acts as an oracle, so the contract relocates trust rather than removing it; a dishonest or compromised certifier could trigger or block payments. Paying farmers'' cooperatives in a stablecoin introduces reserve, conversion and regulatory risks, given the Bank of Ghana''s cautious position on crypto-assets, and cooperatives need cedis or mobile money. A better design records the certification on-chain but triggers payment through a licensed PSP or bank in cedis, so the claim of "removing banks" is neither realistic nor desirable.

Storing Ghana Card numbers on an immutable ledger conflicts with data protection principles under the Data Protection Act, 2012 (Act 843), since data cannot be erased and may be exposed to many parties. Identity should be verified off-chain through authorised services, with only pseudonymous references or verifiable credentials on the ledger.

The recommendation should be a limited pilot of the traceability ledger with off-chain identity and conventional payments, evaluated against clear benefits.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a3b5eca1-8b4c-5a5b-b81e-585989621de0', '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', null, 'csit-613/blockchain-and-digital-finance/bc16', 'essay', 'evaluate', 'hard', 'Evaluate the potential role of a CBDC alongside mobile money', 'Critically evaluate whether a retail central bank digital currency would add value in an economy where mobile money is already widely used, with reference to Ghana''s eCedi pilot in general terms and international experience.', null, null, null, 20, array['Define CBDC and distinguish it from mobile money and cryptocurrency', 'Identify potential benefits such as resilience, interoperability, inclusion and offline payments', 'Analyse risks including bank disintermediation, privacy and adoption', 'Draw on international experience such as the Sand Dollar and eNaira', 'Reach a reasoned conclusion']::text[], '[{"criterion":"Conceptual clarity","marks":5,"descriptor":"Accurately defines CBDC and contrasts liability and control with mobile money."},{"criterion":"Benefits and risks analysis","marks":7,"descriptor":"Balanced analysis of benefits and risks with clear reasoning."},{"criterion":"Use of evidence","marks":5,"descriptor":"Uses international examples accurately and refers to the eCedi only in general, well-documented terms."},{"criterion":"Conclusion","marks":3,"descriptor":"Justified conclusion recognising uncertainty."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a3b5eca1-8b4c-5a5b-b81e-585989621de0', '{}'::jsonb, 'Examiners reward precise distinctions between forms of money, balanced evaluation, accurate and cautious use of evidence and a conclusion that acknowledges uncertainty.', 'A CBDC is a digital form of the national currency that is a direct liability of the central bank. Mobile money, by contrast, is e-money issued by licensed issuers and backed by funds held in trust at commercial banks. Both are digital, but they differ in who stands behind the value and who sets the rules.

Potential benefits include a public, sovereign payment instrument that could support interoperability across providers, resilience if a private platform fails, offline payment capability for areas with weak connectivity and a foundation for more efficient government payments. The Bank of Ghana''s eCedi pilot has publicly emphasised inclusion and offline use, which suggests these goals.

Risks are significant. If citizens hold large CBDC balances, deposits could leave banks, reducing lending capacity, which is why holding limits and intermediated distribution are commonly proposed. Privacy concerns arise if the central bank could see all transactions. Adoption is uncertain: international experience with the Bahamas'' Sand Dollar and Nigeria''s eNaira suggests that uptake can be slow when users already have convenient alternatives. In a mobile money economy, a CBDC must offer a clear advantage, perhaps in cost, interoperability or offline functionality, or be integrated into existing wallets so that users experience it as an improvement rather than a new product.

A reasoned conclusion is that a CBDC may add value as public infrastructure working through mobile money and banks, rather than competing with them, but its value depends on design choices and remains uncertain while pilots continue.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('33762298-8dc7-59c5-94db-f873d4acd578', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'What four properties make cryptographic hash functions useful in blockchains?', 'Determinism, pre-image resistance, collision resistance and the avalanche effect, together they make a hash a reliable fingerprint of data.', 'supplementary', 'csit-613/blockchain-and-digital-finance/d6e09c163c0d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2cf8193a-3d46-5abf-b9be-5fba4ebd6d91', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'Why is a blockchain described as tamper-evident rather than tamper-proof?', 'Any change alters hashes and breaks links, so alteration is detectable, but history can still be rewritten with enough computation, stake or validator collusion.', 'supplementary', 'csit-613/blockchain-and-digital-finance/fbe5c9d7b225', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bf0d3763-2565-5ffd-b64a-4746f770b655', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'What does a Merkle proof allow a lightweight wallet to do?', 'Verify that a transaction is included in a block using only about log2(n) sibling hashes and the Merkle root, without downloading the whole block.', 'supplementary', 'csit-613/blockchain-and-digital-finance/f51157c41d4d', true)
