insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('caa66220-e517-54cf-9353-8a28f8e41a6e', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'How does finality differ between proof of work and BFT consensus?', 'Proof of work gives probabilistic finality that strengthens with each block; BFT voting among known validators gives fast, deterministic finality.', 'supplementary', 'csit-613/blockchain-and-digital-finance/cac059daac81', true)
