insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5ba983e4-1ced-581d-b0b6-a30997ff664f', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '9827bb23-59a2-5006-8c48-43266c64647e', 'When does the "Do you need a blockchain?" framework point to a conventional database?', 'When there is only one writer, when all writers are trusted, or when an always-available trusted third party can maintain the record.', 'supplementary', 'csit-613/blockchain-and-digital-finance/f7bf60497d26', true)
