  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c73c9e09-5849-5bda-8b28-f9da5c3621d6', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '68173535-1095-58eb-a773-cb619df37835', 'What is the key trade-off between custodial and non-custodial crypto wallets?', 'Custodial wallets are convenient but expose users to exchange failure; non-custodial wallets give full control but loss or exposure of the private key is irreversible.', 'supplementary', 'csit-613/blockchain-and-digital-finance/0de7201e206c', true)
