insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('275feaf0-ef7a-5c66-a33e-718507e02670', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'b12966b4-513b-5255-aa13-669a174cbd9d', '68173535-1095-58eb-a773-cb619df37835', 'Why should personal identity data not be stored directly on a blockchain?', 'Immutable ledgers cannot erase data and replicate it widely, conflicting with data protection principles; store data off-chain and use references or verifiable credentials.', 'supplementary', 'csit-613/blockchain-and-digital-finance/a7acf0200174', true)
