insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('22640f1f-a184-5326-8795-aa4b1d41706e', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'csit-613/e-business-in-ghana/gh01', 'mcq', 'understand', 'easy', 'Explain how e-money is backed', 'What primarily protects mobile money customers'' balances if an e-money issuer fails?', null, null, '[{"id":"a","text":"The issuer lends out balances and holds the loans as security"},{"id":"b","text":"Funds equal to outstanding e-money are held in trust accounts at banks"},{"id":"c","text":"Agents guarantee all balances from their own cash"},{"id":"d","text":"The MNO''s airtime revenue is pledged to customers"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('22640f1f-a184-5326-8795-aa4b1d41706e', '{"option":"b"}'::jsonb, 'E-money must be backed by funds held in trust at banks, ring-fenced from the issuer''s own assets. Unlike bank deposits, these funds are not lent out. Agents hold only their own float, and airtime revenue is not a customer safeguard.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('089f1f3f-a9d3-5661-9689-74b5c18bb448', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'csit-613/e-business-in-ghana/gh02', 'true_false', 'understand', 'easy', 'Understand the effect of cash-in transactions', 'When an agent performs a cash-in transaction, new money is created because the customer''s wallet balance increases.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
