insert into public.question_keys (question_id, correct, explanation, model_answer) values ('089f1f3f-a9d3-5661-9689-74b5c18bb448', '{"value":false}'::jsonb, 'The agent transfers e-float they already own in exchange for the customer''s cash. Total money is unchanged; the agent''s liquidity simply shifts from e-float to cash.', null)
