insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('888ed7b8-f04a-55a2-9d06-c8ebaa39d60b', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'csit-613/e-business-in-ghana/gh03', 'short_answer', 'apply', 'medium', 'Calculate an agent''s e-float after transactions', 'An agent opens with GHS 2,000 e-float and GHS 1,500 cash, then processes cash-ins of GHS 1,200 and cash-outs of GHS 900. What is the agent''s e-float balance in GHS?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('888ed7b8-f04a-55a2-9d06-c8ebaa39d60b', '{"answers":["1700","1,700","GHS 1,700","GHS 1700"]}'::jsonb, 'Cash-ins reduce e-float (2,000 − 1,200 = 800) and cash-outs increase it (800 + 900 = 1,700). Cash moves the opposite way, ending at 1,800, and total liquidity stays at 3,500.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2e5dc1b7-d2de-5481-915e-dfd4a9329f22', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'csit-613/e-business-in-ghana/gh04', 'matching', 'recall', 'easy', 'Match ecosystem actors to their roles', 'Match each actor to its main role in Ghana''s mobile money ecosystem.', null, null, '{"left":[{"id":"l1","text":"Bank of Ghana"},{"id":"l2","text":"GhIPSS"},{"id":"l3","text":"Agents"},{"id":"l4","text":"Banks"}],"right":[{"id":"r4","text":"Hold trust accounts backing e-money"},{"id":"r3","text":"Convert cash to e-value and back for customers"},{"id":"r1","text":"Licenses and supervises payment and e-money providers"},{"id":"r2","text":"Operates the national interoperability switch"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2e5dc1b7-d2de-5481-915e-dfd4a9329f22', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Confusing the regulator (Bank of Ghana) with the switch operator (GhIPSS) is a common error. Agents provide the cash interface, and banks hold the trust funds that back outstanding e-money.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5ff59924-3264-5979-96c4-de1d5581cefe', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'csit-613/e-business-in-ghana/gh05', 'scenario', 'analyse', 'medium', 'Analyse agent liquidity patterns', 'What is the most appropriate response?', 'An agent in a busy market area regularly runs out of e-float in the late afternoon, when traders arrive to deposit the day''s takings, and has to turn customers away.', null, '[{"id":"a","text":"Raise cash-in fees to discourage deposits"},{"id":"b","text":"Rebalance before the afternoon peak by converting surplus cash to e-float, anticipating the pattern"},{"id":"c","text":"Stop offering cash-out services"},{"id":"d","text":"Ask traders to share their PINs so deposits can be processed later"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5ff59924-3264-5979-96c4-de1d5581cefe', '{"option":"b"}'::jsonb, 'The shortage is predictable, so proactive rebalancing through a bank or master agent before the peak solves it. Raising fees damages trust and may breach rules, stopping cash-outs removes the flow that replenishes e-float, and requesting PINs is a serious security breach.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('96a708e5-32f2-5328-8519-bf4e352bca87', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'csit-613/e-business-in-ghana/gh06', 'mcq', 'evaluate', 'hard', 'Evaluate the strategic impact of interoperability', 'Which statement best evaluates the effect of mobile money interoperability on competition in Ghana?', null, null, '[{"id":"a","text":"It ends competition because all wallets become identical"},{"id":"b","text":"It partly shares network effects across providers, shifting competition towards price, reliability and value-added services"},{"id":"c","text":"It benefits only the largest provider"},{"id":"d","text":"It has no effect because customers never send money across networks"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('96a708e5-32f2-5328-8519-bf4e352bca87', '{"option":"b"}'::jsonb, 'When wallets connect, the value of a provider''s large user base is partly shared with rivals, so providers compete on other dimensions. Wallets do not become identical, effects on providers are mixed rather than favouring only the largest, and cross-network transfers are a key use case.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('acd5e5f3-fe42-5d69-af9e-7fd406908a2c', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'csit-613/e-business-in-ghana/gh07', 'true_false', 'recall', 'easy', 'Recall the main payment systems law', 'The Payment Systems and Services Act, 2019 (Act 987) provides the legal framework for licensing and supervising payment systems and electronic money issuers in Ghana.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('acd5e5f3-fe42-5d69-af9e-7fd406908a2c', '{"value":true}'::jsonb, 'Act 987 is the core statute for payment systems and e-money oversight by the Bank of Ghana, alongside related laws on AML, data protection and cybersecurity.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ed1e1bff-cb09-52fe-ab24-b7aa4c55777a', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '8100a598-2f8f-5db2-8051-40ff06fbec5e', 'csit-613/e-business-in-ghana/gh08', 'matching', 'understand', 'medium', 'Match UTAUT constructs to examples', 'Match each UTAUT or UTAUT2 construct to the statement that illustrates it.', null, null, '{"left":[{"id":"l1","text":"Performance expectancy"},{"id":"l2","text":"Effort expectancy"},{"id":"l3","text":"Social influence"},{"id":"l4","text":"Facilitating conditions"},{"id":"l5","text":"Habit"}],"right":[{"id":"r4","text":"Network coverage is reliable and an agent is nearby"},{"id":"r2","text":"Scanning the QR code takes only a few seconds"},{"id":"r5","text":"I always pay cash without thinking about it"},{"id":"r1","text":"Paying by wallet saves me a trip to the bank"},{"id":"r3","text":"My suppliers expect me to accept mobile money"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ed1e1bff-cb09-52fe-ab24-b7aa4c55777a', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Performance expectancy concerns gains, effort expectancy ease, social influence the expectations of others, facilitating conditions available resources and habit automatic behaviour. Accurate mapping is the first step in applying the model.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f36b38bb-6f54-56d5-b7d5-863e0cbe3db6', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '8100a598-2f8f-5db2-8051-40ff06fbec5e', 'csit-613/e-business-in-ghana/gh09', 'mcq', 'recall', 'easy', 'Recall the two core constructs of TAM', 'Which two beliefs are central to Davis''s (1989) Technology Acceptance Model?', null, null, '[{"id":"a","text":"Social influence and habit"},{"id":"b","text":"Perceived usefulness and perceived ease of use"},{"id":"c","text":"Price value and hedonic motivation"},{"id":"d","text":"Trust and perceived risk"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f36b38bb-6f54-56d5-b7d5-863e0cbe3db6', '{"option":"b"}'::jsonb, 'TAM centres on perceived usefulness and perceived ease of use. Social influence comes from UTAUT; price value, hedonic motivation and habit from UTAUT2; trust and risk are common extensions.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('93503638-8f62-5fe6-9872-0b0eb8dfc845', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '8100a598-2f8f-5db2-8051-40ff06fbec5e', 'csit-613/e-business-in-ghana/gh10', 'scenario', 'apply', 'medium', 'Apply a cost model to a cash-on-delivery incentive', 'What is the highest discount per order (as a percentage) at which the conversion still does not lose money?', 'An online retailer converts 300 cash-on-delivery orders a month to prepaid by offering a discount. The conversion produces savings of GHS 1,875 per month from fewer failed deliveries and less cash handling. PSP fees on the converted orders are GHS 1,200 per month, and the average order value is GHS 200.', null, '[{"id":"a","text":"About 1.1%"},{"id":"b","text":"About 3%"},{"id":"c","text":"About 5%"},{"id":"d","text":"Any discount, because prepaid orders are always cheaper"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('93503638-8f62-5fe6-9872-0b0eb8dfc845', '{"option":"a"}'::jsonb, 'The room left for discounts is 1,875 − 1,200 = 675 a month. Spread over 300 orders this is GHS 2.25 per order, which is 1.125% of GHS 200. A 3% or 5% discount would lose money, and the scenario shows that prepaid is not automatically cheaper once PSP fees are counted.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2b429d99-664d-5455-9ee8-7ebb52490372', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '8100a598-2f8f-5db2-8051-40ff06fbec5e', 'csit-613/e-business-in-ghana/gh11', 'true_false', 'analyse', 'medium', 'Analyse the risk allocation of cash on delivery', 'Cash on delivery shifts the risk of non-performance from the customer to the seller.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2b429d99-664d-5455-9ee8-7ebb52490372', '{"value":true}'::jsonb, 'With cash on delivery the customer pays only on receipt, so the seller bears the cost of failed or refused deliveries, rider cash handling and delayed settlement. This is why COD remains popular where trust between strangers is low.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3743aafc-e5df-5d45-b1da-c11bb5691219', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '8100a598-2f8f-5db2-8051-40ff06fbec5e', 'csit-613/e-business-in-ghana/gh12', 'short_answer', 'recall', 'easy', 'Recall the Ghanaian digital addressing system', 'What is the name of Ghana''s national digital address system used to support deliveries?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3743aafc-e5df-5d45-b1da-c11bb5691219', '{"answers":["GhanaPostGPS","Ghana Post GPS","GhanaPost GPS"]}'::jsonb, 'GhanaPostGPS assigns digital address codes to locations. It supports last-mile delivery, although many deliveries still rely on landmarks and phone calls to riders.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('352df502-286a-515b-be79-7810bf199ada', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '8100a598-2f8f-5db2-8051-40ff06fbec5e', 'csit-613/e-business-in-ghana/gh13', 'mcq', 'evaluate', 'hard', 'Evaluate adoption levers for an SME', 'An SME finds that customers are aware of its mobile money checkout but still choose cash on delivery because they fear paying for goods that never arrive. Which intervention most directly addresses the main barrier?', null, null, '[{"id":"a","text":"An advertising campaign explaining that mobile money exists"},{"id":"b","text":"Visible buyer protection, instant order confirmation and a clear refund policy"},{"id":"c","text":"Removing the cash-on-delivery option immediately"},{"id":"d","text":"A larger product catalogue"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('352df502-286a-515b-be79-7810bf199ada', '{"option":"b"}'::jsonb, 'The barrier is trust and perceived risk, not awareness, so trust-building measures are the most direct lever. Awareness campaigns target the wrong problem, removing COD abruptly risks losing customers, and a larger catalogue does not reduce perceived risk.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7fc971bb-6575-5ff0-b755-fa8fe8524189', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '8100a598-2f8f-5db2-8051-40ff06fbec5e', 'csit-613/e-business-in-ghana/gh14', 'matching', 'apply', 'medium', 'Apply diffusion of innovations attributes', 'Match each diffusion of innovations attribute to its illustration for QR code payments in a Ghanaian market.', null, null, '{"left":[{"id":"l1","text":"Relative advantage"},{"id":"l2","text":"Compatibility"},{"id":"l3","text":"Trialability"},{"id":"l4","text":"Observability"}],"right":[{"id":"r4","text":"Neighbouring stalls display QR codes and customers see them used"},{"id":"r1","text":"No need to carry change or count notes"},{"id":"r2","text":"Works with the wallet the trader already uses"},{"id":"r3","text":"A trader can test it with a few customers first"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7fc971bb-6575-5ff0-b755-fa8fe8524189', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Rogers'' attributes explain why some innovations spread faster than others. Applying them to a concrete case turns a list of terms into an analytical tool.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6e700edd-ae3b-548a-a856-d910ce276e8b', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', 'f829445e-db69-5130-b76c-aaa39e61f91b', 'csit-613/e-business-in-ghana/gh15', 'matching', 'understand', 'medium', 'Distinguish PSP roles', 'Match each payment role to its description.', null, null, '{"left":[{"id":"l1","text":"Payment gateway"},{"id":"l2","text":"Aggregator"},{"id":"l3","text":"Acquirer"},{"id":"l4","text":"Payment facilitator"}],"right":[{"id":"r2","text":"One integration connecting a merchant to many payment methods"},{"id":"r4","text":"Onboards many small merchants under its own master account"},{"id":"r3","text":"Holds the card acceptance contract and settles card funds to the merchant"},{"id":"r1","text":"Captures payment details at checkout and routes them for authorisation"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6e700edd-ae3b-548a-a856-d910ce276e8b', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Many providers bundle these roles, but analysing them separately clarifies who does what, who carries which risk and what an SME actually needs.', null)
