insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('807a00ab-0c87-52f2-acee-7cbcbd1012e3', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', 'f829445e-db69-5130-b76c-aaa39e61f91b', 'csit-613/e-business-in-ghana/gh16', 'short_answer', 'apply', 'medium', 'Calculate a weighted PSP score', 'A PSP scores 5, 4, 3, 4, 5 and 3 on criteria weighted 0.25, 0.15, 0.20, 0.15, 0.15 and 0.10. What is its weighted score?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('807a00ab-0c87-52f2-acee-7cbcbd1012e3', '{"answers":["4.1","4.10"]}'::jsonb, '5×0.25 + 4×0.15 + 3×0.20 + 4×0.15 + 5×0.15 + 3×0.10 = 1.25 + 0.60 + 0.60 + 0.60 + 0.75 + 0.30 = 4.10. Weighted scoring turns qualitative judgements into a comparable figure, but it must be backed by evidence and tested for sensitivity.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('24b798a4-70ef-5b90-aed4-0890d89ce4b9', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', 'f829445e-db69-5130-b76c-aaa39e61f91b', 'csit-613/e-business-in-ghana/gh17', 'true_false', 'understand', 'easy', 'Understand the dimensions of financial inclusion', 'A person who has opened a mobile money account but never uses it is fully financially included.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('24b798a4-70ef-5b90-aed4-0890d89ce4b9', '{"value":false}'::jsonb, 'Financial inclusion covers access, usage and quality. An unused account shows access only; inclusion also requires regular use of affordable, suitable and well-protected services.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('70281335-8748-53b7-883a-9588d49012e1', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', 'f829445e-db69-5130-b76c-aaa39e61f91b', 'csit-613/e-business-in-ghana/gh18', 'scenario', 'analyse', 'medium', 'Analyse the effect of weight changes on PSP selection', 'What is the most likely effect, and what does it show?', 'An SME''s weighted scoring model ranks Provider A first, with Provider B close behind. The owner then decides to rely on payment links rather than website plugins, which lowers the weight on APIs and raises the weight on fees. Provider B has lower fees but weaker APIs than A.', null, '[{"id":"a","text":"A stays first, because rankings do not change when weights change"},{"id":"b","text":"B may overtake A, showing that the decision is sensitive to weights that reflect business priorities"},{"id":"c","text":"Both providers must be rejected"},{"id":"d","text":"The model becomes invalid and should be abandoned"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('70281335-8748-53b7-883a-9588d49012e1', '{"option":"b"}'::jsonb, 'Moving weight from a criterion where A is stronger to one where B is stronger can reverse a close ranking, as the lesson''s sensitivity test showed. This is why weights must reflect real priorities and why sensitivity analysis is essential. It does not invalidate the model or require rejecting both providers.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2de04c00-dfa5-5ea5-bed6-87bff8836828', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', 'f829445e-db69-5130-b76c-aaa39e61f91b', 'csit-613/e-business-in-ghana/gh19', 'mcq', 'evaluate', 'hard', 'Evaluate alternative data credit for SMEs', 'Which statement gives the most balanced evaluation of using mobile money transaction histories to lend to SMEs?', null, null, '[{"id":"a","text":"It removes all credit risk because transaction data is accurate"},{"id":"b","text":"It can extend credit to firms without collateral, but needs transparent pricing, fair collection, data protection and attention to firms without digital histories"},{"id":"c","text":"It should be banned because data must never be used for credit"},{"id":"d","text":"It only benefits large firms"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2de04c00-dfa5-5ea5-bed6-87bff8836828', '{"option":"b"}'::jsonb, 'Transaction data can demonstrate cash flow and widen access, but risks include costly or poorly disclosed loans, over-indebtedness, privacy concerns and continued exclusion of firms without data. Credit risk is reduced, not eliminated; outright bans ignore the benefits; and the main beneficiaries are often small firms.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('cffa20df-bd87-5926-be39-5829ebe95805', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', 'f829445e-db69-5130-b76c-aaa39e61f91b', 'csit-613/e-business-in-ghana/gh20', 'true_false', 'apply', 'easy', 'Apply hard constraints in PSP selection', 'A PSP that is not licensed or authorised by the Bank of Ghana should be excluded from an SME''s shortlist even if it achieves the highest weighted score.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('cffa20df-bd87-5926-be39-5829ebe95805', '{"value":true}'::jsonb, 'Licensing is a hard constraint, not a scoring criterion. Weighted scores rank only providers that already meet essential requirements such as regulatory authorisation and adequate reconciliation reporting.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('83e3e1b3-d9de-53b1-a69a-3d4a14dbc168', '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', null, 'csit-613/e-business-in-ghana/gh21', 'case_analysis', 'evaluate', 'hard', 'Evaluate a digital payments strategy for a Ghanaian SME using ecosystem and adoption theory', 'Analyse the case using ecosystem, adoption and inclusion concepts, and recommend a justified digital payment strategy for the business.', null, 'Illustrative scenario: Adom Foods is a hypothetical Kumasi-based producer of packaged gari and spices. It sells to market traders in Kejetia, to two supermarkets and, recently, to individual customers through Instagram and WhatsApp. Traders pay mostly in cash; supermarkets pay by bank transfer after 30 days; online customers pay by cash on delivery or by sending mobile money to the owner''s personal number. The owner wants to grow online sales, reduce cash handling and qualify for a working-capital loan, but several traders say they distrust digital payments after hearing about fraud, and some worry about fees and taxes.', null, 25, array['Map the relevant ecosystem actors and payment flows', 'Apply UTAUT2 and trust to explain traders'' and online customers'' behaviour', 'Evaluate PSP and acceptance options with selection criteria', 'Link the strategy to records, reconciliation and access to credit', 'Identify risks, safeguards and a phased plan']::text[], '[{"criterion":"Ecosystem analysis","marks":5,"descriptor":"Accurately maps customers, traders, supermarkets, issuers, PSPs, banks and the regulator, and the flows between them."},{"criterion":"Application of adoption theory","marks":6,"descriptor":"Applies UTAUT2 constructs and trust to each customer segment with specific reasoning."},{"criterion":"Payment option evaluation","marks":6,"descriptor":"Compares merchant wallets, aggregators, QR codes and payment links with clear criteria and hard constraints."},{"criterion":"Inclusion and credit linkage","marks":5,"descriptor":"Explains how structured records support credit while noting risks of costly digital credit."},{"criterion":"Risks and implementation plan","marks":3,"descriptor":"Presents a realistic phased plan with safeguards, noting the analysis is educational, not financial advice."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('83e3e1b3-d9de-53b1-a69a-3d4a14dbc168', '{}'::jsonb, 'Examiners look for segment-specific application of adoption theory, a clear ecosystem map, evidence-based PSP selection, an explicit link between records and credit, and a realistic, phased plan.', 'A strong answer first maps the ecosystem: traders and online customers paying through cash or wallets on different networks; supermarkets paying by bank transfer; e-money issuers and banks; a possible PSP or aggregator; and the Bank of Ghana as regulator. The key structural problem is that online receipts go to a personal wallet, mixing funds and leaving no records for reconciliation or lenders.

Applying UTAUT2, the traders'' reluctance reflects low trust and high perceived risk, price value concerns about fees and taxes, and strong cash habit; performance expectancy is modest because cash already works for them. Online customers face a different barrier: fear of paying for goods that never arrive, which COD resolves at the seller''s expense.

The strategy should therefore differ by segment. For online sales, a licensed aggregator offering payment links, prompts and cards across networks, with instant confirmation and a clear refund policy, addresses trust and effort. For traders, a merchant wallet and a universal QR code, introduced gradually with demonstrations, increases trialability and observability; Adom should never ask for PINs and should explain fees transparently. Supermarket transfers already create records. PSP choice should apply weighted criteria with hard constraints such as licensing and reconciliation reports.

Linking to inclusion, consolidated merchant collections and daily reconciliation produce a transaction history that can support a working-capital loan application, but the owner should compare loan costs carefully and avoid expensive short-term digital credit.

Risks include fraud, platform outages and customer loss if cash is withdrawn too quickly; a phased plan keeps cash and COD available while digital channels grow.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2357a1e2-ebaf-53df-b2c7-96001dfcb912', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'How does e-money differ from a bank deposit?', 'E-money is backed by funds held in trust at banks equal to outstanding balances and is not lent out; a bank deposit is a bank liability that the bank can lend.', 'supplementary', 'csit-613/e-business-in-ghana/9d6ee6239be4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('42f55c01-7bc5-58f0-a5c2-79c52edbdf2f', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'What happens to an agent''s liquidity during cash-in and cash-out transactions?', 'Cash-in reduces e-float and increases cash; cash-out does the reverse. Total liquidity stays the same, but its mix changes, so agents must rebalance.', 'supplementary', 'csit-613/e-business-in-ghana/b9f036284755', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('56769f06-ba27-50f2-aecc-f73ea72a2a69', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'What is the difference between the roles of the Bank of Ghana and GhIPSS?', 'The Bank of Ghana licenses, regulates and supervises payment providers; GhIPSS operates national payment infrastructure, including the mobile money interoperability switch.', 'supplementary', 'csit-613/e-business-in-ghana/ae29af373834', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('48039e77-9002-5c27-b249-053f8aaa6d27', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'How did interoperability change competition among mobile money providers?', 'It partly shared network effects across providers, shifting competition from network size towards price, reliability, user experience and value-added services.', 'supplementary', 'csit-613/e-business-in-ghana/6c0314a593cc', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('490bbfd3-dc38-5a93-9c46-fd47431049fd', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '3e91f010-bbde-5b9d-b1dd-95c27dafc62a', 'Which laws, besides Act 987, are relevant to Ghana''s mobile money ecosystem?', 'The Anti-Money Laundering Act, 2020 (Act 1044), the Data Protection Act, 2012 (Act 843) and the Cybersecurity Act, 2020 (Act 1038).', 'supplementary', 'csit-613/e-business-in-ghana/5c1f3985d56b', true)
