insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c676d452-3c51-5e96-8b07-a457099888c4', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '8100a598-2f8f-5db2-8051-40ff06fbec5e', 'What are the four core determinants in UTAUT?', 'Performance expectancy, effort expectancy, social influence and facilitating conditions, moderated by gender, age, experience and voluntariness.', 'supplementary', 'csit-613/e-business-in-ghana/f396223934f3', true)
