insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3e1ac44f-bdfb-5ef9-87c9-c08d1119e9aa', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '8100a598-2f8f-5db2-8051-40ff06fbec5e', 'Which three constructs did UTAUT2 add for consumer contexts?', 'Hedonic motivation, price value and habit.', 'supplementary', 'csit-613/e-business-in-ghana/d7ca5413bcf9', true)
