insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('800afe5f-63a5-5242-80fc-d683494304a1', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '8100a598-2f8f-5db2-8051-40ff06fbec5e', 'Why does cash on delivery remain popular in Ghanaian online retail?', 'It lowers the customer''s risk where trust between strangers is low, shifting the cost of failed deliveries, cash handling and delayed settlement to the seller.', 'supplementary', 'csit-613/e-business-in-ghana/4f9e7f0e2072', true)
