insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('185c9534-8e73-5853-9fde-84e7b05ce3d1', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '2bd375f1-8d76-50ba-aa3d-d271d89af5b5', '8100a598-2f8f-5db2-8051-40ff06fbec5e', 'Why can a discount for prepaying destroy value?', 'PSP fees replace cash-handling costs, so the savings from fewer failed deliveries may not cover the discount plus fees; the incentive must be modelled.', 'supplementary', 'csit-613/e-business-in-ghana/ae48c851c6a1', true)
