insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('e6a916e0-30da-5768-a630-929602b5b22a', '289f40af-c81b-540f-85f0-62d76d5630d3', 'fintech-regulation-strategy-and-global-developments', 'FinTech Regulation, Strategy and Global Developments', 'How digital finance is regulated, how digital businesses compete on experience and strategy, and what is changing internationally.', 8, true)
