insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4d173a57-4ffe-5c9c-836b-b8a068cfd9ff', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'csit-613/fintech-regulation-strategy-and-global-developments/fr01', 'mcq', 'understand', 'easy', 'Distinguish prudential from conduct regulation', 'Which rule is best classified as conduct regulation rather than prudential regulation?', null, null, '[{"id":"a","text":"A requirement that e-money funds are held in trust accounts separate from the issuer''s assets"},{"id":"b","text":"A requirement to disclose all fees to the customer before a transaction is confirmed"},{"id":"c","text":"A minimum capital requirement for a licensed payment provider"},{"id":"d","text":"A liquidity requirement for a deposit-taking institution"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4d173a57-4ffe-5c9c-836b-b8a068cfd9ff', '{"option":"b"}'::jsonb, 'Conduct regulation governs how customers are treated, including disclosure, pricing and complaints. Safeguarding of funds, capital and liquidity rules aim to keep the provider safe and solvent, so they are prudential.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2315f2b5-f07f-5006-b0d4-4efc333242d0', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'csit-613/fintech-regulation-strategy-and-global-developments/fr02', 'true_false', 'understand', 'medium', 'Understand the purpose of tiered KYC', 'Tiered KYC allows low-limit accounts to be opened with lighter identification, which is consistent with a risk-based approach to AML/CFT.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2315f2b5-f07f-5006-b0d4-4efc333242d0', '{"value":true}'::jsonb, 'A risk-based approach matches the strength of controls to the level of risk. Low balance and transaction limits reduce the potential for abuse, so lighter identification can be justified, and higher tiers require fuller verification. This protects inclusion for people without documents.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a59ab736-2a0b-59a3-9eba-b20774b123aa', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'csit-613/fintech-regulation-strategy-and-global-developments/fr03', 'matching', 'recall', 'easy', 'Match Ghanaian laws to the risk they address', 'Match each Ghanaian law to the main area it addresses.', null, null, '{"left":[{"id":"l1","text":"Payment Systems and Services Act, 2019 (Act 987)"},{"id":"l2","text":"Data Protection Act, 2012 (Act 843)"},{"id":"l3","text":"Anti-Money Laundering Act, 2020 (Act 1044)"},{"id":"l4","text":"Cybersecurity Act, 2020 (Act 1038)"}],"right":[{"id":"r3","text":"Preventing laundering of criminal proceeds"},{"id":"r4","text":"Cybersecurity and incident handling"},{"id":"r2","text":"Protection of personal data"},{"id":"r1","text":"Licensing and supervision of payment systems and e-money"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a59ab736-2a0b-59a3-9eba-b20774b123aa', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each law targets a different risk, and a FinTech product often falls under several at once. Mapping the applicable laws feature by feature is the first compliance task.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ea69d3eb-a8ea-57ff-b84d-90c1b54ef64e', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'csit-613/fintech-regulation-strategy-and-global-developments/fr04', 'scenario', 'apply', 'medium', 'Apply data protection principles to a credit scoring feature', 'Which data protection principle is most directly challenged by this plan?', 'Illustrative scenario: A lending app wants to improve its credit scores by collecting each applicant''s full phone contact list and message metadata, although it already has the applicant''s repayment history and wallet transaction data.', null, '[{"id":"a","text":"Retention, because the app must delete all data immediately"},{"id":"b","text":"Minimality and purpose limitation, because data beyond what is necessary for scoring is being collected"},{"id":"c","text":"Registration, because only banks may score borrowers"},{"id":"d","text":"Portability, because applicants must be allowed to use any app"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ea69d3eb-a8ea-57ff-b84d-90c1b54ef64e', '{"option":"b"}'::jsonb, 'Collecting contact lists and message metadata when necessary data already exists conflicts with collecting only what is needed for a specified purpose. The other options misstate the issue. Retention does not require immediate deletion, scoring is not limited to banks, and portability is not the concern here.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('92bf6b91-f195-56fc-beda-0b034d0b02a8', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'csit-613/fintech-regulation-strategy-and-global-developments/fr05', 'short_answer', 'recall', 'easy', 'Name the money laundering stage', 'In the three-stage model of money laundering, what is the stage called in which funds are moved through many transactions to obscure their origin?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('92bf6b91-f195-56fc-beda-0b034d0b02a8', '{"answers":["layering","Layering"]}'::jsonb, 'Placement puts cash into the system, layering obscures the trail through transactions, and integration returns the funds as apparently legitimate wealth. Fast, cheap transfers make mobile money attractive for layering, which is why monitoring matters.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ea5e5448-057e-5606-baf6-8a103dc1cf56', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'csit-613/fintech-regulation-strategy-and-global-developments/fr06', 'mcq', 'analyse', 'hard', 'Analyse a trade-off between strict KYC and inclusion', 'A regulator proposes requiring full documentary KYC for every wallet regardless of balance. What is the most likely consequence for financial inclusion?', null, null, '[{"id":"a","text":"No effect, because everyone holds the required documents"},{"id":"b","text":"Some people who lack documents may be pushed back to cash or informal channels, which are harder to monitor"},{"id":"c","text":"Wallet usage will automatically increase because trust improves"},{"id":"d","text":"Criminals will be unable to use any financial service"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ea5e5448-057e-5606-baf6-8a103dc1cf56', '{"option":"b"}'::jsonb, 'Uniform strict KYC raises the cost and difficulty of access for people without documents, and exclusion can push activity into less visible channels. Tiered KYC tries to avoid this by linking requirements to risk and limits. Strict rules reduce but do not eliminate crime.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6ce23659-1acb-5039-bf56-9e46a7fa5b47', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'csit-613/fintech-regulation-strategy-and-global-developments/fr07', 'true_false', 'evaluate', 'medium', 'Evaluate the legal status of a regulatory sandbox', 'Taking part in a regulatory sandbox exempts a firm from consumer protection and AML obligations for the duration of the test.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6ce23659-1acb-5039-bf56-9e46a7fa5b47', '{"value":false}'::jsonb, 'Sandboxes allow tailored conditions and closer supervision, but core protections for customers and basic AML duties remain. Participation also does not guarantee later authorisation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('574eaede-8085-540e-a6e8-eb860571c31a', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'csit-613/fintech-regulation-strategy-and-global-developments/cx01', 'mcq', 'understand', 'easy', 'Define a moment of truth', 'In customer journey mapping, what is a moment of truth?', null, null, '[{"id":"a","text":"A touchpoint that disproportionately shapes the customer''s overall judgement"},{"id":"b","text":"The date on which the customer''s contract ends"},{"id":"c","text":"The moment the firm publishes its annual report"},{"id":"d","text":"Any survey question that uses a 0-10 scale"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('574eaede-8085-540e-a6e8-eb860571c31a', '{"option":"a"}'::jsonb, 'Examples are the first transfer or the first failed transaction. These touchpoints carry more weight than routine interactions. The other options describe unrelated events or measurement tools.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8fc5dcb5-7685-5516-b673-2843b09c68c6', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'csit-613/fintech-regulation-strategy-and-global-developments/cx02', 'short_answer', 'recall', 'easy', 'Identify the abbreviation for a loyalty measure', 'Which customer experience metric, abbreviated to three letters, is based on the question "How likely are you to recommend us?" on a 0-10 scale?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8fc5dcb5-7685-5516-b673-2843b09c68c6', '{"answers":["NPS","Net Promoter Score"]}'::jsonb, 'Net Promoter Score is calculated as the percentage of promoters minus the percentage of detractors. It is a trend indicator and should be triangulated with behavioural data rather than treated as proof of loyalty.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c1221ebc-75ad-5f6e-ab5a-1b990ebd835a', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'csit-613/fintech-regulation-strategy-and-global-developments/cx03', 'scenario', 'apply', 'medium', 'Apply funnel analysis to find where users drop out', 'What are the completion rates at PIN set-up and first transfer, in that order?', 'Illustrative scenario: A wallet app records these stages for 1,000 new registrants: PIN set-up 900 entered and 630 completed; first transfer 630 entered and 315 completed.', null, '[{"id":"a","text":"63% and 31.5%"},{"id":"b","text":"70% and 50%"},{"id":"c","text":"70% and 31.5%"},{"id":"d","text":"63% and 50%"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c1221ebc-75ad-5f6e-ab5a-1b990ebd835a', '{"option":"b"}'::jsonb, 'PIN set-up is 630 divided by 900, which is 70%. First transfer is 315 divided by 630, which is 50%. The options 63% and 31.5% divide by the original 1,000 registrants, which measures overall progress, not stage completion.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1776622f-e0de-5575-b0cd-5c4559beabf4', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'csit-613/fintech-regulation-strategy-and-global-developments/cx04', 'true_false', 'evaluate', 'medium', 'Evaluate the role of friction in trust', 'Removing all friction from a payment flow is always beneficial, because it increases conversion and reduces customer regret.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1776622f-e0de-5575-b0cd-5c4559beabf4', '{"value":false}'::jsonb, 'Steps such as confirming the recipient''s name or warning on unusual transfers prevent costly errors and fraud and support trust. Conversion may rise when friction is removed, but fraud and regret can rise too.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('82700f11-f7f0-58c8-a257-24e811c118a1', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'csit-613/fintech-regulation-strategy-and-global-developments/cx05', 'mcq', 'analyse', 'medium', 'Analyse limitations of NPS', 'A provider''s NPS rises for three quarters while the number of active users falls. Which explanation should the analyst test first?', null, null, '[{"id":"a","text":"NPS and behaviour are the same thing, so one set of data must be wrong"},{"id":"b","text":"The survey sample may over-represent satisfied active users, while dissatisfied customers have left or do not respond"},{"id":"c","text":"Falling users always cause rising satisfaction"},{"id":"d","text":"NPS cannot be measured by SMS"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('82700f11-f7f0-58c8-a257-24e811c118a1', '{"option":"b"}'::jsonb, 'Survey scores can be biased by who responds, and customers who leave are no longer surveyed. NPS measures stated willingness to recommend, not usage, so the two can diverge. This is why metrics should be triangulated with behavioural data.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a3e57db7-b3ce-5ace-87e5-5749d2133f12', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'csit-613/fintech-regulation-strategy-and-global-developments/cx06', 'matching', 'understand', 'medium', 'Match market players with typical strengths', 'Match each type of provider with a typical strategic strength.', null, null, '{"left":[{"id":"l1","text":"Bank"},{"id":"l2","text":"MNO-linked e-money entity"},{"id":"l3","text":"FinTech"}],"right":[{"id":"r2","text":"Large customer base and agent distribution"},{"id":"r1","text":"Trusted brand and regulated lending capacity"},{"id":"r3","text":"Speed and a focused user experience"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a3e57db7-b3ce-5ace-87e5-5749d2133f12', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'These are tendencies, not rules. Each type also has weaknesses, such as legacy systems for banks, regulatory limits on credit for MNOs and small balance sheets for FinTechs, which explains why coopetition is common.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bc2b8dee-67bc-5423-9d93-347c794c97b3', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'csit-613/fintech-regulation-strategy-and-global-developments/cx07', 'scenario', 'evaluate', 'hard', 'Evaluate channel strategy for an inclusion target', 'What is the strongest criticism of this proposal?', 'Illustrative scenario: A provider wants to reach rural market traders, many of whom use basic phones and have limited mobile data. Management proposes an app-only launch because apps are cheaper to update.', null, '[{"id":"a","text":"Apps cannot process payments"},{"id":"b","text":"It excludes the target segment, so USSD and agent channels should be first-class"},{"id":"c","text":"Apps are illegal under payment regulation"},{"id":"d","text":"Rural traders never use mobile money"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bc2b8dee-67bc-5423-9d93-347c794c97b3', '{"option":"b"}'::jsonb, 'Designing for the least capable device and context is a core inclusion principle. An app-only launch is cheaper to update but would not reach customers with basic phones and limited data. The other statements are false.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ba16d1e4-14a2-5a53-8e3e-d3eeb6ba136c', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'csit-613/fintech-regulation-strategy-and-global-developments/in01', 'mcq', 'understand', 'easy', 'Explain open banking', 'Which description best fits open banking?', null, null, '[{"id":"a","text":"Banks publish all customer data on the internet"},{"id":"b","text":"With customer consent, banks give authorised third parties secure API access to account data or payment initiation"},{"id":"c","text":"A government takes over bank accounts"},{"id":"d","text":"Any software developer may access any account without authorisation"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ba16d1e4-14a2-5a53-8e3e-d3eeb6ba136c', '{"option":"b"}'::jsonb, 'Open banking relies on consent, authorised providers and secure APIs. It is not public disclosure or unrestricted access, and security and liability rules are an essential part of it.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b0941b4e-c7e4-5cbe-8e32-c1a003d2d10a', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'csit-613/fintech-regulation-strategy-and-global-developments/in02', 'matching', 'recall', 'easy', 'Match payment systems to countries', 'Match each system to its country or region.', null, null, '{"left":[{"id":"l1","text":"UPI"},{"id":"l2","text":"Pix"},{"id":"l3","text":"eNaira"},{"id":"l4","text":"PSD2"}],"right":[{"id":"r3","text":"Nigeria"},{"id":"r2","text":"Brazil"},{"id":"r1","text":"India"},{"id":"r4","text":"European Union"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b0941b4e-c7e4-5cbe-8e32-c1a003d2d10a', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'UPI is run by the National Payments Corporation of India, Pix by the Central Bank of Brazil, eNaira was launched by the Central Bank of Nigeria, and PSD2 is an EU directive on payment services.', null)
