insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e9b6973b-d4c1-58ee-8233-d4a747245559', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'csit-613/fintech-regulation-strategy-and-global-developments/in03', 'true_false', 'understand', 'medium', 'Distinguish a CBDC from cryptocurrency', 'A central bank digital currency is a digital liability of the central bank in the national currency, which distinguishes it from cryptocurrencies that have no issuer.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e9b6973b-d4c1-58ee-8233-d4a747245559', '{"value":true}'::jsonb, 'A CBDC is issued by the central bank and denominated in the national unit of account. Cryptocurrencies such as Bitcoin have no central issuer. A CBDC also differs from e-money, which is a liability of a licensed issuer backed by trust funds.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('fc00f97a-da76-5fb1-ad55-6041d53a0f60', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'csit-613/fintech-regulation-strategy-and-global-developments/in04', 'scenario', 'analyse', 'hard', 'Analyse why a CBDC may see limited uptake', 'Which explanation is most consistent with the lessons of eNaira?', 'Illustrative scenario: A country with widely used, interoperable mobile money launches a retail CBDC wallet. Six months later few people use it, and the central bank asks why.', null, '[{"id":"a","text":"People dislike all digital payments"},{"id":"b","text":"The CBDC may not offer advantages over existing mobile money and bank apps that people already trust"},{"id":"c","text":"CBDCs cannot be used on phones"},{"id":"d","text":"Central banks cannot issue currency"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('fc00f97a-da76-5fb1-ad55-6041d53a0f60', '{"option":"b"}'::jsonb, 'Where existing digital payments are convenient and widely accepted, a new instrument must offer a clear additional benefit such as offline use, privacy or lower cost. Without it, users have little reason to switch. The other options are factually wrong or unsupported.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bd02e51b-201f-5660-9c87-ff497689b5f6', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'csit-613/fintech-regulation-strategy-and-global-developments/in05', 'short_answer', 'recall', 'medium', 'Identify the regional payment system', 'What is the abbreviation of the initiative supported by Afreximbank and the AfCFTA Secretariat to settle intra-African payments in local currencies?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
