insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bd02e51b-201f-5660-9c87-ff497689b5f6', '{"answers":["PAPSS","Pan-African Payment and Settlement System"]}'::jsonb, 'PAPSS aims to reduce the need to route intra-African trade payments through foreign currencies and external banks. Its adoption has progressed in stages, so its current status should be checked.', null)
