insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2786bb32-b444-5ed7-a374-485139871ca8', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'csit-613/fintech-regulation-strategy-and-global-developments/in06', 'mcq', 'evaluate', 'hard', 'Evaluate policy transfer', 'A minister proposes copying India''s UPI exactly. What is the most sound first step?', null, null, '[{"id":"a","text":"Launch immediately because UPI is successful"},{"id":"b","text":"Test problem fit, prerequisites such as identity and interoperability, incentives and risks, then pilot"},{"id":"c","text":"Ban existing payment systems"},{"id":"d","text":"Wait ten years without analysis"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2786bb32-b444-5ed7-a374-485139871ca8', '{"option":"b"}'::jsonb, 'Models succeed under particular conditions, including digital identity, bank participation and policy choices. Transfer therefore requires checking problem fit, prerequisites, incentives and risks, and piloting before scaling.', null)
