insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4f70f387-ad46-5492-a4c0-4a3b0609275c', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'csit-613/fintech-regulation-strategy-and-global-developments/in07', 'true_false', 'analyse', 'medium', 'Assess claims about stablecoins in cross-border payments', 'Stablecoins have already resolved the regulatory, reserve backing and consumer protection questions in cross-border payments.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4f70f387-ad46-5492-a4c0-4a3b0609275c', '{"value":false}'::jsonb, 'Stablecoin use in cross-border transfers is emerging and contested. Questions about reserves, volatility, AML compliance, consumer protection and capital flow management remain open, so claims of cost savings should be treated cautiously.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('76211d78-3723-54d2-8670-1cd04e0452a4', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', null, 'csit-613/fintech-regulation-strategy-and-global-developments/mod01', 'essay', 'evaluate', 'hard', 'Evaluate how regulation, experience and international models should inform a FinTech strategy', 'Discuss how a Ghanaian FinTech should combine regulatory compliance, customer experience design and lessons from international developments to build a sustainable mobile payments and savings product for informal-sector traders.', null, null, null, 20, array['Introduction defining the product and the target segment', 'Regulatory perimeter, licensing route, tiered KYC, data protection and consumer protection', 'Customer journey and inclusive channel design (USSD, agents, app), with metrics used carefully', 'International lessons (instant payments, open banking, mobile money) and how to test their transferability', 'Strategic positioning against banks and MNOs, including partnership options', 'Conclusion with recommendations and risks']::text[], '[{"criterion":"Regulatory analysis","marks":5,"descriptor":"Identifies relevant authorities and laws, explains licensing or partnership choice, tiered KYC, data protection and consumer protection accurately and at the level of principle."},{"criterion":"Customer experience and inclusion","marks":5,"descriptor":"Uses a journey and channel analysis, addresses trust and USSD or agent inclusion, and treats metrics critically."},{"criterion":"International lessons and transfer","marks":4,"descriptor":"Selects relevant models, distinguishes established from emerging developments, and tests transferability to Ghana."},{"criterion":"Strategy and critical evaluation","marks":4,"descriptor":"Positions the firm against banks and MNOs, justifies partnerships, and weighs trade-offs and risks."},{"criterion":"Structure and academic integrity","marks":2,"descriptor":"Clear structure, accurate terminology, no invented statistics, and correct citation."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('76211d78-3723-54d2-8670-1cd04e0452a4', '{}'::jsonb, 'Examiners look for integration of the three lessons, accurate use of Ghanaian instruments without invented figures, critical use of metrics, and a justified, risk-aware recommendation.', 'A strong answer starts by defining the product, for example a wallet with savings and bill payment features for market traders, and noting that the segment has limited documents, feature phones and high sensitivity to fees. It maps the regulatory perimeter: e-money and payments fall under the Bank of Ghana and Act 987, personal data under the Data Protection Act, AML duties under Act 1044, and security incidents under the Cybersecurity Act. It decides whether to seek its own licence or partner with a licensed issuer, noting that partnership does not remove conduct and data duties, and proposes early engagement with the FinTech and Innovation Office or the sandbox for novel features such as credit scoring.

On experience, the answer maps a journey from registration to regular use, identifies moments of truth such as the first transfer, and designs USSD and agent channels as first-class, with an app for richer features. Friction such as recipient name confirmation is justified for trust. Metrics such as funnel completion, complaints and repeat use are triangulated with NPS or CSAT, with caveats about sample bias.

Internationally, the answer draws on instant payment systems like UPI and Pix for simple identifiers and QR acceptance, on open banking for consented data sharing for lending, and on mobile money in Kenya for agent-led distribution, while testing transferability by problem fit, prerequisites, incentives and risks. Strategically, the firm competes with banks and MNOs through a niche focus, partners for licences and distribution, and builds compliance in from the start. The conclusion recommends staged launch, measurable pilot goals and a risk register.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('02a99788-f828-54bb-abf9-df4b5606259d', '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', null, 'csit-613/fintech-regulation-strategy-and-global-developments/mod02', 'case_analysis', 'analyse', 'hard', 'Analyse a compliance and experience problem in a hypothetical wallet provider', 'Analyse the regulatory and customer experience problems in this case and recommend a prioritised set of improvements.', null, 'Illustrative scenario: "SikaLink", a hypothetical wallet start-up, offers small loans through its app. Reviews show customers complaining that repayment amounts were unclear and that collection messages are sent to people in their contact list. Meanwhile, new-user registration requires a full national ID document, and only 40% of those who start registration finish it (an invented figure for this exercise). Complaints are handled only by email, and customers on basic phones cannot use the app at all.', null, 15, array['Identify the data protection and consumer protection problems', 'Analyse the onboarding friction and the inclusion trade-off with tiered KYC', 'Analyse channel and complaints weaknesses', 'Prioritise recommendations with measures of success']::text[], '[{"criterion":"Regulatory and conduct diagnosis","marks":5,"descriptor":"Identifies unclear total cost of credit, contact list misuse and collection practices as data protection and consumer protection concerns, and links them to principles of purpose limitation, minimality and fair treatment."},{"criterion":"Onboarding and inclusion analysis","marks":4,"descriptor":"Explains how tiered KYC could reduce drop-off while maintaining risk-based AML controls."},{"criterion":"Channel and complaints analysis","marks":3,"descriptor":"Proposes USSD or agent access and accessible complaint channels with resolution times and escalation."},{"criterion":"Prioritisation and measures","marks":3,"descriptor":"Ranks actions by harm and feasibility and defines indicators such as completion rate, complaints per thousand transactions and resolution time."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('02a99788-f828-54bb-abf9-df4b5606259d', '{}'::jsonb, 'Examiners look for correct linking of observations to principles, balanced treatment of the KYC trade-off, and prioritised recommendations with measures.', 'The most urgent issue is conduct and data protection. Unclear repayment amounts breach the expectation of transparent pricing, so the app should show the total repayment and due date before acceptance. Messaging a borrower''s contacts uses personal data of third parties for a purpose they never consented to and is inconsistent with purpose limitation, minimality and fair collection, so it should stop immediately and collection should use proportionate methods with the borrower only.

Second, onboarding. Requiring a full national ID for every user creates friction that excludes people without documents. A tiered KYC design could allow a basic tier with low limits and no credit, then upgrade to higher tiers when the customer verifies an identity document. Monitoring continues at every tier, so risk remains controlled. The completion rate should be tracked by step, and the 40% figure treated as a baseline to improve, not as a benchmark.

Third, channels and complaints. Email-only complaints and an app-only service exclude basic phone users. SikaLink should add USSD access for core functions, an agent or call channel, ticket numbers, stated response times and an explanation of how to escalate to the regulator.

Recommendations are prioritised: stop contact-list collection and fix disclosure first, then introduce tiered KYC and complaints reform, then USSD. Success measures include completion rate, complaints per thousand transactions, time to resolve and repeat usage.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('85f72edb-c920-540c-b35b-7ddeae156ff1', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'What are four main reasons financial services are regulated?', 'Stability of providers, protection of consumers, market integrity (preventing financial crime) and competition or inclusion. Digital finance changes how each applies but does not remove them.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/972fa608a27d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b3e669c5-de16-5597-a7a8-f4f76f08e18e', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'How do prudential and conduct regulation differ?', 'Prudential regulation keeps providers safe and solvent (capital, liquidity, safeguarding of funds). Conduct regulation governs how customers are treated (disclosure, fair pricing, complaints, agent behaviour).', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/378c4846b8da', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e92b8a77-6613-55c3-92bf-5e208065c292', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'What is tiered KYC and why is it used?', 'Accounts with low limits need lighter identification, and higher limits require fuller verification. It applies a risk-based approach so that document requirements do not exclude people while risk stays controlled.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/0387444c6440', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('030e6c7c-5af3-5706-8141-8717928e1d8c', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'What are the three stages of money laundering?', 'Placement (getting cash into the system), layering (moving funds to obscure the origin) and integration (returning funds as apparently legitimate wealth).', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/8dc039ec31a5', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('43be2ff1-7c29-51d5-b33d-85683f8e4cde', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'What does a regulatory sandbox allow, and what does it not do?', 'It allows supervised, time-limited testing with real customers under tailored conditions. It does not waive core consumer protection or AML duties and does not guarantee later authorisation.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/4ea24075b8fd', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c999be46-1b75-54c6-a0ad-f5ca75d1359b', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'f3bb9bdd-dfea-5b58-817c-6aad8b901831', 'What is compliance by design?', 'Treating regulatory requirements as product requirements, by mapping regulators early, minimising data, building controls and limits into the flow, keeping evidence and governing third parties.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/995583e6c302', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('cd20d7ea-faca-5b93-b608-2f65c9039b0d', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'What is a customer journey map and what should it show?', 'A structured diagram of a persona''s stages and touchpoints with their actions, thoughts, emotions, pain points and moments of truth, plus the metrics and owners for fixing them.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/7cbab2bfee7a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3e400c5d-8e71-5bdd-9216-55c8e9da50be', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'Why should NPS be used carefully?', 'It captures stated willingness to recommend, hides reasons, is affected by sampling and cultural rating style, and may not predict behaviour. Triangulate it with usage, retention and interviews.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/3d58bb6d947e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2be79e6a-c5e7-5a92-b61a-02d5486c18ea', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'Why does USSD remain important for inclusive digital finance?', 'It works on every handset without data or an app, so it reaches customers with basic phones. Its limits are small screens, time-outs and weaker security than apps.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/884916fe51ea', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e49303da-d2cc-57f2-9c66-95d502b9ebe9', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'What does funnel analysis tell you, and what does it not?', 'It shows where users drop out and at what rate, but not why. Interviews and observation are needed to explain the causes.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/0b38576c8f6c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c6b3fae7-6d43-5f25-aed1-6a35f7424018', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'What is coopetition in digital finance?', 'Firms compete for customers while cooperating on infrastructure, such as shared switches, wallet-to-bank links and API partnerships.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/5ead9f615b31', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1a019264-b06d-58d6-b244-555655d475d5', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', 'bab4f766-c3d4-5871-9c48-5f249c165a9d', 'Why can some friction improve a financial service?', 'Steps such as recipient name confirmation or warnings on unusual transfers prevent errors and fraud, which supports trust even if conversion falls slightly.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/9dd466747e7e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bbd7811d-4d35-5964-82bf-7afe04d00de7', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'How does open banking work?', 'With customer consent, banks give authorised third parties secure API access to account data or payment initiation. It can be regulation-led (EU PSD2) or market-led.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/e2166502c975', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('44c03ef6-b2c4-5a7b-b4e6-63fb61a3129c', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'What features do UPI and Pix share?', 'Open, interoperable rails coordinated by a public authority, simple identifiers such as aliases or keys, QR payments and low-cost design, run by NPCI in India and the Central Bank of Brazil respectively.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/c10ff5821bec', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('00a0e2b5-8ba1-5f66-812a-a7b49e7743a5', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'How does a CBDC differ from e-money and from cryptocurrency?', 'A CBDC is a central bank liability in the national currency. E-money is a licensed issuer''s liability backed by trust funds, and cryptocurrencies have no issuer backing.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/0b238cf32b2f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b386c3ff-abbf-5ac2-97db-5e88e49cfdc7', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'What lesson does Nigeria''s eNaira offer other countries?', 'Reported modest uptake suggests a retail CBDC must offer clear advantages over existing mobile money and bank apps if people are to switch.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/9a66d99caf67', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c6000538-f0c6-5c62-9a00-264bb4ec69a4', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'What problem does PAPSS aim to address?', 'Intra-African payments often route through foreign currencies and external banks. PAPSS aims to settle them in local currencies; check its current adoption status.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/14ff34f1fe24', true)
