insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0aca5770-6af4-50a4-9277-c00c95b3bc50', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'What five questions test whether a foreign fintech model suits Ghana?', 'Problem fit, prerequisites such as identity and interoperability, incentives for participants, risks and safeguards, and evidence from a pilot before scaling.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/7330cc3a8c94', true)
