insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('65cd8599-bad1-54e1-9f99-d3581098b8f4', null, '289f40af-c81b-540f-85f0-62d76d5630d3', 'e6a916e0-30da-5768-a630-929602b5b22a', '64451f85-bb50-5329-b017-02f7e25ac019', 'What is embedded finance and what is its main risk?', 'Financial products offered inside non-financial platforms, often via licensed partners. A main risk is blurred accountability between the platform and the licensed provider.', 'supplementary', 'csit-613/fintech-regulation-strategy-and-global-developments/9b00711402e8', true)
