insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('4a740486-82fe-5753-a2f8-0ee2b8bf934a', '289f40af-c81b-540f-85f0-62d76d5630d3', 'practical-projects', 'Practical Projects', 'Designing e-business and payment solutions.', 9, true)
