insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9da66dd0-42ba-5241-80b6-e11fb970eb72', null, '289f40af-c81b-540f-85f0-62d76d5630d3', '4a740486-82fe-5753-a2f8-0ee2b8bf934a', '31d0a2bd-60aa-5875-936f-94845aacbc75', 'How is break-even order volume calculated?', 'Monthly fixed costs divided by contribution per order after acquisition costs, e.g. 6,500 ÷ 43.40 ≈ 150 orders.', 'supplementary', 'csit-613/practical-projects/f3862a7ac9a5', true)
