insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2a5e7884-7133-50a1-97cb-bf6741996911', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'csit-617/it-professionalism/q01', 'mcq', 'recall', 'easy', 'Identify the characteristics traditionally used to define a profession', 'Which of the following is NOT usually listed as a defining characteristic of a profession?', null, null, '[{"id":"a","text":"A specialised, theory-based body of knowledge"},{"id":"b","text":"A code of ethics and a professional association"},{"id":"c","text":"Guaranteed high salaries for all members"},{"id":"d","text":"A public-service orientation"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2a5e7884-7133-50a1-97cb-bf6741996911', '{"option":"c"}'::jsonb, 'Accounts of professions stress specialised knowledge, controlled entry, a professional body, a code of ethics, autonomy and a public-service orientation. High pay may be common, but it is a consequence of professional status rather than a defining characteristic, and many professionals are not highly paid.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ebf807b0-3f1b-5d89-a7ea-3372481d8299', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'csit-617/it-professionalism/q02', 'true_false', 'understand', 'easy', 'Distinguish accountability from causal responsibility', 'A chief information officer can be accountable for a data breach even if they did not personally cause it.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ebf807b0-3f1b-5d89-a7ea-3372481d8299', '{"value":true}'::jsonb, 'Accountability attaches to roles. The CIO must explain and justify what happened to the board or regulator because of their position, even if causal responsibility lies with a contractor or a junior engineer. This is why accountability and causal responsibility must be kept distinct.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('eaa67397-bec0-5f4b-baf7-9c73d4cdd8bc', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'csit-617/it-professionalism/q03', 'short_answer', 'recall', 'medium', 'Name Nissenbaum''s barrier concerning many contributors', 'Which barrier to accountability, identified by Nissenbaum, describes the difficulty of assigning responsibility when many people contribute to a system?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('eaa67397-bec0-5f4b-baf7-9c73d4cdd8bc', '{"answers":["problem of many hands","many hands","the problem of many hands"]}'::jsonb, 'The problem of many hands arises because systems are built and operated by large teams, vendors and libraries, so each contributor can point to others. The other barriers are bugs, the computer as scapegoat and ownership without liability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ef64b487-ad15-5914-8495-8b7c10320cbf', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'csit-617/it-professionalism/q04', 'matching', 'understand', 'medium', 'Match responsibility concepts to their defining questions', 'Match each concept to the question it answers.', null, null, '{"left":[{"id":"l1","text":"Role responsibility"},{"id":"l2","text":"Causal responsibility"},{"id":"l3","text":"Moral responsibility"},{"id":"l4","text":"Accountability"},{"id":"l5","text":"Liability"}],"right":[{"id":"r3","text":"Did the person act knowingly and freely, without adequate excuse?"},{"id":"r1","text":"What duties come with this position?"},{"id":"r5","text":"Who must compensate or be penalised under law?"},{"id":"r2","text":"Did this person''s action contribute to the outcome?"},{"id":"r4","text":"Who must explain and justify what happened to a forum?"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ef64b487-ad15-5914-8495-8b7c10320cbf', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Separating these five concepts is essential in case analysis. They frequently come apart, for example a person may be causally involved but not blameworthy, or a company may be legally liable without any individual being morally at fault.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a089cc9b-47b1-508a-b8c0-5b88bb00f213', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'csit-617/it-professionalism/q05', 'scenario', 'apply', 'medium', 'Apply the concept of moral responsibility to a software failure', 'Which assessment of moral responsibility is most defensible?', 'Illustrative scenario. At a fictional Accra fintech, a junior developer writes interest-calculation code that is reviewed and approved by two seniors and passes all tests in the agreed test plan. A rare rounding defect later overcharges some customers. Investigation shows the test plan was cut by the product director to meet a launch date, despite written objections from the QA lead.', null, '[{"id":"a","text":"The junior developer bears all the blame because they wrote the faulty line of code"},{"id":"b","text":"Nobody is to blame because software bugs are unavoidable"},{"id":"c","text":"Significant moral responsibility lies with the product director who knowingly cut testing despite objections, while the developer is causally but not primarily morally responsible"},{"id":"d","text":"Only the customers are responsible because they accepted the terms and conditions"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a089cc9b-47b1-508a-b8c0-5b88bb00f213', '{"option":"c"}'::jsonb, 'Moral responsibility requires knowledge and free choice. The director knowingly overrode a warning, so a large share of blame shifts to them. The developer is causally involved but followed reasonable procedures. Treating bugs as nobody''s fault is Nissenbaum''s "bugs" barrier, and blaming customers ignores the organisation''s duties.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('483318aa-b1a2-5f3f-863d-6ce6b6f46144', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'csit-617/it-professionalism/q06', 'mcq', 'analyse', 'hard', 'Analyse the Therac-25 case using barriers to accountability', 'In the Therac-25 accidents, the manufacturer initially doubted that its machine could be responsible for patient injuries. Which barrier to accountability does this most directly illustrate?', null, null, '[{"id":"a","text":"Ownership without liability"},{"id":"b","text":"Treating bugs as improbable natural hazards rather than investigating them as consequences of design choices"},{"id":"c","text":"The problem of many hands"},{"id":"d","text":"The digital divide"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('483318aa-b1a2-5f3f-863d-6ce6b6f46144', '{"option":"b"}'::jsonb, 'Doubting that the software could be at fault reflects the tendency to treat bugs as improbable or unavoidable rather than as outcomes of choices about design, testing and safety interlocks. Many hands also played a role, but the specific behaviour described is about dismissing software faults. The digital divide is unrelated.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8e4218b9-ed36-5e66-87f1-6d44a409e274', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'csit-617/it-professionalism/q07', 'true_false', 'evaluate', 'medium', 'Evaluate the claim that IT is not a profession because licensing is absent', 'The absence of compulsory licensing for most IT roles in Ghana means that IT practitioners cannot meaningfully act as professionals.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8e4218b9-ed36-5e66-87f1-6d44a409e274', '{"value":false}'::jsonb, 'Licensing is only one characteristic of a profession. IT has specialised knowledge, professional bodies and codes of ethics, and individuals can adopt professional standards voluntarily. Some specialisms, such as cybersecurity under Act 1038, are moving towards accreditation. IT is better described as a partial or emerging profession.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('362f6e00-7a60-50cf-9b5a-c6ad9408d944', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'csit-617/it-professionalism/q08', 'mcq', 'recall', 'easy', 'Recall the structure of the ACM Code of Ethics (2018)', 'Which of the following correctly lists the four parts of the ACM Code of Ethics and Professional Conduct (2018)?', null, null, '[{"id":"a","text":"General ethical principles; professional responsibilities; professional leadership principles; compliance with the code"},{"id":"b","text":"Public interest; duty to employer; duty to the profession; duty to colleagues"},{"id":"c","text":"Safety; honesty; competence; environment"},{"id":"d","text":"Privacy; security; intellectual property; accessibility"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('362f6e00-7a60-50cf-9b5a-c6ad9408d944', '{"option":"a"}'::jsonb, 'The ACM 2018 code has four parts. The second option resembles the BCS Code of Conduct''s organising headings, the third mixes IEEE themes, and the fourth lists topics rather than the code''s structure.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a8811512-fd36-561f-b887-94ff96b74e23', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'csit-617/it-professionalism/q09', 'true_false', 'understand', 'easy', 'Understand the legal status of professional codes', 'Breaching the ACM or IEEE code of ethics is, in itself, a criminal offence.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a8811512-fd36-561f-b887-94ff96b74e23', '{"value":false}'::jsonb, 'Professional codes are commitments made by members of voluntary bodies. A breach may lead to disciplinary action or loss of membership, but it is not itself a crime. Many code duties do, however, overlap with legal obligations such as data protection.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('172c8b50-b6d7-57e5-8f45-043a9544a0d6', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'csit-617/it-professionalism/q10', 'short_answer', 'recall', 'medium', 'Define the term for ongoing structured learning', 'What is the term (or its abbreviation) for the planned, ongoing learning that maintains a professional''s competence throughout their career?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('172c8b50-b6d7-57e5-8f45-043a9544a0d6', '{"answers":["continuing professional development","CPD","continuous professional development"]}'::jsonb, 'CPD keeps competence current in a fast-changing field. A useful cycle is reflect, plan, act and evaluate, with records kept as evidence.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ad9039f1-2920-545b-939e-bd5a21fba602', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'csit-617/it-professionalism/q11', 'scenario', 'apply', 'medium', 'Apply competence principles to a request beyond one''s expertise', 'Which response is most consistent with the competence provisions of the ACM and IEEE codes?', 'Illustrative scenario. Kojo, a web developer at a fictional Tamale logistics firm, is asked to implement end-to-end encryption for driver location data within a week. He has never implemented cryptographic protocols and suspects a home-made solution could be insecure.', null, '[{"id":"a","text":"Accept silently and write his own encryption algorithm to save time"},{"id":"b","text":"Refuse and take no further part in the project"},{"id":"c","text":"Disclose his lack of experience, recommend using a well-reviewed library under supervision of someone qualified, and propose a realistic timeline"},{"id":"d","text":"Ask a friend to do it informally without telling his manager"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ad9039f1-2920-545b-939e-bd5a21fba602', '{"option":"c"}'::jsonb, 'Both codes permit unfamiliar work only after full disclosure of limitations and with appropriate support, and both require honest estimates. Silent acceptance breaches honesty and competence; outright refusal is unhelpful; informal outsourcing conceals the problem and may breach confidentiality.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('63e2435a-d634-5bff-af51-ce30465ac2d6', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'csit-617/it-professionalism/q12', 'matching', 'understand', 'medium', 'Associate distinctive commitments with the correct code', 'Match each commitment to the code or framework in which it is most distinctively emphasised.', null, null, '{"left":[{"id":"l1","text":"A dedicated section on the obligations of leaders"},{"id":"l2","text":"Explicit reference to sustainable development and the environment"},{"id":"l3","text":"Organised around public interest, competence and integrity, duty to relevant authority, and duty to the profession"},{"id":"l4","text":"New technologies creating policy vacuums that rules do not yet address"}],"right":[{"id":"r4","text":"James Moor''s account of computer ethics"},{"id":"r1","text":"ACM Code (2018)"},{"id":"r2","text":"IEEE Code of Ethics"},{"id":"r3","text":"BCS Code of Conduct"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('63e2435a-d634-5bff-af51-ce30465ac2d6', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'The ACM code includes a professional leadership section; the IEEE code explicitly mentions sustainable development; the BCS code uses four duty headings; and Moor''s 1985 article introduced the idea of policy vacuums, which explains why codes can never anticipate every technology.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e08cb583-afa4-52f2-9ae7-6fdf43045c05', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'csit-617/it-professionalism/q13', 'mcq', 'analyse', 'hard', 'Analyse the ethical failure in the Volkswagen emissions case', 'Which analysis best captures why the Volkswagen defeat-device case is significant for professional codes of ethics?', null, null, '[{"id":"a","text":"It shows that the engineers lacked technical competence"},{"id":"b","text":"It shows that technical competence without integrity and commitment to public welfare can produce serious harm, and that following instructions does not discharge professional duties"},{"id":"c","text":"It shows that codes of ethics apply only to managers, not engineers"},{"id":"d","text":"It shows that emissions testing software is outside the scope of computing ethics"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e08cb583-afa4-52f2-9ae7-6fdf43045c05', '{"option":"b"}'::jsonb, 'The software worked exactly as designed; the failure was one of honesty and public welfare. An engineer was prosecuted, demonstrating that individual practitioners remain responsible. Codes apply to all members, and embedded software is squarely within computing ethics.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bba37355-fc12-5fc3-890a-d0a98033106d', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'csit-617/it-professionalism/q14', 'true_false', 'evaluate', 'medium', 'Evaluate the role of disclosure in competence obligations', 'Under the IEEE code, a member may undertake a task for which they are not fully qualified provided they give full disclosure of their limitations.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bba37355-fc12-5fc3-890a-d0a98033106d', '{"value":true}'::jsonb, 'The IEEE code asks members to undertake technological tasks only if qualified by training or experience, or after full disclosure of pertinent limitations. What it prohibits is concealment. Disclosure allows the employer to arrange support or alternatives.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9d6fc631-56e5-5e84-8cd7-7fa93cb0591e', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', null, 'csit-617/it-professionalism/q15', 'case_analysis', 'evaluate', 'hard', 'Evaluate professional responsibility and code obligations in a realistic Ghanaian IT failure', 'Analyse the case below. Allocate responsibility, accountability and possible liability, identify the relevant ACM and IEEE principles, and recommend actions for the individuals and the organisation.', null, 'Illustrative scenario. HealthLink Ghana, a fictional company, supplies an appointment and laboratory-results system to private clinics in Accra and Kumasi. To win a new contract, the sales director promised delivery of a results-notification feature in four weeks. The development lead, Esi, warned in writing that the integration had not been security-tested. The director instructed the team to release anyway. A contractor configured the cloud storage bucket, which was left publicly readable. For two months, laboratory results, including HIV test results, were accessible to anyone with the link pattern. A journalist discovered the exposure. Staff told clinics that "the system had a glitch".', null, 25, array['Brief statement of the ethical and professional issues', 'Allocation of role, causal and moral responsibility to each party', 'Accountability and possible liability (educational, not legal advice)', 'Relevant ACM and IEEE principles, paraphrased and applied', 'Nissenbaum''s barriers evident in the case', 'Recommendations for individuals and the organisation, with justification']::text[], '[{"criterion":"Responsibility analysis","marks":7,"descriptor":"Distinguishes role, causal and moral responsibility for the director, Esi, the contractor and leadership, with reasons grounded in knowledge and choice"},{"criterion":"Accountability and liability","marks":4,"descriptor":"Identifies who must answer to clinics, patients and regulators, and notes potential legal exposure without giving legal advice"},{"criterion":"Application of codes","marks":6,"descriptor":"Accurately paraphrases and applies relevant ACM and IEEE principles such as avoiding harm, privacy, confidentiality, security, honesty and competence"},{"criterion":"Barriers to accountability","marks":3,"descriptor":"Recognises the computer-as-scapegoat framing (\"glitch\") and the many-hands problem"},{"criterion":"Recommendations","marks":5,"descriptor":"Proposes concrete, justified actions such as disclosure to affected patients, root-cause review, release governance and CPD"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9d6fc631-56e5-5e84-8cd7-7fa93cb0591e', '{}'::jsonb, 'Examiners look for precise use of responsibility concepts, accurate paraphrase of the codes, recognition of organisational causes and practical, justified recommendations.', 'A strong answer begins by naming the core issues: exposure of highly sensitive health data, a release decision that overrode a security warning, and a misleading explanation to clients. On responsibility, the sales director made a promise without technical consultation and knowingly overrode Esi''s written warning, so carries substantial moral responsibility. Esi discharged an important part of her duty by warning in writing, though candidates may discuss whether she should have escalated further. The contractor is causally responsible for the misconfiguration and morally responsible to the extent that a competent practitioner would know to restrict bucket access. Senior leadership is accountable to clinics, patients and the Data Protection Commission because accountability attaches to their roles. Liability may arise under contract and data protection law, but this is educational analysis, not legal advice.
Applying the codes, the ACM principles to avoid harm, respect privacy, honour confidentiality, be honest and build robustly secure systems were all breached, as was the IEEE commitment to public welfare, privacy and prompt disclosure of dangers. Describing the incident as a "glitch" is a clear instance of the computer as scapegoat, and the chain from sales to contractor illustrates many hands.
Recommendations should include honest notification of clinics and affected patients, reporting as required by law, an independent root-cause review that examines management decisions and not only the contractor, a release gate requiring security sign-off, contractual standards for contractors, and CPD in cloud security. The best answers justify each recommendation by reference to the principles and show awareness of trade-offs, such as reputational cost against the duty of honesty.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8496a41f-a7da-5711-87a3-73fe3655696c', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'Why is IT often described as a "partial" or "emerging" profession?', 'It has specialised knowledge, professional bodies and codes of ethics, but entry is largely uncontrolled, membership is voluntary and many practitioners are employees whose judgement can be overridden.', 'supplementary', 'csit-617/it-professionalism/a3a2623bd0e9', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4b5a0db6-bc04-57bb-9d57-2bce36b8360e', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'How does accountability differ from moral responsibility?', 'Moral responsibility concerns whether a person is blameworthy because they acted knowingly and freely; accountability is the obligation to explain and justify conduct to a forum, and it attaches to roles even without personal fault.', 'supplementary', 'csit-617/it-professionalism/4bf018b0bc20', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('70d1e07f-7204-51b4-b1e8-6744c6284524', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'What is the difference between liability and moral responsibility?', 'Liability is a legal obligation to compensate or be penalised, which can exist without fault (strict liability); moral responsibility can exist even where the law imposes no liability.', 'supplementary', 'csit-617/it-professionalism/fa132b346c26', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('eee8737e-0e75-5558-b87e-31fdfe1a7a5a', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'Name Nissenbaum''s four barriers to accountability in computerised society.', 'The problem of many hands, bugs treated as unavoidable, the computer as scapegoat, and ownership without liability.', 'supplementary', 'csit-617/it-professionalism/27ba363e6b68', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0f5e951d-30ab-51ec-8a39-c4714d6226e8', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'What is forward-looking responsibility and why does professional ethics emphasise it?', 'It is responsibility for ensuring good outcomes and preventing foreseeable harm in future, rather than allocating blame afterwards; professionals are trusted precisely to take this kind of ownership.', 'supplementary', 'csit-617/it-professionalism/a6dd37aaf74b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6ff45126-ef85-50c4-9398-136737cb6969', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', 'a262c8aa-1226-5bfe-a151-d5e42a5255d5', 'What professional lesson does the UK Post Office Horizon case teach?', 'Presuming that a computer system is correct can cause grave injustice; professionals who understand a system''s weaknesses must ensure that knowledge reaches decision-makers such as courts.', 'supplementary', 'csit-617/it-professionalism/0ebcf3f24532', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d0a2a279-63e2-5445-9260-f45f9bce3f54', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'What are five functions of a professional code of ethics?', 'Guidance for judgement, support against improper pressure, education of members, a basis for discipline, and a signal of trustworthiness to the public.', 'supplementary', 'csit-617/it-professionalism/816ae301da22', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('85766d69-39d1-52ed-837d-fb54e14b7cc0', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'What are the four parts of the ACM Code of Ethics (2018)?', 'General ethical principles, professional responsibilities, professional leadership principles, and compliance with the code.', 'supplementary', 'csit-617/it-professionalism/a1f37073452d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('747331f6-b969-5409-96f3-8af3a84fa7fa', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'How do the ACM and IEEE codes resolve conflicts between employer interests and public welfare?', 'Both treat public welfare (safety, health and well-being) as paramount, so it overrides loyalty to employers or clients when they genuinely conflict.', 'supplementary', 'csit-617/it-professionalism/eb5717cdb7d7', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a264298f-0208-506c-91fa-801d39f2f6f2', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'Why is competence an ethical and not merely a technical obligation?', 'Clients and the public rely on professionals because they cannot judge the work themselves; accepting work beyond one''s competence without disclosure exploits that trust and risks harm.', 'supplementary', 'csit-617/it-professionalism/fb3979865cd3', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c083c5cc-7761-599a-8cba-3fcbf9816ec6', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'What are the five dimensions of professional competence?', 'Knowledge, skill, judgement, awareness of one''s limits, and currency (keeping up to date).', 'supplementary', 'csit-617/it-professionalism/6eaab31984b4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('de46c14b-2cb3-54c6-b1c8-9658fa6e285d', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'What does Moor''s idea of a "policy vacuum" imply about codes of ethics?', 'New technologies create situations no existing rule addresses, so codes can never be complete and must be supplemented by ethical reasoning and judgement.', 'supplementary', 'csit-617/it-professionalism/a05ffa892b8c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('de515985-277c-5b46-ab01-ce2ff75dd528', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '5d4c0926-b05f-53e3-9de4-3501fc9f4a7c', '8ef871bc-40d1-5fa6-b484-68bda8d38b26', 'What are the four stages of a CPD cycle?', 'Reflect on gaps, plan learning activities, act by completing them, and evaluate their impact on practice before repeating.', 'supplementary', 'csit-617/it-professionalism/955c8dbf7819', true)
