insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('d0c8cbcc-0fb3-5801-b047-41fe60f8e585', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'ethical-foundations', 'Ethical Foundations', 'The theories and methods used to reason about right and wrong.', 2, true)
