  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4a0a9a2e-f723-54de-99d6-3a0cb0159735', '{"option":"b"}'::jsonb, 'The first level concerns material access, the second concerns skills and use, and the third concerns outcomes and benefits. Handset prices are one cause of first-level divides rather than a level in themselves.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2311afd3-2529-5a04-8a1e-32714ebdf85f', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'csit-617/technology-and-society/q02', 'true_false', 'understand', 'easy', 'Recognise that access alone does not ensure inclusion', 'Once everyone in a community owns a smartphone, the digital divide in that community has been eliminated.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
