insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2311afd3-2529-5a04-8a1e-32714ebdf85f', '{"value":false}'::jsonb, 'Ownership addresses only material access. People may still differ greatly in skills, confidence, language, affordability of data and the benefits they obtain, so second- and third-level divides remain.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0f9af1a0-25a6-55ad-a324-f2f7a1869bfc', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'csit-617/technology-and-society/q03', 'matching', 'understand', 'medium', 'Match WCAG principles to examples of good practice', 'Match each WCAG principle to an example of good practice.', null, null, '{"left":[{"id":"l1","text":"Perceivable"},{"id":"l2","text":"Operable"},{"id":"l3","text":"Understandable"},{"id":"l4","text":"Robust"}],"right":[{"id":"r2","text":"Ensuring every function can be used with a keyboard alone"},{"id":"r1","text":"Providing captions for training videos"},{"id":"r3","text":"Writing clear error messages that explain how to fix a form entry"},{"id":"r4","text":"Using correctly labelled form fields that screen readers can interpret"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
