insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0f9af1a0-25a6-55ad-a324-f2f7a1869bfc', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'POUR organises WCAG success criteria. Captions make audio perceivable, keyboard access makes the interface operable, clear errors make it understandable, and semantic, labelled markup makes it robust for assistive technologies.', null)
