insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3526ff53-7803-5baa-b1de-e9d5d501c808', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'csit-617/technology-and-society/q04', 'short_answer', 'recall', 'medium', 'Recall the main international web accessibility standard', 'What is the abbreviation of the W3C standard most widely used for web accessibility?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
