insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3526ff53-7803-5baa-b1de-e9d5d501c808', '{"answers":["WCAG","Web Content Accessibility Guidelines"]}'::jsonb, 'The Web Content Accessibility Guidelines, with version 2.2 published in 2023, define success criteria at levels A, AA and AAA. Level AA is a common practical target.', null)
