insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('30cb43aa-0e85-511b-9b62-23d64ebe2d5f', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'csit-617/technology-and-society/q05', 'scenario', 'apply', 'medium', 'Apply inclusive design to a digital-by-default proposal', 'Which recommendation best reflects inclusive design principles?', 'Illustrative scenario. A fictional rural bank in the Bono Region plans to replace all counter services with a smartphone app that works only in English and requires a 4G connection.', null, '[{"id":"a","text":"Proceed, because digital services are available 24 hours a day and therefore more inclusive"},{"id":"b","text":"Cancel all digital plans to protect traditional customers"},{"id":"c","text":"Offer the app alongside USSD access, local-language support, low-bandwidth design, accessibility testing and assisted channels through agents or branches"},{"id":"d","text":"Proceed, but charge a fee for counter services so that customers are encouraged to switch"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('30cb43aa-0e85-511b-9b62-23d64ebe2d5f', '{"option":"c"}'::jsonb, 'Inclusion requires multiple channels and design for low bandwidth, local languages and disability, as mobile money''s USSD and agent model shows. Proceeding unchanged excludes many customers, cancelling ignores benefits, and fees penalise those least able to switch.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1ff08b7f-566b-5cfe-a8bc-3f9eba5f9d6d', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'csit-617/technology-and-society/q06', 'mcq', 'analyse', 'hard', 'Analyse data invisibility as a form of exclusion', 'An informal-sector trader in Kumasi who conducts most business in cash is refused credit by a lender that scores applicants only on digital transaction histories. Which concept best explains this outcome?', null, null, '[{"id":"a","text":"The first-level divide only"},{"id":"b","text":"Data invisibility, in which people who generate little digital data are disadvantaged by data-driven systems"},{"id":"c","text":"Universal design"},{"id":"d","text":"Freedom of expression"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1ff08b7f-566b-5cfe-a8bc-3f9eba5f9d6d', '{"option":"b"}'::jsonb, 'The trader may have a phone, so this is not only a first-level issue. The problem is that data-driven systems treat a lack of digital records as a lack of creditworthiness, reproducing existing disadvantage. Universal design and expression are not the core issue here.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2171e57b-c49c-543f-9caa-d1297eecff56', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'csit-617/technology-and-society/q07', 'true_false', 'evaluate', 'medium', 'Evaluate the justice-based argument for inclusion', 'From a Rawlsian perspective, digital innovations should be arranged so that they benefit the least advantaged members of society.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2171e57b-c49c-543f-9caa-d1297eecff56', '{"value":true}'::jsonb, 'Rawls''s difference principle permits inequalities only if they benefit the least advantaged. Applied to technology, it supports designing digital services and policies with the needs of excluded groups at the centre, treating inclusion as a matter of justice rather than charity.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d48869e9-0b92-5e0b-a25f-b47b2ea85a9b', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'csit-617/technology-and-society/q08', 'mcq', 'recall', 'easy', 'Recall the principle affirmed by the 2012 UN Human Rights Council resolution', 'What principle did the UN Human Rights Council affirm in its 2012 resolution on the internet and human rights?', null, null, '[{"id":"a","text":"Internet access must be provided free of charge by every government"},{"id":"b","text":"The same rights that people have offline must also be protected online"},{"id":"c","text":"Private companies are not bound by any human rights expectations"},{"id":"d","text":"Governments may restrict online speech without justification"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d48869e9-0b92-5e0b-a25f-b47b2ea85a9b', '{"option":"b"}'::jsonb, 'The resolution affirmed that rights, in particular freedom of expression, apply online as offline. It did not mandate free access, and it did not endorse unjustified restrictions.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3d0bb1ed-adda-5bea-9624-6274112724a2', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'csit-617/technology-and-society/q09', 'matching', 'understand', 'medium', 'Match the five proportionality questions to their concerns', 'Match each element of the workplace monitoring proportionality framework to the question it asks.', null, null, '{"left":[{"id":"l1","text":"Legitimate aim"},{"id":"l2","text":"Necessity"},{"id":"l3","text":"Proportionality"},{"id":"l4","text":"Transparency"},{"id":"l5","text":"Safeguards"}],"right":[{"id":"r3","text":"Is the intrusion reasonable relative to the benefit?"},{"id":"r2","text":"Could the aim be achieved by less intrusive means?"},{"id":"r5","text":"Are there access limits, retention periods, human review and appeal?"},{"id":"r4","text":"Have workers been clearly told what is monitored and why?"},{"id":"r1","text":"What specific problem is the monitoring meant to address?"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3d0bb1ed-adda-5bea-9624-6274112724a2', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'The framework balances employer interests in security and performance against employee interests in privacy and dignity. Skipping any element, especially necessity, is a common weakness in monitoring policies.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('15e8592e-9809-51d3-94b7-ae2d16e41030', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'csit-617/technology-and-society/q10', 'true_false', 'understand', 'medium', 'Understand why employee consent is a weak basis for monitoring', 'Because employees sign their employment contracts voluntarily, their consent always provides a sufficient ethical justification for any workplace monitoring.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('15e8592e-9809-51d3-94b7-ae2d16e41030', '{"value":false}'::jsonb, 'The power asymmetry of employment means consent may not be freely given, since refusing may risk one''s job. Monitoring must therefore be justified by a legitimate aim and be necessary, proportionate and transparent, with safeguards.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e58646e6-c04f-5913-960d-a104029887fc', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'csit-617/technology-and-society/q11', 'scenario', 'apply', 'medium', 'Apply proportionality to a remote-work monitoring proposal', 'Applying the proportionality framework, what is the most defensible assessment?', 'Illustrative scenario. A fictional Accra marketing agency wants to require all remote staff to keep webcams switched on throughout the working day so that managers can confirm they are working.', null, '[{"id":"a","text":"Acceptable, because productivity is a legitimate aim and the employer owns the laptops"},{"id":"b","text":"Disproportionate, because continuous video monitoring is highly intrusive and less intrusive means, such as output-based goals and regular check-ins, can achieve the aim"},{"id":"c","text":"Acceptable, provided the footage is stored indefinitely"},{"id":"d","text":"Irrelevant to ethics, because remote work happens at home"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e58646e6-c04f-5913-960d-a104029887fc', '{"option":"b"}'::jsonb, 'Productivity is a legitimate aim, but continuous webcam monitoring intrudes into private homes and fails the necessity test when less intrusive options exist. Indefinite storage worsens the intrusion, and the home setting increases rather than removes ethical concern.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('66f6342b-e8d1-522e-a28d-466b2de95532', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'csit-617/technology-and-society/q12', 'short_answer', 'recall', 'medium', 'Name the term for gradual use of data beyond its original purpose', 'What term describes the gradual use of data or technology for purposes beyond those for which it was originally introduced?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('66f6342b-e8d1-522e-a28d-466b2de95532', '{"answers":["function creep","mission creep"]}'::jsonb, 'Function creep is a central risk in monitoring. Vehicle GPS introduced for safety may later be used to discipline workers for breaks. Clear purpose limits and safeguards are needed to prevent it.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('79cddc48-62a1-51ad-96fd-c362b51758ba', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'csit-617/technology-and-society/q13', 'mcq', 'analyse', 'hard', 'Analyse the significance of the Amsterdam ride-hailing data cases', 'What is the main significance of the 2021 Amsterdam court cases brought by ride-hailing drivers under the GDPR?', null, null, '[{"id":"a","text":"They established that platform workers are always employees"},{"id":"b","text":"They showed that data protection rights, such as access to personal data and information about automated decisions, can function as tools for workers to challenge algorithmic management"},{"id":"c","text":"They banned the use of algorithms by platforms in Europe"},{"id":"d","text":"They concerned copyright in driver-generated maps"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('79cddc48-62a1-51ad-96fd-c362b51758ba', '{"option":"b"}'::jsonb, 'The cases used GDPR rights of access and protections around automated decision-making to obtain information about how drivers were assessed. They did not settle employment status, ban algorithms or concern copyright.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('29662a1f-9c40-5ec2-a852-e509243c6ae9', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'csit-617/technology-and-society/q14', 'mcq', 'evaluate', 'hard', 'Evaluate a nationwide internet shutdown using proportionality', 'A government orders a nationwide mobile internet shutdown for a week to stop the spread of rumours during an election. Which evaluation is most consistent with human rights reasoning?', null, null, '[{"id":"a","text":"Justified, because preventing misinformation is always a legitimate aim"},{"id":"b","text":"Likely disproportionate, because it affects entire populations, disrupts commerce, mobile money, emergency services and journalism, and less intrusive measures are available"},{"id":"c","text":"Justified, because the internet is not a human right"},{"id":"d","text":"Irrelevant, because only private companies can violate digital rights"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('29662a1f-9c40-5ec2-a852-e509243c6ae9', '{"option":"b"}'::jsonb, 'Even if the aim is legitimate, a blanket shutdown fails necessity and proportionality because of its wide collateral harm and the availability of targeted alternatives. Whether access is a free-standing right does not matter, since shutdowns impair recognised rights such as expression. States are primary duty-bearers for human rights.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ec6a4c5a-481f-5ece-ae46-6d8ebc6811fe', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', null, 'csit-617/technology-and-society/q15', 'case_analysis', 'evaluate', 'hard', 'Evaluate the inclusion and workplace-rights implications of a digital transformation', 'Analyse the ethical issues in the case, using concepts from both lessons in this module, and recommend a defensible plan for the company.', null, 'Illustrative scenario. NorthStar Retail, a fictional Ghanaian supermarket chain with branches in Accra, Tamale and several district towns, announces a digital transformation. Customers will need to use a new app to access loyalty discounts and home delivery; the app is available only in English and requires a smartphone. In-store, self-checkout machines will replace half the cashiers. Remaining staff will wear wristbands that track movement and idle time, and an algorithm will schedule shifts weekly based on predicted footfall, with automatic warnings for staff whose "efficiency score" falls. Delivery riders will be engaged as independent contractors through the app, with pay set algorithmically.', null, 25, array['Identification of the main ethical issues for customers, staff and riders', 'Digital inclusion analysis using the three levels of the divide and accessibility', 'Workplace monitoring analysis using the proportionality framework', 'Algorithmic management and automation analysis', 'Application of at least two ethical theories and relevant professional principles', 'Recommendations with justification and implementation priorities']::text[], '[{"criterion":"Inclusion analysis","marks":6,"descriptor":"Identifies excluded customer groups across access, skills and outcomes, addresses language and accessibility, and proposes inclusive channels"},{"criterion":"Monitoring and proportionality","marks":6,"descriptor":"Applies aim, necessity, proportionality, transparency and safeguards to wristbands and efficiency scores"},{"criterion":"Algorithmic management and automation","marks":5,"descriptor":"Analyses scheduling, automatic warnings, rider pay and contractor status, including opacity and fairness"},{"criterion":"Ethical theory and codes","marks":4,"descriptor":"Accurately applies at least two theories and relevant ACM or IEEE principles"},{"criterion":"Recommendations","marks":4,"descriptor":"Concrete, prioritised and justified recommendations that balance business goals with rights"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ec6a4c5a-481f-5ece-ae46-6d8ebc6811fe', '{}'::jsonb, 'Examiners look for integration of inclusion and workplace rights, structured proportionality analysis, accurate use of theory and practical, prioritised recommendations.', 'A strong answer opens by recognising NorthStar''s legitimate aims of efficiency, competitiveness and convenience, then identifies three affected groups. For customers, an English-only smartphone app makes discounts conditional on access and skills, disadvantaging older, rural, low-income, non-English-speaking and disabled customers. This creates first- and second-level divides and a third-level divide in outcomes, since excluded customers pay more. Recommendations include USSD or card-based loyalty, local-language options, accessibility testing against WCAG principles and in-store assistance.
For staff, wristband tracking of idle time and automatic warnings should be tested against the proportionality framework. Workforce planning is a legitimate aim, but continuous body tracking is intrusive and aggregated footfall data or supervisor observation may suffice. Automatic warnings without human review fail the safeguards test. Kantian analysis suggests workers are being treated merely as means, while a utilitarian analysis must weigh efficiency gains against stress, injury and turnover. Weekly algorithmic scheduling raises income instability, so minimum notice periods and worker input are needed.
Automation through self-checkout should be accompanied by consultation, redeployment and retraining, consistent with leadership obligations in the ACM Code to enhance the quality of working life. For riders, algorithmic pay and contractor status raise opacity and fairness concerns. The company should explain pay calculations, provide human review of deactivation and consider minimum earnings protections, noting that employment classification is a legal question requiring advice.
The conclusion should prioritise actions: inclusive loyalty channels and human review of discipline first, then replacing wristbands with less intrusive tools, then transparency for riders.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('917d9ea2-48cb-5ec4-bb61-829f7c290088', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'What are the three levels of the digital divide?', 'First level, material access to devices and connectivity; second level, skills and patterns of use; third level, differences in the outcomes and benefits people obtain.', 'supplementary', 'csit-617/technology-and-society/c058364ebdfc', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e8a7667f-433c-5b1b-8d6e-f0da4b006f92', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'What stages make up van Dijk''s sequence of access?', 'Motivational access, material access, skills access and usage access; people can fall behind at any stage.', 'supplementary', 'csit-617/technology-and-society/f9deb9070a5f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('efc79f17-fc4b-53cf-846c-2308f46ed838', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'Why is mobile money often cited as an inclusion success in Ghana, and what are its limits?', 'It works over USSD on basic phones, needs no bank account and is supported by agents; but low-literacy users may share PINs, face fraud and be affected by charges.', 'supplementary', 'csit-617/technology-and-society/01141000e2e4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ccbe66fa-81af-5de8-aaf7-9d0c9e3f4b43', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'What do the POUR principles of WCAG stand for?', 'Perceivable, Operable, Understandable and Robust, the four principles under which WCAG''s accessibility success criteria are organised.', 'supplementary', 'csit-617/technology-and-society/51f8887aacbf', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('073ab995-e3cd-560c-aa6d-4a506432362f', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'Why is digital inclusion a matter of justice rather than charity?', 'Rawls''s difference principle and the capabilities approach hold that fair societies must enable everyone to access essential services and opportunities, so excluding people through design is an injustice, not merely a missed kindness.', 'supplementary', 'csit-617/technology-and-society/5e53d90aa142', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5ed697ac-b420-59f2-aed0-a6c9dcda769a', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '0c92b022-2516-5e81-905c-1716200a03df', 'What is the main risk of a digital-by-default policy?', 'People without devices, skills, connectivity or accessible interfaces lose access to services unless assisted and non-digital channels are retained.', 'supplementary', 'csit-617/technology-and-society/a24810e92747', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4eb06a46-0b10-5d3c-ab2c-5b8dffa83afd', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'What are digital rights?', 'Human rights such as expression, privacy, association, equality and due process as applied to digital technologies, together with protections specific to digital environments.', 'supplementary', 'csit-617/technology-and-society/c0becc7dce71', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('63988b0f-5247-5e98-8046-86a1ab9961b4', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'Why are blanket internet shutdowns usually considered disproportionate?', 'They affect whole populations and disrupt commerce, mobile money, emergency services, education and journalism, while less intrusive measures are usually available.', 'supplementary', 'csit-617/technology-and-society/56f46c2ce2cb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4887ab8d-08cb-565a-ac0f-1a152672f046', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'Why is employee consent a weak justification for workplace monitoring?', 'The employment relationship involves a power imbalance, so consent may not be freely given; monitoring must also be necessary, proportionate and transparent with safeguards.', 'supplementary', 'csit-617/technology-and-society/43dfa4807e34', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3d562076-70d1-5e84-b867-ce673c0dbbf3', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'State the five questions of the workplace monitoring proportionality framework.', 'Is there a legitimate aim? Is monitoring necessary? Is the intrusion proportionate? Is it transparent to workers? Are there adequate safeguards?', 'supplementary', 'csit-617/technology-and-society/c430c57299f3', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('32d7135d-29d0-5ffc-8499-05cba4fe3c49', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'What are the main ethical concerns about algorithmic management?', 'Opacity of decisions, work intensification, bias (for example via customer ratings), lack of voice or human appeal, and misclassification of workers as contractors.', 'supplementary', 'csit-617/technology-and-society/91a08a0f48d5', true)
