insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c964a072-6d11-5a2d-aa1c-0d80ac1b3939', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '3ef57448-266c-5b97-9b39-44d53c2e2c40', '33f2e054-569d-5fa9-9081-58e689f1d453', 'How can data protection rights act as workers'' rights?', 'Rights of access to personal data and protections around automated decision-making let workers obtain information about how algorithms assess them and challenge unfair decisions, as in the 2021 Amsterdam ride-hailing cases.', 'supplementary', 'csit-617/technology-and-society/937dc4a72015', true)
