insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('928a3013-bcf7-5efb-91f7-7a4e4fce4c9e', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'data-and-privacy', 'Data and Privacy', 'The ethics and law of collecting, using and protecting personal data.', 4, true)
