insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5e029540-818b-5bfa-8f6c-70295aabe02a', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '928a3013-bcf7-5efb-91f7-7a4e4fce4c9e', '0c0c1e6f-67f3-5b49-b268-c2c7d090ccde', 'What does Zuboff mean by surveillance capitalism?', 'An economic logic in which human experience is captured as behavioural data, analysed to predict behaviour and used to influence it for profit, creating large asymmetries of knowledge and power.', 'supplementary', 'csit-617/data-and-privacy/35633bc4a972', true)
