insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e421487c-bdca-54a8-ac4f-9c03d5e58389', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '928a3013-bcf7-5efb-91f7-7a4e4fce4c9e', '0c0c1e6f-67f3-5b49-b268-c2c7d090ccde', 'List the seven points of the surveillance assessment checklist.', 'Legal basis, legitimate aim, necessity and targeting, proportionality, independent oversight, transparency and remedy, and security and retention limits.', 'supplementary', 'csit-617/data-and-privacy/3d976b781854', true)
