insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('58996b5c-93ce-5c83-94c2-3b5e88f4fd30', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '928a3013-bcf7-5efb-91f7-7a4e4fce4c9e', '0c0c1e6f-67f3-5b49-b268-c2c7d090ccde', 'What are the recognised limits of confidentiality?', 'Legal requirements such as court orders, the consent of the person concerned and, exceptionally, disclosure to prevent serious harm in the public interest, usually after internal channels have been tried.', 'supplementary', 'csit-617/data-and-privacy/7e39334918a4', true)
