insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4825c7a8-89b4-5dd4-8060-32967eac58dc', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'csit-617/intellectual-property/ip01', 'mcq', 'understand', 'easy', 'Apply the idea-expression distinction to software', 'A competitor studies a popular Ghanaian ride-hailing app and independently writes new code that reproduces its main features. Which statement best describes the copyright position?', null, null, '[{"id":"a","text":"The competitor infringes copyright because the features are the same"},{"id":"b","text":"The competitor does not infringe copyright, because copyright protects expression rather than functionality, provided no code was copied"},{"id":"c","text":"The competitor infringes only if the original app was registered with the Copyright Office"},{"id":"d","text":"Copyright does not apply to software at all"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4825c7a8-89b4-5dd4-8060-32967eac58dc', '{"option":"b"}'::jsonb, 'Copyright protects the expression of a program (its code and some structural elements), not ideas, methods or functionality. Independent creation is a defence. Registration is not required for copyright to arise, and software is protected as a literary work under TRIPS and Act 690, so the other options are wrong.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bfc67afb-9f7c-5a02-aa57-dc66fd23a181', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'csit-617/intellectual-property/ip02', 'matching', 'recall', 'easy', 'Match IP regimes to their characteristic features', 'Match each form of intellectual property to the feature that best characterises it.', null, null, '{"left":[{"id":"l1","text":"Copyright"},{"id":"l2","text":"Patent"},{"id":"l3","text":"Trademark"},{"id":"l4","text":"Trade secret"}],"right":[{"id":"r1","text":"Arises automatically on creation of an original work"},{"id":"r2","text":"Requires novelty, an inventive step and public disclosure"},{"id":"r4","text":"Lasts only as long as the information is kept confidential"},{"id":"r3","text":"Distinguishes the commercial origin of goods or services"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bfc67afb-9f7c-5a02-aa57-dc66fd23a181', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each regime protects a different kind of intangible asset under different conditions. Mixing them up is a common examination error; the comparison table in the lesson summarises subject matter, requirements and duration.', null)
