insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4478e25f-4cd7-508c-a1b5-a511d7f97576', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'csit-617/intellectual-property/ip03', 'true_false', 'understand', 'easy', 'Distinguish patents from copyright regarding independent creation', 'Independent creation is a defence to patent infringement in the same way as it is to copyright infringement.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4478e25f-4cd7-508c-a1b5-a511d7f97576', '{"value":false}'::jsonb, 'Patents protect the claimed invention itself, so someone who independently arrives at the same invention can still infringe. Copyright, by contrast, is infringed only by copying, so independent creation is a defence.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7dad03d7-52a6-5ba2-991e-4a3226270b24', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'csit-617/intellectual-property/ip04', 'scenario', 'apply', 'medium', 'Select appropriate protection for a confidential algorithm', 'Which protection strategy is most appropriate for the scoring rules?', 'An Accra-based credit-scoring start-up has developed a set of unpublished rules that combine mobile-money transaction patterns to predict loan default. The rules give it a competitive advantage. The founders do not want to publish the method, and it is unclear whether it would satisfy patentability requirements.', null, '[{"id":"a","text":"Rely on trademark registration of the rules"},{"id":"b","text":"Protect the rules as a trade secret using access controls and confidentiality agreements"},{"id":"c","text":"Publish the rules on the company website to establish copyright"},{"id":"d","text":"Do nothing, because copyright automatically protects the underlying method"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7dad03d7-52a6-5ba2-991e-4a3226270b24', '{"option":"b"}'::jsonb, 'Trade-secret protection suits valuable information the owner wishes to keep confidential, and does not require disclosure or examination. Trademarks protect brand signs, not methods. Publishing would destroy secrecy, and copyright would not protect the method itself, only its written expression.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d5d29001-9b1f-5757-80a9-f590b5b93529', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'csit-617/intellectual-property/ip05', 'short_answer', 'recall', 'medium', 'Identify Ghana''s principal copyright statute', 'Give the year of Ghana''s Copyright Act that is designated Act 690.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
