insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d5d29001-9b1f-5757-80a9-f590b5b93529', '{"answers":["2005","Copyright Act 2005","Copyright Act, 2005"]}'::jsonb, 'Ghana''s principal copyright statute is the Copyright Act, 2005 (Act 690). It protects computer software among other works and provides for the Copyright Office.', null)
