insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('557e94d2-fdd7-5ddb-a834-556ce6f96bda', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'csit-617/intellectual-property/ip06', 'mcq', 'evaluate', 'hard', 'Evaluate arguments in the software patent debate', 'Which argument against software patents is best grounded in utilitarian reasoning?', null, null, '[{"id":"a","text":"Software patents violate the inventor''s natural right to the fruits of labour"},{"id":"b","text":"Broad, long-lasting software patents may reduce overall innovation and welfare by blocking incremental, fast-moving development"},{"id":"c","text":"Software is mathematics, and mathematics is sacred"},{"id":"d","text":"Patents are unfair because only large firms can read patent claims"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('557e94d2-fdd7-5ddb-a834-556ce6f96bda', '{"option":"b"}'::jsonb, 'Utilitarian reasoning judges IP by its consequences for overall welfare; the claim that software patents may reduce net innovation is a consequentialist argument. The first option invokes Lockean labour theory (and argues for, not against, protection). The third is not an ethical argument, and the fourth is a fairness/access claim stated as an overgeneralisation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('70f9b8d6-ea2d-5e7e-a177-251eca9af756', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'csit-617/intellectual-property/ip07', 'true_false', 'understand', 'medium', 'Interpret the outcome of Google v. Oracle', 'In Google LLC v. Oracle America (2021), the US Supreme Court held that APIs are never protected by copyright.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('70f9b8d6-ea2d-5e7e-a177-251eca9af756', '{"value":false}'::jsonb, 'The Court assumed, without deciding, that the Java API declaring code was copyrightable and held that Google''s copying was fair use. It did not rule on copyrightability, and the decision applies US fair use law, not the law of other jurisdictions.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f7823b9a-0a65-5fc2-81a9-a1e8dc3a700d', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'csit-617/intellectual-property/ip08', 'mcq', 'recall', 'easy', 'Identify the main obligation of the MIT License', 'What is the principal condition a developer must meet when redistributing MIT-licensed code?', null, null, '[{"id":"a","text":"Release all of their own source code under the MIT License"},{"id":"b","text":"Include the original copyright notice and the licence text"},{"id":"c","text":"Pay a royalty to the original author"},{"id":"d","text":"Obtain approval from the Open Source Initiative"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f7823b9a-0a65-5fc2-81a9-a1e8dc3a700d', '{"option":"b"}'::jsonb, 'The MIT License is permissive; its key condition is preserving the copyright notice and licence text in copies or substantial portions. It does not require releasing your own code (that is copyleft), payment or OSI approval.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('49279867-743b-5fd6-8764-687b033d84f9', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'csit-617/intellectual-property/ip09', 'matching', 'understand', 'medium', 'Match licences to their distinctive obligations', 'Match each licence to its most distinctive feature.', null, null, '{"left":[{"id":"l1","text":"MIT"},{"id":"l2","text":"Apache 2.0"},{"id":"l3","text":"GPL"},{"id":"l4","text":"LGPL"},{"id":"l5","text":"AGPL"}],"right":[{"id":"r2","text":"Express patent grant with a patent retaliation clause"},{"id":"r1","text":"Minimal conditions; keep the notice and licence text"},{"id":"r3","text":"Distributed derivative works must be released under the same licence with source"},{"id":"r4","text":"Proprietary programs may link to the library under conditions"},{"id":"r5","text":"Source obligations extend to modified software offered over a network"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('49279867-743b-5fd6-8764-687b033d84f9', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'These distinctions drive compliance decisions. Apache 2.0''s patent terms, GPL''s strong copyleft, LGPL''s linking exception and AGPL''s network clause are the features examiners most often test.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('53544628-6353-5e2d-b3e2-a2a1f36558a4', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'csit-617/intellectual-property/ip10', 'scenario', 'apply', 'medium', 'Apply GPL obligations to a distributed product', 'What is the most appropriate course of action?', 'A developer at a Ghanaian fintech copies a GPL-licensed encryption routine directly into the source code of the company''s proprietary mobile wallet app, which is distributed to customers through app stores. The company does not want to release its source code.', null, '[{"id":"a","text":"Nothing; GPL obligations apply only to non-commercial software"},{"id":"b","text":"Rename the variables in the copied code so that it is no longer GPL code"},{"id":"c","text":"Replace the GPL code with a compatibly licensed or proprietary alternative, or obtain a separate licence from the copyright holder"},{"id":"d","text":"Add the author''s name in a comment, which satisfies the GPL"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('53544628-6353-5e2d-b3e2-a2a1f36558a4', '{"option":"c"}'::jsonb, 'Distributing an app incorporating GPL code generally requires licensing the combined work under the GPL with source. If the company will not do that, it must remove the code or obtain different licence terms. The GPL applies to commercial software, superficial changes still create a derivative work, and attribution alone does not satisfy copyleft.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e710fb82-6ed9-5d59-9f81-5534625664e1', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'csit-617/intellectual-property/ip11', 'true_false', 'understand', 'easy', 'Interpret "free" in free software', 'In the Free Software Foundation''s sense, "free software" means software that is given away at no cost.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e710fb82-6ed9-5d59-9f81-5534625664e1', '{"value":false}'::jsonb, 'The word free refers to freedom (to run, study and change, redistribute and distribute modified versions) not price. Free software may be sold, and no-cost software can be proprietary.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('477cc5a3-ace6-5d17-8de9-966070c45ce5', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'csit-617/intellectual-property/ip12', 'short_answer', 'recall', 'medium', 'Name the licensing technique that keeps derivatives free', 'What term describes the licensing technique that requires distributed modified versions of a work to remain under the same free licence?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('477cc5a3-ace6-5d17-8de9-966070c45ce5', '{"answers":["copyleft","copy left","copyleft licensing"]}'::jsonb, 'Copyleft uses copyright law to require that freedoms granted by the licence are preserved in distributed derivative works. The GPL is the best-known copyleft licence.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3a007a5e-09ee-578d-9a34-3b05f63f1c15', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'csit-617/intellectual-property/ip13', 'mcq', 'analyse', 'hard', 'Analyse when GPL obligations are triggered', 'A bank modifies a GPL-licensed reporting tool and runs it only on its own internal servers for staff use. It never distributes the software outside the organisation. Which statement is most accurate?', null, null, '[{"id":"a","text":"The bank must publish its modified source code immediately"},{"id":"b","text":"Under the standard GPL, internal use without distribution generally does not trigger the obligation to release source code"},{"id":"c","text":"The bank''s use is illegal because GPL software cannot be modified"},{"id":"d","text":"The bank must switch to the LGPL version"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3a007a5e-09ee-578d-9a34-3b05f63f1c15', '{"option":"b"}'::jsonb, 'The GPL''s source-release obligations are tied mainly to distribution (conveying copies). Purely internal use generally does not trigger them. Modification is expressly permitted. The AGPL was created precisely because network use is not covered by the ordinary GPL.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a4a292b3-ddb6-5176-8917-a3366564f26a', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'csit-617/intellectual-property/ip14', 'true_false', 'apply', 'medium', 'Recognise the legal status of unlicensed code', 'Source code published on a public repository without any licence may generally be reused freely because it is in the public domain.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a4a292b3-ddb6-5176-8917-a3366564f26a', '{"value":false}'::jsonb, 'Copyright arises automatically. Without a licence granting permission, the default position is that others may not copy, modify or distribute the code. Visibility does not equal permission.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3a39655f-67b7-5ea7-a3c5-e6f9ab02b8b7', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'csit-617/intellectual-property/ip15', 'mcq', 'understand', 'easy', 'Distinguish plagiarism from copyright infringement', 'Which statement best describes the relationship between plagiarism and copyright infringement?', null, null, '[{"id":"a","text":"They are identical concepts with different names"},{"id":"b","text":"Plagiarism concerns misrepresenting the origin of work; copyright infringement concerns unauthorised copying of protected expression, and the two can occur independently"},{"id":"c","text":"Plagiarism is only possible with copyrighted works"},{"id":"d","text":"Citing a source always prevents copyright infringement"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3a39655f-67b7-5ea7-a3c5-e6f9ab02b8b7', '{"option":"b"}'::jsonb, 'You can plagiarise a public-domain work (no copyright, but false attribution), and you can infringe copyright while citing the author (attribution without permission). They overlap but are distinct. Citation does not grant reproduction rights.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('03fa45ab-2be2-56dc-89a2-5a3ebe68fe3f', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'csit-617/intellectual-property/ip16', 'scenario', 'apply', 'medium', 'Apply integrity principles to generative AI use', 'Which is the most defensible assessment of the student''s conduct?', 'An MSc student''s assignment brief does not mention generative AI. The student uses an AI tool to draft the literature review, edits it lightly, and submits it without mention of the tool. Two of the references cannot be found in any database.', null, '[{"id":"a","text":"Acceptable, because the brief did not prohibit AI"},{"id":"b","text":"Acceptable, because no human author''s words were copied"},{"id":"c","text":"Problematic, because the student did not confirm the institution''s policy, did not disclose the use and submitted unverified, apparently fabricated references"},{"id":"d","text":"Problematic only because of grammar errors in AI output"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('03fa45ab-2be2-56dc-89a2-5a3ebe68fe3f', '{"option":"c"}'::jsonb, 'Silence in a brief does not authorise use; students must check their institution''s policy and ask when unclear. Undisclosed AI-generated text can misrepresent authorship, and submitting non-existent references is fabrication regardless of intention. The permit-disclose-verify-own model captures each failure.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6ca36a19-b055-5919-84a9-3d6b20fdb7a3', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'csit-617/intellectual-property/ip17', 'matching', 'understand', 'medium', 'Distinguish forms of academic misconduct', 'Match each behaviour to the form of misconduct it represents.', null, null, '{"left":[{"id":"l1","text":"Paying a freelancer to write an assignment"},{"id":"l2","text":"Two students writing an individual report together without permission"},{"id":"l3","text":"Inventing survey responses to complete a data set"},{"id":"l4","text":"Resubmitting last year''s essay for a new module"}],"right":[{"id":"r2","text":"Collusion"},{"id":"r3","text":"Fabrication"},{"id":"r1","text":"Contract cheating"},{"id":"r4","text":"Self-plagiarism or duplicate submission"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6ca36a19-b055-5919-84a9-3d6b20fdb7a3', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each behaviour misrepresents something different, who did the work, whether it was individual, whether the data are real, or whether the effort is new. Precise classification shows understanding.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('63299de6-337f-596e-b16d-a9118b523fb9', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'csit-617/intellectual-property/ip18', 'true_false', 'understand', 'easy', 'Interpret similarity-checking results', 'A low similarity score from text-matching software proves that a submission contains no plagiarism.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('63299de6-337f-596e-b16d-a9118b523fb9', '{"value":false}'::jsonb, 'Similarity tools detect textual overlap with indexed sources; they can miss idea plagiarism, translated or paraphrased material, contract cheating and AI-generated text. Scores require human judgement in both directions.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f1e3190c-58c5-556f-ad3f-478e68be3505', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'csit-617/intellectual-property/ip19', 'short_answer', 'recall', 'medium', 'Recall a fundamental value of academic integrity', 'The ICAI''s fundamental values are honesty, trust, fairness, respect, responsibility and which sixth value?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f1e3190c-58c5-556f-ad3f-478e68be3505', '{"answers":["courage"]}'::jsonb, 'Courage, acting with integrity when it is difficult or unpopular, completes the six values described by the International Center for Academic Integrity.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1567dd5a-036a-5304-b611-391819333f3d', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'csit-617/intellectual-property/ip20', 'mcq', 'evaluate', 'hard', 'Evaluate why AI tools are not accepted as authors', 'What is the strongest reason publication-ethics bodies such as COPE give for not accepting AI tools as authors?', null, null, '[{"id":"a","text":"AI tools write poorly"},{"id":"b","text":"AI tools cannot take responsibility or be accountable for the work"},{"id":"c","text":"AI tools are too expensive for most researchers"},{"id":"d","text":"AI tools are protected by trademark law"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1567dd5a-036a-5304-b611-391819333f3d', '{"option":"b"}'::jsonb, 'Authorship entails accountability (answering for the work, correcting errors and attesting to its integrity) which a tool cannot do. Writing quality and cost are irrelevant to the principle, and trademark law has nothing to do with authorship.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('287f7335-3da6-5db0-a1bb-e7f87681e0ac', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', null, 'csit-617/intellectual-property/ip21', 'case_analysis', 'evaluate', 'hard', 'Construct a defensible recommendation on an IP and licensing dilemma', 'Analyse the case and recommend how the company should proceed. Use at least two ethical theories and the ACM Code of Ethics.', null, 'Illustrative scenario. "Tema Smart Ports Ltd", a Ghanaian software firm, is about to ship a container-tracking system to clients in three West African countries. A pre-release audit finds that (a) a senior developer copied a GPL-licensed scheduling module into the product, (b) the user interface uses icons downloaded from a website with no licence information, and (c) the project report submitted to a client funder contains several paragraphs copied from a vendor white paper without citation. The CEO wants to ship on schedule and "fix things later".', null, 25, array['Identify the facts and the IP and integrity issues in each of (a), (b) and (c)', 'Identify stakeholders and their interests', 'Apply relevant legal concepts (copyleft obligations, default copyright, plagiarism vs infringement)', 'Analyse using at least two ethical theories and relevant ACM Code principles', 'Set out options and evaluate them', 'Make a defensible recommendation and address counter-arguments']::text[], '[{"criterion":"Issue identification and legal concepts","marks":6,"descriptor":"Correctly explains GPL obligations on distribution, the no-licence position for icons, and plagiarism versus infringement in the report."},{"criterion":"Stakeholder analysis","marks":4,"descriptor":"Identifies clients, funder, original authors, developers, the firm and end users, with their interests."},{"criterion":"Ethical analysis","marks":7,"descriptor":"Applies at least two theories accurately and cites relevant ACM principles such as 1.3, 1.5 and 2.3."},{"criterion":"Options and recommendation","marks":6,"descriptor":"Evaluates realistic options and gives a clear, justified recommendation with practical steps."},{"criterion":"Counter-arguments and communication","marks":2,"descriptor":"Addresses the CEO''s schedule argument and writes clearly."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('287f7335-3da6-5db0-a1bb-e7f87681e0ac', '{}'::jsonb, 'Examiners look for accurate licence reasoning, clear distinction between plagiarism and infringement, genuine use of two ethical theories with ACM principles, and a practical, justified recommendation.', 'A strong answer separates the three problems. (a) Because the system will be distributed to clients, incorporating GPL code generally obliges the firm to license the combined work under the GPL and provide source. If it wants to remain proprietary, it must replace the module or negotiate a separate licence; renaming or modifying the code does not avoid the obligation. (b) Icons without licence information are protected by default copyright, so the firm lacks permission; it should replace them with properly licensed assets or obtain permission. (c) The report misrepresents vendor material as the firm''s own analysis, plagiarism, and may also infringe copyright; it must be corrected and the funder informed.

Stakeholders include clients (who may inherit legal risk), the funder (misled), original authors (whose conditions are ignored), staff and the firm''s reputation. A utilitarian analysis weighs short-term delay against risks of injunctions, client losses and reputational damage, and the wider harm to the open-source commons; it favours remediation before shipping. A Kantian analysis rejects shipping knowingly non-compliant software because it treats authors merely as means and relies on deception. ACM principles 1.3 (honesty), 1.5 (respect and credit creators'' work) and 2.3 (know and respect rules) point the same way.

Options: ship now and fix later; delay to remediate; ship GPL-compliant. The recommended course is a short delay to replace the GPL module and icons, correct and disclose the report, and introduce SBOM scanning and a licence policy. The schedule counter-argument is acknowledged, but knowingly distributing infringing software converts an internal error into deliberate wrongdoing.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('cda32dab-f38f-5c41-81c9-2d38af5689c0', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'What does the idea-expression distinction mean for software?', 'Copyright protects the way a program is expressed (its code and some structure), not its ideas, algorithms or functionality, so independently written code with the same features does not infringe.', 'supplementary', 'csit-617/intellectual-property/8a5b6b2a8bff', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('56e12c5b-5161-5fac-946e-51fe3df60143', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'Why is independent creation a defence to copyright but not to patent infringement?', 'Copyright is infringed only by copying expression; a patent protects the claimed invention itself, so anyone practising it without a licence infringes, even if they invented it independently.', 'supplementary', 'csit-617/intellectual-property/ea01fce16042', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0f84a525-8a72-5daf-9ed5-ab288b4a8890', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'When is a trade secret the best protection for an algorithm?', 'When the algorithm is valuable, can be kept confidential (it is not exposed by the product), and the owner does not want the disclosure or cost that a patent requires.', 'supplementary', 'csit-617/intellectual-property/5a1a00c3e1a9', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('415386e1-1d12-5c14-89e6-abb20258d2ff', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'Give one utilitarian argument for and one against software patents.', 'For, patents can reward costly R&D and add disclosed knowledge. Against, long, broad patents in a fast, incremental field may block follow-on innovation and impose litigation costs, reducing overall welfare.', 'supplementary', 'csit-617/intellectual-property/9c9cd97299fa', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1afd3e94-b189-5af4-aa83-247165f57ab2', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'In general terms, what does Ghana''s Copyright Act, 2005 (Act 690) do for software?', 'It treats computer software as a protected work, grants authors economic and moral rights, provides limitations for certain uses such as research and education, and establishes the Copyright Office.', 'supplementary', 'csit-617/intellectual-property/e06c02debb9f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('88ffd0c0-82c8-57d2-8f9f-3d4b14e280c2', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '45e874ca-3a81-5858-b577-33dba6ce2a8e', 'What is the "bargain" underlying intellectual property law?', 'The state grants creators limited, temporary exclusivity as an incentive, in return for public benefits such as disclosure (patents) and eventual entry of works into the public domain.', 'supplementary', 'csit-617/intellectual-property/d0935cad0e8e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6adf7df5-1f0a-5a01-baf5-08a44e8ab8ae', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'What triggers the source-code release obligation under the GPL?', 'Mainly distributing (conveying) the program or a work based on it to others; purely internal use generally does not trigger it.', 'supplementary', 'csit-617/intellectual-property/c53497aa6fd0', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('818276ea-cea5-5da6-813f-a65134e28c1f', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'How does Apache 2.0 differ from MIT?', 'Both are permissive, but Apache 2.0 adds an express patent licence, a patent retaliation clause, a NOTICE-file requirement and the duty to mark changed files.', 'supplementary', 'csit-617/intellectual-property/ea7a22739e80', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b6014e04-d99b-54b5-86d1-91e0434f4ac9', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'Why can proprietary software use an LGPL library?', 'The LGPL allows linking from non-LGPL programs provided changes to the library remain LGPL and users can replace or relink the library.', 'supplementary', 'csit-617/intellectual-property/21114d89cfd0', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('28b9e636-b07f-5c6d-a5f4-7aa13cc92510', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'What are the four freedoms of free software?', 'Freedom to run the program for any purpose, to study and change it (needs source), to redistribute copies, and to distribute modified versions.', 'supplementary', 'csit-617/intellectual-property/a7ab6b936622', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9a2cf5b3-9209-58ae-ae5b-42a8ebd97253', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'How do the free software and open-source movements differ in emphasis?', 'Free software treats user freedom as an ethical obligation; open source emphasises the practical benefits of collaborative development, such as quality and innovation.', 'supplementary', 'csit-617/intellectual-property/315854d6e19c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9ac12829-f68b-5a8a-91e4-96312897cf4a', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '52aa1d16-80c4-5682-9db1-d09cc5d07ca9', 'What does a software bill of materials (SBOM) help an organisation do?', 'Inventory every third-party component and its licence so that obligations, incompatibilities and security vulnerabilities can be managed.', 'supplementary', 'csit-617/intellectual-property/66d1b1f9d177', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('981ef598-c9ef-5fd4-b568-327b99f60d98', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'Why can you plagiarise a work that has no copyright?', 'Plagiarism is a failure of attribution, misrepresenting origin, not a breach of legal rights, so presenting a public-domain text as your own is still plagiarism.', 'supplementary', 'csit-617/intellectual-property/322dff6e9328', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0c2be893-0506-5081-a1f4-a9f11e6deeb7', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'What is patchwriting and why is it plagiarism?', 'Stitching together a source''s phrases with minor word changes; it preserves the original expression and structure, so it misrepresents the writing as your own even if cited.', 'supplementary', 'csit-617/intellectual-property/b0ff9f9502db', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('39f86268-7c03-5ace-88a3-5f34b5d15b3a', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'What does "permit, disclose, verify, own" mean for generative AI use?', 'Confirm use is allowed by your institution and the assessment; disclose the tool and purpose; check every claim and reference; take full responsibility for the final work.', 'supplementary', 'csit-617/intellectual-property/23fbac2b1361', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('64105377-8349-5fb8-b663-f5ae2d89e164', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'Why do publication-ethics bodies say AI cannot be an author?', 'Authorship requires accountability, answering for the work and its integrity, which a tool cannot provide.', 'supplementary', 'csit-617/intellectual-property/28527389b1ad', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1bddca4e-2925-5d57-b9df-5909bdcd5f56', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'What lesson does Mata v. Avianca (2023) teach about AI-generated references?', 'AI tools can fabricate plausible citations, and the professional who submits them remains responsible; verification is a non-negotiable duty.', 'supplementary', 'csit-617/intellectual-property/5af0f418b182', true)
