insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a7fdd07a-daf2-5fcd-bf2a-fecad112fd7c', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '04d94be8-b000-5ff6-8215-0eab34e44cf3', '42916a9a-a26c-5284-a1e4-61f6b887dea5', 'How does a Kantian analysis condemn plagiarism?', 'It involves deception that cannot be universalised without destroying the practice of credit, and it treats original authors merely as means.', 'supplementary', 'csit-617/intellectual-property/0e7a6644bc41', true)
