insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('2e71e1ca-c49d-568d-8454-3f9693cdf93c', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'ai-ethics', 'AI and Emerging Ethical Issues', 'The distinctive ethical challenges posed by AI systems.', 6, true)
