insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e646601f-3b50-5e3b-8555-491b7066e771', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'csit-617/professional-practice/pp01', 'mcq', 'understand', 'easy', 'Identify the core wrong in a conflict of interest', 'According to the lesson, what is the central ethical failure in most conflict-of-interest cases?', null, null, '[{"id":"a","text":"Having any private interest at all"},{"id":"b","text":"Concealing or failing to manage the conflict"},{"id":"c","text":"Working for a private company"},{"id":"d","text":"Knowing people who work for vendors"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
