insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e646601f-3b50-5e3b-8555-491b7066e771', '{"option":"b"}'::jsonb, 'Conflicts are situations that are often unavoidable. The wrong lies in hiding them or failing to manage them through disclosure, recusal or other controls. Simply having interests or relationships is not in itself wrongdoing.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ee9f160b-5d34-57ca-8b1b-3f80fb2a4b50', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'csit-617/professional-practice/pp02', 'matching', 'understand', 'medium', 'Classify actual, potential and perceived conflicts', 'Match each situation to the type of conflict of interest it represents.', null, null, '{"left":[{"id":"l1","text":"An IT manager scores a tender submitted by her brother''s company"},{"id":"l2","text":"A developer owns shares in a cloud provider his employer may consider next year"},{"id":"l3","text":"A consultant recommends a vendor after a vendor-paid luxury trip, though his analysis was sound"}],"right":[{"id":"r2","text":"Potential conflict"},{"id":"r3","text":"Perceived conflict"},{"id":"r1","text":"Actual conflict"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
