insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ee9f160b-5d34-57ca-8b1b-3f80fb2a4b50', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'Actual conflicts exist now; potential conflicts may arise if circumstances change; perceived conflicts exist where a reasonable observer could doubt impartiality. All three should be disclosed and managed.', null)
