insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('17d19572-d43b-5276-8f9a-218700c0bc9a', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'csit-617/professional-practice/pp03', 'scenario', 'apply', 'medium', 'Apply the conflict-management process', 'What should Ama do first?', 'Illustrative scenario. Ama, head of IT at a Kumasi manufacturing firm, sits on the committee choosing a cybersecurity vendor. She learns that her husband has just accepted a senior role at one of the bidders. The committee meets tomorrow.', null, '[{"id":"a","text":"Say nothing, because she will remain objective"},{"id":"b","text":"Declare the relationship in writing to the committee chair before the meeting and offer to recuse herself from evaluating that bid"},{"id":"c","text":"Ask her husband to withdraw the bid"},{"id":"d","text":"Resign from the company immediately"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('17d19572-d43b-5276-8f9a-218700c0bc9a', '{"option":"b"}'::jsonb, 'Prompt written disclosure allows the organisation to assess and manage the conflict, typically by recusal from that decision. Silence creates an undisclosed conflict; asking her husband to interfere would be improper; resignation is disproportionate when disclosure and recusal suffice.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6db6e82b-5e08-563d-9ecb-7e2b02840b90', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'csit-617/professional-practice/pp04', 'true_false', 'recall', 'easy', 'Recall ACM guidance on conflicts of interest', 'ACM principle 1.3 (Be honest and trustworthy) asks computing professionals to be forthright about circumstances that might lead to real or perceived conflicts of interest.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
