insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('74885948-1a45-5da6-bdd4-64a508d33ebe', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'csit-617/professional-practice/pp05', 'short_answer', 'recall', 'medium', 'Name the act of withdrawing from a conflicted decision', 'What is the term for withdrawing from a decision or activity in which one has a conflict of interest?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
