insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8b2b8c87-6f69-532d-b01e-fa62dfb3911c', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'csit-617/professional-practice/pp06', 'mcq', 'evaluate', 'hard', 'Evaluate the limits of employee loyalty', 'A manager instructs a developer to mark a known security defect as "resolved" in the client report so that a milestone payment is released. Which response is most defensible?', null, null, '[{"id":"a","text":"Comply, because loyalty to the employer is the developer''s primary duty"},{"id":"b","text":"Comply but keep a private record in case of problems later"},{"id":"c","text":"Decline to misreport, explain the risk and escalate through internal channels if necessary"},{"id":"d","text":"Immediately post the defect details on social media"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
