insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8b2b8c87-6f69-532d-b01e-fa62dfb3911c', '{"option":"c"}'::jsonb, 'Loyalty does not extend to deceiving clients; ACM principles 1.3 and 1.2 require honesty and harm avoidance. Escalating internally is proportionate. Complying, even with a private record, makes the developer complicit, and public disclosure before internal routes is premature and may expose the client to attack.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('78ca4a76-7c78-51be-876b-c119e619e2b4', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'csit-617/professional-practice/pp07', 'true_false', 'apply', 'medium', 'Apply the purpose limitation on privileged access', 'A database administrator who looks up a celebrity customer''s account out of curiosity has not acted unethically, because administrator rights allowed the query.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('78ca4a76-7c78-51be-876b-c119e619e2b4', '{"value":false}'::jsonb, 'Access is granted for specific purposes. Using it beyond them breaches confidentiality and ACM principle 2.8 (access resources only when authorised), whatever the system technically permits.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('79ed60ab-4b39-51e6-b7d8-9f5a220e8da7', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'ba80c4a7-403a-5227-90de-7ff87f4eafeb', 'csit-617/professional-practice/pp08', 'mcq', 'understand', 'medium', 'Distinguish De George''s permissibility and obligation criteria', 'According to De George, which additional conditions turn morally permissible whistleblowing into morally obligatory whistleblowing?', null, null, '[{"id":"a","text":"The harm is serious and the employee has told a superior"},{"id":"b","text":"The employee has exhausted internal channels"},{"id":"c","text":"The employee has documented evidence convincing to a reasonable impartial observer and good reason to believe going public will bring about change"},{"id":"d","text":"The employee will receive a financial reward"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('79ed60ab-4b39-51e6-b7d8-9f5a220e8da7', '{"option":"c"}'::jsonb, 'Criteria 1-3 (serious harm, reporting to a superior, exhausting internal channels) make disclosure permissible; criteria 4-5 (convincing evidence and likelihood of success) make it obligatory. Rewards are not part of De George''s criteria.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3cff5512-11c0-57ce-9fb8-cf2b18a660f7', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'ba80c4a7-403a-5227-90de-7ff87f4eafeb', 'csit-617/professional-practice/pp09', 'matching', 'recall', 'easy', 'Recall the four elements of negligence', 'Match each element of negligence to its meaning.', null, null, '{"left":[{"id":"l1","text":"Duty of care"},{"id":"l2","text":"Breach"},{"id":"l3","text":"Causation"},{"id":"l4","text":"Harm"}],"right":[{"id":"r4","text":"The claimant suffered recognised loss or damage"},{"id":"r3","text":"The breach actually and sufficiently closely caused the loss"},{"id":"r2","text":"Falling below the standard of a reasonably competent professional"},{"id":"r1","text":"An obligation to take reasonable care to avoid foreseeable harm to the claimant"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3cff5512-11c0-57ce-9fb8-cf2b18a660f7', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'All four elements must be established. Examination answers often omit causation, yet a breach that did not cause the loss does not ground liability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4d910dfb-0c71-5e12-b4c5-8f0abde56730', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'ba80c4a7-403a-5227-90de-7ff87f4eafeb', 'csit-617/professional-practice/pp10', 'scenario', 'apply', 'medium', 'Apply De George''s criteria to an IT dilemma', 'On De George''s criteria, what is the most appropriate next step?', 'Illustrative scenario. A tester at a Ghanaian health-software firm discovers that lab results can be attached to the wrong patient. She tells her team lead, who refuses to delay the release. She has not yet raised it with anyone more senior. The software is live in hospitals.', null, '[{"id":"a","text":"Go directly to the media, since harm is serious"},{"id":"b","text":"Do nothing, since she has already told her team lead"},{"id":"c","text":"Escalate in writing up the management chain, to the board if necessary, with evidence, before considering external disclosure"},{"id":"d","text":"Delete the test results to protect the company"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4d910dfb-0c71-5e12-b4c5-8f0abde56730', '{"option":"c"}'::jsonb, 'Criterion 3 requires exhausting internal channels before external disclosure is permissible on De George''s account, unless doing so is unsafe or futile. Doing nothing ignores serious harm, and destroying evidence would be seriously wrong and possibly unlawful.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bc72a543-9f32-5182-a6ba-58fb05c478a3', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'ba80c4a7-403a-5227-90de-7ff87f4eafeb', 'csit-617/professional-practice/pp11', 'true_false', 'understand', 'medium', 'Interpret the professional standard of care', 'In negligence, an IT professional is judged against a standard of perfection, so any software defect that causes loss establishes breach.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bc72a543-9f32-5182-a6ba-58fb05c478a3', '{"value":false}'::jsonb, 'The standard is that of a reasonably competent professional in the field, taking into account accepted practice and knowledge at the time. Not every defect is negligent; the question is whether reasonable care was exercised.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8112738f-126e-5a30-b073-a14027f80da4', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'ba80c4a7-403a-5227-90de-7ff87f4eafeb', 'csit-617/professional-practice/pp12', 'short_answer', 'recall', 'medium', 'Identify Ghana''s whistleblowing statute', 'Give the act number of Ghana''s Whistleblower Act, 2006.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8112738f-126e-5a30-b073-a14027f80da4', '{"answers":["Act 720","720"]}'::jsonb, 'The Whistleblower Act, 2006 (Act 720) provides a framework for disclosure of wrongdoing and protection against victimisation in specified circumstances. Its procedures and scope should be checked before disclosing.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('dfb09015-3912-543e-9af8-18d195f38d69', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'ba80c4a7-403a-5227-90de-7ff87f4eafeb', 'csit-617/professional-practice/pp13', 'mcq', 'analyse', 'hard', 'Analyse the professional failures in Therac-25 and Horizon', 'Which common factor best links the Therac-25 accidents and the UK Post Office Horizon scandal?', null, null, '[{"id":"a","text":"Both were caused solely by external hackers"},{"id":"b","text":"In both, overconfidence in software and failure to take users'' reports of anomalies seriously contributed to serious harm"},{"id":"c","text":"Both involved open-source software licence breaches"},{"id":"d","text":"Both were resolved immediately after the first report"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('dfb09015-3912-543e-9af8-18d195f38d69', '{"option":"b"}'::jsonb, 'Therac-25 involved overconfidence in software and poor response to early incident reports; Horizon involved treating system outputs as reliable while sub-postmasters'' reports of discrepancies were disregarded. Neither was a hacking or licensing case, and neither was resolved quickly.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7dab0d7c-35a9-5a19-bfa4-69cad8274fcb', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'ba80c4a7-403a-5227-90de-7ff87f4eafeb', 'csit-617/professional-practice/pp14', 'mcq', 'evaluate', 'hard', 'Evaluate a criticism of De George''s criteria', 'Which is the strongest criticism of De George''s requirement to exhaust internal channels?', null, null, '[{"id":"a","text":"It makes whistleblowing too easy"},{"id":"b","text":"It may be dangerous or futile where senior management is complicit or evidence could be destroyed"},{"id":"c","text":"It ignores the importance of evidence"},{"id":"d","text":"It applies only to the public sector"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7dab0d7c-35a9-5a19-bfa4-69cad8274fcb', '{"option":"b"}'::jsonb, 'Critics note that internal escalation can expose the employee to retaliation or allow concealment when leadership is involved. The criteria are, if anything, demanding rather than easy, do require evidence (criterion 4), and were developed with corporate product-safety cases in mind.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('37c0301b-bd03-594e-a9a6-fca28ac7a77c', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'bbe606c5-0c94-52ca-951d-5d856ab8fa36', 'csit-617/professional-practice/pp15', 'matching', 'understand', 'easy', 'Classify forms of cybercrime', 'Match each example to its category.', null, null, '{"left":[{"id":"l1","text":"Deploying ransomware against a hospital network"},{"id":"l2","text":"Tricking customers into revealing mobile-money PINs by phone"},{"id":"l3","text":"A bank clerk selling customer records to fraudsters"},{"id":"l4","text":"Distributing child sexual abuse material online"}],"right":[{"id":"r4","text":"Content-related offence"},{"id":"r3","text":"Insider misuse"},{"id":"r1","text":"Cyber-dependent crime"},{"id":"r2","text":"Cyber-enabled crime"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('37c0301b-bd03-594e-a9a6-fca28ac7a77c', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'The classification helps match responses, technical defences for cyber-dependent attacks, awareness and process for cyber-enabled fraud, access controls for insiders and specialised enforcement for content offences.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2f9e07b6-d5d4-520a-a135-4f669ebb6bb9', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'bbe606c5-0c94-52ca-951d-5d856ab8fa36', 'csit-617/professional-practice/pp16', 'mcq', 'recall', 'easy', 'Identify the body established by the Cybersecurity Act, 2020', 'Which institution was established by Ghana''s Cybersecurity Act, 2020 (Act 1038)?', null, null, '[{"id":"a","text":"The Data Protection Commission"},{"id":"b","text":"The Cyber Security Authority"},{"id":"c","text":"The Copyright Office"},{"id":"d","text":"The National Communications Authority"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2f9e07b6-d5d4-520a-a135-4f669ebb6bb9', '{"option":"b"}'::jsonb, 'Act 1038 established the Cyber Security Authority as the regulator for cybersecurity. The Data Protection Commission was established under the Data Protection Act, 2012 (Act 843); the Copyright Office relates to copyright; the NCA regulates communications under separate legislation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0883bc4f-59b6-5bed-9e67-9a20585cb95d', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'bbe606c5-0c94-52ca-951d-5d856ab8fa36', 'csit-617/professional-practice/pp17', 'true_false', 'understand', 'medium', 'Recognise that Act 772 contains cyber offences', 'The Electronic Transactions Act, 2008 (Act 772) concerns only electronic signatures and contains no provisions on cyber offences.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0883bc4f-59b6-5bed-9e67-9a20585cb95d', '{"value":false}'::jsonb, 'Act 772 gives legal recognition to electronic records, signatures and contracts, addresses consumer protection in e-commerce, and also creates cyber offences such as those relating to unauthorised access, interception and interference.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('51d51368-9535-5c63-bc84-7b7145027fb5', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'bbe606c5-0c94-52ca-951d-5d856ab8fa36', 'csit-617/professional-practice/pp18', 'scenario', 'apply', 'medium', 'Apply ethical security-testing principles', 'What is the most ethical course of action?', 'A postgraduate student notices that a Ghanaian online shop''s website appears vulnerable to a common injection attack. Without asking permission, she wants to try extracting a few customer records to "prove" the flaw before reporting it.', null, '[{"id":"a","text":"Extract a few records, since her intentions are good"},{"id":"b","text":"Publish the vulnerability on social media to warn customers"},{"id":"c","text":"Not test further without authorisation, and report the suspected issue privately to the shop through any available disclosure channel"},{"id":"d","text":"Sell the information to a security firm"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('51d51368-9535-5c63-bc84-7b7145027fb5', '{"option":"c"}'::jsonb, 'Authorisation is the legal and ethical dividing line; unauthorised access is generally an offence regardless of intent, and ACM 2.8 requires authorised access. Coordinated, private disclosure allows a fix. Public posting exposes customers, and selling the flaw is clearly wrong.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('68349a9a-ca55-56b7-a1a8-781f35803336', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'bbe606c5-0c94-52ca-951d-5d856ab8fa36', 'csit-617/professional-practice/pp19', 'short_answer', 'recall', 'medium', 'Name the access-control principle that limits insider risk', 'What principle states that users should be granted only the access their role requires?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('68349a9a-ca55-56b7-a1a8-781f35803336', '{"answers":["least privilege","principle of least privilege","need to know"]}'::jsonb, 'Least privilege limits what any insider can misuse, intentionally or accidentally. It works with separation of duties, logging and prompt leaver processes.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1df57935-3a6b-5af7-9763-d0da792b7563', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'bbe606c5-0c94-52ca-951d-5d856ab8fa36', 'csit-617/professional-practice/pp20', 'mcq', 'analyse', 'hard', 'Analyse organisational responsibility for insider misuse', 'In the illustrative PrimeCash case, a customer-service officer leaked customer details used for SIM-swap fraud. Which analysis is most complete?', null, null, '[{"id":"a","text":"Only the officer is responsible, so dismissing her solves the problem"},{"id":"b","text":"The officer is responsible for misuse, but broad access, no monitoring of unusual queries and weak SIM-replacement checks are organisational failures that must also be fixed"},{"id":"c","text":"The telecoms partner alone is responsible"},{"id":"d","text":"No one is responsible because cybercrime is inevitable"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1df57935-3a6b-5af7-9763-d0da792b7563', '{"option":"b"}'::jsonb, 'Individual wrongdoing and organisational control failures both contributed. A complete response addresses accountability for the officer while fixing access, monitoring and verification weaknesses. Blaming only one party, or treating harm as inevitable, ignores preventable causes.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('810a6c9d-abbd-5548-9898-b951ce330603', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'bbe606c5-0c94-52ca-951d-5d856ab8fa36', 'csit-617/professional-practice/pp21', 'true_false', 'understand', 'medium', 'Interpret the Morrisons insider case', 'In WM Morrison Supermarkets v Various Claimants (2020), the UK Supreme Court held that Morrisons was not vicariously liable for an employee who deliberately leaked payroll data to pursue a personal vendetta.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('810a6c9d-abbd-5548-9898-b951ce330603', '{"value":true}'::jsonb, 'The Court found the employee was not acting in the course of employment in the relevant sense. The case nonetheless illustrates insider risk and the need for controls such as monitoring bulk data extraction.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a2001c11-6b91-5bf6-a079-21bc46d0c460', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', null, 'csit-617/professional-practice/pp22', 'case_analysis', 'evaluate', 'hard', 'Integrate conflicts of interest, whistleblowing and negligence in one analysis', 'Analyse the case and recommend what Yaw should do. Apply at least two ethical theories, De George''s criteria and the ACM Code, and consider possible negligence.', null, 'Illustrative scenario. Yaw is a systems engineer at "Coastal Water Utilities", a Ghanaian company serving several towns. The chief technology officer (CTO) awarded a contract for a new remote-monitoring system for water-treatment plants to a vendor in which the CTO holds an undeclared shareholding. Yaw discovers that the system ships with default administrator passwords that cannot be changed, and that it is exposed to the internet. He reports this to the CTO, who tells him the vendor will "patch it eventually" and warns him not to "make trouble". Yaw believes an attacker could alter chemical dosing levels.', null, 25, array['Facts and stakeholders', 'Conflict-of-interest analysis of the CTO''s conduct', 'Security and negligence analysis (duty, breach, causation, harm)', 'Whistleblowing analysis using De George''s criteria and their limitations', 'Ethical theories and ACM principles', 'Options, recommendation and counter-arguments']::text[], '[{"criterion":"Facts, stakeholders and conflict of interest","marks":5,"descriptor":"Identifies the undeclared shareholding as an actual conflict and its effect on decision quality; identifies residents, staff, regulators and the company as stakeholders."},{"criterion":"Negligence and security analysis","marks":5,"descriptor":"Applies all four elements of negligence accurately to the risk and notes critical infrastructure context."},{"criterion":"Whistleblowing analysis","marks":6,"descriptor":"Applies De George''s five criteria correctly, distinguishes permissibility from obligation and discusses limitations given the CTO''s involvement."},{"criterion":"Ethical theory and ACM Code","marks":5,"descriptor":"Uses two theories and principles such as 1.2, 1.3, 2.5, 2.9 and 3.7 accurately."},{"criterion":"Recommendation and counter-arguments","marks":4,"descriptor":"Gives a staged, practical recommendation and answers objections such as loyalty and job risk."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a2001c11-6b91-5bf6-a079-21bc46d0c460', '{}'::jsonb, 'Examiners look for integration of the three topics, accurate De George and negligence analysis, use of the critical infrastructure context and a staged, proportionate recommendation.', 'The CTO''s undeclared shareholding is an actual conflict of interest, breaching ACM 1.3; it may explain why a vendor with poor security was chosen and why the CTO resists action. Stakeholders include residents who depend on safe water, plant staff, the board, regulators and Yaw himself.

Unchangeable default passwords on an internet-exposed industrial control system fall well below accepted security practice, contrary to ACM 2.9 (robustly and usably secure systems) and 3.7 (special care for infrastructure systems). If an attacker altered chemical dosing and residents were harmed, a negligence claim could argue that the company and possibly the vendor owed a duty to consumers, breached it by deploying and retaining a known insecure configuration, caused the harm, and that personal injury is recognised damage. The plant may also be treated as critical information infrastructure under the Cybersecurity Act, 2020 (Act 1038), bringing regulatory obligations.

On De George''s criteria, the potential harm is serious and considerable (1) and Yaw has reported to his superior (2). Because the CTO is conflicted, Yaw should escalate in writing to the managing director, board or audit committee (3). If they fail to act, his technical evidence (4) and the likelihood that the regulator would intervene (5) would make external disclosure, to the Cyber Security Authority or another appropriate regulator rather than the media, obligatory. The limitation that internal escalation may be futile when leadership is implicated supports moving more quickly to the board.

Utilitarian reasoning strongly favours action because the expected harm to many people outweighs the costs to Yaw and the company; deontology supports refusing complicity and honesty to the public. Recommendation: document the vulnerability, propose immediate mitigations (network isolation, compensating controls), escalate to the board with a declaration of the conflict concern, seek advice on protections under the Whistleblower Act, 2006 (Act 720), and report to the regulator if the board does not act. Loyalty and job security are real concerns but cannot outweigh a credible threat to public health.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1e47fcc1-7509-5405-9a77-868830e70077', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'What is a conflict of interest?', 'A situation in which private interests, or duties to another party, could improperly influence a person''s professional judgement where others rely on it.', 'supplementary', 'csit-617/professional-practice/6807d688eb9d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bb62aced-e563-512f-8da6-d7e39e3cbf93', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'Why must perceived conflicts be disclosed even if judgement is unaffected?', 'Because a reasonable observer''s doubt undermines trust and the legitimacy of the decision; disclosure lets the organisation protect both the decision and the individual.', 'supplementary', 'csit-617/professional-practice/dbbd35dd94b2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('018157bc-2954-5746-90af-2ce47fed2add', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'List the steps of conflict-of-interest management.', 'Recognise, disclose in writing, let the organisation assess, manage (recuse, independent review, divest or decline), record and review when circumstances change.', 'supplementary', 'csit-617/professional-practice/c3fdddaa6ba1', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e9ef5901-2230-5782-8adf-a2eaeed0ea12', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'What is the test for whether a gift from a vendor is acceptable?', 'Whether it could influence, or appear to influence, a business decision, considering timing (e.g. during a tender), value, openness and organisational policy.', 'supplementary', 'csit-617/professional-practice/a7631591a425', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ded2edbb-4ea6-5d91-8ce7-367487bbdea7', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'What limits loyalty to an employer?', 'Law and duties to the public. An employer cannot legitimately require deception of clients or regulators, concealment of serious defects or unlawful acts.', 'supplementary', 'csit-617/professional-practice/3c360b2b20bb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8e1b9577-dfe7-5113-8659-0706d0105967', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', '90107044-1a09-504a-8716-b5f420b4aebf', 'What is the ethical rule for privileged access?', 'Access is granted for a purpose and must be used only for that purpose (ACM 2.8); technical ability to view data is not permission.', 'supplementary', 'csit-617/professional-practice/d9ceee9930b7', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('45368418-eebb-5594-a156-6514551051f6', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'ba80c4a7-403a-5227-90de-7ff87f4eafeb', 'State De George''s three criteria for permissible whistleblowing.', '(1) Serious and considerable harm to the public; (2) the employee has reported it to an immediate superior; (3) internal procedures have been exhausted.', 'supplementary', 'csit-617/professional-practice/dc39bb699850', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('80155047-09ad-53ec-a31e-e5b441019a27', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'ba80c4a7-403a-5227-90de-7ff87f4eafeb', 'What two further criteria make whistleblowing obligatory for De George?', '(4) Documented evidence that would convince a reasonable impartial observer; (5) good reason to believe that going public will bring about the necessary change.', 'supplementary', 'csit-617/professional-practice/b1a660c888c7', true)
