insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('81ef9152-14d0-54b5-89ef-38584e8459b1', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'ba80c4a7-403a-5227-90de-7ff87f4eafeb', 'Give two criticisms of De George''s criteria.', 'Exhausting internal channels can be unsafe or futile when management is complicit; the focus on physical public harm is narrow for privacy, fraud or discrimination concerns.', 'supplementary', 'csit-617/professional-practice/fbcbc5afc4f6', true)
