insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f6c6b32d-550a-528d-8cec-5b9d3f5c95c6', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '4d856c6d-28d2-5fe7-b147-8a28d8e6d037', 'ba80c4a7-403a-5227-90de-7ff87f4eafeb', 'What are the four elements of negligence?', 'Duty of care, breach of the standard of a reasonably competent professional, causation, and recognised harm.', 'supplementary', 'csit-617/professional-practice/6bfd1bc12cfc', true)
