insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'it-governance-and-technology-law', 'IT Governance and Technology Law', 'How organisations govern information technology, and the legal framework that technology professionals work within.', 8, true)
