insert into public.question_keys (question_id, correct, explanation, model_answer) values ('16f12ba4-03d4-5f2e-8c50-4b34d71637c5', '{"value":false}'::jsonb, 'COBIT is a reference framework published by ISACA. Organisations may adopt it wholly, partly or alongside other frameworks. It is not legislation, and the lesson stresses that it should be tailored rather than treated as a certification.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('fda72cd9-7332-5aea-a01b-d2c515c07d8e', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8355d865-9e90-5676-b4e1-1f59bf1939ec', 'csit-617/it-governance-and-technology-law/gl04', 'short_answer', 'recall', 'easy', 'Recall the ISO/IEC 38500 governance cycle', 'Complete the ISO/IEC 38500 cycle: Evaluate, Direct, ______.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('fda72cd9-7332-5aea-a01b-d2c515c07d8e', '{"answers":["Monitor","monitoring"]}'::jsonb, 'The three governance tasks are Evaluate, Direct and Monitor. Monitoring closes the loop by checking conformance and performance, which feeds the next round of evaluation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('67a8da83-689c-5a94-ae83-ed37536120bb', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8355d865-9e90-5676-b4e1-1f59bf1939ec', 'csit-617/it-governance-and-technology-law/gl05', 'scenario', 'apply', 'medium', 'Apply governance concepts to a failing project', 'Which governance weakness is most clearly shown?', 'Illustrative scenario. A Ghanaian insurance company launches a claims app. The IT manager chose the vendor and signed off the budget alone. Nine months later the app works technically but few claims are filed through it, and the board only learns of low usage from an external auditor.', null, '[{"id":"a","text":"No benefit owner, business case review or regular monitoring linked the investment to business outcomes"},{"id":"b","text":"The vendor used the wrong programming language"},{"id":"c","text":"The app was insufficiently encrypted"},{"id":"d","text":"The board interfered too much in daily operations"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('67a8da83-689c-5a94-ae83-ed37536120bb', '{"option":"a"}'::jsonb, 'The project is technically complete but delivers little value, and the board lacked reporting. That signals failures of responsibility, strategy and monitoring. Nothing in the scenario points to encryption or language problems, and the board''s problem was too little oversight, not too much.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d34506ea-4f0e-5799-a78c-553a93e0891c', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8355d865-9e90-5676-b4e1-1f59bf1939ec', 'csit-617/it-governance-and-technology-law/gl06', 'mcq', 'analyse', 'medium', 'Analyse why a steering committee may fail', 'A steering committee approves every IT proposal without questions and members send junior delegates. What does this most likely indicate?', null, null, '[{"id":"a","text":"Excellent governance because decisions are fast"},{"id":"b","text":"The committee lacks authority, engagement and evidence, so accountability is diffused"},{"id":"c","text":"That COBIT has been fully implemented"},{"id":"d","text":"That decision rights are perfectly clear"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d34506ea-4f0e-5799-a78c-553a93e0891c', '{"option":"b"}'::jsonb, 'Rubber-stamping and absent decision makers are classic signs of a ritual committee. Speed is not evidence of quality, and clear decision rights would mean empowered members who challenge proposals.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d0b30606-a223-5b51-8e59-38b099eba2d8', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8355d865-9e90-5676-b4e1-1f59bf1939ec', 'csit-617/it-governance-and-technology-law/gl07', 'mcq', 'evaluate', 'hard', 'Evaluate the claim that technology risk is enterprise risk', 'Which argument best supports the claim that technology risk is enterprise risk?', null, null, '[{"id":"a","text":"IT staff are more numerous than other staff"},{"id":"b","text":"A failure in a core system, such as unintended trading orders, can threaten the survival of the whole organisation"},{"id":"c","text":"Technology budgets are always the largest budget"},{"id":"d","text":"Boards usually have technical members"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d0b30606-a223-5b51-8e59-38b099eba2d8', '{"option":"b"}'::jsonb, 'The Knight Capital incident shows how a deployment failure produced losses large enough to endanger the firm. The other options are either untrue as general claims or irrelevant to the nature of the risk.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3373a4e0-d6cb-594b-8909-ed9d0b920803', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8355d865-9e90-5676-b4e1-1f59bf1939ec', 'csit-617/it-governance-and-technology-law/gl08', 'true_false', 'understand', 'medium', 'Explain tailoring in COBIT', 'COBIT expects the same set of objectives and the same level of maturity to be applied to every organisation regardless of size or risk profile.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3373a4e0-d6cb-594b-8909-ed9d0b920803', '{"value":false}'::jsonb, 'COBIT uses design factors such as size, risk profile and compliance needs to tailor the governance system. A microfinance institution and a universal bank would prioritise differently.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3dc113a5-79c1-588d-8c9a-62342409c712', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8355d865-9e90-5676-b4e1-1f59bf1939ec', 'csit-617/it-governance-and-technology-law/gl09', 'scenario', 'analyse', 'hard', 'Link governance failure to professional ethics', 'Which analysis best connects governance and professional ethics?', 'Illustrative scenario. A systems engineer at a Ghanaian bank warns in writing that a planned release lacks a rollback plan. The change manager says the board wants the launch this week and tells her not to put concerns in writing. The release proceeds and causes a day-long outage.', null, '[{"id":"a","text":"The engineer carries no duty because governance belongs to the board"},{"id":"b","text":"Weak decision rights and escalation channels undermined governance, and the engineer''s duties of competence and honesty (for example ACM principles 2.2 and 1.3) support escalating the concern through legitimate channels"},{"id":"c","text":"Only the vendor is responsible"},{"id":"d","text":"The outage proves that written warnings should be avoided"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3dc113a5-79c1-588d-8c9a-62342409c712', '{"option":"b"}'::jsonb, 'Governance should provide escalation routes and protect honest risk reporting. Professional codes ask practitioners to be competent and honest about risks. The engineer is not the only responsible party, but she is not free of duty either, and discouraging written warnings is a governance failure.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f61e31dc-e0fa-53f9-934a-5b70693a1776', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8e8685ee-dfda-58af-a012-8c69a523592c', 'csit-617/it-governance-and-technology-law/gl10', 'matching', 'recall', 'easy', 'Match Ghanaian statutes to their subjects', 'Match each Ghanaian statute to its main subject.', null, null, '{"left":[{"id":"l1","text":"Electronic Transactions Act, 2008 (Act 772)"},{"id":"l2","text":"Data Protection Act, 2012 (Act 843)"},{"id":"l3","text":"Cybersecurity Act, 2020 (Act 1038)"},{"id":"l4","text":"Copyright Act, 2005 (Act 690)"}],"right":[{"id":"r1","text":"Legal recognition of electronic records, signatures and contracts"},{"id":"r3","text":"Cybersecurity regulation and critical information infrastructure"},{"id":"r4","text":"Protection of original works including computer programs"},{"id":"r2","text":"Processing of personal data"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f61e31dc-e0fa-53f9-934a-5b70693a1776', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Each Act has a distinct focus. Confusing them is a common examination error, so linking the statute number, name and subject is worth practising.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d16b4e6e-6de9-5165-a42a-7ffff1bf375f', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8e8685ee-dfda-58af-a012-8c69a523592c', 'csit-617/it-governance-and-technology-law/gl11', 'true_false', 'understand', 'easy', 'Understand the relationship between law and ethics', 'If a practice complies with the law, a professional has no further ethical questions to consider.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d16b4e6e-6de9-5165-a42a-7ffff1bf375f', '{"value":false}'::jsonb, 'Law provides a minimum standard. A practice can be lawful and still be disproportionate, unfair or disrespectful of users, and professional codes such as the ACM Code ask for more than legal compliance.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5d46618f-27ec-5078-8b47-cd30d4457244', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8e8685ee-dfda-58af-a012-8c69a523592c', 'csit-617/it-governance-and-technology-law/gl12', 'short_answer', 'recall', 'easy', 'Recall the data protection regulator', 'Which Ghanaian body supervises compliance with the Data Protection Act, 2012?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5d46618f-27ec-5078-8b47-cd30d4457244', '{"answers":["Data Protection Commission","The Data Protection Commission"]}'::jsonb, 'Act 843 established the Data Protection Commission. The Cyber Security Authority regulates cybersecurity under Act 1038, and the National Communications Authority is the communications sector regulator.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f4c419bf-3c1a-52e9-a3d1-94da5a8879d4', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8e8685ee-dfda-58af-a012-8c69a523592c', 'csit-617/it-governance-and-technology-law/gl13', 'mcq', 'apply', 'medium', 'Apply Act 772 reasoning to system design', 'A fintech builds an online loan agreement. Which design choice best supports the reliability of the electronic records?', null, null, '[{"id":"a","text":"Storing agreements as editable text files on a shared drive"},{"id":"b","text":"Capturing authenticated acceptance with timestamps and an audit trail, and protecting records from alteration"},{"id":"c","text":"Relying on verbal confirmation from the customer"},{"id":"d","text":"Deleting acceptance logs after one week to save space"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f4c419bf-3c1a-52e9-a3d1-94da5a8879d4', '{"option":"b"}'::jsonb, 'Electronic records are only valuable as evidence if they can be attributed to a person, dated, protected from change and retrieved. Editable files, undocumented verbal consent and deleting logs all weaken reliability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c009a850-4aa3-5078-9883-f228c51a55ff', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8e8685ee-dfda-58af-a012-8c69a523592c', 'csit-617/it-governance-and-technology-law/gl14', 'scenario', 'apply', 'medium', 'Apply the compliance method to a vendor decision', 'What is the best response?', 'Illustrative scenario. A Ghanaian health-records start-up wants to host patient data with a cloud provider whose servers are outside Ghana. The founder says this removes the start-up''s data protection duties because the provider will hold the data.', null, '[{"id":"a","text":"Agree, because the provider becomes the only responsible party"},{"id":"b","text":"The start-up usually remains responsible for the data it controls, so it should assess the transfer, sign a processing contract with security and breach terms, and take legal advice"},{"id":"c","text":"Ignore data protection law until a complaint is received"},{"id":"d","text":"Store the data in plain text so that the provider can handle compliance"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c009a850-4aa3-5078-9883-f228c51a55ff', '{"option":"b"}'::jsonb, 'Outsourcing hosting does not normally remove a controller''s responsibility. A structured approach looks at the transfer, contract terms and safeguards. Health data are sensitive, so specialist legal advice is prudent.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d5aed3a0-5e77-5472-a436-98075d61db11', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8e8685ee-dfda-58af-a012-8c69a523592c', 'csit-617/it-governance-and-technology-law/gl15', 'mcq', 'analyse', 'medium', 'Analyse the effect of the GDPR on a non-EU company', 'Why might the EU GDPR matter to a Ghanaian online retailer without any European office?', null, null, '[{"id":"a","text":"It never applies outside Europe"},{"id":"b","text":"It can apply where the retailer offers goods or services to people in the EU or monitors their behaviour"},{"id":"c","text":"It applies only to banks"},{"id":"d","text":"It replaces Ghana''s own data protection law"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d5aed3a0-5e77-5472-a436-98075d61db11', '{"option":"b"}'::jsonb, 'The GDPR has extraterritorial reach in defined circumstances such as targeting people in the EU. It does not replace Ghanaian law, and it is not limited to banks.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('78234f08-7d9f-56e1-8b27-9c71efba718a', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8e8685ee-dfda-58af-a012-8c69a523592c', 'csit-617/it-governance-and-technology-law/gl16', 'short_answer', 'recall', 'medium', 'Recall the Budapest Convention', 'By what common short name is the Council of Europe Convention on Cybercrime known?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('78234f08-7d9f-56e1-8b27-9c71efba718a', '{"answers":["Budapest Convention","The Budapest Convention"]}'::jsonb, 'It is called the Budapest Convention because it was opened for signature in Budapest. Ghana has acceded to it, and it promotes harmonised offences and cross-border cooperation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5737cd7a-c7c7-593d-8274-d2e3b809e2b1', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8e8685ee-dfda-58af-a012-8c69a523592c', 'csit-617/it-governance-and-technology-law/gl17', 'mcq', 'evaluate', 'hard', 'Evaluate the lessons of Schrems II', 'Which conclusion about Schrems II is best supported by the lesson?', null, null, '[{"id":"a","text":"Cross-border transfer tools are permanent once adopted"},{"id":"b","text":"Contracts alone may be insufficient, and the legal environment of the destination country and technical safeguards must be assessed"},{"id":"c","text":"Data location has no legal significance"},{"id":"d","text":"Only US companies are affected by data transfer rules"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5737cd7a-c7c7-593d-8274-d2e3b809e2b1', '{"option":"b"}'::jsonb, 'The Court invalidated the Privacy Shield and required case-by-case checks when relying on standard contractual clauses. The case shows that legal positions can change and that location, contracts and technical safeguards interact.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('19511277-b3fb-5fd2-83bf-0354e6107353', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8e8685ee-dfda-58af-a012-8c69a523592c', 'csit-617/it-governance-and-technology-law/gl18', 'true_false', 'apply', 'medium', 'Apply copyright rules to freelance work', 'A freelance developer who writes code for a client without any written agreement on ownership has removed all risk of a later ownership dispute.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('19511277-b3fb-5fd2-83bf-0354e6107353', '{"value":false}'::jsonb, 'A missing agreement creates uncertainty, and disputes are more likely. Contractors and clients should state ownership and licensing terms in writing, and the exact legal position depends on the contract and the Copyright Act.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('799eddb9-d1ff-5619-8a39-209a44bfae18', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', null, 'csit-617/it-governance-and-technology-law/gl19', 'essay', 'evaluate', 'hard', 'Evaluate the interaction of governance, law and professional ethics', '"Legal compliance and good governance are enough to ensure that IT professionals behave ethically." Critically evaluate this statement with reference to ISO/IEC 38500, COBIT, the Ghanaian technology statutes and the ACM Code of Ethics.', null, null, null, 20, array['Introduction and thesis', 'Governance structures and what they achieve (accountability, decision rights, monitoring)', 'The role and limits of the law (Acts 772, 843, 1038, 775 and 690 as minimum standards)', 'What professional ethics adds (proportionality, honesty, whistleblowing, harm avoidance)', 'A brief illustrative example showing a lawful but ethically doubtful practice', 'Conclusion']::text[], '[{"criterion":"Governance analysis","marks":5,"descriptor":"Accurately explains governance versus management, ISO/IEC 38500 principles or COBIT concepts and how they create accountability."},{"criterion":"Legal analysis","marks":5,"descriptor":"Accurately identifies relevant Ghanaian statutes and explains law as a minimum standard without inventing section numbers or penalties."},{"criterion":"Ethical analysis","marks":5,"descriptor":"Uses ACM principles or ethical theories to show what compliance and governance leave out."},{"criterion":"Argument and evaluation","marks":5,"descriptor":"Offers a clear, balanced thesis, uses an example, considers counter-arguments and reaches a justified conclusion."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('799eddb9-d1ff-5619-8a39-209a44bfae18', '{}'::jsonb, 'Examiners look for a clear thesis, accurate use of frameworks and statutes, and evidence of evaluation rather than description. Strong answers show that governance and law are necessary but not sufficient.', 'A strong answer argues that compliance and governance are necessary but not sufficient. It begins by defining governance as the board''s evaluation, direction and monitoring of IT, with management delivering within that direction. ISO/IEC 38500 and COBIT make accountability visible through clear responsibilities, decision rights, risk appetite and performance reporting. These structures reduce the chance that harmful decisions are made unnoticed.

The answer then explains that Ghanaian statutes such as the Data Protection Act, 2012 (Act 843), the Cybersecurity Act, 2020 (Act 1038), the Electronic Transactions Act, 2008 (Act 772), the Electronic Communications Act, 2008 (Act 775) and the Copyright Act, 2005 (Act 690) set minimum standards enforced by regulators. They cannot anticipate every technology or context, and enforcement and interpretation vary.

Ethics fills the gaps. An organisation might lawfully collect more personal data than it needs, or monitor staff in ways that are technically permitted but disproportionate. ACM principles on honesty, avoiding harm and respecting privacy ask professionals to question such practices and to raise concerns through proper channels. Governance can support this by giving escalation routes, but it cannot create integrity by itself, and a committee can approve harmful proposals.

The conclusion should weigh these points and state that compliance is a floor, governance is an enabling structure and professional judgement is what remains when rules run out.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b504f19a-f4e7-5f25-80ca-c3b2cca62100', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', null, 'csit-617/it-governance-and-technology-law/gl20', 'case_analysis', 'evaluate', 'hard', 'Integrate governance, technology law and ethics in a case', 'Analyse the case. Identify governance failures, the legal frameworks likely to be engaged, the ethical issues and your recommended actions for the organisation and for Kojo.', null, 'Illustrative scenario. "Akwaaba Pay", a hypothetical Ghanaian mobile-payments company, is preparing to expand to customers in the European Union. The chief executive approves a plan to move all customer records to a cloud provider abroad and to launch a feature that scores customers'' creditworthiness using their phone contacts and location history. The IT steering committee has not met for a year. Kojo, a senior developer, notices that the contact data of non-customers will be processed, that there is no breach-response plan and that the company has never checked whether it needs to register with a regulator. His manager says that the launch date is fixed and legal questions can wait until after launch.', null, 25, array['Facts and stakeholders', 'Governance analysis (ISO/IEC 38500 principles, decision rights, steering committee, monitoring)', 'Legal analysis (Acts 843, 772, 1038 and 775 as relevant, and foreign rules such as the GDPR)', 'Ethical analysis (proportionality, consent, harm to non-customers, ACM principles)', 'Options for Kojo and for the company', 'Recommendation and counter-arguments']::text[], '[{"criterion":"Facts and stakeholders","marks":3,"descriptor":"Identifies customers, non-customers whose contacts are processed, staff, regulators and the company."},{"criterion":"Governance analysis","marks":6,"descriptor":"Applies several ISO/IEC 38500 principles accurately, notes the dormant steering committee and missing accountability and monitoring."},{"criterion":"Legal analysis","marks":6,"descriptor":"Identifies relevant Ghanaian statutes and cross-border issues at an appropriate general level, avoids invented provisions and notes the need for legal advice."},{"criterion":"Ethical analysis","marks":5,"descriptor":"Applies at least one ethical theory and relevant ACM principles to data minimisation, consent and harm."},{"criterion":"Recommendation and counter-arguments","marks":5,"descriptor":"Provides a staged, practical recommendation including escalation by Kojo, a compliance review and delayed launch if necessary, and answers objections about commercial pressure."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b504f19a-f4e7-5f25-80ca-c3b2cca62100', '{}'::jsonb, 'Examiners look for integration of the three lenses, accurate and cautious use of legal material and a practical, staged recommendation rather than a list of laws.', 'A good answer begins by identifying stakeholders, notably non-customers whose contacts would be processed without their involvement. On governance, there is no evidence of clear responsibility, a business case, a risk assessment or monitoring: the steering committee has been dormant, so evaluation and direction are weak, and the pressure to launch before legal questions are answered shows the conformance principle being ignored.

On law, the answer should state that Act 843 is engaged by the processing of personal data, including contact data, and that registration and security duties should be checked with the Data Protection Commission. Act 772 is relevant to electronic agreements with customers, Act 1038 to security and incident reporting expectations, and Act 775 and the communications regime where telecom services are used. Moving data abroad and serving EU customers raises cross-border questions, and the GDPR may apply. The answer should be framed as identifying issues for legal advice, not as definitive rulings.

Ethically, using non-customers'' contacts is hard to justify on grounds of consent and proportionality, and ACM principles on avoiding harm and respecting privacy are directly engaged.

Kojo should document his concerns, raise them with his manager and then through the compliance function, legal counsel or the board, and escalate further if ignored. The company should convene the steering committee, perform a legal and privacy impact review, redesign the scoring feature to avoid contact data and delay the launch if needed.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('421650e1-b3fa-5579-9eae-769b8e3cdd53', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8355d865-9e90-5676-b4e1-1f59bf1939ec', 'What is the difference between IT governance and IT management?', 'Governance evaluates, directs and monitors the use of IT (board and executives); management plans, builds, runs and monitors IT within that direction.', 'supplementary', 'csit-617/it-governance-and-technology-law/92e6f82968a2', true)
