insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2a1a21c8-08b5-51ef-8a63-63ddc1c20465', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8355d865-9e90-5676-b4e1-1f59bf1939ec', 'Why is "technology risk is enterprise risk" a governance statement?', 'Failures in core systems, as in the Knight Capital incident, can threaten the whole organisation, so the board remains accountable for oversight.', 'supplementary', 'csit-617/it-governance-and-technology-law/15f2d20b9de8', true)
