insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('699dd8c7-aa2a-5177-9820-ae1763ff185d', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', '8355d865-9e90-5676-b4e1-1f59bf1939ec', 'Why should governance measure outcomes rather than activity?', 'Counting tickets closed or projects delivered says little about whether the business benefits; outcome measures show whether value was actually realised.', 'supplementary', 'csit-617/it-governance-and-technology-law/926fba140430', true)
