insert into public.quizzes (id, external_ref, kind, title, description, instructions, course_id, module_id, lesson_id, scope_course_ids, question_count, open_ended_count, time_limit_minutes, randomize, reveal_answers, is_published, sort_order) values ('bd24398b-2943-5352-bf16-d0b41083731d', 'csit-617/it-governance-and-technology-law/assessment', 'module_assessment', 'Module assessment: IT Governance and Technology Law', 'A timed assessment covering every lesson in "IT Governance and Technology Law".', '18 objective questions and one extended-response question. You have 35 minutes. The objective section is scored automatically; the extended response is self-assessed against a rubric. All questions are supplementary practice questions generated for GradPath. They are not official University of Ghana examination questions, and results are not official grades.', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', '8fddba73-f3ea-5c2e-bd48-c6bfb323ffed', null, '{}'::uuid[], 18, 1, 35, true, 'after_submit', true, 8)
