insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('f787f8b9-cff1-5800-8815-397b649a43f3', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'ethical-case-studies', 'Ethical Case Studies', 'Applying structured ethical reasoning to realistic dilemmas.', 9, true)
