insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d2518717-9c02-5e13-a4a4-3700314ea5ea', '{"answers":["shadow AI","shadow artificial intelligence"]}'::jsonb, 'Shadow AI, like shadow IT, arises when staff adopt tools faster than organisations provide guidance, creating confidentiality, accuracy and accountability risks.', null)
