insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9b5b3c2b-7fb5-5d82-9d8d-e23bbfaf8749', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', 'f8048184-d669-541f-ab3c-6f2d67195eee', 'csit-617/ethical-case-studies/cs19', 'matching', 'analyse', 'medium', 'Match ethical frameworks to their use in the digital exclusion case', 'Match each framework to the question it asks about the app-only market permit system.', null, null, '{"left":[{"id":"l1","text":"Rawlsian justice"},{"id":"l2","text":"Capability approach"},{"id":"l3","text":"Utilitarianism"},{"id":"l4","text":"ACM principle 3.7"}],"right":[{"id":"r2","text":"Do traders have real freedom to use the service, not just formal access?"},{"id":"r4","text":"Is special care taken with a system integrated into public infrastructure?"},{"id":"r1","text":"Does the policy benefit the least advantaged traders?"},{"id":"r3","text":"Do the overall benefits outweigh the harms concentrated on excluded traders?"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
