insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9c74fa9b-ee39-518a-88cb-ffcabe647183', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', 'f8048184-d669-541f-ab3c-6f2d67195eee', 'csit-617/ethical-case-studies/cs20', 'true_false', 'understand', 'medium', 'Understand that digital availability is not access', 'Making a public service available through an app means it is accessible to all citizens.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
