insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9c74fa9b-ee39-518a-88cb-ffcabe647183', '{"value":false}'::jsonb, 'Cost, devices, connectivity, literacy, language and disability can all prevent effective use. Inclusive design requires assisted and alternative channels and accessibility testing.', null)
