insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('921f49ab-56ca-55c4-9f8a-418d00a3a633', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', 'f8048184-d669-541f-ab3c-6f2d67195eee', 'csit-617/ethical-case-studies/cs21', 'mcq', 'analyse', 'hard', 'Identify the common theme across the three cases', 'Which theme is common to the piracy, shadow AI and digital exclusion cases?', null, null, '[{"id":"a","text":"All three are caused only by individual wrongdoing"},{"id":"b","text":"Individual choices or design decisions are shaped by organisational gaps, so responses must fix policies and design as well as individual behaviour"},{"id":"c","text":"All three are solved by banning technology"},{"id":"d","text":"None involves the ACM Code"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('921f49ab-56ca-55c4-9f8a-418d00a3a633', '{"option":"b"}'::jsonb, 'In each case a missing policy, budget plan or inclusive design requirement enabled the harm. Purely individual blame or bans miss the root cause, and the ACM Code applies throughout.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a2ab012e-15e9-5775-9909-1645fb74a103', 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', null, 'csit-617/ethical-case-studies/cs22', 'case_analysis', 'evaluate', 'hard', 'Produce a complete seven-step case analysis', 'Using the seven-step case method, analyse the case and recommend what the company should do. Apply at least two ethical theories and the ACM Code.', null, 'Illustrative scenario. "Afia Retail", a Ghanaian e-commerce company, introduces an AI system that predicts which customers are likely to return goods and automatically restricts their access to "pay on delivery". The model uses purchase history, delivery location and phone type. Customers in certain low-income districts and those using older phones are restricted far more often. Customer-service staff have begun pasting complaint emails, with customer names and addresses, into a public chatbot to draft replies. A data analyst who raised concerns about the model was told that "the numbers speak for themselves".', null, 30, array['Facts, separating known facts from assumptions', 'Stakeholders and their interests', 'Ethical issues (bias and exclusion, transparency, shadow AI and confidentiality, treatment of the analyst)', 'Analysis using at least two ethical theories and ACM principles', 'Options', 'Recommendation with implementation steps', 'Counter-arguments and responses']::text[], '[{"criterion":"Facts and stakeholders","marks":5,"descriptor":"Accurately states facts, notes uncertainties and identifies customers, staff, the analyst, the company and regulators."},{"criterion":"Ethical issues","marks":6,"descriptor":"Identifies proxy discrimination via location and phone type, digital exclusion, lack of transparency and appeal, shadow AI data leakage and suppression of internal concerns."},{"criterion":"Theory and ACM analysis","marks":8,"descriptor":"Applies two theories correctly to the facts and cites relevant principles such as 1.4, 1.6, 1.7, 2.5 and 3.4."},{"criterion":"Options and recommendation","marks":7,"descriptor":"Compares realistic options and gives a staged, practical recommendation."},{"criterion":"Counter-arguments","marks":4,"descriptor":"Addresses at least two strong objections persuasively."}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a2ab012e-15e9-5775-9909-1645fb74a103', '{}'::jsonb, 'Examiners reward complete use of the seven-step method, recognition of both AI bias and shadow-AI issues, accurate theory application and a staged, practical recommendation that answers objections.', 'Facts: the model restricts payment options automatically; restrictions fall disproportionately on low-income districts and older-phone users; staff share personal data with a public chatbot; an analyst''s concern was dismissed. Unknown: whether the model''s predictions are accurate for these groups and what the chatbot provider does with inputs.

Stakeholders include affected customers (many of whom may lack cards or trust in online payment, so pay on delivery is their main route to e-commerce), other customers, customer-service staff, the analyst, the company and the Data Protection Commission.

Issues: delivery location and phone type act as proxies for income, producing indirect discrimination and digital exclusion; customers receive no explanation or appeal; the automated decision lacks human oversight; pasting complaint emails into a public chatbot discloses personal data without safeguards, raising issues under Act 843; and dismissing the analyst discourages internal challenge.

A utilitarian analysis weighs reduced return costs against lost sales, exclusion of poorer customers and reputational and regulatory risk, and notes that the model''s accuracy for the affected groups is unverified. A Rawlsian analysis condemns a rule that burdens the least advantaged without justification; a Kantian analysis objects to judging individuals by group correlates without explanation. ACM 1.4, 2.5, 1.6, 1.7 and 3.4 apply.

Options: continue; abandon the model; keep it with safeguards. Recommendation: suspend automatic restrictions; audit outcomes by district and device; remove or justify proxy features; use the model only to trigger human review or alternative assurances (such as confirmation calls); give customers reasons and an appeal route; stop pasting personal data into public tools and provide an approved tool and policy; and formally invite the analyst to lead the audit. Counter-arguments, that "the numbers speak for themselves" and that returns are costly, are answered by showing that unvalidated proxies are not neutral numbers and that safeguards can control returns without blanket exclusion.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8a60777b-1564-51e9-87c2-e1c3b65d5865', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '94dcd280-810b-59ac-a8b9-4212f813b5e9', 'What are the seven steps of the case analysis method?', 'Facts, stakeholders, ethical issues, analysis through theories and the ACM Code, options, recommendation, counter-arguments.', 'supplementary', 'csit-617/ethical-case-studies/1c607059d700', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('413e5130-eabe-589a-b32c-f0ba2efad98b', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '94dcd280-810b-59ac-a8b9-4212f813b5e9', 'What does the Amazon recruiting tool case (Reuters, 2018) illustrate?', 'Historical bias, a model trained on male-dominated CVs learned to favour men and penalise terms like "women''s"; patching terms gave no guarantee of fairness, and the tool was abandoned.', 'supplementary', 'csit-617/ethical-case-studies/ea7c16783e91', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('007e195f-9b32-5971-a94e-b651204fce98', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '94dcd280-810b-59ac-a8b9-4212f813b5e9', 'Why is validity an ethical issue in AI recruitment?', 'If features such as facial expressions or accents do not predict job performance, using them excludes people for irrelevant reasons while appearing objective.', 'supplementary', 'csit-617/ethical-case-studies/0f6b25ecf515', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('347dab6a-ff58-5070-80a7-d5c3ab64bd5a', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '94dcd280-810b-59ac-a8b9-4212f813b5e9', 'Why is employee consent a weak justification for intrusive monitoring?', 'The power imbalance in employment means consent is rarely free, and consent does not make a disproportionate intrusion necessary or fair.', 'supplementary', 'csit-617/ethical-case-studies/6620dd21a9e6', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9f4b0546-cfe4-55bb-a6ff-c7ba02a9559d', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '94dcd280-810b-59ac-a8b9-4212f813b5e9', 'What principles does Bărbulescu v Romania (2017) illustrate for workplace monitoring?', 'Employees should have prior notice of the nature and extent of monitoring, and monitoring needs legitimate reasons, proportionality and safeguards.', 'supplementary', 'csit-617/ethical-case-studies/2dc67d23a52e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9d986e5c-f3b6-5cbd-bab1-7a5e01bd5bc2', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '94dcd280-810b-59ac-a8b9-4212f813b5e9', 'What is function creep in employee monitoring?', 'Using data collected for one purpose, such as quality assurance, for other purposes, such as disciplining staff over private messages.', 'supplementary', 'csit-617/ethical-case-studies/20543df3cc4b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('cf9475d1-8ea4-5307-b9d2-461e22ccca65', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '6176f9fd-5ddc-58cb-b0a6-ca64239447ec', 'How does data misuse differ from a data breach?', 'Misuse is deliberate use beyond legitimate purposes or expectations; a breach is a security failure that allows unauthorised access, disclosure or loss.', 'supplementary', 'csit-617/ethical-case-studies/ac68bde81429', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d884220d-8f2b-5789-b183-e0e76c1ed49a', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '6176f9fd-5ddc-58cb-b0a6-ca64239447ec', 'What made the Cambridge Analytica case ethically distinctive?', 'A quiz app installed by relatively few users harvested data about their friends, so millions of people who never consented were affected and profiled.', 'supplementary', 'csit-617/ethical-case-studies/9de984d56c86', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0a2ae5f9-ae07-585d-986f-bd93a463040c', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '6176f9fd-5ddc-58cb-b0a6-ca64239447ec', 'What were the key failures in the 2017 Equifax breach?', 'A known Apache Struts vulnerability left unpatched, weak asset inventory and monitoring, and a delayed, poorly executed response to roughly 147 million affected people.', 'supplementary', 'csit-617/ethical-case-studies/8eb3c57f0354', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0cbdbecc-8a3a-5428-a921-33be0d44f444', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '6176f9fd-5ddc-58cb-b0a6-ca64239447ec', 'Why is "no proof of harm" not a reason to withhold breach notification?', 'Incomplete evidence is not proof of safety; affected people need information to protect themselves, and legal notification duties may apply.', 'supplementary', 'csit-617/ethical-case-studies/7a7c528179ea', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bdfe70cc-bcf8-5da3-a031-97f1c4da16ed', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '6176f9fd-5ddc-58cb-b0a6-ca64239447ec', 'Why should organisations avoid scapegoating individuals after a breach?', 'Breaches usually reflect missing organisational controls; blame discourages reporting, while blameless reviews fix root causes.', 'supplementary', 'csit-617/ethical-case-studies/0d247980f0e7', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0339b1ef-9d72-509a-9454-a0fa91adaf63', null, 'ebd2bdb9-0aee-5267-8b90-6a20cc7690c9', 'f787f8b9-cff1-5800-8815-397b649a43f3', '6176f9fd-5ddc-58cb-b0a6-ca64239447ec', 'When do "anonymised" data remain personal data?', 'When individuals can be re-identified, for example by combining the data with other sources.', 'supplementary', 'csit-617/ethical-case-studies/57004f8c6880', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
