insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('2736b42d-ecb0-5cf2-9fe7-9855045e2a29', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'cloud-and-edge-computing', 'Cloud and Edge Computing', 'Computing as a service, at the centre and at the edge.', 2, true)
