insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7d085387-1131-55ce-8ac8-d7b5307cd8a4', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '30a3ff96-2bff-5e20-be6b-e17ab8dcfd53', 'csit-621/cloud-and-edge-computing/q07', 'true_false', 'evaluate', 'medium', 'Evaluate currency risk in cloud business cases', 'For a Ghanaian company billed for cloud services in US dollars, converting capex to opex can increase its exposure to exchange-rate movements.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7d085387-1131-55ce-8ac8-d7b5307cd8a4', '{"value":true}'::jsonb, 'Recurring foreign-currency bills mean the local-currency cost changes with the exchange rate throughout the contract, whereas an upfront hardware purchase fixes most of the cost at one point. Business cases should include currency sensitivity analysis.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1a2dea55-b253-53dd-84e6-2ea80aca4816', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '471f3658-9ddb-54aa-a94a-239141cff8f4', 'csit-621/cloud-and-edge-computing/q08', 'mcq', 'understand', 'easy', 'Identify customer responsibilities in IaaS', 'In an IaaS model, which of the following is normally the customer''s responsibility?', null, null, '[{"id":"a","text":"Physical security of the data centre"},{"id":"b","text":"Patching the guest operating system"},{"id":"c","text":"Maintaining the virtualisation layer"},{"id":"d","text":"Replacing failed physical disks"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1a2dea55-b253-53dd-84e6-2ea80aca4816', '{"option":"b"}'::jsonb, 'In IaaS the provider manages facilities, hardware and virtualisation; the customer manages the operating system and everything above it, including patching. Neglecting this patching is a common cause of compromise.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9084ee1e-5ad5-5b2c-835d-2a5aca293343', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '471f3658-9ddb-54aa-a94a-239141cff8f4', 'csit-621/cloud-and-edge-computing/q09', 'matching', 'understand', 'medium', 'Match workloads to service models', 'Match each example to the service model it best illustrates.', null, null, '{"left":[{"id":"l1","text":"Renting virtual machines and installing your own database software"},{"id":"l2","text":"Deploying your own web application code onto a managed runtime"},{"id":"l3","text":"Subscribing to a hosted email and calendar suite"},{"id":"l4","text":"Running code only when a file is uploaded, billed per execution"}],"right":[{"id":"r4","text":"Serverless (Function as a Service)"},{"id":"r1","text":"IaaS"},{"id":"r3","text":"SaaS"},{"id":"r2","text":"PaaS"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9084ee1e-5ad5-5b2c-835d-2a5aca293343', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'The models differ by how much of the stack the customer controls. Serverless extends PaaS by removing server management entirely and billing per invocation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8d7d1b44-ee4b-5a6c-87ec-16f766fc8aa5', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '471f3658-9ddb-54aa-a94a-239141cff8f4', 'csit-621/cloud-and-edge-computing/q10', 'true_false', 'understand', 'easy', 'Explain the shared responsibility model for SaaS', 'When a company uses a SaaS application, the provider becomes fully responsible for who can access the company''s data.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
