insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8d7d1b44-ee4b-5a6c-87ec-16f766fc8aa5', '{"value":false}'::jsonb, 'Identity and access management and data remain customer responsibilities in every service model. The SaaS customer decides who has accounts, enforces multi-factor authentication and removes leavers.', null)
