insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7500d331-5525-5248-a225-8aa9615f7960', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '471f3658-9ddb-54aa-a94a-239141cff8f4', 'csit-621/cloud-and-edge-computing/q11', 'scenario', 'apply', 'medium', 'Apply the service-model selection heuristic', 'Which service model best fits the app''s back end?', 'A Ghanaian microfinance institution needs a customer-facing loan application app with features that differentiate it from competitors. It has a small development team but no infrastructure engineers, and it wants to release new features monthly.', null, '[{"id":"a","text":"IaaS, because it gives maximum control"},{"id":"b","text":"PaaS, because developers can focus on code while the provider manages runtimes and scaling"},{"id":"c","text":"SaaS, because it needs no development"},{"id":"d","text":"On-premises servers, because they avoid lock-in"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7500d331-5525-5248-a225-8aa9615f7960', '{"option":"b"}'::jsonb, 'A differentiated custom application with developers but no infrastructure engineers fits PaaS. IaaS would demand skills the institution lacks; SaaS cannot deliver a differentiated custom app; on-premises servers increase operational burden without addressing the need.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('158817fc-1e7a-5d53-938a-6f3b9bcaafe1', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '471f3658-9ddb-54aa-a94a-239141cff8f4', 'csit-621/cloud-and-edge-computing/q12', 'scenario', 'analyse', 'hard', 'Analyse the cause of a cloud security incident', 'Which conclusion is best supported?', 'A company running on IaaS suffers a data breach. Investigators find that a web application firewall the company configured was exploited to obtain credentials, and those credentials had permission to read every storage bucket in the account.', null, '[{"id":"a","text":"The provider''s physical data centre security failed"},{"id":"b","text":"The breach reflects failures on the customer side of the shared responsibility model, especially excessive permissions"},{"id":"c","text":"IaaS is inherently insecure and should never be used by banks"},{"id":"d","text":"The virtualisation layer was compromised"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('158817fc-1e7a-5d53-938a-6f3b9bcaafe1', '{"option":"b"}'::jsonb, 'The facts mirror the publicly reported Capital One case. Configuration and access permissions are customer responsibilities in IaaS. Least privilege would have limited the damage. Nothing indicates failure of provider-managed layers, and the incident does not show IaaS is inherently unusable.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('96cc52b1-2977-5e15-918d-08593655f854', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '471f3658-9ddb-54aa-a94a-239141cff8f4', 'csit-621/cloud-and-edge-computing/q13', 'short_answer', 'recall', 'medium', 'Recall the term for dependence on a provider''s proprietary services', 'What term describes dependence on a provider''s proprietary services or formats that makes switching costly?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('96cc52b1-2977-5e15-918d-08593655f854', '{"answers":["vendor lock-in","lock-in","lockin"]}'::jsonb, 'Vendor lock-in rises as organisations adopt proprietary platform features or store data in formats that are hard to export. Contracts should address data export and exit.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('87a59228-ef71-5a64-94e0-3fdb1e659f5b', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '471f3658-9ddb-54aa-a94a-239141cff8f4', 'csit-621/cloud-and-edge-computing/q14', 'mcq', 'evaluate', 'hard', 'Evaluate when serverless is cost-effective', 'For which workload is serverless computing most likely to be less cost-effective than a continuously running virtual machine?', null, null, '[{"id":"a","text":"Processing occasional document uploads at unpredictable times"},{"id":"b","text":"A nightly job that runs for a few minutes"},{"id":"c","text":"A constant, heavy workload running at high utilisation all day"},{"id":"d","text":"Responding to a few webhook calls per hour"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('87a59228-ef71-5a64-94e0-3fdb1e659f5b', '{"option":"c"}'::jsonb, 'Per-invocation billing suits spiky, intermittent workloads because there is no idle cost. For constant heavy use, cumulative per-execution charges can exceed the cost of a well-utilised reserved virtual machine.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a16698a2-f487-57d0-a09b-93000ba098fa', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '6803b609-d7f9-5a90-bdab-356069e86901', 'csit-621/cloud-and-edge-computing/q15', 'mcq', 'apply', 'medium', 'Calculate latency imposed by distance', 'Assuming light in fibre travels about 200 km per millisecond, what is the minimum round-trip propagation delay to a data centre 3,000 km away by fibre path?', null, null, '[{"id":"a","text":"15 ms"},{"id":"b","text":"30 ms"},{"id":"c","text":"3 ms"},{"id":"d","text":"60 ms"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a16698a2-f487-57d0-a09b-93000ba098fa', '{"option":"b"}'::jsonb, 'One way is 3,000 / 200 = 15 ms, so the round trip is 30 ms before routing, queuing and processing delays. Choosing 15 ms forgets the return journey; 60 ms doubles twice.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e722a69f-9f5e-5fbe-be5b-ee8027981dee', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '6803b609-d7f9-5a90-bdab-356069e86901', 'csit-621/cloud-and-edge-computing/q16', 'true_false', 'understand', 'easy', 'Distinguish latency from bandwidth', 'Upgrading a link from 100 Mbps to 1 Gbps will remove the latency caused by the distance to a remote data centre.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e722a69f-9f5e-5fbe-be5b-ee8027981dee', '{"value":false}'::jsonb, 'Bandwidth is capacity; latency is delay. Propagation delay is set by distance and the speed of light in the medium, so more bandwidth does not reduce it.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('89a70711-13a0-5dfc-a10f-dcc6c521f42c', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '6803b609-d7f9-5a90-bdab-356069e86901', 'csit-621/cloud-and-edge-computing/q17', 'matching', 'understand', 'medium', 'Distinguish edge, hybrid and sovereignty concepts', 'Match each term to its definition.', null, null, '{"left":[{"id":"l1","text":"Edge computing"},{"id":"l2","text":"Hybrid cloud"},{"id":"l3","text":"Multi-cloud"},{"id":"l4","text":"Data sovereignty"}],"right":[{"id":"r4","text":"Data being subject to the laws of the jurisdiction where it is held or processed"},{"id":"r1","text":"Processing data near where it is produced or used"},{"id":"r2","text":"Integration of distinct private and public infrastructures"},{"id":"r3","text":"Use of services from more than one public cloud provider"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('89a70711-13a0-5dfc-a10f-dcc6c521f42c', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'These terms are often blurred. Hybrid concerns integrating different infrastructure types; multi-cloud concerns multiple public providers; sovereignty is a legal concept, while residency is a location requirement.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('4f27244a-9f45-58b6-98cf-ebf1ec70608b', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '6803b609-d7f9-5a90-bdab-356069e86901', 'csit-621/cloud-and-edge-computing/q18', 'scenario', 'analyse', 'medium', 'Analyse workload placement at a remote industrial site', 'Which placement is most appropriate?', 'A mine in the Western Region of Ghana uses a satellite link that is slow and occasionally unavailable. It wants haul-truck collision alerts, video analytics for safety-equipment compliance, and fleet-wide maintenance analytics.', null, '[{"id":"a","text":"All three in a distant public cloud region to maximise economies of scale"},{"id":"b","text":"Collision alerts and video analytics at the on-site edge; fleet-wide analytics and model training in the cloud"},{"id":"c","text":"All three on employees'' mobile phones"},{"id":"d","text":"Video analytics in the cloud, collision alerts on paper logs"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('4f27244a-9f45-58b6-98cf-ebf1ec70608b', '{"option":"b"}'::jsonb, 'Collision alerts need millisecond responses and must work offline; video is high-volume and better summarised locally. Fleet-wide analytics benefits from aggregated data and elastic cloud compute. This is the act-locally, learn-centrally pattern.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1c2a79ef-ab19-5a37-b8b0-82d56dbba95b', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '6803b609-d7f9-5a90-bdab-356069e86901', 'csit-621/cloud-and-edge-computing/q19', 'short_answer', 'recall', 'easy', 'Recall Ghana''s principal data protection statute', 'Name Ghana''s principal data protection statute (short title and year).', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1c2a79ef-ab19-5a37-b8b0-82d56dbba95b', '{"answers":["Data Protection Act 2012","Data Protection Act, 2012","Act 843"]}'::jsonb, 'The Data Protection Act, 2012 (Act 843) sets principles for processing personal data and establishes the Data Protection Commission. It applies whichever cloud model or location is used.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f6cedd98-d5bc-5695-828a-d584edf090bc', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '6803b609-d7f9-5a90-bdab-356069e86901', 'csit-621/cloud-and-edge-computing/q20', 'mcq', 'evaluate', 'hard', 'Evaluate the costs of a multi-cloud strategy', 'Which statement best evaluates a proposal to adopt three public cloud providers to improve resilience?', null, null, '[{"id":"a","text":"Multi-cloud always improves resilience, so it should be adopted"},{"id":"b","text":"Resilience improves only if workloads are deliberately designed to fail over; otherwise multi-cloud adds integration, security and skills costs"},{"id":"c","text":"Multi-cloud is illegal under Ghanaian data protection law"},{"id":"d","text":"Multi-cloud removes the need for identity management"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f6cedd98-d5bc-5695-828a-d584edf090bc', '{"option":"b"}'::jsonb, 'Multi-cloud can support resilience and specialist services, but only with deliberate design. Many firms become multi-cloud by accident and face duplicated tools, several identity systems and data transfer costs. There is no general legal prohibition, and identity management becomes more complex, not less.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('aff9434d-c4f4-5136-8bc7-2d2e44dae389', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', null, 'csit-621/cloud-and-edge-computing/q21', 'case_analysis', 'evaluate', 'hard', 'Recommend a cloud and edge architecture for a Ghanaian organisation', 'Critically evaluate the board''s view and recommend an architecture covering service models, deployment models and workload placement.', null, 'Illustrative scenario. Savannah Agro-Processing Ltd (hypothetical) runs a shea and cashew processing plant near Tamale and sells to buyers in Ghana and the European Union. It plans to (a) monitor processing machines with sensors to reduce breakdowns, (b) launch a buyer portal where EU customers place orders and view traceability certificates, (c) move staff email and documents off an ageing local server, and (d) keep detailed farmer supplier records, including names, phone numbers and mobile money details. The plant''s internet connection is unreliable during storms and power outages are frequent. The board believes moving everything to one public cloud region will be cheapest.', null, 25, array['Identify the requirements of each workload, including latency, connectivity, sensitivity and demand variability', 'Apply NIST service and deployment models to each workload', 'Assess edge requirements for the plant and the resilience implications of unreliable connectivity and power', 'Analyse data protection obligations under Ghana''s Act 843 and implications of handling EU customer data', 'Evaluate costs, including elasticity, bandwidth, currency exposure and skills', 'Recommend and justify an integrated architecture with risks and mitigations']::text[], '[{"criterion":"Workload analysis","marks":5,"descriptor":"Each workload''s technical and business requirements are clearly identified"},{"criterion":"Use of cloud models","marks":6,"descriptor":"Correct and justified use of IaaS/PaaS/SaaS and private/public/hybrid concepts, including shared responsibility"},{"criterion":"Edge and resilience","marks":5,"descriptor":"Convincing case for local processing at the plant, addressing connectivity and power constraints"},{"criterion":"Data protection and sovereignty","marks":5,"descriptor":"Accurate discussion of Act 843 obligations and the relevance of the EU GDPR for EU buyer data, without inventing specific legal rules"},{"criterion":"Evaluation and recommendation","marks":4,"descriptor":"Balanced critique of the board''s assumption with a coherent, costed and risk-aware recommendation"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('aff9434d-c4f4-5136-8bc7-2d2e44dae389', '{}'::jsonb, 'Examiners reward workload-by-workload reasoning, correct use of NIST models and shared responsibility, a convincing edge argument grounded in local constraints, accurate data protection discussion and a critical, justified recommendation.', 'A strong answer challenges the assumption that one public cloud region is automatically cheapest and best. It separates the four workloads. Machine monitoring requires local processing: sensor data should be collected and analysed on an on-site edge gateway or small server with battery and generator backup, so that anomaly alerts work during outages; summarised data and longer-term trends can synchronise to the cloud for model training when connectivity returns. The buyer portal is customer-facing, variable in demand and must be highly available; a PaaS deployment in a public cloud suits it, with attention to the EU GDPR because it handles EU customer contact data. Staff email and documents fit a SaaS suite, with multi-factor authentication and account management remaining the company''s responsibility under the shared responsibility model. Farmer supplier records contain personal and financial data; the company, as data controller under Act 843, must ensure lawful processing, security safeguards and appropriate contracts with any processor. Options include a SaaS or PaaS database in a provider region with strong contractual safeguards, or a hybrid design keeping the master records in a controlled environment.
The cost evaluation should note that elasticity benefits the portal, but bandwidth costs, foreign-currency billing, backup connectivity and skills must be included. The recommendation is a deliberate hybrid of edge, SaaS and PaaS rather than a single-region lift-and-shift, with risks such as edge device management and vendor lock-in mitigated through standard tools, data export clauses and staff training.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1cd707f8-ddbe-5ac6-8daa-b6cea4f37073', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '30a3ff96-2bff-5e20-be6b-e17ab8dcfd53', 'What are the five essential characteristics of cloud computing in NIST SP 800-145?', 'On-demand self-service, broad network access, resource pooling, rapid elasticity and measured service (Mell & Grance, 2011).', 'supplementary', 'csit-621/cloud-and-edge-computing/9e495fb03ff8', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1879bd04-43a7-5dce-a64e-86e8f6a3b4f6', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '30a3ff96-2bff-5e20-be6b-e17ab8dcfd53', 'Why is a manually provisioned dedicated server from a data centre usually hosting rather than cloud?', 'It lacks on-demand self-service, rapid elasticity and measured service; network access alone does not make a service cloud.', 'supplementary', 'csit-621/cloud-and-edge-computing/de59a805b462', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ee35775c-2b03-558d-a527-fc6ef07b692e', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '30a3ff96-2bff-5e20-be6b-e17ab8dcfd53', 'How does NIST define a private cloud, and what common misunderstanding does this correct?', 'Infrastructure provisioned for exclusive use by one organisation, on or off premises and possibly run by a third party; private does not have to mean in your own building.', 'supplementary', 'csit-621/cloud-and-edge-computing/9a3e118625e7', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('3c75e2ea-d17c-592b-89a2-da4a232c59fb', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '2736b42d-ecb0-5cf2-9fe7-9855045e2a29', '30a3ff96-2bff-5e20-be6b-e17ab8dcfd53', 'In a cloud cost comparison, where do most savings usually come from?', 'Elasticity and managed services that let the firm pay for peak capacity only when needed; a peak-sized lift-and-shift often costs about the same as on-premises.', 'supplementary', 'csit-621/cloud-and-edge-computing/56c4886f9305', true)
