insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('71aa287d-e3fd-5715-82e7-703195698162', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'csit-621/internet-of-things/q01', 'matching', 'recall', 'easy', 'Recall the layers of IoT architecture', 'Match each component to the IoT architecture layer it belongs to.', null, null, '{"left":[{"id":"l1","text":"Soil-moisture sensor"},{"id":"l2","text":"LoRaWAN gateway and backhaul link"},{"id":"l3","text":"Farm manager''s alert dashboard"},{"id":"l4","text":"Device management and stream processing platform"}],"right":[{"id":"r2","text":"Network layer"},{"id":"r1","text":"Perception layer"},{"id":"r4","text":"Processing (middleware) layer"},{"id":"r3","text":"Application layer"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
