insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('69cf4aa9-4cb0-5f33-9f9a-be5c37443857', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'csit-621/internet-of-things/q02', 'mcq', 'understand', 'easy', 'Distinguish sensors from actuators', 'Which of the following is an actuator?', null, null, '[{"id":"a","text":"A thermometer probe in a cold room"},{"id":"b","text":"A motorised valve that opens an irrigation line on command"},{"id":"c","text":"A GPS receiver on a truck"},{"id":"d","text":"A vibration sensor on a pump"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
