insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('290ea77a-0b69-51fd-919b-ebba6c7ae2eb', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'csit-621/internet-of-things/q03', 'true_false', 'understand', 'medium', 'Distinguish LoRaWAN from NB-IoT', 'LoRaWAN operates in unlicensed spectrum and can be deployed privately, whereas NB-IoT uses licensed spectrum operated by mobile network operators.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
