insert into public.question_keys (question_id, correct, explanation, model_answer) values ('290ea77a-0b69-51fd-919b-ebba6c7ae2eb', '{"value":true}'::jsonb, 'This licensing difference drives business choices. LoRaWAN lets an organisation build coverage where none exists by owning gateways; NB-IoT relies on operator coverage and subscriptions but offers managed quality of service.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9b117789-b683-5da6-a022-06c6f9e08649', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'csit-621/internet-of-things/q04', 'scenario', 'apply', 'medium', 'Apply the connectivity selection framework', 'Which connectivity option is most appropriate?', 'A water utility wants to read meters installed in basements of apartment blocks in Accra once a day. The meters run on batteries that should last many years, and mobile operators in the area offer NB-IoT coverage.', null, '[{"id":"a","text":"Wi-Fi provided by each tenant"},{"id":"b","text":"NB-IoT"},{"id":"c","text":"4G cellular broadband"},{"id":"d","text":"Bluetooth Low Energy with no gateway"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9b117789-b683-5da6-a022-06c6f9e08649', '{"option":"b"}'::jsonb, 'Small daily readings, battery power, indoor or underground locations and existing operator coverage all favour NB-IoT, which offers good building penetration and very low power. Tenant Wi-Fi is unreliable and outside the utility''s control; 4G broadband uses more power than needed; BLE alone lacks range.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d2f83ded-e48f-5b56-b2ad-9e80916c063a', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'csit-621/internet-of-things/q05', 'mcq', 'apply', 'hard', 'Calculate the effect of duty cycle on battery life', 'A sensor uses 0.05 mAh per hour on average and has a 2,500 mAh battery. Approximately how long will the battery last?', null, null, '[{"id":"a","text":"About 50 days"},{"id":"b","text":"About 5.7 years"},{"id":"c","text":"About 2 years"},{"id":"d","text":"About 500 days"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d2f83ded-e48f-5b56-b2ad-9e80916c063a', '{"option":"b"}'::jsonb, '2,500 / 0.05 = 50,000 hours; 50,000 / 24 is about 2,083 days, or roughly 5.7 years. Small reductions in average current from less frequent or shorter transmissions have large effects on battery life and maintenance visits.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('79d563b1-1de6-5a36-a8ab-03eeda6fb9cd', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'csit-621/internet-of-things/q06', 'short_answer', 'recall', 'easy', 'Recall a lightweight IoT messaging protocol', 'Name the lightweight publish/subscribe messaging protocol widely used to send IoT data through a broker.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('79d563b1-1de6-5a36-a8ab-03eeda6fb9cd', '{"answers":["MQTT"]}'::jsonb, 'MQTT uses a broker to which devices publish messages on topics and to which applications subscribe. Its low overhead suits constrained devices and unreliable networks.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f20b11c3-52dd-5608-9104-a2f0ceffa71b', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'csit-621/internet-of-things/q07', 'mcq', 'evaluate', 'hard', 'Evaluate total cost of ownership in IoT design', 'For 500 battery-powered sensors across scattered farms, which cost is most likely to dominate total cost of ownership if Wi-Fi is chosen instead of LPWAN?', null, null, '[{"id":"a","text":"The purchase price of the sensors"},{"id":"b","text":"Field visits to replace batteries"},{"id":"c","text":"Cloud storage for the small readings"},{"id":"d","text":"Licence fees for unlicensed spectrum"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f20b11c3-52dd-5608-9104-a2f0ceffa71b', '{"option":"b"}'::jsonb, 'Wi-Fi''s higher energy use can shorten battery life from years to months, multiplying field visits whose labour and transport costs exceed hardware costs. Storage for a few kilobytes per day is trivial, and unlicensed spectrum carries no licence fee.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2688312a-81ec-5bcf-b420-e49442c215f1', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'csit-621/internet-of-things/q08', 'mcq', 'recall', 'easy', 'Recall the main propagation method of Mirai', 'How did the Mirai malware primarily gain access to IoT devices?', null, null, '[{"id":"a","text":"Exploiting a zero-day flaw in device encryption chips"},{"id":"b","text":"Logging in to exposed Telnet services using common factory default credentials"},{"id":"c","text":"Phishing emails sent to device owners"},{"id":"d","text":"Physically tampering with devices in shops"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2688312a-81ec-5bcf-b420-e49442c215f1', '{"option":"b"}'::jsonb, 'Antonakakis et al. (2017) documented that Mirai scanned for exposed Telnet services and tried a short list of default usernames and passwords. Its success came from widespread unchanged defaults, not sophisticated exploits.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3fdc9e1e-32c8-526e-8a3d-06592d90107a', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'csit-621/internet-of-things/q09', 'true_false', 'understand', 'medium', 'Explain the purpose of network segmentation', 'The main purpose of network segmentation for IoT is to increase the network speed of devices.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3fdc9e1e-32c8-526e-8a3d-06592d90107a', '{"value":false}'::jsonb, 'Segmentation limits which systems a device can communicate with, so that a compromised camera or sensor cannot be used to move laterally to sensitive systems such as finance servers.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c32c5720-649e-5452-ab5b-c9b5b7ac45a1', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'csit-621/internet-of-things/q10', 'matching', 'understand', 'medium', 'Match lifecycle stages to security controls', 'Match each lifecycle stage to an appropriate security control.', null, null, '{"left":[{"id":"l1","text":"Design and manufacture"},{"id":"l2","text":"Procurement"},{"id":"l3","text":"Provisioning"},{"id":"l4","text":"Operation"},{"id":"l5","text":"Decommissioning"}],"right":[{"id":"r3","text":"Registering the device in the inventory and placing it in a segmented zone"},{"id":"r5","text":"Revoking certificates and wiping stored data"},{"id":"r4","text":"Monitoring outbound traffic and applying signed updates"},{"id":"r1","text":"Unique per-device credentials and signed firmware"},{"id":"r2","text":"Tender requirements for a stated security update period"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c32c5720-649e-5452-ab5b-c9b5b7ac45a1', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Device lifecycle security means controls at every stage, not just after installation. Procurement and decommissioning are frequently neglected stages.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5621cf58-5c89-531c-a484-0d3a53688568', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'csit-621/internet-of-things/q11', 'scenario', 'analyse', 'hard', 'Analyse risk priorities in an IoT estate', 'Which action would most reduce the risk that one compromised device leads to compromise of critical systems?', 'An audit of an office building finds IP cameras with default passwords, door access readers, a building management system that contractors access remotely with a shared password, and smart TVs. All are on the same network as staff laptops.', null, '[{"id":"a","text":"Buying a faster internet connection"},{"id":"b","text":"Segmenting the network into zones with firewall rules allowing only required flows"},{"id":"c","text":"Turning off the smart TVs during weekends"},{"id":"d","text":"Installing antivirus software on the cameras"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5621cf58-5c89-531c-a484-0d3a53688568', '{"option":"b"}'::jsonb, 'The flat network is the systemic weakness that allows lateral movement. Segmentation contains incidents; it should be combined with credential changes and MFA for contractor access. Cameras usually cannot run antivirus, and the other options do not address the root problem.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('60ba3ed0-5506-5bdf-b1a8-6f014d211c51', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'csit-621/internet-of-things/q12', 'short_answer', 'recall', 'medium', 'Recall the European consumer IoT security baseline', 'Give the ETSI standard number for the consumer IoT cyber security baseline.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('60ba3ed0-5506-5bdf-b1a8-6f014d211c51', '{"answers":["EN 303 645","ETSI EN 303 645","303 645"]}'::jsonb, 'ETSI EN 303 645 includes provisions such as no universal default passwords, managing vulnerability reports and keeping software updated. It is a useful reference for procurement requirements.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c5e58a2b-1688-5cf1-a879-edd5365881c3', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'csit-621/internet-of-things/q13', 'true_false', 'evaluate', 'medium', 'Evaluate the externality problem in IoT security', 'One reason regulation is argued to be necessary for IoT security is that owners of insecure devices often do not bear the main costs when their devices are used to attack others.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c5e58a2b-1688-5cf1-a879-edd5365881c3', '{"value":true}'::jsonb, 'In the Mirai attacks, harm fell largely on third parties such as Dyn and its customers. This externality weakens market incentives for buyers to pay for security, supporting arguments for baselines and legislation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a84ee345-c3e9-5d5f-a254-2fa7e4e95936', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'csit-621/internet-of-things/q14', 'scenario', 'evaluate', 'hard', 'Evaluate controls for a smart metering system', 'Which control most directly limits the impact of such a compromise?', 'A utility contractor''s head-end system can send remote disconnection commands to thousands of prepaid smart meters. Managers worry about an attacker gaining access to the head-end.', null, '[{"id":"a","text":"Requiring additional authorisation and rate limits for commands affecting many meters"},{"id":"b","text":"Changing the meter casing colour"},{"id":"c","text":"Publishing the head-end address so customers can check it"},{"id":"d","text":"Allowing any staff member to issue bulk commands for faster response"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a84ee345-c3e9-5d5f-a254-2fa7e4e95936', '{"option":"a"}'::jsonb, 'Bulk-command authorisation and rate limits restrict how much harm an attacker or insider can cause quickly, complementing segmentation and strong authentication. Publishing addresses increases exposure, and broad staff permissions violate least privilege.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('edb808ec-1463-529f-974b-fd19b0b854ea', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '395acc95-d71c-5dfc-ad45-1c4d544468f1', 'csit-621/internet-of-things/q15', 'mcq', 'understand', 'medium', 'Explain IIoT security priorities', 'Compared with consumer IoT, which security property is typically given the highest priority in Industrial IoT?', null, null, '[{"id":"a","text":"Anonymity of users"},{"id":"b","text":"Availability and safety of the physical process"},{"id":"c","text":"Speed of app updates"},{"id":"d","text":"Aesthetic design of devices"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('edb808ec-1463-529f-974b-fd19b0b854ea', '{"option":"b"}'::jsonb, 'Industrial systems control physical processes where downtime or incorrect commands can cause production loss, injury or environmental harm. Availability and safety, followed by integrity, usually outrank confidentiality.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('71602ca6-7580-5c22-ace4-1ce244b29340', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '395acc95-d71c-5dfc-ad45-1c4d544468f1', 'csit-621/internet-of-things/q16', 'matching', 'understand', 'easy', 'Distinguish maintenance strategies', 'Match each maintenance strategy to its description.', null, null, '{"left":[{"id":"l1","text":"Reactive"},{"id":"l2","text":"Preventive"},{"id":"l3","text":"Condition-based"},{"id":"l4","text":"Predictive"}],"right":[{"id":"r2","text":"Service at fixed time or usage intervals"},{"id":"r3","text":"Act when a monitored indicator crosses a threshold"},{"id":"r1","text":"Repair only after the asset fails"},{"id":"r4","text":"Use data models to forecast failure and intervene just before it"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('71602ca6-7580-5c22-ace4-1ce244b29340', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'The strategies differ in what triggers maintenance. Predictive maintenance needs data and models; condition-based maintenance needs monitoring and thresholds; reactive maintenance may be rational for cheap, non-critical assets.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('cf7a2984-1d18-5641-b459-ff58c448c7ae', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '395acc95-d71c-5dfc-ad45-1c4d544468f1', 'csit-621/internet-of-things/q17', 'mcq', 'apply', 'medium', 'Calculate a payback period for predictive maintenance', 'A predictive maintenance system costs GHS 300,000 upfront and saves GHS 120,000 a year compared with the current preventive approach. What is the simple payback period?', null, null, '[{"id":"a","text":"1.5 years"},{"id":"b","text":"2.5 years"},{"id":"c","text":"4 years"},{"id":"d","text":"0.4 years"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('cf7a2984-1d18-5641-b459-ff58c448c7ae', '{"option":"b"}'::jsonb, 'Simple payback = investment / annual saving = 300,000 / 120,000 = 2.5 years. Simple payback ignores the time value of money and benefits beyond the payback period, so it should be complemented by NPV and sensitivity analysis.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('53c81b3a-71da-5697-9cd8-e8048a77c3b7', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '395acc95-d71c-5dfc-ad45-1c4d544468f1', 'csit-621/internet-of-things/q18', 'scenario', 'analyse', 'hard', 'Analyse readiness for predictive maintenance', 'What is the most sensible first step?', 'A Ghanaian manufacturer wants to adopt predictive maintenance using machine learning. It has no historical records of when and why machines failed, and its older machines lack digital interfaces.', null, '[{"id":"a","text":"Buy a predictive AI platform and expect accurate forecasts immediately"},{"id":"b","text":"Retrofit sensors on critical machines, begin condition-based monitoring and record failures systematically to build training data"},{"id":"c","text":"Abandon digital maintenance entirely"},{"id":"d","text":"Replace all machines with new ones before collecting any data"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('53c81b3a-71da-5697-9cd8-e8048a77c3b7', '{"option":"b"}'::jsonb, 'Predictive models need labelled historical data. Retrofit sensors and condition-based monitoring deliver value immediately while building the data needed for prediction. Full replacement is costly and unnecessary; expecting immediate AI accuracy ignores the data gap.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5c1a59e5-ba29-5214-a708-dcea38b538c7', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '395acc95-d71c-5dfc-ad45-1c4d544468f1', 'csit-621/internet-of-things/q19', 'short_answer', 'recall', 'easy', 'Recall the term for selling outcomes rather than products', 'What term describes manufacturers shifting from selling products to selling services or outcomes, such as paying per flying hour?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5c1a59e5-ba29-5214-a708-dcea38b538c7', '{"answers":["servitisation","servitization"]}'::jsonb, 'Servitisation, as in Rolls-Royce''s flying-hours arrangements, depends on IIoT data from assets and shifts reliability risk to the supplier, aligning incentives with uptime.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2a29bc18-f772-5703-8ec4-be68471064b0', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '395acc95-d71c-5dfc-ad45-1c4d544468f1', 'csit-621/internet-of-things/q20', 'true_false', 'evaluate', 'medium', 'Evaluate when predictive maintenance is justified', 'Predictive maintenance is the best strategy for every asset in a plant, including cheap non-critical items such as office fans.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2a29bc18-f772-5703-8ec4-be68471064b0', '{"value":false}'::jsonb, 'Monitoring costs must be justified by failure consequences and detectability. For cheap, non-critical assets with no safety implications, run-to-failure can be rational.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8bdfb953-a771-5722-b7de-7ba479a2b3e9', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', null, 'csit-621/internet-of-things/q21', 'case_analysis', 'evaluate', 'hard', 'Evaluate an IoT programme design for a Ghanaian cold chain', 'Critically evaluate the proposal and recommend an IoT architecture, connectivity choices, security controls and a business case approach.', null, 'Illustrative scenario. Coastal Fresh Fish Ltd (hypothetical) distributes frozen fish from cold stores in Tema to retailers in Kumasi, Tamale and Ho using refrigerated trucks. Spoilage from temperature excursions and generator failures is a major cost. Management proposes installing temperature sensors in cold rooms and trucks, GPS trackers on trucks, and vibration sensors on compressors. A vendor offers cheap cameras and sensors with fixed default passwords and no update commitment. The IT manager warns that all devices would join the company''s office network.', null, 25, array['Describe the proposed system using a layered IoT architecture', 'Select and justify connectivity for cold rooms, trucks and compressors', 'Identify security weaknesses in the vendor offer and network design, drawing lessons from Mirai', 'Propose lifecycle security controls including procurement, segmentation and updates', 'Outline a business case, including predictive maintenance for compressors and sensitivity analysis', 'Conclude with a phased implementation recommendation']::text[], '[{"criterion":"Architecture","marks":5,"descriptor":"Clear layered description from sensors to business decisions"},{"criterion":"Connectivity selection","marks":5,"descriptor":"Justified choices reflecting mobility, power, data volume and coverage, such as LTE-M or cellular for trucks and Wi-Fi or wired links in cold stores"},{"criterion":"Security analysis","marks":7,"descriptor":"Identifies default credentials, lack of updates and flat network as critical risks with lifecycle controls and reference to baselines"},{"criterion":"Business case","marks":5,"descriptor":"Sound reasoning on spoilage reduction and maintenance savings with explicit assumptions and sensitivity testing"},{"criterion":"Recommendation and coherence","marks":3,"descriptor":"Phased, realistic plan with clear priorities and logical structure"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8bdfb953-a771-5722-b7de-7ba479a2b3e9', '{}'::jsonb, 'Examiners reward a layered architecture, justified connectivity, strong lifecycle security analysis linked to documented cases, a realistic business case with assumptions and a phased recommendation.', 'A strong answer maps the system across layers: temperature sensors, GPS trackers and compressor vibration sensors in the perception layer; connectivity in the network layer; an IoT platform for storage, rules and analytics; and applications such as real-time excursion alerts, route tracking and maintenance work orders, all linked to the business goal of reducing spoilage. For trucks, a mobile cellular IoT option such as LTE-M or standard cellular suits moving assets across regions, with local buffering when coverage drops. Cold stores have mains power, so wired or Wi-Fi links to a local gateway are feasible, with battery-backed loggers so that data survives power cuts. Compressor sensors can feed an edge gateway that runs condition-based alerts locally.
Security is the decisive issue. Fixed default passwords and no update commitment reproduce the conditions exploited by Mirai, and joining all devices to the office network allows lateral movement. The company should reject the offer or require unique credentials, a stated update period and a vulnerability disclosure process, referencing ETSI EN 303 645. Devices should sit in segmented zones with outbound-only connections to the platform, an asset inventory and monitoring. The business case should quantify current spoilage and compressor failure costs, estimate reductions under explicit assumptions, include connectivity and platform costs and test sensitivity to detection rates. A phased pilot on one route and one cold store, with measured results, should precede rollout.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2b273761-e68b-5fd5-ae94-8308918c3a6e', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'What are the three layers of the basic IoT architecture, and what do five-layer models add?', 'Perception (sensors and actuators), network (connectivity and gateways) and application (user services). Five-layer models add a processing (middleware) layer and a business layer.', 'supplementary', 'csit-621/internet-of-things/1403712bee8e', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5bf3cf97-1496-5e32-bb8d-a6f55c00df48', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'What is the difference between a sensor and an actuator?', 'A sensor measures a physical quantity and converts it into data; an actuator acts on the physical world in response to a command, such as opening a valve.', 'supplementary', 'csit-621/internet-of-things/a7e75b1e3abf', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('7b2cf972-10ae-58de-bde2-77e1225dbe60', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'What fundamental trade-off governs IoT connectivity choice?', 'Range, data rate and battery life cannot all be maximised together; LPWAN gives long range and battery life for small data, while Wi-Fi and cellular broadband give high data rates at higher power.', 'supplementary', 'csit-621/internet-of-things/8c242d4ee0d0', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bf519614-a88e-5e8f-be5e-2ffff06231a4', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'When would you choose LoRaWAN over NB-IoT?', 'When operator coverage is absent or unreliable and the organisation wants to own its network, as LoRaWAN uses unlicensed spectrum with private gateways; NB-IoT depends on licensed operator networks.', 'supplementary', 'csit-621/internet-of-things/cba9dc4fd941', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('db1c5ce3-4965-53e6-91d0-933fe2bd13f9', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', 'f4d0a481-a139-5463-8d0b-2288dd1aca33', 'Why do maintenance visits often dominate IoT total cost of ownership?', 'Power-hungry connectivity shortens battery life, multiplying field visits whose labour and transport costs exceed device prices, especially for dispersed rural deployments.', 'supplementary', 'csit-621/internet-of-things/b1a69274b3ba', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('be315768-d8b7-5dc9-8004-573da434c805', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'Give four reasons IoT devices are harder to secure than laptops or servers.', 'Constrained resources, large and heterogeneous fleets, long lifetimes beyond vendor support, physical exposure, weak defaults, shadow IoT and cyber-physical consequences.', 'supplementary', 'csit-621/internet-of-things/ca245a3103ac', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('35341cac-741f-5b88-9cc9-94bf1c4fb8fd', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'What were the root causes of the Mirai botnet''s spread?', 'Exposed Telnet services and unchanged factory default credentials on cameras, video recorders and routers, which Mirai tried from a short list.', 'supplementary', 'csit-621/internet-of-things/4896b7fe6870', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e9e4afaf-510f-5c3a-b024-eca5f274a767', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'Why is network segmentation a core IoT control?', 'It restricts each device to required communications, limiting lateral movement so that a compromised device cannot reach critical systems.', 'supplementary', 'csit-621/internet-of-things/6fbfdf8738c0', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('22e09ca3-704e-52d5-b3c1-2ae3f9820b41', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'What security tasks belong to the decommissioning stage of the device lifecycle?', 'Revoke credentials and certificates, wipe stored data, update the asset inventory and dispose of hardware securely.', 'supplementary', 'csit-621/internet-of-things/4023e8d9543d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('dfcd2f61-1f22-5575-97f6-010c5884e3d4', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '00364b6f-5e05-587d-b10a-7e777c7cc585', 'Name three IoT security baselines or reference documents.', 'ETSI EN 303 645 (consumer IoT baseline), NIST IR 8259 (manufacturer activities) and the OWASP IoT Top 10 (2018).', 'supplementary', 'csit-621/internet-of-things/9812857689e3', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('211de109-912c-596a-96f3-e7d3d2cc46f8', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '395acc95-d71c-5dfc-ad45-1c4d544468f1', 'What is IT/OT convergence and why is it risky?', 'Connecting operational technology (PLCs, SCADA) to IT networks and the cloud; OT devices built for isolated networks may lack authentication and encryption, and engineering and IT cultures differ.', 'supplementary', 'csit-621/internet-of-things/d4763a2cab06', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('986dec6c-5189-5019-8e4a-80147b3ccfb4', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '395acc95-d71c-5dfc-ad45-1c4d544468f1', 'When is predictive maintenance justified?', 'When failure consequences are high, developing failures are detectable early (a usable P-F interval) and sufficient data exists to build reliable models; otherwise simpler strategies may be better.', 'supplementary', 'csit-621/internet-of-things/c398fec003b5', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('eec26afa-df62-5093-8cc2-4716c064d4ae', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '395acc95-d71c-5dfc-ad45-1c4d544468f1', 'What is the P-F interval?', 'The time between the point a potential failure becomes detectable and the point of functional failure; early-warning sensors lengthen the usable interval for planned repairs.', 'supplementary', 'csit-621/internet-of-things/cb276970b905', true)
