insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bd7cfa47-66c4-5f5c-bf45-c76f19d73e6d', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '75e1c70b-a662-57d3-bacc-2e3ee690d80a', '395acc95-d71c-5dfc-ad45-1c4d544468f1', 'What does the Rolls-Royce flying-hours model illustrate?', 'Servitisation - IIoT engine data allows selling availability rather than products, shifting reliability risk to the supplier and aligning incentives with uptime.', 'supplementary', 'csit-621/internet-of-things/a01fa16f3fc3', true)
