insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('79cfef66-3103-5a91-92f2-01fbb40f4768', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'blockchain-and-distributed-technology', 'Blockchain and Distributed Technology', 'Shared ledgers and their business uses.', 4, true)
