insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3a3c300e-619f-5015-b556-84f803d6e124', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'csit-621/blockchain-and-distributed-technology/q01', 'mcq', 'understand', 'medium', 'Explain why hash-linking makes a blockchain tamper-evident', 'Why does altering a transaction in an old block become detectable in a blockchain?', null, null, '[{"id":"a","text":"Because the transaction is encrypted and cannot be decrypted"},{"id":"b","text":"Because the altered block''s hash changes and no longer matches the previous-hash value stored in the next block"},{"id":"c","text":"Because a central administrator checks every block daily"},{"id":"d","text":"Because old blocks are deleted automatically"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3a3c300e-619f-5015-b556-84f803d6e124', '{"option":"b"}'::jsonb, 'Each block stores the hash of its predecessor. Changing any data changes the block''s hash, breaking the link to the following block. Hashing is not encryption, there is no central administrator in a distributed ledger, and old blocks are retained.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('468124ab-4152-5d05-9aed-134d9a08af3b', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'csit-621/blockchain-and-distributed-technology/q02', 'true_false', 'understand', 'medium', 'Evaluate the claim that blockchains guarantee truthful data', 'Recording supply chain data on a blockchain guarantees that the data is accurate.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('468124ab-4152-5d05-9aed-134d9a08af3b', '{"value":false}'::jsonb, 'A blockchain preserves whatever is entered. If a false weight or origin is recorded, the false record is preserved faithfully. This oracle or garbage-in problem must be addressed through measurement, inspection and audit.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f38c22aa-f8d9-567f-b19c-80b492d1833b', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'csit-621/blockchain-and-distributed-technology/q03', 'matching', 'understand', 'medium', 'Match consensus mechanisms to their characteristics', 'Match each consensus mechanism to its defining characteristic.', null, null, '{"left":[{"id":"l1","text":"Proof of work"},{"id":"l2","text":"Proof of stake"},{"id":"l3","text":"PBFT"}],"right":[{"id":"r3","text":"Known validators vote; decisions final once 2f + 1 agree"},{"id":"r2","text":"Validators lock up capital that can be slashed for misbehaviour"},{"id":"r1","text":"Security from computational cost; chain with most accumulated work accepted"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f38c22aa-f8d9-567f-b19c-80b492d1833b', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'The mechanisms differ in how they resist fake identities and how finality is reached. PoW uses computation, PoS uses capital at risk, and PBFT uses known identities and voting.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b5248c88-6687-5c7e-b88b-e2c5d653db9e', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'csit-621/blockchain-and-distributed-technology/q04', 'mcq', 'apply', 'medium', 'Apply the 3f + 1 rule for Byzantine fault tolerance', 'A consortium using a PBFT-style protocol wants to tolerate up to 3 malicious validators. What is the minimum number of validators required?', null, null, '[{"id":"a","text":"6"},{"id":"b","text":"9"},{"id":"c","text":"10"},{"id":"d","text":"7"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b5248c88-6687-5c7e-b88b-e2c5d653db9e', '{"option":"c"}'::jsonb, 'n = 3f + 1 = 3 x 3 + 1 = 10, with a quorum of 2f + 1 = 7. Nine validators would tolerate only 2 faults; 6 and 7 tolerate 1 and 2 respectively.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9e84ba1e-98a0-5ab8-8ff2-79ed61bcd570', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'csit-621/blockchain-and-distributed-technology/q05', 'short_answer', 'recall', 'easy', 'Recall the term for an attack by a majority of mining power', 'What is the common name for an attack in which a party controlling most of a proof-of-work network''s computing power rewrites recent history?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9e84ba1e-98a0-5ab8-8ff2-79ed61bcd570', '{"answers":["51% attack","51 percent attack","majority attack"]}'::jsonb, 'PoW security assumes an honest majority of computing power. A party with more than half could outpace honest miners and reorganise recent blocks, enabling double-spending.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('991dbdf5-60be-5a00-ac1e-876d152f33f1', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'csit-621/blockchain-and-distributed-technology/q06', 'scenario', 'analyse', 'hard', 'Analyse the choice between permissioned and permissionless ledgers', 'Which design is most appropriate?', 'Seven Ghanaian organisations in the cocoa supply chain want to share records of bag movements. Prices and volumes are commercially sensitive, all participants are known, and the regulator requires clear accountability for every entry.', null, '[{"id":"a","text":"A permissionless proof-of-work blockchain open to anyone"},{"id":"b","text":"A permissioned ledger with BFT-style consensus among the known organisations"},{"id":"c","text":"A public proof-of-stake chain with all data visible to everyone"},{"id":"d","text":"No shared record; each party keeps paper ledgers"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('991dbdf5-60be-5a00-ac1e-876d152f33f1', '{"option":"b"}'::jsonb, 'Known participants, sensitive data and accountability requirements point to a permissioned ledger. BFT-style consensus suits a small number of known validators and gives deterministic finality. Public chains expose data and add unnecessary cost; paper ledgers do not solve reconciliation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a1b2ecae-063b-5701-8d31-61fad6794d07', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'csit-621/blockchain-and-distributed-technology/q07', 'true_false', 'recall', 'easy', 'Recall Ethereum''s change of consensus mechanism', 'Ethereum moved from proof of work to proof of stake in an event known as the Merge in 2022.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a1b2ecae-063b-5701-8d31-61fad6794d07', '{"value":true}'::jsonb, 'The Merge in September 2022 joined Ethereum''s execution layer with the proof-of-stake Beacon Chain, substantially reducing the network''s energy use according to the Ethereum Foundation.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('23363b6d-c01d-56d5-96ae-eab7fd63b9bb', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'csit-621/blockchain-and-distributed-technology/q08', 'mcq', 'evaluate', 'hard', 'Evaluate finality properties for business settlement', 'A bank consortium needs settlement that is final immediately once agreed, with no possibility of later reversal by chain reorganisation. Which approach best meets this need?', null, null, '[{"id":"a","text":"Proof of work with one confirmation"},{"id":"b","text":"A BFT-style protocol among known validators"},{"id":"c","text":"Any public blockchain, because all blockchains are immutable"},{"id":"d","text":"A single spreadsheet emailed between banks"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('23363b6d-c01d-56d5-96ae-eab7fd63b9bb', '{"option":"b"}'::jsonb, 'BFT-style protocols provide deterministic finality once a quorum agrees. PoW finality is probabilistic and one confirmation offers weak assurance. Blockchains are not literally immutable, and spreadsheets lack integrity controls.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('50d07a07-0ded-581d-a4f0-6905464311bb', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'csit-621/blockchain-and-distributed-technology/q09', 'mcq', 'understand', 'medium', 'Explain the role of oracles in smart contracts', 'Why do smart contracts need oracles?', null, null, '[{"id":"a","text":"To make contracts run faster"},{"id":"b","text":"To supply external real-world data, such as delivery confirmations, that the deterministic blockchain cannot obtain itself"},{"id":"c","text":"To encrypt all contract code"},{"id":"d","text":"To replace consensus mechanisms"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('50d07a07-0ded-581d-a4f0-6905464311bb', '{"option":"b"}'::jsonb, 'All nodes must produce identical results, so contracts cannot fetch external data directly. Oracles provide it, which shifts trust to the oracle; a compromised oracle causes the contract to execute wrong outcomes automatically.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('856c678e-f560-5014-a98a-8d205781cfe0', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'csit-621/blockchain-and-distributed-technology/q10', 'true_false', 'understand', 'medium', 'Explain the legal status of smart contracts', 'Any smart contract deployed on a blockchain is automatically a legally binding contract in every jurisdiction.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('856c678e-f560-5014-a98a-8d205781cfe0', '{"value":false}'::jsonb, 'Legal effect depends on the applicable law and surrounding agreements. Businesses usually pair smart contracts with conventional legal agreements covering governing law, disputes and what happens if code and intention diverge.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ac22f3ca-afe0-564c-abab-ca623040c667', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'csit-621/blockchain-and-distributed-technology/q11', 'scenario', 'apply', 'medium', 'Apply the blockchain decision tree', 'According to the decision tree, what should be recommended?', 'A Ghanaian supermarket chain proposes putting its internal stock records on a blockchain. Only the chain''s own staff and systems write to the records.', null, '[{"id":"a","text":"A permissionless blockchain"},{"id":"b","text":"A permissioned blockchain with public read access"},{"id":"c","text":"A conventional database, because there is only one writer"},{"id":"d","text":"A smart contract escrow"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ac22f3ca-afe0-564c-abab-ca623040c667', '{"option":"c"}'::jsonb, 'The decision tree asks early whether there are multiple writers. With a single writer there is no trust problem between parties to solve, so a conventional database is simpler, faster and cheaper.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7c2c4a9b-2b31-5ad5-96e7-abdb4078adb5', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'csit-621/blockchain-and-distributed-technology/q12', 'matching', 'recall', 'easy', 'Recall Hyperledger Fabric terminology', 'Match each Hyperledger Fabric term to its meaning.', null, null, '{"left":[{"id":"l1","text":"Chaincode"},{"id":"l2","text":"Channel"},{"id":"l3","text":"Endorsement policy"},{"id":"l4","text":"Ordering service"}],"right":[{"id":"r4","text":"Component that sequences transactions into blocks"},{"id":"r3","text":"Rule specifying which organisations must approve a transaction"},{"id":"r2","text":"Private ledger shared by a subset of members"},{"id":"r1","text":"Smart contract code"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7c2c4a9b-2b31-5ad5-96e7-abdb4078adb5', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Fabric''s execute-order-validate model uses endorsing peers, an ordering service and validation against endorsement policies; channels address enterprise confidentiality needs.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a63e773c-1b72-5c0e-b403-c1754bc85385', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'csit-621/blockchain-and-distributed-technology/q13', 'short_answer', 'recall', 'medium', 'Recall the type of vulnerability exploited in The DAO incident', 'What type of smart contract vulnerability was exploited in The DAO incident of 2016?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a63e773c-1b72-5c0e-b403-c1754bc85385', '{"answers":["reentrancy","re-entrancy","reentrancy vulnerability"]}'::jsonb, 'A reentrancy flaw allowed repeated withdrawals before the contract updated its balance. The incident led to a contentious hard fork and the continuation of the original chain as Ethereum Classic.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('fdbecca9-c18d-5890-bf7c-9cba68fcbae4', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'csit-621/blockchain-and-distributed-technology/q14', 'scenario', 'analyse', 'hard', 'Analyse reasons for enterprise blockchain failure', 'Which explanation is best supported by network-economics reasoning?', 'A blockchain trade-documentation platform is launched by one of the largest firms in an industry together with a technology partner. Several competitors decline to join, and after a few years the platform is discontinued for lack of commercial viability.', null, '[{"id":"a","text":"The consensus algorithm was too slow"},{"id":"b","text":"Competitors were reluctant to join a platform led by a rival, so the network never reached sufficient participation"},{"id":"c","text":"Blockchains cannot store documents"},{"id":"d","text":"Regulators banned blockchains globally"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('fdbecca9-c18d-5890-bf7c-9cba68fcbae4', '{"option":"b"}'::jsonb, 'The pattern resembles TradeLens. Platform value depends on participation, and sponsorship by a dominant competitor can deter rivals who fear value capture or information exposure. Neutral governance is often critical.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('f65617fc-2750-5812-b311-16154cfab6f0', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'csit-621/blockchain-and-distributed-technology/q15', 'mcq', 'evaluate', 'hard', 'Evaluate a warehouse-receipt proposal', 'Several Ghanaian banks, warehouses and buyers want digital warehouse receipts for cocoa. A neutral, well-run registry that all parties already trust is willing to operate the system. What is the strongest recommendation?', null, null, '[{"id":"a","text":"Use a permissionless blockchain to maximise decentralisation"},{"id":"b","text":"Use a central digital registry with strong audit trails, because an acceptable trusted operator exists"},{"id":"c","text":"Do nothing, because digital receipts cannot work"},{"id":"d","text":"Issue a new cryptocurrency for each receipt"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('f65617fc-2750-5812-b311-16154cfab6f0', '{"option":"b"}'::jsonb, 'The decision tree recommends a centrally operated database when an always-online trusted third party is acceptable to all writers. A blockchain adds cost and complexity without solving an unresolved trust problem; issuing cryptocurrencies adds volatility and regulatory risk.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6a6f8c87-4bfc-5af8-9a8a-a13c732a04fd', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'csit-621/blockchain-and-distributed-technology/q16', 'true_false', 'evaluate', 'medium', 'Evaluate the trust assumptions of smart contracts', 'Smart contracts eliminate the need for trust because code executes exactly as written.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6a6f8c87-4bfc-5af8-9a8a-a13c732a04fd', '{"value":false}'::jsonb, 'Trust shifts rather than disappears, towards code authors, auditors, oracles and whoever controls upgrade mechanisms. The DAO incident shows that code executing as written can still produce outcomes participants regard as unacceptable.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('22545da8-8529-559e-9835-49186a16af40', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', null, 'csit-621/blockchain-and-distributed-technology/q17', 'essay', 'evaluate', 'hard', 'Critically evaluate blockchain for a Ghanaian business problem', 'Blockchain is a solution in search of a problem. Critically evaluate this statement with reference to consensus mechanisms, smart contracts, the decision of when to use blockchain, and one Ghanaian and one international application.', null, null, null, 20, array['Define distributed ledgers, consensus and smart contracts concisely', 'Present the case for the statement, including oracle problems, governance failures and database alternatives', 'Present the case against, identifying conditions where blockchain adds genuine value', 'Apply a structured decision tree to a Ghanaian application', 'Use a documented international case to support the argument', 'Conclude with a nuanced judgement']::text[], '[{"criterion":"Technical understanding","marks":5,"descriptor":"Accurate explanation of ledgers, consensus types and smart contracts, including finality and permission models"},{"criterion":"Critical argument","marks":6,"descriptor":"Balanced evaluation of the statement with clear reasoning on both sides"},{"criterion":"Application","marks":6,"descriptor":"Decision tree applied rigorously to a Ghanaian case and an international case used accurately without invented facts"},{"criterion":"Conclusion and communication","marks":3,"descriptor":"Nuanced, justified conclusion; logical structure and academic style"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('22545da8-8529-559e-9835-49186a16af40', '{}'::jsonb, 'Examiners look for accurate technical grounding, a genuinely two-sided argument, rigorous use of the decision tree, accurate case facts and a nuanced conclusion.', 'A strong answer opens by explaining that a distributed ledger replicates records among participants who agree on updates through consensus, whether proof of work, proof of stake or BFT-style voting among known validators, and that smart contracts automate logic on the ledger. It then supports the statement: many proposals fail basic tests because a single organisation writes the data or because a trusted operator exists, so a conventional database would be cheaper and faster. The oracle problem means a ledger cannot guarantee that physical reality matches the record, and enterprise consortia often fail for governance reasons, as TradeLens illustrates.
The counter-argument identifies genuine value where multiple writers who do not fully trust one another must share state and no operator is acceptable to all; where public verifiability without a gatekeeper matters; or where programmable assets enable new forms of settlement. Walmart''s traceability work shows benefits when a powerful participant can drive adoption, though one should ask how much value came from digitisation and standards rather than the ledger itself.
Applied to a Ghanaian case, such as cocoa warehouse receipts or land records, the decision tree highlights the pivotal question of whether a neutral trusted registry exists, along with oracle controls such as inspection and audits. A nuanced conclusion argues that blockchain is not inherently a solution in search of a problem, but that its appropriate problem space is narrow, and governance, participation and data quality determine success.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('684b3d6c-59b2-539a-bf1d-95f5b57c05ae', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'Why is a blockchain described as tamper-evident rather than immutable?', 'Changing a block changes its hash and breaks the link to the next block, so tampering is detectable; but a controlling majority of work, stake or validators, or a social-consensus fork, could still change history.', 'supplementary', 'csit-621/blockchain-and-distributed-technology/ede6e466a327', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4aa9d682-56aa-50ad-84e9-8aaa97708b32', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'What two problems must consensus mechanisms solve in a distributed ledger?', 'The Byzantine generals problem (agreement despite faulty or malicious participants) and the double-spending problem (one agreed order of transactions so the same digital asset is not spent twice).', 'supplementary', 'csit-621/blockchain-and-distributed-technology/e6bf549ffa6a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('313ca457-35f0-545e-9a9b-c739a31cfb6e', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'Compare finality in proof of work and PBFT.', 'PoW finality is probabilistic and strengthens with each additional block; PBFT finality is deterministic once a quorum of 2f + 1 validators agrees.', 'supplementary', 'csit-621/blockchain-and-distributed-technology/6fbfd859ebf2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('adabdb96-b9be-5a75-b984-7da402ffb9ee', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'How many validators does a BFT protocol need to tolerate f faulty nodes?', 'At least 3f + 1 validators, with decisions requiring 2f + 1; for example, 7 validators tolerate 2 faults.', 'supplementary', 'csit-621/blockchain-and-distributed-technology/a1ade4217db8', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8e984863-1c6a-5263-99e7-955d3a0a3a97', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'What is the oracle (garbage-in) problem?', 'A ledger faithfully preserves whatever is entered, including false data; accuracy depends on measurement, inspection and trusted data sources outside the chain.', 'supplementary', 'csit-621/blockchain-and-distributed-technology/96d7b968a0d3', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('db9b6305-3788-52e3-8e3c-1b6e8be968be', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', 'a57f52aa-0594-5af9-98fd-e3ee604240db', 'Why is the permissioned versus permissionless choice a governance decision?', 'It determines who may participate, validate and read data, and who is trusted to admit members and resolve disputes - not merely a technical setting.', 'supplementary', 'csit-621/blockchain-and-distributed-technology/429be4d032c3', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('cc28a2f3-03bd-5afd-9c67-f50fdc4585b1', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'What is a smart contract, and what analogy did Nick Szabo use?', 'Code stored on a ledger that executes automatically when conditions are met and is verified by the network; Szabo compared it to a vending machine.', 'supplementary', 'csit-621/blockchain-and-distributed-technology/dad2c6827737', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5af4781b-067d-52da-9035-4eae688d8757', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'What lessons does The DAO incident (2016) teach?', 'Smart contract bugs such as reentrancy can be costly; "code is law" can clash with fairness; and immutability can be overridden by social consensus, as the hard fork and Ethereum Classic showed.', 'supplementary', 'csit-621/blockchain-and-distributed-technology/3600f05e4f04', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1c119cbb-5231-5dd3-8d31-73f5a5980562', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'Summarise the key steps of the "do you need a blockchain?" decision tree.', 'Shared state needed? Multiple writers? Is an always-online trusted third party acceptable? Are writers known? Are they trusted? Is public verifiability needed? Blockchain fits only with multiple untrusted writers and no acceptable central operator.', 'supplementary', 'csit-621/blockchain-and-distributed-technology/2d6cc0cdab88', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('42189284-b460-5afd-9624-c34c6b0316e2', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'Which Hyperledger Fabric features address enterprise confidentiality and accountability?', 'Identity-based membership, channels and private data collections, and endorsement policies specifying which organisations must approve transactions.', 'supplementary', 'csit-621/blockchain-and-distributed-technology/5a56a72fa905', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ed9cddf7-1de7-51d8-927a-df71e2cb838c', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'Why did Walmart''s food traceability succeed where TradeLens failed?', 'Walmart''s buying power created participation incentives for a clear food-safety problem; TradeLens struggled to win full industry collaboration, as rivals were reluctant to join a platform led by a competitor.', 'supplementary', 'csit-621/blockchain-and-distributed-technology/1152ddfed588', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c6d52777-1677-5143-bb22-93de5d32c5a2', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '79cfef66-3103-5a91-92f2-01fbb40f4768', '25d15bb0-033f-57b1-8554-529d650968af', 'Do smart contracts remove the need for trust?', 'No - trust shifts to code authors, auditors, oracles and whoever controls upgrades, and legal agreements are still needed for exceptions and disputes.', 'supplementary', 'csit-621/blockchain-and-distributed-technology/828908119669', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
