insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9c5590c3-c8a8-54d6-b5fd-d86cf067394e', '{"option":"b"}'::jsonb, 'Payback = 600,000 / 400,000 = 1.5 years. The result depends on assumptions about training effectiveness and trainee numbers, which should be tested through a controlled pilot.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
