insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ae3edeb9-8a39-5e75-81ff-80d5d2dea5a8', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '664c98d2-6887-56a1-82b9-cc458395fdf8', 'csit-621/immersive-technologies/q07', 'scenario', 'evaluate', 'hard', 'Evaluate the main cost drivers of immersive projects', 'Which critique is most important?', 'A Ghanaian bank''s innovation team proposes buying 50 VR headsets for staff training and argues the project is cheap because headsets cost relatively little each. No training content exists yet, and the bank has no 3D development skills.', null, '[{"id":"a","text":"Headsets will become obsolete in a week"},{"id":"b","text":"Content creation, integration and device management are likely to cost more than the hardware and have not been budgeted"},{"id":"c","text":"VR cannot be used for any training"},{"id":"d","text":"The bank should buy 500 headsets instead"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
