insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ae3edeb9-8a39-5e75-81ff-80d5d2dea5a8', '{"option":"b"}'::jsonb, 'Immersive business cases are often dominated by content development, maintenance and device management. Without content or skills, the headset price says little about total cost. VR can be valuable for training when the task suits it.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6a183f10-b0a1-5a86-aee3-fd2ffb73fe6a', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '664c98d2-6887-56a1-82b9-cc458395fdf8', 'csit-621/immersive-technologies/q08', 'true_false', 'analyse', 'medium', 'Analyse the role of scale in immersive business cases', 'Reducing the number of trainees from 400 to 100 a year would normally strengthen the business case for custom VR training content.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6a183f10-b0a1-5a86-aee3-fd2ffb73fe6a', '{"value":false}'::jsonb, 'Content development costs are largely fixed, so fewer users means a higher cost per trainee and smaller total savings. Scale and frequency of use are key drivers of immersive business cases.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5f02bffc-fa5c-5c22-9e14-a8a2a487eaf4', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '066054ef-515e-5329-92fc-27537156adaa', 'csit-621/immersive-technologies/q09', 'matching', 'understand', 'medium', 'Distinguish digital models, shadows and twins', 'Match each type to its data-flow pattern according to Kritzinger et al. (2018).', null, null, '{"left":[{"id":"l1","text":"Digital model"},{"id":"l2","text":"Digital shadow"},{"id":"l3","text":"Digital twin"}],"right":[{"id":"r1","text":"Manual data flows in both directions"},{"id":"r2","text":"Automatic physical-to-virtual flow, manual virtual-to-physical flow"},{"id":"r3","text":"Automatic data flows in both directions"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5f02bffc-fa5c-5c22-9e14-a8a2a487eaf4', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3"}}'::jsonb, 'The classification is based on automation of data integration. Many systems marketed as digital twins are digital shadows, which may still deliver most of the value with less risk.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9ced923d-3e67-5cf9-b1b0-2dbb70fd69ea', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '066054ef-515e-5329-92fc-27537156adaa', 'csit-621/immersive-technologies/q10', 'mcq', 'recall', 'easy', 'Recall the components of Grieves'' digital twin model', 'Which set describes the three components of a digital twin in Grieves'' model?', null, null, '[{"id":"a","text":"Sensors, cloud and dashboards"},{"id":"b","text":"The physical entity, the virtual entity and the data and information connections between them"},{"id":"c","text":"Hardware, software and users"},{"id":"d","text":"Design, manufacture and disposal"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9ced923d-3e67-5cf9-b1b0-2dbb70fd69ea', '{"option":"b"}'::jsonb, 'Grieves describes a physical product in real space, a virtual product in virtual space and the connections of data and information that tie them together. Sensors and dashboards are enabling technologies, not the conceptual components.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('7fa7e4b9-68ff-5458-841d-fdc71f29cd78', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '066054ef-515e-5329-92fc-27537156adaa', 'csit-621/immersive-technologies/q11', 'scenario', 'apply', 'medium', 'Classify a system using the model/shadow/twin distinction', 'How should this system be classified?', 'A Kumasi hospital installs temperature sensors in its vaccine cold rooms. Readings appear on a live dashboard and staff receive alarms on their phones, after which they manually adjust or repair the refrigeration units.', null, '[{"id":"a","text":"Digital model"},{"id":"b","text":"Digital shadow"},{"id":"c","text":"Digital twin"},{"id":"d","text":"Not a digital representation at all"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('7fa7e4b9-68ff-5458-841d-fdc71f29cd78', '{"option":"b"}'::jsonb, 'Data flows automatically from the physical cold rooms to the virtual representation, but actions flow back manually through staff. That is a digital shadow. It would be a twin only if the system automatically adjusted the refrigeration.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('52894dd9-92fb-5847-82fb-db69c95a5e5e', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '066054ef-515e-5329-92fc-27537156adaa', 'csit-621/immersive-technologies/q12', 'mcq', 'apply', 'hard', 'Apply a sensitivity test to a digital twin business case', 'A water utility twin costs GHS 1,500,000 a year to run. Each 1,000 cubic metres per day of reduced losses saves GHS 730,000 a year at marginal cost. What minimum daily reduction is needed to cover running costs?', null, null, '[{"id":"a","text":"About 1,000 cubic metres per day"},{"id":"b","text":"About 2,050 cubic metres per day"},{"id":"c","text":"About 5,000 cubic metres per day"},{"id":"d","text":"About 730 cubic metres per day"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('52894dd9-92fb-5847-82fb-db69c95a5e5e', '{"option":"b"}'::jsonb, '1,500,000 / 730,000 is about 2.05, so roughly 2,050 cubic metres per day must be saved just to cover running costs, before recovering the upfront investment. Such break-even tests reveal how sensitive twin business cases are to performance.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8b5e20ce-fb21-5697-a964-8aa41b09a821', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '066054ef-515e-5329-92fc-27537156adaa', 'csit-621/immersive-technologies/q13', 'true_false', 'understand', 'easy', 'Explain the role of fidelity', 'A digital twin should always be built at the highest possible visual and physical fidelity.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8b5e20ce-fb21-5697-a964-8aa41b09a821', '{"value":false}'::jsonb, 'Fidelity should match the decisions the twin supports. Higher fidelity increases cost and complexity; a mathematical model with a simple dashboard is often sufficient.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('143f3568-2111-5f0c-aab5-c28822dfe404', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '066054ef-515e-5329-92fc-27537156adaa', 'csit-621/immersive-technologies/q14', 'short_answer', 'recall', 'medium', 'Recall the highest maturity level of a digital twin', 'What is the highest maturity level of a digital twin, in which it acts automatically within guardrails?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('143f3568-2111-5f0c-aab5-c28822dfe404', '{"answers":["autonomous","autonomy"]}'::jsonb, 'Maturity progresses from descriptive, diagnostic, predictive and prescriptive to autonomous. Autonomous twins close the loop to physical assets and require strong guardrails and security.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('2bfb708a-2a0f-57d7-8bf9-0f7072af9714', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '066054ef-515e-5329-92fc-27537156adaa', 'csit-621/immersive-technologies/q15', 'scenario', 'evaluate', 'hard', 'Evaluate the risks of automated virtual-to-physical control', 'Which response is most appropriate?', 'A container terminal''s twin can automatically change truck appointment slots and crane allocations. A vendor proposes extending it to directly control gate barriers and yard lighting through the same internet-connected platform, with no human approval step.', null, '[{"id":"a","text":"Approve immediately, because more automation always increases value"},{"id":"b","text":"Require segmentation, authenticated commands, limits on high-impact actions and human approval where safety is affected"},{"id":"c","text":"Reject all digital twin use at the terminal"},{"id":"d","text":"Allow the vendor to manage all security without oversight"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('2bfb708a-2a0f-57d7-8bf9-0f7072af9714', '{"option":"b"}'::jsonb, 'Automated control paths create cyber-physical risk; compromising the twin could manipulate real assets. Security principles from IoT, including segmentation, least privilege, authenticated commands and human approval for high-impact actions, apply. Rejecting all use discards proven benefits; abdicating oversight ignores accountability.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e4b61ff5-5e1f-5912-9b8e-3f9afcbb21fb', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '066054ef-515e-5329-92fc-27537156adaa', 'csit-621/immersive-technologies/q16', 'mcq', 'analyse', 'medium', 'Analyse the most common barrier to digital twin value', 'A logistics firm buys an advanced simulation platform, but its twin produces unreliable results because container identifiers and time stamps differ across its systems. Which layer of the twin architecture is the weakest?', null, null, '[{"id":"a","text":"Visualisation"},{"id":"b","text":"Integration and context (consistent asset model and data alignment)"},{"id":"c","text":"Physical sensors only"},{"id":"d","text":"Cloud elasticity"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e4b61ff5-5e1f-5912-9b8e-3f9afcbb21fb', '{"option":"b"}'::jsonb, 'Without consistent identifiers and aligned time stamps, data cannot be linked to the right entities, and the models produce misleading results. Data integration is frequently the hardest and most important part of a twin programme.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3d8cd85a-353c-5b12-8f36-fc4c2e940e0d', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', null, 'csit-621/immersive-technologies/q17', 'case_analysis', 'evaluate', 'hard', 'Evaluate an immersive technology and digital twin proposal', 'Critically evaluate both proposals and advise the board on priorities, design and safeguards.', null, 'Illustrative scenario. Korle Bu Regional Health Services (hypothetical) runs a large teaching hospital group in Ghana. The board is considering two proposals. Proposal A is a VR training programme for nurses and junior doctors covering emergency procedures and rare clinical scenarios. Proposal B is a "digital twin of the hospital" that would combine bed management data, patient flow, equipment sensors and a 3D model of the buildings, eventually allowing automatic allocation of beds and theatre slots. A vendor has presented an impressive 3D visualisation and claims both projects will "transform patient care". Budgets are tight and data systems are fragmented across departments.', null, 25, array['Define the relevant concepts using the reality-virtuality continuum and the model/shadow/twin distinction', 'Assess Proposal A using task matching, effectiveness evidence, scale and human factors', 'Assess Proposal B using scope and maturity levels, data readiness and integration needs', 'Construct an outline business case for each with key assumptions and sensitivity tests', 'Analyse risks, including patient safety, data protection under Act 843 and cyber security of automated control', 'Recommend priorities and a phased plan']::text[], '[{"criterion":"Conceptual accuracy","marks":5,"descriptor":"Correct use of Milgram and Kishino, Azuma, and Kritzinger et al. classifications"},{"criterion":"Evaluation of Proposal A","marks":5,"descriptor":"Task-focused assessment of VR training, including effectiveness measurement, content costs, scale and cybersickness"},{"criterion":"Evaluation of Proposal B","marks":6,"descriptor":"Realistic assessment of scope, maturity and data readiness, identifying that the vendor''s offer may be a model or shadow and that integration is the main challenge"},{"criterion":"Business case and risk","marks":6,"descriptor":"Explicit assumptions, sensitivity reasoning, data protection and safety and security safeguards for automated decisions"},{"criterion":"Recommendation","marks":3,"descriptor":"Clear, phased and justified priorities"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3d8cd85a-353c-5b12-8f36-fc4c2e940e0d', '{}'::jsonb, 'Examiners reward precise concepts, task-focused evaluation of VR, realistic assessment of twin maturity and data readiness, explicit business-case assumptions, attention to safety, data protection and security, and a phased recommendation.', 'A strong answer begins by noting that a 3D visualisation alone is a digital model, not a twin, and that the hospital''s fragmented data means Proposal B currently lacks the integration layer on which any twin depends. Proposal A is assessed through task matching: emergency procedures and rare scenarios are high-stakes and hard to practise safely, which suits VR''s presence and repeatability. Its business case rests on measured improvements in competence and on scale across training cohorts; content costs, device management, infection control for shared headsets and cybersickness must be included. A pilot comparing VR-supported and conventional training on assessed performance would provide evidence.
For Proposal B, the answer recommends starting at system scope with a digital shadow of bed occupancy and patient flow, which needs consistent patient and bed identifiers, timely data entry and integration across departmental systems. Descriptive and predictive capabilities, such as forecasting bed demand from admissions data, can deliver value before any automation. Automatic allocation of beds or theatre slots raises patient-safety and accountability concerns and should remain prescriptive, with clinicians approving decisions. Patient data processing must comply with the Data Protection Act, 2012 (Act 843), with access controls, minimisation and security, and any control paths must be segmented and authenticated.
The recommendation prioritises a modest VR pilot and a data integration programme leading to a digital shadow, deferring the full twin and treating vendor claims of transformation with scepticism until evidence is gathered.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('5ebd2f99-2df8-56d3-a36a-6753c5b64522', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '664c98d2-6887-56a1-82b9-cc458395fdf8', 'Describe Milgram and Kishino''s reality-virtuality continuum.', 'A scale from the real environment through augmented reality and augmented virtuality to a fully virtual environment; mixed reality originally meant everything between the two extremes.', 'supplementary', 'csit-621/immersive-technologies/fb64fe6bf5f3', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a1480bf1-3b34-5573-863d-6720936d20a1', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '664c98d2-6887-56a1-82b9-cc458395fdf8', 'What are Azuma''s three defining characteristics of augmented reality?', 'It combines real and virtual content, is interactive in real time, and is registered in three dimensions.', 'supplementary', 'csit-621/immersive-technologies/780dcb545482', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1300277f-1969-5da9-9705-a08ed8b9b267', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '664c98d2-6887-56a1-82b9-cc458395fdf8', 'What is the difference between immersion and presence?', 'Immersion is the objective capability of the system (field of view, tracking, display); presence is the user''s subjective sense of being in the virtual place.', 'supplementary', 'csit-621/immersive-technologies/acb992464261', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6272d9a7-7726-556d-9b63-9d64db51fa4e', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '664c98d2-6887-56a1-82b9-cc458395fdf8', 'When does AR fit a task better than VR?', 'When the user must see and work on real objects or surroundings, often hands-free, such as guided repairs; VR suits tasks where the real environment is irrelevant or too dangerous to practise in.', 'supplementary', 'csit-621/immersive-technologies/e7f34cb59c49', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('0a543064-1984-5f78-953d-def70bd30974', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '664c98d2-6887-56a1-82b9-cc458395fdf8', 'What usually dominates the cost of immersive projects?', 'Content creation and maintenance, integration with enterprise data and device management, rather than headset hardware.', 'supplementary', 'csit-621/immersive-technologies/6899b483e305', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c0a786d4-eb06-5d2c-8bff-2c8833e3302c', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5a42e26a-7aa0-5652-a5bf-b63a4631437c', '664c98d2-6887-56a1-82b9-cc458395fdf8', 'Why do scale and frequency matter in immersive business cases?', 'Content costs are largely fixed, so spreading them over many users and repetitions lowers cost per use; small-scale deployments rarely pay back custom content.', 'supplementary', 'csit-621/immersive-technologies/11d819882767', true)
