insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'future-technologies', 'Future Technologies', 'Automation, connectivity and intelligence shaping the next decade.', 7, true)
