insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1aa96d01-d0dc-5d0a-aef3-bd68bd86817b', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '6f670383-140d-5a51-9c15-75b9cb4d51eb', 'csit-621/future-technologies/ft16', 'short_answer', 'recall', 'easy', 'Recall the term for using data beyond its original purpose', 'What two-word term describes the gradual reuse of data or technology for purposes beyond those originally approved?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
