insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1aa96d01-d0dc-5d0a-aef3-bd68bd86817b', '{"answers":["function creep"]}'::jsonb, 'Function creep occurs, for example, when traffic camera data is later used for policing or monitoring without a new legal basis. Purpose limitation in data protection law is designed to prevent it.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a80d1e2b-cc61-57e4-bd82-eb7116fcd212', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '6f670383-140d-5a51-9c15-75b9cb4d51eb', 'csit-621/future-technologies/ft17', 'matching', 'understand', 'medium', 'Match smart city layers to components', 'Match each smart city layer to an example component.', null, null, '{"left":[{"id":"l1","text":"Sensing layer"},{"id":"l2","text":"Connectivity layer"},{"id":"l3","text":"Data platform layer"},{"id":"l4","text":"Analytics and AI layer"},{"id":"l5","text":"Governance layer"}],"right":[{"id":"r4","text":"Flood prediction models"},{"id":"r2","text":"LPWAN and 4G/5G networks"},{"id":"r3","text":"Integration, catalogue, access control and open APIs"},{"id":"r5","text":"Data protection impact assessments and citizen consultation"},{"id":"r1","text":"Water-level sensors in drains"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a80d1e2b-cc61-57e4-bd82-eb7116fcd212', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'The layers move from collecting data to transporting, integrating, analysing and governing it. Governance cuts across all layers and is what distinguishes a responsible smart city from a collection of gadgets.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0f26a804-def6-55ee-aedc-38654bf42ef4', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '6f670383-140d-5a51-9c15-75b9cb4d51eb', 'csit-621/future-technologies/ft18', 'mcq', 'analyse', 'hard', 'Analyse lessons from Sidewalk Toronto', 'What is the most important lesson of the Sidewalk Toronto project for public-private smart city partnerships?', null, null, '[{"id":"a","text":"Sensors are too expensive for cities"},{"id":"b","text":"Data governance, public ownership and trust need to be settled early, or they can derail even well-funded projects"},{"id":"c","text":"Technology firms should never work with cities"},{"id":"d","text":"Waterfront locations are unsuitable for smart cities"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0f26a804-def6-55ee-aedc-38654bf42ef4', '{"option":"b"}'::jsonb, 'The project''s controversy centred on who would own and control data collected in public spaces and the influence of a private technology firm; Sidewalk Labs withdrew in 2020. The lesson is about governance and trust, not sensor cost or geography, and partnerships can work if these issues are resolved transparently.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('cda4c0fc-05c8-5d00-ab09-f1a078d00c74', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', null, 'csit-621/future-technologies/ft19', 'case_analysis', 'evaluate', 'hard', 'Design and evaluate an IoT-enabled business solution with a cloud versus edge analysis', 'Propose and critically evaluate an IoT-enabled solution for the company, including a justified cloud versus edge processing design, connectivity choices, automation level, risks and a recommendation.', null, 'Illustrative scenario. Volta Fresh Logistics is a fictional cold-chain distributor based in Tema that moves fish, poultry and vaccines to retailers and clinics across Ghana in 60 refrigerated trucks and three cold stores. Spoilage from temperature excursions is costly, drivers sometimes switch off refrigeration to save fuel, and clients increasingly demand proof of temperature compliance. Mobile coverage is good in cities but patchy on some rural routes. Management is considering sensors in trucks and cold stores, a cloud dashboard, automated alerts, possibly automated cold-store doors and, in the longer term, autonomous yard robots in its Tema warehouse. The IT team is small and the budget is limited.', null, 25, array['Define business problem, objectives and success measures', 'Design IoT architecture (sensors, gateways, connectivity, platform, applications)', 'Analyse cloud versus edge processing, including offline operation on rural routes', 'Choose connectivity (cellular, LPWAN, 5G, satellite) with justification', 'Determine appropriate automation levels and human oversight', 'Assess risks (security, data quality, workforce, cost) and mitigations', 'Recommend a phased plan with measurable outcomes']::text[], '[{"criterion":"Problem framing and objectives","marks":3,"descriptor":"Clear statement of spoilage, compliance and behavioural problems with measurable objectives"},{"criterion":"IoT architecture","marks":5,"descriptor":"Coherent layered design with suitable sensors, gateways, platform and applications"},{"criterion":"Cloud versus edge analysis","marks":6,"descriptor":"Justifies local buffering and alerting at the edge for patchy coverage and latency, with cloud for fleet analytics, compliance records and integration; discusses trade-offs"},{"criterion":"Connectivity and automation choices","marks":4,"descriptor":"Realistic connectivity choices; appropriate automation levels with human oversight; critical view of autonomous robots"},{"criterion":"Risk assessment","marks":4,"descriptor":"Identifies security, data integrity, driver relations, cost and vendor risks with mitigations"},{"criterion":"Recommendation and phasing","marks":3,"descriptor":"Phased, affordable plan with KPIs and justification"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('cda4c0fc-05c8-5d00-ab09-f1a078d00c74', '{}'::jsonb, 'Examiners look for an architecture grounded in requirements, a reasoned cloud-versus-edge split driven by connectivity and latency, proportionate automation, realistic risks and a phased plan.', 'A strong answer frames the problem as reducing spoilage, proving compliance and changing driver behaviour, with KPIs such as excursion minutes per trip, spoilage value and audit pass rates.

Architecture: temperature and door sensors in each truck compartment and cold store, connected to an in-vehicle gateway with GPS. Gateways send data to a cloud IoT platform feeding dashboards, compliance reports and client portals, with integration to dispatch systems.

Cloud versus edge: the decisive factor is patchy rural coverage and the need for immediate response. The truck gateway should process data at the edge, detecting excursions and alerting the driver locally within seconds and buffering readings when offline, then synchronising later with tamper-evident timestamps. The cloud suits fleet-wide analytics, historical compliance records, predictive maintenance of refrigeration units and client access, where latency is not critical. Pure cloud processing would fail offline; pure edge would lose fleet visibility.

Connectivity: 4G cellular for trucks, with store-and-forward; LPWAN or Wi-Fi inside cold stores; satellite only as an optional backup for vaccine loads. 5G is unnecessary for these data rates.

Automation: automated alerts and escalation are appropriate; automated door control in cold stores may be justified with manual override; autonomous yard robots are premature given scale, budget and skills.

Risks: device tampering, insecure default credentials, data gaps, driver resistance (address through engagement and incentives rather than only surveillance), vendor lock-in and running costs. Phase 1 pilots ten trucks and one cold store; scale if KPIs improve.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8711c096-cfe3-555b-a9e5-f23c28cac6e9', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', null, 'csit-621/future-technologies/ft20', 'essay', 'evaluate', 'hard', 'Evaluate the opportunities and risks of smart city initiatives in Ghana', 'Critically evaluate the extent to which advanced AI and 5G-enabled smart city initiatives could address urban challenges in Accra or Kumasi, and what safeguards are required.', null, null, null, 20, array['Identify urban challenges and relevant smart city applications', 'Explain the roles of AI, IoT, connectivity and data platforms', 'Evaluate benefits against privacy, surveillance, inclusion, cost and lock-in risks', 'Discuss legal and governance safeguards including Act 843', 'Conclude with a justified position and priorities']::text[], '[{"criterion":"Understanding of technologies and architecture","marks":5,"descriptor":"Accurate account of AI capabilities and limits, connectivity options and the data platform"},{"criterion":"Application to Ghanaian urban context","marks":5,"descriptor":"Relevant challenges such as flooding, congestion and waste, with illustrative scenarios clearly labelled"},{"criterion":"Critical evaluation of risks","marks":6,"descriptor":"Balanced analysis of privacy, surveillance, exclusion, security, sustainability of funding and vendor lock-in"},{"criterion":"Safeguards and conclusion","marks":4,"descriptor":"Concrete governance measures and a justified conclusion"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8711c096-cfe3-555b-a9e5-f23c28cac6e9', '{}'::jsonb, 'Examiners reward essays that are problem-led, technically accurate, critical about risks, specific on safeguards and honest about the limits of technology.', 'A strong essay begins with real problems: recurrent flooding, congestion, waste management and pressure on services. It explains that AI can predict floods from sensor and weather data, optimise traffic signals and waste routes, and support citizen services through multilingual assistants, while connectivity ranges from LPWAN for sensors to 4G and, where justified, 5G for video-heavy or low-latency applications. It stresses that the urban data platform, with open standards and city ownership of data, determines whether projects integrate or fragment.

The evaluation recognises benefits but also constraints: maintenance funding beyond pilots, power and connectivity reliability, scarce skills, and the risk that technology-led projects ignore informal settlements and traders. It analyses privacy and surveillance risks, especially facial recognition and function creep, and notes AI limitations such as hallucination and weak coverage of Ghanaian languages. Sidewalk Toronto illustrates how data governance failures can derail projects.

Safeguards include compliance with Act 843 and the Cybersecurity Act, data protection impact assessments, proportionality tests, transparency registers of AI systems, independent oversight, inclusive non-digital channels, procurement clauses on data ownership and exit, and phased, problem-led pilots.

A justified conclusion is that targeted, well-governed applications can address specific urban challenges, but smart technology cannot substitute for urban planning, drainage investment and institutional capacity.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('3c3b2886-3be5-5af1-ae58-a4724c0b5a03', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'csit-621/future-technologies/ft21', 'mcq', 'understand', 'easy', 'Explain what a cyber-physical system is', 'Which description best fits a cyber-physical system?', null, null, '[{"id":"a","text":"A standalone spreadsheet used to record production"},{"id":"b","text":"A system in which physical processes are monitored and controlled by networked computation in a feedback loop"},{"id":"c","text":"A purely virtual game environment"},{"id":"d","text":"A paper-based quality checklist"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('3c3b2886-3be5-5af1-ae58-a4724c0b5a03', '{"option":"b"}'::jsonb, 'A cyber-physical system closes the loop between physical processes and digital analysis, using sensors, networks, software and actuators. Spreadsheets and paper checklists have no automatic feedback to the process, and a virtual game has no physical process.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('c0e4c752-67aa-5783-8c0c-8813d83c7bdc', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'csit-621/future-technologies/ft22', 'true_false', 'understand', 'easy', 'Recognise the origin and nature of the term Industry 4.0', 'True or false: The term Industrie 4.0 originated in a German strategic initiative in the early 2010s and is a policy and concept label rather than a precisely measurable event.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('c0e4c752-67aa-5783-8c0c-8813d83c7bdc', '{"value":true}'::jsonb, 'The term was introduced in Germany around 2011 and developed in working group recommendations published in 2013. The numbering of revolutions is a convenient simplification, and there is debate over whether the current period is a distinct revolution.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('68db188d-5153-5f94-94c4-e183cb465811', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'csit-621/future-technologies/ft23', 'scenario', 'apply', 'medium', 'Apply the digitise-and-stabilise-first principle', 'What is the most sensible first step?', 'A fictional Ghanaian bakery chain wants to buy an advanced "smart production" platform. Its recipes and
batch sizes vary by baker, production records are handwritten, and ovens frequently stop because of power
interruptions.', null, '[{"id":"a","text":"Buy the full platform immediately to leapfrog competitors"},{"id":"b","text":"Standardise and digitise basic production records, address power resilience, and pilot a narrow use case"},{"id":"c","text":"Install predictive maintenance across all ovens before collecting any data"},{"id":"d","text":"Cancel any digital work because Industry 4.0 is hype"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('68db188d-5153-5f94-94c4-e183cb465811', '{"option":"b"}'::jsonb, 'Maturity thinking says to stabilise and digitise before automating or optimising. Reliable records and power are prerequisites for useful data, and a narrow pilot tests value. Buying everything first or deploying prediction without data wastes money, while rejecting all digitisation ignores genuine, low-cost benefits.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('a3282836-24af-515c-89b4-603de9f71964', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'csit-621/future-technologies/ft24', 'matching', 'understand', 'medium', 'Match Industry 4.0 concepts to their definitions', 'Match each concept to its description.', null, null, '{"left":[{"id":"l1","text":"Digital twin"},{"id":"l2","text":"Interoperability"},{"id":"l3","text":"Predictive maintenance"},{"id":"l4","text":"Operational technology"}],"right":[{"id":"r4","text":"Hardware and software that monitors or controls physical equipment"},{"id":"r2","text":"Ability of different systems to exchange and use information consistently"},{"id":"r3","text":"Using data and models to anticipate equipment failure"},{"id":"r1","text":"Up-to-date digital representation of a physical asset or process used for monitoring and simulation"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('a3282836-24af-515c-89b4-603de9f71964', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'These terms recur in smart manufacturing discussions. Distinguishing OT from IT is important for security, because OT failures can have physical consequences.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('64aa6975-d6c7-57ee-95f3-5c79852e90b1', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'csit-621/future-technologies/ft25', 'mcq', 'analyse', 'medium', 'Analyse the risk created by connecting operational equipment', 'Why does connecting operational technology to corporate networks and the internet raise particular security concerns?', null, null, '[{"id":"a","text":"It reduces the number of systems that can be attacked"},{"id":"b","text":"It widens the attack surface and an attack can have physical consequences, while OT components are often hard to patch"},{"id":"c","text":"It makes patching unnecessary"},{"id":"d","text":"It removes the need for access control"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('64aa6975-d6c7-57ee-95f3-5c79852e90b1', '{"option":"b"}'::jsonb, 'Connectivity exposes equipment that was previously isolated, and OT environments often use long-lived components with limited patching options. Compromise can damage equipment or endanger people, not just expose data. The other options reverse the actual effect.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('d83682e9-bb42-5e11-bb23-3ad167f4f86b', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'csit-621/future-technologies/ft26', 'short_answer', 'recall', 'easy', 'Recall the name of an industrial interoperability standard', 'Which widely used industrial communication standard, abbreviated with the letters OPC, supports secure platform-independent exchange of machine data?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('d83682e9-bb42-5e11-bb23-3ad167f4f86b', '{"answers":["OPC UA","OPC Unified Architecture"]}'::jsonb, 'OPC UA is a standard for secure, platform-independent machine and process data exchange. Standards like it reduce vendor lock-in and support integration between equipment and enterprise systems.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('5eed0c67-5697-59f1-a314-ba8533fbeaf8', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'csit-621/future-technologies/ft27', 'mcq', 'evaluate', 'hard', 'Evaluate claims made about flagship Industry 4.0 plants', 'A vendor cites a flagship factory''s reported productivity gains to promise similar results to your firm. What is the most appropriate response?', null, null, '[{"id":"a","text":"Accept the claim because it comes from a respected company"},{"id":"b","text":"Treat the claim as a claim, and examine whether your products, scale, skills, infrastructure and baseline resemble the flagship''s and what independent evidence exists"},{"id":"c","text":"Ignore all digital technologies"},{"id":"d","text":"Assume results scale automatically to any firm"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('5eed0c67-5697-59f1-a314-ba8533fbeaf8', '{"option":"b"}'::jsonb, 'Flagship results often come from the promoting company and from favourable conditions such as stable, high-volume processes and long investment in skills. Critical evaluation checks transferability and evidence. Blind acceptance and blanket rejection are both poor judgement.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('b8edc665-3ce1-577c-9941-319b23c27557', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '960d9a06-431c-5162-a6f3-d5e824eab7ac', 'How do automation, robotics and autonomy differ?', 'Automation is what is done (a task performed by technology); robotics is one physical means of doing it (sense-think-act machines); autonomy is how independently the system decides and acts within a defined domain.', 'supplementary', 'csit-621/future-technologies/422fb301209c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('08487b63-590a-5df1-b070-7c0471c6f0ac', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '960d9a06-431c-5162-a6f3-d5e824eab7ac', 'Give two strengths and two weaknesses of RPA.', 'Strengths, fast to deploy and works across legacy systems without changing them. Weaknesses, brittle when interfaces change and automates existing (possibly broken) processes; bots also need governance of credentials and ownership.', 'supplementary', 'csit-621/future-technologies/03ee846210cd', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9bb10c4a-3845-56ac-981d-98eca7c3f148', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '960d9a06-431c-5162-a6f3-d5e824eab7ac', 'Where is the critical boundary in SAE J3016 and why?', 'Between levels 2 and 3. At levels 0-2 the human is driving and must supervise; at levels 3-5 the automated system drives when engaged, with level 3 still needing a human ready to take over on request.', 'supplementary', 'csit-621/future-technologies/f60d7444d5ef', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('1f2d14c2-9214-5162-8622-5e3ffc5bfd88', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '960d9a06-431c-5162-a6f3-d5e824eab7ac', 'What does the Parasuraman, Sheridan and Wickens model add to automation decisions?', 'It separates four functions (information acquisition, information analysis, decision selection and action implementation) each of which can be automated to a different degree, helping decide where human judgement should remain.', 'supplementary', 'csit-621/future-technologies/e729db24e80c', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8da711e3-671f-512a-bf7f-18fd8ba17991', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '960d9a06-431c-5162-a6f3-d5e824eab7ac', 'Why is the Zipline drone service in Ghana a useful example of autonomous systems?', 'It shows autonomy working within a defined operating domain (planned routes and coordinated airspace) to solve a real logistics problem for health facilities, through a partnership with the Government of Ghana.', 'supplementary', 'csit-621/future-technologies/0a1655c247e4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('06ac2d43-2de9-5bde-ba5c-0fe204c0b5f2', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '960d9a06-431c-5162-a6f3-d5e824eab7ac', 'What is automation complacency and how should designers respond?', 'Supervisors of reliable automation monitor less carefully over time and react slowly. Designers should not rely on humans as the only safety backstop, and should use monitoring, clear handovers and limited operating domains.', 'supplementary', 'csit-621/future-technologies/94cedb2aab11', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('7ae6b3f4-00d4-5180-b2c3-23ffa6373a14', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '41465dbf-12cb-5e5e-b0e4-4976814bb864', 'Name and explain the three 5G usage scenarios.', 'eMBB, high data rates and capacity; URLLC, very low latency and very high reliability for control applications; mMTC, very large numbers of low-power, low-data devices.', 'supplementary', 'csit-621/future-technologies/a865d53e2935', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('e3a2dd8f-a79e-5e71-8182-20913068a706', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '41465dbf-12cb-5e5e-b0e4-4976814bb864', 'What is network slicing and what does it require?', 'Multiple isolated logical networks with different guaranteed performance on shared infrastructure. It requires a standalone 5G core and an operator able to sell and manage slices.', 'supplementary', 'csit-621/future-technologies/cde1014aedb4', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('dba7f966-df78-5647-bcee-cec86038e61b', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '41465dbf-12cb-5e5e-b0e4-4976814bb864', 'When does private 5G make more sense than Wi-Fi?', 'At large, often outdoor, mission-critical sites with many moving devices or heavy interference (ports, mines, factories) where reliability, mobility and control justify the cost, spectrum and skills required.', 'supplementary', 'csit-621/future-technologies/a794cbbec867', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9c4c8009-8760-55cb-86a8-79eb525950cd', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '41465dbf-12cb-5e5e-b0e4-4976814bb864', 'Why is 5G often described as having a "killer application" problem?', 'Consumers often see little extra value over good 4G, so operators struggle to earn returns; stronger cases tend to come from fixed wireless access and enterprise or industrial uses needing capabilities 4G lacks.', 'supplementary', 'csit-621/future-technologies/1ff6bd564ca2', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('6e183668-aa92-553a-86e3-1bb5d12ced7d', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '41465dbf-12cb-5e5e-b0e4-4976814bb864', 'What strands make up "future connectivity" beyond today''s 5G?', '5G-Advanced releases, 6G research under the ITU''s IMT-2030 framework, low Earth orbit satellite broadband, non-terrestrial networks integrated into mobile standards, and continued reliance on fibre and submarine cables.', 'supplementary', 'csit-621/future-technologies/f3c431235951', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('f5d92150-2f0a-5970-bd7d-056eb72dc625', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '6f670383-140d-5a51-9c15-75b9cb4d51eb', 'List the six layers of a smart city architecture.', 'Sensing, connectivity, data platform, analytics and AI, applications, and governance (which cuts across all the others).', 'supplementary', 'csit-621/future-technologies/a5887053b7c8', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('fb58f392-bd54-508a-ab95-c4136a2f3ad7', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '6f670383-140d-5a51-9c15-75b9cb4d51eb', 'Why is the urban data platform the strategic core of a smart city?', 'It integrates data from many systems through common standards and open APIs, enforces governance and privacy, publishes open data and lets the city avoid fragmented, vendor-locked pilots.', 'supplementary', 'csit-621/future-technologies/f2fc9a5b7ae1', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8e6b0f99-1f68-50a6-9783-01c44d640939', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '6f670383-140d-5a51-9c15-75b9cb4d51eb', 'Name four limitations of advanced AI relevant to public services in Ghana.', 'Hallucination, bias from unrepresentative training data, weaker performance in under-represented languages such as Twi, Ewe, Ga and Dagbani, and significant energy and computing demands; also difficulty of explanation.', 'supplementary', 'csit-621/future-technologies/10d5079b4449', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('2e53c891-d9f2-5fed-b79c-aa457dd77ffd', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '6f670383-140d-5a51-9c15-75b9cb4d51eb', 'What are the main privacy risks of smart cities?', 'Mass surveillance (e.g. facial recognition), function creep, re-identification of "anonymous" location data, security breaches of centralised data, exclusion of non-digital residents and vendor lock-in.', 'supplementary', 'csit-621/future-technologies/62caa3a9c9c6', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('c7436d9e-e26b-59cc-a68e-cad78d72f030', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', '6f670383-140d-5a51-9c15-75b9cb4d51eb', 'What is the central lesson of Sidewalk Toronto?', 'Data governance and public trust, who owns and controls data collected in public spaces, must be settled early; the controversy contributed to the project''s end when Sidewalk Labs withdrew in 2020.', 'supplementary', 'csit-621/future-technologies/aab5e175c87a', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('245a992f-60d7-5e26-823a-ca6ec3bad328', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'What is a cyber-physical system and what makes it different from older automation?', 'It closes a feedback loop of sensing, connectivity, analytics and actuation. Unlike fixed-programme automation it is networked and data-rich and can adapt, which also means failures or attacks can have physical effects.', 'supplementary', 'csit-621/future-technologies/9ca401ec37fd', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('ef45dff7-5dd9-5231-a7ba-60f119003197', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'Why is the "four industrial revolutions" narrative a simplification?', 'Change was gradual and uneven, and Industry 4.0 is a concept and policy label from a German initiative (c. 2011), not a measurable event; whether it is a new revolution is debated.', 'supplementary', 'csit-621/future-technologies/f9078e01f592', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('15a06a5c-1134-59ac-aea6-3642b6fc1c0f', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'Why does interoperability matter in smart business systems?', 'Equipment and software from many vendors must exchange data with consistent meaning; standards such as OPC UA, RAMI 4.0 and ISA-95 enable integration and reduce vendor lock-in.', 'supplementary', 'csit-621/future-technologies/e1631e1abac6', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('9636dc20-bc7c-5db1-9239-12da51f07966', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'What three layers does a smart business system need?', 'A data layer (reliable, governed collection), an analytics layer (insight from rules to machine learning) and an action layer (decisions and automation with human oversight).', 'supplementary', 'csit-621/future-technologies/6514ddf410c3', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a3ee8af2-3859-58fd-964d-c02874c11b29', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'ecc6f589-0b21-558b-adb5-ded5f3e79b55', 'd906842f-f518-537f-bb89-2cd0103091b5', 'What does "digitise and stabilise before you automate and optimise" mean?', 'Document and stabilise processes and capture reliable data first; automating a chaotic process only makes the chaos faster, so progress should climb a maturity ladder in measurable steps.', 'supplementary', 'csit-621/future-technologies/c5a060409c07', true)
