insert into public.course_modules (id, course_id, slug, title, description, sort_order, is_published) values ('5b3b4db5-3611-52d0-8ee3-a393924d5603', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'sustainable-technology', 'Sustainable Technology', 'Technology''s environmental footprint and its potential to reduce it.', 8, true)
