insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ae73dc44-4428-5605-adf5-a1f261949173', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'csit-621/sustainable-technology/st01', 'scenario', 'apply', 'medium', 'Calculate Power Usage Effectiveness', 'What is the facility''s PUE?', 'Illustrative scenario. A Kumasi data centre''s IT equipment draws an average of 250 kW. Total facility load, including cooling, UPS losses and lighting, averages 475 kW.', null, '[{"id":"a","text":"0.53"},{"id":"b","text":"1.53"},{"id":"c","text":"1.90"},{"id":"d","text":"2.25"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ae73dc44-4428-5605-adf5-a1f261949173', '{"option":"c"}'::jsonb, 'PUE = total facility energy / IT equipment energy = 475 / 250 = 1.9. The value 0.53 is the inverse (IT / total, known as DCiE), which is a common error. 1.53 and 2.25 do not follow from the data. A PUE of 1.9 means 0.9 kWh of overhead for every 1 kWh delivered to IT.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('8539f98b-b4c5-5db2-8af7-7421ee95cf65', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'csit-621/sustainable-technology/st02', 'true_false', 'analyse', 'hard', 'Analyse the limitations of PUE', 'Consolidating servers through virtualisation always improves (lowers) a data centre''s PUE.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('8539f98b-b4c5-5db2-8af7-7421ee95cf65', '{"value":false}'::jsonb, 'Consolidation reduces IT load, and if facility overhead does not fall proportionately, the ratio of total to IT energy can rise, worsening PUE even though total energy falls. This is why PUE should be reported alongside absolute energy, carbon and useful-work measures.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('43a5c21c-969d-5587-b842-9f7084e91a5d', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'csit-621/sustainable-technology/st03', 'short_answer', 'recall', 'easy', 'Recall the Ghanaian law governing e-waste', 'Ghana''s Hazardous and Electronic Waste Control and Management Act was passed in 2016. What is its Act number (for example, "Act 843")?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('43a5c21c-969d-5587-b842-9f7084e91a5d', '{"answers":["Act 917","917"]}'::jsonb, 'The Hazardous and Electronic Waste Control and Management Act, 2016 (Act 917) provides for the control and management of hazardous and electronic waste and introduced an advance eco-levy on imported electrical and electronic equipment.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('ef3c1d7e-289f-5ccd-b40d-a6b5ba555be3', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'csit-621/sustainable-technology/st04', 'mcq', 'evaluate', 'hard', 'Evaluate accounts of Agbogbloshie', 'Which statement gives the most accurate account of Agbogbloshie in Accra?', null, null, '[{"id":"a","text":"It was the world''s largest dump for e-waste shipped from Europe, with no local economic role"},{"id":"b","text":"It was a complex informal scrap recycling hub that processed much locally generated material and supported many livelihoods, while practices such as open cable burning caused serious environmental and health harm"},{"id":"c","text":"It was a modern, regulated recycling plant operated by multinational firms"},{"id":"d","text":"It was a myth invented by journalists, with no environmental problems"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('ef3c1d7e-289f-5ccd-b40d-a6b5ba555be3', '{"option":"b"}'::jsonb, 'Researchers have challenged the "world''s largest e-waste dump" label, pointing to local generation of much of the material and the site''s role as a scrap trading hub and source of livelihoods. Yet open burning of cables to recover copper produced hazardous smoke and contamination. It was not a regulated plant, and its harms were real, not invented. The scrapyard was demolished in 2021.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('b52b04b3-6b8a-5068-8716-4ba8bfe670b1', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'csit-621/sustainable-technology/st05', 'matching', 'understand', 'medium', 'Match green IT measures to the layer they address', 'Match each measure to the main problem it addresses.', null, null, '{"left":[{"id":"l1","text":"Virtualisation and consolidation"},{"id":"l2","text":"Hot-aisle/cold-aisle containment"},{"id":"l3","text":"Solar panels with battery storage"},{"id":"l4","text":"Extending laptop life through repair"},{"id":"l5","text":"Certified data sanitisation before disposal"}],"right":[{"id":"r5","text":"Data breaches from discarded storage devices"},{"id":"r2","text":"Mixing of hot exhaust and cold supply air"},{"id":"r1","text":"Low server utilisation wasting IT energy"},{"id":"r4","text":"Embodied emissions and e-waste from frequent replacement"},{"id":"r3","text":"Reliance on diesel generators during outages"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('b52b04b3-6b8a-5068-8716-4ba8bfe670b1', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4","l5":"r5"}}'::jsonb, 'Each measure targets a distinct source of waste or risk across the IT, facility, power, lifecycle and security dimensions. A good green IT plan combines them rather than relying on one.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('9eaef898-60c8-5073-a1b0-ed5401d9d0fd', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'csit-621/sustainable-technology/st06', 'scenario', 'apply', 'medium', 'Calculate annual energy savings from a PUE improvement', 'What is the approximate annual energy saving?', 'Illustrative scenario. A facility has a constant IT load of 100 kW and improves its PUE from 2.0 to 1.5 with no change in IT load.', null, '[{"id":"a","text":"50 kWh"},{"id":"b","text":"438,000 kWh"},{"id":"c","text":"876,000 kWh"},{"id":"d","text":"1,314,000 kWh"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('9eaef898-60c8-5073-a1b0-ed5401d9d0fd', '{"option":"b"}'::jsonb, 'Total load falls from 100 × 2.0 = 200 kW to 100 × 1.5 = 150 kW, a reduction of 50 kW. Annual saving = 50 × 8,760 hours = 438,000 kWh. 50 kWh forgets to annualise; 876,000 kWh is the IT energy itself; 1,314,000 kWh is the new total annual energy.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('24cb9af7-2faa-5601-99a0-a29c341310f0', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'csit-621/sustainable-technology/st07', 'mcq', 'understand', 'medium', 'Explain the lifecycle view of green computing', 'Why does Murugesan''s holistic approach to green IT include design, manufacturing and disposal as well as use?', null, null, '[{"id":"a","text":"Because electricity use by IT is negligible"},{"id":"b","text":"Because significant environmental impacts, such as embodied emissions and hazardous waste, occur outside the use phase"},{"id":"c","text":"Because only manufacturers are responsible for green IT"},{"id":"d","text":"Because disposal is the only phase that regulators control"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('24cb9af7-2faa-5601-99a0-a29c341310f0', '{"option":"b"}'::jsonb, 'Manufacturing devices and disposing of them carry major impacts, including embodied emissions and toxic substances, so a use-only focus misses much of the footprint. Electricity use is not negligible, responsibility is shared, and regulation addresses several phases.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('afbcbb72-53bd-5331-a59d-b27317f70a51', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'csit-621/sustainable-technology/st08', 'matching', 'apply', 'medium', 'Classify emissions into GHG Protocol scopes', 'Match each emission source of a Ghanaian bank to its GHG Protocol scope.', null, null, '{"left":[{"id":"l1","text":"Diesel burned in the bank''s own backup generators"},{"id":"l2","text":"Grid electricity consumed at head office"},{"id":"l3","text":"Cloud hosting services purchased from a provider"},{"id":"l4","text":"Manufacturing of laptops bought for staff"}],"right":[{"id":"r1","text":"Scope 1"},{"id":"r4","text":"Scope 3 (purchased goods)"},{"id":"r2","text":"Scope 2"},{"id":"r3","text":"Scope 3 (purchased services)"}]}'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('afbcbb72-53bd-5331-a59d-b27317f70a51', '{"pairs":{"l1":"r1","l2":"r2","l3":"r3","l4":"r4"}}'::jsonb, 'Scope 1 covers direct emissions from owned sources; scope 2 covers purchased electricity; scope 3 covers value-chain emissions such as purchased goods and services. Moving workloads to the cloud shifts their emissions from scope 2 to scope 3.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('0fc082c7-d137-5ad7-a0df-eccd7119dfd2', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'csit-621/sustainable-technology/st09', 'true_false', 'understand', 'medium', 'Explain the rebound effect', 'The rebound effect means that efficiency improvements can lead to increased consumption that offsets some or all of the expected savings.', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('0fc082c7-d137-5ad7-a0df-eccd7119dfd2', '{"value":true}'::jsonb, 'Efficiency lowers the cost of an activity, which can increase demand. Jevons observed that more efficient steam engines increased coal use. In digital services, cheaper computing can drive much higher total usage.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('1086167c-8fab-572f-8055-6fa0d1bc4090', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'csit-621/sustainable-technology/st10', 'mcq', 'analyse', 'hard', 'Analyse the environmental footprint of AI', 'Which statement about AI''s environmental impact is most accurate?', null, null, '[{"id":"a","text":"Only training matters; using a trained model has no meaningful energy cost"},{"id":"b","text":"Training is energy-intensive, but large-scale inference, hardware manufacture and water for cooling also contribute, and the carbon impact depends on location and electricity source"},{"id":"c","text":"AI always reduces net emissions because it optimises other systems"},{"id":"d","text":"AI''s footprint is identical wherever it runs"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('1086167c-8fab-572f-8055-6fa0d1bc4090', '{"option":"b"}'::jsonb, 'Inference is cheaper per request but occurs at enormous scale; accelerators have manufacturing impacts; cooling uses water; and grid carbon intensity varies by location and time. AI can enable savings elsewhere, but net reductions are not guaranteed.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('6820fa8a-9a7a-58be-8d44-c9d729df04ee', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'csit-621/sustainable-technology/st11', 'short_answer', 'recall', 'easy', 'Recall the term for misleading environmental claims', 'What term describes misleading claims that exaggerate the environmental benefits of a product or organisation?', null, null, null, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('6820fa8a-9a7a-58be-8d44-c9d729df04ee', '{"answers":["greenwashing"]}'::jsonb, 'Greenwashing includes vague labels, selective disclosure, ignoring scope 3 or lifecycle impacts, and unverified claims. Specific, lifecycle-based and independently verified claims reduce the risk.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('911f0ae6-4c85-5a77-b4dd-201b09646314', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'csit-621/sustainable-technology/st12', 'scenario', 'evaluate', 'hard', 'Evaluate a carbon claim relating to cloud migration', 'What is the best evaluation of this claim?', 'Illustrative scenario. A Ghanaian insurer moves all its servers to a public cloud and announces that its "IT emissions are now zero" because its electricity bill for servers has disappeared.', null, '[{"id":"a","text":"Correct, because the insurer no longer pays for server electricity"},{"id":"b","text":"Misleading, because the emissions have moved from scope 2 into scope 3 (purchased cloud services); they may be lower, but they are not zero"},{"id":"c","text":"Correct, because cloud providers do not emit greenhouse gases"},{"id":"d","text":"Misleading, because cloud emissions count as the insurer''s scope 1"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('911f0ae6-4c85-5a77-b4dd-201b09646314', '{"option":"b"}'::jsonb, 'The provider''s data centres still consume electricity; for the insurer these emissions fall in scope 3 as purchased services. They may be lower if the provider is more efficient or uses low-carbon power, but claiming zero is greenwashing. Cloud emissions are not the insurer''s scope 1, which covers only directly owned or controlled sources.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('e1edc8d4-911c-53ba-aa61-53371aeed99e', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'csit-621/sustainable-technology/st13', 'mcq', 'understand', 'medium', 'Explain the priority order of circular economy loops', 'In circular economy thinking for IT equipment, which option generally preserves the most value?', null, null, '[{"id":"a","text":"Shredding devices to recover metals"},{"id":"b","text":"Extending device life through repair and maintenance"},{"id":"c","text":"Landfilling devices safely"},{"id":"d","text":"Incinerating plastic casings for energy"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('e1edc8d4-911c-53ba-aa61-53371aeed99e', '{"option":"b"}'::jsonb, 'Inner loops such as maintenance and repair preserve the product''s function and embodied energy; reuse and refurbishment come next; recycling is the last loop. Landfill and incineration lose materials and can cause pollution.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('bb05a0f4-bd8b-5098-8e93-d92de9800da9', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'csit-621/sustainable-technology/st14', 'mcq', 'understand', 'medium', 'Explain the Porter hypothesis', 'What does the Porter hypothesis (Porter and van der Linde, 1995) propose?', null, null, '[{"id":"a","text":"Environmental regulation always reduces competitiveness"},{"id":"b","text":"Well-designed environmental regulation can stimulate innovation that offsets compliance costs and improves competitiveness"},{"id":"c","text":"Firms should ignore environmental issues to maximise profit"},{"id":"d","text":"Only governments can innovate for sustainability"}]'::jsonb, 1, '{}'::text[], '[]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('bb05a0f4-bd8b-5098-8e93-d92de9800da9', '{"option":"b"}'::jsonb, 'Porter and van der Linde argued that pollution often signals wasted resources, so regulation that pushes firms to innovate can improve efficiency and competitiveness. The hypothesis is contested and not guaranteed, but it rejects the idea that environmental performance and profit are always in conflict.', null)
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('41376996-d820-5f5a-9095-b1657150cc69', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', null, 'csit-621/sustainable-technology/st15', 'case_analysis', 'evaluate', 'hard', 'Evaluate a green IT and sustainable innovation plan for a Ghanaian organisation', 'Evaluate the organisation''s environmental position and recommend a costed, prioritised sustainability plan, including a PUE calculation, a scope 1-3 analysis and an assessment of its AI plans.', null, 'Illustrative scenario. Oda River Bank is a fictional Ghanaian bank with an on-premises data centre in Accra. Over the last year the IT load averaged 200 kW and the total facility load averaged 400 kW. A diesel generator runs frequently during supply interruptions. The bank replaces laptops every three years and sells old devices to informal collectors without wiping them. It plans to deploy a generative AI customer-service assistant hosted by a cloud provider and to announce that it is "going green". Assume, for illustration only, an electricity cost of GHS 2.00 per kWh.', null, 20, array['Calculate current PUE and the annual saving from improving to PUE 1.6', 'Classify the bank''s emissions into scopes 1, 2 and 3', 'Assess e-waste and data-security practices against Act 917 and good practice', 'Evaluate the AI assistant''s direct and enabling effects', 'Recommend a prioritised plan and a credible, non-greenwashing communication approach']::text[], '[{"criterion":"PUE calculation and interpretation","marks":5,"descriptor":"Correctly calculates PUE of 2.0, annual saving of 700,800 kWh and GHS 1,401,600 at the assumed tariff, and notes PUE limitations"},{"criterion":"Scope analysis","marks":4,"descriptor":"Correctly assigns generator (scope 1), grid electricity (scope 2), purchased devices and cloud AI (scope 3)"},{"criterion":"E-waste and lifecycle","marks":4,"descriptor":"Identifies data-breach and environmental risks of informal disposal; recommends sanitisation, licensed recycling, life extension and compliance with Act 917"},{"criterion":"AI evaluation","marks":4,"descriptor":"Balanced qualitative assessment of training and inference energy, provider choice, model size and enabling benefits"},{"criterion":"Plan and communication","marks":3,"descriptor":"Prioritised, measurable plan and specific, verified claims rather than vague \"going green\" messaging"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('41376996-d820-5f5a-9095-b1657150cc69', '{}'::jsonb, 'Examiners look for correct calculations with annualisation, accurate scope classification, linkage of e-waste to data security and Act 917, a balanced view of AI, and avoidance of greenwashing.', 'Current PUE = 400 / 200 = 2.0. At PUE 1.6 total load would be 200 × 1.6 = 320 kW, saving 80 kW. Annually that is 80 × 8,760 = 700,800 kWh, worth about GHS 1,401,600 at the assumed tariff. Measures include airflow containment, raising set points within guidance, efficient cooling and UPS, and consolidation; the answer should note that consolidation may raise PUE while reducing total energy, so absolute energy must also be reported.

Scope 1 covers generator diesel (and any owned vehicles and refrigerant leaks); scope 2 covers grid electricity; scope 3 includes manufacture of laptops and servers, the cloud-hosted AI service, business travel and disposal. Solar and battery storage would cut both scope 1 fuel use and costs.

Selling unwiped laptops to informal collectors risks a serious data breach and contributes to hazardous informal recycling. The bank should extend device life to four or five years, sanitise storage with certified methods, use licensed recyclers, and keep records consistent with Act 917.

The AI assistant adds scope 3 emissions from inference at scale and from the provider''s infrastructure. The bank should prefer an appropriately sized model, a provider with credible low-carbon commitments and transparent reporting, and measure enabling benefits such as fewer branch visits.

Priorities: metering and data security first, cooling and power improvements second, device lifecycle third, and AI with sustainability criteria in procurement. Communication should state measured reductions by scope and avoid "going green" slogans.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (id, course_id, module_id, lesson_id, external_ref, type, bloom, difficulty, objective, prompt, scenario, case_text, options, marks, answer_structure, rubric, source, is_published) values ('98af18e1-523b-540f-b9cb-eca8a4cb56fc', 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', null, 'csit-621/sustainable-technology/st16', 'essay', 'evaluate', 'hard', 'Evaluate whether digital technology is a net environmental benefit', '"Digital technology is part of the solution to environmental problems, not part of the problem." Critically evaluate this statement with reference to green computing, AI and e-waste.', null, null, null, 15, array['Introduce direct, enabling and systemic effects', 'Assess direct footprints including data centres, AI and devices', 'Assess enabling benefits with examples', 'Discuss rebound effects and e-waste, including the Ghanaian context', 'Conclude that net impact depends on design, governance and use']::text[], '[{"criterion":"Analytical framework","marks":4,"descriptor":"Uses direct, enabling and systemic effects to structure the argument"},{"criterion":"Evidence and examples","marks":5,"descriptor":"Accurate, appropriately hedged examples on data centres, AI, devices and enabling uses, including Ghana"},{"criterion":"Critical evaluation","marks":4,"descriptor":"Recognises rebound, greenwashing and e-waste harms; avoids one-sided claims"},{"criterion":"Conclusion","marks":2,"descriptor":"Justified, nuanced conclusion"}]'::jsonb, 'ai_practice', true)
  on conflict (id) do update set course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, external_ref = excluded.external_ref, type = excluded.type, bloom = excluded.bloom, difficulty = excluded.difficulty, objective = excluded.objective, prompt = excluded.prompt, scenario = excluded.scenario, case_text = excluded.case_text, options = excluded.options, marks = excluded.marks, answer_structure = excluded.answer_structure, rubric = excluded.rubric, source = excluded.source, is_published = excluded.is_published;
insert into public.question_keys (question_id, correct, explanation, model_answer) values ('98af18e1-523b-540f-b9cb-eca8a4cb56fc', '{}'::jsonb, 'Examiners reward essays that structure the argument with the three orders of effect, use accurate hedged evidence, address e-waste and rebound, and reach a nuanced conclusion.', 'A good essay rejects the binary framing. Digital technology has substantial direct impacts: data centres and networks consume growing amounts of electricity, AI training and especially large-scale inference add to demand, cooling uses water, and device manufacturing carries embodied emissions and mineral extraction. In Ghana, diesel generators for towers and data centres and informal e-waste recycling (illustrated, with care, by Agbogbloshie) show local dimensions of these harms.

Enabling effects are real: smart grids help integrate renewables, sensors reduce fertiliser and water use, logistics optimisation saves fuel, and digital services can replace some travel and paper. AI can improve forecasting and efficiency in energy systems.

Systemic effects complicate the picture. Rebound effects (Jevons paradox) mean cheaper digital services can drive more consumption, and some "enabling" claims are greenwashing when they ignore lifecycle or scope 3 emissions.

The conclusion should be that technology is both part of the problem and part of the solution; its net effect depends on efficient design, low-carbon power, circular lifecycle management, credible carbon accounting and choices about what technology is used for.')
  on conflict (question_id) do update set correct = excluded.correct, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bd217bf6-f5a7-56c8-ac36-9e4a6120d8cb', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'Define PUE and state its ideal value.', 'PUE = total facility energy ÷ IT equipment energy. The theoretical ideal is 1.0 (no overhead); a PUE of 2.0 means one unit of overhead for every unit delivered to IT.', 'supplementary', 'csit-621/sustainable-technology/1b338bf716c8', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('a05f78d3-3fbb-58c5-a176-ea7b1df03fe3', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'What does PUE fail to measure?', 'Whether IT equipment does useful work, the carbon intensity of the electricity and water consumption. Consolidation can cut total energy yet raise PUE, so report absolute energy and carbon too (and companion metrics such as CUE and WUE).', 'supplementary', 'csit-621/sustainable-technology/a467eb291f1b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('4548ebb9-f423-5c1e-87c0-e5afc777cc09', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'How do you convert an average power load into annual energy?', 'Multiply average kW by 8,760 hours per year. For example, 400 kW × 8,760 = 3,504,000 kWh.', 'supplementary', 'csit-621/sustainable-technology/7311bfd3737b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('d7f1558a-02f9-567c-a3d3-01631bd40893', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'What are Murugesan''s four areas of green IT?', 'Green use, green disposal, green design and green manufacturing, a lifecycle view rather than a focus on electricity alone.', 'supplementary', 'csit-621/sustainable-technology/29b451203684', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('7e082d1f-a839-53af-9090-ad8d31921448', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'Why are efficiency measures especially valuable for Ghanaian data centres?', 'High electricity tariffs, supply interruptions that drive diesel generator use, and a hot, humid climate that raises cooling loads and limits free cooling.', 'supplementary', 'csit-621/sustainable-technology/429de7e080eb', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('45a1ead1-6d21-5af7-8020-9daa6229676b', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', '968a94fa-ddca-5ead-8cf2-728efbb32192', 'How should Agbogbloshie be described accurately?', 'As a complex informal scrap recycling hub in Accra that processed much locally generated material and supported many livelihoods, where open cable burning caused serious harm; often mislabelled the "world''s largest e-waste dump"; the scrapyard was demolished in 2021.', 'supplementary', 'csit-621/sustainable-technology/4178c2aa005b', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('fd30c697-f9b9-56a2-91a0-eea5b7502139', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'Distinguish direct, enabling and systemic environmental effects of technology.', 'Direct, the technology''s own footprint; enabling, changes it causes elsewhere (e.g. fuel saved by route optimisation); systemic, long-run behavioural and market changes, including rebound effects.', 'supplementary', 'csit-621/sustainable-technology/f4c2108d394f', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('aef800c0-24c4-56d0-adbc-40bc87c3cdcc', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'Define scopes 1, 2 and 3 under the GHG Protocol.', 'Scope 1, direct emissions from owned or controlled sources; scope 2, purchased electricity, heat, steam or cooling; scope 3, all other value-chain emissions, upstream and downstream.', 'supplementary', 'csit-621/sustainable-technology/96d00cceeaf8', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('fd4eab69-e31e-5a98-bd3e-8bcadaab13c2', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'What happens to emissions, in scope terms, when a firm moves servers to the cloud?', 'They shift from scope 2 (its own purchased electricity) to scope 3 (purchased services). They may fall if the provider is more efficient or cleaner, but they do not disappear.', 'supplementary', 'csit-621/sustainable-technology/508dc8fa813d', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('15450bd9-55b7-5191-95bf-c783952a3bfd', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'Summarise AI''s environmental footprint qualitatively.', 'Energy for training and, in aggregate, for large-scale inference; manufacturing of accelerators; water for cooling; impact varies with grid carbon intensity. Mitigate with efficient or smaller models, clean power and high utilisation.', 'supplementary', 'csit-621/sustainable-technology/5932018674b0', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('bbf7ea2d-3d5b-5c51-a30c-987d9689c902', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'What is the Jevons paradox?', 'The observation that efficiency improvements can increase total resource consumption because lower costs stimulate more use, a classic rebound effect.', 'supplementary', 'csit-621/sustainable-technology/48425c277ff9', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('8524632e-8329-5782-95a5-436191a09965', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', '5b3b4db5-3611-52d0-8ee3-a393924d5603', 'fef7b8bc-7a65-58e9-a198-12a44727d39a', 'Why is Fairphone a good example of sustainable innovation?', 'It designs modular, repairable phones with long support and fairer sourcing, tackling embodied emissions and e-waste through product and business model design.', 'supplementary', 'csit-621/sustainable-technology/3592e1cf4689', true)
  on conflict (id) do update set user_id = excluded.user_id, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id, front = excluded.front, back = excluded.back, source = excluded.source, external_ref = excluded.external_ref, is_published = excluded.is_published;
