insert into public.flashcards (id, user_id, course_id, module_id, lesson_id, front, back, source, external_ref, is_published) values ('43ee02bf-aac7-5501-8f6f-8ef9fb89c7ab', null, 'efc99e8b-9466-5435-a078-ba0143f3c2ea', 'f94ba37a-0108-5091-97ac-e26bb26cc689', '8333f7f3-38b6-513d-813a-33cfd3e33c87', 'What decisions can be made at a Stage-Gate gate?', 'Go, kill, hold or recycle, made by cross-functional gatekeepers reviewing deliverables against criteria such as fit, feasibility, return and risk.', 'supplementary', 'csit-621/business-adoption/41852ea8a069', true)
